//! Canonical `InternPool` (`TypeArena`), Constrained Type Groups & Bidirectional Type Checker
//!
//! Implements Frontend Semantics through Phase 7.6 (`PLAN.md` Sections 2.2–2.3 & Phase 7.6,
//! `DR-02`, `DR-04`, `DR-05`, `DR-07`, `DR-20`, `DR-21`, and `DR-22` `ADR-22A`–`ADR-22F` / `SE-09`–`SE-23`):
//! - 14-byte zero-padding SoA `TypeNode` (`TypeTag`, `TypeFlags`, `ParamMode`) and `InternPool`
//!   (`TypeArena`) pre-populating static `TypeId` slots `0..63` (19 sized primitives `0..18`, sentinels
//!   `19..21`, unsized `opaque` `22`, 12 Constrained Type Groups `32..44`, and `45..50` `DR-22` built-ins),
//! - Inline & named Constrained Type Groups (`[Data: str | &[u8]]`), `distinct` newtypes, range refinements,
//!   exact `bit_field` & backed `enum` layouts, `#soa` projections, `T!E` unified `Result`, and target layouts,
//! - Spine-local Dunfield–Krishnaswami bidirectional type checking, MVS call-site `own` / `&out` enforcement,
//!   typed `@cfg(expr)` gating, `FmtSpec` / `FmtArgs` dual-mode interpolation, 3-tier closures, `task_group`,
//!   `subscript` / `yield`, `@constructor` / `@builder`, labeled `fsm: match`, and `BodySemanticSideTables`.

const std = @import("std");
const mem_foundation = @import("mem_foundation.zig");
const syntax_arenas = @import("syntax_arenas.zig");
const lexer = @import("lexer.zig");
const symbol_resolver = @import("symbol_resolver.zig");
const parser = @import("parser.zig");
const diagnostic = @import("diag/diagnostic.zig");
const query_db = @import("query_db.zig");
const codegen_abi = @import("codegen_abi.zig");

/// Re-exported canonical 32-bit `TypeId` handle (`0..63` static, `>= 64` dynamic).
pub const TypeId = mem_foundation.TypeId;

const FileId = mem_foundation.FileId;
const Span = mem_foundation.Span;
const SymbolId = mem_foundation.SymbolId;
const StringInterner = mem_foundation.StringInterner;
const TokenIndex = mem_foundation.TokenIndex;
const CstNodeIndex = mem_foundation.CstNodeIndex;
const NodeIndex = mem_foundation.NodeIndex;
const ExtraIndex = mem_foundation.ExtraIndex;
const ScopeId = mem_foundation.ScopeId;
const DefId = query_db.DefId;
const TokenKind = syntax_arenas.TokenKind;
const CstNodeKind = syntax_arenas.CstNodeKind;
const AstTag = syntax_arenas.AstTag;
const PackedOperand = mem_foundation.PackedOperand;
const TokenBuffer = syntax_arenas.TokenBuffer;
const LosslessCstArena = syntax_arenas.LosslessCstArena;
const AstArena = syntax_arenas.AstArena;
const Namespace = symbol_resolver.Namespace;
const NamespaceMask = symbol_resolver.NamespaceMask;
const SymbolIndex = symbol_resolver.SymbolIndex;
const SymbolKind = symbol_resolver.SymbolKind;
const SymbolRecord = symbol_resolver.SymbolRecord;
const SymbolTable = symbol_resolver.SymbolTable;
const FnParamSpec = symbol_resolver.FnParamSpec;
const DiagnosticSink = diagnostic.DiagnosticSink;
const DiagnosticCode = diagnostic.DiagnosticCode;
const Severity = diagnostic.Severity;
const LabeledSpan = diagnostic.LabeledSpan;
const TextEdit = diagnostic.TextEdit;
const SuggestedFix = diagnostic.SuggestedFix;

// ---------------------------------------- TYPES ----------------------------------------

// --------- Constrained Type Group Bitmasks (`DR-04`) ----------

/// 32-bit bitmask of primitive `TypeId`s (`0..18`) for $O(1)$ Constrained Type Group checks (`DR-04` Section 1.2).
pub const TypeGroupMask = struct {
    /// `Signed = i8 | i16 | i32 | i64 | i128 | isize` (slots `5..10`).
    pub const SIGNED: u32 = TypeId.i8_ty.primitiveBit() |
        TypeId.i16_ty.primitiveBit() |
        TypeId.i32_ty.primitiveBit() |
        TypeId.i64_ty.primitiveBit() |
        TypeId.i128_ty.primitiveBit() |
        TypeId.isize_ty.primitiveBit();
    /// `Unsigned = u8 | u16 | u32 | u64 | u128 | usize` (slots `11..16`).
    pub const UNSIGNED: u32 = TypeId.u8_ty.primitiveBit() |
        TypeId.u16_ty.primitiveBit() |
        TypeId.u32_ty.primitiveBit() |
        TypeId.u64_ty.primitiveBit() |
        TypeId.u128_ty.primitiveBit() |
        TypeId.usize_ty.primitiveBit();
    /// `Integer = Signed | Unsigned` (slots `5..16`).
    pub const INTEGER: u32 = SIGNED | UNSIGNED;
    /// `Float = f32 | f64` (slots `17..18`).
    pub const FLOAT: u32 = TypeId.f32_ty.primitiveBit() | TypeId.f64_ty.primitiveBit();
    /// `Number = Integer | Float` (slots `5..18`).
    pub const NUMBER: u32 = INTEGER | FLOAT;
    /// `Numeric = Number` (alias bitmask for numeric algorithms, slots `5..18`).
    pub const NUMERIC: u32 = NUMBER;
    /// `Comparable = Number | bool | char | str` (slots `2..18`).
    pub const COMPARABLE: u32 = NUMBER |
        TypeId.bool_ty.primitiveBit() |
        TypeId.char_ty.primitiveBit() |
        TypeId.str_ty.primitiveBit();
    /// `Equatable = Comparable | unit` (slots `0` and `2..18`).
    pub const EQUATABLE: u32 = COMPARABLE | TypeId.unit_ty.primitiveBit();
    /// `Bytes = u8 | i8` (slots `5` and `11`).
    pub const BYTES: u32 = TypeId.i8_ty.primitiveBit() | TypeId.u8_ty.primitiveBit();
    /// `Scalar = Number | bool | char` (slots `2..3` and `5..18`).
    pub const SCALAR: u32 = NUMBER | TypeId.bool_ty.primitiveBit() | TypeId.char_ty.primitiveBit();
    /// `Copy = Scalar | str | never | unit` (all 19 primitives, slots `0..18`).
    pub const COPY: u32 = (1 << 19) - 1;
    /// `FromBytes = Integer | Float | unit` (excludes `bool`, `char`, `str`, `never`, `DR-20` `D-01`).
    pub const FROM_BYTES: u32 = INTEGER | FLOAT | TypeId.unit_ty.primitiveBit();
    /// `IntoBytes = FromBytes | bool | char` (excludes `str` and `never`, `DR-20` `D-01`).
    pub const INTO_BYTES: u32 = FROM_BYTES | TypeId.bool_ty.primitiveBit() | TypeId.char_ty.primitiveBit();

    /// Returns `true` if `prim_ty` (`0..18`) is a member of `group_mask` in $O(1)$ bit-test time.
    pub inline fn containsPrimitive(group_mask: u32, prim_ty: TypeId) bool {
        if (!prim_ty.isSizedPrimitive()) return false;
        return (group_mask & prim_ty.primitiveBit()) != 0;
    }

    /// Returns `true` if every primitive in `sub_mask` is also in `super_mask` (`(sub & ~super) == 0`).
    pub inline fn isSubsetOf(sub_mask: u32, super_mask: u32) bool {
        return (sub_mask & ~super_mask) == 0;
    }

    /// Returns the canonical 32-bit `TypeGroupMask` for a built-in group `TypeId` (`32..44`).
    pub inline fn forBuiltinGroup(group_id: TypeId) u32 {
        return switch (group_id) {
            .group_signed => SIGNED,
            .group_unsigned => UNSIGNED,
            .group_integer => INTEGER,
            .group_float => FLOAT,
            .group_number => NUMBER,
            ._retired_group_numeric => 0,
            .group_comparable => COMPARABLE,
            .group_equatable => EQUATABLE,
            .group_bytes => BYTES,
            .group_scalar => SCALAR,
            .group_copy => COPY,
            .group_from_bytes => FROM_BYTES,
            .group_into_bytes => INTO_BYTES,
            else => 0,
        };
    }
};

// -------------- 14-Byte SoA `TypeNode` (`DR-04`) --------------

/// Discriminant tag for `TypeNode` in `InternPool` (`DR-04` Section 2.2).
pub const TypeTag = enum(u8) {
    /// Built-in primitive type (`i8`..`unit`, or sentinels `untyped_int_ty`/`untyped_float_ty`/`err_ty`).
    primitive = 0,
    /// Built-in Constrained Type Group (`Signed`..`Copy`, `lhs = TypeGroupMask`).
    builtin_group = 1,
    /// User-defined Constrained Type Group (`type G = A | ~B`, `lhs = extra_start`, `rhs = def_id`).
    user_group = 2,
    /// Nominal `distinct` newtype (`type Id = distinct u64`, `lhs = base_ty`, `rhs = sym_idx`).
    distinct_ty = 3,
    /// Range or pattern refinement type (`T is low..=high`, `lhs = base_ty`, `rhs = extra_start`).
    refined_ty = 4,
    /// Underlying-type approximation (`~T`, `lhs = target_ty`).
    tilde_approx = 5,
    /// Nominal `struct` type (`lhs = def_id`, `rhs = sym_idx`).
    struct_ty = 6,
    /// Nominal `enum` type (`lhs = def_id`, `rhs = sym_idx`).
    enum_ty = 7,
    /// Nominal `union` type (`lhs = def_id`, `rhs = sym_idx`).
    union_ty = 8,
    /// Packed `bit_field` integer type (`lhs = backing_ty`, `rhs = sym_idx`).
    bit_field_ty = 9,
    /// Structural tuple type (`(T1, T2)`, `lhs = extra_start`, `rhs = arity`).
    tuple_ty = 10,
    /// Fixed-length array type (`[T; N]`, `lhs = elem_ty`, `rhs = len`).
    array_ty = 11,
    /// Dynamically sized slice type (`[T]`, `lhs = elem_ty`).
    slice_ty = 12,
    /// Structure-of-Arrays slice type (`#soa [T]`, `lhs = elem_ty`).
    soa_slice_ty = 13,
    /// Structure-of-Arrays fixed array type (`#soa [T; N]`, `lhs = elem_ty`, `rhs = len`).
    soa_array_ty = 14,
    /// First-class optional type (`T?`, `lhs = payload_ty`).
    optional_ty = 15,
    /// First-class error result type (`Result[T, E]`, `lhs = ok_ty`, `rhs = err_ty`).
    result_ty = 16,
    /// Shared borrowed reference (`&T` / `ref T`, `lhs = pointee_ty`).
    ref_ty = 17,
    /// Exclusive mutable reference (`&mut T` / `inout T`, `lhs = pointee_ty`).
    mut_ref_ty = 18,
    /// Raw pointer (`*T` or `*mut T`, `lhs = pointee_ty`, `rhs = is_mut`).
    raw_ptr_ty = 19,
    /// Function signature type (`fn(P…) -> R`, `lhs = extra_start`, `rhs = ret_ty`).
    fn_ty = 20,
    /// Anonymous closure type (`|P…| -> R`, `lhs = extra_start`, `rhs = ret_ty`).
    closure_ty = 21,
    /// Nominal `trait` interface (`lhs = def_id`, `rhs = sym_idx`).
    trait_ty = 22,
    /// Type-erased `dyn Trait` existential (`lhs = trait_ty`).
    dyn_trait_ty = 23,
    /// Generic type parameter (`[T: Bound]`, `lhs = bound_ty`, `rhs = name_sym`).
    type_param = 24,
    /// Bind-once Constrained Type Group variable (`x: Number, y: Number`, `lhs = group_ty`, `rhs = name_sym`).
    bind_once_group_var = 25,
    /// Bind-many independent `any Group` variable (`x: any Number`, `lhs = group_ty`, `rhs = ordinal`).
    bind_many_any_var = 26,
    /// Associated trait projection (`T.Item`, `lhs = base_ty`, `rhs = assoc_name_sym`).
    associated_ty = 27,
    /// Stackless coroutine future value (`Future[T]`, `lhs = output_ty`, `rhs = producer_id`).
    future_ty = 28,
};

/// 1-byte bit-packed semantic properties cached on every `TypeNode` (`DR-04` Section 2.2).
pub const TypeFlags = packed struct(u8) {
    /// `true` if values of this type are implicitly `Copy` (bitwise copyable).
    is_copy: bool = false,
    /// `true` if this type or any child contains `type_param`, `bind_once_group_var`, or `bind_many_any_var`.
    has_type_vars: bool = false,
    /// `true` if this type contains a borrowed reference (`&T` / `&mut T`).
    has_regions: bool = false,
    /// `true` if this type is or contains `TypeId.err_ty` (suppresses cascading diagnostics).
    has_error: bool = false,
    /// `true` if values of this type must not be silently ignored (`Result[T, E]` or `@must_use`).
    is_must_use: bool = false,
    /// `true` if this type has a statically known compile-time size.
    is_sized: bool = true,
    /// `true` if this type is or transitively contains a `@secret` value (`DR-20` `D-02`, Seam #1).
    is_secret: bool = false,
    /// `true` if this type has an automatic or custom destructor (`AutoDrop` / `Drop`).
    has_drop: bool = false,

    comptime {
        std.debug.assert(@sizeOf(TypeFlags) == 1);
    }
};

/// Three-tier value ownership classification (`DR-06` §1.2).
pub const OwnershipTier = enum(u8) {
    /// Tier 1: Bitwise copyable value (`Copy` primitives, slices, `&T`, `*T`, `fn`, `@local` closures).
    copy_tier = 0,
    /// Tier 2: Owned value with deterministic scope-exit `Drop`/`AutoDrop` (`Vec[T]`, `String`, `Map[K, V]`).
    auto_drop_tier = 1,
    /// Tier 3: Must-consume `@linear` resource (`Arena`, `File`, `Socket`, `PgTx`, `&mut T` linear loan).
    linear_tier = 2,

    /// Returns the stricter (higher-ranked) of two `OwnershipTier` values.
    pub inline fn maxTier(lhs_tier: OwnershipTier, rhs_tier: OwnershipTier) OwnershipTier {
        return if (@backingInt(lhs_tier) >= @backingInt(rhs_tier)) lhs_tier else rhs_tier;
    }
};

/// 1-byte bit-packed contract guarantees carried on `.fn_ty` and `.closure_ty` signatures (`DR-17`, `DR-22` `SE-22`).
pub const FnPtrContractMask = packed struct(u8) {
    /// `true` if the function type guarantees `@no_alloc` (`E0320` on violation).
    has_no_alloc: bool = false,
    /// `true` if the function type guarantees `@no_panic` (`E0321` on violation).
    has_no_panic: bool = false,
    /// `true` if the function type guarantees `@no_block` (`E0322` on violation).
    has_no_block: bool = false,
    /// `true` if the closure/function parameter activates an implicit `@builder` `&mut S` scope (`SE-22`).
    has_builder: bool = false,
    /// Reserved zero bits keeping `FnPtrContractMask` at `1` byte.
    _reserved: u4 = 0,

    /// Mask covering runtime effect-contract bits (`@no_alloc`, `@no_panic`, `@no_block`).
    pub const EFFECT_BITS_MASK: u8 = 0x07;

    comptime {
        std.debug.assert(@sizeOf(FnPtrContractMask) == 1);
    }

    /// Returns `true` if any contract or `@builder` bit is set on `self`.
    pub inline fn hasAny(self: FnPtrContractMask) bool {
        return @as(u8, @bitCast(self)) != 0;
    }

    /// Returns `true` if any runtime effect-contract bit (`@no_alloc` / `@no_panic` / `@no_block`) is set.
    pub inline fn hasEffectContracts(self: FnPtrContractMask) bool {
        return (@as(u8, @bitCast(self)) & EFFECT_BITS_MASK) != 0;
    }

    /// Returns `true` if `self` guarantees every runtime effect contract required by `required`.
    pub inline fn isSatisfying(self: FnPtrContractMask, required: FnPtrContractMask) bool {
        const self_bits: u8 = @as(u8, @bitCast(self)) & EFFECT_BITS_MASK;
        const req_bits: u8 = @as(u8, @bitCast(required)) & EFFECT_BITS_MASK;
        return (self_bits & req_bits) == req_bits;
    }
};

/// Parameter passing convention mode (`DR-02` Section 1.1 & `DR-04` Section 2.2).
pub const ParamMode = enum(u2) {
    /// Immutable borrow/value convention (`let`, default).
    let_mode = 0,
    /// Exclusive in-place mutation convention (`inout` / `&mut`).
    inout_mode = 1,
    /// Ownership consumption convention (`sink` / `own`).
    sink_mode = 2,
    /// Uninitialized out-parameter initialization convention (`set`).
    set_mode = 3,
};

/// 14-byte SoA type record (`1B tag + 1B flags + 4B hash + 4B lhs + 4B rhs = 14B` across SoA columns).
pub const TypeNode = struct {
    /// Structural category of the type (`1` byte).
    tag: TypeTag,
    /// Cached semantic flags (`1` byte).
    flags: TypeFlags = .{},
    /// Canonical 32-bit structural `Wyhash(0)` digest (`4` bytes).
    hash: u32 = 0,
    /// Primary payload (`TypeId`, `DefId`, `TypeGroupMask`, or `extra` start index, `4` bytes).
    lhs: u32 = 0,
    /// Secondary payload (`TypeId`, `SymbolIndex`, array length, or `extra` count, `4` bytes).
    rhs: u32 = 0,
};

/// Decoded inclusive 128-bit integer refinement bounds (`T is min_val..=max_val`).
pub const RefinementBounds = struct {
    /// Underlying primitive or nominal integer `TypeId`.
    base_ty: TypeId,
    /// Defining `SymbolIndex` of the refined type alias.
    sym_idx: SymbolIndex,
    /// Inclusive lower bound (`i128`).
    min_val: i128,
    /// Inclusive upper bound (`i128`).
    max_val: i128,
};

/// Decoded user-defined Constrained Type Group (`type G = A | ~B`).
pub const UserTypeGroupView = struct {
    /// Defining `SymbolIndex` of the type group.
    sym_idx: SymbolIndex,
    /// Bitmask of exact primitive types (`0..18`) included in the group.
    prim_mask: u32,
    /// Bitmask of `~Primitive` underlying approximations (`0..18`) included in the group.
    tilde_prim_mask: u32,
    /// Slice of exact non-primitive member `TypeId.toU32()` handles.
    exact_members: []const u32,
    /// Slice of `~Nominal` underlying member `TypeId.toU32()` handles.
    tilde_members: []const u32,
};

/// Decoded function or closure signature from `InternPool.extra`.
pub const FnSignatureView = struct {
    /// Return `TypeId`.
    ret_ty: TypeId,
    /// Slice of parameter `TypeId.toU32()` values (`arity` elements).
    param_types: []const u32,
    /// Slice of packed `ParamMode` values (`arity` elements).
    param_modes: []const u32,
    /// Contract guarantees packed in bits `16..23` of `extra[node.lhs]`.
    contracts: FnPtrContractMask = .{},
    /// Closure environment ownership tier packed in bits `24..25` of `extra[node.lhs]`.
    capture_tier: OwnershipTier = .copy_tier,
    /// Whether the closure environment captures a `@linear` obligation packed at bit `26`.
    has_linear_capture: bool = false,
    /// Whether the signature accepts trailing C variadic `...` arguments packed at bit `27` (`ADR-22F`).
    is_variadic: bool = false,
    /// Whether the signature uses `extern "C"` calling convention packed at bit `28` (`ADR-22F`).
    is_c_abi: bool = false,
    /// Whether the function or closure is `async` packed at bit `29` (`SE-20`).
    is_async: bool = false,
    /// Whether a `.closure_ty` captures any outer lexical binding (or `own` env) packed at bit `30` (`SE-19`).
    has_env_capture: bool = false,

    /// Returns the number of parameters in the signature.
    pub inline fn paramCount(self: FnSignatureView) usize {
        return self.param_types.len;
    }

    /// Returns the `TypeId` of parameter `idx`.
    pub inline fn getParamType(self: FnSignatureView, idx: usize) TypeId {
        if (idx >= self.param_types.len) return .err_ty;
        return TypeId.fromInt(self.param_types[idx]);
    }

    /// Returns the `ParamMode` of parameter `idx`.
    pub inline fn getParamMode(self: FnSignatureView, idx: usize) ParamMode {
        if (idx >= self.param_modes.len) return .let_mode;
        return @fromBackingInt(@intCast(@as(u2, @truncate(self.param_modes[idx]))));
    }
};

// ---------- `SubstitutionMap` (`DR-04` Section 2.4) -----------

/// Single binding pair mapping a type variable `TypeId` to its instantiated `TypeId`.
pub const SubstEntry = struct {
    /// Type variable (`bind_once_group_var`, `bind_many_any_var`, or `type_param`).
    var_ty: TypeId,
    /// Bound target `TypeId`.
    concrete_ty: TypeId,
    /// Source `Span` of the argument that established this binding (for `E0404` secondary labels).
    first_bind_span: Span = .{ .file_id = .none, .start_byte = 0, .end_byte = 0 },
};

/// Stack-first substitution table for call-site generic and Type Group instantiation (`DR-04` Section 2.4).
pub const SubstitutionMap = struct {
    /// Inline small-buffer storage covering `<= 16` type variables with zero heap allocations.
    inline_entries: [16]SubstEntry = undefined,
    /// Number of active entries in `inline_entries` (`0..16`).
    inline_len: u8 = 0,
    /// Overflow heap list used only when a signature exceeds 16 distinct type variables.
    overflow_entries: std.ArrayListUnmanaged(SubstEntry) = .empty,

    /// Releases any overflow storage back to `allocator`.
    pub fn deinit(self: *SubstitutionMap, allocator: std.mem.Allocator) void {
        self.overflow_entries.deinit(allocator);
        self.* = undefined;
    }

    /// Clears all bindings while retaining overflow capacity.
    pub fn clear(self: *SubstitutionMap) void {
        self.inline_len = 0;
        self.overflow_entries.clearRetainingCapacity();
    }

    /// Looks up the bound `SubstEntry` for `var_ty`, or `null` if unbound.
    pub fn getEntry(self: *const SubstitutionMap, var_ty: TypeId) ?SubstEntry {
        var i: usize = 0;
        while (i < self.inline_len) : (i += 1) {
            if (self.inline_entries[i].var_ty == var_ty) return self.inline_entries[i];
        }
        for (self.overflow_entries.items) |entry| {
            if (entry.var_ty == var_ty) return entry;
        }
        return null;
    }

    /// Looks up the bound `TypeId` for `var_ty`, or `null` if unbound.
    pub inline fn lookup(self: *const SubstitutionMap, var_ty: TypeId) ?TypeId {
        if (self.getEntry(var_ty)) |entry| return entry.concrete_ty;
        return null;
    }

    /// Inserts or updates the binding `var_ty -> concrete_ty` with `bind_span`.
    pub fn put(
        self: *SubstitutionMap,
        allocator: std.mem.Allocator,
        var_ty: TypeId,
        concrete_ty: TypeId,
        bind_span: Span,
    ) !void {
        var i: usize = 0;
        while (i < self.inline_len) : (i += 1) {
            if (self.inline_entries[i].var_ty == var_ty) {
                self.inline_entries[i].concrete_ty = concrete_ty;
                if (self.inline_entries[i].first_bind_span.file_id.isNone()) {
                    self.inline_entries[i].first_bind_span = bind_span;
                }
                return;
            }
        }
        for (self.overflow_entries.items) |*entry| {
            if (entry.var_ty == var_ty) {
                entry.concrete_ty = concrete_ty;
                if (entry.first_bind_span.file_id.isNone()) {
                    entry.first_bind_span = bind_span;
                }
                return;
            }
        }
        if (self.inline_len < self.inline_entries.len) {
            self.inline_entries[self.inline_len] = .{
                .var_ty = var_ty,
                .concrete_ty = concrete_ty,
                .first_bind_span = bind_span,
            };
            self.inline_len += 1;
            return;
        }
        try self.overflow_entries.append(allocator, .{
            .var_ty = var_ty,
            .concrete_ty = concrete_ty,
            .first_bind_span = bind_span,
        });
    }

    /// Zero-allocation 128-slot (`64` 2-way sets) stack memo for `SubstitutionMap.apply` over generic DAGs.
    const ApplyMemo = struct {
        /// Validity bitset for the 128 slots (`16` bytes zeroed at init).
        has_bits: [2]u64 = @splat(0),
        /// Exact `TypeId.toU32()` keys for populated slots.
        type_raws: [128]u32 = undefined,
        /// Exact recursion depths for populated slots.
        depths: [128]u16 = undefined,
        /// Substituted `TypeId` values for populated slots.
        vals: [128]TypeId = undefined,

        /// Returns `true` if slot `slot_idx` holds a valid entry.
        inline fn hasSlot(self: *const ApplyMemo, slot_idx: u7) bool {
            const word_idx: usize = slot_idx >> 6;
            const bit_pos: u6 = @truncate(slot_idx);
            return (self.has_bits[word_idx] & (@as(u64, 1) << bit_pos)) != 0;
        }

        /// Marks slot `slot_idx` valid.
        inline fn setSlot(self: *ApplyMemo, slot_idx: u7) void {
            const word_idx: usize = slot_idx >> 6;
            const bit_pos: u6 = @truncate(slot_idx);
            self.has_bits[word_idx] |= (@as(u64, 1) << bit_pos);
        }

        /// Computes the 2-way set base index (`0, 2, …, 126`) for `(type_raw, depth_u16)`.
        inline fn computeSetBase(type_raw: u32, depth_u16: u16) u7 {
            var mix: u32 = (type_raw *% 0x9E37_79B1) ^ (@as(u32, depth_u16) *% 0x85EB_CA6B);
            mix ^= mix >> 16;
            mix *%= 0x7FEB_352D;
            mix ^= mix >> 15;
            return @as(u7, @truncate(mix)) & 0x7E;
        }

        /// Looks up a cached substituted `TypeId` matching `(type_raw, depth)` (`null` on miss).
        inline fn lookup(self: *const ApplyMemo, type_raw: u32, depth: u32) ?TypeId {
            const depth_u16: u16 = @intCast(depth);
            const base_slot = computeSetBase(type_raw, depth_u16);
            if (self.hasSlot(base_slot) and
                self.type_raws[base_slot] == type_raw and
                self.depths[base_slot] == depth_u16)
            {
                return self.vals[base_slot];
            }
            const second_slot = base_slot | 1;
            if (self.hasSlot(second_slot) and
                self.type_raws[second_slot] == type_raw and
                self.depths[second_slot] == depth_u16)
            {
                return self.vals[second_slot];
            }
            return null;
        }

        /// Stores `result_ty` under `(type_raw, depth)` using `depth & 1` parity selection.
        inline fn store(self: *ApplyMemo, type_raw: u32, depth: u32, result_ty: TypeId) void {
            const depth_u16: u16 = @intCast(depth);
            const base_slot = computeSetBase(type_raw, depth_u16);
            const second_slot = base_slot | 1;
            const parity_way: u7 = @intCast(depth & 1);
            const parity_slot = base_slot | parity_way;
            const alt_slot = base_slot | (parity_way ^ 1);
            const slot_idx: u7 = if (self.hasSlot(base_slot) and
                self.type_raws[base_slot] == type_raw and
                self.depths[base_slot] == depth_u16)
                base_slot
            else if (self.hasSlot(second_slot) and
                self.type_raws[second_slot] == type_raw and
                self.depths[second_slot] == depth_u16)
                second_slot
            else if (!self.hasSlot(parity_slot))
                parity_slot
            else if (!self.hasSlot(alt_slot))
                alt_slot
            else
                parity_slot;
            self.type_raws[slot_idx] = type_raw;
            self.depths[slot_idx] = depth_u16;
            self.vals[slot_idx] = result_ty;
            self.setSlot(slot_idx);
        }
    };

    /// Recursively substitutes bound type variables inside `ty`, returning immediately in $O(1)$ if `!has_type_vars`.
    pub fn apply(self: *const SubstitutionMap, pool: *InternPool, ty: TypeId) !TypeId {
        if (ty.isPrimitiveOrSentinel() or ty.isBuiltinGroup()) return ty;
        if (!pool.getNode(ty).flags.has_type_vars) return ty;
        var memo: ApplyMemo = .{};
        return self.applyBounded(pool, ty, 0, &memo);
    }

    /// Depth-bounded helper (`MAX_TYPE_DEPTH`) for `apply`.
    fn applyBounded(
        self: *const SubstitutionMap,
        pool: *InternPool,
        ty: TypeId,
        depth: u32,
        memo: *ApplyMemo,
    ) anyerror!TypeId {
        if (depth >= MAX_TYPE_DEPTH) return .err_ty;
        if (ty.isPrimitiveOrSentinel() or ty.isBuiltinGroup()) return ty;
        const node = pool.getNode(ty);
        if (!node.flags.has_type_vars) return ty;
        if (memo.lookup(ty.toU32(), depth)) |cached_ty| return cached_ty;

        const result_ty: TypeId = switch (node.tag) {
            .primitive => if (node.rhs == TypeId.task_group_base_ty.toU32())
                try pool.internTaskGroup(
                    try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                )
            else if (node.rhs == TypeId.task_handle_base_ty.toU32())
                try pool.internTaskHandle(
                    try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                )
            else
                ty,
            .bind_once_group_var, .bind_many_any_var, .type_param => blk: {
                if (self.lookup(ty)) |bound| {
                    if (bound == .untyped_int_ty) break :blk defaultConcreteForGroup(TypeId.fromInt(node.lhs), true);
                    if (bound == .untyped_float_ty) break :blk defaultConcreteForGroup(TypeId.fromInt(node.lhs), false);
                    break :blk bound;
                }
                break :blk ty;
            },
            .optional_ty => try pool.internOptional(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
            ),
            .future_ty => try pool.internFuture(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                node.rhs,
            ),
            .result_ty => try pool.internResult(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                try self.applyBounded(pool, TypeId.fromInt(node.rhs), depth + 1, memo),
            ),
            .slice_ty => try pool.internSlice(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                false,
            ),
            .soa_slice_ty => try pool.internSlice(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                true,
            ),
            .array_ty, .soa_array_ty => blk: {
                const subst_elem = try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo);
                const is_soa = (node.tag == .soa_array_ty);
                if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0) {
                    const const_sym = SymbolId.fromInt(node.rhs & ~SYMBOLIC_ARRAY_LEN_FLAG);
                    const len_key = try pool.internSymbolicArray(.unit_ty, const_sym, false);
                    if (self.lookup(len_key)) |bound_len_ty| {
                        const bound_node = pool.getNode(bound_len_ty);
                        if (bound_node.tag == .array_ty and (bound_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0) {
                            break :blk try pool.internArray(subst_elem, bound_node.rhs, is_soa);
                        }
                    }
                    break :blk try pool.internSymbolicArray(subst_elem, const_sym, is_soa);
                }
                break :blk try pool.internArray(subst_elem, node.rhs, is_soa);
            },
            .ref_ty => try pool.internRef(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                false,
            ),
            .mut_ref_ty => if (node.rhs == 2)
                try pool.internOutRef(
                    try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                )
            else
                try pool.internRef(
                    try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                    true,
                ),
            .raw_ptr_ty => try pool.internRawPtr(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
                node.rhs != 0,
            ),
            .tilde_approx => try pool.internTildeApprox(
                try self.applyBounded(pool, TypeId.fromInt(node.lhs), depth + 1, memo),
            ),
            .tuple_ty => blk: {
                const arity: usize = node.rhs;
                if (arity == 0) break :blk .unit_ty;
                const elems = pool.extra.items[node.lhs .. node.lhs + arity];
                const subst_elems = try pool.allocator.alloc(TypeId, arity);
                defer pool.allocator.free(subst_elems);
                for (elems, 0..) |raw_elem, i| {
                    subst_elems[i] = try self.applyBounded(
                        pool,
                        TypeId.fromInt(raw_elem),
                        depth + 1,
                        memo,
                    );
                }
                break :blk try pool.internTuple(subst_elems);
            },
            .struct_ty, .enum_ty, .union_ty => blk: {
                const raw_args = pool.getGenericTypeArgs(ty);
                if (raw_args.len == 0) break :blk ty;
                const subst_args = try pool.allocator.alloc(TypeId, raw_args.len);
                defer pool.allocator.free(subst_args);
                for (raw_args, 0..) |raw_arg, i| {
                    subst_args[i] = try self.applyBounded(
                        pool,
                        TypeId.fromInt(raw_arg),
                        depth + 1,
                        memo,
                    );
                }
                break :blk try pool.internNominalInstantiation(
                    ty,
                    subst_args,
                    node.flags.is_copy,
                    node.flags.has_drop,
                );
            },
            .fn_ty, .closure_ty => blk: {
                const sig_view = pool.getFnSignatureView(ty) orelse break :blk ty;
                const arity = sig_view.paramCount();
                const subst_params = try pool.allocator.alloc(TypeId, arity);
                defer if (arity > 0) pool.allocator.free(subst_params);
                const subst_modes = try pool.allocator.alloc(ParamMode, arity);
                defer if (arity > 0) pool.allocator.free(subst_modes);
                for (0..arity) |i| {
                    subst_params[i] = try self.applyBounded(pool, sig_view.getParamType(i), depth + 1, memo);
                    subst_modes[i] = sig_view.getParamMode(i);
                }
                const subst_ret = try self.applyBounded(pool, sig_view.ret_ty, depth + 1, memo);
                if (node.tag == .closure_ty) {
                    break :blk try pool.internClosureSignatureExt(
                        subst_params,
                        subst_modes,
                        subst_ret,
                        sig_view.contracts,
                        sig_view.capture_tier,
                        sig_view.has_linear_capture,
                        sig_view.is_async,
                        sig_view.has_env_capture,
                    );
                }
                break :blk try pool.internFnSignatureExt(
                    node.tag,
                    subst_params,
                    subst_modes,
                    subst_ret,
                    node.flags.is_must_use,
                    sig_view.contracts,
                    sig_view.capture_tier,
                    sig_view.has_linear_capture,
                    sig_view.is_variadic,
                    sig_view.is_c_abi,
                    sig_view.is_async,
                );
            },
            else => ty,
        };
        memo.store(ty.toU32(), depth, result_ty);
        return result_ty;
    }
};

// --------- Target Layout & Body Side Tables (`DR-05`) ---------

/// Target pointer, cache-line, and SIMD alignment parameters shared across `TypeChecker`, `HIR`, `MirVm`, and `MIR`.
pub const TargetLayout = struct {
    /// Target pointer width in bytes (`8` on 64-bit hosts, `4` on `wasm32`).
    ptr_byte_size: u8 = 8,
    /// Base-2 logarithm of target pointer alignment (`3` -> 8-byte align, `2` -> 4-byte align).
    ptr_align_log2: u8 = 3,
    /// Base-2 logarithm of target cache-line size (`6` -> 64B, `7` -> 128B on `aarch64-macos`).
    cache_line_align_log2: u8 = 6,
    /// Base-2 logarithm of target baseline SIMD column alignment (`4` -> 16B, `5` -> 32B, `6` -> 64B).
    simd_align_log2: u8 = 4,

    /// Canonical 64-bit native target layout (`x86_64` / `aarch64`).
    pub const NATIVE_64: TargetLayout = .{ .ptr_byte_size = 8, .ptr_align_log2 = 3 };
    /// Canonical 64-bit Apple Silicon target layout (`aarch64-macos`, `128B` L2 cache line).
    pub const AARCH64_MACOS: TargetLayout = .{
        .ptr_byte_size = 8,
        .ptr_align_log2 = 3,
        .cache_line_align_log2 = 7,
        .simd_align_log2 = 4,
    };
    /// Canonical 32-bit WebAssembly target layout (`wasm32`).
    pub const WASM32: TargetLayout = .{ .ptr_byte_size = 4, .ptr_align_log2 = 2 };

    /// Returns the pointer alignment in bytes (`1 << ptr_align_log2`).
    pub inline fn ptrAlignBytes(self: TargetLayout) u32 {
        return @as(u32, 1) << @intCast(self.ptr_align_log2);
    }

    /// Returns the target cache-line alignment in bytes (`1 << cache_line_align_log2`).
    pub inline fn cacheLineAlignBytes(self: TargetLayout) u32 {
        return @as(u32, 1) << @intCast(self.cache_line_align_log2);
    }

    /// Returns the target SIMD column alignment in bytes (`1 << simd_align_log2`).
    pub inline fn simdAlignBytes(self: TargetLayout) u32 {
        return @as(u32, 1) << @intCast(self.simd_align_log2);
    }
};

/// Computed target-specific byte size and alignment of a `TypeId`.
pub const TypeLayout = struct {
    /// Total padded size of the type in bytes (`0` for ZSTs and unsized symbolic types).
    byte_size: u64,
    /// Required alignment in bytes (`>= 1`, always a power of two).
    align_bytes: u32,
    /// Base-2 logarithm of `align_bytes`.
    align_log2: u8,
    /// `true` when the type has a statically known concrete size.
    is_sized: bool = true,
};

/// Leaf scalar or non-null pointer niche classification (`DR-07`, `DR-09`).
pub const NicheKind = enum(u8) {
    /// No unused bit pattern exists inside this type.
    none = 0,
    /// Non-null pointer slot (`&T`, `&mut T`, `fn`, `[T]`, `#soa [T]`, `str`, `closure`) where `0` is invalid.
    zero_ptr = 1,
    /// Scalar integer slot (`bool`, `char`, `enum` tag, or positive `is` refinement) with unused value(s).
    high_scalar_range = 2,
};

/// Borrow-safe leaf niche location inside a concrete type.
pub const LeafNicheInfo = struct {
    /// Encoding kind of the niche slot.
    kind: NicheKind = .none,
    /// Byte offset of the niche scalar/pointer from the start of the enclosing type.
    byte_offset: u32 = 0,
    /// Byte width of the niche scalar/pointer (`1`, `2`, `4`, or `8`).
    scalar_bytes: u8 = 0,
    /// First invalid bit pattern (`0` for `.zero_ptr`, `2` for `bool`, `0x110000` for `char`, `V` for `enum`).
    invalid_first: u64 = 0,
    /// Number of contiguous invalid bit patterns starting at `invalid_first`.
    invalid_count: u64 = 0,
};

/// Canonical in-memory representation of `Option[T]`, `Result[T, E]`, and `enum` sums.
pub const SumMemoryReprKind = enum(u8) {
    /// Explicit integer tag at byte `0` followed by aligned payload union.
    explicit_tag = 0,
    /// Single ZST variant folded into payload's leaf scalar/pointer niche (`sizeof == sizeof(payload)`).
    niche_single = 1,
    /// `Result[T, never]` transparent single-variant representation (`sizeof == sizeof(T)`, `tag == 0`).
    transparent_ok = 2,
};

/// Complete resolved in-memory sum layout shared across `TypeChecker`, `MIR`, `MirOpt`, `MirVm`, and codegen.
pub const SumMemoryLayout = struct {
    /// Representation kind in memory.
    repr: SumMemoryReprKind = .explicit_tag,
    /// Total padded size of the sum in bytes.
    byte_size: u64 = 0,
    /// Required alignment in bytes (`1 << align_log2`).
    align_bytes: u32 = 1,
    /// Base-2 logarithm of `align_bytes`.
    align_log2: u8 = 0,
    /// `true` when all constituent variants have statically known sizes.
    is_sized: bool = true,
    /// Explicit tag byte width (`1`, `2`, `4`, or `8` when `repr == .explicit_tag`; `0` otherwise).
    tag_bytes: u8 = 1,
    /// Byte offset where non-ZST variant payloads start (`0` for `.niche_single` and `.transparent_ok`).
    payload_offset: u64 = 0,
    /// Discriminant ordinal represented by `niche.invalid_first` when `repr == .niche_single`.
    zst_discriminant: u32 = 0,
    /// Discriminant ordinal represented by non-niche payload bytes when `repr == .niche_single`.
    payload_discriminant: u32 = 1,
    /// Concrete `TypeId` of the non-ZST payload when `repr == .niche_single` or `.transparent_ok`.
    payload_ty: TypeId = .unit_ty,
    /// Leaf scalar/pointer niche descriptor when `repr == .niche_single`.
    niche: LeafNicheInfo = .{},
};

/// Computed `#soa [S; C]` column offset and alignment metadata.
pub const SoaColumnInfo = struct {
    /// Byte offset of column `field_ordinal` inside `#soa [S; C]`.
    byte_offset: u64,
    /// Column alignment `log2` (`@max(field_align_log2, target_layout.simd_align_log2)`).
    col_align_log2: u8,
    /// Resolved concrete `TypeId` of the struct field.
    field_ty: TypeId,
    /// Computed `TypeLayout` of `field_ty`.
    field_layout: TypeLayout,
};

/// Validated compile-time constant argument value inside an `@attribute_schema` instance.
pub const AttrArgValue = union(enum) {
    /// Boolean literal (`true` / `false`).
    bool_val: bool,
    /// Unicode scalar character literal.
    char_val: u21,
    /// Signed or unsigned 128-bit integer constant.
    int_val: i128,
    /// 64-bit IEEE-754 floating-point constant.
    float_val: f64,
    /// Interned UTF-8 string literal (`SymbolId`).
    str_val: SymbolId,
    /// Enum variant ordinal tag (`0..N-1`).
    enum_tag: u32,
    /// Omitted or `.None` optional value.
    none_opt: void,
};

/// Single validated field argument on an `@attribute_schema` attribute application.
pub const AttrFieldInit = struct {
    /// Interned schema field name (`SymbolId.none` when positional).
    field_name: SymbolId,
    /// Resolved field ordinal (`0..N-1`) inside the `@attribute_schema` struct.
    field_ordinal: u16,
    /// Evaluated compile-time constant argument value.
    value: AttrArgValue,
};

/// Validated user-defined `@attribute_schema` instance attached to a declaration, field, or variant.
pub const AttrInstance = struct {
    /// Schema struct `TypeId` (`struct_ty` annotated with `@attribute_schema`).
    schema_type_id: TypeId,
    /// Target `SymbolIndex` receiving the attribute (`struct_sym`, `field_sym`, `enum_variant_sym`, etc.).
    target_symbol: SymbolIndex,
    /// Enclosing top-level item `DefId` (`DefId.NONE` when module-scoped without a `DefId`).
    owner_def_id: DefId,
    /// Source span of the `@Schema(…)` attribute application.
    attr_span: Span,
    /// Owned slice of validated constant field initializers.
    fields: []AttrFieldInit,
};

/// Canonical field slots exposed on `Context` (`DR-08` §5.3, `DR-18` §2.1, `DR-20` `D-04`, `DR-21` `SE-08`).
pub const ContextFieldKind = enum(u8) {
    /// Dynamic general-purpose allocator capability handle (`allocator: Allocator`).
    allocator = 0,
    /// Dual-ping-pong scratch arena array (`scratch: [BumpArena; 2]`, `D-04`).
    scratch = 1,
    /// Per-context deterministic PRNG seed (`rng_seed: u64`).
    rng_seed = 2,
    /// Nullable lock-free crash-flight-recorder ring pointer (`trace_sink: (*mut u8)?`, `D-06B`, Seam #2).
    trace_sink = 3,
    /// Scoped temporary bump/arena allocator capability (`temp_allocator: Allocator`, `SE-08`).
    temp_allocator = 4,
    /// Structured logger capability handle (`logger: Logger`, `SE-08`).
    logger = 5,
    /// Structured diagnostic sink capability handle (`diagnostics: DiagSink`, `SE-08`).
    diagnostics = 6,
    /// Cooperative cancellation token capability (`cancel_token: CancelToken`, `SE-08`).
    cancel_token = 7,
    /// Pluggable async I/O & timer reactor vtable handle (`reactor: Reactor`, `DR-08` §5.3, `DR-18` §2.1).
    reactor = 8,
    /// Pluggable async reactor / deterministic simulation state handle (`reactor_ctx: ReactorCtx`, `DR-18` §2.1).
    reactor_ctx = 9,

    /// Returns `true` when `with context.<slot> = val { … }` is permitted for `self` (`DR-08`, `DR-21` `SE-08`).
    pub inline fn isWithOverridable(self: ContextFieldKind) bool {
        return switch (self) {
            .allocator,
            .temp_allocator,
            .logger,
            .diagnostics,
            .cancel_token,
            .reactor,
            .reactor_ctx,
            => true,
            .scratch,
            .rng_seed,
            .trace_sink,
            => false,
        };
    }
};

/// Canonical `Context` seam layout metadata (`DR-08` §5.3, `DR-18` §2.1, `DR-20` `D-04`, `DR-21` `SE-08`).
pub const ContextFieldLayout = struct {
    /// Canonical field name on `Context`.
    name: []const u8,
    /// Logical `ContextFieldKind` slot.
    kind: ContextFieldKind,
    /// Zero-based canonical slot ordinal.
    slot_ordinal: u8,

    /// Canonical 80-byte (`10 * 8`) 10-slot `Context` size on 64-bit targets (`DR-08` §5.3, `SE-08`).
    pub const BYTE_SIZE_64: u32 = 80;
    /// Canonical 40-byte (`10 * 4`) 10-slot `Context` size on 32-bit `wasm32` targets (`DR-08` §5.3, `SE-08`).
    pub const BYTE_SIZE_32: u32 = 40;

    /// Returns the 10-slot `Context` byte size (`10 * ptr_byte_size`) for `ptr_byte_size` (`4` or `8`).
    pub inline fn byteSizeForPtrWidth(ptr_byte_size: u8) u32 {
        return @as(u32, CANONICAL_FIELDS.len) * @as(u32, ptr_byte_size);
    }

    /// Canonical 10-slot `Context` seam layout table (`0..3` `DR-20` + `4..7` `SE-08` + `8..9` `DR-08` reactor).
    pub const CANONICAL_FIELDS = [10]ContextFieldLayout{
        .{ .name = "allocator", .kind = .allocator, .slot_ordinal = 0 },
        .{ .name = "scratch", .kind = .scratch, .slot_ordinal = 1 },
        .{ .name = "rng_seed", .kind = .rng_seed, .slot_ordinal = 2 },
        .{ .name = "trace_sink", .kind = .trace_sink, .slot_ordinal = 3 },
        .{ .name = "temp_allocator", .kind = .temp_allocator, .slot_ordinal = 4 },
        .{ .name = "logger", .kind = .logger, .slot_ordinal = 5 },
        .{ .name = "diagnostics", .kind = .diagnostics, .slot_ordinal = 6 },
        .{ .name = "cancel_token", .kind = .cancel_token, .slot_ordinal = 7 },
        .{ .name = "reactor", .kind = .reactor, .slot_ordinal = 8 },
        .{ .name = "reactor_ctx", .kind = .reactor_ctx, .slot_ordinal = 9 },
    };

    /// Resolves `field_name` against `CANONICAL_FIELDS`, returning `null` if unknown.
    pub fn fromFieldName(field_name: []const u8) ?ContextFieldLayout {
        return CONTEXT_FIELD_LAYOUT_MAP.get(field_name);
    }

    /// Returns the underlying `Context` `.struct_ty` when `raw_ty` is `&Context` (`null` otherwise).
    pub fn resolveRefPointee(
        pool: *const InternPool,
        sym_table: *const SymbolTable,
        raw_ty: TypeId,
    ) ?TypeId {
        const ty = pool.unwrapUnderlyingType(raw_ty);
        if (ty.isPrimitiveOrSentinel()) return null;
        const node = pool.getNode(ty);
        if (node.tag != .ref_ty) return null;
        const pointee_ty = pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
        if (pointee_ty.isPrimitiveOrSentinel()) return null;
        const pointee_node = pool.getNode(pointee_ty);
        if (pointee_node.tag != .struct_ty) return null;
        const sym_idx = SymbolIndex.fromInt(pointee_node.rhs);
        if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) return null;
        if (!std.mem.eql(u8, sym_table.getSymbol(sym_idx).name_text, "Context")) return null;
        return pointee_ty;
    }
};

/// Exact wire-layout safety failure reason reported by `E0315` (`DR-20` `D-01`).
pub const WireLayoutViolationReason = enum(u8) {
    /// Type carries `@secret` (`is_secret == true`) and cannot cross raw byte boundaries.
    secret_type = 0,
    /// Type belongs to `AutoDrop` or `@linear` ownership tier (`has_drop` or linear resource).
    non_copy_ownership = 1,
    /// Type contains pointers, references, slices, `str`, function pointers, closures, or `dyn Trait`.
    indirection_or_handle = 2,
    /// Type has invalid bit patterns (`bool`, `char`, `never`, `T?`, `Result`, or non-exhaustive `enum`).
    invalid_bit_patterns = 3,
    /// Refinement `T is low..=high` narrows the domain of its base integer type.
    refinement_narrows_domain = 4,
    /// Struct or tuple contains unzeroed inter-field padding without `@zero_pad`.
    unzeroed_inter_field_padding = 5,
    /// Struct or tuple contains unzeroed tail padding without `@zero_pad`.
    unzeroed_tail_padding = 6,
    /// `union` lacks `@zero_pad` required to zero inactive variant tail bytes before `IntoBytes`.
    union_requires_zero_pad = 7,
    /// `@bit_cast[Dst](src)` source and destination byte sizes differ.
    size_mismatch = 8,
};

/// Structured layout diagnostic explanation for `E0315` wire-contract violations.
pub const WireLayoutViolation = struct {
    /// Primary violation classification.
    reason: WireLayoutViolationReason,
    /// Exact byte offset where padding or invalid bit-pattern member begins.
    byte_offset: u64 = 0,
    /// Number of uninitialized padding bytes (or expected size on `.size_mismatch`).
    padding_bytes: u64 = 0,
    /// Offending field/type identifier when applicable (`""` for anonymous primitives/tuples).
    field_name: []const u8 = "",
};

/// Selector distinguishing `.narrow` (trapping/checked) vs. `.try_narrow` (`Option`-returning) (`DR-20` `D-11`).
pub const NarrowCallKind = enum(u8) {
    /// Checked `.narrow[Dst]()` / `.narrow() -> Dst` (traps on out-of-range runtime value unless statically proven).
    narrow = 0,
    /// Fallible `.try_narrow[Dst]()` / `.try_narrow() -> Dst?` (returns `.None` on out-of-range value).
    try_narrow = 1,
};

/// Side-table record recorded by `TypeChecker` for `.narrow` / `.try_narrow` method calls (`DR-20` `D-11`).
pub const NarrowCallInfo = struct {
    /// `.narrow` vs. `.try_narrow`.
    kind: NarrowCallKind,
    /// Receiver integer (or `RangeRefined` integer) `TypeId`.
    src_ty: TypeId,
    /// Target narrowed integer (or `RangeRefined` integer) `TypeId` (`Dst`, unwrapped from `Dst?` for `try_narrow`).
    dst_ty: TypeId,
    /// Inclusive lower bound of `dst_ty` (`128`-bit signed domain).
    min_val: i128 = 0,
    /// Inclusive upper bound of `dst_ty` (`128`-bit signed domain).
    max_val: i128 = 0,
};

/// Single call-site argument slot mapping a source argument expression to a canonical parameter ordinal (`DR-21` `SE-07`).
pub const CallArgSlot = struct {
    /// Canonical callee parameter index (`0..total_params - 1`, excluding `self` on method calls).
    param_index: u16,
    /// Value expression AST `NodeIndex` (unwrapped from `.named_arg`).
    arg_ast_node: NodeIndex,
    /// `true` when supplied as `label: expr`.
    is_named: bool,
};

/// Side-table record recorded by `TypeChecker` for calls using named or omitted-default arguments (`DR-21` `SE-07`).
pub const CallArgMapping = struct {
    /// Resolved callee `SymbolIndex` (`fn_sym` or `enum_variant_sym`).
    callee_sym: SymbolIndex = .none,
    /// Owned slice of supplied call arguments in left-to-right source evaluation order.
    provided_slots: []CallArgSlot = &.{},
    /// Total formal parameter count (excluding `self` on method calls).
    total_params: u16 = 0,
    /// `true` when arguments are out-of-order relative to formal parameters or omit trailing/middle defaults.
    has_reordered_or_default: bool = false,
};

/// Re-exported `@cfg` target operating-system selector (`SE-18`).
pub const CfgOs = symbol_resolver.CfgOs;

/// Re-exported `@cfg` target CPU architecture selector (`SE-18`).
pub const CfgArch = symbol_resolver.CfgArch;

/// Re-exported `@cfg` target C ABI selector (`SE-18`).
pub const CfgAbi = symbol_resolver.CfgAbi;

/// Re-exported `@cfg` target byte-order selector (`SE-18`).
pub const CfgEndian = symbol_resolver.CfgEndian;

/// Re-exported compile-time `@cfg(expr)` evaluation context (`DR-22` `SE-18`).
pub const CfgEnv = symbol_resolver.CfgEnv;

/// Validated per-hole interpolation descriptor recorded for `HirLowerer` (`DR-22` `SE-12`).
pub const InterpHoleSpec = struct {
    /// Zero-based hole index inside the interpolated string literal.
    hole_index: u16,
    /// `true` when `{expr=}` self-documenting debug shorthand is present.
    has_debug_eq: bool,
    /// Validated 8-byte `FmtSpec` descriptor (`flags_and_fill`, `width_or_none`, `precision_or_none`).
    spec: lexer.FmtSpec,
    /// Synthesized `TypeId` of the interpolated hole expression.
    expr_type_id: TypeId,
    /// Rebased source `Span` of the sub-expression inside `file_id`.
    expr_span: Span,
    /// Interned trimmed source text of `expr` (used to emit `"expr = "` prefix for `{expr=}`).
    raw_expr_text: SymbolId = .none,
};

/// Validated string interpolation side-table metadata keyed by `.string_lit` AST offset (`SE-12`).
pub const StringInterpMeta = struct {
    /// `true` when checked top-down against `FmtArgs` (zero-allocation borrowed view mode).
    is_fmt_args_mode: bool = false,
    /// `true` when the literal uses triple-quote `"""…"""` multiline delimiters.
    is_multiline: bool = false,
    /// Opening quote delimiter byte width (`3` for `"""`, `1` for `"`).
    delimiter_width: u8 = 1,
    /// Owned slice of validated `{expr[=][:spec]}` hole descriptors.
    holes: []InterpHoleSpec = &.{},
};

/// Stores resolved types, symbols, generic instantiations, `?` conversions, and `@attribute_schema`
/// instances strictly within `[ast_start .. ast_end)` using window-relative keys (`node_id - ast_start`)
/// so sibling-body edits that shift `ast_start` preserve Early Cutoff via $O(1)$ `rebaseWindow`.
pub const BodySemanticSideTables = struct {
    /// Allocator owning all slices and maps in this artifact.
    allocator: std.mem.Allocator,
    /// Owning definition handle (`DefId.NONE` for whole-file extraction).
    def_id: DefId,
    /// Inclusive AST `NodeIndex` start of the body window.
    ast_start: u32,
    /// Exclusive AST `NodeIndex` end of the body window (`node_types.len == ast_end - ast_start`).
    ast_end: u32,
    /// Dense resolved `TypeId` per AST node in `[ast_start .. ast_end)`.
    node_types: []TypeId,
    /// Dense resolved `SymbolIndex` per AST node in `[ast_start .. ast_end)` (`.none` when unmapped).
    node_symbols: []SymbolIndex,
    /// Concrete generic / Type-Group `[TypeId…]` arguments keyed by relative AST offset (`node_id - ast_start`).
    call_instantiations: std.AutoHashMapUnmanaged(u32, []TypeId) = .empty,
    /// `@from` `FromError` conversion function `DefId`s keyed by relative `.try_expr` AST offset.
    try_conversions: std.AutoHashMapUnmanaged(u32, DefId) = .empty,
    /// `@derive(From)` 0-based target enum variant ordinals keyed by relative `.try_expr` AST offset (`SE-10`).
    try_from_variants: std.AutoHashMapUnmanaged(u32, u32) = .empty,
    /// Resolved `.narrow` / `.try_narrow` descriptors keyed by relative `.method_call` AST offset (`DR-20` `D-11`).
    narrow_calls: std.AutoHashMapUnmanaged(u32, NarrowCallInfo) = .empty,
    /// Named / default call-argument mappings keyed by relative call AST offset (`DR-21` `SE-07`).
    call_arg_mappings: std.AutoHashMapUnmanaged(u32, CallArgMapping) = .empty,
    /// Validated `FmtSpec` / `FmtArgs` interpolation descriptors keyed by relative `.string_lit` AST offset (`SE-12`).
    string_interps: std.AutoHashMapUnmanaged(u32, StringInterpMeta) = .empty,
    /// State struct `TypeId` (`S` in `&mut S`) keyed by relative trailing-block `@builder` call AST offset (`SE-22`).
    builder_block_calls: std.AutoHashMapUnmanaged(u32, TypeId) = .empty,
    /// Formal parameter ordinal receiving implicit `__builder` keyed by relative `@builder_item` call AST offset (`SE-22`).
    implicit_builder_item_calls: std.AutoHashMapUnmanaged(u32, u16) = .empty,
    /// Target labeled `.match_expr` `NodeIndex` keyed by relative `continue :fsm expr` AST offset (`SE-23`).
    labeled_match_continues: std.AutoHashMapUnmanaged(u32, NodeIndex) = .empty,
    /// Validated `@attribute_schema` instances scoped to `def_id` (or file when `def_id.isNone()`).
    attr_instances: []AttrInstance = &.{},

    /// Releases all owned slices and hash maps in `self`.
    pub fn deinit(self: *BodySemanticSideTables) void {
        if (self.node_types.len > 0) self.allocator.free(self.node_types);
        if (self.node_symbols.len > 0) self.allocator.free(self.node_symbols);
        var inst_iter = self.call_instantiations.valueIterator();
        while (inst_iter.next()) |slice_ptr| {
            if (slice_ptr.*.len > 0) self.allocator.free(slice_ptr.*);
        }
        self.call_instantiations.deinit(self.allocator);
        self.try_conversions.deinit(self.allocator);
        self.try_from_variants.deinit(self.allocator);
        self.narrow_calls.deinit(self.allocator);
        var map_iter = self.call_arg_mappings.valueIterator();
        while (map_iter.next()) |mapping_ptr| {
            if (mapping_ptr.provided_slots.len > 0) self.allocator.free(mapping_ptr.provided_slots);
        }
        self.call_arg_mappings.deinit(self.allocator);
        var interp_iter = self.string_interps.valueIterator();
        while (interp_iter.next()) |interp_ptr| {
            if (interp_ptr.holes.len > 0) self.allocator.free(interp_ptr.holes);
        }
        self.string_interps.deinit(self.allocator);
        self.builder_block_calls.deinit(self.allocator);
        self.implicit_builder_item_calls.deinit(self.allocator);
        self.labeled_match_continues.deinit(self.allocator);
        for (self.attr_instances) |attr_inst| {
            if (attr_inst.fields.len > 0) self.allocator.free(attr_inst.fields);
        }
        if (self.attr_instances.len > 0) self.allocator.free(self.attr_instances);
        self.* = undefined;
    }

    /// Rebases `[ast_start .. ast_end)` and AST-indexed side-table targets when preceding sibling bodies shift AST indices.
    pub inline fn rebaseWindow(self: *BodySemanticSideTables, new_ast_start: u32) void {
        const delta: i64 = @as(i64, new_ast_start) - @as(i64, self.ast_start);
        const window_len = self.ast_end - self.ast_start;
        self.ast_start = new_ast_start;
        self.ast_end = new_ast_start + window_len;
        if (delta != 0) {
            if (self.call_arg_mappings.count() > 0) {
                var map_iter = self.call_arg_mappings.valueIterator();
                while (map_iter.next()) |mapping_ptr| {
                    for (mapping_ptr.provided_slots) |*slot_ptr| {
                        if (!slot_ptr.arg_ast_node.isNone()) {
                            const shifted = @as(i64, slot_ptr.arg_ast_node.asInt()) + delta;
                            if (shifted >= 0 and shifted < @as(i64, NodeIndex.none.asInt())) {
                                slot_ptr.arg_ast_node = NodeIndex.fromInt(@intCast(shifted));
                            }
                        }
                    }
                }
            }
            if (self.labeled_match_continues.count() > 0) {
                var cont_iter = self.labeled_match_continues.valueIterator();
                while (cont_iter.next()) |target_ptr| {
                    if (!target_ptr.*.isNone()) {
                        const shifted = @as(i64, target_ptr.*.asInt()) + delta;
                        if (shifted >= 0 and shifted < @as(i64, NodeIndex.none.asInt())) {
                            target_ptr.* = NodeIndex.fromInt(@intCast(shifted));
                        }
                    }
                }
            }
        }
    }

    /// Looks up the resolved `TypeId` of `node_id` in $O(1)$ time (`.err_ty` if outside window).
    pub inline fn getNodeType(self: *const BodySemanticSideTables, node_id: NodeIndex) TypeId {
        if (node_id.isNone()) return .err_ty;
        const raw_idx = node_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return .err_ty;
        return self.node_types[raw_idx - self.ast_start];
    }

    /// Looks up the resolved `SymbolIndex` of `node_id` in $O(1)$ time (`.none` if unmapped).
    pub inline fn getNodeSymbol(self: *const BodySemanticSideTables, node_id: NodeIndex) SymbolIndex {
        if (node_id.isNone()) return .none;
        const raw_idx = node_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return .none;
        return self.node_symbols[raw_idx - self.ast_start];
    }

    /// Looks up the inferred concrete `TypeId` instantiation tuple for call AST node `call_id`.
    pub inline fn getCallInstantiation(
        self: *const BodySemanticSideTables,
        call_id: NodeIndex,
    ) ?[]const TypeId {
        if (call_id.isNone()) return null;
        const raw_idx = call_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.call_instantiations.get(raw_idx - self.ast_start);
    }

    /// Looks up the `@from` conversion `DefId` recorded for `.try_expr` AST node `try_id`.
    pub inline fn getTryConversion(self: *const BodySemanticSideTables, try_id: NodeIndex) ?DefId {
        if (try_id.isNone()) return null;
        const raw_idx = try_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.try_conversions.get(raw_idx - self.ast_start);
    }

    /// Looks up the `@derive(From)` 0-based target enum variant ordinal for `.try_expr` AST node `try_id` (`SE-10`).
    pub inline fn getTryFromVariant(self: *const BodySemanticSideTables, try_id: NodeIndex) ?u32 {
        if (try_id.isNone()) return null;
        const raw_idx = try_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.try_from_variants.get(raw_idx - self.ast_start);
    }

    /// Looks up the `.narrow` / `.try_narrow` descriptor recorded for `.method_call` AST node `call_id`.
    pub inline fn getNarrowCall(self: *const BodySemanticSideTables, call_id: NodeIndex) ?NarrowCallInfo {
        if (call_id.isNone()) return null;
        const raw_idx = call_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.narrow_calls.get(raw_idx - self.ast_start);
    }

    /// Looks up the named / default argument mapping recorded for call AST node `call_id` (`DR-21` `SE-07`).
    pub inline fn getCallArgMapping(self: *const BodySemanticSideTables, call_id: NodeIndex) ?CallArgMapping {
        if (call_id.isNone()) return null;
        const raw_idx = call_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.call_arg_mappings.get(raw_idx - self.ast_start);
    }

    /// Looks up the validated `StringInterpMeta` recorded for `.string_lit` AST node `str_id` (`SE-12`).
    pub inline fn getStringInterp(self: *const BodySemanticSideTables, str_id: NodeIndex) ?StringInterpMeta {
        if (str_id.isNone()) return null;
        const raw_idx = str_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.string_interps.get(raw_idx - self.ast_start);
    }

    /// Looks up the `@builder` state struct `TypeId` (`S`) for trailing-block call AST node `call_id` (`SE-22`).
    pub inline fn getBuilderBlockStateType(self: *const BodySemanticSideTables, call_id: NodeIndex) ?TypeId {
        if (call_id.isNone()) return null;
        const raw_idx = call_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.builder_block_calls.get(raw_idx - self.ast_start);
    }

    /// Looks up the formal parameter ordinal receiving implicit `__builder` on `@builder_item` call `call_id` (`SE-22`).
    pub inline fn getImplicitBuilderParamIndex(self: *const BodySemanticSideTables, call_id: NodeIndex) ?u16 {
        if (call_id.isNone()) return null;
        const raw_idx = call_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.implicit_builder_item_calls.get(raw_idx - self.ast_start);
    }

    /// Looks up the target labeled `.match_expr` `NodeIndex` for `continue :fsm expr` AST node `cont_id` (`SE-23`).
    pub inline fn getLabeledMatchContinueTarget(
        self: *const BodySemanticSideTables,
        cont_id: NodeIndex,
    ) ?NodeIndex {
        if (cont_id.isNone()) return null;
        const raw_idx = cont_id.asInt();
        if (raw_idx < self.ast_start or raw_idx >= self.ast_end) return null;
        return self.labeled_match_continues.get(raw_idx - self.ast_start);
    }
};

/// Canonical compiler-intrinsic selector for `@snake_case` expressions (`DR-05` §3.3, `DR-20` `D-01`, Phase 7).
pub const IntrinsicKind = enum(u8) {
    /// `@align_of[T]() -> usize` (`0`).
    align_of = 0,
    /// `@as_bytes(&val) -> &[u8]` (`1`, requires `T: IntoBytes`, `E0315`).
    as_bytes = 1,
    /// `@atomic_cmpxchg(ptr, expected, desired) -> (T, bool)` (`2`).
    atomic_cmpxchg = 2,
    /// `@atomic_fence(order?) -> unit` (`3`).
    atomic_fence = 3,
    /// `@atomic_load(ptr, order?) -> T` (`4`).
    atomic_load = 4,
    /// `@atomic_rmw_add(ptr, delta, order?) -> T` (`5`).
    atomic_rmw_add = 5,
    /// `@atomic_rmw_sub(ptr, delta, order?) -> T` (`6`).
    atomic_rmw_sub = 6,
    /// `@atomic_rmw_xchg(ptr, val, order?) -> T` (`7`).
    atomic_rmw_xchg = 7,
    /// `@atomic_store(ptr, val, order?) -> unit` (`8`).
    atomic_store = 8,
    /// `@bit_cast[Dst](src) -> Dst` (`9`, requires `Src: IntoBytes`, `Dst: FromBytes`, equal size, `E0315`).
    bit_cast = 9,
    /// `@c_import(comptime path: str) -> module` (`10`, `DR-10` §2.2 C header translation).
    c_import = 10,
    /// `@caller_location() -> SourceLoc` (`11`, `DR-22` `SE-17`).
    caller_location = 11,
    /// `@compile_assert(cond: bool, msg: str) -> unit` (`12`).
    compile_assert = 12,
    /// `@compile_error(msg: str) -> never` (`13`).
    compile_error = 13,
    /// `@default_init[T]() -> T` (`14`).
    default_init = 14,
    /// `@drop_trace(id: i64) -> unit` (`15`).
    drop_trace = 15,
    /// `@embed_bytes(comptime path: str) -> &[u8]` (`16`).
    embed_bytes = 16,
    /// `@field(target, comptime field_ref) -> FieldTy` (`17`).
    field = 17,
    /// `@field_attr_lookup[A](id: MetaId, idx: u32) -> A?` (`18`).
    field_attr_lookup = 18,
    /// `@from_bytes[T](bytes: &[u8]) -> T?` (`19`, requires `T: FromBytes`, `E0315`).
    from_bytes = 19,
    /// `@has_field[T](comptime name: str) -> bool` (`20`).
    has_field = 20,
    /// `@implements[T, Trait]() -> bool` (`21`).
    implements = 21,
    /// `@panic(msg: str) -> never` (`22`).
    panic = 22,
    /// `@poll_reload(state?) -> bool` (`23`, `DR-19` quiescent epoch safepoint hook).
    poll_reload = 23,
    /// `@simd_add(lhs, rhs) -> Vec` (`24`).
    simd_add = 24,
    /// `@simd_mul(lhs, rhs) -> Vec` (`25`).
    simd_mul = 25,
    /// `@simd_reduce_add(vec) -> Lane` (`26`).
    simd_reduce_add = 26,
    /// `@simd_splat[Vec](lane) -> Vec` (`27`).
    simd_splat = 27,
    /// `@simd_sub(lhs, rhs) -> Vec` (`28`).
    simd_sub = 28,
    /// `@size_of[T]() -> usize` (`29`).
    size_of = 29,
    /// `@sys_exit(code: i32) -> never` (`30`).
    sys_exit = 30,
    /// `@sys_write(fd: i32, buf) -> isize` (`31`).
    sys_write = 31,
    /// `@trap() -> never` (`32`).
    trap = 32,
    /// `@type_info[T]() -> cx.meta.TypeInfo` (`33`).
    type_info = 33,
    /// `@type_name[T]() -> str` (`34`).
    type_name = 34,
    /// `@view_bytes[T](bytes: &[u8]) -> (&T)?` (`35`, requires `T: FromBytes`, `E0315`).
    view_bytes = 35,
};

/// Canonical integer primitive associated constant tags (`MIN`, `MAX`, `BITS`).
pub const IntAssocConstKind = enum(u8) {
    /// Bit width of the integer primitive (`u32`).
    bits = 0,
    /// Maximum representable integer value (`Self`).
    max = 1,
    /// Minimum representable integer value (`Self`).
    min = 2,
};

/// Canonical floating-point primitive associated constant tags (`f32` / `f64`).
pub const FloatAssocConstKind = enum(u8) {
    /// IEEE-754 bit width (`32` or `64`, typed as `u32`).
    bits = 0,
    /// Machine epsilon (`Self`).
    epsilon = 1,
    /// Positive IEEE-754 infinity (`Self`).
    infinity = 2,
    /// Finite maximum representable float (`Self`).
    max = 3,
    /// Finite minimum representable float (`-MAX`, `Self`).
    min = 4,
    /// Quiet NaN (`Self`).
    nan = 5,
    /// Negative IEEE-754 infinity (`Self`).
    neg_infinity = 6,
    /// Archimedes' circle constant $\pi$ (`Self`).
    pi = 7,
    /// Full-turn circle constant $\tau = 2\pi$ (`Self`).
    tau = 8,
};

/// Half-open CST node index range and diagnostic `Span` for a single `.type_param` subtree.
const TypeParamCstRange = struct {
    /// Inclusive starting CST node index of the `.type_param` subtree.
    cst_start: usize,
    /// Exclusive ending CST node index of the `.type_param` subtree.
    cst_end: usize,
    /// Source span of the `.type_param` for diagnostic reporting.
    span: Span,
};

/// Candidate enum variant recorded while synthesizing `@derive(From)` / `@from` conversions.
const FromCand = struct {
    /// Single-field payload `TypeId` converted by `From[src_ty]`.
    src_ty: TypeId,
    /// Zero-based variant ordinal inside the parent enum.
    ordinal: u16,
    /// `true` when the variant carries an explicit `@from` attribute.
    is_explicit_from: bool,
    /// Declaration `Span` of the variant for collision diagnostics.
    span: Span,
};

/// Function-level or return-level FFI contract attribute tag (`DR-10` §2.3).
const FnFfiAttrKind = enum(u8) {
    /// `@free_with(dealloc_fn)` deallocator pairing contract.
    free_with,
    /// `@may_be_null` nullable return pointer contract.
    may_be_null,
    /// `@non_null` non-null return pointer contract.
    non_null,
    /// `@null_terminated` NUL-terminated return pointer contract.
    null_terminated,
    /// `@owned_by_caller` linear return ownership obligation.
    owned_by_caller,
    /// `@thread_local` invalid placement guard on functions.
    thread_local,
    /// `@trusted` safe-callable foreign symbol contract.
    trusted,
};

/// Parameter-level FFI contract attribute tag (`DR-10` §2.3).
const ParamFfiAttrKind = enum(u8) {
    /// `@borrowed` non-escaping foreign parameter borrow.
    borrowed,
    /// `@byte_len(param)` byte-capacity spatial contract.
    byte_len,
    /// `@consumes` deallocation sink contract.
    consumes,
    /// `@escapes` foreign pointer retention contract.
    escapes,
    /// `@may_be_null` nullable pointer parameter contract.
    may_be_null,
    /// `@non_null` non-null pointer parameter contract.
    non_null,
    /// `@null_terminated` C string parameter contract.
    null_terminated,
    /// `@out_param` foreign write-out initialization contract.
    out_param,
    /// `@slice_len(param)` element-count spatial contract.
    slice_len,
};

/// Built-in method tag on structured `TaskGroup[E]` handles (`DR-08`).
const TaskGroupMethodKind = enum(u8) {
    /// `group.cancel()` cooperative cancellation request.
    cancel,
    /// `group.cancel_all()` cooperative cancellation request.
    cancel_all,
    /// `group.is_cancelled()` cancellation state query.
    is_cancelled,
    /// `group.spawn(fut)` work-stealing cross-thread child task spawn.
    spawn,
    /// `group.spawn_local(fut)` current-thread pinned child task spawn.
    spawn_local,
};

/// Exact collision-free key for `LayoutNicheMemo` covering `subst.len <= 2` type-parameter bindings.
const LayoutNicheKey = struct {
    /// Resolved `TypeId.toU32()` handle.
    type_raw: u32,
    /// First generic parameter `TypeId.toU32()` (`0` when `subst_len < 1`).
    k0: u32,
    /// First concrete argument `TypeId.toU32()` (`0` when `subst_len < 1`).
    v0: u32,
    /// Second generic parameter `TypeId.toU32()` (`0` when `subst_len < 2`).
    k1: u32,
    /// Second concrete argument `TypeId.toU32()` (`0` when `subst_len < 2`).
    v1: u32,
    /// Recursion depth at query point (`< MAX_TYPE_DEPTH`).
    depth: u16,
    /// Active `NominalTypeSubst` entry count (`0`, `1`, or `2`).
    subst_len: u8,

    /// Builds an exact `LayoutNicheKey` when `subst` has `<= 2` non-const bindings (`null` otherwise).
    inline fn fromQuery(type_id: TypeId, subst: *const NominalTypeSubst, depth: u32) ?LayoutNicheKey {
        if (depth > std.math.maxInt(u16)) return null;
        return switch (subst.len) {
            0 => .{
                .type_raw = type_id.toU32(),
                .k0 = 0,
                .v0 = 0,
                .k1 = 0,
                .v1 = 0,
                .depth = @intCast(depth),
                .subst_len = 0,
            },
            1 => if (subst.const_syms[0] == .empty) .{
                .type_raw = type_id.toU32(),
                .k0 = subst.keys[0].toU32(),
                .v0 = subst.vals[0].toU32(),
                .k1 = 0,
                .v1 = 0,
                .depth = @intCast(depth),
                .subst_len = 1,
            } else null,
            2 => if (subst.const_syms[0] == .empty and subst.const_syms[1] == .empty) .{
                .type_raw = type_id.toU32(),
                .k0 = subst.keys[0].toU32(),
                .v0 = subst.vals[0].toU32(),
                .k1 = subst.keys[1].toU32(),
                .v1 = subst.vals[1].toU32(),
                .depth = @intCast(depth),
                .subst_len = 2,
            } else null,
            else => null,
        };
    }

    /// Returns `true` when `self` and `other` match bit-for-bit across all active key components.
    inline fn isEqual(self: LayoutNicheKey, other: LayoutNicheKey) bool {
        return self.type_raw == other.type_raw and
            self.depth == other.depth and
            self.subst_len == other.subst_len and
            self.k0 == other.k0 and
            self.v0 == other.v0 and
            self.k1 == other.k1 and
            self.v1 == other.v1;
    }

    /// Computes the 2-way set base index (`0, 2, …, 254`) for `self`.
    inline fn computeSetBase(self: LayoutNicheKey) u8 {
        var mix: u32 = (self.type_raw *% 0x9E37_79B1) ^ (@as(u32, self.depth) *% 0x85EB_CA6B);
        if (self.subst_len >= 1) {
            mix ^= (self.k0 *% 0xC2B2_AE35) ^ (self.v0 *% 0x27D4_EB2F);
        }
        if (self.subst_len >= 2) {
            mix ^= (self.k1 *% 0x1656_67B1) ^ (self.v1 *% 0xD3A2_646C);
        }
        mix ^= mix >> 16;
        mix *%= 0x7FEB_352D;
        mix ^= mix >> 15;
        return @as(u8, @truncate(mix)) & 0xFE;
    }
};

/// Zero-heap-allocation 256-slot (`128` 2-way sets) SoA stack memo for `TypeLayout` and `LeafNicheInfo` DAG queries.
const LayoutNicheMemo = struct {
    /// Bitset marking slots holding a valid `TypeLayout` (`32` bytes zeroed at init).
    has_layout_bits: [4]u64 = @splat(0),
    /// Bitset marking slots holding a valid `LeafNicheInfo` (`32` bytes zeroed at init).
    has_niche_bits: [4]u64 = @splat(0),
    /// Uninitialized 256-slot exact query keys (populated on demand).
    keys: [256]LayoutNicheKey = undefined,
    /// Uninitialized 256-slot cached `TypeLayout` values (populated on demand).
    layout_vals: [256]TypeLayout = undefined,
    /// Uninitialized 256-slot cached `LeafNicheInfo` values (populated on demand).
    niche_vals: [256]LeafNicheInfo = undefined,

    /// Returns `true` if `bit_words` has bit `slot_idx` set.
    inline fn hasBit(bit_words: *const [4]u64, slot_idx: u8) bool {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        return (bit_words[word_idx] & (@as(u64, 1) << bit_pos)) != 0;
    }

    /// Sets bit `slot_idx` inside `bit_words`.
    inline fn setBit(bit_words: *[4]u64, slot_idx: u8) void {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        bit_words[word_idx] |= (@as(u64, 1) << bit_pos);
    }

    /// Clears bit `slot_idx` inside `bit_words`.
    inline fn clearBit(bit_words: *[4]u64, slot_idx: u8) void {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        bit_words[word_idx] &= ~(@as(u64, 1) << bit_pos);
    }

    /// Returns `true` if `slot_idx` holds either a valid layout or niche entry.
    inline fn isSlotOccupied(self: *const LayoutNicheMemo, slot_idx: u8) bool {
        return hasBit(&self.has_layout_bits, slot_idx) or hasBit(&self.has_niche_bits, slot_idx);
    }

    /// Selects the target slot inside `key`'s 2-way set, preserving immediate child parity (`depth & 1`).
    inline fn selectStoreSlot(self: *const LayoutNicheMemo, key: LayoutNicheKey) u8 {
        const base_slot = key.computeSetBase();
        if (self.isSlotOccupied(base_slot) and self.keys[base_slot].isEqual(key)) return base_slot;
        const second_slot = base_slot | 1;
        if (self.isSlotOccupied(second_slot) and self.keys[second_slot].isEqual(key)) return second_slot;
        const parity_way: u8 = @intCast(key.depth & 1);
        const parity_slot = base_slot | parity_way;
        const alt_slot = base_slot | (parity_way ^ 1);
        if (!self.isSlotOccupied(parity_slot)) return parity_slot;
        if (!self.isSlotOccupied(alt_slot)) return alt_slot;
        return parity_slot;
    }

    /// Looks up a cached `TypeLayout` matching `key` (`null` on miss).
    inline fn lookupLayout(self: *const LayoutNicheMemo, key: LayoutNicheKey) ?TypeLayout {
        const base_slot = key.computeSetBase();
        if (hasBit(&self.has_layout_bits, base_slot) and self.keys[base_slot].isEqual(key)) {
            return self.layout_vals[base_slot];
        }
        const second_slot = base_slot | 1;
        if (hasBit(&self.has_layout_bits, second_slot) and self.keys[second_slot].isEqual(key)) {
            return self.layout_vals[second_slot];
        }
        return null;
    }

    /// Stores `layout_val` under `key`, clearing any stale `has_niche_bits` bit if `slot_idx` changed keys.
    inline fn storeLayout(self: *LayoutNicheMemo, key: LayoutNicheKey, layout_val: TypeLayout) void {
        const slot_idx = self.selectStoreSlot(key);
        if (!self.isSlotOccupied(slot_idx) or !self.keys[slot_idx].isEqual(key)) {
            clearBit(&self.has_niche_bits, slot_idx);
            self.keys[slot_idx] = key;
        }
        self.layout_vals[slot_idx] = layout_val;
        setBit(&self.has_layout_bits, slot_idx);
    }

    /// Looks up a cached `LeafNicheInfo` matching `key` (`null` on miss).
    inline fn lookupNiche(self: *const LayoutNicheMemo, key: LayoutNicheKey) ?LeafNicheInfo {
        const base_slot = key.computeSetBase();
        if (hasBit(&self.has_niche_bits, base_slot) and self.keys[base_slot].isEqual(key)) {
            return self.niche_vals[base_slot];
        }
        const second_slot = base_slot | 1;
        if (hasBit(&self.has_niche_bits, second_slot) and self.keys[second_slot].isEqual(key)) {
            return self.niche_vals[second_slot];
        }
        return null;
    }

    /// Stores `niche_val` under `key`, clearing any stale `has_layout_bits` bit if `slot_idx` changed keys.
    inline fn storeNiche(self: *LayoutNicheMemo, key: LayoutNicheKey, niche_val: LeafNicheInfo) void {
        const slot_idx = self.selectStoreSlot(key);
        if (!self.isSlotOccupied(slot_idx) or !self.keys[slot_idx].isEqual(key)) {
            clearBit(&self.has_layout_bits, slot_idx);
            self.keys[slot_idx] = key;
        }
        self.niche_vals[slot_idx] = niche_val;
        setBit(&self.has_niche_bits, slot_idx);
    }
};

/// Zero-heap-allocation 128-slot (`64` 2-way sets) visited memo for `Send` / `Sync` DAG verification (`DR-08`).
const SendSyncVisitedMemo = struct {
    /// Validity bitset for the 128 slots (`16` bytes zeroed at init).
    has_bits: [2]u64 = @splat(0),
    /// Exact `TypeId.toU32()` keys proven `Send` / `Sync` (`null` violation).
    type_raws: [128]u32 = undefined,
    /// Packed `(depth << 1) | @intFromBool(is_requiring_sync)` metadata for populated slots.
    meta_tags: [128]u16 = undefined,

    /// Returns `true` if slot `slot_idx` holds a valid entry.
    inline fn hasSlot(self: *const SendSyncVisitedMemo, slot_idx: u7) bool {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        return (self.has_bits[word_idx] & (@as(u64, 1) << bit_pos)) != 0;
    }

    /// Marks slot `slot_idx` valid.
    inline fn setSlot(self: *SendSyncVisitedMemo, slot_idx: u7) void {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        self.has_bits[word_idx] |= (@as(u64, 1) << bit_pos);
    }

    /// Computes the 2-way set base index (`0, 2, …, 126`) for `(type_raw, meta_tag)`.
    inline fn computeSetBase(type_raw: u32, meta_tag: u16) u7 {
        var mix: u32 = (type_raw *% 0x9E37_79B1) ^ (@as(u32, meta_tag) *% 0x85EB_CA6B);
        mix ^= mix >> 16;
        mix *%= 0x7FEB_352D;
        mix ^= mix >> 15;
        return @as(u7, @truncate(mix)) & 0x7E;
    }

    /// Returns `true` if `(type_raw, is_requiring_sync, depth)` was already proven valid (`null` violation).
    inline fn hasVerified(
        self: *const SendSyncVisitedMemo,
        type_raw: u32,
        is_requiring_sync: bool,
        depth: u32,
    ) bool {
        const meta_tag: u16 = (@as(u16, @intCast(depth)) << 1) | @intFromBool(is_requiring_sync);
        const base_slot = computeSetBase(type_raw, meta_tag);
        if (self.hasSlot(base_slot) and
            self.type_raws[base_slot] == type_raw and
            self.meta_tags[base_slot] == meta_tag)
        {
            return true;
        }
        const second_slot = base_slot | 1;
        return self.hasSlot(second_slot) and
            self.type_raws[second_slot] == type_raw and
            self.meta_tags[second_slot] == meta_tag;
    }

    /// Records that `(type_raw, is_requiring_sync, depth)` has zero `Send` / `Sync` violations.
    inline fn recordVerified(
        self: *SendSyncVisitedMemo,
        type_raw: u32,
        is_requiring_sync: bool,
        depth: u32,
    ) void {
        const meta_tag: u16 = (@as(u16, @intCast(depth)) << 1) | @intFromBool(is_requiring_sync);
        const base_slot = computeSetBase(type_raw, meta_tag);
        const second_slot = base_slot | 1;
        const parity_way: u7 = @intCast(depth & 1);
        const parity_slot = base_slot | parity_way;
        const alt_slot = base_slot | (parity_way ^ 1);
        const slot_idx: u7 = if (self.hasSlot(base_slot) and
            self.type_raws[base_slot] == type_raw and
            self.meta_tags[base_slot] == meta_tag)
            base_slot
        else if (self.hasSlot(second_slot) and
            self.type_raws[second_slot] == type_raw and
            self.meta_tags[second_slot] == meta_tag)
            second_slot
        else if (!self.hasSlot(parity_slot))
            parity_slot
        else if (!self.hasSlot(alt_slot))
            alt_slot
        else
            parity_slot;
        self.type_raws[slot_idx] = type_raw;
        self.meta_tags[slot_idx] = meta_tag;
        self.setSlot(slot_idx);
    }
};

/// Exact collision-free key for `OwnershipMemo` covering `subst.len <= 1` type-parameter bindings.
const OwnershipMemoKey = struct {
    /// Resolved `TypeId.toU32()` handle.
    ty_raw: u32,
    /// First generic parameter `TypeId.toU32()` (`0` when `subst_len == 0`).
    k0: u32,
    /// First concrete argument `TypeId.toU32()` (`0` when `subst_len == 0`).
    v0: u32,
    /// Active `NominalTypeSubst` entry count (`0` or `1`).
    subst_len: u8,
    /// `true` when `&mut T` is classified as `.linear_tier` (`false` for `hasLinearObligation`).
    is_mut_ref_linear: bool,

    /// Builds an exact `OwnershipMemoKey` when `subst` has `<= 1` non-const binding (`null` otherwise).
    inline fn fromQuery(
        ty: TypeId,
        subst: *const NominalTypeSubst,
        is_mut_ref_linear: bool,
    ) ?OwnershipMemoKey {
        return switch (subst.len) {
            0 => .{
                .ty_raw = ty.toU32(),
                .k0 = 0,
                .v0 = 0,
                .subst_len = 0,
                .is_mut_ref_linear = is_mut_ref_linear,
            },
            1 => if (subst.const_syms[0] == .empty) .{
                .ty_raw = ty.toU32(),
                .k0 = subst.keys[0].toU32(),
                .v0 = subst.vals[0].toU32(),
                .subst_len = 1,
                .is_mut_ref_linear = is_mut_ref_linear,
            } else null,
            else => null,
        };
    }

    /// Returns `true` when `self` and `other` match bit-for-bit.
    inline fn isEqual(self: OwnershipMemoKey, other: OwnershipMemoKey) bool {
        return self.ty_raw == other.ty_raw and
            self.is_mut_ref_linear == other.is_mut_ref_linear and
            self.subst_len == other.subst_len and
            self.k0 == other.k0 and
            self.v0 == other.v0;
    }

    /// Computes the 2-way set base index (`0, 2, …, 126`) for `self`.
    inline fn computeSetBase(self: OwnershipMemoKey) u7 {
        var mix: u32 = (self.ty_raw *% 0x9E37_79B1) ^
            (@as(u32, @intFromBool(self.is_mut_ref_linear)) *% 0x85EB_CA6B);
        if (self.subst_len >= 1) {
            mix ^= (self.k0 *% 0xC2B2_AE35) ^ (self.v0 *% 0x27D4_EB2F);
        }
        mix ^= mix >> 16;
        mix *%= 0x7FEB_352D;
        mix ^= mix >> 15;
        return @as(u7, @truncate(mix)) & 0x7E;
    }
};

/// Zero-heap-allocation 128-slot (`64` 2-way sets) stack memo for `classifyOwnershipTierCore`.
const OwnershipMemo = struct {
    /// Validity bitset for the 128 slots (`16` bytes zeroed at init).
    has_bits: [2]u64 = @splat(0),
    /// Uninitialized 128-slot exact keys (populated on demand).
    keys: [128]OwnershipMemoKey = undefined,
    /// Uninitialized 128-slot cached `OwnershipTier` results (populated on demand).
    vals: [128]OwnershipTier = undefined,

    /// Returns `true` if slot `slot_idx` holds a valid entry.
    inline fn hasSlot(self: *const OwnershipMemo, slot_idx: u7) bool {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        return (self.has_bits[word_idx] & (@as(u64, 1) << bit_pos)) != 0;
    }

    /// Marks slot `slot_idx` valid.
    inline fn setSlot(self: *OwnershipMemo, slot_idx: u7) void {
        const word_idx: usize = slot_idx >> 6;
        const bit_pos: u6 = @truncate(slot_idx);
        self.has_bits[word_idx] |= (@as(u64, 1) << bit_pos);
    }

    /// Looks up a cached `OwnershipTier` matching `key` (`null` on miss).
    inline fn lookup(self: *const OwnershipMemo, key: OwnershipMemoKey) ?OwnershipTier {
        const base_slot = key.computeSetBase();
        if (self.hasSlot(base_slot) and self.keys[base_slot].isEqual(key)) {
            return self.vals[base_slot];
        }
        const second_slot = base_slot | 1;
        if (self.hasSlot(second_slot) and self.keys[second_slot].isEqual(key)) {
            return self.vals[second_slot];
        }
        return null;
    }

    /// Stores `tier_val` under `key`, using `depth & 1` parity selection when evicting.
    inline fn store(self: *OwnershipMemo, key: OwnershipMemoKey, depth: usize, tier_val: OwnershipTier) void {
        const base_slot = key.computeSetBase();
        const second_slot = base_slot | 1;
        const parity_way: u7 = @intCast(depth & 1);
        const parity_slot = base_slot | parity_way;
        const alt_slot = base_slot | (parity_way ^ 1);
        const slot_idx: u7 = if (self.hasSlot(base_slot) and self.keys[base_slot].isEqual(key))
            base_slot
        else if (self.hasSlot(second_slot) and self.keys[second_slot].isEqual(key))
            second_slot
        else if (!self.hasSlot(parity_slot))
            parity_slot
        else if (!self.hasSlot(alt_slot))
            alt_slot
        else
            parity_slot;
        self.keys[slot_idx] = key;
        self.vals[slot_idx] = tier_val;
        self.setSlot(slot_idx);
    }
};

