/// Maximum recursion depth for cycle-safe ownership tier classification (`>= MAX_TYPE_DEPTH`).
const MAX_OWNERSHIP_VISIT_DEPTH: usize = MAX_TYPE_DEPTH;

/// $O(1)$ static slot-indexed display table for built-in primitives and Constrained Type Groups (`0..63`).
const BUILTIN_TYPE_NAMES: [STATIC_TYPE_SLOT_COUNT]?[]const u8 = blk: {
    var names: [STATIC_TYPE_SLOT_COUNT]?[]const u8 = @splat(null);
    for (symbol_resolver.BUILTIN_TYPES_AND_GROUPS) |entry| {
        names[entry.type_id.toU32()] = entry.name;
    }
    break :blk names;
};

// -------------------------------------- INTERNALS --------------------------------------

comptime {
    // Enforce the `DR-04` Section 2.2 14-byte zero-padding SoA column footprint invariant:
    const soa_bytes_per_type_node = @sizeOf(TypeTag) + @sizeOf(TypeFlags) +
        @sizeOf(u32) + @sizeOf(u32) + @sizeOf(u32);
    std.debug.assert(soa_bytes_per_type_node == 14);
}

/// Returns `true` if `rel_path` is a safe sandboxed relative header path without traversal or root escape.
fn isValidSandboxedCImportRelPath(rel_path: []const u8) bool {
    if (rel_path.len == 0) return false;
    if (rel_path[0] == '/' or rel_path[0] == '\\') return false;
    for (rel_path) |byte_val| {
        if (byte_val == 0 or byte_val == '\\' or byte_val == ':') return false;
    }
    var seg_iter = std.mem.splitScalar(u8, rel_path, '/');
    while (seg_iter.next()) |seg| {
        if (seg.len == 0 or std.mem.eql(u8, seg, ".") or std.mem.eql(u8, seg, "..")) {
            return false;
        }
    }
    return true;
}

/// Returns `true` if `tag` is a nominal declaration constructor eligible for cross-major `E0012` matching.
inline fn isCrossMajorNominalTag(tag: TypeTag) bool {
    return switch (tag) {
        .struct_ty, .enum_ty, .union_ty, .bit_field_ty, .trait_ty, .distinct_ty => true,
        else => false,
    };
}

/// Returns `true` if `tag` is a syntactic type AST node tag.
fn isTypeAstTag(tag: AstTag) bool {
    return switch (tag) {
        .type_hole,
        .prim_type,
        .named_type,
        .generic_type,
        .tuple_type,
        .array_type,
        .slice_type,
        .ref_type,
        .ptr_type,
        .optional_type,
        .result_type,
        .fn_type,
        .closure_type,
        .mode_type,
        .union_bound_type,
        .intersect_bound_type,
        => true,
        else => false,
    };
}

/// Computes a 32-bit structural hash for `(tag, flags, lhs, rhs, extra_slice)`.
fn computeStructuralTypeHash(
    tag: TypeTag,
    flags: TypeFlags,
    lhs: u32,
    rhs: u32,
    extra_slice: []const u32,
) u32 {
    var hasher = std.hash.Wyhash.init(TYPE_HASH_SEED);
    const header_bytes = [2]u8{ @backingInt(tag), @bitCast(flags) };
    hasher.update(&header_bytes);
    var pair_bytes: [8]u8 = undefined;
    std.mem.writeInt(u32, pair_bytes[0..4], lhs, .little);
    std.mem.writeInt(u32, pair_bytes[4..8], rhs, .little);
    hasher.update(&pair_bytes);
    for (extra_slice) |word| {
        var word_bytes: [4]u8 = undefined;
        std.mem.writeInt(u32, &word_bytes, word, .little);
        hasher.update(&word_bytes);
    }
    const digest64 = hasher.final();
    return @truncate(digest64 ^ (digest64 >> 32));
}

/// Returns the default concrete primitive type for an unresolved `untyped_int_ty` or `untyped_float_ty` in `group_ty`.
fn defaultConcreteForGroup(group_ty: TypeId, is_int: bool) TypeId {
    if (group_ty.isBuiltinGroup()) {
        const mask = TypeGroupMask.forBuiltinGroup(group_ty);
        if (is_int) {
            if (TypeGroupMask.containsPrimitive(mask, .i32_ty)) return .i32_ty;
            if (TypeGroupMask.containsPrimitive(mask, .u32_ty)) return .u32_ty;
            if (TypeGroupMask.containsPrimitive(mask, .u8_ty)) return .u8_ty;
            if (TypeGroupMask.containsPrimitive(mask, .i64_ty)) return .i64_ty;
        } else {
            if (TypeGroupMask.containsPrimitive(mask, .f64_ty)) return .f64_ty;
            if (TypeGroupMask.containsPrimitive(mask, .f32_ty)) return .f32_ty;
        }
    }
    return if (is_int) .i32_ty else .f64_ty;
}

/// Inclusive `[min_val, max_val]` 128-bit bounds and bit width of a primitive integer `TypeId`.
pub const PrimitiveIntBounds = struct {
    /// Minimum representable signed/unsigned value (`i128` domain).
    min_val: i128,
    /// Maximum representable signed/unsigned value (`i128` domain; capped at `i128` max for `u128`).
    max_val: i128,
    /// Bit width of the primitive integer (`8`, `16`, `32`, `64`, or `128`).
    bits: u16,
};

/// Returns the inclusive `[min_val, max_val]` 128-bit integer bounds of a primitive integer `TypeId`.
pub fn getPrimitiveIntBounds(prim_ty: TypeId) ?PrimitiveIntBounds {
    return switch (prim_ty) {
        .i8_ty => .{ .min_val = std.math.minInt(i8), .max_val = std.math.maxInt(i8), .bits = 8 },
        .i16_ty => .{ .min_val = std.math.minInt(i16), .max_val = std.math.maxInt(i16), .bits = 16 },
        .i32_ty => .{ .min_val = std.math.minInt(i32), .max_val = std.math.maxInt(i32), .bits = 32 },
        .i64_ty, .isize_ty => .{ .min_val = std.math.minInt(i64), .max_val = std.math.maxInt(i64), .bits = 64 },
        .i128_ty => .{ .min_val = std.math.minInt(i128), .max_val = std.math.maxInt(i128), .bits = 128 },
        .u8_ty => .{ .min_val = 0, .max_val = std.math.maxInt(u8), .bits = 8 },
        .u16_ty => .{ .min_val = 0, .max_val = std.math.maxInt(u16), .bits = 16 },
        .u32_ty => .{ .min_val = 0, .max_val = std.math.maxInt(u32), .bits = 32 },
        .u64_ty, .usize_ty => .{ .min_val = 0, .max_val = std.math.maxInt(u64), .bits = 64 },
        .u128_ty => .{ .min_val = 0, .max_val = std.math.maxInt(i128), .bits = 128 },
        else => null,
    };
}

/// Returns the target-aware bit width of a primitive integer `TypeId` (`32` on `wasm32`, `64` on 64-bit for `usize`/`isize`).
pub fn getTargetPrimitiveIntBits(prim_ty: TypeId, target_layout: TargetLayout) ?u16 {
    if (prim_ty == .usize_ty or prim_ty == .isize_ty) {
        return @as(u16, target_layout.ptr_byte_size) * 8;
    }
    if (getPrimitiveIntBounds(prim_ty)) |bounds| {
        return bounds.bits;
    }
    return null;
}

/// Returns the target-aware inclusive `[min_val, max_val]` 128-bit bounds of a primitive integer `TypeId`.
fn getTargetPrimitiveIntBounds(
    prim_ty: TypeId,
    target_layout: TargetLayout,
) ?PrimitiveIntBounds {
    if (target_layout.ptr_byte_size == 4) {
        if (prim_ty == .isize_ty) {
            return .{ .min_val = std.math.minInt(i32), .max_val = std.math.maxInt(i32), .bits = 32 };
        } else if (prim_ty == .usize_ty) {
            return .{ .min_val = 0, .max_val = std.math.maxInt(u32), .bits = 32 };
        }
    }
    return getPrimitiveIntBounds(prim_ty);
}

/// Returns `true` if `enum_sym` is a fieldless `enum` whose variant count equals `2^bit_width` with zero tag holes.
fn isExhaustiveFieldlessEnumForBits(
    sym_table: *const SymbolTable,
    enum_sym: SymbolRecord,
    bit_width: u16,
) bool {
    if (bit_width == 0 or bit_width >= 64 or enum_sym.target_scope.isNone()) return false;
    var variant_count: u64 = 0;
    for (sym_table.getScopeMembers(enum_sym.target_scope)) |mem_idx| {
        const mem_sym = sym_table.getSymbol(mem_idx).*;
        if (mem_sym.kind != .enum_variant_sym) continue;
        if (mem_sym.type_id != .unit_ty) return false;
        variant_count += 1;
    }
    return variant_count == (@as(u64, 1) << @intCast(bit_width));
}

/// Returns `true` if `arr_cst` is a repeat `[val; count]` array literal with a direct-child `;` separator.
pub fn hasShallowSemicolonInArrayCst(
    cst_arena: *const LosslessCstArena,
    token_buffer: *const TokenBuffer,
    arr_cst: CstNodeIndex,
) bool {
    if (arr_cst.isNone() or arr_cst.asInt() >= cst_arena.countNodes()) return false;
    const start_idx: usize = arr_cst.asInt();
    const rec = cst_arena.getNode(arr_cst);
    const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), cst_arena.countNodes());
    var cur = start_idx + 1;
    while (cur < end_idx) {
        const sub = cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
        if (sub.subtree_size <= 1 and !sub.token.isNone() and
            sub.token.asInt() < token_buffer.countTokens() and
            token_buffer.getToken(sub.token).kind == .semi)
        {
            return true;
        }
        cur += @max(@as(usize, sub.subtree_size), 1);
    }
    return false;
}

/// Returns `true` if `tup_cst` has a direct-child `,` separator (distinguishing `(pat,)` from `(pat)`).
pub fn hasShallowCommaInTupleCst(
    cst_arena: *const LosslessCstArena,
    token_buffer: *const TokenBuffer,
    tup_cst: CstNodeIndex,
) bool {
    if (tup_cst.isNone() or tup_cst.asInt() >= cst_arena.countNodes()) return false;
    const start_idx: usize = tup_cst.asInt();
    const rec = cst_arena.getNode(tup_cst);
    const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), cst_arena.countNodes());
    var cur = start_idx + 1;
    while (cur < end_idx) {
        const sub = cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
        if (sub.subtree_size <= 1 and !sub.token.isNone() and
            sub.token.asInt() < token_buffer.countTokens() and
            token_buffer.getToken(sub.token).kind == .comma)
        {
            return true;
        }
        cur += @max(@as(usize, sub.subtree_size), 1);
    }
    return false;
}

/// Returns `true` if `lexeme` begins with a raw string prefix (`r"…"` or `r#…"…`).
pub inline fn isRawStringLexeme(lexeme: []const u8) bool {
    return lexeme.len >= 2 and lexeme[0] == 'r' and (lexeme[1] == '"' or lexeme[1] == '#');
}

/// Returns `true` if `slice[pos..]` starts with at least `expected_hashes` `'#'` bytes.
inline fn hasAtLeastHashes(slice: []const u8, pos: usize, expected_hashes: usize) bool {
    if (pos + expected_hashes > slice.len) return false;
    var idx: usize = 0;
    while (idx < expected_hashes) : (idx += 1) {
        if (slice[pos + idx] != '#') return false;
    }
    return true;
}

/// Returns the inner verbatim slice of a raw string literal (`r"…"`, `r#"…"#`, `r"""…"""`, `r#"""…"""#`),
/// or `null` when standard `"…"` or when multi-line indentation stripping requires buffer allocation.
pub fn extractRawStringContent(lexeme: []const u8) ?[]const u8 {
    if (lexeme.len < 2 or lexeme[0] != 'r') return null;
    var hash_count: usize = 0;
    while (1 + hash_count < lexeme.len and lexeme[1 + hash_count] == '#') : (hash_count += 1) {}
    const quote_pos = 1 + hash_count;
    if (quote_pos >= lexeme.len or lexeme[quote_pos] != '"') return null;
    if (!hasAtLeastHashes(lexeme, lexeme.len -| hash_count, hash_count)) return null;

    var quote_run: usize = 0;
    while (quote_pos + quote_run < lexeme.len and lexeme[quote_pos + quote_run] == '"') : (quote_run += 1) {}
    const is_triple = quote_run >= 3 and
        !(hash_count > 0 and hasAtLeastHashes(lexeme, quote_pos + quote_run, hash_count)) and
        quote_pos + 6 + hash_count <= lexeme.len;

    if (!is_triple) {
        const prefix_len = quote_pos + 1;
        const suffix_len = 1 + hash_count;
        if (prefix_len + suffix_len > lexeme.len) return null;
        if (lexeme[lexeme.len - suffix_len] != '"') return null;
        return lexeme[prefix_len .. lexeme.len - suffix_len];
    }

    const close_quote_pos = lexeme.len - (3 + hash_count);
    if (lexeme[close_quote_pos] != '"' or
        lexeme[close_quote_pos + 1] != '"' or
        lexeme[close_quote_pos + 2] != '"')
    {
        return null;
    }
    var body_start = quote_pos + 3;
    while (body_start < close_quote_pos and (lexeme[body_start] == ' ' or lexeme[body_start] == '\t')) : (body_start += 1) {}
    if (body_start < close_quote_pos and lexeme[body_start] == '\r') body_start += 1;
    if (body_start >= close_quote_pos or lexeme[body_start] != '\n') return null;
    body_start += 1;

    var raw_body = lexeme[body_start..close_quote_pos];
    var dedent_cols: usize = 0;
    if (std.mem.lastIndexOfScalar(u8, raw_body, '\n')) |last_nl| {
        const closing_ws = raw_body[last_nl + 1 ..];
        for (closing_ws) |ws_byte| {
            if (ws_byte != ' ' and ws_byte != '\t') return null;
        }
        dedent_cols = closing_ws.len;
        const body_end = if (last_nl > 0 and raw_body[last_nl - 1] == '\r') last_nl - 1 else last_nl;
        raw_body = raw_body[0..body_end];
    } else {
        for (raw_body) |ws_byte| {
            if (ws_byte != ' ' and ws_byte != '\t') return null;
        }
        return "";
    }

    if (raw_body.len == 0) return "";
    if (std.mem.indexOfScalar(u8, raw_body, '\r') != null) return null;
    if (dedent_cols == 0) return raw_body;
    if (std.mem.indexOfScalar(u8, raw_body, '\n') == null) {
        if (raw_body.len < dedent_cols) return null;
        for (raw_body[0..dedent_cols]) |ws_byte| {
            if (ws_byte != ' ' and ws_byte != '\t') return null;
        }
        return raw_body[dedent_cols..];
    }
    return null;
}

/// Parses a single hexadecimal digit into `0..15`, or returns `null`.
fn parseHexNibble(hex_byte: u8) ?u8 {
    return switch (hex_byte) {
        '0'...'9' => hex_byte - '0',
        'a'...'f' => hex_byte - 'a' + 10,
        'A'...'F' => hex_byte - 'A' + 10,
        else => null,
    };
}

/// Decodes a character literal lexeme (`'a'`, `'\n'`, `'\x41'`, `'\u{1F600}'`) into its Unicode scalar value.
pub fn extractCharLiteralCodepoint(lexeme: []const u8) ?u21 {
    if (lexeme.len < 3 or lexeme[0] != '\'' or lexeme[lexeme.len - 1] != '\'') return null;
    const body = lexeme[1 .. lexeme.len - 1];
    if (body.len == 0) return null;
    if (body[0] != '\\') {
        const seq_len = std.unicode.utf8ByteSequenceLength(body[0]) catch return null;
        if (seq_len > body.len) return null;
        return std.unicode.utf8Decode(body[0..seq_len]) catch null;
    }
    if (body.len < 2) return null;
    return switch (body[1]) {
        'n' => '\n',
        'r' => '\r',
        't' => '\t',
        '0' => 0,
        '\\' => '\\',
        '\'' => '\'',
        '"' => '"',
        '{' => '{',
        '}' => '}',
        'x' => blk: {
            if (body.len < 4) break :blk null;
            const hi = parseHexNibble(body[2]) orelse break :blk null;
            const lo = parseHexNibble(body[3]) orelse break :blk null;
            break :blk @as(u21, (hi << 4) | lo);
        },
        'u' => blk: {
            if (body.len < 4 or body[2] != '{') break :blk null;
            const close_rel = std.mem.indexOfScalarPos(u8, body, 3, '}') orelse break :blk null;
            const hex_digits = body[3..close_rel];
            if (hex_digits.len == 0 or hex_digits.len > 6) break :blk null;
            var scalar_val: u32 = 0;
            for (hex_digits) |digit_byte| {
                const nib = parseHexNibble(digit_byte) orelse break :blk null;
                scalar_val = (scalar_val << 4) | nib;
            }
            if (scalar_val > 0x10FFFF or !std.unicode.utf8ValidCodepoint(@intCast(scalar_val))) break :blk null;
            break :blk @intCast(scalar_val);
        },
        else => @as(u21, body[1]),
    };
}

/// Unescapes a non-raw string literal segment (`\n`, `\r`, `\t`, `\0`, `\\`, `\"`, `\'`, `\{`, `\}`, `\xHH`, `\u{…}`).
pub fn decodeStandardStringSegment(allocator: std.mem.Allocator, raw_seg: []const u8) ![]u8 {
    var out_buf: std.ArrayListUnmanaged(u8) = .empty;
    errdefer out_buf.deinit(allocator);
    try out_buf.ensureTotalCapacity(allocator, raw_seg.len);

    var cursor: usize = 0;
    while (cursor < raw_seg.len) {
        if (raw_seg[cursor] == '\\' and cursor + 1 < raw_seg.len) {
            const esc = raw_seg[cursor + 1];
            switch (esc) {
                'n' => {
                    try out_buf.append(allocator, '\n');
                    cursor += 2;
                },
                'r' => {
                    try out_buf.append(allocator, '\r');
                    cursor += 2;
                },
                't' => {
                    try out_buf.append(allocator, '\t');
                    cursor += 2;
                },
                '0' => {
                    try out_buf.append(allocator, 0);
                    cursor += 2;
                },
                '\\', '"', '\'', '{', '}' => {
                    try out_buf.append(allocator, esc);
                    cursor += 2;
                },
                '\n' => {
                    cursor += 2;
                },
                '\r' => {
                    cursor += if (cursor + 2 < raw_seg.len and raw_seg[cursor + 2] == '\n') 3 else 2;
                },
                'x' => {
                    if (cursor + 3 < raw_seg.len) {
                        if (parseHexNibble(raw_seg[cursor + 2])) |hi| {
                            if (parseHexNibble(raw_seg[cursor + 3])) |lo| {
                                try out_buf.append(allocator, (hi << 4) | lo);
                                cursor += 4;
                                continue;
                            }
                        }
                    }
                    try out_buf.append(allocator, esc);
                    cursor += 2;
                },
                'u' => {
                    if (cursor + 3 < raw_seg.len and raw_seg[cursor + 2] == '{') {
                        if (std.mem.indexOfScalarPos(u8, raw_seg, cursor + 3, '}')) |close_pos| {
                            const hex_digits = raw_seg[cursor + 3 .. close_pos];
                            if (hex_digits.len > 0 and hex_digits.len <= 6) {
                                var scalar_val: u32 = 0;
                                var is_valid_hex = true;
                                for (hex_digits) |digit_byte| {
                                    if (parseHexNibble(digit_byte)) |nib| {
                                        scalar_val = (scalar_val << 4) | nib;
                                    } else {
                                        is_valid_hex = false;
                                        break;
                                    }
                                }
                                if (is_valid_hex and scalar_val <= 0x10FFFF and
                                    std.unicode.utf8ValidCodepoint(@intCast(scalar_val)))
                                {
                                    var utf8_bytes: [4]u8 = undefined;
                                    const encoded_len = std.unicode.utf8Encode(
                                        @intCast(scalar_val),
                                        &utf8_bytes,
                                    ) catch 0;
                                    try out_buf.appendSlice(allocator, utf8_bytes[0..encoded_len]);
                                    cursor = close_pos + 1;
                                    continue;
                                }
                            }
                        }
                    }
                    try out_buf.append(allocator, esc);
                    cursor += 2;
                },
                else => {
                    try out_buf.append(allocator, esc);
                    cursor += 2;
                },
            }
            continue;
        }
        if ((raw_seg[cursor] == '{' or raw_seg[cursor] == '}') and
            cursor + 1 < raw_seg.len and raw_seg[cursor + 1] == raw_seg[cursor])
        {
            try out_buf.append(allocator, raw_seg[cursor]);
            cursor += 2;
            continue;
        }
        try out_buf.append(allocator, raw_seg[cursor]);
        cursor += 1;
    }
    return out_buf.toOwnedSlice(allocator);
}

/// Byte offsets of an unescaped `{expr}` interpolation segment within a standard string body.
pub const InterpolationSegment = struct {
    /// Byte offset of the `{` delimiter inside `body`.
    open_brace: usize,
    /// Start byte offset of `expr` (`open_brace + 1`).
    expr_start: usize,
    /// End byte offset of `expr` (position of matching `}`).
    expr_end: usize,
    /// Byte offset immediately following matching `}`.
    after_close: usize,
};

/// Advances past a backslash escape starting at `slash_pos` (including braced `\u{…}`).
fn advancePastStringEscape(body: []const u8, slash_pos: usize) usize {
    if (slash_pos + 1 >= body.len) return body.len;
    if (body[slash_pos + 1] == 'u' and slash_pos + 2 < body.len and body[slash_pos + 2] == '{') {
        var scan_idx = slash_pos + 3;
        while (scan_idx < body.len and body[scan_idx] != '}') : (scan_idx += 1) {}
        return if (scan_idx < body.len) scan_idx + 1 else body.len;
    }
    return slash_pos + 2;
}

/// Skips a raw string literal starting after `'r'` (`after_r_pos`) inside an interpolation `{expr}` hole.
fn skipRawStringInsideHole(slice: []const u8, after_r_pos: usize) usize {
    var cursor = after_r_pos;
    var raw_hashes: usize = 0;
    while (cursor < slice.len and slice[cursor] == '#') : (cursor += 1) {
        raw_hashes += 1;
    }
    if (cursor >= slice.len or slice[cursor] != '"') return cursor;
    var quote_run: usize = 0;
    while (cursor + quote_run < slice.len and slice[cursor + quote_run] == '"') : (quote_run += 1) {}
    const is_triple = quote_run >= 3 and
        !(raw_hashes > 0 and hasAtLeastHashes(slice, cursor + quote_run, raw_hashes));
    cursor += if (is_triple) 3 else 1;

    while (cursor < slice.len) {
        if (slice[cursor] == '"') {
            if (is_triple) {
                if (cursor + 2 < slice.len and
                    slice[cursor + 1] == '"' and
                    slice[cursor + 2] == '"' and
                    hasAtLeastHashes(slice, cursor + 3, raw_hashes))
                {
                    return cursor + 3 + raw_hashes;
                }
                cursor += 1;
                continue;
            }
            if (hasAtLeastHashes(slice, cursor + 1, raw_hashes)) {
                return cursor + 1 + raw_hashes;
            }
        }
        cursor += 1;
    }
    return slice.len;
}

/// Skips a standard or byte string (`"…"` / `"""…"""`) starting at opening `"` inside an `{expr}` hole.
fn skipQuotedStringInsideHole(slice: []const u8, open_quote_pos: usize, is_interp_allowed: bool) usize {
    const is_triple = open_quote_pos + 2 < slice.len and
        slice[open_quote_pos + 1] == '"' and
        slice[open_quote_pos + 2] == '"';
    var cursor = open_quote_pos + (if (is_triple) @as(usize, 3) else 1);
    while (cursor < slice.len) {
        if (slice[cursor] == '\\') {
            cursor = advancePastStringEscape(slice, cursor);
            continue;
        }
        if (slice[cursor] == '"') {
            if (is_triple) {
                if (cursor + 2 < slice.len and slice[cursor + 1] == '"' and slice[cursor + 2] == '"') {
                    return cursor + 3;
                }
                cursor += 1;
                continue;
            }
            return cursor + 1;
        }
        if (is_interp_allowed and slice[cursor] == '{') {
            if (cursor + 1 < slice.len and slice[cursor + 1] == '{') {
                cursor += 2;
                continue;
            }
            if (scanNextInterpolationSegment(slice, cursor)) |nested_seg| {
                cursor = nested_seg.after_close;
                continue;
            }
            return slice.len;
        }
        cursor += 1;
    }
    return slice.len;
}

/// Skips a nested string, byte-string, char/byte literal, or comment starting at `cursor` inside `{expr}`, or returns `null`.
fn trySkipLiteralOrCommentInHole(slice: []const u8, cursor: usize, expr_floor: usize) ?usize {
    const cur_byte = slice[cursor];
    const is_word_start = cursor <= expr_floor or
        (!std.ascii.isAlphanumeric(slice[cursor - 1]) and slice[cursor - 1] != '_');
    if (cur_byte == '"') {
        return skipQuotedStringInsideHole(slice, cursor, true);
    }
    if (cur_byte == 'r' and is_word_start and cursor + 1 < slice.len and
        (slice[cursor + 1] == '"' or slice[cursor + 1] == '#'))
    {
        return skipRawStringInsideHole(slice, cursor + 1);
    }
    if (cur_byte == 'b' and is_word_start and cursor + 1 < slice.len) {
        if (slice[cursor + 1] == '"') {
            return skipQuotedStringInsideHole(slice, cursor + 1, false);
        }
        if (slice[cursor + 1] == '\'') {
            var char_cur = cursor + 2;
            while (char_cur < slice.len and slice[char_cur] != '\'') {
                char_cur += if (slice[char_cur] == '\\' and char_cur + 1 < slice.len) 2 else 1;
            }
            return if (char_cur < slice.len) char_cur + 1 else slice.len;
        }
        if (slice[cursor + 1] == 'r' and cursor + 2 < slice.len and
            (slice[cursor + 2] == '"' or slice[cursor + 2] == '#'))
        {
            return skipRawStringInsideHole(slice, cursor + 2);
        }
    }
    if (cur_byte == '\'') {
        var char_cur = cursor + 1;
        while (char_cur < slice.len and slice[char_cur] != '\'') {
            char_cur += if (slice[char_cur] == '\\' and char_cur + 1 < slice.len) 2 else 1;
        }
        return if (char_cur < slice.len) char_cur + 1 else slice.len;
    }
    if (cur_byte == '/' and cursor + 1 < slice.len and slice[cursor + 1] == '/') {
        var line_cur = cursor + 2;
        while (line_cur < slice.len and slice[line_cur] != '\n') : (line_cur += 1) {}
        return line_cur;
    }
    if (cur_byte == '/' and cursor + 1 < slice.len and slice[cursor + 1] == '*') {
        var blk_cur = cursor + 2;
        var comment_depth: u32 = 1;
        while (blk_cur + 1 < slice.len and comment_depth > 0) {
            if (slice[blk_cur] == '/' and slice[blk_cur + 1] == '*') {
                comment_depth += 1;
                blk_cur += 2;
            } else if (slice[blk_cur] == '*' and slice[blk_cur + 1] == '/') {
                comment_depth -= 1;
                blk_cur += 2;
            } else {
                blk_cur += 1;
            }
        }
        return if (comment_depth == 0) blk_cur else slice.len;
    }
    return null;
}

/// Scans `body[start_pos..]` (inside `"…"`) for the next unescaped `{expr}` segment, respecting nested quotes/comments.
pub fn scanNextInterpolationSegment(body: []const u8, start_pos: usize) ?InterpolationSegment {
    var cursor = start_pos;
    while (cursor < body.len) {
        if (body[cursor] == '\\') {
            cursor = advancePastStringEscape(body, cursor);
            continue;
        }
        if ((body[cursor] == '{' or body[cursor] == '}') and
            cursor + 1 < body.len and body[cursor + 1] == body[cursor])
        {
            cursor += 2;
            continue;
        }
        if (body[cursor] != '{') {
            cursor += 1;
            continue;
        }
        const open_brace = cursor;
        const expr_start = cursor + 1;
        cursor += 1;
        var brace_depth: u32 = 1;
        while (cursor < body.len and brace_depth > 0) {
            if (trySkipLiteralOrCommentInHole(body, cursor, expr_start)) |next_cursor| {
                cursor = next_cursor;
                continue;
            }
            const cur_byte = body[cursor];
            if (cur_byte == '{') {
                brace_depth += 1;
                cursor += 1;
            } else if (cur_byte == '}') {
                brace_depth -= 1;
                if (brace_depth == 0) {
                    return .{
                        .open_brace = open_brace,
                        .expr_start = expr_start,
                        .expr_end = cursor,
                        .after_close = cursor + 1,
                    };
                }
                cursor += 1;
            } else {
                cursor += 1;
            }
        }
        return null;
    }
    return null;
}

/// Splits an interpolation hole `{expr[=][:spec]}` into its expression, optional `=` debug prefix, and optional `:spec` (`SE-12`).
pub fn splitInterpolationHole(raw_hole: []const u8) struct {
    expr_slice: []const u8,
    debug_prefix_slice: []const u8,
    has_debug_eq: bool,
    spec_slice: ?[]const u8,
    spec_offset: usize,
} {
    var paren_depth: u32 = 0;
    var bracket_depth: u32 = 0;
    var brace_depth: u32 = 0;
    var colon_idx: ?usize = null;
    var cursor: usize = 0;
    while (cursor < raw_hole.len) {
        if (trySkipLiteralOrCommentInHole(raw_hole, cursor, 0)) |next_cursor| {
            cursor = next_cursor;
            continue;
        }
        const cur_byte = raw_hole[cursor];
        switch (cur_byte) {
            '(' => paren_depth += 1,
            ')' => paren_depth -|= 1,
            '[' => bracket_depth += 1,
            ']' => bracket_depth -|= 1,
            '{' => brace_depth += 1,
            '}' => brace_depth -|= 1,
            ':' => {
                if (paren_depth == 0 and bracket_depth == 0 and brace_depth == 0) {
                    const has_next_eq_or_colon = cursor + 1 < raw_hole.len and
                        (raw_hole[cursor + 1] == '=' or raw_hole[cursor + 1] == ':');
                    const has_prev_colon = cursor > 0 and raw_hole[cursor - 1] == ':';
                    if (!has_next_eq_or_colon and !has_prev_colon) {
                        colon_idx = cursor;
                        break;
                    }
                }
            },
            else => {},
        }
        cursor += 1;
    }

    const pre_spec = if (colon_idx) |c_idx| raw_hole[0..c_idx] else raw_hole;
    const spec_slice: ?[]const u8 = if (colon_idx) |c_idx| raw_hole[c_idx + 1 ..] else null;
    const spec_offset: usize = if (colon_idx) |c_idx| c_idx + 1 else raw_hole.len;

    const trimmed_right = std.mem.trimEnd(u8, pre_spec, " \t\r\n");
    if (trimmed_right.len > 0 and trimmed_right[trimmed_right.len - 1] == '=') {
        const is_compound_op = trimmed_right.len >= 2 and switch (trimmed_right[trimmed_right.len - 2]) {
            '=', '!', '<', '>', ':', '+', '-', '*', '/', '%', '&', '|', '^' => true,
            else => false,
        };
        if (!is_compound_op) {
            return .{
                .expr_slice = trimmed_right[0 .. trimmed_right.len - 1],
                .debug_prefix_slice = std.mem.trimStart(u8, trimmed_right, " \t\r\n"),
                .has_debug_eq = true,
                .spec_slice = spec_slice,
                .spec_offset = spec_offset,
            };
        }
    }

    return .{
        .expr_slice = pre_spec,
        .debug_prefix_slice = "",
        .has_debug_eq = false,
        .spec_slice = spec_slice,
        .spec_offset = spec_offset,
    };
}

/// Parses an integer literal lexeme (handling `0x`, `0b`, `0o`, `_`, and type suffixes) into `i128` + optional suffix `TypeId`.
pub fn extractIntLiteralValue(raw_lexeme: []const u8) ?struct {
    value: i128,
    magnitude: u128 = 0,
    is_above_i128_max: bool = false,
    suffix_ty: ?TypeId,
} {
    if (raw_lexeme.len == 0) return null;
    var is_negative = false;
    var slice = raw_lexeme;
    if (slice[0] == '-') {
        is_negative = true;
        slice = slice[1..];
    } else if (slice[0] == '+') {
        slice = slice[1..];
    }
    if (slice.len == 0) return null;

    var base: u8 = 10;
    var suffix_ty: ?TypeId = null;
    if (lexer.extractNumericSuffix(slice)) |parsed_num| {
        if (parsed_num.is_float_syntax) return null;
        base = parsed_num.radix;
        suffix_ty = parsed_num.suffix_type;
        slice = parsed_num.digits_slice;
        if (base != 10 and slice.len >= 2) {
            slice = slice[2..];
        }
    } else |_| {
        if (slice.len >= 2 and slice[0] == '0') {
            if (slice[1] == 'x' or slice[1] == 'X') {
                base = 16;
                slice = slice[2..];
            } else if (slice[1] == 'b' or slice[1] == 'B') {
                base = 2;
                slice = slice[2..];
            } else if (slice[1] == 'o' or slice[1] == 'O') {
                base = 8;
                slice = slice[2..];
            }
        }
    }

    var magnitude: u128 = 0;
    var has_digits = false;
    for (slice) |ch| {
        if (ch == '_') continue;
        const digit: u8 = switch (ch) {
            '0'...'9' => ch - '0',
            'a'...'f' => ch - 'a' + 10,
            'A'...'F' => ch - 'A' + 10,
            else => return null,
        };
        if (digit >= base) return null;
        has_digits = true;
        magnitude = std.math.mul(u128, magnitude, base) catch return null;
        magnitude = std.math.add(u128, magnitude, digit) catch return null;
    }
    if (!has_digits) return null;

    if (is_negative) {
        const min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;
        if (magnitude > min_abs) return null;
        if (magnitude == min_abs) {
            return .{
                .value = std.math.minInt(i128),
                .magnitude = magnitude,
                .is_above_i128_max = false,
                .suffix_ty = suffix_ty,
            };
        }
        return .{
            .value = -@as(i128, @intCast(magnitude)),
            .magnitude = magnitude,
            .is_above_i128_max = false,
            .suffix_ty = suffix_ty,
        };
    }
    if (magnitude > @as(u128, @intCast(std.math.maxInt(i128)))) {
        return .{
            .value = std.math.maxInt(i128),
            .magnitude = magnitude,
            .is_above_i128_max = true,
            .suffix_ty = suffix_ty,
        };
    }
    return .{
        .value = @intCast(magnitude),
        .magnitude = magnitude,
        .is_above_i128_max = false,
        .suffix_ty = suffix_ty,
    };
}

/// Stack-backed slice writer used by `InternPool.formatType` with zero heap allocations.
const SliceBufWriter = struct {
    buf: []u8,
    pos: usize = 0,

    /// Appends `bytes` into `self.buf`, truncating if capacity is exceeded.
    fn writeAll(self: *SliceBufWriter, bytes: []const u8) void {
        if (self.pos >= self.buf.len) return;
        const avail = self.buf.len - self.pos;
        const n = @min(avail, bytes.len);
        @memcpy(self.buf[self.pos .. self.pos + n], bytes[0..n]);
        self.pos += n;
    }

    /// Formats `args` with `fmt_str` into the remaining capacity of `self.buf`.
    fn print(self: *SliceBufWriter, comptime fmt_str: []const u8, args: anytype) void {
        if (self.pos >= self.buf.len) return;
        const written = std.fmt.bufPrint(self.buf[self.pos..], fmt_str, args) catch {
            self.pos = self.buf.len;
            return;
        };
        self.pos += written.len;
    }
};

/// Packs `(src_err_ty, dst_err_ty)` into a 64-bit key for $O(1)$ `FromError` conversion lookup.
inline fn packFromErrorPair(src_err_ty: TypeId, dst_err_ty: TypeId) u64 {
    return (@as(u64, src_err_ty.toU32()) << 32) | @as(u64, dst_err_ty.toU32());
}

/// Packs `(target_ty, trait_sym_idx)` into a 64-bit key for $O(1)$ `@implements` / `@derive` lookup.
pub inline fn packTraitImplPair(target_ty: TypeId, trait_sym_idx: SymbolIndex) u64 {
    return (@as(u64, target_ty.toU32()) << 32) | @as(u64, trait_sym_idx.asInt());
}

/// Converts a `snake_case` identifier into `PascalCase` inside `out_buf` with zero heap allocations.
fn toPascalCase(snake_name: []const u8, out_buf: []u8) []const u8 {
    var write_pos: usize = 0;
    var is_cap_next = true;
    for (snake_name) |byte_val| {
        if (byte_val == '_') {
            is_cap_next = true;
            continue;
        }
        if (write_pos >= out_buf.len) break;
        out_buf[write_pos] = if (is_cap_next and byte_val >= 'a' and byte_val <= 'z')
            byte_val - ('a' - 'A')
        else
            byte_val;
        write_pos += 1;
        is_cap_next = false;
    }
    return out_buf[0..write_pos];
}

/// Fast $O(1)$ layout resolver for primitives, references, raw pointers, slices, functions, and closures (`null` for composites).
inline fn tryComputeFastTypeLayout(
    pool: *const InternPool,
    type_id: TypeId,
    target_layout: TargetLayout,
) ?TypeLayout {
    switch (type_id) {
        .unit_ty, .never_ty, .err_ty => {
            return .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
        },
        .opaque_ty => {
            return .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0, .is_sized = false };
        },
        .bool_ty, .i8_ty, .u8_ty => {
            return .{ .byte_size = 1, .align_bytes = 1, .align_log2 = 0 };
        },
        .i16_ty, .u16_ty => {
            return .{ .byte_size = 2, .align_bytes = 2, .align_log2 = 1 };
        },
        .i32_ty, .u32_ty, .f32_ty, .char_ty, .untyped_int_ty => {
            return .{ .byte_size = 4, .align_bytes = 4, .align_log2 = 2 };
        },
        .fmt_spec_ty => {
            return .{ .byte_size = 8, .align_bytes = 4, .align_log2 = 2 };
        },
        .i64_ty, .u64_ty, .f64_ty, .untyped_float_ty => {
            return .{ .byte_size = 8, .align_bytes = 8, .align_log2 = 3 };
        },
        .i128_ty, .u128_ty => {
            return .{ .byte_size = 16, .align_bytes = 16, .align_log2 = 4 };
        },
        .isize_ty, .usize_ty, .source_loc_ty, .task_group_base_ty, .task_handle_base_ty => {
            return .{
                .byte_size = target_layout.ptr_byte_size,
                .align_bytes = target_layout.ptrAlignBytes(),
                .align_log2 = target_layout.ptr_align_log2,
            };
        },
        .str_ty, .bencher_ty => {
            return .{
                .byte_size = @as(u64, target_layout.ptr_byte_size) * 2,
                .align_bytes = target_layout.ptrAlignBytes(),
                .align_log2 = target_layout.ptr_align_log2,
            };
        },
        .fmt_args_ty => {
            return .{
                .byte_size = @as(u64, target_layout.ptr_byte_size) * 4,
                .align_bytes = target_layout.ptrAlignBytes(),
                .align_log2 = target_layout.ptr_align_log2,
            };
        },
        else => {},
    }
    if (pool.isTaskGroupType(type_id) or pool.isTaskHandleType(type_id)) {
        return .{
            .byte_size = target_layout.ptr_byte_size,
            .align_bytes = target_layout.ptrAlignBytes(),
            .align_log2 = target_layout.ptr_align_log2,
        };
    }

    const node = pool.getNode(type_id);
    return switch (node.tag) {
        .ref_ty, .mut_ref_ty, .raw_ptr_ty, .fn_ty => .{
            .byte_size = target_layout.ptr_byte_size,
            .align_bytes = target_layout.ptrAlignBytes(),
            .align_log2 = target_layout.ptr_align_log2,
        },
        .slice_ty, .soa_slice_ty => .{
            .byte_size = @as(u64, target_layout.ptr_byte_size) * 2,
            .align_bytes = target_layout.ptrAlignBytes(),
            .align_log2 = target_layout.ptr_align_log2,
        },
        .closure_ty => blk: {
            const word_count: u64 = if (pool.getFnSignatureView(type_id)) |sig_view|
                (if (sig_view.capture_tier != .copy_tier or sig_view.has_linear_capture) @as(u64, 3) else @as(u64, 2))
            else
                2;
            break :blk .{
                .byte_size = @as(u64, target_layout.ptr_byte_size) * word_count,
                .align_bytes = target_layout.ptrAlignBytes(),
                .align_log2 = target_layout.ptr_align_log2,
            };
        },
        else => null,
    };
}

/// Depth-bounded helper (`MAX_TYPE_DEPTH`) for `computeTypeLayoutWithPool` with generic nominal substitution `subst`.
fn computeTypeLayoutBounded(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_type_id: TypeId,
    target_layout: TargetLayout,
    subst: *const NominalTypeSubst,
    depth: u32,
) TypeLayout {
    const type_id = subst.resolve(raw_type_id);
    if (depth >= MAX_TYPE_DEPTH) {
        return .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0, .is_sized = false };
    }
    if (tryComputeFastTypeLayout(pool, type_id, target_layout)) |fast_layout| {
        return fast_layout;
    }
    var memo: LayoutNicheMemo = .{};
    return computeTypeLayoutBoundedMemo(pool, sym_table, type_id, target_layout, subst, depth, &memo);
}

/// Memoized depth-bounded `TypeLayout` walker sharing `memo` across layout, niche, and sum queries.
fn computeTypeLayoutBoundedMemo(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_type_id: TypeId,
    target_layout: TargetLayout,
    subst: *const NominalTypeSubst,
    depth: u32,
    memo: *LayoutNicheMemo,
) TypeLayout {
    const type_id = subst.resolve(raw_type_id);
    if (depth >= MAX_TYPE_DEPTH) {
        return .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0, .is_sized = false };
    }
    if (tryComputeFastTypeLayout(pool, type_id, target_layout)) |fast_layout| {
        return fast_layout;
    }
    const maybe_key = LayoutNicheKey.fromQuery(type_id, subst, depth);
    if (maybe_key) |memo_key| {
        if (memo.lookupLayout(memo_key)) |cached_layout| return cached_layout;
    }

    const node = pool.getNode(type_id);
    const computed_layout: TypeLayout = switch (node.tag) {
        .future_ty => blk: {
            const out_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            const hdr_bytes: u64 = @as(u64, target_layout.ptr_byte_size) * 4;
            const fut_log2 = @max(target_layout.ptr_align_log2, out_layout.align_log2);
            const fut_align = @as(u32, 1) << @intCast(fut_log2);
            break :blk .{
                .byte_size = alignUpU64(hdr_bytes +| out_layout.byte_size, fut_align),
                .align_bytes = fut_align,
                .align_log2 = fut_log2,
                .is_sized = out_layout.is_sized,
            };
        },
        .distinct_ty, .bit_field_ty => computeTypeLayoutBoundedMemo(
            pool,
            sym_table,
            TypeId.fromInt(node.lhs),
            target_layout,
            subst,
            depth + 1,
            memo,
        ),
        .refined_ty => computeTypeLayoutBoundedMemo(
            pool,
            sym_table,
            TypeId.fromInt(node.rhs),
            target_layout,
            subst,
            depth + 1,
            memo,
        ),
        .array_ty => blk: {
            const elem_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0 or !elem_layout.is_sized) {
                break :blk .{
                    .byte_size = 0,
                    .align_bytes = elem_layout.align_bytes,
                    .align_log2 = elem_layout.align_log2,
                    .is_sized = false,
                };
            }
            break :blk .{
                .byte_size = elem_layout.byte_size *| @as(u64, node.rhs),
                .align_bytes = elem_layout.align_bytes,
                .align_log2 = elem_layout.align_log2,
            };
        },
        .soa_array_ty => blk: {
            const elem_raw = subst.resolve(TypeId.fromInt(node.lhs));
            const elem_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                elem_raw,
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0 or !elem_layout.is_sized) {
                const unsized_log2 = @max(elem_layout.align_log2, target_layout.simd_align_log2);
                break :blk .{
                    .byte_size = 0,
                    .align_bytes = @as(u32, 1) << @intCast(unsized_log2),
                    .align_log2 = unsized_log2,
                    .is_sized = false,
                };
            }
            const elem_unwrapped = pool.unwrapUnderlyingType(elem_raw);
            const elem_node = pool.getNode(elem_unwrapped);
            if (elem_node.tag != .struct_ty) {
                const arr_log2 = @max(elem_layout.align_log2, target_layout.simd_align_log2);
                const arr_align = @as(u32, 1) << @intCast(arr_log2);
                break :blk .{
                    .byte_size = alignUpU64(elem_layout.byte_size *| @as(u64, node.rhs), arr_align),
                    .align_bytes = arr_align,
                    .align_log2 = arr_log2,
                };
            }
            const sym_idx = SymbolIndex.fromInt(elem_node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                break :blk .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
            }
            const st_sym = sym_table.getSymbol(sym_idx).*;
            if (st_sym.target_scope.isNone()) {
                break :blk .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
            }
            const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, elem_unwrapped, st_sym, subst);
            const active_subst = if (child_subst.len > 0) &child_subst else subst;
            var cur_offset: u64 = 0;
            var max_align_log2: u8 = 0;
            var has_any_field = false;
            var is_all_sized = true;
            for (sym_table.getScopeMembers(st_sym.target_scope)) |mem_idx| {
                const mem_sym = sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind != .field_sym) continue;
                has_any_field = true;
                const field_layout = computeTypeLayoutBoundedMemo(
                    pool,
                    sym_table,
                    mem_sym.type_id,
                    target_layout,
                    active_subst,
                    depth + 1,
                    memo,
                );
                if (!field_layout.is_sized) is_all_sized = false;
                const col_log2 = @max(field_layout.align_log2, target_layout.simd_align_log2);
                const col_align = @as(u32, 1) << @intCast(col_log2);
                max_align_log2 = @max(max_align_log2, col_log2);
                cur_offset = alignUpU64(cur_offset, col_align) +| (field_layout.byte_size *| @as(u64, node.rhs));
            }
            if (!has_any_field) {
                break :blk .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
            }
            const max_align_bytes = @as(u32, 1) << @intCast(max_align_log2);
            break :blk .{
                .byte_size = if (node.rhs == 0) 0 else alignUpU64(cur_offset, max_align_bytes),
                .align_bytes = max_align_bytes,
                .align_log2 = max_align_log2,
                .is_sized = is_all_sized,
            };
        },
        .tuple_ty => blk: {
            const elems = pool.getTupleElements(type_id);
            var rank_mask: u64 = 0;
            var max_align_log2: u8 = 0;
            var is_all_sized = true;
            for (elems) |raw_elem| {
                const elem_layout = computeTypeLayoutBoundedMemo(
                    pool,
                    sym_table,
                    TypeId.fromInt(raw_elem),
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                );
                if (!elem_layout.is_sized) is_all_sized = false;
                if (elem_layout.align_log2 > max_align_log2) max_align_log2 = elem_layout.align_log2;
                const has_niche = computeLeafNicheBoundedMemo(
                    pool,
                    sym_table,
                    TypeId.fromInt(raw_elem),
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                ).kind != .none;
                const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
                rank_mask |= (@as(u64, 1) << rank);
            }
            var cur_offset: u64 = 0;
            while (rank_mask != 0) {
                const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                rank_mask &= ~(@as(u64, 1) << top_rank);
                for (elems) |raw_elem| {
                    const elem_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        TypeId.fromInt(raw_elem),
                        target_layout,
                        subst,
                        depth + 1,
                        memo,
                    );
                    const has_niche = computeLeafNicheBoundedMemo(
                        pool,
                        sym_table,
                        TypeId.fromInt(raw_elem),
                        target_layout,
                        subst,
                        depth + 1,
                        memo,
                    ).kind != .none;
                    const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) |
                        @intFromBool(has_niche);
                    if (rank != top_rank) continue;
                    cur_offset = alignUpU64(cur_offset, elem_layout.align_bytes) +| elem_layout.byte_size;
                }
            }
            const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
            break :blk .{
                .byte_size = alignUpU64(cur_offset, max_align_bytes),
                .align_bytes = max_align_bytes,
                .align_log2 = max_align_log2,
                .is_sized = is_all_sized,
            };
        },
        .struct_ty => blk: {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                break :blk .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
            }
            const struct_sym = sym_table.getSymbol(sym_idx).*;
            if (struct_sym.flags.is_builtin and std.mem.eql(u8, struct_sym.name_text, "Context")) {
                const ptr_align = target_layout.ptrAlignBytes();
                const ctx_size: u64 = if (target_layout.ptr_byte_size >= 8)
                    ContextFieldLayout.BYTE_SIZE_64
                else
                    @as(u64, target_layout.ptr_byte_size) * ContextFieldLayout.CANONICAL_FIELDS.len;
                break :blk .{
                    .byte_size = ctx_size,
                    .align_bytes = ptr_align,
                    .align_log2 = target_layout.ptr_align_log2,
                };
            }
            if (struct_sym.target_scope.isNone()) {
                var empty_log2: u8 = 0;
                if (struct_sym.contract_flags.is_cache_aligned) {
                    empty_log2 = @max(empty_log2, target_layout.cache_line_align_log2);
                }
                if (struct_sym.explicit_align_log2_plus1 > 0) {
                    empty_log2 = @max(empty_log2, struct_sym.explicit_align_log2_plus1 - 1);
                }
                break :blk .{
                    .byte_size = 0,
                    .align_bytes = @as(u32, 1) << @intCast(empty_log2),
                    .align_log2 = empty_log2,
                };
            }
            const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, type_id, struct_sym, subst);
            const active_subst = if (child_subst.len > 0) &child_subst else subst;
            const is_packed = struct_sym.contract_flags.is_packed;
            const is_decl_order = is_packed or struct_sym.contract_flags.is_repr_c;
            const members = sym_table.getScopeMembers(struct_sym.target_scope);
            var cur_offset: u64 = 0;
            var max_align_log2: u8 = 0;
            var is_all_sized = true;
            if (is_decl_order) {
                for (members) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    const field_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    if (!field_layout.is_sized) is_all_sized = false;
                    if (!is_packed and field_layout.align_log2 > max_align_log2) {
                        max_align_log2 = field_layout.align_log2;
                    }
                    const eff_align: u32 = if (is_packed) 1 else field_layout.align_bytes;
                    cur_offset = alignUpU64(cur_offset, eff_align) +| field_layout.byte_size;
                }
            } else {
                var rank_mask: u64 = 0;
                for (members) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    const field_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    if (!field_layout.is_sized) is_all_sized = false;
                    if (field_layout.align_log2 > max_align_log2) max_align_log2 = field_layout.align_log2;
                    const has_niche = computeLeafNicheBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    ).kind != .none;
                    const rank: u6 = (@as(u6, @intCast(@min(field_layout.align_log2, 30))) << 1) |
                        @intFromBool(has_niche);
                    rank_mask |= (@as(u64, 1) << rank);
                }
                while (rank_mask != 0) {
                    const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                    rank_mask &= ~(@as(u64, 1) << top_rank);
                    for (members) |mem_idx| {
                        const mem_sym = sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        const field_layout = computeTypeLayoutBoundedMemo(
                            pool,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                            memo,
                        );
                        const has_niche = computeLeafNicheBoundedMemo(
                            pool,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                            memo,
                        ).kind != .none;
                        const rank: u6 = (@as(u6, @intCast(@min(field_layout.align_log2, 30))) << 1) |
                            @intFromBool(has_niche);
                        if (rank != top_rank) continue;
                        cur_offset = alignUpU64(cur_offset, field_layout.align_bytes) +| field_layout.byte_size;
                    }
                }
            }
            if (struct_sym.contract_flags.is_cache_aligned) {
                max_align_log2 = @max(max_align_log2, target_layout.cache_line_align_log2);
            }
            if (struct_sym.explicit_align_log2_plus1 > 0) {
                max_align_log2 = @max(max_align_log2, struct_sym.explicit_align_log2_plus1 - 1);
            }
            const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
            break :blk .{
                .byte_size = alignUpU64(cur_offset, max_align_bytes),
                .align_bytes = max_align_bytes,
                .align_log2 = max_align_log2,
                .is_sized = is_all_sized,
            };
        },
        .union_ty => blk: {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                break :blk .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
            }
            const union_sym = sym_table.getSymbol(sym_idx).*;
            if (union_sym.target_scope.isNone()) {
                break :blk .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0 };
            }
            const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, type_id, union_sym, subst);
            const active_subst = if (child_subst.len > 0) &child_subst else subst;
            var max_field_size: u64 = 0;
            var max_align_log2: u8 = 0;
            var is_all_sized = true;
            for (sym_table.getScopeMembers(union_sym.target_scope)) |mem_idx| {
                const mem_sym = sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind != .field_sym) continue;
                const field_layout = computeTypeLayoutBoundedMemo(
                    pool,
                    sym_table,
                    mem_sym.type_id,
                    target_layout,
                    active_subst,
                    depth + 1,
                    memo,
                );
                if (!field_layout.is_sized) is_all_sized = false;
                if (field_layout.byte_size > max_field_size) max_field_size = field_layout.byte_size;
                if (!union_sym.contract_flags.is_packed and field_layout.align_log2 > max_align_log2) {
                    max_align_log2 = field_layout.align_log2;
                }
            }
            if (union_sym.contract_flags.is_cache_aligned) {
                max_align_log2 = @max(max_align_log2, target_layout.cache_line_align_log2);
            }
            if (union_sym.explicit_align_log2_plus1 > 0) {
                max_align_log2 = @max(max_align_log2, union_sym.explicit_align_log2_plus1 - 1);
            }
            const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
            break :blk .{
                .byte_size = alignUpU64(max_field_size, max_align_bytes),
                .align_bytes = max_align_bytes,
                .align_log2 = max_align_log2,
                .is_sized = is_all_sized,
            };
        },
        .optional_ty, .result_ty, .enum_ty => blk: {
            const sum_layout = computeSumMemoryLayoutBoundedMemo(
                pool,
                sym_table,
                type_id,
                target_layout,
                subst,
                depth,
                memo,
            );
            break :blk .{
                .byte_size = sum_layout.byte_size,
                .align_bytes = sum_layout.align_bytes,
                .align_log2 = sum_layout.align_log2,
                .is_sized = sum_layout.is_sized,
            };
        },
        else => .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0, .is_sized = false },
    };
    if (maybe_key) |memo_key| {
        memo.storeLayout(memo_key, computed_layout);
    }
    return computed_layout;
}

/// Fast $O(1)$ leaf niche resolver for primitives, references, slices, functions, and closures (`null` for composites).
inline fn tryComputeFastLeafNiche(
    pool: *const InternPool,
    ty: TypeId,
    target_layout: TargetLayout,
) ?LeafNicheInfo {
    switch (ty) {
        .bool_ty => return .{
            .kind = .high_scalar_range,
            .byte_offset = 0,
            .scalar_bytes = 1,
            .invalid_first = 2,
            .invalid_count = 254,
        },
        .char_ty => return .{
            .kind = .high_scalar_range,
            .byte_offset = 0,
            .scalar_bytes = 4,
            .invalid_first = 0x110000,
            .invalid_count = 0x1_0000_0000 - 0x110000,
        },
        .str_ty, .source_loc_ty, .fmt_args_ty => return .{
            .kind = .zero_ptr,
            .byte_offset = 0,
            .scalar_bytes = target_layout.ptr_byte_size,
            .invalid_first = 0,
            .invalid_count = 1,
        },
        .opaque_ty, .fmt_spec_ty, .bencher_ty => return .{},
        else => {
            if (ty.isSizedPrimitive()) return .{};
        },
    }

    const node = pool.getNode(ty);
    return switch (node.tag) {
        .ref_ty, .mut_ref_ty, .fn_ty, .slice_ty, .soa_slice_ty, .closure_ty => .{
            .kind = .zero_ptr,
            .byte_offset = 0,
            .scalar_bytes = target_layout.ptr_byte_size,
            .invalid_first = 0,
            .invalid_count = 1,
        },
        .raw_ptr_ty, .union_ty, .future_ty, .soa_array_ty, .bit_field_ty => .{},
        else => null,
    };
}

/// Memoized depth-bounded leaf niche walker sharing `memo` across layout, niche, and sum queries.
fn computeLeafNicheBoundedMemo(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_ty: TypeId,
    target_layout: TargetLayout,
    subst: *const NominalTypeSubst,
    depth: u32,
    memo: *LayoutNicheMemo,
) LeafNicheInfo {
    const ty = subst.resolve(raw_ty);
    if (ty.isError() or depth >= MAX_TYPE_DEPTH) return .{};
    if (tryComputeFastLeafNiche(pool, ty, target_layout)) |fast_niche| {
        return fast_niche;
    }
    const maybe_key = LayoutNicheKey.fromQuery(ty, subst, depth);
    if (maybe_key) |memo_key| {
        if (memo.lookupNiche(memo_key)) |cached_niche| return cached_niche;
    }

    const node = pool.getNode(ty);
    const computed_niche: LeafNicheInfo = switch (node.tag) {
        .distinct_ty => computeLeafNicheBoundedMemo(
            pool,
            sym_table,
            TypeId.fromInt(node.lhs),
            target_layout,
            subst,
            depth + 1,
            memo,
        ),
        .refined_ty => blk: {
            if (pool.getRefinementBounds(ty)) |bounds| {
                const base_prim = pool.unwrapUnderlyingType(subst.resolve(bounds.base_ty));
                if (bounds.min_val > 0 and base_prim != .i128_ty and base_prim != .u128_ty) {
                    if (getTargetPrimitiveIntBits(base_prim, target_layout)) |bit_width| {
                        const byte_width: u8 = @intCast(bit_width / 8);
                        if (byte_width == 1 or byte_width == 2 or byte_width == 4 or byte_width == 8) {
                            const max_unsigned: u64 = if (bit_width == 64)
                                std.math.maxInt(u64)
                            else
                                (@as(u64, 1) << @intCast(bit_width)) - 1;
                            const raw_count: u64 = @intCast(@min(bounds.min_val, @as(i128, std.math.maxInt(u64))));
                            const count_u64: u64 = @min(raw_count, max_unsigned);
                            if (count_u64 > 0) {
                                break :blk .{
                                    .kind = .high_scalar_range,
                                    .byte_offset = 0,
                                    .scalar_bytes = byte_width,
                                    .invalid_first = 0,
                                    .invalid_count = count_u64,
                                };
                            }
                        }
                    }
                }
            }
            break :blk .{};
        },
        .array_ty => if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0 or node.rhs == 0)
            .{}
        else
            computeLeafNicheBoundedMemo(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                target_layout,
                subst,
                depth + 1,
                memo,
            ),
        .tuple_ty => blk: {
            const elems = pool.getTupleElements(ty);
            var rank_mask: u64 = 0;
            for (elems) |raw_elem| {
                const elem_layout = computeTypeLayoutBoundedMemo(
                    pool,
                    sym_table,
                    TypeId.fromInt(raw_elem),
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                );
                const sub_niche = computeLeafNicheBoundedMemo(
                    pool,
                    sym_table,
                    TypeId.fromInt(raw_elem),
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                );
                const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) |
                    @intFromBool(sub_niche.kind != .none);
                rank_mask |= (@as(u64, 1) << rank);
            }
            var cur_offset: u64 = 0;
            while (rank_mask != 0) {
                const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                rank_mask &= ~(@as(u64, 1) << top_rank);
                for (elems) |raw_elem| {
                    const elem_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        TypeId.fromInt(raw_elem),
                        target_layout,
                        subst,
                        depth + 1,
                        memo,
                    );
                    const sub_niche = computeLeafNicheBoundedMemo(
                        pool,
                        sym_table,
                        TypeId.fromInt(raw_elem),
                        target_layout,
                        subst,
                        depth + 1,
                        memo,
                    );
                    const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) |
                        @intFromBool(sub_niche.kind != .none);
                    if (rank != top_rank) continue;
                    const aligned_off = alignUpU64(cur_offset, elem_layout.align_bytes);
                    if (sub_niche.kind != .none and aligned_off +| sub_niche.byte_offset <= std.math.maxInt(u32)) {
                        var shifted = sub_niche;
                        shifted.byte_offset = @intCast(aligned_off + sub_niche.byte_offset);
                        break :blk shifted;
                    }
                    cur_offset = aligned_off +| elem_layout.byte_size;
                }
            }
            break :blk .{};
        },
        .struct_ty => blk: {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) break :blk .{};
            const st_sym = sym_table.getSymbol(sym_idx).*;
            if (st_sym.target_scope.isNone() or st_sym.contract_flags.is_packed) break :blk .{};
            const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, ty, st_sym, subst);
            const active_subst = if (child_subst.len > 0) &child_subst else subst;
            const members = sym_table.getScopeMembers(st_sym.target_scope);
            var cur_offset: u64 = 0;
            if (st_sym.contract_flags.is_repr_c) {
                for (members) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    const field_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    const aligned_off = alignUpU64(cur_offset, field_layout.align_bytes);
                    const sub_niche = computeLeafNicheBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    if (sub_niche.kind != .none and aligned_off +| sub_niche.byte_offset <= std.math.maxInt(u32)) {
                        var shifted = sub_niche;
                        shifted.byte_offset = @intCast(aligned_off + sub_niche.byte_offset);
                        break :blk shifted;
                    }
                    cur_offset = aligned_off +| field_layout.byte_size;
                }
                break :blk .{};
            }
            var rank_mask: u64 = 0;
            for (members) |mem_idx| {
                const mem_sym = sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind != .field_sym) continue;
                const field_layout = computeTypeLayoutBoundedMemo(
                    pool,
                    sym_table,
                    mem_sym.type_id,
                    target_layout,
                    active_subst,
                    depth + 1,
                    memo,
                );
                const sub_niche = computeLeafNicheBoundedMemo(
                    pool,
                    sym_table,
                    mem_sym.type_id,
                    target_layout,
                    active_subst,
                    depth + 1,
                    memo,
                );
                const rank: u6 = (@as(u6, @intCast(@min(field_layout.align_log2, 30))) << 1) |
                    @intFromBool(sub_niche.kind != .none);
                rank_mask |= (@as(u64, 1) << rank);
            }
            while (rank_mask != 0) {
                const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                rank_mask &= ~(@as(u64, 1) << top_rank);
                for (members) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    const field_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    const sub_niche = computeLeafNicheBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    const rank: u6 = (@as(u6, @intCast(@min(field_layout.align_log2, 30))) << 1) |
                        @intFromBool(sub_niche.kind != .none);
                    if (rank != top_rank) continue;
                    const aligned_off = alignUpU64(cur_offset, field_layout.align_bytes);
                    if (sub_niche.kind != .none and aligned_off +| sub_niche.byte_offset <= std.math.maxInt(u32)) {
                        var shifted = sub_niche;
                        shifted.byte_offset = @intCast(aligned_off + sub_niche.byte_offset);
                        break :blk shifted;
                    }
                    cur_offset = aligned_off +| field_layout.byte_size;
                }
            }
            break :blk .{};
        },
        .enum_ty => blk: {
            if (pool.getEnumBackingIntType(ty) != null) break :blk .{};
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) break :blk .{};
            const enum_sym = sym_table.getSymbol(sym_idx).*;
            if (enum_sym.target_scope.isNone()) break :blk .{};
            var variant_count: u64 = 0;
            for (sym_table.getScopeMembers(enum_sym.target_scope)) |mem_idx| {
                if (sym_table.getSymbol(mem_idx).kind == .enum_variant_sym) variant_count += 1;
            }
            if (variant_count == 0) break :blk .{};
            const auto_tag_log2: u8 = if (variant_count <= 256) 0 else if (variant_count <= 65_536) 1 else 2;
            const repr_tag_log2: u8 = switch (enum_sym.repr_tag_bits) {
                8 => 0,
                16 => 1,
                32 => 2,
                64 => 3,
                128 => break :blk .{},
                else => 0,
            };
            const tag_log2: u8 = @max(auto_tag_log2, repr_tag_log2);
            const tag_bytes: u8 = @as(u8, 1) << @intCast(tag_log2);
            const tag_bits: u8 = tag_bytes * 8;
            const max_tag_val: u64 = if (tag_bits == 64)
                std.math.maxInt(u64)
            else
                (@as(u64, 1) << @intCast(tag_bits)) - 1;
            if (variant_count <= max_tag_val) {
                break :blk .{
                    .kind = .high_scalar_range,
                    .byte_offset = 0,
                    .scalar_bytes = tag_bytes,
                    .invalid_first = variant_count,
                    .invalid_count = (max_tag_val - variant_count) + 1,
                };
            }
            break :blk .{};
        },
        .optional_ty, .result_ty => blk: {
            const sum_layout = computeSumMemoryLayoutBoundedMemo(
                pool,
                sym_table,
                ty,
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            break :blk switch (sum_layout.repr) {
                .transparent_ok => computeLeafNicheBoundedMemo(
                    pool,
                    sym_table,
                    sum_layout.payload_ty,
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                ),
                .niche_single => if (sum_layout.niche.kind == .high_scalar_range and
                    sum_layout.niche.invalid_count > 1)
                    .{
                        .kind = .high_scalar_range,
                        .byte_offset = sum_layout.niche.byte_offset,
                        .scalar_bytes = sum_layout.niche.scalar_bytes,
                        .invalid_first = sum_layout.niche.invalid_first + 1,
                        .invalid_count = sum_layout.niche.invalid_count - 1,
                    }
                else
                    .{},
                .explicit_tag => .{
                    .kind = .high_scalar_range,
                    .byte_offset = 0,
                    .scalar_bytes = sum_layout.tag_bytes,
                    .invalid_first = 2,
                    .invalid_count = 254,
                },
            };
        },
        else => .{},
    };
    if (maybe_key) |memo_key| {
        memo.storeNiche(memo_key, computed_niche);
    }
    return computed_niche;
}

/// Memoized depth-bounded helper computing canonical sum memory layout while sharing `memo`.
fn computeSumMemoryLayoutBoundedMemo(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_sum_ty: TypeId,
    target_layout: TargetLayout,
    subst: *const NominalTypeSubst,
    depth: u32,
    memo: *LayoutNicheMemo,
) SumMemoryLayout {
    const sum_ty = subst.resolve(raw_sum_ty);
    if (sum_ty.isError() or depth >= MAX_TYPE_DEPTH) {
        return .{ .is_sized = false };
    }
    const node = pool.getNode(sum_ty);
    switch (node.tag) {
        .optional_ty => {
            const payload_ty = subst.resolve(TypeId.fromInt(node.lhs));
            const payload_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                payload_ty,
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            const niche = computeLeafNicheBoundedMemo(
                pool,
                sym_table,
                payload_ty,
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            if (niche.kind != .none) {
                return .{
                    .repr = .niche_single,
                    .byte_size = payload_layout.byte_size,
                    .align_bytes = payload_layout.align_bytes,
                    .align_log2 = payload_layout.align_log2,
                    .is_sized = payload_layout.is_sized,
                    .tag_bytes = 0,
                    .payload_offset = 0,
                    .zst_discriminant = 0,
                    .payload_discriminant = 1,
                    .payload_ty = payload_ty,
                    .niche = niche,
                };
            }
            const payload_offset = alignUpU64(1, payload_layout.align_bytes);
            return .{
                .repr = .explicit_tag,
                .byte_size = alignUpU64(payload_offset +| payload_layout.byte_size, payload_layout.align_bytes),
                .align_bytes = payload_layout.align_bytes,
                .align_log2 = payload_layout.align_log2,
                .is_sized = payload_layout.is_sized,
                .tag_bytes = 1,
                .payload_offset = payload_offset,
                .payload_ty = payload_ty,
            };
        },
        .result_ty => {
            const ok_ty = subst.resolve(TypeId.fromInt(node.lhs));
            const err_ty = subst.resolve(TypeId.fromInt(node.rhs));
            const ok_unwrapped = pool.unwrapUnderlyingType(ok_ty);
            const err_unwrapped = pool.unwrapUnderlyingType(err_ty);
            const ok_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                ok_ty,
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            if (err_unwrapped == .never_ty) {
                return .{
                    .repr = .transparent_ok,
                    .byte_size = ok_layout.byte_size,
                    .align_bytes = ok_layout.align_bytes,
                    .align_log2 = ok_layout.align_log2,
                    .is_sized = ok_layout.is_sized,
                    .tag_bytes = 0,
                    .payload_offset = 0,
                    .payload_discriminant = 0,
                    .payload_ty = ok_ty,
                };
            }
            const err_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                err_ty,
                target_layout,
                subst,
                depth + 1,
                memo,
            );
            if (err_unwrapped == .unit_ty and ok_unwrapped != .unit_ty) {
                const ok_niche = computeLeafNicheBoundedMemo(
                    pool,
                    sym_table,
                    ok_ty,
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                );
                if (ok_niche.kind != .none) {
                    return .{
                        .repr = .niche_single,
                        .byte_size = ok_layout.byte_size,
                        .align_bytes = ok_layout.align_bytes,
                        .align_log2 = ok_layout.align_log2,
                        .is_sized = ok_layout.is_sized,
                        .tag_bytes = 0,
                        .payload_offset = 0,
                        .zst_discriminant = 1,
                        .payload_discriminant = 0,
                        .payload_ty = ok_ty,
                        .niche = ok_niche,
                    };
                }
            } else if (ok_unwrapped == .unit_ty and err_unwrapped != .unit_ty) {
                const err_niche = computeLeafNicheBoundedMemo(
                    pool,
                    sym_table,
                    err_ty,
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                );
                if (err_niche.kind != .none) {
                    return .{
                        .repr = .niche_single,
                        .byte_size = err_layout.byte_size,
                        .align_bytes = err_layout.align_bytes,
                        .align_log2 = err_layout.align_log2,
                        .is_sized = err_layout.is_sized,
                        .tag_bytes = 0,
                        .payload_offset = 0,
                        .zst_discriminant = 0,
                        .payload_discriminant = 1,
                        .payload_ty = err_ty,
                        .niche = err_niche,
                    };
                }
            }
            const max_payload_log2: u8 = @max(ok_layout.align_log2, err_layout.align_log2);
            const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_payload_log2);
            const max_payload_size: u64 = @max(ok_layout.byte_size, err_layout.byte_size);
            const payload_offset = alignUpU64(1, max_align_bytes);
            return .{
                .repr = .explicit_tag,
                .byte_size = alignUpU64(payload_offset +| max_payload_size, max_align_bytes),
                .align_bytes = max_align_bytes,
                .align_log2 = max_payload_log2,
                .is_sized = ok_layout.is_sized and err_layout.is_sized,
                .tag_bytes = 1,
                .payload_offset = payload_offset,
            };
        },
        .enum_ty => {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                return .{ .byte_size = 1, .align_bytes = 1, .align_log2 = 0, .tag_bytes = 1 };
            }
            const enum_sym = sym_table.getSymbol(sym_idx).*;
            if (enum_sym.target_scope.isNone()) {
                return .{ .byte_size = 1, .align_bytes = 1, .align_log2 = 0, .tag_bytes = 1 };
            }
            const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, sum_ty, enum_sym, subst);
            const active_subst = if (child_subst.len > 0) &child_subst else subst;
            var variant_count: usize = 0;
            var max_payload_size: u64 = 0;
            var max_payload_log2: u8 = 0;
            var is_all_sized = true;
            for (sym_table.getScopeMembers(enum_sym.target_scope)) |mem_idx| {
                const mem_sym = sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind != .enum_variant_sym) continue;
                variant_count += 1;
                if (mem_sym.type_id != .unit_ty and !mem_sym.type_id.isError()) {
                    const var_layout = computeTypeLayoutBoundedMemo(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                        memo,
                    );
                    if (!var_layout.is_sized) is_all_sized = false;
                    if (var_layout.byte_size > max_payload_size) max_payload_size = var_layout.byte_size;
                    if (var_layout.align_log2 > max_payload_log2) max_payload_log2 = var_layout.align_log2;
                }
            }
            if (variant_count == 0 and pool.getEnumBackingIntType(sum_ty) == null) {
                return .{ .byte_size = 0, .align_bytes = 1, .align_log2 = 0, .tag_bytes = 0 };
            }
            if (pool.getEnumBackingIntType(sum_ty)) |backing_int_ty| {
                const backing_layout = computeTypeLayoutBoundedMemo(
                    pool,
                    sym_table,
                    backing_int_ty,
                    target_layout,
                    subst,
                    depth + 1,
                    memo,
                );
                var max_align_log2: u8 = backing_layout.align_log2;
                if (enum_sym.contract_flags.is_cache_aligned) {
                    max_align_log2 = @max(max_align_log2, target_layout.cache_line_align_log2);
                }
                if (enum_sym.explicit_align_log2_plus1 > 0) {
                    max_align_log2 = @max(max_align_log2, enum_sym.explicit_align_log2_plus1 - 1);
                }
                const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
                const tag_b: u8 = @intCast(@min(backing_layout.byte_size, 16));
                return .{
                    .repr = .explicit_tag,
                    .byte_size = alignUpU64(backing_layout.byte_size, max_align_bytes),
                    .align_bytes = max_align_bytes,
                    .align_log2 = max_align_log2,
                    .is_sized = backing_layout.is_sized,
                    .tag_bytes = tag_b,
                    .payload_offset = tag_b,
                };
            }
            const auto_tag_log2: u8 = if (variant_count <= 256) 0 else if (variant_count <= 65_536) 1 else 2;
            const repr_tag_log2: u8 = switch (enum_sym.repr_tag_bits) {
                8 => 0,
                16 => 1,
                32 => 2,
                64 => 3,
                128 => 4,
                else => 0,
            };
            const tag_log2: u8 = @max(auto_tag_log2, repr_tag_log2);
            const tag_bytes: u8 = @as(u8, 1) << @intCast(tag_log2);
            var max_align_log2: u8 = @max(tag_log2, max_payload_log2);
            if (enum_sym.contract_flags.is_cache_aligned) {
                max_align_log2 = @max(max_align_log2, target_layout.cache_line_align_log2);
            }
            if (enum_sym.explicit_align_log2_plus1 > 0) {
                max_align_log2 = @max(max_align_log2, enum_sym.explicit_align_log2_plus1 - 1);
            }
            const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
            if (max_payload_size == 0) {
                return .{
                    .repr = .explicit_tag,
                    .byte_size = alignUpU64(tag_bytes, max_align_bytes),
                    .align_bytes = max_align_bytes,
                    .align_log2 = max_align_log2,
                    .is_sized = is_all_sized,
                    .tag_bytes = tag_bytes,
                    .payload_offset = tag_bytes,
                };
            }
            const payload_align_bytes: u32 = @as(u32, 1) << @intCast(max_payload_log2);
            const payload_offset = alignUpU64(tag_bytes, payload_align_bytes);
            return .{
                .repr = .explicit_tag,
                .byte_size = alignUpU64(payload_offset +| max_payload_size, max_align_bytes),
                .align_bytes = max_align_bytes,
                .align_log2 = max_align_log2,
                .is_sized = is_all_sized,
                .tag_bytes = tag_bytes,
                .payload_offset = payload_offset,
            };
        },
        else => return .{ .is_sized = false },
    }
}

/// Recursive `Send`/`Sync` verifier propagating `NominalTypeSubst` across generic `struct`/`enum`/`union` instantiations.
fn explainNonSendOrSyncTypeWithSubst(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_ty: TypeId,
    parent_subst: *const NominalTypeSubst,
    is_requiring_sync: bool,
    depth: u32,
    memo: *SendSyncVisitedMemo,
) ?[]const u8 {
    if (depth >= 16 or raw_ty.isError()) return null;
    const subst_ty = parent_subst.resolve(raw_ty);
    if (subst_ty.isError()) return null;
    if (parent_subst.len == 0 and memo.hasVerified(subst_ty.toU32(), is_requiring_sync, depth)) {
        return null;
    }

    // Inspect `@not_send` / `@not_sync` on `distinct` newtypes before unwrapping their base representation:
    var walk_distinct = pool.unwrapRefinementBase(subst_ty);
    var dist_hops: u8 = 0;
    while (!walk_distinct.isError() and dist_hops < 8) : (dist_hops += 1) {
        const d_node = pool.getNode(walk_distinct);
        if (d_node.tag != .distinct_ty) break;
        const d_sym_idx = SymbolIndex.fromInt(d_node.rhs);
        if (!d_sym_idx.isNone() and d_sym_idx.asInt() < sym_table.symbols.items.len) {
            const d_sym = sym_table.getSymbol(d_sym_idx).*;
            if (isNominalNotSend(d_sym)) {
                return "non-`Send` type cannot cross worker threads in `TaskGroup.spawn`; use `group.spawn_local`";
            }
            if (is_requiring_sync and isNominalNotSync(d_sym)) {
                return "shared `&T` capture in `TaskGroup.spawn` requires `T: Sync` (non-atomic interior mutability is `!Sync`)";
            }
        }
        walk_distinct = pool.unwrapRefinementBase(TypeId.fromInt(d_node.lhs));
    }

    const ty = pool.unwrapUnderlyingType(subst_ty);
    if (ty.isError() or ty.isSizedPrimitive()) return null;
    const node = pool.getNode(ty);
    const violation_reason: ?[]const u8 = switch (node.tag) {
        .raw_ptr_ty => "`TaskGroup.spawn` cannot capture or send raw pointers (`*T` / `*mut T`) across threads",
        .ref_ty => explainNonSendOrSyncTypeWithSubst(
            pool,
            sym_table,
            TypeId.fromInt(node.lhs),
            parent_subst,
            true,
            depth + 1,
            memo,
        ),
        .mut_ref_ty => explainNonSendOrSyncTypeWithSubst(
            pool,
            sym_table,
            TypeId.fromInt(node.lhs),
            parent_subst,
            is_requiring_sync,
            depth + 1,
            memo,
        ),
        .slice_ty, .soa_slice_ty, .array_ty, .soa_array_ty, .optional_ty, .future_ty => {
            return explainNonSendOrSyncTypeWithSubst(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                parent_subst,
                is_requiring_sync,
                depth + 1,
                memo,
            );
        },
        .result_ty => blk: {
            if (explainNonSendOrSyncTypeWithSubst(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                parent_subst,
                is_requiring_sync,
                depth + 1,
                memo,
            )) |reason| {
                break :blk reason;
            }
            break :blk explainNonSendOrSyncTypeWithSubst(
                pool,
                sym_table,
                TypeId.fromInt(node.rhs),
                parent_subst,
                is_requiring_sync,
                depth + 1,
                memo,
            );
        },
        .tuple_ty => blk: {
            for (pool.getTupleElements(ty)) |elem_raw| {
                if (explainNonSendOrSyncTypeWithSubst(
                    pool,
                    sym_table,
                    TypeId.fromInt(elem_raw),
                    parent_subst,
                    is_requiring_sync,
                    depth + 1,
                    memo,
                )) |reason| {
                    break :blk reason;
                }
            }
            break :blk null;
        },
        .closure_ty => blk: {
            if (pool.getFnSignatureView(ty)) |sig| {
                if (sig.capture_tier == .copy_tier and sig.has_env_capture and !is_requiring_sync) {
                    break :blk "`@local` borrow-capturing closure is not `Send` across `TaskGroup.spawn`; use `own` or `spawn_local`";
                }
            }
            break :blk null;
        },
        .struct_ty, .enum_ty, .union_ty => blk: {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < sym_table.symbols.items.len) {
                const sym = sym_table.getSymbol(sym_idx).*;
                if (isNominalNotSend(sym)) {
                    break :blk "non-`Send` type cannot cross worker threads in `TaskGroup.spawn`; use `group.spawn_local`";
                }
                if (is_requiring_sync and isNominalNotSync(sym)) {
                    break :blk "shared `&T` capture in `TaskGroup.spawn` requires `T: Sync` (non-atomic interior mutability is `!Sync`)";
                }
                if (isStdCoreOrBuiltinSymbol(sym_table, sym) and
                    SAFE_SEND_SYNC_CORE_NOMINAL_MAP.has(sym.name_text))
                {
                    break :blk null;
                }
                for (pool.getGenericTypeArgs(ty)) |arg_raw| {
                    if (explainNonSendOrSyncTypeWithSubst(
                        pool,
                        sym_table,
                        TypeId.fromInt(arg_raw),
                        parent_subst,
                        is_requiring_sync,
                        depth + 1,
                        memo,
                    )) |reason| {
                        break :blk reason;
                    }
                }
                if (!sym.target_scope.isNone()) {
                    const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, ty, sym, parent_subst);
                    const active_subst = if (child_subst.len > 0) &child_subst else parent_subst;
                    for (sym_table.getScopeMembers(sym.target_scope)) |mem_idx| {
                        const mem_sym = sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym and mem_sym.kind != .enum_variant_sym) continue;
                        if (explainNonSendOrSyncTypeWithSubst(
                            pool,
                            sym_table,
                            mem_sym.type_id,
                            active_subst,
                            is_requiring_sync,
                            depth + 1,
                            memo,
                        )) |reason| {
                            break :blk reason;
                        }
                    }
                }
            }
            break :blk null;
        },
        else => null,
    };
    if (violation_reason == null and parent_subst.len == 0) {
        memo.recordVerified(subst_ty.toU32(), is_requiring_sync, depth);
    }
    return violation_reason;
}

/// Returns `true` if `sym_table` records an explicit `Drop`/`AutoDrop` trait `impl` or inherent `fn drop` for `ty`.
fn hasNominalDropTraitImpl(
    sym_table: *const SymbolTable,
    ty: TypeId,
    base_nom_ty: TypeId,
    target_scope: ScopeId,
) bool {
    if (!target_scope.isNone()) {
        for (sym_table.getScopeMembers(target_scope)) |mem_idx| {
            const mem_sym = sym_table.getSymbol(mem_idx).*;
            if (mem_sym.kind == .fn_sym and std.mem.eql(u8, mem_sym.name_text, "drop")) {
                return true;
            }
        }
    }
    var key_it = sym_table.trait_impl_pairs.keyIterator();
    while (key_it.next()) |pair_key_ptr| {
        const target_raw: u32 = @truncate(pair_key_ptr.* >> 32);
        const trait_raw: u32 = @truncate(pair_key_ptr.*);
        if (target_raw != ty.toU32() and target_raw != base_nom_ty.toU32()) continue;
        const trait_idx = SymbolIndex.fromInt(trait_raw);
        if (trait_idx.isNone() or trait_idx.asInt() >= sym_table.symbols.items.len) continue;
        const trait_name = sym_table.getSymbol(trait_idx).name_text;
        if (std.mem.eql(u8, trait_name, "Drop") or std.mem.eql(u8, trait_name, "AutoDrop")) {
            return true;
        }
    }
    return false;
}

/// Returns the maximum of two `OwnershipTier` values (`copy_tier < auto_drop_tier < linear_tier`).
inline fn maxOwnershipTier(lhs_tier: OwnershipTier, rhs_tier: OwnershipTier) OwnershipTier {
    return if (@backingInt(rhs_tier) > @backingInt(lhs_tier)) rhs_tier else lhs_tier;
}

/// Fast $O(1)$ ownership tier check for primitives, references, slices, functions, and closures (`null` for composites).
inline fn tryClassifyFastOwnershipTier(
    pool: *const InternPool,
    ty: TypeId,
    is_mut_ref_linear: bool,
) ?OwnershipTier {
    if (ty == .opaque_ty) return .auto_drop_tier;
    if (ty == .bencher_ty or pool.isTaskGroupType(ty) or pool.isTaskHandleType(ty)) {
        return .linear_tier;
    }
    if (ty.isError() or ty == .untyped_int_ty or ty == .untyped_float_ty or
        ty == .source_loc_ty or ty == .fmt_spec_ty or ty == .fmt_args_ty or ty.isSizedPrimitive())
    {
        return .copy_tier;
    }
    const node = pool.getNode(ty);
    return switch (node.tag) {
        .mut_ref_ty => if (is_mut_ref_linear) .linear_tier else .copy_tier,
        .slice_ty,
        .soa_slice_ty,
        .ref_ty,
        .raw_ptr_ty,
        .fn_ty,
        .bit_field_ty,
        .trait_ty,
        .builtin_group,
        .user_group,
        .tilde_approx,
        .bind_once_group_var,
        .bind_many_any_var,
        => .copy_tier,
        .dyn_trait_ty => .auto_drop_tier,
        .closure_ty => if (pool.getFnSignatureView(ty)) |sig_view|
            (if (is_mut_ref_linear)
                sig_view.capture_tier
            else if (sig_view.has_linear_capture)
                .linear_tier
            else
                sig_view.capture_tier)
        else
            .copy_tier,
        else => null,
    };
}

// ------------------------------------- PUBLIC API --------------------------------------

// ------------ Canonical `InternPool` (`TypeArena`) ------------

/// Canonical Structure-of-Arrays (SoA) type interner with static `0..63` pre-population (`DR-04` Section 2).
pub const InternPool = struct {
    /// Backing allocator for the SoA columns, `extra` array, and deduplication buckets.
    allocator: std.mem.Allocator,
    /// 14-byte zero-padding SoA `TypeNode` table indexed by `TypeId.toU32()`.
    nodes: std.MultiArrayList(TypeNode) = .empty,
    /// Flat `u32` payload trail storing tuple elements, function parameter lists, and refinement bounds.
    extra: std.ArrayListUnmanaged(u32) = .empty,
    /// Map from 32-bit structural hash to candidate `TypeId` bucket for $O(1)$ deduplication.
    dedup_buckets: std.AutoHashMapUnmanaged(u32, std.ArrayListUnmanaged(TypeId)) = .empty,
    /// Explicit backing integer `TypeId` (`enum Name: BackingInt`) keyed by nominal `enum_ty.toU32()` (`ADR-22D`).
    backed_enum_int_types: std.AutoHashMapUnmanaged(u32, TypeId) = .empty,
    /// Evaluated 128-bit discriminant per `(enum_ty.toU32() << 32) | variant_ordinal` on backed enums (`ADR-22D`).
    backed_enum_discriminants: std.AutoHashMapUnmanaged(u64, i128) = .empty,
    /// Synthesized `@derive(From)` 0-based enum variant ordinal keyed by `packFromErrorPair(src_err, dst_enum)` (`SE-10`).
    derived_from_variants: std.AutoHashMapUnmanaged(u64, u32) = .empty,

    /// Initializes a new `InternPool` and pre-populates static `TypeId` slots `0..63`.
    pub fn init(allocator: std.mem.Allocator) !InternPool {
        var self = InternPool{ .allocator = allocator };
        errdefer self.deinit();
        try self.populateStaticSlots();
        return self;
    }

    /// Releases all SoA columns, `extra` payloads, and deduplication buckets.
    pub fn deinit(self: *InternPool) void {
        var bucket_iter = self.dedup_buckets.valueIterator();
        while (bucket_iter.next()) |bucket_ptr| {
            bucket_ptr.deinit(self.allocator);
        }
        self.dedup_buckets.deinit(self.allocator);
        self.backed_enum_int_types.deinit(self.allocator);
        self.backed_enum_discriminants.deinit(self.allocator);
        self.derived_from_variants.deinit(self.allocator);
        self.extra.deinit(self.allocator);
        self.nodes.deinit(self.allocator);
        self.* = undefined;
    }

    /// Resets dynamic types (`>= 64`) while preserving static slots `0..63` and allocated capacity.
    pub fn resetDynamic(self: *InternPool) !void {
        var bucket_iter = self.dedup_buckets.valueIterator();
        while (bucket_iter.next()) |bucket_ptr| {
            bucket_ptr.clearRetainingCapacity();
        }
        self.backed_enum_int_types.clearRetainingCapacity();
        self.backed_enum_discriminants.clearRetainingCapacity();
        self.derived_from_variants.clearRetainingCapacity();
        self.extra.clearRetainingCapacity();
        if (self.nodes.len > STATIC_TYPE_SLOT_COUNT) {
            self.nodes.shrinkRetainingCapacity(STATIC_TYPE_SLOT_COUNT);
        } else if (self.nodes.len < STATIC_TYPE_SLOT_COUNT) {
            self.nodes.shrinkRetainingCapacity(0);
            try self.populateStaticSlots();
        }
    }

    /// Pre-populates static slots `0..63` (`DR-04` Section 2.1, `DR-22` `ADR-22F` & `SE-12`/`SE-16`/`SE-17`/`SE-20`).
    fn populateStaticSlots(self: *InternPool) !void {
        try self.nodes.ensureTotalCapacity(self.allocator, STATIC_TYPE_SLOT_COUNT);
        var slot_idx: u32 = 0;
        while (slot_idx < STATIC_TYPE_SLOT_COUNT) : (slot_idx += 1) {
            const tid = TypeId.fromInt(slot_idx);
            if (slot_idx <= 18) {
                const flags: TypeFlags = .{ .is_copy = true, .is_sized = true };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, slot_idx, 0, &.{}),
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            } else if (slot_idx >= 19 and slot_idx <= 21) {
                const flags: TypeFlags = .{
                    .is_copy = true,
                    .has_error = (tid == .err_ty),
                    .is_sized = true,
                };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, slot_idx, 0, &.{}),
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            } else if (tid == .opaque_ty) {
                const flags: TypeFlags = .{ .is_copy = false, .is_sized = false };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, slot_idx, 0, &.{}),
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            } else if (slot_idx >= 32 and slot_idx <= 44 and tid != ._retired_group_numeric) {
                const mask = TypeGroupMask.forBuiltinGroup(tid);
                const flags: TypeFlags = .{ .is_copy = true, .is_sized = true };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .builtin_group,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.builtin_group, flags, mask, slot_idx, &.{}),
                    .lhs = mask,
                    .rhs = slot_idx,
                });
            } else if (tid == .source_loc_ty or tid == .fmt_spec_ty) {
                const flags: TypeFlags = .{ .is_copy = true, .is_sized = true };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, slot_idx, 0, &.{}),
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            } else if (tid == .fmt_args_ty) {
                const flags: TypeFlags = .{ .is_copy = true, .has_regions = true, .is_sized = true };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, slot_idx, 0, &.{}),
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            } else if (tid == .bencher_ty) {
                const flags: TypeFlags = .{ .is_copy = false, .is_sized = true };
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, slot_idx, 0, &.{}),
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            } else if (tid == .task_group_base_ty) {
                const flags: TypeFlags = .{ .is_copy = false, .is_must_use = true, .is_sized = true };
                const default_err = TypeId.never_ty.toU32();
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, default_err, slot_idx, &.{}),
                    .lhs = default_err,
                    .rhs = slot_idx,
                });
            } else if (tid == .task_handle_base_ty) {
                const flags: TypeFlags = .{ .is_copy = false, .is_must_use = true, .is_sized = true };
                const default_val = TypeId.unit_ty.toU32();
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = flags,
                    .hash = computeStructuralTypeHash(.primitive, flags, default_val, slot_idx, &.{}),
                    .lhs = default_val,
                    .rhs = slot_idx,
                });
            } else {
                self.nodes.appendAssumeCapacity(.{
                    .tag = .primitive,
                    .flags = .{ .has_error = true },
                    .hash = slot_idx,
                    .lhs = slot_idx,
                    .rhs = 0,
                });
            }
        }
    }

    /// Retrieves the `TypeNode` for `type_id` in $O(1)$ time.
    pub inline fn getNode(self: *const InternPool, type_id: TypeId) TypeNode {
        const idx = type_id.toU32();
        if (idx >= self.nodes.len) return self.nodes.get(TypeId.err_ty.toU32());
        return self.nodes.get(idx);
    }

    /// Retrieves the `TypeTag` for `type_id` in $O(1)$ time.
    pub inline fn getTag(self: *const InternPool, type_id: TypeId) TypeTag {
        const idx = type_id.toU32();
        if (idx >= self.nodes.len) return .primitive;
        return self.nodes.items(.tag)[idx];
    }

    /// Retrieves the `TypeFlags` for `type_id` in $O(1)$ time.
    pub inline fn getFlags(self: *const InternPool, type_id: TypeId) TypeFlags {
        const idx = type_id.toU32();
        if (idx >= self.nodes.len) return .{ .has_error = true };
        return self.nodes.items(.flags)[idx];
    }

    /// Retrieves the canonical 32-bit structural hash of `type_id` (used for position-independent query hashing).
    pub inline fn getHash(self: *const InternPool, type_id: TypeId) u32 {
        const idx = type_id.toU32();
        if (idx >= self.nodes.len) return 0xDEAD_BEEF;
        return self.nodes.items(.hash)[idx];
    }

    /// Returns the total number of `TypeNode` slots in the pool.
    pub inline fn countTypes(self: *const InternPool) usize {
        return self.nodes.len;
    }

    /// Interns a fixed-arity `TypeNode` (`tag`, `flags`, `lhs`, `rhs`) with $O(1)$ structural deduplication.
    pub fn internSimple(
        self: *InternPool,
        tag: TypeTag,
        flags: TypeFlags,
        lhs: u32,
        rhs: u32,
    ) !TypeId {
        const struct_hash = computeStructuralTypeHash(tag, flags, lhs, rhs, &.{});
        const gop = try self.dedup_buckets.getOrPut(self.allocator, struct_hash);
        if (!gop.found_existing) {
            gop.value_ptr.* = .empty;
        } else {
            for (gop.value_ptr.items) |cand_id| {
                const cand = self.getNode(cand_id);
                if (cand.tag == tag and
                    @as(u8, @bitCast(cand.flags)) == @as(u8, @bitCast(flags)) and
                    cand.lhs == lhs and cand.rhs == rhs)
                {
                    return cand_id;
                }
            }
        }

        const new_id = TypeId.fromInt(@intCast(self.nodes.len));
        try self.nodes.append(self.allocator, .{
            .tag = tag,
            .flags = flags,
            .hash = struct_hash,
            .lhs = lhs,
            .rhs = rhs,
        });
        try gop.value_ptr.append(self.allocator, new_id);
        return new_id;
    }

    /// Interns a variable-length `TypeNode` whose `lhs` indexes `extra_slice` in `self.extra`.
    pub fn internExtra(
        self: *InternPool,
        tag: TypeTag,
        flags: TypeFlags,
        rhs: u32,
        extra_slice: []const u32,
    ) !TypeId {
        const len_u32: u32 = @intCast(extra_slice.len);
        const struct_hash = computeStructuralTypeHash(tag, flags, len_u32, rhs, extra_slice);
        const gop = try self.dedup_buckets.getOrPut(self.allocator, struct_hash);
        if (!gop.found_existing) {
            gop.value_ptr.* = .empty;
        } else {
            for (gop.value_ptr.items) |cand_id| {
                const cand = self.getNode(cand_id);
                if (cand.tag == tag and
                    @as(u8, @bitCast(cand.flags)) == @as(u8, @bitCast(flags)) and
                    cand.rhs == rhs and
                    cand.lhs + extra_slice.len <= self.extra.items.len)
                {
                    const existing_slice = self.extra.items[cand.lhs .. cand.lhs + extra_slice.len];
                    if (std.mem.eql(u32, existing_slice, extra_slice)) {
                        return cand_id;
                    }
                }
            }
        }

        const extra_start: u32 = @intCast(self.extra.items.len);
        try self.extra.appendSlice(self.allocator, extra_slice);

        const new_id = TypeId.fromInt(@intCast(self.nodes.len));
        try self.nodes.append(self.allocator, .{
            .tag = tag,
            .flags = flags,
            .hash = struct_hash,
            .lhs = extra_start,
            .rhs = rhs,
        });
        try gop.value_ptr.append(self.allocator, new_id);
        return new_id;
    }

    // --------------- Specialized Type Constructors ----------------

    /// Interns `T?` (`optional_ty`).
    pub fn internOptional(self: *InternPool, payload_ty: TypeId) !TypeId {
        if (payload_ty.isError()) return .err_ty;
        const inner_flags = self.getFlags(payload_ty);
        return self.internSimple(.optional_ty, .{
            .is_copy = inner_flags.is_copy,
            .has_type_vars = inner_flags.has_type_vars,
            .has_regions = inner_flags.has_regions,
            .is_sized = true,
            .is_secret = inner_flags.is_secret,
            .has_drop = inner_flags.has_drop,
        }, payload_ty.toU32(), 0);
    }

    /// Interns `Result[T, E]` (`result_ty`, always marked `is_must_use = true` per `DR-07` Section 2.7).
    pub fn internResult(self: *InternPool, ok_ty: TypeId, err_ty_arg: TypeId) !TypeId {
        if (ok_ty.isError() or err_ty_arg.isError()) return .err_ty;
        const ok_flags = self.getFlags(ok_ty);
        const err_flags = self.getFlags(err_ty_arg);
        return self.internSimple(.result_ty, .{
            .is_copy = ok_flags.is_copy and err_flags.is_copy,
            .has_type_vars = ok_flags.has_type_vars or err_flags.has_type_vars,
            .has_regions = ok_flags.has_regions or err_flags.has_regions,
            .is_must_use = true,
            .is_sized = true,
            .is_secret = ok_flags.is_secret or err_flags.is_secret,
            .has_drop = ok_flags.has_drop or err_flags.has_drop,
        }, ok_ty.toU32(), err_ty_arg.toU32());
    }

    /// Interns `[T]` or `#soa [T]` (`slice_ty` / `soa_slice_ty`).
    pub fn internSlice(self: *InternPool, elem_ty: TypeId, is_soa: bool) !TypeId {
        if (elem_ty.isError()) return .err_ty;
        const elem_flags = self.getFlags(elem_ty);
        return self.internSimple(if (is_soa) .soa_slice_ty else .slice_ty, .{
            .is_copy = true,
            .has_type_vars = elem_flags.has_type_vars,
            .has_regions = true,
            .is_sized = true,
            .is_secret = elem_flags.is_secret,
        }, elem_ty.toU32(), 0);
    }

    /// Interns `[T; N]` or `#soa [T; N]` (`array_ty` / `soa_array_ty`).
    pub fn internArray(self: *InternPool, elem_ty: TypeId, array_len: u32, is_soa: bool) !TypeId {
        if (elem_ty.isError()) return .err_ty;
        const elem_flags = self.getFlags(elem_ty);
        return self.internSimple(if (is_soa) .soa_array_ty else .array_ty, .{
            .is_copy = elem_flags.is_copy,
            .has_type_vars = elem_flags.has_type_vars,
            .has_regions = elem_flags.has_regions,
            .is_sized = true,
            .is_secret = elem_flags.is_secret,
            .has_drop = elem_flags.has_drop,
        }, elem_ty.toU32(), array_len);
    }

    /// Interns a symbolic generic `[T; N]` or `#soa [T; N]` array parameterized by `const_param_sym_id`.
    pub fn internSymbolicArray(
        self: *InternPool,
        elem_ty: TypeId,
        const_param_sym_id: SymbolId,
        is_soa: bool,
    ) !TypeId {
        if (elem_ty.isError()) return .err_ty;
        const elem_flags = self.getFlags(elem_ty);
        return self.internSimple(if (is_soa) .soa_array_ty else .array_ty, .{
            .is_copy = elem_flags.is_copy,
            .has_type_vars = true,
            .has_regions = elem_flags.has_regions,
            .is_sized = false,
            .is_secret = elem_flags.is_secret,
            .has_drop = elem_flags.has_drop,
        }, elem_ty.toU32(), SYMBOLIC_ARRAY_LEN_FLAG | (const_param_sym_id.asInt() & ~SYMBOLIC_ARRAY_LEN_FLAG));
    }

    /// Interns a concrete `const` generic integer argument (`[unit; N]`, matching `SubstitutionMap` `len_key` bindings).
    pub fn internConstIntArg(self: *InternPool, val: i128) !TypeId {
        const clamped_len: u32 = if (val <= 0)
            0
        else if (val > 0x7FFF_FFFF)
            0x7FFF_FFFF
        else
            @intCast(val);
        return self.internArray(.unit_ty, clamped_len, false);
    }

    /// Interns `&T` or `&mut T` (`ref_ty` / `mut_ref_ty`).
    pub fn internRef(self: *InternPool, inner_ty: TypeId, is_mut: bool) !TypeId {
        if (inner_ty.isError()) return .err_ty;
        const inner_flags = self.getFlags(inner_ty);
        return self.internSimple(if (is_mut) .mut_ref_ty else .ref_ty, .{
            .is_copy = !is_mut,
            .has_type_vars = inner_flags.has_type_vars,
            .has_regions = true,
            .is_sized = true,
            .is_secret = inner_flags.is_secret,
        }, inner_ty.toU32(), if (is_mut) 1 else 0);
    }

    /// Interns `&out T` (`mut_ref_ty` with `rhs = 2`, `ADR-22B`).
    pub fn internOutRef(self: *InternPool, inner_ty: TypeId) !TypeId {
        if (inner_ty.isError()) return .err_ty;
        const inner_flags = self.getFlags(inner_ty);
        return self.internSimple(.mut_ref_ty, .{
            .is_copy = false,
            .has_type_vars = inner_flags.has_type_vars,
            .has_regions = true,
            .is_sized = true,
            .is_secret = inner_flags.is_secret,
        }, inner_ty.toU32(), 2);
    }

    /// Returns `true` if `ty` is an `&out T` out-parameter reference (`ADR-22B`).
    pub inline fn isOutRef(self: *const InternPool, ty: TypeId) bool {
        if (ty.isPrimitiveOrSentinel()) return false;
        const node = self.getNode(ty);
        return node.tag == .mut_ref_ty and node.rhs == 2;
    }

    /// Interns `TaskGroup[E]` (`SE-20`, `@linear` must-consume structured concurrency scope).
    pub fn internTaskGroup(self: *InternPool, err_ty_arg: TypeId) !TypeId {
        if (err_ty_arg.isError()) return .err_ty;
        const err_flags = self.getFlags(err_ty_arg);
        return self.internSimple(.primitive, .{
            .is_copy = false,
            .has_type_vars = err_flags.has_type_vars,
            .has_regions = err_flags.has_regions,
            .is_must_use = true,
            .is_sized = true,
            .is_secret = err_flags.is_secret,
        }, err_ty_arg.toU32(), TypeId.task_group_base_ty.toU32());
    }

    /// Returns `true` if `ty` is `TaskGroup` or `TaskGroup[E]` (`SE-20`).
    pub inline fn isTaskGroupType(self: *const InternPool, ty: TypeId) bool {
        if (ty == .task_group_base_ty) return true;
        if (ty.toU32() < STATIC_TYPE_SLOT_COUNT) return false;
        const node = self.getNode(ty);
        return node.tag == .primitive and node.rhs == TypeId.task_group_base_ty.toU32();
    }

    /// Returns the error `TypeId` `E` of `TaskGroup[E]`, or `null` if `ty` is not a `TaskGroup`.
    pub inline fn getTaskGroupErrorType(self: *const InternPool, ty: TypeId) ?TypeId {
        if (!self.isTaskGroupType(ty)) return null;
        return TypeId.fromInt(self.getNode(ty).lhs);
    }

    /// Interns `TaskHandle[T]` (`SE-20`, `@linear` must-join task handle).
    pub fn internTaskHandle(self: *InternPool, val_ty: TypeId) !TypeId {
        if (val_ty.isError()) return .err_ty;
        const val_flags = self.getFlags(val_ty);
        return self.internSimple(.primitive, .{
            .is_copy = false,
            .has_type_vars = val_flags.has_type_vars,
            .has_regions = val_flags.has_regions,
            .is_must_use = true,
            .is_sized = true,
            .is_secret = val_flags.is_secret,
        }, val_ty.toU32(), TypeId.task_handle_base_ty.toU32());
    }

    /// Returns `true` if `ty` is `TaskHandle` or `TaskHandle[T]` (`SE-20`).
    pub inline fn isTaskHandleType(self: *const InternPool, ty: TypeId) bool {
        if (ty == .task_handle_base_ty) return true;
        if (ty.toU32() < STATIC_TYPE_SLOT_COUNT) return false;
        const node = self.getNode(ty);
        return node.tag == .primitive and node.rhs == TypeId.task_handle_base_ty.toU32();
    }

    /// Returns the payload `TypeId` `T` of `TaskHandle[T]`, or `null` if `ty` is not a `TaskHandle`.
    pub inline fn getTaskHandleValueType(self: *const InternPool, ty: TypeId) ?TypeId {
        if (!self.isTaskHandleType(ty)) return null;
        return TypeId.fromInt(self.getNode(ty).lhs);
    }

    /// Interns `Future[T]` (`future_ty`, marked `is_must_use = true`, `is_copy = false` per `DR-08`).
    pub fn internFuture(self: *InternPool, output_ty: TypeId, producer_id: u32) !TypeId {
        if (output_ty.isError()) return .err_ty;
        const out_flags = self.getFlags(output_ty);
        return self.internSimple(.future_ty, .{
            .is_copy = false,
            .has_type_vars = out_flags.has_type_vars,
            .has_regions = out_flags.has_regions,
            .is_must_use = true,
            .is_sized = true,
            .is_secret = out_flags.is_secret,
            .has_drop = out_flags.has_drop,
        }, output_ty.toU32(), producer_id);
    }

    /// Returns `true` if `ty` is a `Future[T]` (`TypeTag.future_ty`).
    pub inline fn isFutureType(self: *const InternPool, ty: TypeId) bool {
        if (ty.isPrimitiveOrSentinel() or ty.toU32() < STATIC_TYPE_SLOT_COUNT) return false;
        return self.getTag(ty) == .future_ty;
    }

    /// Returns the unwrapped output `TypeId` `T` of `Future[T]`, or `null` if `ty` is not a `Future`.
    pub inline fn getFutureOutputType(self: *const InternPool, ty: TypeId) ?TypeId {
        if (!self.isFutureType(ty)) return null;
        return TypeId.fromInt(self.getNode(ty).lhs);
    }

    /// Returns the `producer_id` (`SymbolIndex` or synthetic `DefId`, `0` if erased) stored on `Future[T]`.
    pub inline fn getFutureProducerId(self: *const InternPool, ty: TypeId) u32 {
        if (!self.isFutureType(ty)) return 0;
        return self.getNode(ty).rhs;
    }

    /// Records the explicit integer backing `TypeId` for a backed `enum Name: BackingInt` (`ADR-22D`).
    pub fn setEnumBackingIntType(self: *InternPool, enum_ty: TypeId, backing_int_ty: TypeId) !void {
        try self.backed_enum_int_types.put(self.allocator, enum_ty.toU32(), backing_int_ty);
    }

    /// Returns the explicit integer backing `TypeId` of `enum_ty`, or `null` for an unbacked `enum`.
    pub inline fn getEnumBackingIntType(self: *const InternPool, enum_ty: TypeId) ?TypeId {
        const base_ty = self.unwrapNominalInstantiationBase(enum_ty);
        return self.backed_enum_int_types.get(base_ty.toU32());
    }

    /// Records the evaluated `i128` discriminant value for `variant_ordinal` on `enum_ty` (`ADR-22D`).
    pub fn setEnumVariantDiscriminant(
        self: *InternPool,
        enum_ty: TypeId,
        variant_ordinal: u32,
        discriminant: i128,
    ) !void {
        const key: u64 = (@as(u64, enum_ty.toU32()) << 32) | @as(u64, variant_ordinal);
        try self.backed_enum_discriminants.put(self.allocator, key, discriminant);
    }

    /// Returns the evaluated `i128` discriminant for `variant_ordinal` on a backed `enum_ty`, or `null`.
    pub inline fn getEnumVariantDiscriminant(
        self: *const InternPool,
        enum_ty: TypeId,
        variant_ordinal: u32,
    ) ?i128 {
        const base_ty = self.unwrapNominalInstantiationBase(enum_ty);
        const key: u64 = (@as(u64, base_ty.toU32()) << 32) | @as(u64, variant_ordinal);
        return self.backed_enum_discriminants.get(key);
    }

    /// Records a `@derive(From)` single-field enum variant error conversion `(src_err_ty -> dst_enum_ty)` (`SE-10`).
    pub fn registerDerivedFromVariant(
        self: *InternPool,
        src_err_ty: TypeId,
        dst_enum_ty: TypeId,
        variant_ordinal: u32,
    ) !void {
        const key = packFromErrorPair(src_err_ty, dst_enum_ty);
        try self.derived_from_variants.put(self.allocator, key, variant_ordinal);
    }

    /// Looks up the 0-based enum variant ordinal for a `@derive(From)` conversion `(src_err_ty -> dst_enum_ty)`.
    pub inline fn getDerivedFromVariant(
        self: *const InternPool,
        src_err_ty: TypeId,
        dst_enum_ty: TypeId,
    ) ?u32 {
        const base_dst = self.unwrapNominalInstantiationBase(dst_enum_ty);
        return self.derived_from_variants.get(packFromErrorPair(src_err_ty, base_dst));
    }

    /// Unwraps a generic nominal instantiation back to its canonical uninstantiated nominal `TypeId`.
    pub inline fn unwrapNominalInstantiationBase(self: *const InternPool, nominal_ty: TypeId) TypeId {
        if (nominal_ty.toU32() < STATIC_TYPE_SLOT_COUNT) return nominal_ty;
        const node = self.getNode(nominal_ty);
        if ((node.tag == .struct_ty or node.tag == .enum_ty or node.tag == .union_ty) and
            (node.lhs & GENERIC_NOMINAL_INST_MASK) == GENERIC_NOMINAL_INST_TAG)
        {
            var scan_id: u32 = STATIC_TYPE_SLOT_COUNT;
            while (scan_id < self.nodes.len) : (scan_id += 1) {
                const cand = self.nodes.get(scan_id);
                if (cand.tag == node.tag and cand.rhs == node.rhs and
                    (cand.lhs & GENERIC_NOMINAL_INST_MASK) != GENERIC_NOMINAL_INST_TAG)
                {
                    return TypeId.fromInt(scan_id);
                }
            }
        }
        return nominal_ty;
    }

    /// Interns `*T` or `*mut T` (`raw_ptr_ty`).
    pub fn internRawPtr(self: *InternPool, inner_ty: TypeId, is_mut: bool) !TypeId {
        if (inner_ty.isError()) return .err_ty;
        const inner_flags = self.getFlags(inner_ty);
        return self.internSimple(.raw_ptr_ty, .{
            .is_copy = true,
            .has_type_vars = inner_flags.has_type_vars,
            .is_sized = true,
            .is_secret = inner_flags.is_secret,
        }, inner_ty.toU32(), if (is_mut) 1 else 0);
    }

    /// Interns `~T` (`tilde_approx`).
    pub fn internTildeApprox(self: *InternPool, target_ty: TypeId) !TypeId {
        if (target_ty.isError()) return .err_ty;
        const inner_flags = self.getFlags(target_ty);
        return self.internSimple(.tilde_approx, .{
            .is_copy = inner_flags.is_copy,
            .has_type_vars = true,
            .is_sized = true,
            .is_secret = inner_flags.is_secret,
        }, target_ty.toU32(), 0);
    }

    /// Interns `(T1, T2, …)` (`tuple_ty`; `()` returns `.unit_ty`).
    pub fn internTuple(self: *InternPool, elem_types: []const TypeId) !TypeId {
        if (elem_types.len == 0) return .unit_ty;
        var is_copy = true;
        var has_vars = false;
        var has_regs = false;
        var has_secret = false;
        var has_drop = false;
        const raw_words = try self.allocator.alloc(u32, elem_types.len);
        defer self.allocator.free(raw_words);

        for (elem_types, 0..) |elem_ty, i| {
            if (elem_ty.isError()) return .err_ty;
            const fl = self.getFlags(elem_ty);
            if (!fl.is_copy) is_copy = false;
            if (fl.has_type_vars) has_vars = true;
            if (fl.has_regions) has_regs = true;
            if (fl.is_secret) has_secret = true;
            if (fl.has_drop) has_drop = true;
            raw_words[i] = elem_ty.toU32();
        }
        return self.internExtra(.tuple_ty, .{
            .is_copy = is_copy,
            .has_type_vars = has_vars,
            .has_regions = has_regs,
            .is_sized = true,
            .is_secret = has_secret,
            .has_drop = has_drop,
        }, @intCast(elem_types.len), raw_words);
    }

    /// Interns a nominal `struct`, `enum`, `union`, `bit_field`, or `trait` type.
    pub fn internNominal(
        self: *InternPool,
        tag: TypeTag,
        lhs_id: u32,
        sym_idx: SymbolIndex,
        is_copy: bool,
        is_must_use: bool,
        is_secret: bool,
    ) !TypeId {
        return self.internSimple(tag, .{
            .is_copy = is_copy,
            .is_must_use = is_must_use,
            .is_sized = (tag != .trait_ty),
            .is_secret = is_secret,
        }, lhs_id, sym_idx.asInt());
    }

    /// Interns a generic nominal instantiation (`Vec[T]`, `Map[K, V]`) carrying concrete `type_args`.
    pub fn internNominalInstantiation(
        self: *InternPool,
        base_ty: TypeId,
        type_args: []const TypeId,
        is_copy: bool,
        has_drop: bool,
    ) !TypeId {
        if (base_ty.isError() or type_args.len == 0) return base_ty;
        const base_node = self.getNode(base_ty);
        const is_reinst = (base_node.lhs & GENERIC_NOMINAL_INST_MASK) == GENERIC_NOMINAL_INST_TAG;
        var has_vars = if (is_reinst) false else base_node.flags.has_type_vars;
        var has_regs = if (is_reinst) false else base_node.flags.has_regions;
        var has_secret = if (is_reinst) false else base_node.flags.is_secret;

        var extra_words: std.ArrayListUnmanaged(u32) = .empty;
        defer extra_words.deinit(self.allocator);
        try extra_words.append(self.allocator, @intCast(type_args.len));
        for (type_args) |arg_ty| {
            if (arg_ty.isError()) return .err_ty;
            const arg_fl = self.getFlags(arg_ty);
            if (arg_fl.has_type_vars) has_vars = true;
            if (arg_fl.has_regions) has_regs = true;
            if (arg_fl.is_secret) has_secret = true;
            try extra_words.append(self.allocator, arg_ty.toU32());
        }

        const flags: TypeFlags = .{
            .is_copy = is_copy,
            .has_type_vars = has_vars,
            .has_regions = has_regs,
            .is_must_use = base_node.flags.is_must_use,
            .is_sized = base_node.flags.is_sized,
            .is_secret = has_secret,
            .has_drop = has_drop,
        };
        const struct_hash = computeStructuralTypeHash(
            base_node.tag,
            .{},
            GENERIC_NOMINAL_INST_TAG | @as(u32, @intCast(extra_words.items.len)),
            base_node.rhs,
            extra_words.items,
        );
        const gop = try self.dedup_buckets.getOrPut(self.allocator, struct_hash);
        if (!gop.found_existing) {
            gop.value_ptr.* = .empty;
        } else {
            for (gop.value_ptr.items) |cand_id| {
                const cand = self.getNode(cand_id);
                if (cand.tag == base_node.tag and
                    cand.rhs == base_node.rhs and
                    (cand.lhs & GENERIC_NOMINAL_INST_MASK) == GENERIC_NOMINAL_INST_TAG)
                {
                    const start_idx: usize = cand.lhs & ~GENERIC_NOMINAL_INST_MASK;
                    if (start_idx + extra_words.items.len <= self.extra.items.len and
                        std.mem.eql(u32, self.extra.items[start_idx .. start_idx + extra_words.items.len], extra_words.items))
                    {
                        return cand_id;
                    }
                }
            }
        }

        const extra_start: u32 = @intCast(self.extra.items.len);
        try self.extra.appendSlice(self.allocator, extra_words.items);
        const new_id = TypeId.fromInt(@intCast(self.nodes.len));
        try self.nodes.append(self.allocator, .{
            .tag = base_node.tag,
            .flags = flags,
            .hash = struct_hash,
            .lhs = GENERIC_NOMINAL_INST_TAG | (extra_start & ~GENERIC_NOMINAL_INST_MASK),
            .rhs = base_node.rhs,
        });
        try gop.value_ptr.append(self.allocator, new_id);
        return new_id;
    }

    /// Returns the interned `TypeId.toU32()` argument slice on an instantiated generic nominal container.
    pub fn getGenericTypeArgs(self: *const InternPool, nominal_ty: TypeId) []const u32 {
        const node = self.getNode(nominal_ty);
        if (node.tag != .struct_ty and node.tag != .enum_ty and node.tag != .union_ty) return &.{};
        if ((node.lhs & GENERIC_NOMINAL_INST_MASK) != GENERIC_NOMINAL_INST_TAG) return &.{};
        const start_idx: usize = node.lhs & ~GENERIC_NOMINAL_INST_MASK;
        if (start_idx >= self.extra.items.len) return &.{};
        const count: usize = self.extra.items[start_idx];
        if (start_idx + 1 + count > self.extra.items.len) return &.{};
        return self.extra.items[start_idx + 1 .. start_idx + 1 + count];
    }

    /// Interns a `type New = distinct Base;` type (`distinct_ty`).
    pub fn internDistinct(
        self: *InternPool,
        base_ty: TypeId,
        sym_idx: SymbolIndex,
    ) !TypeId {
        if (base_ty.isError()) return .err_ty;
        const base_flags = self.getFlags(base_ty);
        return self.internSimple(.distinct_ty, .{
            .is_copy = base_flags.is_copy,
            .has_regions = base_flags.has_regions,
            .is_must_use = base_flags.is_must_use,
            .is_sized = true,
            .is_secret = base_flags.is_secret,
            .has_drop = base_flags.has_drop,
        }, base_ty.toU32(), sym_idx.asInt());
    }

    /// Interns a range refinement type `type R = Base is min_val..=max_val;` (`refined_ty`).
    pub fn internRefined(
        self: *InternPool,
        base_ty: TypeId,
        sym_idx: SymbolIndex,
        min_val: i128,
        max_val: i128,
    ) !TypeId {
        if (base_ty.isError()) return .err_ty;
        const base_flags = self.getFlags(base_ty);
        const min_u: u128 = @bitCast(min_val);
        const max_u: u128 = @bitCast(max_val);
        const payload = [6]u32{
            base_ty.toU32(),
            sym_idx.asInt(),
            @truncate(min_u),
            @truncate(min_u >> 32),
            @truncate(max_u),
            @truncate(max_u >> 32),
        };
        // Also store upper 64 bits so full 128-bit bounds are preserved losslessly:
        const full_payload = [10]u32{
            payload[0],
            payload[1],
            @truncate(min_u),
            @truncate(min_u >> 32),
            @truncate(min_u >> 64),
            @truncate(min_u >> 96),
            @truncate(max_u),
            @truncate(max_u >> 32),
            @truncate(max_u >> 64),
            @truncate(max_u >> 96),
        };
        return self.internExtra(.refined_ty, .{
            .is_copy = base_flags.is_copy,
            .is_sized = true,
            .is_secret = base_flags.is_secret,
            .has_drop = base_flags.has_drop,
        }, base_ty.toU32(), &full_payload);
    }

    /// Decodes the `RefinementBounds` of a `.refined_ty` node.
    pub fn getRefinementBounds(self: *const InternPool, refined_ty: TypeId) ?RefinementBounds {
        const node = self.getNode(refined_ty);
        if (node.tag != .refined_ty or node.lhs + 10 > self.extra.items.len) return null;
        const words = self.extra.items[node.lhs .. node.lhs + 10];
        const min_u: u128 = (@as(u128, words[2])) |
            (@as(u128, words[3]) << 32) |
            (@as(u128, words[4]) << 64) |
            (@as(u128, words[5]) << 96);
        const max_u: u128 = (@as(u128, words[6])) |
            (@as(u128, words[7]) << 32) |
            (@as(u128, words[8]) << 64) |
            (@as(u128, words[9]) << 96);
        return .{
            .base_ty = TypeId.fromInt(words[0]),
            .sym_idx = SymbolIndex.fromInt(words[1]),
            .min_val = @bitCast(min_u),
            .max_val = @bitCast(max_u),
        };
    }

    /// Interns a user-defined Constrained Type Group (`type G = A | ~B`).
    pub fn internUserGroup(
        self: *InternPool,
        sym_idx: SymbolIndex,
        prim_mask: u32,
        tilde_prim_mask: u32,
        exact_members: []const u32,
        tilde_members: []const u32,
    ) !TypeId {
        var extra_words: std.ArrayListUnmanaged(u32) = .empty;
        defer extra_words.deinit(self.allocator);
        try extra_words.append(self.allocator, sym_idx.asInt());
        try extra_words.append(self.allocator, prim_mask);
        try extra_words.append(self.allocator, tilde_prim_mask);
        try extra_words.append(self.allocator, @intCast(exact_members.len));
        try extra_words.append(self.allocator, @intCast(tilde_members.len));
        try extra_words.appendSlice(self.allocator, exact_members);
        try extra_words.appendSlice(self.allocator, tilde_members);

        return self.internExtra(.user_group, .{
            .is_copy = true,
            .is_sized = true,
        }, sym_idx.asInt(), extra_words.items);
    }

    /// Decodes a `.user_group` `TypeId` into its `UserTypeGroupView`.
    pub fn getUserGroupView(self: *const InternPool, group_ty: TypeId) ?UserTypeGroupView {
        const node = self.getNode(group_ty);
        if (node.tag != .user_group or node.lhs + 5 > self.extra.items.len) return null;
        const header = self.extra.items[node.lhs .. node.lhs + 5];
        const exact_len: usize = header[3];
        const tilde_len: usize = header[4];
        const exact_start: usize = node.lhs + 5;
        const tilde_start: usize = exact_start + exact_len;
        if (tilde_start + tilde_len > self.extra.items.len) return null;
        return .{
            .sym_idx = SymbolIndex.fromInt(header[0]),
            .prim_mask = header[1],
            .tilde_prim_mask = header[2],
            .exact_members = self.extra.items[exact_start .. exact_start + exact_len],
            .tilde_members = self.extra.items[tilde_start .. tilde_start + tilde_len],
        };
    }

    /// Interns a Bind-Once Type Group variable (`x: Number, y: Number`, `DR-04` Section 1.3).
    pub fn internBindOnceVar(self: *InternPool, group_ty: TypeId, name_sym: SymbolId) !TypeId {
        return self.internSimple(.bind_once_group_var, .{
            .is_copy = true,
            .has_type_vars = true,
            .is_sized = true,
        }, group_ty.toU32(), name_sym.asInt());
    }

    /// Interns a Bind-Many `any Group` variable (`x: any Number`, `DR-04` Section 1.3).
    pub fn internBindManyVar(self: *InternPool, group_ty: TypeId, ordinal: u32) !TypeId {
        return self.internSimple(.bind_many_any_var, .{
            .is_copy = true,
            .has_type_vars = true,
            .is_sized = true,
        }, group_ty.toU32(), ordinal);
    }

    /// Interns a generic type parameter (`[T: Bound]`).
    pub fn internTypeParam(self: *InternPool, bound_ty: TypeId, name_sym: SymbolId) !TypeId {
        return self.internSimple(.type_param, .{
            .is_copy = true,
            .has_type_vars = true,
            .is_sized = true,
        }, bound_ty.toU32(), name_sym.asInt());
    }

    /// Interns a function or closure signature (`fn(P…) -> R`) with default empty `FnPtrContractMask`.
    pub fn internFn(
        self: *InternPool,
        tag: TypeTag,
        param_types: []const TypeId,
        param_modes: []const ParamMode,
        ret_ty: TypeId,
        is_must_use: bool,
    ) !TypeId {
        return self.internFnWithContractsAndCapture(
            tag,
            param_types,
            param_modes,
            ret_ty,
            is_must_use,
            .{},
            .copy_tier,
        );
    }

    /// Interns a function or closure signature carrying `FnPtrContractMask` in bits `16..23` of `extra[0]`.
    pub fn internFnWithContracts(
        self: *InternPool,
        tag: TypeTag,
        param_types: []const TypeId,
        param_modes: []const ParamMode,
        ret_ty: TypeId,
        is_must_use: bool,
        contracts: FnPtrContractMask,
    ) !TypeId {
        return self.internFnWithContractsAndCapture(
            tag,
            param_types,
            param_modes,
            ret_ty,
            is_must_use,
            contracts,
            .copy_tier,
        );
    }

    /// Interns a function or closure signature carrying `contracts` (`16..23`) and `capture_tier` (`24..25`).
    pub fn internFnWithContractsAndCapture(
        self: *InternPool,
        tag: TypeTag,
        param_types: []const TypeId,
        param_modes: []const ParamMode,
        ret_ty: TypeId,
        is_must_use: bool,
        contracts: FnPtrContractMask,
        capture_tier: OwnershipTier,
    ) !TypeId {
        return self.internFnSignatureFull(
            tag,
            param_types,
            param_modes,
            ret_ty,
            is_must_use,
            contracts,
            capture_tier,
            false,
        );
    }

    /// Interns a function or closure signature carrying `contracts`, `capture_tier`, and `has_linear_capture` (`bit 26`).
    pub fn internFnSignatureFull(
        self: *InternPool,
        tag: TypeTag,
        param_types: []const TypeId,
        param_modes: []const ParamMode,
        ret_ty: TypeId,
        is_must_use: bool,
        contracts: FnPtrContractMask,
        capture_tier: OwnershipTier,
        has_linear_capture: bool,
    ) !TypeId {
        return self.internFnSignatureExt(
            tag,
            param_types,
            param_modes,
            ret_ty,
            is_must_use,
            contracts,
            capture_tier,
            has_linear_capture,
            false,
            false,
            false,
        );
    }

    /// Interns a function or closure signature packing `is_variadic` (`27`), `is_c_abi` (`28`), and `is_async` (`29`).
    pub fn internFnSignatureExt(
        self: *InternPool,
        tag: TypeTag,
        param_types: []const TypeId,
        param_modes: []const ParamMode,
        ret_ty: TypeId,
        is_must_use: bool,
        contracts: FnPtrContractMask,
        capture_tier: OwnershipTier,
        has_linear_capture: bool,
        is_variadic: bool,
        is_c_abi: bool,
        is_async: bool,
    ) !TypeId {
        var has_vars = self.getFlags(ret_ty).has_type_vars;
        var extra_words: std.ArrayListUnmanaged(u32) = .empty;
        defer extra_words.deinit(self.allocator);

        const arity: u32 = @intCast(param_types.len);
        const packed_hdr: u32 = (arity & 0xFFFF) |
            (@as(u32, @as(u8, @bitCast(contracts))) << 16) |
            (@as(u32, @backingInt(capture_tier)) << 24) |
            (@as(u32, @intFromBool(has_linear_capture)) << 26) |
            (@as(u32, @intFromBool(is_variadic)) << 27) |
            (@as(u32, @intFromBool(is_c_abi)) << 28) |
            (@as(u32, @intFromBool(is_async)) << 29);
        try extra_words.append(self.allocator, packed_hdr);
        for (param_types) |pty| {
            if (self.getFlags(pty).has_type_vars) has_vars = true;
            try extra_words.append(self.allocator, pty.toU32());
        }
        for (0..param_types.len) |i| {
            const mode: ParamMode = if (i < param_modes.len) param_modes[i] else .let_mode;
            try extra_words.append(self.allocator, @backingInt(mode));
        }

        const is_copy_fn = if (tag == .fn_ty) true else (capture_tier == .copy_tier and !has_linear_capture);
        return self.internExtra(tag, .{
            .is_copy = is_copy_fn,
            .has_type_vars = has_vars,
            .is_must_use = is_must_use,
            .is_sized = true,
            .has_drop = (tag == .closure_ty and capture_tier == .auto_drop_tier),
        }, ret_ty.toU32(), extra_words.items);
    }

    /// Interns a `.closure_ty` signature recording `has_env_capture` at bit `30` (`SE-19` `fn` coercion gate).
    pub fn internClosureSignatureExt(
        self: *InternPool,
        param_types: []const TypeId,
        param_modes: []const ParamMode,
        ret_ty: TypeId,
        contracts: FnPtrContractMask,
        capture_tier: OwnershipTier,
        has_linear_capture: bool,
        is_async: bool,
        has_env_capture: bool,
    ) !TypeId {
        var has_vars = self.getFlags(ret_ty).has_type_vars;
        var extra_words: std.ArrayListUnmanaged(u32) = .empty;
        defer extra_words.deinit(self.allocator);

        const arity: u32 = @intCast(param_types.len);
        const packed_hdr: u32 = (arity & 0xFFFF) |
            (@as(u32, @as(u8, @bitCast(contracts))) << 16) |
            (@as(u32, @backingInt(capture_tier)) << 24) |
            (@as(u32, @intFromBool(has_linear_capture)) << 26) |
            (@as(u32, @intFromBool(is_async)) << 29) |
            (@as(u32, @intFromBool(has_env_capture)) << 30);
        try extra_words.append(self.allocator, packed_hdr);
        for (param_types) |pty| {
            if (self.getFlags(pty).has_type_vars) has_vars = true;
            try extra_words.append(self.allocator, pty.toU32());
        }
        for (0..param_types.len) |i| {
            const mode: ParamMode = if (i < param_modes.len) param_modes[i] else .let_mode;
            try extra_words.append(self.allocator, @backingInt(mode));
        }

        const is_copy_fn = (capture_tier == .copy_tier and !has_linear_capture);
        return self.internExtra(.closure_ty, .{
            .is_copy = is_copy_fn,
            .has_type_vars = has_vars,
            .is_must_use = false,
            .is_sized = true,
            .has_drop = (capture_tier == .auto_drop_tier),
        }, ret_ty.toU32(), extra_words.items);
    }

    /// Decodes a `.fn_ty` or `.closure_ty` `TypeId` into its `FnSignatureView`.
    pub fn getFnSignatureView(self: *const InternPool, fn_ty: TypeId) ?FnSignatureView {
        const node = self.getNode(fn_ty);
        if (node.tag != .fn_ty and node.tag != .closure_ty) return null;
        if (node.lhs >= self.extra.items.len) return null;
        const raw_hdr = self.extra.items[node.lhs];
        const arity: usize = raw_hdr & 0xFFFF;
        const contracts: FnPtrContractMask = @bitCast(@as(u8, @truncate(raw_hdr >> 16)));
        const raw_tier: u8 = @truncate((raw_hdr >> 24) & 0x03);
        const capture_tier: OwnershipTier = if (raw_tier <= 2) @fromBackingInt(@intCast(raw_tier)) else .copy_tier;
        const has_linear_capture = ((raw_hdr >> 26) & 1) != 0;
        const is_variadic = ((raw_hdr >> 27) & 1) != 0;
        const is_c_abi = ((raw_hdr >> 28) & 1) != 0;
        const is_async = ((raw_hdr >> 29) & 1) != 0;
        const has_env_capture = ((raw_hdr >> 30) & 1) != 0;
        const params_start: usize = node.lhs + 1;
        const modes_start: usize = params_start + arity;
        if (modes_start + arity > self.extra.items.len) return null;
        return .{
            .ret_ty = TypeId.fromInt(node.rhs),
            .param_types = self.extra.items[params_start .. params_start + arity],
            .param_modes = self.extra.items[modes_start .. modes_start + arity],
            .contracts = contracts,
            .capture_tier = capture_tier,
            .has_linear_capture = has_linear_capture,
            .is_variadic = is_variadic,
            .is_c_abi = is_c_abi,
            .is_async = is_async,
            .has_env_capture = has_env_capture,
        };
    }

    /// Unwraps chains of `.distinct_ty` and `.refined_ty` to the underlying representation `TypeId`.
    pub fn unwrapUnderlyingType(self: *const InternPool, ty: TypeId) TypeId {
        var cur = ty;
        var steps: usize = 0;
        while (steps < 64) : (steps += 1) {
            const node = self.getNode(cur);
            if (node.tag == .distinct_ty) {
                cur = TypeId.fromInt(node.lhs);
            } else if (node.tag == .refined_ty) {
                cur = TypeId.fromInt(node.rhs);
            } else {
                break;
            }
        }
        return cur;
    }

    /// Unwraps only `.refined_ty` layers (preserving `.distinct_ty` nominal boundaries).
    pub fn unwrapRefinementBase(self: *const InternPool, ty: TypeId) TypeId {
        var cur = ty;
        var steps: usize = 0;
        while (steps < 64) : (steps += 1) {
            const node = self.getNode(cur);
            if (node.tag == .refined_ty) {
                cur = TypeId.fromInt(node.rhs);
            } else {
                break;
            }
        }
        return cur;
    }

    /// Returns the slice of element `TypeId.toU32()` handles for a `.tuple_ty` node.
    pub fn getTupleElements(self: *const InternPool, tuple_ty: TypeId) []const u32 {
        const node = self.getNode(tuple_ty);
        if (node.tag != .tuple_ty) return &.{};
        const start: usize = node.lhs;
        const count: usize = node.rhs;
        if (start + count > self.extra.items.len) return &.{};
        return self.extra.items[start .. start + count];
    }

    /// Formats `ty` into caller-provided `buf` (zero heap allocations).
    pub fn formatType(
        self: *const InternPool,
        ty: TypeId,
        sym_table: *const SymbolTable,
        buf: []u8,
    ) []const u8 {
        var writer = SliceBufWriter{ .buf = buf };
        self.writeTypeToWriter(ty, sym_table, &writer, 0);
        return writer.buf[0..writer.pos];
    }

    /// Recursively writes the human-readable CoreX name of `ty` to `writer` (bounded by `MAX_TYPE_DEPTH`).
    fn writeTypeToWriter(
        self: *const InternPool,
        ty: TypeId,
        sym_table: *const SymbolTable,
        writer: *SliceBufWriter,
        depth: u32,
    ) void {
        if (writer.pos >= writer.buf.len) return;
        if (depth >= MAX_TYPE_DEPTH) return writer.writeAll("<type>");
        if (ty.toU32() < STATIC_TYPE_SLOT_COUNT) {
            if (BUILTIN_TYPE_NAMES[ty.toU32()]) |builtin_name| {
                return writer.writeAll(builtin_name);
            }
        }
        if (ty == .untyped_int_ty) return writer.writeAll("{integer}");
        if (ty == .untyped_float_ty) return writer.writeAll("{float}");
        if (ty == .err_ty) return writer.writeAll("<error>");

        const node = self.getNode(ty);
        switch (node.tag) {
            .primitive => {
                if (node.rhs == TypeId.task_group_base_ty.toU32()) {
                    writer.writeAll("TaskGroup[");
                    self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
                    return writer.writeAll("]");
                }
                if (node.rhs == TypeId.task_handle_base_ty.toU32()) {
                    writer.writeAll("TaskHandle[");
                    self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
                    return writer.writeAll("]");
                }
                return writer.writeAll("<primitive>");
            },
            .struct_ty, .enum_ty, .union_ty, .bit_field_ty, .trait_ty, .distinct_ty, .user_group => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() != INTERSECT_GROUP_SENTINEL and
                    sym_idx.asInt() < sym_table.symbols.items.len)
                {
                    writer.writeAll(sym_table.getSymbol(sym_idx).name_text);
                    const gen_args = self.getGenericTypeArgs(ty);
                    if (gen_args.len > 0) {
                        writer.writeAll("[");
                        for (gen_args, 0..) |raw_arg, i| {
                            if (i > 0) writer.writeAll(", ");
                            self.writeTypeToWriter(TypeId.fromInt(raw_arg), sym_table, writer, depth + 1);
                        }
                        writer.writeAll("]");
                    }
                    return;
                }
                if (node.tag == .user_group) {
                    if (self.getUserGroupView(ty)) |group_view| {
                        const sep = if (sym_idx.asInt() == INTERSECT_GROUP_SENTINEL) " & " else " | ";
                        var count: usize = 0;
                        var prim_idx: u32 = 0;
                        while (prim_idx <= 18) : (prim_idx += 1) {
                            const prim_tid = TypeId.fromInt(prim_idx);
                            if (TypeGroupMask.containsPrimitive(group_view.prim_mask, prim_tid)) {
                                if (count > 0) writer.writeAll(sep);
                                self.writeTypeToWriter(prim_tid, sym_table, writer, depth + 1);
                                count += 1;
                            }
                            if (TypeGroupMask.containsPrimitive(group_view.tilde_prim_mask, prim_tid)) {
                                if (count > 0) writer.writeAll(sep);
                                writer.writeAll("~");
                                self.writeTypeToWriter(prim_tid, sym_table, writer, depth + 1);
                                count += 1;
                            }
                        }
                        for (group_view.exact_members) |raw_mem| {
                            if (count > 0) writer.writeAll(sep);
                            self.writeTypeToWriter(TypeId.fromInt(raw_mem), sym_table, writer, depth + 1);
                            count += 1;
                        }
                        for (group_view.tilde_members) |raw_mem| {
                            if (count > 0) writer.writeAll(sep);
                            writer.writeAll("~");
                            self.writeTypeToWriter(TypeId.fromInt(raw_mem), sym_table, writer, depth + 1);
                            count += 1;
                        }
                        if (count > 0) return;
                    }
                }
                return writer.writeAll("<nominal>");
            },
            .tuple_ty => {
                const elems = self.getTupleElements(ty);
                writer.writeAll("(");
                for (elems, 0..) |raw_elem, i| {
                    if (writer.pos >= writer.buf.len) return;
                    if (i > 0) writer.writeAll(", ");
                    self.writeTypeToWriter(TypeId.fromInt(raw_elem), sym_table, writer, depth + 1);
                }
                if (elems.len == 1) writer.writeAll(",");
                return writer.writeAll(")");
            },
            .refined_ty => {
                if (self.getRefinementBounds(ty)) |bounds| {
                    if (!bounds.sym_idx.isNone() and bounds.sym_idx.asInt() < sym_table.symbols.items.len) {
                        const sym_name = sym_table.getSymbol(bounds.sym_idx).name_text;
                        if (sym_name.len > 0) {
                            return writer.print("{s} ({d}..={d})", .{ sym_name, bounds.min_val, bounds.max_val });
                        }
                    }
                    self.writeTypeToWriter(bounds.base_ty, sym_table, writer, depth + 1);
                    return writer.print(" is {d}..={d}", .{ bounds.min_val, bounds.max_val });
                }
                return writer.writeAll("<refined>");
            },
            .tilde_approx => {
                writer.writeAll("~");
                return self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
            },
            .optional_ty => {
                const inner_ty = TypeId.fromInt(node.lhs);
                const inner_tag = self.getTag(inner_ty);
                const needs_parens = !inner_ty.isPrimitiveOrSentinel() and
                    (inner_tag == .result_ty or inner_tag == .fn_ty or inner_tag == .closure_ty or
                        inner_tag == .ref_ty or inner_tag == .mut_ref_ty or inner_tag == .raw_ptr_ty or
                        inner_tag == .refined_ty);
                if (needs_parens) writer.writeAll("(");
                self.writeTypeToWriter(inner_ty, sym_table, writer, depth + 1);
                if (needs_parens) writer.writeAll(")");
                return writer.writeAll("?");
            },
            .result_ty => {
                const ok_ty = TypeId.fromInt(node.lhs);
                const err_ty_val = TypeId.fromInt(node.rhs);
                const ok_tag = self.getTag(ok_ty);
                const err_tag = self.getTag(err_ty_val);
                const is_ok_paren = !ok_ty.isPrimitiveOrSentinel() and
                    (ok_tag == .result_ty or ok_tag == .fn_ty or ok_tag == .closure_ty or ok_tag == .refined_ty);
                const is_err_paren = !err_ty_val.isPrimitiveOrSentinel() and
                    (err_tag == .result_ty or err_tag == .fn_ty or err_tag == .closure_ty or err_tag == .refined_ty);
                if (is_ok_paren) writer.writeAll("(");
                self.writeTypeToWriter(ok_ty, sym_table, writer, depth + 1);
                if (is_ok_paren) writer.writeAll(")");
                writer.writeAll("!");
                if (is_err_paren) writer.writeAll("(");
                self.writeTypeToWriter(err_ty_val, sym_table, writer, depth + 1);
                if (is_err_paren) writer.writeAll(")");
                return;
            },
            .slice_ty => {
                writer.writeAll("[");
                self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
                return writer.writeAll("]");
            },
            .soa_slice_ty => {
                writer.writeAll("#soa [");
                self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
                return writer.writeAll("]");
            },
            .array_ty, .soa_array_ty => {
                writer.writeAll(if (node.tag == .soa_array_ty) "#soa [" else "[");
                self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
                if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0) {
                    const const_sym = SymbolId.fromInt(node.rhs & ~SYMBOLIC_ARRAY_LEN_FLAG);
                    for (sym_table.symbols.items) |cand_sym| {
                        const is_sym_len = cand_sym.kind == .const_param_sym or
                            (cand_sym.kind == .param_sym and cand_sym.flags.is_comptime);
                        if (is_sym_len and cand_sym.name == const_sym) {
                            return writer.print("; {s}]", .{cand_sym.name_text});
                        }
                    }
                    return writer.writeAll("; <const>]");
                }
                return writer.print("; {d}]", .{node.rhs});
            },
            .ref_ty => {
                writer.writeAll("&");
                return self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
            },
            .mut_ref_ty => {
                writer.writeAll(if (node.rhs == 2) "&out " else "&mut ");
                return self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
            },
            .raw_ptr_ty => {
                writer.writeAll(if (node.rhs != 0) "*mut " else "*");
                return self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
            },
            .bind_once_group_var, .type_param => {
                return self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
            },
            .bind_many_any_var => {
                writer.writeAll("any ");
                return self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
            },
            .fn_ty, .closure_ty => {
                const sig_view = self.getFnSignatureView(ty) orelse return writer.writeAll("<fn>");
                if (sig_view.contracts.has_builder) writer.writeAll("@builder ");
                if (sig_view.contracts.has_no_alloc) writer.writeAll("@no_alloc ");
                if (sig_view.contracts.has_no_panic) writer.writeAll("@no_panic ");
                if (sig_view.contracts.has_no_block) writer.writeAll("@no_block ");
                if (sig_view.is_c_abi and node.tag == .fn_ty) writer.writeAll("extern \"C\" ");
                if (sig_view.is_async) writer.writeAll("async ");
                if (node.tag == .closure_ty and sig_view.capture_tier != .copy_tier) {
                    writer.writeAll("own ");
                }
                writer.writeAll(if (node.tag == .closure_ty) "|" else "fn(");
                for (0..sig_view.paramCount()) |i| {
                    if (i > 0) writer.writeAll(", ");
                    const param_ty = sig_view.getParamType(i);
                    const param_tag = self.getTag(param_ty);
                    switch (sig_view.getParamMode(i)) {
                        .let_mode => {},
                        .inout_mode => {
                            if (param_tag != .mut_ref_ty) writer.writeAll("&mut ");
                        },
                        .sink_mode => writer.writeAll("own "),
                        .set_mode => {
                            if (!self.isOutRef(param_ty)) writer.writeAll("&out ");
                        },
                    }
                    self.writeTypeToWriter(param_ty, sym_table, writer, depth + 1);
                }
                if (sig_view.is_variadic) {
                    if (sig_view.paramCount() > 0) writer.writeAll(", ");
                    writer.writeAll("...");
                }
                writer.writeAll(if (node.tag == .closure_ty) "| -> " else ") -> ");
                return self.writeTypeToWriter(sig_view.ret_ty, sym_table, writer, depth + 1);
            },
            .future_ty => {
                writer.writeAll("Future[");
                self.writeTypeToWriter(TypeId.fromInt(node.lhs), sym_table, writer, depth + 1);
                return writer.writeAll("]");
            },
            else => return writer.writeAll("<type>"),
        }
    }

    /// Returns `null` if `ty` satisfies `FromBytes` (`DR-20` `D-01`), or a `WireLayoutViolation` explaining why not.
    pub fn explainFromBytesViolation(
        self: *const InternPool,
        ty: TypeId,
        sym_table: *const SymbolTable,
        target_layout: TargetLayout,
    ) ?WireLayoutViolation {
        return self.explainFromBytesViolationBounded(ty, sym_table, target_layout, &NominalTypeSubst.EMPTY, 0);
    }

    /// Returns `true` if every possible bit pattern of `ty` is a valid, non-secret, `Copy` value (`DR-20` `D-01`).
    pub fn isFromBytesValid(
        self: *const InternPool,
        ty: TypeId,
        sym_table: *const SymbolTable,
        target_layout: TargetLayout,
    ) bool {
        return self.explainFromBytesViolation(ty, sym_table, target_layout) == null;
    }

    /// Depth-bounded helper for `explainFromBytesViolation` with generic nominal substitution `subst`.
    fn explainFromBytesViolationBounded(
        self: *const InternPool,
        raw_ty: TypeId,
        sym_table: *const SymbolTable,
        target_layout: TargetLayout,
        subst: *const NominalTypeSubst,
        depth: u32,
    ) ?WireLayoutViolation {
        const ty = subst.resolve(raw_ty);
        if (ty.isError() or depth >= MAX_TYPE_DEPTH) return null;
        if (self.getFlags(ty).is_secret) {
            return .{ .reason = .secret_type };
        }
        if (classifyOwnershipTierWithSubst(self, sym_table, ty, subst) != .copy_tier) {
            return .{ .reason = .non_copy_ownership };
        }
        if (ty == .untyped_int_ty or ty == .untyped_float_ty) return null;
        if (ty == .opaque_ty or ty == .fmt_spec_ty) {
            return .{ .reason = .invalid_bit_patterns };
        }
        if (ty == .source_loc_ty or ty == .fmt_args_ty or ty == .bencher_ty or
            self.isTaskGroupType(ty) or self.isTaskHandleType(ty))
        {
            return .{ .reason = .indirection_or_handle };
        }
        if (ty.isSizedPrimitive()) {
            if (ty == .str_ty) return .{ .reason = .indirection_or_handle };
            if (TypeGroupMask.containsPrimitive(TypeGroupMask.FROM_BYTES, ty)) return null;
            return .{ .reason = .invalid_bit_patterns };
        }

        const node = self.getNode(ty);
        switch (node.tag) {
            .raw_ptr_ty,
            .ref_ty,
            .mut_ref_ty,
            .slice_ty,
            .soa_slice_ty,
            .fn_ty,
            .closure_ty,
            .dyn_trait_ty,
            .trait_ty,
            => return .{ .reason = .indirection_or_handle },
            .optional_ty => return .{ .reason = .invalid_bit_patterns },
            .result_ty => {
                if (subst.resolve(TypeId.fromInt(node.rhs)) == .never_ty) {
                    return self.explainFromBytesViolationBounded(
                        TypeId.fromInt(node.lhs),
                        sym_table,
                        target_layout,
                        subst,
                        depth + 1,
                    );
                }
                return .{ .reason = .invalid_bit_patterns };
            },
            .refined_ty => {
                const bounds = self.getRefinementBounds(ty) orelse
                    return .{ .reason = .refinement_narrows_domain };
                if (self.explainFromBytesViolationBounded(
                    bounds.base_ty,
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                )) |violation| {
                    return violation;
                }
                const underlying_prim = self.unwrapUnderlyingType(subst.resolve(bounds.base_ty));
                if (underlying_prim == .u128_ty) {
                    return .{ .reason = .refinement_narrows_domain };
                }
                const full_bounds = getTargetPrimitiveIntBounds(underlying_prim, target_layout) orelse
                    return .{ .reason = .refinement_narrows_domain };
                if (bounds.min_val <= full_bounds.min_val and bounds.max_val >= full_bounds.max_val) {
                    return null;
                }
                return .{ .reason = .refinement_narrows_domain };
            },
            .distinct_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() < sym_table.symbols.items.len) {
                    if (sym_table.getSymbol(sym_idx).contract_flags.is_secret) {
                        return .{ .reason = .secret_type, .field_name = sym_table.getSymbol(sym_idx).name_text };
                    }
                }
                return self.explainFromBytesViolationBounded(
                    TypeId.fromInt(node.lhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                );
            },
            .array_ty, .soa_array_ty => {
                if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                return self.explainFromBytesViolationBounded(
                    TypeId.fromInt(node.lhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                );
            },
            .tuple_ty => {
                const elems = self.getTupleElements(ty);
                var rank_mask: u64 = 0;
                for (elems) |raw_elem| {
                    const elem_ty = subst.resolve(TypeId.fromInt(raw_elem));
                    const elem_layout = computeTypeLayoutBounded(
                        self,
                        sym_table,
                        elem_ty,
                        target_layout,
                        subst,
                        depth + 1,
                    );
                    const has_niche = computeLeafNicheBounded(
                        self,
                        sym_table,
                        elem_ty,
                        target_layout,
                        subst,
                        depth + 1,
                    ).kind != .none;
                    const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
                    rank_mask |= (@as(u64, 1) << rank);
                }
                var cur_offset: u64 = 0;
                while (rank_mask != 0) {
                    const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                    rank_mask &= ~(@as(u64, 1) << top_rank);
                    for (elems) |raw_elem| {
                        const elem_ty = subst.resolve(TypeId.fromInt(raw_elem));
                        const elem_layout = computeTypeLayoutBounded(
                            self,
                            sym_table,
                            elem_ty,
                            target_layout,
                            subst,
                            depth + 1,
                        );
                        const has_niche = computeLeafNicheBounded(
                            self,
                            sym_table,
                            elem_ty,
                            target_layout,
                            subst,
                            depth + 1,
                        ).kind != .none;
                        const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) |
                            @intFromBool(has_niche);
                        if (rank != top_rank) continue;
                        const aligned_off = alignUpU64(cur_offset, elem_layout.align_bytes);
                        if (self.explainFromBytesViolationBounded(
                            elem_ty,
                            sym_table,
                            target_layout,
                            subst,
                            depth + 1,
                        )) |sub_v| {
                            return .{
                                .reason = sub_v.reason,
                                .byte_offset = aligned_off +| sub_v.byte_offset,
                                .padding_bytes = sub_v.padding_bytes,
                                .field_name = sub_v.field_name,
                            };
                        }
                        cur_offset = aligned_off +| elem_layout.byte_size;
                    }
                }
                return null;
            },
            .bit_field_ty => {
                const backing_ty = self.unwrapUnderlyingType(subst.resolve(TypeId.fromInt(node.lhs)));
                const backing_bits = getTargetPrimitiveIntBits(backing_ty, target_layout) orelse
                    return .{ .reason = .invalid_bit_patterns };
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const bf_sym = sym_table.getSymbol(sym_idx).*;
                if (bf_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = bf_sym.name_text };
                }
                if (bf_sym.target_scope.isNone()) return null;
                var total_bits: u32 = 0;
                for (sym_table.getScopeMembers(bf_sym.target_scope)) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    total_bits += mem_sym.bit_width;
                    const mem_ty = subst.resolve(mem_sym.type_id);
                    if (self.getFlags(mem_ty).is_secret) {
                        return .{ .reason = .secret_type, .field_name = mem_sym.name_text };
                    }
                    // Peel only `.distinct_ty` wrappers first so any `.refined_ty` or `@secret` layer is caught:
                    var peeled_mem = mem_ty;
                    var has_refinement_layer = false;
                    var peel_steps: u32 = 0;
                    while (!peeled_mem.isPrimitiveOrSentinel() and peel_steps < MAX_TYPE_DEPTH) : (peel_steps += 1) {
                        const peeled_node = self.getNode(peeled_mem);
                        if (peeled_node.tag == .distinct_ty) {
                            const dist_sym = SymbolIndex.fromInt(peeled_node.rhs);
                            if (!dist_sym.isNone() and dist_sym.asInt() < sym_table.symbols.items.len and
                                sym_table.getSymbol(dist_sym).contract_flags.is_secret)
                            {
                                return .{ .reason = .secret_type, .field_name = mem_sym.name_text };
                            }
                            peeled_mem = subst.resolve(TypeId.fromInt(peeled_node.lhs));
                            continue;
                        }
                        if (peeled_node.tag == .refined_ty) {
                            has_refinement_layer = true;
                        }
                        break;
                    }
                    if (!has_refinement_layer and peeled_mem == .bool_ty) {
                        if (mem_sym.bit_width != 1) {
                            return .{ .reason = .invalid_bit_patterns, .field_name = mem_sym.name_text };
                        }
                    } else if (!has_refinement_layer and !peeled_mem.isPrimitiveOrSentinel() and
                        self.getTag(peeled_mem) == .enum_ty)
                    {
                        const enum_sym_idx = SymbolIndex.fromInt(self.getNode(peeled_mem).rhs);
                        if (enum_sym_idx.isNone() or enum_sym_idx.asInt() >= sym_table.symbols.items.len) {
                            return .{ .reason = .invalid_bit_patterns, .field_name = mem_sym.name_text };
                        }
                        const enum_sym = sym_table.getSymbol(enum_sym_idx).*;
                        if (enum_sym.contract_flags.is_secret) {
                            return .{ .reason = .secret_type, .field_name = mem_sym.name_text };
                        }
                        if (!isExhaustiveFieldlessEnumForBits(sym_table, enum_sym, mem_sym.bit_width)) {
                            return .{ .reason = .invalid_bit_patterns, .field_name = mem_sym.name_text };
                        }
                    } else if (self.explainFromBytesViolationBounded(
                        mem_ty,
                        sym_table,
                        target_layout,
                        subst,
                        depth + 1,
                    )) |violation| {
                        return .{
                            .reason = violation.reason,
                            .field_name = if (violation.field_name.len > 0) violation.field_name else mem_sym.name_text,
                        };
                    }
                }
                if (total_bits != backing_bits) {
                    return .{ .reason = .invalid_bit_patterns, .field_name = bf_sym.name_text };
                }
                return null;
            },
            .struct_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const st_sym = sym_table.getSymbol(sym_idx).*;
                if (st_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = st_sym.name_text };
                }
                if (st_sym.target_scope.isNone()) return null;
                const child_subst = NominalTypeSubst.fromNominal(self, sym_table, ty, st_sym, subst);
                const active_subst = if (child_subst.len > 0) &child_subst else subst;
                const is_packed = st_sym.contract_flags.is_packed;
                const is_decl_order = is_packed or st_sym.contract_flags.is_repr_c;
                const members = sym_table.getScopeMembers(st_sym.target_scope);
                var cur_offset: u64 = 0;
                if (is_decl_order) {
                    for (members) |mem_idx| {
                        const mem_sym = sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        const f_layout = computeTypeLayoutBounded(
                            self,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                        );
                        const aligned_off = if (is_packed) cur_offset else alignUpU64(cur_offset, f_layout.align_bytes);
                        if (self.explainFromBytesViolationBounded(
                            mem_sym.type_id,
                            sym_table,
                            target_layout,
                            active_subst,
                            depth + 1,
                        )) |sub_v| {
                            return .{
                                .reason = sub_v.reason,
                                .byte_offset = aligned_off +| sub_v.byte_offset,
                                .padding_bytes = sub_v.padding_bytes,
                                .field_name = if (sub_v.field_name.len > 0) sub_v.field_name else mem_sym.name_text,
                            };
                        }
                        cur_offset = aligned_off +| f_layout.byte_size;
                    }
                    return null;
                }
                var rank_mask: u64 = 0;
                for (members) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    const f_layout = computeTypeLayoutBounded(
                        self,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                    );
                    const has_niche = computeLeafNicheBounded(
                        self,
                        sym_table,
                        mem_sym.type_id,
                        target_layout,
                        active_subst,
                        depth + 1,
                    ).kind != .none;
                    const rank: u6 = (@as(u6, @intCast(@min(f_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
                    rank_mask |= (@as(u64, 1) << rank);
                }
                while (rank_mask != 0) {
                    const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                    rank_mask &= ~(@as(u64, 1) << top_rank);
                    for (members) |mem_idx| {
                        const mem_sym = sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        const f_layout = computeTypeLayoutBounded(
                            self,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                        );
                        const has_niche = computeLeafNicheBounded(
                            self,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                        ).kind != .none;
                        const rank: u6 = (@as(u6, @intCast(@min(f_layout.align_log2, 30))) << 1) |
                            @intFromBool(has_niche);
                        if (rank != top_rank) continue;
                        const aligned_off = alignUpU64(cur_offset, f_layout.align_bytes);
                        if (self.explainFromBytesViolationBounded(
                            mem_sym.type_id,
                            sym_table,
                            target_layout,
                            active_subst,
                            depth + 1,
                        )) |sub_v| {
                            return .{
                                .reason = sub_v.reason,
                                .byte_offset = aligned_off +| sub_v.byte_offset,
                                .padding_bytes = sub_v.padding_bytes,
                                .field_name = if (sub_v.field_name.len > 0) sub_v.field_name else mem_sym.name_text,
                            };
                        }
                        cur_offset = aligned_off +| f_layout.byte_size;
                    }
                }
                return null;
            },
            .union_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const un_sym = sym_table.getSymbol(sym_idx).*;
                if (un_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = un_sym.name_text };
                }
                if (un_sym.target_scope.isNone()) return null;
                const child_subst = NominalTypeSubst.fromNominal(self, sym_table, ty, un_sym, subst);
                const active_subst = if (child_subst.len > 0) &child_subst else subst;
                for (sym_table.getScopeMembers(un_sym.target_scope)) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    if (self.explainFromBytesViolationBounded(
                        mem_sym.type_id,
                        sym_table,
                        target_layout,
                        active_subst,
                        depth + 1,
                    )) |sub_v| {
                        return .{
                            .reason = sub_v.reason,
                            .byte_offset = sub_v.byte_offset,
                            .padding_bytes = sub_v.padding_bytes,
                            .field_name = if (sub_v.field_name.len > 0) sub_v.field_name else mem_sym.name_text,
                        };
                    }
                }
                return null;
            },
            .enum_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const enum_sym = sym_table.getSymbol(sym_idx).*;
                if (enum_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = enum_sym.name_text };
                }
                if (self.getEnumBackingIntType(ty)) |backing_int_ty| {
                    const backing_bits = getTargetPrimitiveIntBits(
                        self.unwrapUnderlyingType(backing_int_ty),
                        target_layout,
                    ) orelse return .{ .reason = .invalid_bit_patterns, .field_name = enum_sym.name_text };
                    if (!isExhaustiveFieldlessEnumForBits(sym_table, enum_sym, backing_bits)) {
                        return .{ .reason = .invalid_bit_patterns, .field_name = enum_sym.name_text };
                    }
                    return null;
                }
                if (enum_sym.repr_tag_bits == 0 or
                    !isExhaustiveFieldlessEnumForBits(sym_table, enum_sym, enum_sym.repr_tag_bits))
                {
                    return .{ .reason = .invalid_bit_patterns, .field_name = enum_sym.name_text };
                }
                return null;
            },
            else => return .{ .reason = .invalid_bit_patterns },
        }
    }

    /// Returns `null` if `ty` satisfies `IntoBytes` (`DR-20` `D-01`), or a `WireLayoutViolation` with padding offset.
    pub fn explainIntoBytesViolation(
        self: *const InternPool,
        ty: TypeId,
        sym_table: *const SymbolTable,
        target_layout: TargetLayout,
    ) ?WireLayoutViolation {
        return self.explainIntoBytesViolationBounded(ty, sym_table, target_layout, &NominalTypeSubst.EMPTY, 0);
    }

    /// Returns `true` if `ty` has initialized, non-secret, pointer-free bytes (`DR-20` `D-01`).
    pub fn isIntoBytesValid(
        self: *const InternPool,
        ty: TypeId,
        sym_table: *const SymbolTable,
        target_layout: TargetLayout,
    ) bool {
        return self.explainIntoBytesViolation(ty, sym_table, target_layout) == null;
    }

    /// Depth-bounded helper for `explainIntoBytesViolation` with generic nominal substitution `subst`.
    fn explainIntoBytesViolationBounded(
        self: *const InternPool,
        raw_ty: TypeId,
        sym_table: *const SymbolTable,
        target_layout: TargetLayout,
        subst: *const NominalTypeSubst,
        depth: u32,
    ) ?WireLayoutViolation {
        const ty = subst.resolve(raw_ty);
        if (ty.isError() or depth >= MAX_TYPE_DEPTH) return null;
        if (self.getFlags(ty).is_secret) {
            return .{ .reason = .secret_type };
        }
        if (classifyOwnershipTierWithSubst(self, sym_table, ty, subst) != .copy_tier) {
            return .{ .reason = .non_copy_ownership };
        }
        if (ty == .untyped_int_ty or ty == .untyped_float_ty) return null;
        if (ty == .opaque_ty or ty == .fmt_spec_ty) {
            return .{ .reason = .invalid_bit_patterns };
        }
        if (ty == .source_loc_ty or ty == .fmt_args_ty or ty == .bencher_ty or
            self.isTaskGroupType(ty) or self.isTaskHandleType(ty))
        {
            return .{ .reason = .indirection_or_handle };
        }
        if (ty.isSizedPrimitive()) {
            if (ty == .str_ty) return .{ .reason = .indirection_or_handle };
            if (TypeGroupMask.containsPrimitive(TypeGroupMask.INTO_BYTES, ty)) return null;
            return .{ .reason = .invalid_bit_patterns };
        }

        const node = self.getNode(ty);
        switch (node.tag) {
            .raw_ptr_ty,
            .ref_ty,
            .mut_ref_ty,
            .slice_ty,
            .soa_slice_ty,
            .fn_ty,
            .closure_ty,
            .dyn_trait_ty,
            .trait_ty,
            => return .{ .reason = .indirection_or_handle },
            .refined_ty => {
                if (self.getRefinementBounds(ty)) |bounds| {
                    return self.explainIntoBytesViolationBounded(
                        bounds.base_ty,
                        sym_table,
                        target_layout,
                        subst,
                        depth + 1,
                    );
                }
                return self.explainIntoBytesViolationBounded(
                    TypeId.fromInt(node.rhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                );
            },
            .distinct_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() < sym_table.symbols.items.len) {
                    if (sym_table.getSymbol(sym_idx).contract_flags.is_secret) {
                        return .{ .reason = .secret_type, .field_name = sym_table.getSymbol(sym_idx).name_text };
                    }
                }
                return self.explainIntoBytesViolationBounded(
                    TypeId.fromInt(node.lhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                );
            },
            .bit_field_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() < sym_table.symbols.items.len) {
                    const bf_sym = sym_table.getSymbol(sym_idx).*;
                    if (bf_sym.contract_flags.is_secret) {
                        return .{ .reason = .secret_type, .field_name = bf_sym.name_text };
                    }
                    if (!bf_sym.target_scope.isNone()) {
                        for (sym_table.getScopeMembers(bf_sym.target_scope)) |mem_idx| {
                            const mem_sym = sym_table.getSymbol(mem_idx).*;
                            const mem_ty = subst.resolve(mem_sym.type_id);
                            if (mem_sym.kind == .field_sym and self.getFlags(mem_ty).is_secret) {
                                return .{ .reason = .secret_type, .field_name = mem_sym.name_text };
                            }
                        }
                    }
                }
                return self.explainIntoBytesViolationBounded(
                    TypeId.fromInt(node.lhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                );
            },
            .array_ty => {
                if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                return self.explainIntoBytesViolationBounded(
                    TypeId.fromInt(node.lhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                );
            },
            .soa_array_ty => {
                if ((node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                if (self.explainIntoBytesViolationBounded(
                    TypeId.fromInt(node.lhs),
                    sym_table,
                    target_layout,
                    subst,
                    depth + 1,
                )) |elem_v| {
                    return elem_v;
                }
                const elem_ty = self.unwrapUnderlyingType(subst.resolve(TypeId.fromInt(node.lhs)));
                const elem_node = self.getNode(elem_ty);
                if (elem_node.tag == .struct_ty) {
                    const sym_idx = SymbolIndex.fromInt(elem_node.rhs);
                    if (!sym_idx.isNone() and sym_idx.asInt() < sym_table.symbols.items.len) {
                        const st_sym = sym_table.getSymbol(sym_idx).*;
                        if (!st_sym.contract_flags.is_zero_pad and !st_sym.target_scope.isNone() and node.rhs > 0) {
                            const child_subst = NominalTypeSubst.fromNominal(self, sym_table, elem_ty, st_sym, subst);
                            const active_subst = if (child_subst.len > 0) &child_subst else subst;
                            var cur_offset: u64 = 0;
                            var max_align_log2: u8 = 0;
                            for (sym_table.getScopeMembers(st_sym.target_scope)) |mem_idx| {
                                const mem_sym = sym_table.getSymbol(mem_idx).*;
                                if (mem_sym.kind != .field_sym) continue;
                                const f_layout = computeTypeLayoutBounded(
                                    self,
                                    sym_table,
                                    mem_sym.type_id,
                                    target_layout,
                                    active_subst,
                                    depth + 1,
                                );
                                const col_log2 = @max(f_layout.align_log2, target_layout.simd_align_log2);
                                const col_align = @as(u32, 1) << @intCast(col_log2);
                                max_align_log2 = @max(max_align_log2, col_log2);
                                const col_off = alignUpU64(cur_offset, col_align);
                                if (col_off > cur_offset) {
                                    return .{
                                        .reason = .unzeroed_inter_field_padding,
                                        .byte_offset = cur_offset,
                                        .padding_bytes = col_off - cur_offset,
                                        .field_name = mem_sym.name_text,
                                    };
                                }
                                cur_offset = col_off +| (f_layout.byte_size *| @as(u64, node.rhs));
                            }
                            const max_align = @as(u32, 1) << @intCast(max_align_log2);
                            const total_sz = alignUpU64(cur_offset, max_align);
                            if (total_sz > cur_offset) {
                                return .{
                                    .reason = .unzeroed_tail_padding,
                                    .byte_offset = cur_offset,
                                    .padding_bytes = total_sz - cur_offset,
                                    .field_name = st_sym.name_text,
                                };
                            }
                        }
                    }
                }
                return null;
            },
            .tuple_ty => {
                const elems = self.getTupleElements(ty);
                var rank_mask: u64 = 0;
                var max_align_log2: u8 = 0;
                for (elems) |raw_elem| {
                    const elem_ty = subst.resolve(TypeId.fromInt(raw_elem));
                    const elem_layout = computeTypeLayoutBounded(
                        self,
                        sym_table,
                        elem_ty,
                        target_layout,
                        subst,
                        depth + 1,
                    );
                    if (elem_layout.align_log2 > max_align_log2) max_align_log2 = elem_layout.align_log2;
                    const has_niche = computeLeafNicheBounded(
                        self,
                        sym_table,
                        elem_ty,
                        target_layout,
                        subst,
                        depth + 1,
                    ).kind != .none;
                    const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
                    rank_mask |= (@as(u64, 1) << rank);
                }
                var cur_offset: u64 = 0;
                while (rank_mask != 0) {
                    const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                    rank_mask &= ~(@as(u64, 1) << top_rank);
                    for (elems) |raw_elem| {
                        const elem_ty = subst.resolve(TypeId.fromInt(raw_elem));
                        const elem_layout = computeTypeLayoutBounded(
                            self,
                            sym_table,
                            elem_ty,
                            target_layout,
                            subst,
                            depth + 1,
                        );
                        const has_niche = computeLeafNicheBounded(
                            self,
                            sym_table,
                            elem_ty,
                            target_layout,
                            subst,
                            depth + 1,
                        ).kind != .none;
                        const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) |
                            @intFromBool(has_niche);
                        if (rank != top_rank) continue;
                        const aligned_off = alignUpU64(cur_offset, elem_layout.align_bytes);
                        if (self.explainIntoBytesViolationBounded(
                            elem_ty,
                            sym_table,
                            target_layout,
                            subst,
                            depth + 1,
                        )) |sub_v| {
                            return .{
                                .reason = sub_v.reason,
                                .byte_offset = aligned_off +| sub_v.byte_offset,
                                .padding_bytes = sub_v.padding_bytes,
                                .field_name = sub_v.field_name,
                            };
                        }
                        if (aligned_off > cur_offset) {
                            return .{
                                .reason = .unzeroed_inter_field_padding,
                                .byte_offset = cur_offset,
                                .padding_bytes = aligned_off - cur_offset,
                            };
                        }
                        cur_offset = aligned_off +| elem_layout.byte_size;
                    }
                }
                const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
                const total_size = alignUpU64(cur_offset, max_align_bytes);
                if (total_size > cur_offset) {
                    return .{
                        .reason = .unzeroed_tail_padding,
                        .byte_offset = cur_offset,
                        .padding_bytes = total_size - cur_offset,
                    };
                }
                return null;
            },
            .struct_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const st_sym = sym_table.getSymbol(sym_idx).*;
                if (st_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = st_sym.name_text };
                }
                if (st_sym.target_scope.isNone()) return null;
                const child_subst = NominalTypeSubst.fromNominal(self, sym_table, ty, st_sym, subst);
                const active_subst = if (child_subst.len > 0) &child_subst else subst;
                const is_zero_padded = st_sym.contract_flags.is_zero_pad;
                const is_packed = st_sym.contract_flags.is_packed;
                const is_decl_order = is_packed or st_sym.contract_flags.is_repr_c;
                const members = sym_table.getScopeMembers(st_sym.target_scope);
                var cur_offset: u64 = 0;
                var max_align_log2: u8 = 0;
                if (is_decl_order) {
                    for (members) |mem_idx| {
                        const mem_sym = sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        const f_layout = computeTypeLayoutBounded(
                            self,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                        );
                        if (!is_packed and f_layout.align_log2 > max_align_log2) max_align_log2 = f_layout.align_log2;
                        const aligned_off = if (is_packed) cur_offset else alignUpU64(cur_offset, f_layout.align_bytes);
                        if (self.explainIntoBytesViolationBounded(
                            mem_sym.type_id,
                            sym_table,
                            target_layout,
                            active_subst,
                            depth + 1,
                        )) |sub_v| {
                            return .{
                                .reason = sub_v.reason,
                                .byte_offset = aligned_off +| sub_v.byte_offset,
                                .padding_bytes = sub_v.padding_bytes,
                                .field_name = if (sub_v.field_name.len > 0) sub_v.field_name else mem_sym.name_text,
                            };
                        }
                        if (!is_zero_padded and aligned_off > cur_offset) {
                            return .{
                                .reason = .unzeroed_inter_field_padding,
                                .byte_offset = cur_offset,
                                .padding_bytes = aligned_off - cur_offset,
                                .field_name = mem_sym.name_text,
                            };
                        }
                        cur_offset = aligned_off +| f_layout.byte_size;
                    }
                } else {
                    var rank_mask: u64 = 0;
                    for (members) |mem_idx| {
                        const mem_sym = sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        const f_layout = computeTypeLayoutBounded(
                            self,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                        );
                        if (f_layout.align_log2 > max_align_log2) max_align_log2 = f_layout.align_log2;
                        const has_niche = computeLeafNicheBounded(
                            self,
                            sym_table,
                            mem_sym.type_id,
                            target_layout,
                            active_subst,
                            depth + 1,
                        ).kind != .none;
                        const rank: u6 = (@as(u6, @intCast(@min(f_layout.align_log2, 30))) << 1) |
                            @intFromBool(has_niche);
                        rank_mask |= (@as(u64, 1) << rank);
                    }
                    while (rank_mask != 0) {
                        const top_rank: u6 = @intCast(63 - @clz(rank_mask));
                        rank_mask &= ~(@as(u64, 1) << top_rank);
                        for (members) |mem_idx| {
                            const mem_sym = sym_table.getSymbol(mem_idx).*;
                            if (mem_sym.kind != .field_sym) continue;
                            const f_layout = computeTypeLayoutBounded(
                                self,
                                sym_table,
                                mem_sym.type_id,
                                target_layout,
                                active_subst,
                                depth + 1,
                            );
                            const has_niche = computeLeafNicheBounded(
                                self,
                                sym_table,
                                mem_sym.type_id,
                                target_layout,
                                active_subst,
                                depth + 1,
                            ).kind != .none;
                            const rank: u6 = (@as(u6, @intCast(@min(f_layout.align_log2, 30))) << 1) |
                                @intFromBool(has_niche);
                            if (rank != top_rank) continue;
                            const aligned_off = alignUpU64(cur_offset, f_layout.align_bytes);
                            if (self.explainIntoBytesViolationBounded(
                                mem_sym.type_id,
                                sym_table,
                                target_layout,
                                active_subst,
                                depth + 1,
                            )) |sub_v| {
                                return .{
                                    .reason = sub_v.reason,
                                    .byte_offset = aligned_off +| sub_v.byte_offset,
                                    .padding_bytes = sub_v.padding_bytes,
                                    .field_name = if (sub_v.field_name.len > 0) sub_v.field_name else mem_sym.name_text,
                                };
                            }
                            if (!is_zero_padded and aligned_off > cur_offset) {
                                return .{
                                    .reason = .unzeroed_inter_field_padding,
                                    .byte_offset = cur_offset,
                                    .padding_bytes = aligned_off - cur_offset,
                                    .field_name = mem_sym.name_text,
                                };
                            }
                            cur_offset = aligned_off +| f_layout.byte_size;
                        }
                    }
                }
                if (st_sym.contract_flags.is_cache_aligned) {
                    max_align_log2 = @max(max_align_log2, target_layout.cache_line_align_log2);
                }
                if (st_sym.explicit_align_log2_plus1 > 0) {
                    max_align_log2 = @max(max_align_log2, st_sym.explicit_align_log2_plus1 - 1);
                }
                const max_align_bytes: u32 = @as(u32, 1) << @intCast(max_align_log2);
                const total_size = alignUpU64(cur_offset, max_align_bytes);
                if (!is_zero_padded and total_size > cur_offset) {
                    return .{
                        .reason = .unzeroed_tail_padding,
                        .byte_offset = cur_offset,
                        .padding_bytes = total_size - cur_offset,
                        .field_name = st_sym.name_text,
                    };
                }
                return null;
            },
            .result_ty => {
                const err_unwrapped = self.unwrapUnderlyingType(subst.resolve(TypeId.fromInt(node.rhs)));
                if (err_unwrapped == .never_ty) {
                    return self.explainIntoBytesViolationBounded(
                        TypeId.fromInt(node.lhs),
                        sym_table,
                        target_layout,
                        subst,
                        depth + 1,
                    );
                }
                return .{ .reason = .invalid_bit_patterns };
            },
            .union_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const un_sym = sym_table.getSymbol(sym_idx).*;
                if (un_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = un_sym.name_text };
                }
                if (un_sym.target_scope.isNone()) return null;
                const child_subst = NominalTypeSubst.fromNominal(self, sym_table, ty, un_sym, subst);
                const active_subst = if (child_subst.len > 0) &child_subst else subst;
                for (sym_table.getScopeMembers(un_sym.target_scope)) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym) continue;
                    if (self.explainIntoBytesViolationBounded(
                        mem_sym.type_id,
                        sym_table,
                        target_layout,
                        active_subst,
                        depth + 1,
                    )) |sub_v| {
                        return .{
                            .reason = sub_v.reason,
                            .byte_offset = sub_v.byte_offset,
                            .padding_bytes = sub_v.padding_bytes,
                            .field_name = if (sub_v.field_name.len > 0) sub_v.field_name else mem_sym.name_text,
                        };
                    }
                }
                if (!un_sym.contract_flags.is_zero_pad) {
                    const un_layout = computeTypeLayoutBounded(self, sym_table, ty, target_layout, subst, depth + 1);
                    return .{
                        .reason = .union_requires_zero_pad,
                        .byte_offset = 0,
                        .padding_bytes = un_layout.byte_size,
                        .field_name = un_sym.name_text,
                    };
                }
                return null;
            },
            .enum_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                    return .{ .reason = .invalid_bit_patterns };
                }
                const enum_sym = sym_table.getSymbol(sym_idx).*;
                if (enum_sym.contract_flags.is_secret) {
                    return .{ .reason = .secret_type, .field_name = enum_sym.name_text };
                }
                if (enum_sym.target_scope.isNone()) return null;
                const child_subst = NominalTypeSubst.fromNominal(self, sym_table, ty, enum_sym, subst);
                const active_subst = if (child_subst.len > 0) &child_subst else subst;
                var has_payload = false;
                for (sym_table.getScopeMembers(enum_sym.target_scope)) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .enum_variant_sym) continue;
                    if (mem_sym.type_id != .unit_ty) {
                        has_payload = true;
                        if (self.explainIntoBytesViolationBounded(
                            mem_sym.type_id,
                            sym_table,
                            target_layout,
                            active_subst,
                            depth + 1,
                        )) |sub_v| {
                            return sub_v;
                        }
                    }
                }
                if (has_payload and !enum_sym.contract_flags.is_zero_pad) {
                    const enum_layout = computeTypeLayoutBounded(self, sym_table, ty, target_layout, subst, depth + 1);
                    return .{
                        .reason = .unzeroed_inter_field_padding,
                        .byte_offset = 1,
                        .padding_bytes = enum_layout.byte_size -| 1,
                        .field_name = enum_sym.name_text,
                    };
                }
                return null;
            },
            else => return .{ .reason = .invalid_bit_patterns },
        }
    }
};

/// Stack-allocated generic type-parameter substitution table for instantiated nominals (`DR-04` §1.4).
pub const NominalTypeSubst = struct {
    /// Maximum inline generic type parameters tracked per nominal declaration.
    pub const MAX_PARAMS: usize = 16;

    /// Declared `.type_param` `TypeId` keys from `sym.target_scope`.
    keys: [MAX_PARAMS]TypeId = @splat(.err_ty),
    /// Declared `.const_param_sym` `SymbolId` keys (`SymbolId.empty` for type parameters).
    const_syms: [MAX_PARAMS]SymbolId = @splat(.empty),
    /// Bound concrete `TypeId` arguments from `pool.getGenericTypeArgs(nominal_ty)`.
    vals: [MAX_PARAMS]TypeId = @splat(.err_ty),
    /// Active key-value pair count (`0` when non-generic).
    len: u8 = 0,

    /// Empty substitution identity.
    pub const EMPTY: NominalTypeSubst = .{};

    /// Builds a root substitution table directly from `nominal_ty` (unwrapping `distinct` / refinement layers).
    pub fn init(
        pool: *const InternPool,
        sym_table: *const SymbolTable,
        nominal_ty: TypeId,
    ) NominalTypeSubst {
        const unwrapped = pool.unwrapUnderlyingType(nominal_ty);
        if (unwrapped.isError()) return EMPTY;
        const node = pool.getNode(unwrapped);
        if (node.tag != .struct_ty and node.tag != .enum_ty and
            node.tag != .union_ty and node.tag != .bit_field_ty)
        {
            return EMPTY;
        }
        const sym_idx = SymbolIndex.fromInt(node.rhs);
        if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) return EMPTY;
        return fromNominal(pool, sym_table, unwrapped, sym_table.getSymbol(sym_idx).*, &EMPTY);
    }

    /// Builds a stack substitution mapping `nom_sym`'s `.type_param_sym` members to `nominal_ty`'s generic args,
    /// composing each argument through `parent_subst` for nested generic instantiations (`Outer[Inner[T]]`).
    pub fn fromNominal(
        pool: *const InternPool,
        sym_table: *const SymbolTable,
        nominal_ty: TypeId,
        nom_sym: SymbolRecord,
        parent_subst: *const NominalTypeSubst,
    ) NominalTypeSubst {
        var out: NominalTypeSubst = .{};
        if (nom_sym.target_scope.isNone()) return out;
        const raw_args = pool.getGenericTypeArgs(pool.unwrapUnderlyingType(nominal_ty));
        if (raw_args.len == 0) return out;
        var arg_idx: usize = 0;
        for (sym_table.getScopeMembers(nom_sym.target_scope)) |mem_idx| {
            if (arg_idx >= raw_args.len or out.len >= MAX_PARAMS) break;
            const mem_sym = sym_table.getSymbol(mem_idx).*;
            if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError()) {
                out.keys[out.len] = mem_sym.type_id;
                out.vals[out.len] = parent_subst.resolve(TypeId.fromInt(raw_args[arg_idx]));
                out.len += 1;
                arg_idx += 1;
            } else if (mem_sym.kind == .const_param_sym and mem_sym.name != .empty) {
                out.const_syms[out.len] = mem_sym.name;
                out.vals[out.len] = parent_subst.resolve(TypeId.fromInt(raw_args[arg_idx]));
                out.len += 1;
                arg_idx += 1;
            }
        }
        return out;
    }

    /// Resolves `ty` through up to `MAX_PARAMS` transitive steps if it matches `keys`, or returns `ty`.
    pub inline fn resolve(self: *const NominalTypeSubst, ty: TypeId) TypeId {
        var cur = ty;
        var step: usize = 0;
        while (step < self.len) : (step += 1) {
            var has_matched = false;
            for (0..self.len) |i| {
                if (!self.keys[i].isError() and self.keys[i] == cur and self.vals[i] != cur) {
                    cur = self.vals[i];
                    has_matched = true;
                    break;
                }
            }
            if (!has_matched) break;
        }
        return cur;
    }

    /// Deeply substitutes `.type_param` occurrences in `member_ty` (including compound `[T; N]`, `(T, U)`, etc.).
    pub fn applyMut(
        self: *const NominalTypeSubst,
        allocator: std.mem.Allocator,
        pool: *InternPool,
        member_ty: TypeId,
    ) !TypeId {
        if (self.len == 0 or member_ty.isPrimitiveOrSentinel() or !pool.getFlags(member_ty).has_type_vars) {
            return member_ty;
        }
        const direct_ty = self.resolve(member_ty);
        if (direct_ty != member_ty and !pool.getFlags(direct_ty).has_type_vars) return direct_ty;
        var subst_map: SubstitutionMap = .{};
        defer subst_map.deinit(allocator);
        for (0..self.len) |i| {
            if (self.const_syms[i] != .empty) {
                const len_key = try pool.internSymbolicArray(.unit_ty, self.const_syms[i], false);
                try subst_map.put(
                    allocator,
                    len_key,
                    self.vals[i],
                    .{ .file_id = .none, .start_byte = 0, .end_byte = 0 },
                );
            } else if (!self.keys[i].isError()) {
                try subst_map.put(
                    allocator,
                    self.keys[i],
                    self.vals[i],
                    .{ .file_id = .none, .start_byte = 0, .end_byte = 0 },
                );
            }
        }
        return subst_map.apply(pool, member_ty);
    }
};

/// Canonical alias for `InternPool` (`PLAN.md` Phase 4).
pub const TypeArena = InternPool;

// ------------ Target-Aware Type Layout Calculator -------------

/// Rounds `byte_offset` up to the next power-of-two multiple of `align_bytes` (with saturating `u64` arithmetic).
pub inline fn alignUpU64(byte_offset: u64, align_bytes: u32) u64 {
    if (align_bytes <= 1) return byte_offset;
    const mask: u64 = @as(u64, align_bytes) - 1;
    return (byte_offset +| mask) & ~mask;
}

/// Computes the exact target-architecture `TypeLayout` (`byte_size`, `align_bytes`, `align_log2`) of `type_id`.
pub fn computeTypeLayoutWithPool(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    type_id: TypeId,
    target_layout: TargetLayout,
) TypeLayout {
    return computeTypeLayoutBounded(pool, sym_table, type_id, target_layout, &NominalTypeSubst.EMPTY, 0);
}

/// Resolves the leaf scalar or pointer niche (`LeafNicheInfo`) inside `type_id` under `target_layout`.
pub fn computeLeafNiche(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    type_id: TypeId,
    target_layout: TargetLayout,
) LeafNicheInfo {
    return computeLeafNicheBounded(pool, sym_table, type_id, target_layout, &NominalTypeSubst.EMPTY, 0);
}

/// Depth-bounded leaf niche resolver.
pub fn computeLeafNicheBounded(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_ty: TypeId,
    target_layout: TargetLayout,
    subst: *const NominalTypeSubst,
    depth: u32,
) LeafNicheInfo {
    const ty = subst.resolve(raw_ty);
    if (ty.isError() or depth >= MAX_TYPE_DEPTH) return .{};
    if (tryComputeFastLeafNiche(pool, ty, target_layout)) |fast_niche| {
        return fast_niche;
    }
    var memo: LayoutNicheMemo = .{};
    return computeLeafNicheBoundedMemo(pool, sym_table, ty, target_layout, subst, depth, &memo);
}

/// Resolves the canonical in-memory `SumMemoryLayout` for `Option[T]`, `Result[T, E]`, or `enum`.
pub fn computeSumMemoryLayout(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    sum_ty: TypeId,
    target_layout: TargetLayout,
) SumMemoryLayout {
    return computeSumMemoryLayoutBounded(
        pool,
        sym_table,
        pool.unwrapUnderlyingType(sum_ty),
        target_layout,
        &NominalTypeSubst.EMPTY,
        0,
    );
}

/// Depth-bounded helper computing canonical sum memory layout.
pub fn computeSumMemoryLayoutBounded(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_sum_ty: TypeId,
    target_layout: TargetLayout,
    subst: *const NominalTypeSubst,
    depth: u32,
) SumMemoryLayout {
    const sum_ty = subst.resolve(raw_sum_ty);
    if (sum_ty.isError() or depth >= MAX_TYPE_DEPTH) {
        return .{ .is_sized = false };
    }
    var memo: LayoutNicheMemo = .{};
    return computeSumMemoryLayoutBoundedMemo(pool, sym_table, sum_ty, target_layout, subst, depth, &memo);
}

/// Computes the exact byte offset of `field_ordinal` inside `struct_ty` (`null` if `struct_ty` is not a `struct`).
pub fn computeStructFieldOffset(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    struct_ty: TypeId,
    field_ordinal: u32,
    target_layout: TargetLayout,
) ?u64 {
    const unwrapped = pool.unwrapUnderlyingType(struct_ty);
    const node = pool.getNode(unwrapped);
    if (node.tag != .struct_ty) return null;
    const sym_idx = SymbolIndex.fromInt(node.rhs);
    if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) return null;
    const struct_sym = sym_table.getSymbol(sym_idx).*;
    if (struct_sym.target_scope.isNone()) return null;

    const subst = NominalTypeSubst.fromNominal(pool, sym_table, unwrapped, struct_sym, &NominalTypeSubst.EMPTY);
    const is_packed = struct_sym.contract_flags.is_packed;
    const is_decl_order = is_packed or struct_sym.contract_flags.is_repr_c;
    const members = sym_table.getScopeMembers(struct_sym.target_scope);
    var memo: LayoutNicheMemo = .{};
    var cur_offset: u64 = 0;
    if (is_decl_order) {
        var cur_ordinal: u32 = 0;
        for (members) |mem_idx| {
            const mem_sym = sym_table.getSymbol(mem_idx).*;
            if (mem_sym.kind != .field_sym) continue;
            const field_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                mem_sym.type_id,
                target_layout,
                &subst,
                1,
                &memo,
            );
            const eff_align: u32 = if (is_packed) 1 else field_layout.align_bytes;
            const aligned_offset = alignUpU64(cur_offset, eff_align);
            if (cur_ordinal == field_ordinal) return aligned_offset;
            cur_offset = aligned_offset +| field_layout.byte_size;
            cur_ordinal += 1;
        }
        return null;
    }

    var rank_mask: u64 = 0;
    for (members) |mem_idx| {
        const mem_sym = sym_table.getSymbol(mem_idx).*;
        if (mem_sym.kind != .field_sym) continue;
        const field_layout = computeTypeLayoutBoundedMemo(
            pool,
            sym_table,
            mem_sym.type_id,
            target_layout,
            &subst,
            1,
            &memo,
        );
        const has_niche = computeLeafNicheBoundedMemo(
            pool,
            sym_table,
            mem_sym.type_id,
            target_layout,
            &subst,
            1,
            &memo,
        ).kind != .none;
        const rank: u6 = (@as(u6, @intCast(@min(field_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
        rank_mask |= (@as(u64, 1) << rank);
    }
    while (rank_mask != 0) {
        const top_rank: u6 = @intCast(63 - @clz(rank_mask));
        rank_mask &= ~(@as(u64, 1) << top_rank);
        var cur_ordinal: u32 = 0;
        for (members) |mem_idx| {
            const mem_sym = sym_table.getSymbol(mem_idx).*;
            if (mem_sym.kind != .field_sym) continue;
            defer cur_ordinal += 1;
            const field_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                mem_sym.type_id,
                target_layout,
                &subst,
                1,
                &memo,
            );
            const has_niche = computeLeafNicheBoundedMemo(
                pool,
                sym_table,
                mem_sym.type_id,
                target_layout,
                &subst,
                1,
                &memo,
            ).kind != .none;
            const rank: u6 = (@as(u6, @intCast(@min(field_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
            if (rank != top_rank) continue;
            const aligned_offset = alignUpU64(cur_offset, field_layout.align_bytes);
            if (cur_ordinal == field_ordinal) return aligned_offset;
            cur_offset = aligned_offset +| field_layout.byte_size;
        }
    }
    return null;
}

/// Computes the exact byte offset of `elem_ordinal` inside `tuple_ty` (`null` if `tuple_ty` is not a `tuple`).
pub fn computeTupleElemOffset(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    tuple_ty: TypeId,
    elem_ordinal: u32,
    target_layout: TargetLayout,
) ?u64 {
    const unwrapped = pool.unwrapUnderlyingType(tuple_ty);
    const node = pool.getNode(unwrapped);
    if (node.tag != .tuple_ty) return null;
    const elems = pool.getTupleElements(unwrapped);
    if (elem_ordinal >= elems.len) return null;

    var memo: LayoutNicheMemo = .{};
    var rank_mask: u64 = 0;
    for (elems) |raw_elem| {
        const elem_ty = TypeId.fromInt(raw_elem);
        const elem_layout = computeTypeLayoutBoundedMemo(
            pool,
            sym_table,
            elem_ty,
            target_layout,
            &NominalTypeSubst.EMPTY,
            1,
            &memo,
        );
        const has_niche = computeLeafNicheBoundedMemo(
            pool,
            sym_table,
            elem_ty,
            target_layout,
            &NominalTypeSubst.EMPTY,
            1,
            &memo,
        ).kind != .none;
        const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
        rank_mask |= (@as(u64, 1) << rank);
    }
    var cur_offset: u64 = 0;
    while (rank_mask != 0) {
        const top_rank: u6 = @intCast(63 - @clz(rank_mask));
        rank_mask &= ~(@as(u64, 1) << top_rank);
        for (elems, 0..) |raw_elem, idx| {
            const elem_ty = TypeId.fromInt(raw_elem);
            const elem_layout = computeTypeLayoutBoundedMemo(
                pool,
                sym_table,
                elem_ty,
                target_layout,
                &NominalTypeSubst.EMPTY,
                1,
                &memo,
            );
            const has_niche = computeLeafNicheBoundedMemo(
                pool,
                sym_table,
                elem_ty,
                target_layout,
                &NominalTypeSubst.EMPTY,
                1,
                &memo,
            ).kind != .none;
            const rank: u6 = (@as(u6, @intCast(@min(elem_layout.align_log2, 30))) << 1) | @intFromBool(has_niche);
            if (rank != top_rank) continue;
            const aligned_offset = alignUpU64(cur_offset, elem_layout.align_bytes);
            if (idx == elem_ordinal) return aligned_offset;
            cur_offset = aligned_offset +| elem_layout.byte_size;
        }
    }
    return null;
}

/// Computes the SIMD-aligned byte offset and type of column `field_ordinal` inside `#soa [S; elem_count]`.
pub fn computeSoaColumnInfo(
    allocator: ?std.mem.Allocator,
    pool: *InternPool,
    sym_table: *const SymbolTable,
    elem_struct_ty: TypeId,
    elem_count: u64,
    field_ordinal: u32,
    target_layout: TargetLayout,
) ?SoaColumnInfo {
    const unwrapped = pool.unwrapUnderlyingType(elem_struct_ty);
    const node = pool.getNode(unwrapped);
    if (node.tag != .struct_ty) return null;
    const sym_idx = SymbolIndex.fromInt(node.rhs);
    if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) return null;
    const struct_sym = sym_table.getSymbol(sym_idx).*;
    if (struct_sym.target_scope.isNone()) return null;

    const subst = NominalTypeSubst.fromNominal(pool, sym_table, unwrapped, struct_sym, &NominalTypeSubst.EMPTY);
    var memo: LayoutNicheMemo = .{};
    var cur_offset: u64 = 0;
    var cur_ordinal: u32 = 0;
    for (sym_table.getScopeMembers(struct_sym.target_scope)) |mem_idx| {
        const mem_sym = sym_table.getSymbol(mem_idx).*;
        if (mem_sym.kind != .field_sym) continue;
        const field_layout = computeTypeLayoutBoundedMemo(
            pool,
            sym_table,
            mem_sym.type_id,
            target_layout,
            &subst,
            1,
            &memo,
        );
        const col_log2 = @max(field_layout.align_log2, target_layout.simd_align_log2);
        const col_align = @as(u32, 1) << @intCast(col_log2);
        const col_offset = alignUpU64(cur_offset, col_align);
        if (cur_ordinal == field_ordinal) {
            const concrete_ty = if (subst.len > 0 and allocator != null)
                subst.applyMut(allocator.?, pool, mem_sym.type_id) catch subst.resolve(mem_sym.type_id)
            else
                subst.resolve(mem_sym.type_id);
            return .{
                .byte_offset = col_offset,
                .col_align_log2 = col_log2,
                .field_ty = concrete_ty,
                .field_layout = field_layout,
            };
        }
        cur_offset = col_offset +| (field_layout.byte_size *| elem_count);
        cur_ordinal += 1;
    }
    return null;
}

/// Read-only `const InternPool` variant of `computeSoaColumnInfo` for `TypeLayoutResolver` and `MirOpt`.
pub fn computeSoaColumnInfoReadOnly(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    elem_struct_ty: TypeId,
    elem_count: u64,
    field_ordinal: u32,
    target_layout: TargetLayout,
) ?SoaColumnInfo {
    const unwrapped = pool.unwrapUnderlyingType(elem_struct_ty);
    const node = pool.getNode(unwrapped);
    if (node.tag != .struct_ty) return null;
    const sym_idx = SymbolIndex.fromInt(node.rhs);
    if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) return null;
    const struct_sym = sym_table.getSymbol(sym_idx).*;
    if (struct_sym.target_scope.isNone()) return null;

    const subst = NominalTypeSubst.fromNominal(pool, sym_table, unwrapped, struct_sym, &NominalTypeSubst.EMPTY);
    var memo: LayoutNicheMemo = .{};
    var cur_offset: u64 = 0;
    var cur_ordinal: u32 = 0;
    for (sym_table.getScopeMembers(struct_sym.target_scope)) |mem_idx| {
        const mem_sym = sym_table.getSymbol(mem_idx).*;
        if (mem_sym.kind != .field_sym) continue;
        const field_layout = computeTypeLayoutBoundedMemo(
            pool,
            sym_table,
            mem_sym.type_id,
            target_layout,
            &subst,
            1,
            &memo,
        );
        const col_log2 = @max(field_layout.align_log2, target_layout.simd_align_log2);
        const col_align = @as(u32, 1) << @intCast(col_log2);
        const col_offset = alignUpU64(cur_offset, col_align);
        if (cur_ordinal == field_ordinal) {
            return .{
                .byte_offset = col_offset,
                .col_align_log2 = col_log2,
                .field_ty = subst.resolve(mem_sym.type_id),
                .field_layout = field_layout,
            };
        }
        cur_offset = col_offset +| (field_layout.byte_size *| elem_count);
        cur_ordinal += 1;
    }
    return null;
}

// ---------- Ownership Tiers, Context & Group Bounds -----------

/// Returns `true` if `sym` is a compiler built-in or declared inside `PackageId.std_core` (`core/*`).
pub inline fn isStdCoreOrBuiltinSymbol(sym_table: *const SymbolTable, sym: SymbolRecord) bool {
    return sym.flags.is_builtin or sym_table.getFilePackageId(sym.decl_span.file_id) == .std_core;
}

/// Returns `true` if nominal symbol `sym` carries an explicit `@not_send` marker (`DR-08`).
pub fn isNominalNotSend(sym: SymbolRecord) bool {
    return sym.extra_flags.is_not_send;
}

/// Returns `true` if nominal symbol `sym` carries an explicit `@not_sync` marker (`DR-08`).
pub fn isNominalNotSync(sym: SymbolRecord) bool {
    return sym.extra_flags.is_not_sync;
}

/// Evaluates cross-module `Send` (`is_requiring_sync = false`) or `Sync` (`true`) satisfaction in $O(1)$ per node (`DR-08`).
pub fn explainNonSendOrSyncTypeWithPool(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_ty: TypeId,
    is_requiring_sync: bool,
    depth: u32,
) ?[]const u8 {
    if (depth >= 16 or raw_ty.isError() or raw_ty.isSizedPrimitive()) return null;
    var memo: SendSyncVisitedMemo = .{};
    return explainNonSendOrSyncTypeWithSubst(
        pool,
        sym_table,
        raw_ty,
        &NominalTypeSubst.EMPTY,
        is_requiring_sync,
        depth,
        &memo,
    );
}

/// Returns `true` if `ty` (or its borrowed `&Context` / `&mut Context` target) is the `Context` capability struct.
pub fn isContextType(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    ty: TypeId,
) bool {
    if (ty.isError()) return false;
    var cur_ty = pool.unwrapRefinementBase(ty);
    const cur_tag = pool.getTag(cur_ty);
    if (cur_tag == .ref_ty or cur_tag == .mut_ref_ty) {
        cur_ty = pool.unwrapRefinementBase(TypeId.fromInt(pool.getNode(cur_ty).lhs));
    }
    const node = pool.getNode(cur_ty);
    if (node.tag != .struct_ty) return false;
    const sym_idx = SymbolIndex.fromInt(node.rhs);
    if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) return false;
    return std.mem.eql(u8, sym_table.getSymbol(sym_idx).name_text, "Context");
}

/// Classifies `ty` into its canonical compile-time `OwnershipTier` (`Copy`, `AutoDrop`, or `@linear`, `DR-06` Section 1.2).
pub fn classifyOwnershipTier(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    ty: TypeId,
) OwnershipTier {
    if (tryClassifyFastOwnershipTier(pool, ty, true)) |fast_tier| return fast_tier;
    var visited_buf: [MAX_OWNERSHIP_VISIT_DEPTH]u64 = undefined;
    return classifyOwnershipTierBounded(pool, sym_table, ty, &NominalTypeSubst.EMPTY, &visited_buf, 0);
}

/// Classifies `ty` under an active generic nominal substitution `subst` (`Copy`, `AutoDrop`, or `@linear`).
pub fn classifyOwnershipTierWithSubst(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    ty: TypeId,
    subst: *const NominalTypeSubst,
) OwnershipTier {
    const resolved_ty = subst.resolve(ty);
    if (tryClassifyFastOwnershipTier(pool, resolved_ty, true)) |fast_tier| return fast_tier;
    var visited_buf: [MAX_OWNERSHIP_VISIT_DEPTH]u64 = undefined;
    return classifyOwnershipTierBounded(pool, sym_table, resolved_ty, subst, &visited_buf, 0);
}

/// Returns `true` iff `ty` owns a `@linear` completeness obligation (`E0304`), excluding pure `&mut T` borrows.
pub fn hasLinearObligation(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    ty: TypeId,
) bool {
    if (tryClassifyFastOwnershipTier(pool, ty, false)) |fast_tier| return fast_tier == .linear_tier;
    var visited_buf: [MAX_OWNERSHIP_VISIT_DEPTH]u64 = undefined;
    var memo: OwnershipMemo = .{};
    var has_hit_cycle = false;
    return classifyOwnershipTierCore(
        pool,
        sym_table,
        ty,
        &NominalTypeSubst.EMPTY,
        false,
        &visited_buf,
        0,
        &memo,
        &has_hit_cycle,
    ) == .linear_tier;
}

/// Returns `true` iff `ty` under `subst` owns a `@linear` completeness obligation (`E0304`), excluding `&mut T` borrows.
pub fn hasLinearObligationWithSubst(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    ty: TypeId,
    subst: *const NominalTypeSubst,
) bool {
    const resolved_ty = subst.resolve(ty);
    if (tryClassifyFastOwnershipTier(pool, resolved_ty, false)) |fast_tier| return fast_tier == .linear_tier;
    var visited_buf: [MAX_OWNERSHIP_VISIT_DEPTH]u64 = undefined;
    var memo: OwnershipMemo = .{};
    var has_hit_cycle = false;
    return classifyOwnershipTierCore(
        pool,
        sym_table,
        resolved_ty,
        subst,
        false,
        &visited_buf,
        0,
        &memo,
        &has_hit_cycle,
    ) == .linear_tier;
}

/// Cycle-safe, depth-bounded helper for `classifyOwnershipTier` with generic nominal substitution `subst`.
fn classifyOwnershipTierBounded(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_ty: TypeId,
    subst: *const NominalTypeSubst,
    visited_stack: []u64,
    depth: usize,
) OwnershipTier {
    var memo: OwnershipMemo = .{};
    var has_hit_cycle = false;
    return classifyOwnershipTierCore(
        pool,
        sym_table,
        raw_ty,
        subst,
        true,
        visited_stack,
        depth,
        &memo,
        &has_hit_cycle,
    );
}

/// Returns `true` if `raw_group_ty` statically guarantees `Copy` on every admissible concrete type (`ADR-22B`).
fn isGroupImplyingCopy(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_group_ty: TypeId,
    depth: u32,
) bool {
    if (depth >= 16) return false;
    const grp_ty = pool.unwrapUnderlyingType(raw_group_ty);
    switch (grp_ty) {
        .group_copy,
        .group_signed,
        .group_unsigned,
        .group_integer,
        .group_float,
        .group_number,
        .group_scalar,
        .group_from_bytes,
        .group_into_bytes,
        => return true,
        .group_bytes,
        .group_equatable,
        .group_comparable,
        ._retired_group_numeric,
        => return false,
        else => {},
    }
    if (grp_ty.isSizedPrimitive() or grp_ty == .source_loc_ty or
        grp_ty == .fmt_spec_ty or grp_ty == .fmt_args_ty)
    {
        return true;
    }
    const g_node = pool.getNode(grp_ty);
    switch (g_node.tag) {
        .ref_ty, .raw_ptr_ty, .fn_ty, .slice_ty, .soa_slice_ty, .bit_field_ty => return true,
        .trait_ty => {
            const sym_idx = SymbolIndex.fromInt(g_node.rhs);
            if (sym_idx.isNone()) return false;
            const sym = sym_table.getSymbol(sym_idx);
            return sym.flags.is_builtin and std.mem.eql(u8, sym.name_text, "Copy");
        },
        .tilde_approx => return isGroupImplyingCopy(pool, sym_table, TypeId.fromInt(g_node.lhs), depth + 1),
        .user_group => {
            const view = pool.getUserGroupView(grp_ty) orelse return false;
            if (view.tilde_prim_mask == INTERSECT_GROUP_SENTINEL or g_node.rhs == INTERSECT_GROUP_SENTINEL) {
                for (view.exact_members) |raw_m| {
                    if (isGroupImplyingCopy(pool, sym_table, TypeId.fromInt(raw_m), depth + 1)) return true;
                }
                return false;
            }
            const has_any_member = view.prim_mask != 0 or view.tilde_prim_mask != 0 or
                view.exact_members.len > 0 or view.tilde_members.len > 0;
            if (!has_any_member) return false;
            for (view.exact_members) |raw_m| {
                const mem_ty = TypeId.fromInt(raw_m);
                if (!isGroupImplyingCopy(pool, sym_table, mem_ty, depth + 1) and !pool.getFlags(mem_ty).is_copy) {
                    return false;
                }
            }
            for (view.tilde_members) |raw_m| {
                const mem_ty = TypeId.fromInt(raw_m);
                if (!isGroupImplyingCopy(pool, sym_table, mem_ty, depth + 1) and !pool.getFlags(mem_ty).is_copy) {
                    return false;
                }
            }
            return true;
        },
        else => return g_node.flags.is_copy,
    }
}

/// Shared cycle-safe classifier for `classifyOwnershipTier` (`is_mut_ref_linear = true`) and `hasLinearObligation` (`false`).
fn classifyOwnershipTierCore(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    raw_ty: TypeId,
    subst: *const NominalTypeSubst,
    is_mut_ref_linear: bool,
    visited_stack: []u64,
    depth: usize,
    memo: *OwnershipMemo,
    has_hit_cycle: *bool,
) OwnershipTier {
    const ty = subst.resolve(raw_ty);
    if (tryClassifyFastOwnershipTier(pool, ty, is_mut_ref_linear)) |fast_tier| {
        return fast_tier;
    }
    const maybe_key = OwnershipMemoKey.fromQuery(ty, subst, is_mut_ref_linear);
    if (maybe_key) |memo_key| {
        if (memo.lookup(memo_key)) |cached_tier| return cached_tier;
    }
    if (depth >= visited_stack.len) {
        has_hit_cycle.* = true;
        return .copy_tier;
    }
    const subst_tag: u64 = if (subst.len > 0) @as(u64, subst.vals[0].toU32()) << 32 else 0;
    const visit_key: u64 = subst_tag | @as(u64, ty.toU32());
    for (visited_stack[0..depth]) |seen_raw| {
        if (seen_raw == visit_key) {
            has_hit_cycle.* = true;
            return .copy_tier;
        }
    }
    visited_stack[depth] = visit_key;
    const next_depth = depth + 1;

    var has_subtree_cycle = false;
    const node = pool.getNode(ty);
    const tier_result: OwnershipTier = switch (node.tag) {
        .type_param => if (isGroupImplyingCopy(pool, sym_table, TypeId.fromInt(node.lhs), 0))
            .copy_tier
        else
            .auto_drop_tier,
        .future_ty => blk: {
            const out_tier = classifyOwnershipTierCore(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                subst,
                false,
                visited_stack,
                next_depth,
                memo,
                &has_subtree_cycle,
            );
            if (out_tier == .linear_tier) break :blk .linear_tier;
            const prod_id = pool.getFutureProducerId(ty);
            if (prod_id != 0) {
                var prod_sym_idx: SymbolIndex = .none;
                if (prod_id < sym_table.symbols.items.len and
                    sym_table.getSymbol(SymbolIndex.fromInt(prod_id)).kind == .fn_sym)
                {
                    prod_sym_idx = SymbolIndex.fromInt(prod_id);
                } else if (sym_table.def_to_symbol.get(prod_id)) |mapped_sym| {
                    prod_sym_idx = mapped_sym;
                }
                if (!prod_sym_idx.isNone() and prod_sym_idx.asInt() < sym_table.symbols.items.len) {
                    const fn_ty = pool.unwrapUnderlyingType(sym_table.getSymbol(prod_sym_idx).type_id);
                    if (!fn_ty.isError()) {
                        if (pool.getFnSignatureView(fn_ty)) |sig_view| {
                            for (0..sig_view.paramCount()) |param_i| {
                                const param_mode = sig_view.getParamMode(param_i);
                                if (param_mode == .inout_mode or param_mode == .set_mode) continue;
                                const param_tier = classifyOwnershipTierCore(
                                    pool,
                                    sym_table,
                                    sig_view.getParamType(param_i),
                                    &NominalTypeSubst.EMPTY,
                                    false,
                                    visited_stack,
                                    next_depth,
                                    memo,
                                    &has_subtree_cycle,
                                );
                                if (param_tier == .linear_tier) break :blk .linear_tier;
                            }
                        }
                    }
                }
            }
            break :blk .auto_drop_tier;
        },
        .refined_ty => if (pool.getRefinementBounds(ty)) |bounds|
            classifyOwnershipTierCore(
                pool,
                sym_table,
                bounds.base_ty,
                subst,
                is_mut_ref_linear,
                visited_stack,
                next_depth,
                memo,
                &has_subtree_cycle,
            )
        else
            classifyOwnershipTierCore(
                pool,
                sym_table,
                TypeId.fromInt(node.rhs),
                subst,
                is_mut_ref_linear,
                visited_stack,
                next_depth,
                memo,
                &has_subtree_cycle,
            ),
        .array_ty, .soa_array_ty, .optional_ty => classifyOwnershipTierCore(
            pool,
            sym_table,
            TypeId.fromInt(node.lhs),
            subst,
            is_mut_ref_linear,
            visited_stack,
            next_depth,
            memo,
            &has_subtree_cycle,
        ),
        .result_ty => blk: {
            const ok_tier = classifyOwnershipTierCore(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                subst,
                is_mut_ref_linear,
                visited_stack,
                next_depth,
                memo,
                &has_subtree_cycle,
            );
            if (ok_tier == .linear_tier) break :blk .linear_tier;
            const err_tier = classifyOwnershipTierCore(
                pool,
                sym_table,
                TypeId.fromInt(node.rhs),
                subst,
                is_mut_ref_linear,
                visited_stack,
                next_depth,
                memo,
                &has_subtree_cycle,
            );
            break :blk maxOwnershipTier(ok_tier, err_tier);
        },
        .tuple_ty => blk: {
            var max_tier: OwnershipTier = .copy_tier;
            for (pool.getTupleElements(ty)) |raw_elem| {
                const elem_tier = classifyOwnershipTierCore(
                    pool,
                    sym_table,
                    TypeId.fromInt(raw_elem),
                    subst,
                    is_mut_ref_linear,
                    visited_stack,
                    next_depth,
                    memo,
                    &has_subtree_cycle,
                );
                max_tier = maxOwnershipTier(max_tier, elem_tier);
                if (max_tier == .linear_tier) break :blk .linear_tier;
            }
            break :blk max_tier;
        },
        .distinct_ty => blk: {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < sym_table.symbols.items.len) {
                const dist_sym = sym_table.getSymbol(sym_idx).*;
                if (dist_sym.contract_flags.is_linear) break :blk .linear_tier;
                if (hasNominalDropTraitImpl(sym_table, ty, dist_sym.type_id, dist_sym.target_scope)) {
                    const inner_tier = classifyOwnershipTierCore(
                        pool,
                        sym_table,
                        TypeId.fromInt(node.lhs),
                        subst,
                        is_mut_ref_linear,
                        visited_stack,
                        next_depth,
                        memo,
                        &has_subtree_cycle,
                    );
                    break :blk maxOwnershipTier(.auto_drop_tier, inner_tier);
                }
            }
            if (pool.getFlags(ty).has_drop) {
                const inner_tier = classifyOwnershipTierCore(
                    pool,
                    sym_table,
                    TypeId.fromInt(node.lhs),
                    subst,
                    is_mut_ref_linear,
                    visited_stack,
                    next_depth,
                    memo,
                    &has_subtree_cycle,
                );
                break :blk maxOwnershipTier(.auto_drop_tier, inner_tier);
            }
            break :blk classifyOwnershipTierCore(
                pool,
                sym_table,
                TypeId.fromInt(node.lhs),
                subst,
                is_mut_ref_linear,
                visited_stack,
                next_depth,
                memo,
                &has_subtree_cycle,
            );
        },
        .struct_ty, .enum_ty, .union_ty => blk: {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (sym_idx.isNone() or sym_idx.asInt() >= sym_table.symbols.items.len) {
                break :blk if (pool.getFlags(ty).has_drop) .auto_drop_tier else .copy_tier;
            }
            const nom_sym = sym_table.getSymbol(sym_idx).*;
            if (nom_sym.contract_flags.is_linear or LINEAR_BUILTIN_TYPE_MAP.has(nom_sym.name_text)) {
                break :blk .linear_tier;
            }
            if (COPY_BUILTIN_NOMINAL_MAP.has(nom_sym.name_text)) {
                break :blk .copy_tier;
            }
            var max_tier: OwnershipTier = .copy_tier;
            if (AUTO_DROP_CONTAINER_MAP.has(nom_sym.name_text) or
                pool.getFlags(ty).has_drop or
                hasNominalDropTraitImpl(sym_table, ty, nom_sym.type_id, nom_sym.target_scope))
            {
                max_tier = .auto_drop_tier;
            }
            const child_subst = NominalTypeSubst.fromNominal(pool, sym_table, ty, nom_sym, subst);
            const active_subst = if (child_subst.len > 0) &child_subst else subst;
            for (pool.getGenericTypeArgs(ty)) |raw_arg| {
                const arg_tier = classifyOwnershipTierCore(
                    pool,
                    sym_table,
                    TypeId.fromInt(raw_arg),
                    subst,
                    is_mut_ref_linear,
                    visited_stack,
                    next_depth,
                    memo,
                    &has_subtree_cycle,
                );
                max_tier = maxOwnershipTier(max_tier, arg_tier);
                if (max_tier == .linear_tier) break :blk .linear_tier;
            }
            if (!nom_sym.target_scope.isNone()) {
                for (sym_table.getScopeMembers(nom_sym.target_scope)) |mem_idx| {
                    const mem_sym = sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind != .field_sym and mem_sym.kind != .enum_variant_sym) continue;
                    if (mem_sym.type_id == .unit_ty or mem_sym.type_id.isError()) continue;
                    const child_tier = classifyOwnershipTierCore(
                        pool,
                        sym_table,
                        mem_sym.type_id,
                        active_subst,
                        is_mut_ref_linear,
                        visited_stack,
                        next_depth,
                        memo,
                        &has_subtree_cycle,
                    );
                    max_tier = maxOwnershipTier(max_tier, child_tier);
                    if (max_tier == .linear_tier) break :blk .linear_tier;
                }
            }
            break :blk max_tier;
        },
        else => .copy_tier,
    };
    if (has_subtree_cycle) {
        has_hit_cycle.* = true;
    } else if (maybe_key) |memo_key| {
        memo.store(memo_key, depth, tier_result);
    }
    return tier_result;
}

/// Classification of whether a candidate type satisfies a Constrained Type Group or `~T` bound.
pub const GroupMatchResult = enum(u8) {
    /// Candidate is not a member of the group (`E0402`).
    rejected = 0,
    /// Candidate is a `distinct` type whose underlying type is in the group without `~` (`E0405`).
    rejected_distinct_without_tilde = 1,
    /// Candidate matches via `~T` underlying approximation (rank 2 in overload resolution).
    matched_via_tilde = 2,
    /// Candidate matches as an exact member of the group (rank 1 in overload resolution).
    matched_exact = 3,
};

/// Evaluates whether `candidate_ty` satisfies `group_ty` (built-in group, `Copy`/`FromBytes`/`IntoBytes`, user group, or `~T`).
pub fn checkGroupSatisfaction(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    target_layout: TargetLayout,
    candidate_ty: TypeId,
    group_ty: TypeId,
) GroupMatchResult {
    return checkGroupSatisfactionBounded(pool, sym_table, target_layout, candidate_ty, group_ty, 0);
}

/// Depth-bounded helper (`MAX_TYPE_DEPTH`) for `checkGroupSatisfaction`.
fn checkGroupSatisfactionBounded(
    pool: *const InternPool,
    sym_table: *const SymbolTable,
    target_layout: TargetLayout,
    candidate_ty: TypeId,
    group_ty: TypeId,
    depth: u32,
) GroupMatchResult {
    if (depth >= MAX_TYPE_DEPTH) return .rejected;
    if (candidate_ty.isError() or group_ty.isError()) return .matched_exact;
    if (candidate_ty == .opaque_ty or group_ty == ._retired_group_numeric) return .rejected;

    // [1] Ownership & wire-transmute structural groups (checked BEFORE `unwrapRefinementBase`):
    if (group_ty == .group_copy) {
        return if (classifyOwnershipTier(pool, sym_table, candidate_ty) == .copy_tier)
            .matched_exact
        else
            .rejected;
    }
    if (group_ty == .group_from_bytes) {
        return if (pool.isFromBytesValid(candidate_ty, sym_table, target_layout))
            .matched_exact
        else
            .rejected;
    }
    if (group_ty == .group_into_bytes) {
        return if (pool.isIntoBytesValid(candidate_ty, sym_table, target_layout))
            .matched_exact
        else
            .rejected;
    }

    const unwrapped_refinement = pool.unwrapRefinementBase(candidate_ty);
    const underlying_ty = pool.unwrapUnderlyingType(candidate_ty);
    const is_distinct_candidate = (pool.getTag(unwrapped_refinement) == .distinct_ty);

    // [2] `~Target` underlying-type approximation:
    const group_node = pool.getNode(group_ty);
    if (group_node.tag == .tilde_approx) {
        const inner_target = TypeId.fromInt(group_node.lhs);
        if (inner_target == .group_copy or
            inner_target == .group_from_bytes or
            inner_target == .group_into_bytes)
        {
            if (pool.getFlags(candidate_ty).is_secret and
                (inner_target == .group_from_bytes or inner_target == .group_into_bytes))
            {
                return .rejected;
            }
            const direct_match = checkGroupSatisfactionBounded(
                pool,
                sym_table,
                target_layout,
                candidate_ty,
                inner_target,
                depth + 1,
            );
            if (direct_match == .matched_exact or direct_match == .matched_via_tilde) {
                return if (is_distinct_candidate) .matched_via_tilde else direct_match;
            }
            return .rejected;
        }
        if (inner_target.isBuiltinGroup() or
            pool.getTag(inner_target) == .user_group or
            pool.getTag(inner_target) == .tilde_approx)
        {
            const base_match = checkGroupSatisfactionBounded(
                pool,
                sym_table,
                target_layout,
                underlying_ty,
                inner_target,
                depth + 1,
            );
            if (base_match == .matched_exact or base_match == .matched_via_tilde) {
                return if (is_distinct_candidate) .matched_via_tilde else base_match;
            }
            return .rejected;
        }
        const target_ty = pool.unwrapUnderlyingType(inner_target);
        if (unwrapped_refinement == target_ty) return .matched_exact;
        if (underlying_ty == target_ty) return .matched_via_tilde;
        if (candidate_ty == .untyped_int_ty and target_ty.isIntegerPrimitive()) return .matched_exact;
        if (candidate_ty == .untyped_float_ty and target_ty.isFloatPrimitive()) return .matched_exact;
        return .rejected;
    }

    // [3] Built-in Constrained Type Group (`32..41`):
    if (group_ty.isBuiltinGroup() or group_node.tag == .builtin_group) {
        const mask = if (group_ty.isBuiltinGroup())
            TypeGroupMask.forBuiltinGroup(group_ty)
        else
            group_node.lhs;

        if (candidate_ty == .untyped_int_ty) {
            return if ((mask & TypeGroupMask.INTEGER) != 0) .matched_exact else .rejected;
        }
        if (candidate_ty == .untyped_float_ty) {
            return if ((mask & TypeGroupMask.FLOAT) != 0) .matched_exact else .rejected;
        }
        if (!is_distinct_candidate and unwrapped_refinement.isSizedPrimitive()) {
            return if (TypeGroupMask.containsPrimitive(mask, unwrapped_refinement))
                .matched_exact
            else
                .rejected;
        }
        if (is_distinct_candidate and underlying_ty.isSizedPrimitive() and
            TypeGroupMask.containsPrimitive(mask, underlying_ty))
        {
            return .rejected_distinct_without_tilde;
        }
        return .rejected;
    }

    // [4] User-defined Constrained Type Group (`type G = A | ~B`, `[Data: str | &[u8]]`, or `A & B`):
    if (pool.getUserGroupView(group_ty)) |view| {
        if (view.tilde_prim_mask == INTERSECT_GROUP_SENTINEL) {
            var best_result: GroupMatchResult = .matched_exact;
            if (view.prim_mask != 0) {
                if (candidate_ty == .untyped_int_ty) {
                    if ((view.prim_mask & TypeGroupMask.INTEGER) == 0) return .rejected;
                } else if (candidate_ty == .untyped_float_ty) {
                    if ((view.prim_mask & TypeGroupMask.FLOAT) == 0) return .rejected;
                } else if (!is_distinct_candidate and unwrapped_refinement.isSizedPrimitive()) {
                    if (!TypeGroupMask.containsPrimitive(view.prim_mask, unwrapped_refinement)) return .rejected;
                } else {
                    return .rejected;
                }
            }
            for (view.exact_members) |exact_raw| {
                const sub_res = checkGroupSatisfactionBounded(
                    pool,
                    sym_table,
                    target_layout,
                    candidate_ty,
                    TypeId.fromInt(exact_raw),
                    depth + 1,
                );
                if (sub_res == .rejected or sub_res == .rejected_distinct_without_tilde) return sub_res;
                if (sub_res == .matched_via_tilde) best_result = .matched_via_tilde;
            }
            return best_result;
        }
        if (candidate_ty == .untyped_int_ty) {
            if (((view.prim_mask | view.tilde_prim_mask) & TypeGroupMask.INTEGER) != 0) {
                return .matched_exact;
            }
            for (view.exact_members) |exact_raw| {
                const sub_res = checkGroupSatisfactionBounded(
                    pool,
                    sym_table,
                    target_layout,
                    candidate_ty,
                    TypeId.fromInt(exact_raw),
                    depth + 1,
                );
                if (sub_res != .rejected) return sub_res;
            }
            return .rejected;
        }
        if (candidate_ty == .untyped_float_ty) {
            if (((view.prim_mask | view.tilde_prim_mask) & TypeGroupMask.FLOAT) != 0) {
                return .matched_exact;
            }
            for (view.exact_members) |exact_raw| {
                const sub_res = checkGroupSatisfactionBounded(
                    pool,
                    sym_table,
                    target_layout,
                    candidate_ty,
                    TypeId.fromInt(exact_raw),
                    depth + 1,
                );
                if (sub_res != .rejected) return sub_res;
            }
            return .rejected;
        }
        if (!is_distinct_candidate and unwrapped_refinement.isSizedPrimitive()) {
            if (TypeGroupMask.containsPrimitive(view.prim_mask, unwrapped_refinement)) {
                return .matched_exact;
            }
            if (TypeGroupMask.containsPrimitive(view.tilde_prim_mask, unwrapped_refinement)) {
                return .matched_via_tilde;
            }
        }
        for (view.exact_members) |exact_raw| {
            const exact_ty = TypeId.fromInt(exact_raw);
            if (unwrapped_refinement == exact_ty) return .matched_exact;
            const exact_tag = pool.getTag(exact_ty);
            if (exact_ty.isBuiltinGroup() or exact_tag == .user_group or exact_tag == .tilde_approx) {
                const sub_res = checkGroupSatisfactionBounded(
                    pool,
                    sym_table,
                    target_layout,
                    candidate_ty,
                    exact_ty,
                    depth + 1,
                );
                if (sub_res == .matched_exact or sub_res == .matched_via_tilde) return sub_res;
            } else if (exact_tag == .ref_ty) {
                const exp_inner = pool.getNode(TypeId.fromInt(pool.getNode(exact_ty).lhs));
                const cand_node = pool.getNode(unwrapped_refinement);
                if (exp_inner.tag == .slice_ty and (cand_node.tag == .ref_ty or cand_node.tag == .mut_ref_ty)) {
                    const cand_inner = pool.getNode(TypeId.fromInt(cand_node.lhs));
                    if ((cand_inner.tag == .slice_ty or cand_inner.tag == .array_ty) and
                        cand_inner.lhs == exp_inner.lhs)
                    {
                        return .matched_exact;
                    }
                }
            }
        }
        for (view.tilde_members) |tilde_raw| {
            if (unwrapped_refinement.toU32() == tilde_raw) return .matched_exact;
            if (underlying_ty.toU32() == tilde_raw) return .matched_via_tilde;
        }
        if (is_distinct_candidate and underlying_ty.isSizedPrimitive()) {
            if (TypeGroupMask.containsPrimitive(view.tilde_prim_mask, underlying_ty)) {
                return .matched_via_tilde;
            }
            if (TypeGroupMask.containsPrimitive(view.prim_mask, underlying_ty)) {
                return .rejected_distinct_without_tilde;
            }
        }
        if (is_distinct_candidate) {
            for (view.exact_members) |exact_raw| {
                if (underlying_ty.toU32() == exact_raw) return .rejected_distinct_without_tilde;
            }
        }
        return .rejected;
    }

    // [5] Nominal trait bound (`[T: MyTrait]`):
    if (unwrapped_refinement == group_ty) return .matched_exact;
    return .rejected;
}

/// Returns `true` if `sub_group` is a mathematical subset of `super_group` (`G_1 <: G_2`, `DR-04` Section 1.2).
pub fn isTypeGroupSubset(
    pool: *const InternPool,
    sub_group: TypeId,
    super_group: TypeId,
) bool {
    if (sub_group == super_group) return true;
    if (sub_group.isBuiltinGroup() and super_group.isBuiltinGroup()) {
        if (sub_group == .group_copy or
            sub_group == .group_from_bytes or
            sub_group == .group_into_bytes)
        {
            return super_group == .group_copy;
        }
        if (super_group == .group_copy) return true;
        return TypeGroupMask.isSubsetOf(
            TypeGroupMask.forBuiltinGroup(sub_group),
            TypeGroupMask.forBuiltinGroup(super_group),
        );
    }
    if (pool.getUserGroupView(sub_group)) |sub_view| {
        if (super_group.isBuiltinGroup() and super_group != .group_copy) {
            const super_mask = TypeGroupMask.forBuiltinGroup(super_group);
            return sub_view.exact_members.len == 0 and
                sub_view.tilde_members.len == 0 and
                sub_view.tilde_prim_mask == 0 and
                TypeGroupMask.isSubsetOf(sub_view.prim_mask, super_mask);
        }
    }
    return false;
}

// ------- Maranget 128-Bit Interval Splitting (`DR-07`) --------

/// Inclusive 128-bit integer range `[min_val, max_val]` for Maranget pattern exhaustiveness.
pub const Interval128 = struct {
    /// Inclusive lower bound.
    min_val: i128,
    /// Inclusive upper bound (`min_val <= max_val`).
    max_val: i128,
};

/// Subtracts `arm_range` (`[min_val, max_val]`) in place from `uncovered_intervals[0..uncovered_count.*]`.
pub fn subtractIntervalFromUncovered(
    uncovered_intervals: *[128]Interval128,
    uncovered_count: *usize,
    arm_range: Interval128,
) void {
    if (arm_range.min_val > arm_range.max_val) return;
    var i: usize = 0;
    while (i < uncovered_count.*) {
        const cur = uncovered_intervals[i];
        if (arm_range.max_val < cur.min_val or arm_range.min_val > cur.max_val) {
            i += 1;
            continue;
        }
        // Overflow-safe boundary checks at `minInt(i128)` and `maxInt(i128)` (Critique H1):
        const has_left_rem = (arm_range.min_val > cur.min_val);
        const has_right_rem = (arm_range.max_val < cur.max_val);

        if (has_left_rem and has_right_rem) {
            uncovered_intervals[i] = .{ .min_val = cur.min_val, .max_val = arm_range.min_val - 1 };
            if (uncovered_count.* < uncovered_intervals.len) {
                var shift_idx: usize = uncovered_count.*;
                while (shift_idx > i + 1) : (shift_idx -= 1) {
                    uncovered_intervals[shift_idx] = uncovered_intervals[shift_idx - 1];
                }
                uncovered_intervals[i + 1] = .{ .min_val = arm_range.max_val + 1, .max_val = cur.max_val };
                uncovered_count.* += 1;
                i += 2;
            } else {
                i += 1;
            }
        } else if (has_left_rem) {
            uncovered_intervals[i] = .{ .min_val = cur.min_val, .max_val = arm_range.min_val - 1 };
            i += 1;
        } else if (has_right_rem) {
            uncovered_intervals[i] = .{ .min_val = arm_range.max_val + 1, .max_val = cur.max_val };
            i += 1;
        } else {
            var rem_idx: usize = i;
            while (rem_idx + 1 < uncovered_count.*) : (rem_idx += 1) {
                uncovered_intervals[rem_idx] = uncovered_intervals[rem_idx + 1];
            }
            uncovered_count.* -= 1;
        }
    }
}

/// Subtracts `arm_range` (`[min_val, max_val]`) in place from an unbounded `uncovered_intervals` list.
fn subtractIntervalFromUncoveredList(
    allocator: std.mem.Allocator,
    uncovered_intervals: *std.ArrayListUnmanaged(Interval128),
    arm_range: Interval128,
) !void {
    if (arm_range.min_val > arm_range.max_val) return;
    var i: usize = 0;
    while (i < uncovered_intervals.items.len) {
        const cur = uncovered_intervals.items[i];
        if (arm_range.max_val < cur.min_val or arm_range.min_val > cur.max_val) {
            i += 1;
            continue;
        }
        const has_left_rem = (arm_range.min_val > cur.min_val);
        const has_right_rem = (arm_range.max_val < cur.max_val);

        if (has_left_rem and has_right_rem) {
            uncovered_intervals.items[i] = .{ .min_val = cur.min_val, .max_val = arm_range.min_val - 1 };
            try uncovered_intervals.insert(
                allocator,
                i + 1,
                .{ .min_val = arm_range.max_val + 1, .max_val = cur.max_val },
            );
            i += 2;
        } else if (has_left_rem) {
            uncovered_intervals.items[i] = .{ .min_val = cur.min_val, .max_val = arm_range.min_val - 1 };
            i += 1;
        } else if (has_right_rem) {
            uncovered_intervals.items[i] = .{ .min_val = arm_range.max_val + 1, .max_val = cur.max_val };
            i += 1;
        } else {
            _ = uncovered_intervals.orderedRemove(i);
        }
    }
}

// ----------- Spine-Local Bidirectional Type Checker -----------

/// Active loop frame on `TypeChecker.loop_frames` tracking `:label` and value-break unification (`DR-21` `SE-05`, `SE-06`).
pub const LoopFrame = struct {
    /// Optional `:label` symbol (`SymbolId.none` when unlabeled).
    label: SymbolId = .none,
    /// Unified break value `TypeId` (`.never_ty` before first break).
    break_ty: TypeId = .never_ty,
    /// `true` once at least one `break val;` targets this loop.
    has_value_break: bool = false,
    /// `true` once at least one bare `break;` targets this loop.
    has_bare_break: bool = false,
    /// `true` for `loop { … }` (`SE-06`), `false` for `for` / `while` (`SE-05`).
    is_unconditional_loop: bool = false,
    /// `true` for `comptime for` loops where value `break` is forbidden (`E0412`).
    is_comptime_for: bool = false,
    /// `true` for labeled `fsm: match scrut { … }` frames (`SE-23`; skipped by unlabeled `break`/`continue`).
    is_labeled_match: bool = false,
    /// Expected scrutinee `TypeId` for `continue :fsm next_expr` transitions (`SE-23`).
    match_scrutinee_ty: TypeId = .err_ty,
    /// Target `.match_expr` AST `NodeIndex` for `continue :fsm next_expr` side-table recording (`SE-23`).
    match_ast_node: NodeIndex = .none,
    /// Active `defer_depth` when this loop was entered (`E0412` guard against jumping out of `defer`).
    defer_depth_at_entry: u32 = 0,
};

/// Bidirectional type checker and semantic verifier for a single compilation unit or `DefId`.
pub const TypeChecker = struct {
    /// Backing allocator for side tables and scratch buffers.
    allocator: std.mem.Allocator,
    /// Shared string interner.
    interner: *StringInterner,
    /// Shared canonical `InternPool`.
    pool: *InternPool,
    /// Shared `SymbolTable`.
    sym_table: *SymbolTable,
    /// Current source file handle.
    file_id: FileId,
    /// UTF-8 source buffer of `file_id`.
    source: []const u8,
    /// Read-only `TokenBuffer` of `file_id`.
    token_buffer: *const TokenBuffer,
    /// Read-only `LosslessCstArena` of `file_id`.
    cst_arena: *const LosslessCstArena,
    /// Read-only `AstArena` of `file_id`.
    ast_arena: *const AstArena,
    /// Optional diagnostic sink receiving `E0400`–`E0437`, `E0502`–`E0510`, and `W0401`–`W0402`.
    diagnostic_sink: ?*DiagnosticSink,
    /// Optional query database reference for cross-item `comptime` evaluation.
    db: ?*query_db.CompilerDb = null,
    /// Active target pointer layout (`TargetLayout.NATIVE_64` by default).
    target_layout: TargetLayout = TargetLayout.NATIVE_64,
    /// Compile-time `@cfg(expr)` target and build-mode environment (`SE-18`, synchronized with `db` when present).
    cfg_env: CfgEnv = .{},
    /// `true` when checking `test` and `bench` bodies (`SE-16`, synchronized with `db.is_including_tests` when present).
    is_including_tests: bool = true,
    /// Reverse lookup table mapping each `CstNodeIndex` to the outermost `NodeIndex` anchored at that CST node.
    cst_to_ast: []NodeIndex = &.{},
    /// Dense array mapping each AST `NodeIndex.asInt()` to its inferred/checked `TypeId`.
    node_types: []TypeId = &.{},
    /// Dense array mapping each AST `NodeIndex.asInt()` to its resolved `SymbolIndex` (`.none` by default).
    node_symbols: []SymbolIndex = &.{},
    /// Precomputed end offset in `ast_arena.extra_data` for each AST `NodeIndex` owning an `.extra` slice.
    node_extra_end: []u32 = &.{},
    /// Concrete generic / Type-Group `[TypeId…]` instantiation tuples keyed by call `NodeIndex.asInt()`.
    call_instantiations: std.AutoHashMapUnmanaged(u32, []TypeId) = .empty,
    /// `@from` `FromError` conversion `DefId`s keyed by `.try_expr` `NodeIndex.asInt()`.
    try_conversions: std.AutoHashMapUnmanaged(u32, DefId) = .empty,
    /// `@derive(From)` 0-based target enum variant ordinals keyed by `.try_expr` `NodeIndex.asInt()` (`SE-10`).
    try_from_variants: std.AutoHashMapUnmanaged(u32, u32) = .empty,
    /// Resolved `.narrow` / `.try_narrow` call metadata keyed by `.method_call` `NodeIndex.asInt()` (`D-11`).
    narrow_calls: std.AutoHashMapUnmanaged(u32, NarrowCallInfo) = .empty,
    /// Named / default call-argument mappings keyed by call `NodeIndex.asInt()` (`DR-21` `SE-07`).
    call_arg_mappings: std.AutoHashMapUnmanaged(u32, CallArgMapping) = .empty,
    /// Validated `FmtSpec` / `FmtArgs` interpolation descriptors keyed by `.string_lit` `NodeIndex.asInt()` (`SE-12`).
    string_interps: std.AutoHashMapUnmanaged(u32, StringInterpMeta) = .empty,
    /// State struct `TypeId` (`S` in `&mut S`) keyed by trailing-block `@builder` call `NodeIndex.asInt()` (`SE-22`).
    builder_block_calls: std.AutoHashMapUnmanaged(u32, TypeId) = .empty,
    /// Formal parameter ordinal receiving implicit `__builder` keyed by `@builder_item` call `NodeIndex.asInt()` (`SE-22`).
    implicit_builder_item_calls: std.AutoHashMapUnmanaged(u32, u16) = .empty,
    /// Target labeled `.match_expr` `NodeIndex` keyed by `continue :fsm expr` `NodeIndex.asInt()` (`SE-23`).
    labeled_match_continues: std.AutoHashMapUnmanaged(u32, NodeIndex) = .empty,
    /// Validated `@attribute_schema` instances collected across declarations, fields, and variants.
    attr_instances: std.ArrayListUnmanaged(AttrInstance) = .empty,
    /// `true` when checking a privileged `cx` / `core` library file permitted to declare `@std_cap_boundary`.
    is_stdlib_file: bool = false,
    /// `true` when `--internal-core` is enabled (`DR-21` `ADR-21B` kernel gate).
    is_internal_core: bool = false,
    /// Lazily synthesized `cx.mem.BumpArena` `TypeId` for `Context.scratch` (`D-04`).
    builtin_bump_arena_ty: TypeId = .err_ty,
    /// Active lexical `ScopeId` during body checking.
    current_scope: ScopeId = .none,
    /// Declared return `TypeId` of the enclosing function (`.unit_ty` at module level).
    current_fn_ret_ty: TypeId = .unit_ty,
    /// Expected break `TypeId` of the innermost `loop` expression.
    current_loop_break_ty: TypeId = .unit_ty,
    /// Counter generating unique ordinals for `bind_many_any_var` parameters.
    next_any_ordinal: u32 = 0,
    /// Active Bind-Once group variables within the current function signature (`SymbolId -> TypeId`).
    active_bind_once_vars: std.AutoHashMapUnmanaged(u32, TypeId) = .empty,
    /// Current recursion depth across type AST resolution, unification, and expression checking (`MAX_TYPE_DEPTH`).
    recursion_depth: u32 = 0,
    /// Nesting depth of active `defer` / `errdefer` cleanup bodies.
    defer_depth: u32 = 0,
    /// Nesting depth of loops opened *inside* the innermost `defer` / `errdefer` body.
    defer_inner_loop_depth: u32 = 0,
    /// Nesting depth of pure `comptime` evaluation contexts (`const`, `comptime { … }`, `comptime fn`).
    pure_comptime_depth: u32 = 0,
    /// Lexical scope depth boundary separating outer runtime bindings from `comptime`-local bindings.
    comptime_boundary_scope_depth: u16 = 0,
    /// Nesting depth of `comptime if` / `comptime match` branches whose condition is not statically folded yet.
    comptime_branch_guard_depth: u32 = 0,
    /// `true` while binding `comptime for` pattern variables so each binding receives `flags.is_comptime = true`.
    is_binding_comptime: bool = false,
    /// `true` when checking a direct positive `if` / `while` condition where `expr is Pat` bindings scope into `then`.
    is_direct_positive_cond: bool = false,
    /// `true` when checking a dominating `if` / `while` condition spine where `x := init` is permitted (`SE-02`).
    is_dominating_walrus_pos: bool = false,
    /// `true` inside negated `!(…)` or `is not` where pattern bindings must emit `E0214` (`SE-01`).
    is_negated_is_context: bool = false,
    /// `true` on the LHS of `and` when a subsequent conjunct could re-read a moved `@linear` scrutinee (`SE-01`).
    has_following_and_conjunct: bool = false,
    /// Maximum allowed earlier parameter ordinal when checking a parameter `= default_expr` (`SE-07`).
    active_default_param_max_ordinal: ?u16 = null,
    /// Stack of active `for` / `while` / `loop` frames for `:label` and value-break resolution (`SE-05`, `SE-06`).
    loop_frames: [32]LoopFrame = undefined,
    /// Current depth of `loop_frames`.
    loop_frame_depth: u8 = 0,
    /// Stack tracking whether each enclosing `[…]` index bracket supports `$` length (`SE-04`, `E0416`).
    bracket_len_stack: [32]bool = @splat(false),
    /// Current depth of `bracket_len_stack`.
    bracket_len_depth: u8 = 0,
    /// `true` while resolving a function signature (`extractFnParamFromCst` or return type).
    is_in_fn_signature: bool = false,
    /// `true` while resolving a function return type (rejects existential `-> any Group`).
    is_in_return_type_pos: bool = false,
    /// `true` while checking an `extern` function body or default parameter where `context` is unavailable (`E0401`).
    is_extern_fn: bool = false,
    /// `true` inside `async fn`, `async` closures, `async { … }` blocks, `async test`, or `task_group` nursery bodies (`E0438`).
    is_in_async: bool = false,
    /// `true` while checking the direct nursery closure argument of `task_group(|group| { … })`.
    is_in_nursery_cb_arg: bool = false,
    /// Lexical scope depth of the innermost enclosing `task_group` nursery callback (`E0309`).
    nursery_scope_depth: ?u16 = null,
    /// `true` once Pass 1 (`resolveModuleSignatures`) has propagated `Copy` / `Drop` flags across all nominals.
    has_completed_pass1: bool = false,
    /// `true` once the `cx.meta` reflection mirror types have been lazily synthesized.
    has_reflection_mirrors: bool = false,
    /// Lazily synthesized `cx.meta.MetaId` `TypeId`.
    mirror_meta_id_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.PrimKind` `TypeId`.
    mirror_prim_kind_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.FieldInfo` `TypeId`.
    mirror_field_info_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.StructInfo` `TypeId`.
    mirror_struct_info_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.VariantInfo` `TypeId`.
    mirror_variant_info_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.EnumInfo` `TypeId`.
    mirror_enum_info_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.TypeKind` `TypeId`.
    mirror_type_kind_ty: TypeId = .err_ty,
    /// Lazily synthesized `cx.meta.TypeInfo` `TypeId`.
    mirror_type_info_ty: TypeId = .err_ty,
    /// Active `const` evaluation stack for cycle detection (`E0509`).
    active_const_eval: [32]SymbolIndex = @splat(.none),
    /// Current length of `active_const_eval`.
    active_const_eval_len: u8 = 0,
    /// Nesting depth of `unsafe { … }` blocks and `unsafe fn` bodies (`ADR-22F`).
    unsafe_depth: u32 = 0,
    /// `true` while evaluating the direct place operand of `&raw` / `&raw mut`.
    is_in_raw_addr_of: bool = false,
    /// Stack of active `@builder` state struct `TypeId`s (`S` in `&mut S`, `SE-22`).
    active_builder_stack: [16]TypeId = @splat(.err_ty),
    /// Current depth of `active_builder_stack` (`SE-22`).
    active_builder_depth: u8 = 0,
    /// `true` while checking a `subscript` `let` or `inout` accessor arm (`SE-21`).
    is_in_subscript_arm: bool = false,
    /// `true` when checking an `inout` (`&mut T`) `subscript` arm (`SE-21`).
    is_in_subscript_inout_arm: bool = false,
    /// Expected element `TypeId` yielded by the active `subscript` arm (`SE-21`).
    current_subscript_elem_ty: TypeId = .err_ty,
    /// Count of `yield` statements encountered in the active `subscript` arm (`SE-21`).
    subscript_yield_count: u32 = 0,
    /// `true` while resolving the direct pointee of `*opaque` / `*mut opaque` (`ADR-22F`).
    is_allowing_opaque_type: bool = false,
    /// Set of `SymbolIndex` values pruned by `@cfg(false)` (`SE-18`).
    cfg_disabled_symbols: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// `true` when checking an explicit `own expr` operand (`ADR-22B`).
    is_in_explicit_own_expr: bool = false,
    /// Last `SymbolIndex` resolved by `resolveNamedOrGroupTypeRaw` (used by `.generic_type` on generic `type` aliases).
    last_resolved_type_sym: SymbolIndex = .none,

    /// Initializes a `TypeChecker` for `file_id`, building the shared $O(N)$ lookup and side tables.
    pub fn init(
        allocator: std.mem.Allocator,
        interner: *StringInterner,
        pool: *InternPool,
        sym_table: *SymbolTable,
        file_id: FileId,
        source: []const u8,
        token_buffer: *const TokenBuffer,
        cst_arena: *const LosslessCstArena,
        ast_arena: *const AstArena,
        diagnostic_sink: ?*DiagnosticSink,
    ) !TypeChecker {
        const ast_len = ast_arena.countNodes();

        const cst_map = try syntax_arenas.computeCstToAstMap(allocator, cst_arena.countNodes(), ast_arena);
        errdefer if (cst_map.len > 0) allocator.free(cst_map);

        const ty_table = try allocator.alloc(TypeId, ast_len);
        errdefer if (ty_table.len > 0) allocator.free(ty_table);
        @memset(ty_table, .err_ty);

        const sym_node_table = try allocator.alloc(SymbolIndex, ast_len);
        errdefer if (sym_node_table.len > 0) allocator.free(sym_node_table);
        @memset(sym_node_table, .none);

        const extra_end_table = try syntax_arenas.computeAstNodeExtraEnds(allocator, ast_arena);
        errdefer if (extra_end_table.len > 0) allocator.free(extra_end_table);

        const mod_scope = sym_table.file_module_scopes.get(file_id.asInt()) orelse sym_table.prelude_scope;
        const file_pkg_id = sym_table.getFilePackageId(file_id);

        return .{
            .allocator = allocator,
            .interner = interner,
            .pool = pool,
            .sym_table = sym_table,
            .file_id = file_id,
            .source = source,
            .token_buffer = token_buffer,
            .cst_arena = cst_arena,
            .ast_arena = ast_arena,
            .diagnostic_sink = diagnostic_sink,
            .cfg_env = sym_table.effectiveCfgEnvForFile(file_id),
            .is_including_tests = sym_table.is_including_tests and (file_pkg_id == .root),
            .cst_to_ast = cst_map,
            .node_types = ty_table,
            .node_symbols = sym_node_table,
            .node_extra_end = extra_end_table,
            .current_scope = mod_scope,
        };
    }

    /// Releases side tables owned by `self`.
    pub fn deinit(self: *TypeChecker) void {
        if (self.cst_to_ast.len > 0) self.allocator.free(self.cst_to_ast);
        if (self.node_types.len > 0) self.allocator.free(self.node_types);
        if (self.node_symbols.len > 0) self.allocator.free(self.node_symbols);
        if (self.node_extra_end.len > 0) self.allocator.free(self.node_extra_end);
        var inst_iter = self.call_instantiations.valueIterator();
        while (inst_iter.next()) |slice_ptr| {
            if (slice_ptr.*.len > 0) self.allocator.free(slice_ptr.*);
        }
        self.call_instantiations.deinit(self.allocator);
        self.try_conversions.deinit(self.allocator);
        self.try_from_variants.deinit(self.allocator);
        self.narrow_calls.deinit(self.allocator);
        var map_iter = self.call_arg_mappings.valueIterator();
        while (map_iter.next()) |mapping_ptr| {
            if (mapping_ptr.provided_slots.len > 0) self.allocator.free(mapping_ptr.provided_slots);
        }
        self.call_arg_mappings.deinit(self.allocator);
        var interp_iter = self.string_interps.valueIterator();
        while (interp_iter.next()) |interp_ptr| {
            if (interp_ptr.holes.len > 0) self.allocator.free(interp_ptr.holes);
        }
        self.string_interps.deinit(self.allocator);
        self.builder_block_calls.deinit(self.allocator);
        self.implicit_builder_item_calls.deinit(self.allocator);
        self.labeled_match_continues.deinit(self.allocator);
        for (self.attr_instances.items) |attr_inst| {
            if (attr_inst.fields.len > 0) self.allocator.free(attr_inst.fields);
        }
        self.attr_instances.deinit(self.allocator);
        self.active_bind_once_vars.deinit(self.allocator);
        self.cfg_disabled_symbols.deinit(self.allocator);
        self.* = undefined;
    }

    /// Records `ty` for `node_id` in `self.node_types` and returns `ty`.
    inline fn recordNodeType(self: *TypeChecker, node_id: NodeIndex, ty: TypeId) TypeId {
        if (!node_id.isNone() and node_id.asInt() < self.node_types.len) {
            self.node_types[node_id.asInt()] = ty;
        }
        return ty;
    }

    /// Returns the recorded `TypeId` for `node_id` in `self.node_types`, or `.err_ty` if unset.
    inline fn getNodeType(self: *const TypeChecker, node_id: NodeIndex) TypeId {
        if (!node_id.isNone() and node_id.asInt() < self.node_types.len) {
            return self.node_types[node_id.asInt()];
        }
        return .err_ty;
    }

    /// Records `sym_idx` for `node_id` in `self.node_symbols`.
    inline fn recordNodeSymbol(self: *TypeChecker, node_id: NodeIndex, sym_idx: SymbolIndex) void {
        if (!node_id.isNone() and node_id.asInt() < self.node_symbols.len) {
            self.node_symbols[node_id.asInt()] = sym_idx;
        }
    }

    /// Records inferred concrete `type_args` for `call_id` in `self.call_instantiations`.
    fn recordCallInstantiation(self: *TypeChecker, call_id: NodeIndex, type_args: []const TypeId) !void {
        if (call_id.isNone() or type_args.len == 0) return;
        const owned_slice = try self.allocator.dupe(TypeId, type_args);
        errdefer self.allocator.free(owned_slice);
        if (try self.call_instantiations.fetchPut(self.allocator, call_id.asInt(), owned_slice)) |prev_kv| {
            if (prev_kv.value.len > 0) self.allocator.free(prev_kv.value);
        }
    }

    /// Records a named or default call-argument mapping for `call_id` in `self.call_arg_mappings` (`DR-21` `SE-07`).
    fn recordCallArgMapping(
        self: *TypeChecker,
        call_id: NodeIndex,
        callee_sym: SymbolIndex,
        slots: []const CallArgSlot,
        total_params: u16,
        has_reordered_or_default: bool,
    ) !void {
        if (call_id.isNone()) return;
        const owned_slots = try self.allocator.dupe(CallArgSlot, slots);
        errdefer if (owned_slots.len > 0) self.allocator.free(owned_slots);
        if (try self.call_arg_mappings.fetchPut(self.allocator, call_id.asInt(), .{
            .callee_sym = callee_sym,
            .provided_slots = owned_slots,
            .total_params = total_params,
            .has_reordered_or_default = has_reordered_or_default,
        })) |prev_kv| {
            if (prev_kv.value.provided_slots.len > 0) self.allocator.free(prev_kv.value.provided_slots);
        }
    }

    /// Computes the target-architecture `TypeLayout` of `type_id` using `self.pool` and `self.sym_table`.
    pub fn computeTypeLayout(
        self: *const TypeChecker,
        type_id: TypeId,
        target_layout: TargetLayout,
    ) TypeLayout {
        return computeTypeLayoutWithPool(self.pool, self.sym_table, type_id, target_layout);
    }

    /// Resolves the flattened top-level `AstArena` item matching `target_ordinal`, expanding `extern_block_decl` members.
    fn findTopLevelDefAstNode(self: *const TypeChecker, target_ordinal: u12) NodeIndex {
        if (self.ast_arena.countNodes() == 0) return .none;
        const root_node = self.ast_arena.getNode(.root);
        if (root_node.lhs.tag != .extra or root_node.rhs.tag != .extra or root_node.rhs.payload == 0) return .none;
        const item_slice = self.ast_arena.getExtraSlice(
            ExtraIndex.fromInt(root_node.lhs.payload),
            root_node.rhs.payload,
        );
        var top_ordinal: u12 = 0;
        for (item_slice) |raw_node_idx| {
            const cand_idx = NodeIndex.fromInt(raw_node_idx);
            if (cand_idx.asInt() >= self.ast_arena.countNodes()) continue;
            const cand_tag = self.ast_arena.getNode(cand_idx).tag;
            if (cand_tag == .item_hole) continue;
            if (!self.is_including_tests and (cand_tag == .test_decl or cand_tag == .bench_decl)) continue;
            if (cand_tag == .extern_block_decl) {
                for (self.ast_arena.getExternBlockItems(cand_idx)) |ext_raw_idx| {
                    const ext_idx = NodeIndex.fromInt(ext_raw_idx);
                    if (ext_idx.asInt() >= self.ast_arena.countNodes()) continue;
                    const ext_tag = self.ast_arena.getNode(ext_idx).tag;
                    if (ext_tag == .fn_decl or ext_tag == .extern_static_decl or ext_tag == .const_decl) {
                        if (top_ordinal == target_ordinal) return ext_idx;
                        if (top_ordinal < std.math.maxInt(u12)) top_ordinal += 1;
                    }
                }
                continue;
            }
            if (top_ordinal == target_ordinal) return cand_idx;
            if (top_ordinal < std.math.maxInt(u12)) top_ordinal += 1;
        }
        return .none;
    }

    /// Extracts window-scoped `BodySemanticSideTables` (`[ast_start .. ast_end)`) for `def_id`.
    pub fn extractBodySemanticSideTables(
        self: *const TypeChecker,
        allocator: std.mem.Allocator,
        def_id: DefId,
    ) !BodySemanticSideTables {
        var ast_start: u32 = 0;
        var ast_end: u32 = @intCast(self.ast_arena.countNodes());

        if (!def_id.isNone()) {
            var target_cst: CstNodeIndex = .none;
            var target_ast: NodeIndex = .none;
            if (self.sym_table.def_to_symbol.get(def_id.asInt())) |sym_idx| {
                const sym = self.sym_table.getSymbol(sym_idx).*;
                target_cst = sym.cst_node;
                target_ast = sym.ast_node;
            } else {
                target_ast = self.findTopLevelDefAstNode(def_id.itemIndex());
                if (!target_ast.isNone()) {
                    target_cst = self.ast_arena.getCstOrigin(target_ast);
                }
            }

            if (!target_cst.isNone() and target_cst.asInt() < self.cst_arena.countNodes()) {
                const cst_start: usize = target_cst.asInt();
                const cst_rec = self.cst_arena.getNode(target_cst);
                const cst_end: usize = @min(
                    cst_start + @max(@as(usize, cst_rec.subtree_size), 1),
                    self.cst_to_ast.len,
                );
                var min_ast: u32 = std.math.maxInt(u32);
                var max_ast: u32 = 0;
                for (self.cst_to_ast[cst_start..cst_end]) |mapped_ast| {
                    if (!mapped_ast.isNone()) {
                        if (mapped_ast.asInt() < min_ast) min_ast = mapped_ast.asInt();
                        if (mapped_ast.asInt() > max_ast) max_ast = mapped_ast.asInt();
                    }
                }
                if (min_ast <= max_ast and max_ast < self.ast_arena.countNodes()) {
                    ast_start = min_ast;
                    ast_end = max_ast + 1;
                } else if (!target_ast.isNone() and target_ast.asInt() < self.ast_arena.countNodes()) {
                    ast_start = target_ast.asInt();
                    ast_end = target_ast.asInt() + 1;
                }
            } else if (!target_ast.isNone() and target_ast.asInt() < self.ast_arena.countNodes()) {
                ast_start = target_ast.asInt();
                ast_end = target_ast.asInt() + 1;
            }
        }

        return self.extractWindowSideTables(allocator, def_id, ast_start, ast_end);
    }

    /// Extracts whole-file `BodySemanticSideTables` (`[0 .. ast_arena.countNodes())`).
    pub fn extractFileSemanticSideTables(
        self: *const TypeChecker,
        allocator: std.mem.Allocator,
    ) !BodySemanticSideTables {
        return self.extractWindowSideTables(
            allocator,
            .NONE,
            0,
            @intCast(self.ast_arena.countNodes()),
        );
    }

    /// Copies side tables strictly intersecting `[ast_start .. ast_end)` into a new `BodySemanticSideTables`.
    fn extractWindowSideTables(
        self: *const TypeChecker,
        allocator: std.mem.Allocator,
        def_id: DefId,
        ast_start: u32,
        ast_end: u32,
    ) !BodySemanticSideTables {
        const clamped_end: usize = @min(@as(usize, ast_end), self.node_types.len);
        const clamped_start: usize = @min(@as(usize, ast_start), clamped_end);

        const owned_types = try allocator.dupe(TypeId, self.node_types[clamped_start..clamped_end]);
        errdefer if (owned_types.len > 0) allocator.free(owned_types);

        const owned_symbols = try allocator.dupe(SymbolIndex, self.node_symbols[clamped_start..clamped_end]);
        errdefer if (owned_symbols.len > 0) allocator.free(owned_symbols);

        var result = BodySemanticSideTables{
            .allocator = allocator,
            .def_id = def_id,
            .ast_start = @intCast(clamped_start),
            .ast_end = @intCast(clamped_end),
            .node_types = owned_types,
            .node_symbols = owned_symbols,
        };
        errdefer result.deinit();

        var inst_iter = self.call_instantiations.iterator();
        while (inst_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                const duped_args = try allocator.dupe(TypeId, entry.value_ptr.*);
                errdefer if (duped_args.len > 0) allocator.free(duped_args);
                try result.call_instantiations.put(allocator, raw_node - result.ast_start, duped_args);
            }
        }

        var try_iter = self.try_conversions.iterator();
        while (try_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                try result.try_conversions.put(allocator, raw_node - result.ast_start, entry.value_ptr.*);
            }
        }

        var try_var_iter = self.try_from_variants.iterator();
        while (try_var_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                try result.try_from_variants.put(allocator, raw_node - result.ast_start, entry.value_ptr.*);
            }
        }

        var narrow_iter = self.narrow_calls.iterator();
        while (narrow_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                try result.narrow_calls.put(allocator, raw_node - result.ast_start, entry.value_ptr.*);
            }
        }

        var map_iter = self.call_arg_mappings.iterator();
        while (map_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                const duped_slots = try allocator.dupe(CallArgSlot, entry.value_ptr.provided_slots);
                errdefer if (duped_slots.len > 0) allocator.free(duped_slots);
                try result.call_arg_mappings.put(allocator, raw_node - result.ast_start, .{
                    .callee_sym = entry.value_ptr.callee_sym,
                    .provided_slots = duped_slots,
                    .total_params = entry.value_ptr.total_params,
                    .has_reordered_or_default = entry.value_ptr.has_reordered_or_default,
                });
            }
        }

        var interp_iter = self.string_interps.iterator();
        while (interp_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                const duped_holes = try allocator.dupe(InterpHoleSpec, entry.value_ptr.holes);
                errdefer if (duped_holes.len > 0) allocator.free(duped_holes);
                try result.string_interps.put(allocator, raw_node - result.ast_start, .{
                    .is_fmt_args_mode = entry.value_ptr.is_fmt_args_mode,
                    .is_multiline = entry.value_ptr.is_multiline,
                    .delimiter_width = entry.value_ptr.delimiter_width,
                    .holes = duped_holes,
                });
            }
        }

        var builder_blk_iter = self.builder_block_calls.iterator();
        while (builder_blk_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                try result.builder_block_calls.put(allocator, raw_node - result.ast_start, entry.value_ptr.*);
            }
        }

        var builder_item_iter = self.implicit_builder_item_calls.iterator();
        while (builder_item_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                try result.implicit_builder_item_calls.put(
                    allocator,
                    raw_node - result.ast_start,
                    entry.value_ptr.*,
                );
            }
        }

        var match_cont_iter = self.labeled_match_continues.iterator();
        while (match_cont_iter.next()) |entry| {
            const raw_node = entry.key_ptr.*;
            if (raw_node >= result.ast_start and raw_node < result.ast_end) {
                try result.labeled_match_continues.put(
                    allocator,
                    raw_node - result.ast_start,
                    entry.value_ptr.*,
                );
            }
        }

        var matching_attrs: std.ArrayListUnmanaged(AttrInstance) = .empty;
        errdefer {
            for (matching_attrs.items) |attr_item| {
                if (attr_item.fields.len > 0) allocator.free(attr_item.fields);
            }
            matching_attrs.deinit(allocator);
        }
        for (self.attr_instances.items) |attr_inst| {
            if (def_id.isNone() or attr_inst.owner_def_id == def_id) {
                const duped_fields = try allocator.dupe(AttrFieldInit, attr_inst.fields);
                errdefer if (duped_fields.len > 0) allocator.free(duped_fields);
                try matching_attrs.append(allocator, .{
                    .schema_type_id = attr_inst.schema_type_id,
                    .target_symbol = attr_inst.target_symbol,
                    .owner_def_id = attr_inst.owner_def_id,
                    .attr_span = attr_inst.attr_span,
                    .fields = duped_fields,
                });
            }
        }
        result.attr_instances = try matching_attrs.toOwnedSlice(allocator);
        return result;
    }

    /// Returns the `extra_data` slice owned by `node_id` in $O(1)$ time.
    pub fn getNodeExtraSlice(self: *const TypeChecker, node_id: NodeIndex, is_rhs: bool) []const u32 {
        if (node_id.isNone() or node_id.asInt() >= self.ast_arena.countNodes()) return &.{};
        const ast_node = self.ast_arena.getNode(node_id);
        const op = if (is_rhs) ast_node.rhs else ast_node.lhs;
        if (op.tag != .extra) return &.{};
        const start_idx: usize = op.payload;
        const end_idx: usize = @min(
            @as(usize, self.node_extra_end[node_id.asInt()]),
            self.ast_arena.extra_data.items.len,
        );
        if (start_idx >= end_idx) return &.{};
        return self.ast_arena.extra_data.items[start_idx..end_idx];
    }

    /// Computes the source `Span` of an AST node from its CST origin or `main_token`.
    pub fn getAstNodeSpan(self: *const TypeChecker, node_id: NodeIndex) Span {
        if (node_id.isNone() or node_id.asInt() >= self.ast_arena.countNodes()) {
            return Span.init(self.file_id, 0, 0);
        }
        const ast_node = self.ast_arena.getNode(node_id);
        if (!ast_node.main_token.isNone() and ast_node.main_token.asInt() < self.token_buffer.countTokens()) {
            return self.token_buffer.getTokenSpan(self.file_id, ast_node.main_token);
        }
        return Span.init(self.file_id, 0, 0);
    }

    /// Finds the outermost AST `NodeIndex` anchored inside the CST range `[cst_start .. cst_end)`.
    fn findFirstAstInCstRange(self: *const TypeChecker, cst_start: usize, cst_end: usize) NodeIndex {
        const clamped_end = @min(cst_end, self.cst_to_ast.len);
        var cur = cst_start;
        while (cur < clamped_end) : (cur += 1) {
            const mapped = self.cst_to_ast[cur];
            if (!mapped.isNone()) return mapped;
        }
        return .none;
    }

    // --------- Pass 1: Module Signature & Type Resolution ---------

    /// Resolves all top-level nominal types, type aliases, type groups, constants, and function signatures.
    pub fn resolveModuleSignatures(self: *TypeChecker) !void {
        symbol_resolver.suppressCPrimitiveTypeCasingWarnings(self.diagnostic_sink, self.file_id, self.source);
        const mod_scope = self.sym_table.file_module_scopes.get(self.file_id.asInt()) orelse return;
        try self.pruneCfgDisabledScopeItemsRecursive(mod_scope);
        try self.resolveScopeSignaturesRecursive(mod_scope);
        try self.propagateNominalFlagsFixpoint();
        if (self.ast_arena.countNodes() > 0) {
            const root_node = self.ast_arena.getNode(.root);
            if (root_node.lhs.tag == .extra and root_node.rhs.tag == .extra and root_node.rhs.payload > 0) {
                const root_items = self.ast_arena.getExtraSlice(
                    ExtraIndex.fromInt(root_node.lhs.payload),
                    root_node.rhs.payload,
                );
                try self.registerImplTraitPairsInItemSlice(mod_scope, root_items);
            }
        }
        try self.propagateNominalFlagsFixpoint();
        self.has_completed_pass1 = true;
        try self.verifyAllPass1FnParamModes();
        try self.verifyScopeDerivesAndAttributesRecursive(mod_scope);
        try self.checkScopeDefaultParamExprsRecursive(mod_scope);
    }

    /// Enforces `ADR-22B` `E0421` across all Pass-1 `fn` signatures after nominal `Copy` / `Drop` flags converge.
    fn verifyAllPass1FnParamModes(self: *TypeChecker) !void {
        const sym_count = self.sym_table.countSymbols();
        var idx: u32 = 0;
        while (idx < sym_count) : (idx += 1) {
            const sym_idx = SymbolIndex.fromInt(idx);
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const fn_sym = self.sym_table.getSymbol(sym_idx).*;
            if (fn_sym.flags.is_builtin or fn_sym.flags.is_imported) continue;
            if (!fn_sym.decl_span.file_id.isNone() and fn_sym.decl_span.file_id != self.file_id) continue;
            if (fn_sym.kind != .fn_sym or fn_sym.flags.is_extern or fn_sym.extra_flags.is_test) continue;
            const sig_view = self.pool.getFnSignatureView(fn_sym.type_id) orelse continue;
            const param_specs = self.sym_table.getFnParamSpecs(sym_idx);

            var p_i: usize = 0;
            while (p_i < sig_view.paramCount()) : (p_i += 1) {
                const mode = sig_view.getParamMode(p_i);
                if (mode != .let_mode) continue;
                const is_comptime_p = p_i < 64 and (fn_sym.is_comptime_param_mask & (@as(u64, 1) << @intCast(p_i))) != 0;
                if (is_comptime_p) continue;
                const param_ty = sig_view.getParamType(p_i);
                if (param_ty.isError()) continue;
                const param_tag = self.pool.getTag(param_ty);
                if (param_tag == .ref_ty or param_tag == .mut_ref_ty or param_tag == .raw_ptr_ty or
                    param_tag == .slice_ty or param_tag == .soa_slice_ty or param_tag == .fn_ty or
                    param_tag == .bind_once_group_var or param_tag == .bind_many_any_var)
                {
                    continue;
                }
                if (self.isCopyType(param_ty)) continue;

                var param_span = fn_sym.decl_span;
                var pname: []const u8 = if (p_i < param_specs.len and param_specs[p_i].name_text.len > 0)
                    param_specs[p_i].name_text
                else
                    "x";
                if (!fn_sym.target_scope.isNone()) {
                    for (self.sym_table.getScopeMembers(fn_sym.target_scope)) |mem_idx| {
                        const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind == .param_sym and mem_sym.member_ordinal == p_i) {
                            param_span = mem_sym.decl_span;
                            if (mem_sym.name_text.len > 0) pname = mem_sym.name_text;
                            break;
                        }
                    }
                }
                var ty_buf: [96]u8 = undefined;
                const ty_str = self.pool.formatType(param_ty, self.sym_table, &ty_buf);
                var msg_buf: [240]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "by-value parameter `{s}: {s}` requires `{s}: Copy`; borrow as `{s}: &{s}` or move as `{s}: own {s}`",
                    .{ pname, ty_str, ty_str, pname, ty_str, pname, ty_str },
                ) catch "non-`Copy` parameter cannot be passed bare by value; use `&T` or `own T`";
                try self.emitDiagnosticSimple(
                    .e0421_non_copy_value_parameter,
                    param_span,
                    msg,
                    "help: write `&T` to borrow or `own T` to transfer ownership",
                );
            }
        }
    }

    /// Returns `true` if `sym_idx` was pruned by a false `@cfg(…)` predicate (`SE-18`).
    pub fn isSymbolCfgDisabled(self: *const TypeChecker, sym_idx: SymbolIndex) bool {
        if (sym_idx.isNone()) return false;
        return self.cfg_disabled_symbols.contains(sym_idx.asInt());
    }

    /// Evaluates `@cfg(…)` attributes across `scope_id` and prunes disabled items before Pass 1 (`SE-18`).
    fn pruneCfgDisabledScopeItemsRecursive(self: *TypeChecker, scope_id: ScopeId) anyerror!void {
        if (scope_id.isNone()) return;
        const scope_file_id = self.sym_table.scope_arena.getScope(scope_id).file_id;
        const scope_kind = self.sym_table.scope_arena.getScope(scope_id).kind;
        const members_copy = try self.allocator.dupe(
            SymbolIndex,
            self.sym_table.getScopeMembers(scope_id),
        );
        defer self.allocator.free(members_copy);

        for (members_copy) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin) continue;
            if (sym.flags.is_imported and !sym.has_cfg_attr) continue;

            const is_in_current_file = if (sym.flags.is_imported)
                scope_file_id == self.file_id
            else
                sym.decl_span.file_id == self.file_id;

            if (is_in_current_file and (!sym.cst_node.isNone() or !sym.enclosing_cfg_cst.isNone())) {
                var is_enabled = true;
                if (!sym.enclosing_cfg_cst.isNone()) {
                    if (!(try self.evaluateCstNodeCfgAttributesMode(sym.enclosing_cfg_cst, false))) {
                        is_enabled = false;
                    }
                }
                if (is_enabled and !sym.cst_node.isNone()) {
                    const should_emit_diags = !sym.flags.is_imported;
                    if (!(try self.evaluateCstNodeCfgAttributesMode(sym.cst_node, should_emit_diags))) {
                        is_enabled = false;
                    }
                }

                const scoped_key: u64 = (@as(u64, sym.name.asInt()) << 32) |
                    (@as(u64, @backingInt(sym.namespace)) << 30) |
                    @as(u64, scope_id.asInt() & 0x3FFF_FFFF);

                if (!is_enabled) {
                    try self.cfg_disabled_symbols.put(self.allocator, sym_idx.asInt(), {});
                    self.sym_table.getSymbolMut(sym_idx).flags.is_used = true;
                    if (self.sym_table.scoped_map.get(scoped_key)) |mapped_idx| {
                        if (mapped_idx == sym_idx) {
                            _ = self.sym_table.scoped_map.remove(scoped_key);
                        }
                    }
                    continue;
                }

                // Promote an enabled `@cfg` twin into `scoped_map` if an earlier disabled twin vacated the slot,
                // or emit deferred `E0408` if two active twins remain enabled simultaneously (`SE-18`):
                if (!sym.name.isNone()) {
                    if (self.sym_table.scoped_map.get(scoped_key)) |prev_idx| {
                        if (prev_idx != sym_idx) {
                            if (self.isSymbolCfgDisabled(prev_idx)) {
                                try self.sym_table.scoped_map.put(self.sym_table.allocator, scoped_key, sym_idx);
                            } else if (sym.has_cfg_attr or self.sym_table.getSymbol(prev_idx).has_cfg_attr) {
                                const prev_sym = self.sym_table.getSymbol(prev_idx).*;
                                const is_local_shadow = (scope_kind == .block_scope or
                                    scope_kind == .match_arm_scope or scope_kind == .loop_scope) and
                                    (sym.kind == .local_let_sym or sym.kind == .local_var_sym);
                                const is_distinct_tb = (sym.extra_flags.is_test or sym.extra_flags.is_bench) and
                                    (prev_sym.extra_flags.is_test != sym.extra_flags.is_test or
                                        prev_sym.extra_flags.is_bench != sym.extra_flags.is_bench);
                                if (prev_sym.kind != .overload_group_sym and !is_local_shadow and !is_distinct_tb and
                                    (!prev_sym.flags.is_imported or !sym.flags.is_imported))
                                {
                                    if (self.diagnostic_sink) |sink| {
                                        const is_missing_ov = sym.namespace == .value_ns and
                                            sym.kind == .fn_sym and prev_sym.kind == .fn_sym;
                                        try symbol_resolver.emitDuplicateDefinitionDiagnostic(
                                            sink,
                                            sym.name_text,
                                            sym.decl_span,
                                            prev_sym.decl_span,
                                            is_missing_ov,
                                        );
                                    }
                                }
                            }
                        }
                    } else {
                        try self.sym_table.scoped_map.put(self.sym_table.allocator, scoped_key, sym_idx);
                    }
                }
            }
            if (!sym.target_scope.isNone() and !sym.flags.is_imported) {
                switch (sym.kind) {
                    .module_sym => {
                        if (self.sym_table.scope_arena.getScope(sym.target_scope).file_id == self.file_id) {
                            try self.pruneCfgDisabledScopeItemsRecursive(sym.target_scope);
                        }
                    },
                    .struct_sym, .union_sym, .bit_field_sym, .enum_sym, .trait_sym => {
                        try self.pruneCfgDisabledScopeItemsRecursive(sym.target_scope);
                    },
                    else => {},
                }
            }
        }
    }

    /// Quietly evaluates leading `@cfg(…)` attributes on `cst_node` without emitting duplicate diagnostics.
    pub fn isCstNodeCfgEnabled(self: *TypeChecker, cst_node: CstNodeIndex) bool {
        return self.evaluateCstNodeCfgAttributesMode(cst_node, false) catch true;
    }

    /// Evaluates `@cfg(…)` attributes on `cst_node` with configurable diagnostic emission (`is_emitting_diags`).
    fn evaluateCstNodeCfgAttributesMode(
        self: *TypeChecker,
        cst_node: CstNodeIndex,
        is_emitting_diags: bool,
    ) anyerror!bool {
        var pkg_cfg = self.cfg_env;
        pkg_cfg.owner_pkg_id = self.sym_table.getFilePackageId(self.file_id);
        pkg_cfg.sym_table_features = self.sym_table;
        return symbol_resolver.evaluateCstNodeCfgWithEnv(
            &pkg_cfg,
            self.file_id,
            self.source,
            self.token_buffer,
            self.cst_arena,
            cst_node,
            if (is_emitting_diags) self.diagnostic_sink else null,
        );
    }

    /// Evaluates all leading `@cfg(…)` attributes on `cst_node`, returning `false` if any evaluates to `false`.
    fn evaluateCstNodeCfgAttributes(self: *TypeChecker, cst_node: CstNodeIndex) anyerror!bool {
        var pkg_cfg = self.cfg_env;
        pkg_cfg.owner_pkg_id = self.sym_table.getFilePackageId(self.file_id);
        pkg_cfg.sym_table_features = self.sym_table;
        return symbol_resolver.evaluateCstNodeCfgWithEnv(
            &pkg_cfg,
            self.file_id,
            self.source,
            self.token_buffer,
            self.cst_arena,
            cst_node,
            self.diagnostic_sink,
        );
    }

    /// Type-checks `param: T = default_expr` initializers across `scope_id` (`DR-21` `SE-07`).
    fn checkScopeDefaultParamExprsRecursive(self: *TypeChecker, scope_id: ScopeId) anyerror!void {
        if (scope_id.isNone()) return;
        const members_copy = try self.allocator.dupe(
            SymbolIndex,
            self.sym_table.getScopeMembers(scope_id),
        );
        defer self.allocator.free(members_copy);

        for (members_copy) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin or sym.flags.is_imported) continue;
            switch (sym.kind) {
                .fn_sym => {
                    try self.checkFnDefaultParamExprs(sym_idx);
                },
                .module_sym => {
                    if (!sym.target_scope.isNone() and
                        self.sym_table.scope_arena.getScope(sym.target_scope).file_id == self.file_id)
                    {
                        try self.checkScopeDefaultParamExprsRecursive(sym.target_scope);
                    }
                },
                .struct_sym, .union_sym, .bit_field_sym, .enum_sym, .trait_sym => {
                    if (!sym.target_scope.isNone()) {
                        try self.checkScopeDefaultParamExprsRecursive(sym.target_scope);
                    }
                },
                else => {},
            }
        }
    }

    /// Type-checks each default parameter initializer on `fn_sym_idx` in `fn_sym.target_scope` (`SE-07`).
    fn checkFnDefaultParamExprs(self: *TypeChecker, fn_sym_idx: SymbolIndex) !void {
        const fn_sym = self.sym_table.getSymbol(fn_sym_idx).*;
        if (fn_sym.decl_span.file_id != self.file_id or fn_sym.target_scope.isNone()) return;
        const specs_mut = self.sym_table.getFnParamSpecsMut(fn_sym_idx);
        if (specs_mut.len == 0) return;
        const sig_view = self.pool.getFnSignatureView(fn_sym.type_id) orelse return;

        const saved_scope = self.current_scope;
        const saved_max_ord = self.active_default_param_max_ordinal;
        const saved_extern = self.is_extern_fn;
        self.current_scope = fn_sym.target_scope;
        self.is_extern_fn = fn_sym.flags.is_extern;
        defer {
            self.current_scope = saved_scope;
            self.active_default_param_max_ordinal = saved_max_ord;
            self.is_extern_fn = saved_extern;
        }

        for (specs_mut, 0..) |*spec, idx| {
            if (!spec.has_default) continue;
            if (spec.decl_file_id != self.file_id) continue;
            const param_ty = sig_view.getParamType(idx);
            if (spec.is_caller_location_default) {
                spec.default_type_id = .source_loc_ty;
                if (!param_ty.isError() and param_ty != .source_loc_ty) {
                    if (!spec.default_ast_node.isNone()) {
                        _ = try self.checkTypeCompatibility(spec.default_ast_node, .source_loc_ty, param_ty);
                    }
                }
                if (!spec.default_ast_node.isNone()) {
                    _ = self.recordNodeType(spec.default_ast_node, .source_loc_ty);
                }
                continue;
            }
            if (spec.default_ast_node.isNone()) continue;
            self.active_default_param_max_ordinal = @intCast(idx);
            const def_tag = self.ast_arena.getNode(spec.default_ast_node).tag;
            if (def_tag != .contextual_variant and def_tag != .closure_expr) {
                const synth_def_ty = try self.synthExpr(spec.default_ast_node);
                spec.default_type_id = synth_def_ty;
                if (synth_def_ty.isError() or synth_def_ty == .never_ty) {
                    _ = self.recordNodeType(
                        spec.default_ast_node,
                        if (synth_def_ty == .never_ty) param_ty else .err_ty,
                    );
                } else if (try self.checkTypeCompatibility(spec.default_ast_node, synth_def_ty, param_ty)) {
                    _ = self.recordNodeType(spec.default_ast_node, param_ty);
                } else {
                    _ = self.recordNodeType(spec.default_ast_node, .err_ty);
                }
            } else {
                spec.default_type_id = try self.checkExpr(spec.default_ast_node, param_ty);
            }
        }
        for (self.sym_table.getScopeMembers(fn_sym.target_scope)) |mem_idx| {
            const mem_sym = self.sym_table.getSymbol(mem_idx).*;
            if (mem_sym.kind == .param_sym and mem_sym.flags.is_used and mem_sym.member_ordinal < specs_mut.len) {
                specs_mut[mem_sym.member_ordinal].is_used_by_default = true;
            }
        }
    }

    /// Refreshes `default_ast_node` indices and side tables on `fn_sym_idx` after a body-only edit (`SE-07`).
    pub fn refreshFnDefaultParamAstAndSideTables(self: *TypeChecker, fn_sym_idx: SymbolIndex) !void {
        const fn_sym = self.sym_table.getSymbol(fn_sym_idx).*;
        if (fn_sym.decl_span.file_id != self.file_id or fn_sym.cst_node.isNone()) return;
        if (fn_sym.cst_node.asInt() >= self.cst_arena.countNodes()) return;
        const specs_mut = self.sym_table.getFnParamSpecsMut(fn_sym_idx);
        if (specs_mut.len == 0) return;

        const start_idx: usize = fn_sym.cst_node.asInt();
        const root_rec = self.cst_arena.getNode(fn_sym.cst_node);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, root_rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );

        var ordinal: usize = 0;
        var cursor: usize = start_idx + 1;
        while (cursor < end_idx and ordinal < specs_mut.len) {
            const node = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cursor)));
            if (node.kind == .block or node.kind == .fn_expr_body) break;
            if (node.kind == .fn_param) {
                const param_end = @min(cursor + @max(@as(usize, node.subtree_size), 1), end_idx);
                if (specs_mut[ordinal].has_default and specs_mut[ordinal].decl_file_id == self.file_id) {
                    var colon_pos: ?usize = null;
                    var scan_cur = cursor + 1;
                    while (scan_cur < param_end) : (scan_cur += 1) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(scan_cur)));
                        if (sub.kind == .attribute) {
                            if (sub.subtree_size > 1) scan_cur += @as(usize, sub.subtree_size) - 1;
                            continue;
                        }
                        const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                        if (!is_leaf or sub.flags.is_missing_or_injected or sub.token.isNone()) continue;
                        if (sub.token.asInt() >= self.token_buffer.countTokens()) continue;
                        if (self.token_buffer.getToken(sub.token).kind == .colon) {
                            colon_pos = scan_cur;
                            break;
                        }
                    }
                    var eq_pos: ?usize = null;
                    var eq_scan = if (colon_pos) |c_pos| c_pos + 1 else cursor + 1;
                    while (eq_scan < param_end) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(eq_scan)));
                        const step: usize = @max(@as(usize, sub.subtree_size), 1);
                        if (step == 1 and !sub.flags.is_bracketed and !sub.flags.is_missing_or_injected and
                            !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens() and
                            self.token_buffer.getToken(sub.token).kind == .eq)
                        {
                            eq_pos = eq_scan;
                            break;
                        }
                        eq_scan += step;
                    }
                    specs_mut[ordinal].default_ast_node = if (eq_pos) |ep|
                        self.findFirstAstInCstRange(ep + 1, param_end)
                    else
                        .none;
                }
                ordinal += 1;
                cursor = param_end;
                continue;
            }
            cursor += 1;
        }
        try self.checkFnDefaultParamExprs(fn_sym_idx);
    }

    /// Returns `true` if `ty` belongs to Ownership Tier 1 (`Copy`, `DR-06` §1.2).
    pub fn isCopyType(self: *const TypeChecker, ty: TypeId) bool {
        return classifyOwnershipTier(self.pool, self.sym_table, ty) == .copy_tier;
    }

    /// Runs a bounded fixpoint propagating `is_secret` and ownership flags (`is_copy`, `has_drop`).
    fn propagateNominalFlagsFixpoint(self: *TypeChecker) !void {
        // [1] Bounded transitive fixpoint propagating `TypeFlags.is_secret` upward across composites:
        var pass_idx: u32 = 0;
        while (pass_idx < MAX_TYPE_DEPTH) : (pass_idx += 1) {
            var has_changed = false;
            var raw_ty: u32 = TypeId.first_dynamic.toU32();
            while (raw_ty < self.pool.nodes.len) : (raw_ty += 1) {
                const cur_ty = TypeId.fromInt(raw_ty);
                if (self.pool.getFlags(cur_ty).is_secret) continue;
                const node = self.pool.getNode(cur_ty);
                const is_marked_secret: bool = switch (node.tag) {
                    .ref_ty,
                    .mut_ref_ty,
                    .raw_ptr_ty,
                    .slice_ty,
                    .soa_slice_ty,
                    .array_ty,
                    .soa_array_ty,
                    .optional_ty,
                    .tilde_approx,
                    => self.pool.getFlags(TypeId.fromInt(node.lhs)).is_secret,
                    .result_ty => self.pool.getFlags(TypeId.fromInt(node.lhs)).is_secret or
                        self.pool.getFlags(TypeId.fromInt(node.rhs)).is_secret,
                    .tuple_ty => blk: {
                        for (self.pool.getTupleElements(cur_ty)) |raw_elem| {
                            if (self.pool.getFlags(TypeId.fromInt(raw_elem)).is_secret) break :blk true;
                        }
                        break :blk false;
                    },
                    .distinct_ty => self.pool.getFlags(TypeId.fromInt(node.lhs)).is_secret or
                        (!SymbolIndex.fromInt(node.rhs).isNone() and
                            self.sym_table.getSymbol(SymbolIndex.fromInt(node.rhs)).contract_flags.is_secret),
                    .refined_ty => self.pool.getFlags(TypeId.fromInt(node.rhs)).is_secret,
                    .struct_ty, .union_ty, .bit_field_ty, .enum_ty => blk: {
                        const sym_idx = SymbolIndex.fromInt(node.rhs);
                        if (sym_idx.isNone()) break :blk false;
                        const nom_sym = self.sym_table.getSymbol(sym_idx).*;
                        if (nom_sym.contract_flags.is_secret) break :blk true;
                        for (self.pool.getGenericTypeArgs(cur_ty)) |raw_arg| {
                            if (self.pool.getFlags(TypeId.fromInt(raw_arg)).is_secret) break :blk true;
                        }
                        if (nom_sym.target_scope.isNone()) break :blk false;
                        for (self.sym_table.getScopeMembers(nom_sym.target_scope)) |member_idx| {
                            const member_sym = self.sym_table.getSymbol(member_idx).*;
                            if ((member_sym.kind == .field_sym or member_sym.kind == .enum_variant_sym) and
                                !member_sym.type_id.isError() and
                                self.pool.getFlags(member_sym.type_id).is_secret)
                            {
                                break :blk true;
                            }
                        }
                        break :blk false;
                    },
                    else => false,
                };
                if (is_marked_secret) {
                    self.pool.nodes.items(.flags)[raw_ty].is_secret = true;
                    has_changed = true;
                }
            }
            if (!has_changed) break;
        }

        // [2] Evict premature `@derive(Debug)` registrations on transitively `@secret` nominals and sync `is_copy` / `has_drop`:
        const debug_trait_idx = try self.lookupAndEnsureTraitByName("Debug");
        const display_trait_idx = try self.lookupAndEnsureTraitByName("Display");
        var raw_ty: u32 = TypeId.first_dynamic.toU32();
        while (raw_ty < self.pool.nodes.len) : (raw_ty += 1) {
            const cur_ty = TypeId.fromInt(raw_ty);
            const node = self.pool.getNode(cur_ty);
            if (node.flags.is_secret) {
                if (!debug_trait_idx.isNone()) {
                    _ = self.sym_table.trait_impl_pairs.remove(packTraitImplPair(cur_ty, debug_trait_idx));
                }
                if (!display_trait_idx.isNone()) {
                    _ = self.sym_table.trait_impl_pairs.remove(packTraitImplPair(cur_ty, display_trait_idx));
                }
            }
            switch (node.tag) {
                .struct_ty,
                .enum_ty,
                .union_ty,
                .bit_field_ty,
                .distinct_ty,
                .refined_ty,
                .tuple_ty,
                .array_ty,
                .soa_array_ty,
                .optional_ty,
                .result_ty,
                .closure_ty,
                .mut_ref_ty,
                .ref_ty,
                .raw_ptr_ty,
                .slice_ty,
                .soa_slice_ty,
                .fn_ty,
                => {
                    const tier = classifyOwnershipTier(self.pool, self.sym_table, cur_ty);
                    self.pool.nodes.items(.flags)[raw_ty].is_copy = (tier == .copy_tier);
                    if (tier == .auto_drop_tier) {
                        self.pool.nodes.items(.flags)[raw_ty].has_drop = true;
                    }
                },
                else => {},
            }
        }
    }

    /// Recursively resolves declarations in `scope_id` and its child module/type scopes.
    fn resolveScopeSignaturesRecursive(self: *TypeChecker, scope_id: ScopeId) anyerror!void {
        const saved_scope = self.current_scope;
        self.current_scope = scope_id;
        defer self.current_scope = saved_scope;

        const members_copy = try self.allocator.dupe(
            SymbolIndex,
            self.sym_table.getScopeMembers(scope_id),
        );
        defer self.allocator.free(members_copy);

        // [1] Pre-assign nominal `TypeId` handles for structs, enums, unions, bit_fields, and traits:
        for (members_copy) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin or sym.flags.is_imported) continue;
            const nominal_ty: ?TypeId = switch (sym.kind) {
                .struct_sym => try self.pool.internNominal(
                    .struct_ty,
                    sym.def_id.asInt(),
                    sym_idx,
                    false,
                    sym.flags.is_must_use,
                    sym.contract_flags.is_secret,
                ),
                .enum_sym => try self.pool.internNominal(
                    .enum_ty,
                    sym.def_id.asInt(),
                    sym_idx,
                    !sym.contract_flags.is_linear,
                    sym.flags.is_must_use,
                    sym.contract_flags.is_secret,
                ),
                .union_sym => try self.pool.internNominal(
                    .union_ty,
                    sym.def_id.asInt(),
                    sym_idx,
                    !sym.contract_flags.is_linear,
                    sym.flags.is_must_use,
                    sym.contract_flags.is_secret,
                ),
                .bit_field_sym => blk: {
                    var backing_ty: TypeId = .u32_ty;
                    if (!sym.ast_node.isNone()) {
                        const bf_ast = self.ast_arena.getNode(sym.ast_node);
                        if (bf_ast.lhs.tag == .node) {
                            backing_ty = try self.resolveTypeAst(NodeIndex.fromInt(bf_ast.lhs.payload));
                            if (self.pool.getTag(backing_ty) == .tuple_ty) {
                                const tup_elems = self.pool.getTupleElements(backing_ty);
                                if (tup_elems.len == 1) {
                                    backing_ty = TypeId.fromInt(tup_elems[0]);
                                }
                            }
                        }
                    }
                    break :blk try self.pool.internNominal(
                        .bit_field_ty,
                        backing_ty.toU32(),
                        sym_idx,
                        true,
                        sym.flags.is_must_use,
                        sym.contract_flags.is_secret,
                    );
                },
                .trait_sym => try self.pool.internNominal(
                    .trait_ty,
                    sym.def_id.asInt(),
                    sym_idx,
                    false,
                    false,
                    false,
                ),
                else => null,
            };
            if (nominal_ty) |tid| {
                self.sym_table.getSymbolMut(sym_idx).type_id = tid;
                try self.sym_table.type_to_symbol.put(self.allocator, tid.toU32(), sym_idx);
                if (!sym.target_scope.isNone()) {
                    try self.ensureSelfAliasInTargetScope(sym.target_scope, tid);
                }
            }
        }

        // [2] Resolve `type` aliases, `distinct` newtypes, `is` range refinements, and user Type Groups:
        for (members_copy) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin or sym.flags.is_imported) continue;
            switch (sym.kind) {
                .type_alias_sym, .distinct_type_sym, .refined_type_sym, .type_group_sym => {
                    const resolved_ty = try self.resolveTypeAliasSymbol(sym_idx);
                    self.sym_table.getSymbolMut(sym_idx).type_id = resolved_ty;
                    if (sym.kind != .type_alias_sym) {
                        try self.sym_table.type_to_symbol.put(self.allocator, resolved_ty.toU32(), sym_idx);
                    }
                },
                else => {},
            }
        }

        // [3] Resolve struct/union/bit_field fields, enum variants, `@derive` headers, constants, and functions:
        for (members_copy) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin or sym.flags.is_imported) continue;
            switch (sym.kind) {
                .module_sym => {
                    if (!sym.target_scope.isNone() and
                        self.sym_table.scope_arena.getScope(sym.target_scope).file_id == self.file_id)
                    {
                        try self.resolveScopeSignaturesRecursive(sym.target_scope);
                        if (!sym.ast_node.isNone()) {
                            const mod_items = self.extractModInnerItemsSlice(sym.ast_node);
                            if (mod_items.len > 0) {
                                try self.registerImplTraitPairsInItemSlice(sym.target_scope, mod_items);
                            }
                        }
                    }
                },
                .struct_sym, .union_sym, .bit_field_sym => {
                    try self.resolveStructOrBitFieldFields(sym_idx);
                    if (sym.derive_mask.hasAny()) {
                        try self.registerDerivedTraitHeaders(sym_idx);
                    }
                    if (!sym.target_scope.isNone()) {
                        try self.resolveScopeSignaturesRecursive(sym.target_scope);
                    }
                },
                .enum_sym => {
                    try self.resolveEnumVariantPayloads(sym_idx);
                    if (sym.derive_mask.hasAny()) {
                        try self.registerDerivedTraitHeaders(sym_idx);
                    }
                    if (!sym.target_scope.isNone()) {
                        try self.resolveScopeSignaturesRecursive(sym.target_scope);
                    }
                },
                .trait_sym => {
                    if (!sym.target_scope.isNone()) {
                        try self.resolveScopeSignaturesRecursive(sym.target_scope);
                    }
                },
                .const_sym => {
                    if (!sym.ast_node.isNone()) {
                        const c_node = self.ast_arena.getNode(sym.ast_node);
                        var const_ty: TypeId = .err_ty;
                        if (c_node.lhs.tag == .node) {
                            const_ty = try self.resolveTypeAst(NodeIndex.fromInt(c_node.lhs.payload));
                        } else if (c_node.rhs.tag == .node) {
                            const init_id = NodeIndex.fromInt(c_node.rhs.payload);
                            self.pure_comptime_depth += 1;
                            defer self.pure_comptime_depth -= 1;
                            const_ty = try self.synthExpr(init_id);
                            if (const_ty == .untyped_int_ty) const_ty = .i32_ty;
                            if (const_ty == .untyped_float_ty) const_ty = .f64_ty;
                            self.bindCImportModuleToSymbolIfPresent(sym_idx, init_id);
                        }
                        self.sym_table.getSymbolMut(sym_idx).type_id = const_ty;
                    }
                },
                .extern_static_sym => {
                    if (!sym.ast_node.isNone()) {
                        const static_node = self.ast_arena.getNode(sym.ast_node);
                        const static_ty: TypeId = if (static_node.lhs.tag == .node)
                            try self.resolveTypeAst(NodeIndex.fromInt(static_node.lhs.payload))
                        else
                            .err_ty;
                        if (sym.flags.is_extern and !static_ty.isError()) {
                            const ty_span = if (static_node.lhs.tag == .node)
                                self.getAstNodeSpan(NodeIndex.fromInt(static_node.lhs.payload))
                            else
                                sym.decl_span;
                            try self.checkCAbiBoundaryType(static_ty, ty_span);
                        }
                        self.sym_table.getSymbolMut(sym_idx).type_id = static_ty;
                    }
                },
                .fn_sym => {
                    try self.resolveFnSignatureSymbol(sym_idx);
                },
                else => {},
            }
        }
    }

    /// Binds `Self` to `nominal_ty` inside `target_scope` if not already defined.
    fn ensureSelfAliasInTargetScope(
        self: *TypeChecker,
        target_scope: ScopeId,
        nominal_ty: TypeId,
    ) !void {
        const self_sym_id = try self.interner.intern("Self");
        const existing = self.sym_table.lookupInScopeDirect(
            target_scope,
            self_sym_id,
            NamespaceMask.TYPE_ONLY,
        );
        if (!existing.isNone()) return;
        _ = try self.sym_table.defineSymbol(.{
            .name = self_sym_id,
            .name_text = self.interner.get(self_sym_id),
            .kind = .type_alias_sym,
            .namespace = .type_ns,
            .visibility = .private,
            .flags = .{ .is_used = true, .is_builtin = true },
            .scope_id = target_scope,
            .type_id = nominal_ty,
        }, null);
    }

    /// Promotes `Self` inside `nominal_sym_idx`'s `target_scope` to `Base[T1, …]` once header `type_param`s are registered.
    fn syncGenericSelfAliasInTargetScope(self: *TypeChecker, nominal_sym_idx: SymbolIndex) !void {
        const nom_sym = self.sym_table.getSymbol(nominal_sym_idx).*;
        if (nom_sym.target_scope.isNone() or nom_sym.type_id.isError()) return;
        var header_type_params: [16]TypeId = undefined;
        var header_param_count: usize = 0;
        for (self.sym_table.getScopeMembers(nom_sym.target_scope)) |mem_idx| {
            const mem_sym = self.sym_table.getSymbol(mem_idx).*;
            if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError() and
                header_param_count < header_type_params.len)
            {
                header_type_params[header_param_count] = mem_sym.type_id;
                header_param_count += 1;
            }
        }
        if (header_param_count == 0) return;
        const generic_self_ty = try self.internNominalWithResolvedArgs(
            nom_sym.type_id,
            header_type_params[0..header_param_count],
        );
        const self_sym_id = try self.interner.intern("Self");
        const existing = self.sym_table.lookupInScopeDirect(
            nom_sym.target_scope,
            self_sym_id,
            NamespaceMask.TYPE_ONLY,
        );
        if (!existing.isNone()) {
            self.sym_table.getSymbolMut(existing).type_id = generic_self_ty;
        }
    }

    /// Extracts inner item AST indices from an inline `mod foo { … }` declaration.
    fn extractModInnerItemsSlice(self: *const TypeChecker, mod_node_idx: NodeIndex) []const u32 {
        return self.getNodeExtraSlice(mod_node_idx, true);
    }

    /// Ensures a `.trait_sym` has a resolved `.trait_ty` in `self.pool` and `self.sym_table.type_to_symbol`.
    fn ensureTraitSymbolTypeId(self: *TypeChecker, trait_sym_idx: SymbolIndex) !TypeId {
        const sym = self.sym_table.getSymbol(trait_sym_idx).*;
        if (!sym.type_id.isError()) return sym.type_id;
        const trait_ty = try self.pool.internNominal(
            .trait_ty,
            sym.def_id.asInt(),
            trait_sym_idx,
            false,
            false,
            false,
        );
        self.sym_table.getSymbolMut(trait_sym_idx).type_id = trait_ty;
        try self.sym_table.type_to_symbol.put(self.allocator, trait_ty.toU32(), trait_sym_idx);
        return trait_ty;
    }

    /// Looks up a built-in or in-scope trait by `trait_name` and ensures its `.trait_ty` is interned.
    fn lookupAndEnsureTraitByName(self: *TypeChecker, trait_name: []const u8) !SymbolIndex {
        const sym_id = try self.interner.intern(trait_name);
        switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.TYPE_ONLY)) {
            .found => |sym_idx| {
                const sym = self.sym_table.getSymbol(sym_idx);
                if (sym.kind == .trait_sym) {
                    _ = try self.ensureTraitSymbolTypeId(sym_idx);
                    return sym_idx;
                }
            },
            else => {},
        }
        return .none;
    }

    /// Registers `(target_ty, trait_sym_idx)` pairs from `impl Trait for TargetType` declarations in `item_slice`.
    fn registerImplTraitPairsInItemSlice(
        self: *TypeChecker,
        enclosing_scope: ScopeId,
        item_slice: []const u32,
    ) !void {
        const saved_scope = self.current_scope;
        defer self.current_scope = saved_scope;

        for (item_slice) |raw_item_id| {
            const item_node_id = NodeIndex.fromInt(raw_item_id);
            if (item_node_id.isNone() or item_node_id.asInt() >= self.ast_arena.countNodes()) continue;
            const item_node = self.ast_arena.getNode(item_node_id);
            if (item_node.tag != .impl_decl) continue;

            const item_cst = self.ast_arena.getCstOrigin(item_node_id);
            if (item_cst.isNone() or item_cst.asInt() >= self.cst_arena.countNodes()) continue;
            if (!(try self.evaluateCstNodeCfgAttributes(item_cst))) continue;
            const start_idx: usize = item_cst.asInt();
            const root_rec = self.cst_arena.getNode(item_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, root_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );

            const impl_hdr_scope = try self.sym_table.scope_arena.allocScope(
                .impl_scope,
                enclosing_scope,
                .NONE,
                self.file_id,
                .{},
            );
            self.current_scope = impl_hdr_scope;

            var for_cst_pos: ?usize = null;
            var header_end_pos: usize = end_idx;
            var cursor: usize = start_idx + 1;
            while (cursor < end_idx) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cursor)));
                if (sub.kind == .type_param) {
                    const param_end = @min(cursor + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    try self.registerGenericTypeParamFromCst(impl_hdr_scope, cursor, param_end);
                    cursor = param_end;
                    continue;
                }
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (is_leaf and !sub.flags.is_missing_or_injected and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const tok_kind = self.token_buffer.getToken(sub.token).kind;
                    if (tok_kind == .lbrace or tok_kind == .kw_where or tok_kind == .semi) {
                        header_end_pos = cursor;
                        break;
                    }
                    if (tok_kind == .kw_for and for_cst_pos == null) {
                        for_cst_pos = cursor;
                    }
                }
                cursor += 1;
            }

            if (for_cst_pos) |for_pos| {
                if (item_node.lhs.tag == .node) {
                    const trait_ty = try self.resolveTypeAst(NodeIndex.fromInt(item_node.lhs.payload));
                    const target_ast = self.findFirstAstInCstRange(for_pos + 1, header_end_pos);
                    if (!trait_ty.isError() and !target_ast.isNone()) {
                        const target_ty = try self.resolveTypeAst(target_ast);
                        if (!target_ty.isError()) {
                            if (self.sym_table.type_to_symbol.get(trait_ty.toU32())) |trait_sym_idx| {
                                const trait_sym = self.sym_table.getSymbol(trait_sym_idx).*;
                                const is_fmt_trait = std.mem.eql(u8, trait_sym.name_text, "Debug") or
                                    std.mem.eql(u8, trait_sym.name_text, "Display");
                                if (is_fmt_trait and self.pool.getFlags(target_ty).is_secret) {
                                    var ty_buf: [96]u8 = undefined;
                                    const target_str = self.pool.formatType(target_ty, self.sym_table, &ty_buf);
                                    var msg_buf: [200]u8 = undefined;
                                    const msg = std.fmt.bufPrint(
                                        &msg_buf,
                                        "cannot implement `{s}` for `@secret` type `{s}`",
                                        .{ trait_sym.name_text, target_str },
                                    ) catch "cannot implement formatting trait for `@secret` type";
                                    try self.emitDiagnosticSimple(
                                        .e0402_unsatisfied_trait_bound,
                                        self.getAstNodeSpan(item_node_id),
                                        msg,
                                        "`@secret` types forbid `Debug` and `Display` formatting",
                                    );
                                } else {
                                    try self.sym_table.trait_impl_pairs.put(
                                        self.sym_table.allocator,
                                        packTraitImplPair(target_ty, trait_sym_idx),
                                        {},
                                    );
                                    if ((std.mem.eql(u8, trait_sym.name_text, "Drop") or
                                        std.mem.eql(u8, trait_sym.name_text, "AutoDrop")) and
                                        !target_ty.isSizedPrimitive() and target_ty != .opaque_ty and
                                        target_ty.toU32() < self.pool.nodes.len)
                                    {
                                        self.pool.nodes.items(.flags)[target_ty.toU32()].has_drop = true;
                                        self.pool.nodes.items(.flags)[target_ty.toU32()].is_copy = false;
                                    }
                                }
                                try self.verifyImplMethodContractNonEscalation(
                                    item_node_id,
                                    target_ty,
                                    trait_sym_idx,
                                    self.sym_table.type_to_symbol.get(target_ty.toU32()) == null,
                                );
                            }
                        }
                    }
                }
            } else {
                const target_ast = self.findFirstAstInCstRange(start_idx + 1, header_end_pos);
                var resolved_target_ty: TypeId = .err_ty;
                const is_non_nominal = if (!target_ast.isNone()) blk_non_nom: {
                    resolved_target_ty = try self.resolveTypeAst(target_ast);
                    break :blk_non_nom self.sym_table.type_to_symbol.get(resolved_target_ty.toU32()) == null;
                } else true;
                try self.verifyImplMethodContractNonEscalation(
                    item_node_id,
                    resolved_target_ty,
                    .none,
                    is_non_nominal,
                );
            }
        }
    }

    /// Verifies that `impl` methods preserve all trait contracts (`E0323`, `Fix-17`) and checks `@std_cap_boundary` (`E0327`).
    fn verifyImplMethodContractNonEscalation(
        self: *TypeChecker,
        impl_node_id: NodeIndex,
        target_ty: TypeId,
        trait_sym_idx: SymbolIndex,
        is_checking_cap_boundary: bool,
    ) !void {
        const member_items = self.getNodeExtraSlice(impl_node_id, true);
        if (member_items.len == 0) return;
        const trait_sym_opt = if (!trait_sym_idx.isNone()) self.sym_table.getSymbol(trait_sym_idx).* else null;
        const target_scope: ScopeId = if (!target_ty.isError()) blk_scope: {
            if (self.sym_table.type_to_symbol.get(target_ty.toU32())) |target_sym_idx| {
                break :blk_scope self.sym_table.getSymbol(target_sym_idx).target_scope;
            }
            break :blk_scope .none;
        } else .none;

        for (member_items) |raw_member_id| {
            const member_ast_id = NodeIndex.fromInt(raw_member_id);
            if (member_ast_id.isNone() or member_ast_id.asInt() >= self.ast_arena.countNodes()) continue;
            const member_ast = self.ast_arena.getNode(member_ast_id);
            if (member_ast.tag != .fn_decl) continue;
            const member_cst = self.ast_arena.getCstOrigin(member_ast_id);
            const mem_meta = try symbol_resolver.extractItemHeaderMetadataValidated(
                self.source,
                self.file_id,
                self.token_buffer,
                self.cst_arena,
                member_cst,
                member_ast.main_token,
                null,
            );
            const method_span = self.getAstNodeSpan(member_ast_id);
            if (is_checking_cap_boundary and mem_meta.contract_flags.is_std_cap_boundary and
                !(self.is_stdlib_file or self.is_internal_core))
            {
                try self.emitDiagnosticSimple(
                    .e0327_forbidden_sandbox_bypass_attribute,
                    method_span,
                    "`@std_cap_boundary` is restricted to privileged `cx` / `core` library modules",
                    "forbidden capability-boundary attribute in user code",
                );
            }

            const trait_sym = trait_sym_opt orelse continue;
            if (!target_scope.isNone()) {
                for (self.sym_table.getScopeMembers(target_scope)) |cand_sym_idx| {
                    const cand_sym = self.sym_table.getSymbol(cand_sym_idx);
                    if (cand_sym.kind == .fn_sym and cand_sym.ast_node == member_ast_id) {
                        try self.sym_table.impl_method_trait.put(
                            self.sym_table.allocator,
                            cand_sym_idx.asInt(),
                            trait_sym_idx,
                        );
                        break;
                    }
                }
            }
            if (trait_sym.target_scope.isNone()) continue;
            const method_name = self.extractFnDeclNameFromCst(member_cst, member_ast.main_token);
            if (method_name.len == 0) continue;
            const method_sym_id = try self.interner.intern(method_name);
            const trait_method_idx = self.sym_table.lookupInScopeDirect(
                trait_sym.target_scope,
                method_sym_id,
                NamespaceMask.VALUE_ONLY,
            );
            if (trait_method_idx.isNone()) continue;
            const trait_method = self.sym_table.getSymbol(trait_method_idx).*;
            if (trait_method.kind != .fn_sym) continue;

            const missing_contract: ?[]const u8 = if (trait_method.contract_flags.is_no_alloc and
                !mem_meta.contract_flags.is_no_alloc)
                "@no_alloc"
            else if (trait_method.contract_flags.is_no_panic and !mem_meta.contract_flags.is_no_panic)
                "@no_panic"
            else if (trait_method.contract_flags.is_no_block and !mem_meta.contract_flags.is_no_block)
                "@no_block"
            else
                null;

            if (missing_contract) |contract_attr| {
                var msg_buf: [220]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "`impl` method `{s}` omits required `{s}` contract declared by trait `{s}`",
                    .{ method_name, contract_attr, trait_sym.name_text },
                ) catch "`impl` method omits required effect contract declared by trait";
                try self.emitDiagnosticSimple(
                    .e0323_trait_impl_effect_escalation,
                    method_span,
                    msg,
                    "trait implementation cannot escalate effect or allocation contracts",
                );
            }
        }
    }

    /// Extracts the declared function identifier lexeme from a `.fn_decl` CST subtree.
    fn extractFnDeclNameFromCst(
        self: *const TypeChecker,
        fn_cst: CstNodeIndex,
        fallback_tok: TokenIndex,
    ) []const u8 {
        if (!fn_cst.isNone() and fn_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = fn_cst.asInt();
            const root_rec = self.cst_arena.getNode(fn_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, root_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var has_seen_kw_fn = false;
            var cur: usize = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.kind == .attribute) {
                    if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                    continue;
                }
                if (sub.kind == .block or sub.kind == .fn_expr_body or
                    sub.kind == .param_list or sub.kind == .type_params) break;
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (!is_leaf or sub.flags.is_missing_or_injected or sub.token.isNone()) continue;
                if (sub.token.asInt() >= self.token_buffer.countTokens()) continue;
                const tok_kind = self.token_buffer.getToken(sub.token).kind;
                if (tok_kind == .kw_fn) {
                    has_seen_kw_fn = true;
                } else if (has_seen_kw_fn and symbol_resolver.isIdentifierToken(tok_kind)) {
                    return symbol_resolver.extractTokenSlice(self.source, self.token_buffer, sub.token);
                }
            }
        }
        return symbol_resolver.extractTokenSlice(self.source, self.token_buffer, fallback_tok);
    }

    /// Registers Two-Phase `@derive(Eq, Hash, Debug, Clone)` trait headers and method signatures (`DR-05` §2.2).
    fn registerDerivedTraitHeaders(self: *TypeChecker, nominal_sym_idx: SymbolIndex) !void {
        const nom_sym = self.sym_table.getSymbol(nominal_sym_idx).*;
        if (nom_sym.type_id.isError() or nom_sym.target_scope.isNone()) return;

        const self_ref_ty = try self.pool.internRef(nom_sym.type_id, false);
        const DerivedSpec = struct {
            is_enabled: bool,
            trait_name: []const u8,
            method_name: []const u8,
            has_other_param: bool,
            ret_ty: TypeId,
        };
        const specs = [4]DerivedSpec{
            .{
                .is_enabled = nom_sym.derive_mask.has_eq,
                .trait_name = "Eq",
                .method_name = "eq",
                .has_other_param = true,
                .ret_ty = .bool_ty,
            },
            .{
                .is_enabled = nom_sym.derive_mask.has_hash,
                .trait_name = "Hash",
                .method_name = "hash",
                .has_other_param = false,
                .ret_ty = .u64_ty,
            },
            .{
                .is_enabled = nom_sym.derive_mask.has_debug,
                .trait_name = "Debug",
                .method_name = "debug",
                .has_other_param = false,
                .ret_ty = .str_ty,
            },
            .{
                .is_enabled = nom_sym.derive_mask.has_clone,
                .trait_name = "Clone",
                .method_name = "clone",
                .has_other_param = false,
                .ret_ty = nom_sym.type_id,
            },
        };

        for (specs) |spec| {
            if (!spec.is_enabled) continue;
            if (std.mem.eql(u8, spec.trait_name, "Debug") and
                (nom_sym.contract_flags.is_secret or self.pool.getFlags(nom_sym.type_id).is_secret))
            {
                continue;
            }
            const trait_sym_idx = try self.lookupAndEnsureTraitByName(spec.trait_name);
            if (!trait_sym_idx.isNone()) {
                try self.sym_table.trait_impl_pairs.put(
                    self.sym_table.allocator,
                    packTraitImplPair(nom_sym.type_id, trait_sym_idx),
                    {},
                );
            }

            const method_sym_id = try self.interner.intern(spec.method_name);
            const existing_method = self.sym_table.lookupInScopeDirect(
                nom_sym.target_scope,
                method_sym_id,
                NamespaceMask.VALUE_ONLY,
            );
            if (!existing_method.isNone()) continue;

            const two_params = [2]TypeId{ self_ref_ty, self_ref_ty };
            const two_modes = [2]ParamMode{ .let_mode, .let_mode };
            const param_len: usize = if (spec.has_other_param) 2 else 1;
            const method_fn_ty = try self.pool.internFn(
                .fn_ty,
                two_params[0..param_len],
                two_modes[0..param_len],
                spec.ret_ty,
                false,
            );
            _ = try self.sym_table.defineSymbol(.{
                .name = method_sym_id,
                .name_text = self.interner.get(method_sym_id),
                .kind = .fn_sym,
                .namespace = .value_ns,
                .visibility = if (nom_sym.flags.is_pub) .public else .private,
                .flags = .{
                    .is_pub = nom_sym.flags.is_pub,
                    .is_used = true,
                    .is_prototype_only = true,
                },
                .scope_id = nom_sym.target_scope,
                .owner_def_id = nom_sym.def_id,
                .decl_span = nom_sym.decl_span,
                .type_id = method_fn_ty,
            }, null);
        }
    }

    /// Recursively verifies `@attribute_schema` rules, `@derive` member bounds, and user `@Schema(…)` attributes.
    fn verifyScopeDerivesAndAttributesRecursive(self: *TypeChecker, scope_id: ScopeId) anyerror!void {
        const saved_scope = self.current_scope;
        self.current_scope = scope_id;
        defer self.current_scope = saved_scope;

        const members_copy = try self.allocator.dupe(
            SymbolIndex,
            self.sym_table.getScopeMembers(scope_id),
        );
        defer self.allocator.free(members_copy);

        for (members_copy) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin or sym.flags.is_imported) continue;

            if (sym.contract_flags.is_std_cap_boundary and !(self.is_stdlib_file or self.is_internal_core)) {
                try self.emitDiagnosticSimple(
                    .e0327_forbidden_sandbox_bypass_attribute,
                    sym.decl_span,
                    "`@std_cap_boundary` is restricted to privileged `cx` / `core` library modules",
                    "forbidden capability-boundary attribute in user code",
                );
            }
            if (sym.contract_flags.is_secret and
                sym.kind != .struct_sym and
                sym.kind != .distinct_type_sym and
                sym.kind != .type_alias_sym and
                sym.kind != .refined_type_sym and
                sym.kind != .type_group_sym)
            {
                try self.emitDiagnosticSimple(
                    .e0405_distinct_type_mixing,
                    sym.decl_span,
                    "`@secret` is only permitted on `struct` declarations and `distinct` type aliases",
                    "use `struct` or `type Name = distinct Base;` for `@secret` values",
                );
            }
            if (sym.flags.is_attribute_schema) {
                try self.validateAttributeSchemaDecl(sym_idx);
            }
            if (sym.derive_mask.hasAny()) {
                try self.verifyDerivedTraitMemberBounds(sym_idx);
            }
            try self.validateSymbolAttributes(sym_idx, sym.def_id);

            switch (sym.kind) {
                .module_sym => {
                    if (!sym.target_scope.isNone() and
                        self.sym_table.scope_arena.getScope(sym.target_scope).file_id == self.file_id)
                    {
                        try self.verifyScopeDerivesAndAttributesRecursive(sym.target_scope);
                    }
                },
                .struct_sym, .union_sym, .bit_field_sym, .enum_sym, .trait_sym => {
                    if (!sym.target_scope.isNone()) {
                        const child_members = try self.allocator.dupe(
                            SymbolIndex,
                            self.sym_table.getScopeMembers(sym.target_scope),
                        );
                        defer self.allocator.free(child_members);
                        for (child_members) |child_idx| {
                            const child_sym = self.sym_table.getSymbol(child_idx).*;
                            if (child_sym.flags.is_builtin or child_sym.flags.is_imported) continue;
                            if (child_sym.contract_flags.is_std_cap_boundary and
                                !(self.is_stdlib_file or self.is_internal_core))
                            {
                                try self.emitDiagnosticSimple(
                                    .e0327_forbidden_sandbox_bypass_attribute,
                                    child_sym.decl_span,
                                    "`@std_cap_boundary` is restricted to privileged `cx` / `core` library modules",
                                    "forbidden capability-boundary attribute in user code",
                                );
                            }
                            if (child_sym.kind == .field_sym or child_sym.kind == .enum_variant_sym) {
                                try self.validateSymbolAttributes(child_idx, sym.def_id);
                            } else if (child_sym.kind == .fn_sym) {
                                try self.validateSymbolAttributes(child_idx, child_sym.def_id);
                            }
                        }
                    }
                },
                else => {},
            }
        }
    }

    /// Validates an `@attribute_schema` declaration, rejecting raw pointers, `&mut`, and closures (`E0503`).
    fn validateAttributeSchemaDecl(self: *TypeChecker, sym_idx: SymbolIndex) !void {
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (sym.kind != .struct_sym) {
            try self.emitDiagnosticSimple(
                .e0503_forbidden_comptime_operation,
                sym.decl_span,
                "`@attribute_schema` is only permitted on `struct` declarations",
                "only value `struct` declarations can define attribute schemas",
            );
            return;
        }
        if (sym.target_scope.isNone()) return;
        for (self.sym_table.getScopeMembers(sym.target_scope)) |member_idx| {
            const member_sym = self.sym_table.getSymbol(member_idx).*;
            if (member_sym.kind != .field_sym) continue;
            if (!self.isAllowedAttributeSchemaFieldType(member_sym.type_id, 0)) {
                try self.emitDiagnosticSimple(
                    .e0503_forbidden_comptime_operation,
                    member_sym.decl_span,
                    "`@attribute_schema` field cannot contain raw pointers, `&mut` references, or function/closure types",
                    "disallowed field type in `@attribute_schema` struct",
                );
            }
        }
    }

    /// Returns `true` if `ty` is a pure compile-time metadata value type permitted in `@attribute_schema`.
    fn isAllowedAttributeSchemaFieldType(self: *const TypeChecker, ty: TypeId, depth: u32) bool {
        if (ty.isError() or depth >= MAX_TYPE_DEPTH) return true;
        if (ty == .opaque_ty or ty == .bencher_ty or ty == .fmt_args_ty or
            self.pool.isTaskGroupType(ty) or self.pool.isTaskHandleType(ty))
        {
            return false;
        }
        if (ty == .source_loc_ty or ty == .fmt_spec_ty) return true;
        if (ty.isSizedPrimitive()) return ty != .never_ty;
        const node = self.pool.getNode(ty);
        return switch (node.tag) {
            .raw_ptr_ty, .mut_ref_ty, .fn_ty, .closure_ty => false,
            .ref_ty, .slice_ty, .soa_slice_ty, .array_ty, .soa_array_ty, .optional_ty => self.isAllowedAttributeSchemaFieldType(
                TypeId.fromInt(node.lhs),
                depth + 1,
            ),
            .result_ty => self.isAllowedAttributeSchemaFieldType(TypeId.fromInt(node.lhs), depth + 1) and
                self.isAllowedAttributeSchemaFieldType(TypeId.fromInt(node.rhs), depth + 1),
            .tuple_ty => blk: {
                for (self.pool.getTupleElements(ty)) |raw_elem| {
                    if (!self.isAllowedAttributeSchemaFieldType(TypeId.fromInt(raw_elem), depth + 1)) {
                        break :blk false;
                    }
                }
                break :blk true;
            },
            .distinct_ty => self.isAllowedAttributeSchemaFieldType(TypeId.fromInt(node.lhs), depth + 1),
            .refined_ty => self.isAllowedAttributeSchemaFieldType(TypeId.fromInt(node.rhs), depth + 1),
            .struct_ty, .union_ty => blk: {
                const nom_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(node.rhs)).*;
                if (nom_sym.target_scope.isNone()) break :blk true;
                for (self.sym_table.getScopeMembers(nom_sym.target_scope)) |field_idx| {
                    const field_sym = self.sym_table.getSymbol(field_idx).*;
                    if (field_sym.kind != .field_sym) continue;
                    if (!self.isAllowedAttributeSchemaFieldType(field_sym.type_id, depth + 1)) {
                        break :blk false;
                    }
                }
                break :blk true;
            },
            .enum_ty => blk: {
                const enum_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(node.rhs)).*;
                if (enum_sym.target_scope.isNone()) break :blk true;
                for (self.sym_table.getScopeMembers(enum_sym.target_scope)) |var_idx| {
                    const var_sym = self.sym_table.getSymbol(var_idx).*;
                    if (var_sym.kind != .enum_variant_sym or var_sym.type_id == .unit_ty) continue;
                    if (!self.isAllowedAttributeSchemaFieldType(var_sym.type_id, depth + 1)) {
                        break :blk false;
                    }
                }
                break :blk true;
            },
            else => true,
        };
    }

    /// Verifies that all struct fields / enum variant payloads satisfy each requested `@derive` trait (`E0402`).
    fn verifyDerivedTraitMemberBounds(self: *TypeChecker, nominal_sym_idx: SymbolIndex) !void {
        const nom_sym = self.sym_table.getSymbol(nominal_sym_idx).*;
        if (nom_sym.target_scope.isNone()) return;

        // Validate unknown trait identifiers inside `@derive(…)`:
        if (!nom_sym.cst_node.isNone() and nom_sym.cst_node.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = nom_sym.cst_node.asInt();
            const root_rec = self.cst_arena.getNode(nom_sym.cst_node);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, root_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                const is_lbrace_leaf = sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens() and
                    self.token_buffer.getToken(sub.token).kind == .lbrace;
                if (is_lbrace_leaf or sub.kind == .struct_introducer or
                    sub.kind == .enum_introducer or sub.kind == .union_introducer) break;
                if (sub.kind == .attribute) {
                    const attr_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    try self.checkDeriveTraitNamesInAttrCst(cur, attr_end);
                    if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                }
            }
        }

        if (nom_sym.derive_mask.has_from and nom_sym.kind != .enum_sym) {
            try self.emitDiagnosticSimple(
                .e0427_invalid_error_composition,
                nom_sym.decl_span,
                "`@derive(From)` is only permitted on `enum` error types",
                "`@derive(From)` requires an `enum` declaration",
            );
        }
        if (nom_sym.derive_mask.has_copy) {
            for (self.sym_table.getScopeMembers(nom_sym.target_scope)) |member_idx| {
                const member_sym = self.sym_table.getSymbol(member_idx).*;
                if (member_sym.kind != .field_sym and member_sym.kind != .enum_variant_sym) continue;
                if (member_sym.kind == .enum_variant_sym and member_sym.type_id == .unit_ty) continue;
                if (!member_sym.type_id.isError() and !self.isCopyType(member_sym.type_id)) {
                    var ty_buf: [96]u8 = undefined;
                    const member_ty_str = self.pool.formatType(member_sym.type_id, self.sym_table, &ty_buf);
                    var msg_buf: [200]u8 = undefined;
                    const msg = std.fmt.bufPrint(
                        &msg_buf,
                        "cannot `@derive(Copy)`: member `{s}` of type `{s}` is not `Copy`",
                        .{ member_sym.name_text, member_ty_str },
                    ) catch "cannot `@derive(Copy)`: member type is not `Copy`";
                    try self.emitDiagnosticSimple(
                        .e0402_unsatisfied_trait_bound,
                        member_sym.decl_span,
                        msg,
                        "member type is not `Copy`",
                    );
                }
            }
        }

        const TraitCheck = struct { is_enabled: bool, name: []const u8 };
        const checks = [4]TraitCheck{
            .{ .is_enabled = nom_sym.derive_mask.has_eq, .name = "Eq" },
            .{ .is_enabled = nom_sym.derive_mask.has_hash, .name = "Hash" },
            .{ .is_enabled = nom_sym.derive_mask.has_debug, .name = "Debug" },
            .{ .is_enabled = nom_sym.derive_mask.has_clone, .name = "Clone" },
        };

        for (checks) |chk| {
            if (!chk.is_enabled) continue;
            if (std.mem.eql(u8, chk.name, "Debug") and
                (nom_sym.contract_flags.is_secret or self.pool.getFlags(nom_sym.type_id).is_secret))
            {
                var msg_buf: [200]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "cannot `@derive(Debug)` on `@secret` type `{s}`",
                    .{nom_sym.name_text},
                ) catch "cannot `@derive(Debug)` on `@secret` type";
                try self.emitDiagnosticSimple(
                    .e0402_unsatisfied_trait_bound,
                    nom_sym.decl_span,
                    msg,
                    "`@secret` types forbid `Debug` formatting to prevent credential leakage",
                );
                continue;
            }
            const trait_sym_idx = try self.lookupAndEnsureTraitByName(chk.name);
            if (trait_sym_idx.isNone()) continue;
            const trait_ty = self.sym_table.getSymbol(trait_sym_idx).type_id;

            for (self.sym_table.getScopeMembers(nom_sym.target_scope)) |member_idx| {
                const member_sym = self.sym_table.getSymbol(member_idx).*;
                if (member_sym.kind != .field_sym and member_sym.kind != .enum_variant_sym) continue;
                if (member_sym.kind == .enum_variant_sym and member_sym.type_id == .unit_ty) continue;
                if (!(try self.hasTraitImplementation(member_sym.type_id, trait_ty, 0))) {
                    var ty_buf: [96]u8 = undefined;
                    const member_ty_str = self.pool.formatType(member_sym.type_id, self.sym_table, &ty_buf);
                    var msg_buf: [200]u8 = undefined;
                    const msg = std.fmt.bufPrint(
                        &msg_buf,
                        "cannot `@derive({s})`: member `{s}` of type `{s}` does not implement `{s}`",
                        .{ chk.name, member_sym.name_text, member_ty_str, chk.name },
                    ) catch "cannot `@derive`: member type does not implement derived trait";
                    try self.emitDiagnosticSimple(
                        .e0402_unsatisfied_trait_bound,
                        member_sym.decl_span,
                        msg,
                        "member type does not satisfy derived trait bound",
                    );
                }
            }
        }
    }

    /// Checks that every identifier passed to `@derive(…)` resolves to a known trait (`E0403` / `E0402`).
    fn checkDeriveTraitNamesInAttrCst(self: *TypeChecker, attr_start: usize, attr_end: usize) !void {
        var has_seen_derive = false;
        var cur = attr_start + 1;
        while (cur < attr_end) : (cur += 1) {
            const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (leaf.subtree_size > 1 or leaf.token.isNone() or
                leaf.token.asInt() >= self.token_buffer.countTokens()) continue;
            const kind = self.token_buffer.getToken(leaf.token).kind;
            if (!symbol_resolver.isIdentifierToken(kind)) continue;
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, leaf.token);
            if (!has_seen_derive) {
                if (!std.mem.eql(u8, lex, "derive")) return;
                has_seen_derive = true;
                continue;
            }
            if (std.mem.eql(u8, lex, "From") or std.mem.eql(u8, lex, "Copy")) continue;
            const sym_id = try self.interner.intern(lex);
            const span = self.token_buffer.getTokenSpan(self.file_id, leaf.token);
            switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.TYPE_ONLY)) {
                .found => |found_idx| {
                    if (self.sym_table.getSymbol(found_idx).kind != .trait_sym) {
                        try self.emitDiagnosticSimple(
                            .e0402_unsatisfied_trait_bound,
                            span,
                            "`@derive(…)` argument must be a trait",
                            "expected trait identifier here",
                        );
                    }
                },
                else => {
                    if (self.diagnostic_sink) |sink| {
                        try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                            sink,
                            self.interner,
                            lex,
                            span,
                            self.sym_table.suggestClosestSymbol(
                                self.current_scope,
                                lex,
                                NamespaceMask.TYPE_ONLY,
                            ),
                        );
                    }
                },
            }
        }
    }

    /// Returns `true` if `target_ty` implements `trait_ty` (`impl Trait for T`, `@derive`, or built-in capability).
    pub fn hasTraitImplementation(
        self: *TypeChecker,
        target_ty: TypeId,
        trait_ty: TypeId,
        depth: u32,
    ) anyerror!bool {
        if (target_ty.isError() or trait_ty.isError() or depth >= MAX_TYPE_DEPTH) return true;
        if (target_ty == .never_ty) return true;
        if (target_ty == .opaque_ty) return false;
        const bound_ty = self.pool.unwrapUnderlyingType(trait_ty);
        if (bound_ty.isBuiltinGroup() or self.pool.getTag(bound_ty) == .user_group) {
            if (self.pool.getUserGroupView(bound_ty)) |ug_view| {
                if (ug_view.tilde_prim_mask == INTERSECT_GROUP_SENTINEL) {
                    if (ug_view.prim_mask != 0) {
                        const unwrapped_t = self.pool.unwrapRefinementBase(target_ty);
                        if (!unwrapped_t.isSizedPrimitive() or
                            !TypeGroupMask.containsPrimitive(ug_view.prim_mask, unwrapped_t))
                        {
                            return false;
                        }
                    }
                    for (ug_view.exact_members) |exact_raw| {
                        if (!(try self.hasTraitImplementation(target_ty, TypeId.fromInt(exact_raw), depth + 1))) {
                            return false;
                        }
                    }
                    return true;
                }
            }
            const sat = checkGroupSatisfaction(self.pool, self.sym_table, self.target_layout, target_ty, bound_ty);
            if (sat != .rejected and sat != .rejected_distinct_without_tilde) return true;
            if (self.pool.getUserGroupView(bound_ty)) |ug_view| {
                for (ug_view.exact_members) |exact_raw| {
                    const exact_ty = TypeId.fromInt(exact_raw);
                    if (self.pool.getTag(exact_ty) == .trait_ty) {
                        if (try self.hasTraitImplementation(target_ty, exact_ty, depth + 1)) return true;
                    }
                }
            }
            return false;
        }

        const trait_sym_idx = self.sym_table.type_to_symbol.get(bound_ty.toU32()) orelse return false;
        const trait_sym = self.sym_table.getSymbol(trait_sym_idx).*;
        const t_name = trait_sym.name_text;
        if (self.pool.getFlags(target_ty).is_secret and
            (std.mem.eql(u8, t_name, "Debug") or std.mem.eql(u8, t_name, "Display")))
        {
            return false;
        }
        if (self.sym_table.trait_impl_pairs.contains(packTraitImplPair(target_ty, trait_sym_idx))) {
            return true;
        }

        const target_node = self.pool.getNode(target_ty);
        if (target_node.tag == .refined_ty) {
            return self.hasTraitImplementation(TypeId.fromInt(target_node.rhs), trait_ty, depth + 1);
        }

        if (!trait_sym.flags.is_builtin) return false;
        if (std.mem.eql(u8, t_name, "Copy")) {
            return classifyOwnershipTier(self.pool, self.sym_table, target_ty) == .copy_tier;
        }
        if (std.mem.eql(u8, t_name, "AutoDrop")) {
            return classifyOwnershipTier(self.pool, self.sym_table, target_ty) == .auto_drop_tier;
        }

        if (std.mem.eql(u8, t_name, "Send") or std.mem.eql(u8, t_name, "Sync")) {
            const is_sync = std.mem.eql(u8, t_name, "Sync");
            return target_ty != .fmt_args_ty and target_ty != .bencher_ty and
                self.explainNonSendOrSyncType(target_ty, is_sync, depth) == null;
        }
        if (std.mem.eql(u8, t_name, "Default")) {
            return switch (target_node.tag) {
                .primitive => target_ty.isSizedPrimitive() and target_ty != .never_ty,
                .optional_ty => true,
                .array_ty => (target_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0 and
                    try self.hasTraitImplementation(TypeId.fromInt(target_node.lhs), trait_ty, depth + 1),
                .tuple_ty => blk: {
                    for (self.pool.getTupleElements(target_ty)) |raw_elem| {
                        if (!(try self.hasTraitImplementation(TypeId.fromInt(raw_elem), trait_ty, depth + 1))) {
                            break :blk false;
                        }
                    }
                    break :blk true;
                },
                else => false,
            };
        }

        const is_eq = std.mem.eql(u8, t_name, "Eq");
        const is_hash = std.mem.eql(u8, t_name, "Hash");
        const is_debug = std.mem.eql(u8, t_name, "Debug") or std.mem.eql(u8, t_name, "Display");
        const is_clone = std.mem.eql(u8, t_name, "Clone");
        const is_ord = std.mem.eql(u8, t_name, "Ord");
        if (!is_eq and !is_hash and !is_debug and !is_clone and !is_ord) return false;

        if (target_ty == .source_loc_ty or target_ty == .fmt_spec_ty) return !is_ord;
        if (target_ty == .fmt_args_ty) return is_debug or is_clone;
        if (target_ty == .bencher_ty or self.pool.isTaskGroupType(target_ty) or self.pool.isTaskHandleType(target_ty)) {
            return false;
        }

        return switch (target_node.tag) {
            .primitive => if (!target_ty.isSizedPrimitive()) false else if (target_ty.isFloatPrimitive()) !is_hash else true,
            .raw_ptr_ty => !is_ord,
            .fn_ty => is_clone,
            .ref_ty => if (is_clone)
                true
            else
                self.hasTraitImplementation(TypeId.fromInt(target_node.lhs), trait_ty, depth + 1),
            .mut_ref_ty => if (is_clone)
                false
            else
                self.hasTraitImplementation(TypeId.fromInt(target_node.lhs), trait_ty, depth + 1),
            .slice_ty, .soa_slice_ty => if (is_clone)
                true
            else
                self.hasTraitImplementation(TypeId.fromInt(target_node.lhs), trait_ty, depth + 1),
            .array_ty, .soa_array_ty, .optional_ty => self.hasTraitImplementation(
                TypeId.fromInt(target_node.lhs),
                trait_ty,
                depth + 1,
            ),
            .result_ty => (try self.hasTraitImplementation(
                TypeId.fromInt(target_node.lhs),
                trait_ty,
                depth + 1,
            )) and (try self.hasTraitImplementation(
                TypeId.fromInt(target_node.rhs),
                trait_ty,
                depth + 1,
            )),
            .tuple_ty => blk: {
                for (self.pool.getTupleElements(target_ty)) |raw_elem| {
                    if (!(try self.hasTraitImplementation(TypeId.fromInt(raw_elem), trait_ty, depth + 1))) {
                        break :blk false;
                    }
                }
                break :blk true;
            },
            else => false,
        };
    }

    /// Validates user `@Schema(…)` attributes attached to `target_sym_idx`, populating `self.attr_instances`.
    fn validateSymbolAttributes(
        self: *TypeChecker,
        target_sym_idx: SymbolIndex,
        owner_def_id: DefId,
    ) !void {
        const target_sym = self.sym_table.getSymbol(target_sym_idx).*;
        if (target_sym.cst_node.isNone() or target_sym.cst_node.asInt() >= self.cst_arena.countNodes()) return;

        const start_idx: usize = target_sym.cst_node.asInt();
        const root_rec = self.cst_arena.getNode(target_sym.cst_node);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, root_rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );

        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .struct_introducer or sub.kind == .enum_introducer or
                sub.kind == .union_introducer or sub.kind == .fn_introducer or
                sub.kind == .type_alias_introducer or sub.kind == .const_introducer or
                sub.kind == .block or sub.kind == .fn_expr_body) break;
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const leaf_kind = self.token_buffer.getToken(sub.token).kind;
                if (leaf_kind == .colon or leaf_kind == .lbrace or leaf_kind == .lparen) break;
            }
            if (sub.kind == .attribute) {
                const attr_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                try self.validateSingleAttributeCst(target_sym_idx, owner_def_id, cur, attr_end);
                if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
            }
        }
    }

    /// Validates a single CST `.attribute` subtree `[attr_start .. attr_end)` against an `@attribute_schema` struct.
    fn validateSingleAttributeCst(
        self: *TypeChecker,
        target_sym_idx: SymbolIndex,
        owner_def_id: DefId,
        attr_start: usize,
        attr_end: usize,
    ) !void {
        var name_tok: TokenIndex = .none;
        var name_leaf_pos: usize = attr_start + 1;
        while (name_leaf_pos < attr_end) : (name_leaf_pos += 1) {
            const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(name_leaf_pos)));
            if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                leaf.token.asInt() < self.token_buffer.countTokens())
            {
                const kind = self.token_buffer.getToken(leaf.token).kind;
                if (symbol_resolver.isIdentifierToken(kind)) {
                    name_tok = leaf.token;
                    break;
                }
            }
        }
        if (name_tok.isNone()) return;

        const attr_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok);
        if (attr_name.len == 0 or BUILTIN_ATTRIBUTE_MAP.has(attr_name)) return;

        const attr_span = self.token_buffer.getTokenSpan(self.file_id, name_tok);
        const schema_sym_idx = try self.lookupAttributeSchemaSymbol(attr_name);
        if (schema_sym_idx.isNone()) {
            if (self.diagnostic_sink) |sink| {
                try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                    sink,
                    self.interner,
                    attr_name,
                    attr_span,
                    self.sym_table.suggestClosestSymbol(
                        self.current_scope,
                        attr_name,
                        NamespaceMask.TYPE_ONLY,
                    ),
                );
            }
            return;
        }

        const schema_sym = self.sym_table.getSymbol(schema_sym_idx).*;
        if (schema_sym.kind != .struct_sym or !schema_sym.flags.is_attribute_schema) {
            try self.emitDiagnosticSimple(
                .e0503_forbidden_comptime_operation,
                attr_span,
                "type used as `@attribute` is not annotated with `@attribute_schema`",
                "add `@attribute_schema` to this struct declaration to use it as an attribute",
            );
            return;
        }

        const target_sym = self.sym_table.getSymbol(target_sym_idx).*;
        const is_target_allowed = switch (target_sym.kind) {
            .struct_sym => schema_sym.attr_target_mask.has_struct_target,
            .enum_sym => schema_sym.attr_target_mask.has_enum_target,
            .union_sym => schema_sym.attr_target_mask.has_union_target,
            .field_sym => schema_sym.attr_target_mask.has_field_target,
            .enum_variant_sym => schema_sym.attr_target_mask.has_variant_target,
            .fn_sym => schema_sym.attr_target_mask.has_fn_target,
            .param_sym => schema_sym.attr_target_mask.has_param_target,
            .local_let_sym, .local_var_sym => schema_sym.attr_target_mask.has_local_target,
            else => true,
        };
        if (!is_target_allowed) {
            var msg_buf: [192]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &msg_buf,
                "attribute `@{s}` is not permitted on this declaration target",
                .{attr_name},
            ) catch "attribute is not permitted on this declaration target";
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                attr_span,
                msg,
                "disallowed target for `@attribute_schema(targets = …)`",
            );
            return;
        }

        if (schema_sym.target_scope.isNone()) return;
        var schema_fields: std.ArrayListUnmanaged(SymbolIndex) = .empty;
        defer schema_fields.deinit(self.allocator);
        for (self.sym_table.getScopeMembers(schema_sym.target_scope)) |mem_idx| {
            if (self.sym_table.getSymbol(mem_idx).kind == .field_sym) {
                try schema_fields.append(self.allocator, mem_idx);
            }
        }
        const schema_field_count = schema_fields.items.len;

        const supplied_values = try self.allocator.alloc(?AttrArgValue, schema_field_count);
        defer if (supplied_values.len > 0) self.allocator.free(supplied_values);
        @memset(supplied_values, null);
        var arg_cursor = name_leaf_pos + 1;
        var positional_idx: usize = 0;
        self.pure_comptime_depth += 1;
        defer self.pure_comptime_depth -= 1;

        // Advance past opening `(` if present:
        var has_open_paren = false;
        while (arg_cursor < attr_end) : (arg_cursor += 1) {
            const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(arg_cursor)));
            if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                leaf.token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(leaf.token).kind == .lparen)
            {
                has_open_paren = true;
                arg_cursor += 1;
                break;
            }
        }

        if (has_open_paren) {
            while (arg_cursor < attr_end) {
                // Find next top-level `,` or `)` boundary in `[arg_cursor .. attr_end)`:
                var seg_end = arg_cursor;
                var paren_depth: u32 = 0;
                while (seg_end < attr_end) : (seg_end += 1) {
                    const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(seg_end)));
                    if (sub.subtree_size <= 1 and !sub.token.isNone() and
                        sub.token.asInt() < self.token_buffer.countTokens())
                    {
                        const tok_kind = self.token_buffer.getToken(sub.token).kind;
                        if (tok_kind == .lparen or tok_kind == .lbracket or tok_kind == .lbrace) {
                            paren_depth += 1;
                        } else if (tok_kind == .rparen or tok_kind == .rbracket or tok_kind == .rbrace) {
                            if (paren_depth == 0) break;
                            paren_depth -= 1;
                        } else if (tok_kind == .comma and paren_depth == 0) {
                            break;
                        }
                    }
                }
                if (seg_end > arg_cursor) {
                    try self.checkAttributeArgumentSegment(
                        schema_sym.target_scope,
                        schema_fields.items,
                        supplied_values,
                        &positional_idx,
                        arg_cursor,
                        seg_end,
                    );
                }
                if (seg_end >= attr_end) break;
                const delim_sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(seg_end)));
                if (delim_sub.subtree_size <= 1 and !delim_sub.token.isNone() and
                    delim_sub.token.asInt() < self.token_buffer.countTokens() and
                    self.token_buffer.getToken(delim_sub.token).kind == .rparen) break;
                arg_cursor = seg_end + 1;
            }
        }

        var resolved_fields = try self.allocator.alloc(AttrFieldInit, schema_field_count);
        errdefer if (resolved_fields.len > 0) self.allocator.free(resolved_fields);

        for (schema_fields.items, 0..) |field_sym_idx, i| {
            const field_sym = self.sym_table.getSymbol(field_sym_idx).*;
            const val_opt = supplied_values[i] orelse try self.extractFieldDefaultAttrValue(field_sym);
            if (val_opt) |attr_val| {
                resolved_fields[i] = .{
                    .field_name = field_sym.name,
                    .field_ordinal = @intCast(i),
                    .value = attr_val,
                };
            } else {
                var msg_buf: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "missing required field `{s}` in `@{s}` attribute",
                    .{ field_sym.name_text, attr_name },
                ) catch "missing required field in attribute";
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    attr_span,
                    msg,
                    "required `@attribute_schema` field was not supplied",
                );
                resolved_fields[i] = .{
                    .field_name = field_sym.name,
                    .field_ordinal = @intCast(i),
                    .value = .none_opt,
                };
            }
        }

        try self.attr_instances.append(self.allocator, .{
            .schema_type_id = schema_sym.type_id,
            .target_symbol = target_sym_idx,
            .owner_def_id = owner_def_id,
            .attr_span = attr_span,
            .fields = resolved_fields,
        });
    }

    /// Resolves `attr_name` (`@ArgAttr`, `@arg`, `@cli_command`) to its schema `SymbolIndex` in `type_ns`.
    fn lookupAttributeSchemaSymbol(self: *TypeChecker, attr_name: []const u8) !SymbolIndex {
        const direct_id = try self.interner.intern(attr_name);
        if (self.sym_table.lookupLexical(self.current_scope, direct_id, NamespaceMask.TYPE_ONLY) == .found) {
            return self.sym_table.lookupLexical(self.current_scope, direct_id, NamespaceMask.TYPE_ONLY).found;
        }
        if (attr_name.len > 0 and attr_name[0] >= 'a' and attr_name[0] <= 'z') {
            var pascal_buf: [120]u8 = undefined;
            const pascal_name = toPascalCase(attr_name, &pascal_buf);
            var suffixed_buf: [128]u8 = undefined;
            if (std.fmt.bufPrint(&suffixed_buf, "{s}Attr", .{pascal_name})) |with_attr| {
                const suffixed_id = try self.interner.intern(with_attr);
                switch (self.sym_table.lookupLexical(
                    self.current_scope,
                    suffixed_id,
                    NamespaceMask.TYPE_ONLY,
                )) {
                    .found => |found_idx| return found_idx,
                    else => {},
                }
            } else |_| {}

            const pascal_id = try self.interner.intern(pascal_name);
            switch (self.sym_table.lookupLexical(self.current_scope, pascal_id, NamespaceMask.TYPE_ONLY)) {
                .found => |found_idx| return found_idx,
                else => {},
            }
        }
        return .none;
    }

    /// Validates one `name = expr` or positional `expr` segment inside an `@Schema(…)` call.
    fn checkAttributeArgumentSegment(
        self: *TypeChecker,
        schema_scope: ScopeId,
        schema_fields: []const SymbolIndex,
        supplied_values: []?AttrArgValue,
        positional_idx: *usize,
        seg_start: usize,
        seg_end: usize,
    ) !void {
        var named_tok: TokenIndex = .none;
        var expr_search_start = seg_start;

        var cur = seg_start;
        while (cur < seg_end) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size > 1) break;
            if (sub.token.isNone() or sub.token.asInt() >= self.token_buffer.countTokens()) continue;
            const kind = self.token_buffer.getToken(sub.token).kind;
            if (named_tok.isNone() and symbol_resolver.isIdentifierToken(kind)) {
                named_tok = sub.token;
            } else if (!named_tok.isNone() and (kind == .eq or kind == .colon)) {
                expr_search_start = cur + 1;
                break;
            } else {
                named_tok = .none;
                break;
            }
        }
        if (expr_search_start == seg_start) named_tok = .none;

        const expr_ast_id = self.findFirstAstInCstRange(expr_search_start, seg_end);
        if (expr_ast_id.isNone()) return;

        var target_field_slot: ?usize = null;
        if (!named_tok.isNone()) {
            const field_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, named_tok);
            const field_sym_id = try self.interner.intern(field_lex);
            const found_field = self.sym_table.lookupInScopeDirect(
                schema_scope,
                field_sym_id,
                NamespaceMask.VALUE_ONLY,
            );
            if (found_field.isNone()) {
                if (self.diagnostic_sink) |sink| {
                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                        sink,
                        self.interner,
                        field_lex,
                        self.token_buffer.getTokenSpan(self.file_id, named_tok),
                        self.sym_table.suggestClosestInScope(
                            schema_scope,
                            field_lex,
                            NamespaceMask.VALUE_ONLY,
                        ),
                    );
                }
                _ = try self.synthExpr(expr_ast_id);
                return;
            }
            for (schema_fields, 0..) |cand_field_idx, i| {
                if (cand_field_idx == found_field) {
                    target_field_slot = i;
                    break;
                }
            }
        } else {
            if (positional_idx.* < schema_fields.len) {
                target_field_slot = positional_idx.*;
            }
            positional_idx.* += 1;
        }

        if (target_field_slot) |slot_i| {
            const expected_ty = self.sym_table.getSymbol(schema_fields[slot_i]).type_id;
            _ = try self.checkExpr(expr_ast_id, expected_ty);
            supplied_values[slot_i] = try self.evalAttrArgValue(expr_ast_id, expected_ty);
        } else {
            _ = try self.synthExpr(expr_ast_id);
        }
    }

    /// Evaluates a `.struct_field`'s optional `= default_expr` into an `AttrArgValue`, or returns `null`.
    fn extractFieldDefaultAttrValue(self: *TypeChecker, field_sym: SymbolRecord) !?AttrArgValue {
        if (field_sym.cst_node.isNone() or field_sym.cst_node.asInt() >= self.cst_arena.countNodes()) return null;
        const start_idx: usize = field_sym.cst_node.asInt();
        const rec = self.cst_arena.getNode(field_sym.cst_node);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var eq_pos: ?usize = null;
        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(sub.token).kind == .eq)
            {
                eq_pos = cur;
                break;
            }
        }
        const found_eq = eq_pos orelse return null;
        const default_ast = self.findFirstAstInCstRange(found_eq + 1, end_idx);
        if (default_ast.isNone()) return null;
        return try self.evalAttrArgValue(default_ast, field_sym.type_id);
    }

    /// Evaluates a typechecked attribute argument AST node into a scalar `AttrArgValue`.
    fn evalAttrArgValue(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !AttrArgValue {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return .none_opt;
        const expr_node = self.ast_arena.getNode(expr_id);
        switch (expr_node.tag) {
            .bool_lit => {
                const is_true = !expr_node.main_token.isNone() and
                    self.token_buffer.getToken(expr_node.main_token).kind == .kw_true;
                return .{ .bool_val = is_true };
            },
            .char_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, expr_node.main_token);
                return .{ .char_val = extractCharLiteralCodepoint(lex) orelse 0 };
            },
            .string_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, expr_node.main_token);
                if (lexer.cookStringLiteral(self.allocator, lex)) |cooked| {
                    defer self.allocator.free(cooked);
                    return .{ .str_val = try self.interner.intern(cooked) };
                } else |_| {}
                if (extractRawStringContent(lex)) |raw_body| {
                    return .{ .str_val = try self.interner.intern(raw_body) };
                }
                const inner = if (lex.len >= 2 and lex[0] == '"' and lex[lex.len - 1] == '"')
                    lex[1 .. lex.len - 1]
                else
                    lex;
                const decoded = try decodeStandardStringSegment(self.allocator, inner);
                defer self.allocator.free(decoded);
                return .{ .str_val = try self.interner.intern(decoded) };
            },
            .contextual_variant => {
                const var_tok = if (expr_node.lhs.tag == .token)
                    TokenIndex.fromInt(expr_node.lhs.payload)
                else
                    expr_node.main_token;
                const var_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, var_tok);
                const unwrapped_exp = self.pool.unwrapUnderlyingType(expected_ty);
                const exp_node = self.pool.getNode(unwrapped_exp);
                if (exp_node.tag == .optional_ty) {
                    if (std.mem.eql(u8, var_name, "None")) return .none_opt;
                    if (std.mem.eql(u8, var_name, "Some")) {
                        const arg_nodes = self.getNodeExtraSlice(expr_id, true);
                        if (arg_nodes.len == 1) {
                            return self.evalAttrArgValue(
                                NodeIndex.fromInt(arg_nodes[0]),
                                TypeId.fromInt(exp_node.lhs),
                            );
                        }
                    }
                }
                const target_enum_ty = if (exp_node.tag == .optional_ty)
                    self.pool.unwrapUnderlyingType(TypeId.fromInt(exp_node.lhs))
                else
                    unwrapped_exp;
                const target_enum_node = self.pool.getNode(target_enum_ty);
                if (target_enum_node.tag == .enum_ty) {
                    const enum_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(target_enum_node.rhs)).*;
                    if (!enum_sym.target_scope.isNone()) {
                        if (self.interner.lookup(var_name)) |var_sym_id| {
                            const found_v = self.sym_table.lookupInScopeDirect(
                                enum_sym.target_scope,
                                var_sym_id,
                                NamespaceMask.VALUE_ONLY,
                            );
                            if (!found_v.isNone()) {
                                return .{ .enum_tag = self.sym_table.getSymbol(found_v).member_ordinal };
                            }
                        }
                    }
                }
                return .{ .enum_tag = 0 };
            },
            .float_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, expr_node.main_token);
                return .{ .float_val = parseAttrFloatLiteralLexeme(lex) };
            },
            .int_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, expr_node.main_token);
                const unwrapped_exp = self.pool.unwrapUnderlyingType(expected_ty);
                if (unwrapped_exp == .f32_ty or unwrapped_exp == .f64_ty or
                    (if (lexer.extractNumericSuffix(lex)) |p_num|
                        p_num.suffix_type == .f32_ty or p_num.suffix_type == .f64_ty
                    else |_|
                        false))
                {
                    if (extractIntLiteralValue(lex)) |parsed_int| {
                        return .{ .float_val = @floatFromInt(parsed_int.value) };
                    }
                }
                if (try self.evalConstIntExpr(expr_id, false)) |int_val| {
                    return .{ .int_val = int_val };
                }
                return .none_opt;
            },
            .unary_expr => {
                if (!expr_node.main_token.isNone() and
                    self.token_buffer.getToken(expr_node.main_token).kind == .minus and
                    expr_node.lhs.tag == .node)
                {
                    const inner_val = try self.evalAttrArgValue(NodeIndex.fromInt(expr_node.lhs.payload), expected_ty);
                    if (inner_val == .float_val) {
                        return .{ .float_val = -inner_val.float_val };
                    }
                }
                if (try self.evalConstIntExpr(expr_id, false)) |int_val| {
                    return .{ .int_val = int_val };
                }
                return .none_opt;
            },
            else => {
                if (try self.evalConstIntExpr(expr_id, false)) |int_val| {
                    return .{ .int_val = int_val };
                }
                return .none_opt;
            },
        }
    }

    /// Parses a CoreX float literal `lexeme` (stripping `_` separators and `_f32`/`_f64` suffixes) into `f64`.
    fn parseAttrFloatLiteralLexeme(lexeme: []const u8) f64 {
        const digits_raw = if (lexer.extractNumericSuffix(lexeme)) |parsed|
            parsed.digits_slice
        else |_|
            lexeme;
        var clean_buf: [128]u8 = undefined;
        var clean_len: usize = 0;
        for (digits_raw) |byte_val| {
            if (byte_val == '_') continue;
            if (clean_len >= clean_buf.len) return 0.0;
            clean_buf[clean_len] = byte_val;
            clean_len += 1;
        }
        return std.fmt.parseFloat(f64, clean_buf[0..clean_len]) catch 0.0;
    }

    /// Validates trailing generic defaults (`E0426`) and populates default `TypeId` / `const` values (`SE-10A`).
    fn validateAndPopulateGenericParamSpecs(
        self: *TypeChecker,
        owner_sym_idx: SymbolIndex,
        target_scope: ScopeId,
    ) !void {
        if (owner_sym_idx.isNone()) return;
        const owner_sym = self.sym_table.getSymbol(owner_sym_idx).*;
        const specs_mut = self.sym_table.getGenericParamSpecsMut(owner_sym_idx);
        if (specs_mut.len == 0) return;

        const saved_scope = self.current_scope;
        if (!target_scope.isNone()) self.current_scope = target_scope;
        defer self.current_scope = saved_scope;

        var tp_ranges: [32]TypeParamCstRange = undefined;
        var tp_range_count: usize = 0;

        const is_local_file = owner_sym.decl_span.file_id == self.file_id and
            !owner_sym.cst_node.isNone() and
            owner_sym.cst_node.asInt() < self.cst_arena.countNodes();
        if (is_local_file) {
            const start_idx: usize = owner_sym.cst_node.asInt();
            const root_rec = self.cst_arena.getNode(owner_sym.cst_node);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, root_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cursor: usize = start_idx + 1;
            while (cursor < end_idx and tp_range_count < tp_ranges.len) {
                const node = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cursor)));
                if (node.kind == .param_list or node.kind == .where_clause or
                    node.kind == .block or node.kind == .fn_expr_body or node.kind == .subscript_arm)
                {
                    break;
                }
                if ((node.kind == .attribute or node.kind == .visibility_modifier) and node.subtree_size > 1) {
                    cursor += @max(@as(usize, node.subtree_size), 1);
                    continue;
                }
                if (node.kind == .type_param) {
                    const tp_end = @min(cursor + @max(@as(usize, node.subtree_size), 1), end_idx);
                    var tp_name_tok: TokenIndex = .none;
                    var tp_cur = cursor + 1;
                    while (tp_cur < tp_end) : (tp_cur += 1) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(tp_cur)));
                        if (sub.subtree_size <= 1 and !sub.flags.is_bracketed and
                            !sub.flags.is_missing_or_injected and !sub.token.isNone() and
                            sub.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tk = self.token_buffer.getToken(sub.token).kind;
                            if (symbol_resolver.isIdentifierToken(tk)) {
                                tp_name_tok = sub.token;
                                break;
                            }
                        }
                    }
                    if (!tp_name_tok.isNone()) {
                        tp_ranges[tp_range_count] = .{
                            .cst_start = cursor,
                            .cst_end = tp_end,
                            .span = self.token_buffer.getTokenSpan(self.file_id, tp_name_tok),
                        };
                        tp_range_count += 1;
                    }
                    cursor = tp_end;
                    continue;
                }
                cursor += 1;
            }
        }

        var has_seen_default = false;
        for (specs_mut, 0..) |*g_spec, spec_i| {
            const param_span = if (spec_i < tp_range_count)
                tp_ranges[spec_i].span
            else
                owner_sym.decl_span;
            if (g_spec.has_default) {
                has_seen_default = true;
            } else if (has_seen_default and is_local_file) {
                try self.emitDiagnosticSimple(
                    .e0426_non_trailing_generic_default,
                    param_span,
                    "generic parameter without a default cannot follow a defaulted generic parameter",
                    "non-trailing generic parameter default; move defaulted generic parameters to the end",
                );
            }
            if (!g_spec.has_default) continue;
            if (spec_i < tp_range_count) {
                const cst_start = tp_ranges[spec_i].cst_start;
                const cst_end = tp_ranges[spec_i].cst_end;
                var eq_pos: ?usize = null;
                var bracket_depth: u32 = 0;
                var paren_depth: u32 = 0;
                var cur = cst_start + 1;
                while (cur < cst_end) : (cur += 1) {
                    const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                    if (sub.subtree_size > 1 or sub.flags.is_bracketed or
                        sub.flags.is_missing_or_injected or sub.token.isNone() or
                        sub.token.asInt() >= self.token_buffer.countTokens())
                    {
                        continue;
                    }
                    const tk = self.token_buffer.getToken(sub.token).kind;
                    if (tk == .lbracket) {
                        bracket_depth += 1;
                    } else if (tk == .rbracket) {
                        bracket_depth -|= 1;
                    } else if (tk == .lparen) {
                        paren_depth += 1;
                    } else if (tk == .rparen) {
                        paren_depth -|= 1;
                    } else if (tk == .eq and bracket_depth == 0 and paren_depth == 0) {
                        eq_pos = cur;
                        break;
                    }
                }
                const def_search_start = if (eq_pos) |ep| ep + 1 else cst_start;
                const def_ast = self.findFirstAstInCstRange(def_search_start, cst_end);
                if (!def_ast.isNone()) {
                    g_spec.default_ast_node = def_ast;
                    if (g_spec.is_const) {
                        self.pure_comptime_depth += 1;
                        defer self.pure_comptime_depth -= 1;
                        var expected_const_ty: TypeId = .err_ty;
                        if (!target_scope.isNone() and g_spec.name != .empty) {
                            const cp_idx = self.sym_table.lookupInScopeDirect(
                                target_scope,
                                g_spec.name,
                                NamespaceMask.CONST_ONLY,
                            );
                            if (!cp_idx.isNone()) expected_const_ty = self.sym_table.getSymbol(cp_idx).type_id;
                        }
                        if (!expected_const_ty.isError() and expected_const_ty != .group_copy) {
                            _ = try self.checkExpr(def_ast, expected_const_ty);
                        } else {
                            _ = try self.synthExpr(def_ast);
                        }
                        const c_val = (try self.evalConstIntExpr(def_ast, true)) orelse 0;
                        g_spec.default_type_id = try self.pool.internConstIntArg(c_val);
                    } else {
                        const saved_in_sig = self.is_in_fn_signature;
                        self.is_in_fn_signature = false;
                        defer self.is_in_fn_signature = saved_in_sig;
                        g_spec.default_type_id = try self.resolveTypeAst(def_ast);
                        if (g_spec.has_explicit_bound) {
                            try self.validateDeclaredGenericTypeDefaultBound(
                                target_scope,
                                g_spec.*,
                                specs_mut[0..spec_i],
                                self.getAstNodeSpan(def_ast),
                            );
                        }
                    }
                    continue;
                }
            }
            if (!g_spec.is_const and g_spec.default_type_id.isError() and g_spec.default_type_sym != .empty) {
                switch (self.sym_table.lookupLexical(self.current_scope, g_spec.default_type_sym, NamespaceMask.TYPE_ONLY)) {
                    .found => |found_sym| {
                        g_spec.default_type_id = try self.resolveTypeSymbol(found_sym);
                        if (is_local_file and g_spec.has_explicit_bound) {
                            try self.validateDeclaredGenericTypeDefaultBound(
                                target_scope,
                                g_spec.*,
                                specs_mut[0..spec_i],
                                param_span,
                            );
                        }
                    },
                    else => {},
                }
            }
        }
    }

    /// Validates `g_spec.default_type_id` against `g_spec`'s declared `: ConstraintExpr` bound (`E0402`).
    fn validateDeclaredGenericTypeDefaultBound(
        self: *TypeChecker,
        target_scope: ScopeId,
        g_spec: symbol_resolver.GenericParamSpec,
        prior_specs: []const symbol_resolver.GenericParamSpec,
        diag_span: Span,
    ) !void {
        if (target_scope.isNone() or g_spec.name == .empty or g_spec.default_type_id.isError()) return;
        const tp_sym_idx = self.sym_table.lookupInScopeDirect(target_scope, g_spec.name, NamespaceMask.TYPE_ONLY);
        if (tp_sym_idx.isNone()) return;
        const tp_ty = self.sym_table.getSymbol(tp_sym_idx).type_id;
        if (tp_ty.isError() or self.pool.getTag(tp_ty) != .type_param) return;
        const grp_ty = TypeId.fromInt(self.pool.getNode(tp_ty).lhs);
        if (grp_ty.isError()) return;

        const def_ty = g_spec.default_type_id;
        if (self.pool.getTag(def_ty) == .type_param) {
            const def_node = self.pool.getNode(def_ty);
            const def_name_sym = SymbolId.fromInt(def_node.rhs);
            var has_prior_explicit_bound = false;
            for (prior_specs) |prior| {
                if (prior.name == def_name_sym) {
                    has_prior_explicit_bound = prior.has_explicit_bound;
                    break;
                }
            }
            if (!has_prior_explicit_bound) {
                try self.emitGroupConstraintError(diag_span, def_ty, grp_ty, false);
                return;
            }
            const sub_grp = TypeId.fromInt(def_node.lhs);
            if (!isTypeGroupSubset(self.pool, sub_grp, grp_ty)) {
                try self.emitGroupConstraintError(diag_span, def_ty, grp_ty, false);
            }
            return;
        }
        if (self.pool.getFlags(def_ty).has_type_vars) return;

        var sat = checkGroupSatisfaction(self.pool, self.sym_table, self.target_layout, def_ty, grp_ty);
        if (sat == .rejected and self.pool.getTag(grp_ty) == .trait_ty) {
            if (try self.hasTraitImplementation(def_ty, grp_ty, 0)) sat = .matched_exact;
        }
        if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
            try self.emitGroupConstraintError(diag_span, def_ty, grp_ty, sat == .rejected_distinct_without_tilde);
        }
    }

    /// Resolves a trailing generic parameter default `g_spec` (`SE-10A`) into a `TypeId` or `.const_int_arg`.
    fn resolveGenericDefaultSpec(
        self: *TypeChecker,
        owner_sym_idx: SymbolIndex,
        g_spec: symbol_resolver.GenericParamSpec,
    ) anyerror!TypeId {
        if (!g_spec.default_type_id.isError()) return g_spec.default_type_id;
        if (owner_sym_idx.isNone()) {
            return if (g_spec.is_const) self.pool.internConstIntArg(0) else .err_ty;
        }
        const owner_sym = self.sym_table.getSymbol(owner_sym_idx).*;
        const lookup_scope = if (!owner_sym.target_scope.isNone()) owner_sym.target_scope else owner_sym.scope_id;
        if (g_spec.is_const) {
            if (!g_spec.default_ast_node.isNone() and owner_sym.decl_span.file_id == self.file_id) {
                const saved_scope = self.current_scope;
                self.current_scope = lookup_scope;
                defer self.current_scope = saved_scope;
                self.pure_comptime_depth += 1;
                defer self.pure_comptime_depth -= 1;
                _ = try self.synthExpr(g_spec.default_ast_node);
                const c_val = (try self.evalConstIntExpr(g_spec.default_ast_node, true)) orelse 0;
                return self.pool.internConstIntArg(c_val);
            }
            if (!g_spec.default_ast_node.isNone() and owner_sym.decl_span.file_id != self.file_id) {
                if (self.db) |db_ptr| {
                    const other_fid = owner_sym.decl_span.file_id;
                    if (db_ptr.source_inputs.getPtr(other_fid.asInt())) |ext_in| {
                        if (db_ptr.parsed_artifacts.getPtr(other_fid.asInt())) |ext_parsed| {
                            if (self.evalReadOnlyConstExprInt(
                                ext_in.owned_text,
                                &ext_parsed.token_buffer,
                                &ext_parsed.ast_arena,
                                lookup_scope,
                                g_spec.default_ast_node,
                                0,
                            )) |c_val| {
                                return self.pool.internConstIntArg(c_val);
                            }
                        }
                    }
                }
            }
            return self.pool.internConstIntArg(0);
        }
        if (!g_spec.default_ast_node.isNone() and owner_sym.decl_span.file_id == self.file_id) {
            const saved_scope = self.current_scope;
            const saved_in_sig = self.is_in_fn_signature;
            self.current_scope = lookup_scope;
            self.is_in_fn_signature = false;
            defer {
                self.current_scope = saved_scope;
                self.is_in_fn_signature = saved_in_sig;
            }
            return self.resolveTypeAst(g_spec.default_ast_node);
        }
        if (!g_spec.default_ast_node.isNone() and owner_sym.decl_span.file_id != self.file_id) {
            if (self.db) |db_ptr| {
                const other_fid = owner_sym.decl_span.file_id;
                if (db_ptr.source_inputs.getPtr(other_fid.asInt())) |ext_in| {
                    if (db_ptr.parsed_artifacts.getPtr(other_fid.asInt())) |ext_parsed| {
                        var ext_checker = try TypeChecker.init(
                            self.allocator,
                            self.interner,
                            self.pool,
                            self.sym_table,
                            other_fid,
                            ext_in.owned_text,
                            &ext_parsed.token_buffer,
                            &ext_parsed.cst_arena,
                            &ext_parsed.ast_arena,
                            null,
                        );
                        defer ext_checker.deinit();
                        ext_checker.db = db_ptr;
                        ext_checker.target_layout = self.target_layout;
                        ext_checker.cfg_env = self.cfg_env;
                        ext_checker.is_including_tests = self.is_including_tests;
                        ext_checker.current_scope = lookup_scope;
                        return ext_checker.resolveTypeAst(g_spec.default_ast_node);
                    }
                }
            }
        }
        if (g_spec.default_type_sym != .empty) {
            switch (self.sym_table.lookupLexical(lookup_scope, g_spec.default_type_sym, NamespaceMask.TYPE_ONLY)) {
                .found => |found_sym| return self.resolveTypeSymbol(found_sym),
                else => {},
            }
        }
        return .err_ty;
    }

    /// Progressively resolves and substitutes omitted trailing generic defaults (`SE-10A`).
    fn appendResolvedTrailingGenericDefaults(
        self: *TypeChecker,
        owner_sym_idx: SymbolIndex,
        resolved_args: *std.ArrayListUnmanaged(TypeId),
        site_span: Span,
    ) !void {
        if (owner_sym_idx.isNone()) return;
        const g_specs = self.sym_table.getGenericParamSpecs(owner_sym_idx);
        if (resolved_args.items.len >= g_specs.len) return;

        const owner_sym = self.sym_table.getSymbol(owner_sym_idx).*;
        var param_tys: [NominalTypeSubst.MAX_PARAMS]TypeId = @splat(.err_ty);
        var param_const_syms: [NominalTypeSubst.MAX_PARAMS]SymbolId = @splat(.none);
        var param_count: usize = 0;
        if (!owner_sym.target_scope.isNone()) {
            for (self.sym_table.getScopeMembers(owner_sym.target_scope)) |mem_idx| {
                if (param_count >= NominalTypeSubst.MAX_PARAMS) break;
                const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError()) {
                    param_tys[param_count] = mem_sym.type_id;
                    param_count += 1;
                } else if (mem_sym.kind == .const_param_sym and !mem_sym.name.isNone()) {
                    param_const_syms[param_count] = mem_sym.name;
                    param_count += 1;
                }
            }
        }

        var prog_subst: NominalTypeSubst = .{};
        for (resolved_args.items, 0..) |arg_ty, arg_i| {
            if (arg_i >= param_count or prog_subst.len >= NominalTypeSubst.MAX_PARAMS) break;
            prog_subst.keys[prog_subst.len] = param_tys[arg_i];
            prog_subst.const_syms[prog_subst.len] = param_const_syms[arg_i];
            prog_subst.vals[prog_subst.len] = arg_ty;
            prog_subst.len += 1;
        }

        while (resolved_args.items.len < g_specs.len) {
            const spec_idx = resolved_args.items.len;
            const next_spec = g_specs[spec_idx];
            if (!next_spec.has_default) break;
            const raw_def = try self.resolveGenericDefaultSpec(owner_sym_idx, next_spec);
            if (raw_def.isError()) break;
            const subst_def = try prog_subst.applyMut(self.allocator, self.pool, raw_def);
            if (subst_def.isError()) break;

            if (!next_spec.is_const and next_spec.has_explicit_bound and
                spec_idx < param_count and !param_tys[spec_idx].isError() and
                !self.pool.getFlags(subst_def).has_type_vars)
            {
                const grp_ty = TypeId.fromInt(self.pool.getNode(param_tys[spec_idx]).lhs);
                var sat = checkGroupSatisfaction(self.pool, self.sym_table, self.target_layout, subst_def, grp_ty);
                if (sat == .rejected and self.pool.getTag(grp_ty) == .trait_ty) {
                    if (try self.hasTraitImplementation(subst_def, grp_ty, 0)) sat = .matched_exact;
                }
                if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
                    try self.emitGroupConstraintError(
                        site_span,
                        subst_def,
                        grp_ty,
                        sat == .rejected_distinct_without_tilde,
                    );
                }
            }

            try resolved_args.append(self.allocator, subst_def);
            if (spec_idx < param_count and prog_subst.len < NominalTypeSubst.MAX_PARAMS) {
                prog_subst.keys[prog_subst.len] = param_tys[spec_idx];
                prog_subst.const_syms[prog_subst.len] = param_const_syms[spec_idx];
                prog_subst.vals[prog_subst.len] = subst_def;
                prog_subst.len += 1;
            }
        }
    }

    /// Resolves a `type_ns` `SymbolIndex` to its canonical `TypeId` (evaluating lazy `type` aliases if needed).
    fn resolveTypeSymbol(self: *TypeChecker, sym_idx: SymbolIndex) anyerror!TypeId {
        if (sym_idx.isNone()) return .err_ty;
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (sym.type_id.isError() and
            (sym.kind == .type_alias_sym or sym.kind == .distinct_type_sym or
                sym.kind == .refined_type_sym or sym.kind == .type_group_sym))
        {
            const resolved_alias = try self.resolveTypeAliasSymbol(sym_idx);
            self.sym_table.getSymbolMut(sym_idx).type_id = resolved_alias;
            return resolved_alias;
        }
        return sym.type_id;
    }

    /// Resolves a `type` declaration symbol (`type_alias_sym`, `distinct_type_sym`, `refined_type_sym`, `type_group_sym`).
    fn resolveTypeAliasSymbol(self: *TypeChecker, sym_idx: SymbolIndex) anyerror!TypeId {
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (!sym.type_id.isError()) return sym.type_id;
        if (sym.ast_node.isNone()) return .err_ty;

        const saved_scope = self.current_scope;
        if (!sym.target_scope.isNone()) {
            self.current_scope = sym.target_scope;
        }
        defer self.current_scope = saved_scope;

        try self.registerNominalHeaderTypeParams(sym.target_scope, sym.cst_node);
        try self.validateAndPopulateGenericParamSpecs(sym_idx, sym.target_scope);

        const ast_node = self.ast_arena.getNode(sym.ast_node);

        // [1] User-defined Constrained Type Group (`type G = A | ~B;`):
        if (ast_node.lhs.tag == .extra and ast_node.rhs.tag == .extra) {
            if (sym.contract_flags.is_secret) {
                try self.emitDiagnosticSimple(
                    .e0405_distinct_type_mixing,
                    sym.decl_span,
                    "`@secret` cannot be applied to a Constrained Type Group; use `type Name = distinct Base;`",
                    "help: declare a nominal `@secret` newtype with `distinct`",
                );
            }
            const member_slice = self.ast_arena.getExtraSlice(
                ExtraIndex.fromInt(ast_node.lhs.payload),
                ast_node.rhs.payload,
            );
            var prim_mask: u32 = 0;
            var tilde_prim_mask: u32 = 0;
            var exact_members: std.ArrayListUnmanaged(u32) = .empty;
            defer exact_members.deinit(self.allocator);
            var tilde_members: std.ArrayListUnmanaged(u32) = .empty;
            defer tilde_members.deinit(self.allocator);

            for (member_slice) |raw_mem_ast| {
                const mem_ast_id = NodeIndex.fromInt(raw_mem_ast);
                const mem_ty = try self.resolveTypeAst(mem_ast_id);
                if (mem_ty.isError()) continue;

                const mem_node = self.pool.getNode(mem_ty);
                if (mem_node.tag == .tilde_approx) {
                    const inner_ty = self.pool.unwrapUnderlyingType(TypeId.fromInt(mem_node.lhs));
                    if (inner_ty.isSizedPrimitive()) {
                        tilde_prim_mask |= inner_ty.primitiveBit();
                    } else if (inner_ty.isBuiltinGroup()) {
                        tilde_prim_mask |= TypeGroupMask.forBuiltinGroup(inner_ty);
                    } else {
                        try tilde_members.append(self.allocator, inner_ty.toU32());
                    }
                } else if (mem_ty.isSizedPrimitive()) {
                    prim_mask |= mem_ty.primitiveBit();
                } else if (mem_ty.isBuiltinGroup()) {
                    prim_mask |= TypeGroupMask.forBuiltinGroup(mem_ty);
                } else if (self.pool.getUserGroupView(mem_ty)) |sub_view| {
                    prim_mask |= sub_view.prim_mask;
                    tilde_prim_mask |= sub_view.tilde_prim_mask;
                    try exact_members.appendSlice(self.allocator, sub_view.exact_members);
                    try tilde_members.appendSlice(self.allocator, sub_view.tilde_members);
                } else {
                    try exact_members.append(self.allocator, mem_ty.toU32());
                }
            }
            return self.pool.internUserGroup(
                sym_idx,
                prim_mask,
                tilde_prim_mask,
                exact_members.items,
                tilde_members.items,
            );
        }

        if (ast_node.lhs.tag != .node) return .err_ty;
        const target_ast_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const target_ast = self.ast_arena.getNode(target_ast_id);

        // [2] Nominal `distinct` newtype (`type Id = distinct u64;`):
        if (target_ast.tag == .mode_type) {
            const mode_lexeme = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                target_ast.main_token,
            );
            if (std.mem.eql(u8, mode_lexeme, "distinct") and target_ast.lhs.tag == .node) {
                const base_ty = try self.resolveTypeAst(NodeIndex.fromInt(target_ast.lhs.payload));
                const dist_ty = try self.pool.internDistinct(base_ty, sym_idx);
                if (sym.contract_flags.is_secret and !dist_ty.isError() and dist_ty.toU32() < self.pool.nodes.len) {
                    self.pool.nodes.items(.flags)[dist_ty.toU32()].is_secret = true;
                }
                return dist_ty;
            }
        }

        // Transparent `type c_void = opaque;` is the sole legal non-pointer alias of `opaque` (`ADR-22F`):
        const is_plain_transparent_alias = (ast_node.rhs.tag != .node and
            (target_ast.tag == .prim_type or target_ast.tag == .named_type));
        const saved_allow_opaque = self.is_allowing_opaque_type;
        if (is_plain_transparent_alias) self.is_allowing_opaque_type = true;
        const base_ty = resolve_base: {
            defer self.is_allowing_opaque_type = saved_allow_opaque;
            break :resolve_base try self.resolveTypeAst(target_ast_id);
        };
        if (base_ty.isError()) return .err_ty;

        if (sym.contract_flags.is_secret) {
            var msg_buf: [220]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &msg_buf,
                "`@secret` cannot be applied to transparent type alias `{s}`; use `type {s} = distinct …;`",
                .{ sym.name_text, sym.name_text },
            ) catch "`@secret` requires a `distinct` newtype rather than a transparent alias";
            try self.emitDiagnosticSimple(
                .e0405_distinct_type_mixing,
                sym.decl_span,
                msg,
                "help: add `distinct` after `=` to isolate the `@secret` type",
            );
        }

        // [3] Range or pattern refinement (`type Port = u16 is 1024..=65535;`):
        if (ast_node.rhs.tag == .node) {
            const pat_node_id = NodeIndex.fromInt(ast_node.rhs.payload);
            if (self.extractPatternRangeBounds(pat_node_id)) |range| {
                // Verify refinement bounds fit within `base_ty`:
                const underlying_prim = self.pool.unwrapUnderlyingType(base_ty);
                if (getPrimitiveIntBounds(underlying_prim)) |prim_bounds| {
                    if (range.min_val > range.max_val or
                        range.min_val < prim_bounds.min_val or
                        range.max_val > prim_bounds.max_val)
                    {
                        try self.emitRangeRefinementError(
                            self.getAstNodeSpan(pat_node_id),
                            base_ty,
                            range.min_val,
                            prim_bounds.min_val,
                            prim_bounds.max_val,
                        );
                    }
                }
                return self.pool.internRefined(base_ty, sym_idx, range.min_val, range.max_val);
            }
        }

        return base_ty;
    }

    /// Registers header `.type_param` declarations on a nominal `struct`, `union`, `bit_field`, or `enum`.
    fn registerNominalHeaderTypeParams(
        self: *TypeChecker,
        target_scope: ScopeId,
        cst_node: CstNodeIndex,
    ) !void {
        if (target_scope.isNone() or cst_node.isNone() or cst_node.asInt() >= self.cst_arena.countNodes()) return;
        for (self.sym_table.getScopeMembers(target_scope)) |existing_idx| {
            const existing_kind = self.sym_table.getSymbol(existing_idx).kind;
            if (existing_kind == .type_param_sym or existing_kind == .const_param_sym) return;
        }
        const start_idx: usize = cst_node.asInt();
        const root_rec = self.cst_arena.getNode(cst_node);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, root_rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var cursor: usize = start_idx + 1;
        while (cursor < end_idx) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cursor)));
            if (sub.kind == .struct_field or sub.kind == .enum_variant or sub.kind == .block) break;
            if (sub.kind == .type_param) {
                const param_end = @min(cursor + @max(@as(usize, sub.subtree_size), 1), end_idx);
                try self.registerGenericTypeParamFromCst(target_scope, cursor, param_end);
                cursor = param_end;
                continue;
            }
            cursor += 1;
        }
    }

    /// Resolves field types of a `struct`, `union`, or `bit_field` declaration and checks `bit_field` widths.
    fn resolveStructOrBitFieldFields(self: *TypeChecker, struct_sym_idx: SymbolIndex) !void {
        const struct_sym = self.sym_table.getSymbol(struct_sym_idx).*;
        if (struct_sym.target_scope.isNone() or struct_sym.ast_node.isNone()) return;

        const saved_scope = self.current_scope;
        self.current_scope = struct_sym.target_scope;
        defer self.current_scope = saved_scope;

        try self.registerNominalHeaderTypeParams(struct_sym.target_scope, struct_sym.cst_node);
        try self.validateAndPopulateGenericParamSpecs(struct_sym_idx, struct_sym.target_scope);
        try self.syncGenericSelfAliasInTargetScope(struct_sym_idx);

        const ast_node = self.ast_arena.getNode(struct_sym.ast_node);
        const field_members = try self.allocator.dupe(
            SymbolIndex,
            self.sym_table.getScopeMembers(struct_sym.target_scope),
        );
        defer self.allocator.free(field_members);

        if (struct_sym.kind == .bit_field_sym) {
            const bf_node = self.pool.getNode(self.pool.unwrapUnderlyingType(struct_sym.type_id));
            const raw_backing_ty = TypeId.fromInt(bf_node.lhs);
            const backing_ty = self.pool.unwrapUnderlyingType(raw_backing_ty);
            const backing_bits_opt: ?u32 = if (TypeGroupMask.containsPrimitive(TypeGroupMask.UNSIGNED, backing_ty))
                (if (getTargetPrimitiveIntBits(backing_ty, self.target_layout)) |bits_u16| @as(u32, bits_u16) else null)
            else blk_arr: {
                const b_node = self.pool.getNode(backing_ty);
                if (b_node.tag == .array_ty and
                    self.pool.unwrapUnderlyingType(TypeId.fromInt(b_node.lhs)) == .u8_ty and
                    (b_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0 and b_node.rhs > 0)
                {
                    break :blk_arr b_node.rhs * 8;
                }
                break :blk_arr null;
            };
            if (backing_bits_opt == null and !backing_ty.isError()) {
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    struct_sym.decl_span,
                    "`bit_field` backing type must be an unsigned integer (`u8`..`u128`, `usize`) or `[u8; N]`",
                    "invalid `bit_field` backing type",
                );
            }
            const backing_bits: u32 = if (backing_bits_opt) |bits_val| bits_val else 64;
            var total_bits: u32 = 0;
            var has_field_error = false;

            for (field_members) |f_sym_idx| {
                const f_sym = self.sym_table.getSymbol(f_sym_idx).*;
                if (f_sym.kind != .field_sym) continue;
                const field_ty = try self.resolveFieldTypeFromCst(f_sym.cst_node);
                self.sym_table.getSymbolMut(f_sym_idx).type_id = field_ty;
                if (field_ty.isError()) {
                    has_field_error = true;
                    continue;
                }
                const unwrapped_field_ty = self.pool.unwrapUnderlyingType(field_ty);
                const enum_backing = self.pool.getEnumBackingIntType(unwrapped_field_ty);
                const eff_field_ty = enum_backing orelse unwrapped_field_ty;
                const field_max_bits: u32 = if (getTargetPrimitiveIntBits(eff_field_ty, self.target_layout)) |fb|
                    fb
                else if (eff_field_ty == .bool_ty)
                    1
                else
                    backing_bits;
                var eff_width: u32 = f_sym.bit_width;
                if (eff_width == 0 and !self.hasPipeBitWidthInFieldCst(f_sym.cst_node)) {
                    eff_width = field_max_bits;
                    self.sym_table.getSymbolMut(f_sym_idx).bit_width = @intCast(@min(eff_width, 0xFFFF));
                }
                if (eff_width == 0 or eff_width > field_max_bits) {
                    try self.emitDiagnosticSimple(
                        .e0423_invalid_bitfield_or_enum_cast,
                        f_sym.decl_span,
                        "`bit_field` member bit width is out of bounds for its field type",
                        "invalid field bit width here",
                    );
                }
                total_bits += eff_width;
            }
            if (!has_field_error and backing_bits_opt != null and total_bits != backing_bits) {
                var msg_buf: [200]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "`bit_field` member bit widths sum to `{d}` bits, but backing type requires `{d}` bits",
                    .{ total_bits, backing_bits },
                ) catch "`bit_field` member bit widths do not match backing integer width";
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    struct_sym.decl_span,
                    msg,
                    "total bit width must equal backing integer bit width",
                );
            }
            return;
        }

        const type_ast_slice: []const u32 = if (ast_node.lhs.tag == .extra and ast_node.rhs.tag == .extra)
            self.ast_arena.getExtraSlice(ExtraIndex.fromInt(ast_node.lhs.payload), ast_node.rhs.payload)
        else
            &.{};

        var field_i: usize = 0;
        var has_all_copy_fields = true;
        for (field_members) |f_sym_idx| {
            const f_sym = self.sym_table.getSymbol(f_sym_idx).*;
            if (f_sym.kind != .field_sym) continue;
            const field_ty = if (field_i < type_ast_slice.len)
                try self.resolveTypeAst(NodeIndex.fromInt(type_ast_slice[field_i]))
            else
                try self.resolveFieldTypeFromCst(f_sym.cst_node);

            self.sym_table.getSymbolMut(f_sym_idx).type_id = field_ty;
            if (struct_sym.contract_flags.is_repr_c and !field_ty.isError()) {
                try self.checkCAbiBoundaryType(field_ty, f_sym.decl_span);
            }
            if (!self.pool.getFlags(field_ty).is_copy) has_all_copy_fields = false;
            field_i += 1;
        }
        if (has_all_copy_fields and
            !struct_sym.contract_flags.is_linear and
            struct_sym.type_id.toU32() < self.pool.nodes.len and
            !self.pool.getFlags(struct_sym.type_id).has_drop)
        {
            self.pool.nodes.items(.flags)[struct_sym.type_id.toU32()].is_copy = true;
        }
    }

    /// Returns `true` if `field_cst` explicitly wrote a `| width` clause.
    fn hasPipeBitWidthInFieldCst(self: *const TypeChecker, field_cst: CstNodeIndex) bool {
        if (field_cst.isNone() or field_cst.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = field_cst.asInt();
        const rec = self.cst_arena.getNode(field_cst);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(sub.token).kind == .pipe)
            {
                return true;
            }
        }
        return false;
    }

    /// Resolves the type AST node inside a `.struct_field` CST subtree.
    fn resolveFieldTypeFromCst(self: *TypeChecker, field_cst: CstNodeIndex) !TypeId {
        if (field_cst.isNone() or field_cst.asInt() >= self.cst_arena.countNodes()) return .err_ty;
        const start_idx: usize = field_cst.asInt();
        const rec = self.cst_arena.getNode(field_cst);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        const ty_ast = self.findFirstAstInCstRange(start_idx + 1, end_idx);
        if (!ty_ast.isNone()) return self.resolveTypeAst(ty_ast);
        return .err_ty;
    }

    /// Resolves tuple/struct payloads, backed `enum Name: Int` discriminants (`ADR-22D`), and `@derive(From)` (`SE-10B`).
    fn resolveEnumVariantPayloads(self: *TypeChecker, enum_sym_idx: SymbolIndex) !void {
        const enum_sym = self.sym_table.getSymbol(enum_sym_idx).*;
        if (enum_sym.target_scope.isNone()) return;

        const saved_scope = self.current_scope;
        self.current_scope = enum_sym.target_scope;
        defer self.current_scope = saved_scope;

        try self.registerNominalHeaderTypeParams(enum_sym.target_scope, enum_sym.cst_node);
        try self.validateAndPopulateGenericParamSpecs(enum_sym_idx, enum_sym.target_scope);
        try self.syncGenericSelfAliasInTargetScope(enum_sym_idx);

        // Check for integer-backed `enum Name: BackingInt` (`ADR-22D`):
        var backing_int_ty: ?TypeId = null;
        if (!enum_sym.ast_node.isNone() and enum_sym.ast_node.asInt() < self.ast_arena.countNodes()) {
            const enum_ast = self.ast_arena.getNode(enum_sym.ast_node);
            if (enum_ast.lhs.tag == .node) {
                const raw_backing = try self.resolveTypeAst(NodeIndex.fromInt(enum_ast.lhs.payload));
                const unwrapped_backing = self.pool.unwrapUnderlyingType(raw_backing);
                if (!unwrapped_backing.isError()) {
                    if (!unwrapped_backing.isIntegerPrimitive()) {
                        try self.emitDiagnosticSimple(
                            .e0423_invalid_bitfield_or_enum_cast,
                            self.getAstNodeSpan(NodeIndex.fromInt(enum_ast.lhs.payload)),
                            "backed `enum` representation type must be a primitive integer (`u8`..`u128`, `i8`..`i128`, `usize`, `isize`)",
                            "expected primitive integer backing type",
                        );
                    } else {
                        backing_int_ty = unwrapped_backing;
                        if (!enum_sym.type_id.isError()) {
                            try self.pool.setEnumBackingIntType(enum_sym.type_id, unwrapped_backing);
                        }
                    }
                }
            }
        }

        const variant_members = try self.allocator.dupe(
            SymbolIndex,
            self.sym_table.getScopeMembers(enum_sym.target_scope),
        );
        defer self.allocator.free(variant_members);

        var next_discrim: i128 = 0;
        var seen_discrims: std.AutoHashMapUnmanaged(i128, void) = .empty;
        defer seen_discrims.deinit(self.allocator);

        var from_cands: std.ArrayListUnmanaged(FromCand) = .empty;
        defer from_cands.deinit(self.allocator);

        for (variant_members) |var_sym_idx| {
            const var_sym = self.sym_table.getSymbol(var_sym_idx).*;
            if (var_sym.kind != .enum_variant_sym) continue;
            var payload_ty: TypeId = .unit_ty;
            var eq_cst_pos: ?usize = null;
            var var_cst_end: usize = 0;
            var is_single_field_tuple_variant = false;

            if (!var_sym.cst_node.isNone() and var_sym.cst_node.asInt() < self.cst_arena.countNodes()) {
                const start_idx: usize = var_sym.cst_node.asInt();
                const rec = self.cst_arena.getNode(var_sym.cst_node);
                const end_idx: usize = @min(
                    start_idx + @max(@as(usize, rec.subtree_size), 1),
                    self.cst_arena.countNodes(),
                );
                var_cst_end = end_idx;
                var has_lbrace = false;
                var elem_tys: std.ArrayListUnmanaged(TypeId) = .empty;
                defer elem_tys.deinit(self.allocator);
                var child_idx: usize = start_idx + 1;
                while (child_idx < end_idx) {
                    const child_rec = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(child_idx)));
                    const child_size = @max(@as(usize, child_rec.subtree_size), 1);
                    if (child_rec.subtree_size <= 1 and !child_rec.token.isNone() and
                        child_rec.token.asInt() < self.token_buffer.countTokens())
                    {
                        const leaf_kind = self.token_buffer.getToken(child_rec.token).kind;
                        if (leaf_kind == .eq) {
                            eq_cst_pos = child_idx;
                            break;
                        }
                        if (leaf_kind == .lbrace) has_lbrace = true;
                    }
                    if (child_rec.kind != .attribute) {
                        const ty_ast = self.findFirstAstInCstRange(child_idx, @min(child_idx + child_size, end_idx));
                        if (!ty_ast.isNone() and isTypeAstTag(self.ast_arena.getNode(ty_ast).tag)) {
                            try elem_tys.append(self.allocator, try self.resolveTypeAst(ty_ast));
                        }
                    }
                    child_idx += child_size;
                }
                if (elem_tys.items.len == 1) {
                    payload_ty = elem_tys.items[0];
                    is_single_field_tuple_variant = !has_lbrace;
                } else if (elem_tys.items.len > 1) {
                    payload_ty = try self.pool.internTuple(elem_tys.items);
                }
            }
            self.sym_table.getSymbolMut(var_sym_idx).type_id = payload_ty;

            if (backing_int_ty) |b_int| {
                if (payload_ty != .unit_ty) {
                    try self.emitDiagnosticSimple(
                        .e0423_invalid_bitfield_or_enum_cast,
                        var_sym.decl_span,
                        "integer-backed `enum` cannot declare payload-carrying variants",
                        "remove variant payload or remove `: Int` backing type",
                    );
                } else {
                    if (eq_cst_pos) |eq_pos| {
                        const disc_ast = self.findFirstAstInCstRange(eq_pos + 1, var_cst_end);
                        if (!disc_ast.isNone()) {
                            self.pure_comptime_depth += 1;
                            defer self.pure_comptime_depth -= 1;
                            _ = try self.synthExpr(disc_ast);
                            if (try self.evalConstIntExpr(disc_ast, true)) |eval_disc| {
                                next_discrim = eval_disc;
                            }
                        }
                    }
                    if (getPrimitiveIntBounds(b_int)) |bounds| {
                        if (next_discrim < bounds.min_val or next_discrim > bounds.max_val) {
                            try self.emitDiagnosticSimple(
                                .e0423_invalid_bitfield_or_enum_cast,
                                var_sym.decl_span,
                                "backed `enum` variant discriminant overflows backing integer range",
                                "discriminant value out of bounds for backing integer",
                            );
                        }
                    }
                    if (seen_discrims.contains(next_discrim)) {
                        try self.emitDiagnosticSimple(
                            .e0423_invalid_bitfield_or_enum_cast,
                            var_sym.decl_span,
                            "duplicate variant discriminant value in integer-backed `enum`",
                            "discriminant value already assigned to an earlier variant",
                        );
                    } else {
                        try seen_discrims.put(self.allocator, next_discrim, {});
                    }
                    if (!enum_sym.type_id.isError()) {
                        try self.pool.setEnumVariantDiscriminant(enum_sym.type_id, var_sym.member_ordinal, next_discrim);
                    }
                    next_discrim +%= 1;
                }
            } else if (eq_cst_pos != null) {
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    var_sym.decl_span,
                    "explicit `= Expr` variant discriminant requires an integer-backed `enum Name: Int`",
                    "add `: u8` (or another integer type) to the `enum` header",
                );
            }

            if ((var_sym.flags.is_from_error or (enum_sym.derive_mask.has_from and is_single_field_tuple_variant)) and
                payload_ty != .unit_ty and !payload_ty.isError() and !enum_sym.type_id.isError())
            {
                const src_err = if (self.pool.getTag(payload_ty) == .tuple_ty) blk: {
                    const tup_elems = self.pool.getTupleElements(payload_ty);
                    break :blk if (tup_elems.len == 1) TypeId.fromInt(tup_elems[0]) else payload_ty;
                } else payload_ty;
                try from_cands.append(self.allocator, .{
                    .src_ty = src_err,
                    .ordinal = var_sym.member_ordinal,
                    .is_explicit_from = var_sym.flags.is_from_error,
                    .span = var_sym.decl_span,
                });
            }
        }

        // Register `@from` / `@derive(From)` single-field enum variant conversions (`SE-10B`, `E0427` on ambiguity):
        for (from_cands.items, 0..) |cand, i| {
            var has_explicit_override = false;
            var has_ambiguous_dup = false;
            for (from_cands.items, 0..) |other, j| {
                if (i == j or other.src_ty != cand.src_ty) continue;
                if (other.is_explicit_from and !cand.is_explicit_from) {
                    has_explicit_override = true;
                } else if (cand.is_explicit_from == other.is_explicit_from) {
                    if (j < i) has_explicit_override = true else has_ambiguous_dup = true;
                }
            }
            if (has_explicit_override) continue;
            if (has_ambiguous_dup) {
                try self.emitDiagnosticSimple(
                    .e0427_invalid_error_composition,
                    cand.span,
                    "ambiguous `@derive(From)`: multiple variants wrap the same error type without `@from` disambiguation",
                    "mark the preferred conversion variant with `@from`",
                );
                continue;
            }
            try self.sym_table.from_error_pairs.put(
                self.sym_table.allocator,
                packFromErrorPair(cand.src_ty, enum_sym.type_id),
                {},
            );
            try self.pool.registerDerivedFromVariant(cand.src_ty, enum_sym.type_id, cand.ordinal);
        }
    }

    /// Resolves the parameter types, modes, return type, and `@from` registration of a `fn_sym`.
    pub fn resolveFnSignatureSymbol(self: *TypeChecker, fn_sym_idx: SymbolIndex) !void {
        const fn_sym = self.sym_table.getSymbol(fn_sym_idx).*;
        if (!fn_sym.type_id.isError() and self.pool.getTag(fn_sym.type_id) == .fn_ty) return;
        if (fn_sym.ast_node.isNone()) return;

        const prev_specs = try self.allocator.dupe(
            symbol_resolver.FnParamSpec,
            self.sym_table.getFnParamSpecs(fn_sym_idx),
        );
        defer self.allocator.free(prev_specs);

        self.active_bind_once_vars.clearRetainingCapacity();
        const saved_scope = self.current_scope;
        const saved_in_sig = self.is_in_fn_signature;
        self.is_in_fn_signature = true;
        defer {
            self.current_scope = saved_scope;
            self.is_in_fn_signature = saved_in_sig;
        }

        const fn_scope = try self.sym_table.scope_arena.allocScope(
            .fn_scope,
            fn_sym.scope_id,
            fn_sym.def_id,
            self.file_id,
            .{},
        );
        self.sym_table.getSymbolMut(fn_sym_idx).target_scope = fn_scope;
        self.current_scope = fn_scope;

        var param_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer param_types.deinit(self.allocator);
        var param_modes: std.ArrayListUnmanaged(ParamMode) = .empty;
        defer param_modes.deinit(self.allocator);
        var param_specs: std.ArrayListUnmanaged(symbol_resolver.FnParamSpec) = .empty;
        defer param_specs.deinit(self.allocator);
        var is_variadic_fn = fn_sym.extra_flags.is_variadic;
        var has_builder_param = fn_sym.extra_flags.is_builder;
        var is_async_fn = false;

        // [1] Walk `.type_params` and `.param_list` inside `fn_sym.cst_node`:
        if (!fn_sym.cst_node.isNone() and fn_sym.cst_node.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = fn_sym.cst_node.asInt();
            const root_rec = self.cst_arena.getNode(fn_sym.cst_node);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, root_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );

            var cursor: usize = start_idx + 1;
            while (cursor < end_idx) {
                const cst_id = CstNodeIndex.fromInt(@intCast(cursor));
                const node = self.cst_arena.getNode(cst_id);
                if (node.kind == .block or node.kind == .fn_expr_body) break;
                if (node.subtree_size <= 1 and !node.token.isNone() and
                    node.token.asInt() < self.token_buffer.countTokens())
                {
                    const hdr_tok_kind = self.token_buffer.getToken(node.token).kind;
                    if (hdr_tok_kind == .lbrace) break;
                    if (hdr_tok_kind == .kw_async) is_async_fn = true;
                }

                if (node.kind == .type_param) {
                    const param_end = @min(cursor + @max(@as(usize, node.subtree_size), 1), end_idx);
                    try self.registerGenericTypeParamFromCst(fn_scope, cursor, param_end);
                    cursor = param_end;
                    continue;
                }
                if (node.kind == .variadic_param or
                    (node.subtree_size <= 1 and !node.token.isNone() and
                        node.token.asInt() < self.token_buffer.countTokens() and
                        self.token_buffer.getToken(node.token).kind == .dotdotdot))
                {
                    is_variadic_fn = true;
                    cursor += @max(@as(usize, node.subtree_size), 1);
                    continue;
                }

                if (node.kind == .fn_param) {
                    const param_end = @min(cursor + @max(@as(usize, node.subtree_size), 1), end_idx);
                    if (self.hasDotDotDotInCstRange(cursor, param_end)) {
                        is_variadic_fn = true;
                        cursor = param_end;
                        continue;
                    }
                    const ord_idx = param_types.items.len;
                    const prev_opt: ?symbol_resolver.FnParamSpec = if (ord_idx < prev_specs.len and !prev_specs[ord_idx].is_variadic)
                        prev_specs[ord_idx]
                    else
                        null;
                    const param_info = try self.extractFnParamFromCst(
                        fn_sym_idx,
                        fn_scope,
                        cursor,
                        param_end,
                        @intCast(ord_idx),
                        prev_opt,
                    );
                    if (param_info.spec.is_builder) has_builder_param = true;
                    try param_types.append(self.allocator, param_info.ty);
                    try param_modes.append(self.allocator, param_info.mode);
                    try param_specs.append(self.allocator, param_info.spec);
                    cursor = param_end;
                    continue;
                }
                cursor += 1;
            }
        }
        try self.validateAndPopulateGenericParamSpecs(fn_sym_idx, fn_scope);

        // Enforce `SE-11` `E0430`: required non-keyword-only parameter cannot follow a defaulted parameter:
        var has_seen_std_default = false;
        for (param_specs.items) |p_spec| {
            if (p_spec.is_keyword_only) continue;
            if (p_spec.has_default) {
                has_seen_std_default = true;
            } else if (has_seen_std_default) {
                const p_span = if (!p_spec.name.isNone()) blk_sp: {
                    const p_sym = self.sym_table.lookupInScopeDirect(fn_scope, p_spec.name, NamespaceMask.VALUE_ONLY);
                    break :blk_sp if (!p_sym.isNone()) self.sym_table.getSymbol(p_sym).decl_span else fn_sym.decl_span;
                } else fn_sym.decl_span;
                try self.emitDiagnosticSimple(
                    .e0430_non_default_after_default_param,
                    p_span,
                    "required parameter without default cannot follow a defaulted parameter before `*`",
                    "move required parameters before defaulted parameters or place after `*,`",
                );
            }
        }

        if (is_variadic_fn) {
            if (!fn_sym.flags.is_extern or param_types.items.len == 0) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    fn_sym.decl_span,
                    "C variadic `...` is only permitted on `extern \"C\" fn` declarations with at least one fixed parameter",
                    "invalid C variadic signature",
                );
            }
        }

        try self.sym_table.setFnParamSpecs(fn_sym_idx, param_specs.items);

        // [2] Resolve return type (`-> Type`; defaults to `.unit_ty`):
        const fn_ast = self.ast_arena.getNode(fn_sym.ast_node);
        var ret_ty: TypeId = .unit_ty;
        if (fn_ast.lhs.tag == .node) {
            self.is_in_return_type_pos = true;
            defer self.is_in_return_type_pos = false;
            ret_ty = try self.resolveTypeAst(NodeIndex.fromInt(fn_ast.lhs.payload));
        }
        if (fn_ast.tag == .test_decl or fn_ast.tag == .bench_decl) {
            const is_valid_test_ret = ret_ty.isError() or ret_ty == .unit_ty or
                (self.pool.getTag(ret_ty) == .result_ty and
                    TypeId.fromInt(self.pool.getNode(ret_ty).lhs) == .unit_ty);
            if (!is_valid_test_ret) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    fn_sym.decl_span,
                    "`test` and `bench` declarations must return `unit` or `unit!E`",
                    "expected `unit` or `unit!E` return type",
                );
            }
            if (fn_ast.tag == .bench_decl) {
                const expected_bencher_ref = try self.pool.internRef(.bencher_ty, true);
                if (param_types.items.len != 1 or (!param_types.items[0].isError() and param_types.items[0] != expected_bencher_ref)) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        fn_sym.decl_span,
                        "`bench` declaration must accept a single `b: &mut Bencher` parameter",
                        "expected `(b: &mut Bencher)` parameter",
                    );
                }
            }
        }

        const is_must_use = fn_sym.flags.is_must_use or self.pool.getFlags(ret_ty).is_must_use;
        if (is_must_use) {
            self.sym_table.getSymbolMut(fn_sym_idx).flags.is_must_use = true;
        }
        if (fn_ast.tag == .subscript_decl and self.hasSubscriptInoutArmInCst(fn_sym.cst_node)) {
            self.sym_table.getSymbolMut(fn_sym_idx).flags.is_mut = true;
        }
        const fn_contracts: FnPtrContractMask = .{
            .has_no_alloc = fn_sym.contract_flags.is_no_alloc,
            .has_no_panic = fn_sym.contract_flags.is_no_panic,
            .has_no_block = fn_sym.contract_flags.is_no_block,
            .has_builder = has_builder_param,
        };
        const fn_ty = try self.pool.internFnSignatureExt(
            .fn_ty,
            param_types.items,
            param_modes.items,
            ret_ty,
            is_must_use,
            fn_contracts,
            .copy_tier,
            false,
            is_variadic_fn,
            fn_sym.flags.is_extern,
            is_async_fn,
        );
        self.sym_table.getSymbolMut(fn_sym_idx).type_id = fn_ty;
        try self.extractAndValidateFnFfiContract(fn_sym_idx, param_types.items, param_specs.items, ret_ty);

        // [3] Register `@from` error conversion (`@from fn from_io(e: SrcErr) -> DstErr` or `Result[_, DstErr]`):
        if (fn_sym.flags.is_from_error and param_types.items.len == 1) {
            const src_err = param_types.items[0];
            const dst_err = if (self.pool.getTag(ret_ty) == .result_ty)
                TypeId.fromInt(self.pool.getNode(ret_ty).rhs)
            else
                ret_ty;
            if (!src_err.isError() and !dst_err.isError()) {
                const pair_key = packFromErrorPair(src_err, dst_err);
                try self.sym_table.from_error_pairs.put(
                    self.sym_table.allocator,
                    pair_key,
                    {},
                );
                if (!fn_sym.def_id.isNone()) {
                    try self.sym_table.from_error_fn_defs.put(
                        self.sym_table.allocator,
                        pair_key,
                        fn_sym.def_id,
                    );
                }
            }
        }
    }

    /// Returns `true` if `ty` or any nested array, pointer, reference, or tuple element is `Option[*T]` / `Option[*mut T]`.
    fn hasForbiddenCAbiOptionalRawPtr(self: *const TypeChecker, ty: TypeId, depth: u32) bool {
        if (depth >= 32 or ty.isError()) return false;
        const unwrapped = self.pool.unwrapUnderlyingType(ty);
        const node = self.pool.getNode(unwrapped);
        return switch (node.tag) {
            .optional_ty => blk: {
                const inner_ty = self.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
                if (self.pool.getTag(inner_ty) == .raw_ptr_ty) break :blk true;
                break :blk self.hasForbiddenCAbiOptionalRawPtr(inner_ty, depth + 1);
            },
            .array_ty,
            .soa_array_ty,
            .slice_ty,
            .soa_slice_ty,
            .raw_ptr_ty,
            .ref_ty,
            .mut_ref_ty,
            => self.hasForbiddenCAbiOptionalRawPtr(TypeId.fromInt(node.lhs), depth + 1),
            .tuple_ty => blk: {
                for (self.pool.getTupleElements(unwrapped)) |elem_raw| {
                    if (self.hasForbiddenCAbiOptionalRawPtr(TypeId.fromInt(elem_raw), depth + 1)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Rejects non-niche `Option[*T]` / `Option[*mut T]` (`16B` tagged union) across C ABI boundaries (`E0401`, `DR-10` §2.3).
    fn checkCAbiBoundaryType(self: *TypeChecker, ty: TypeId, span: Span) !void {
        if (!self.hasForbiddenCAbiOptionalRawPtr(ty, 0)) return;

        const sink = self.diagnostic_sink orelse return;
        const labels = [1]LabeledSpan{
            .{
                .span = span,
                .label = "`*T?` / `*mut T?` has 16-byte non-niche layout incompatible with C pointers",
                .style = .primary,
            },
        };
        const notes = [1][]const u8{
            "help: use *T or *mut T with @may_be_null for nullable C object pointers, or (extern \"C\" fn(…))? for nullable C function pointers",
        };
        _ = try sink.emit(.{
            .code = .e0401_type_mismatch,
            .severity = .err,
            .primary_span = span,
            .message = "cannot use non-niche optional raw pointer `*T?` / `*mut T?` in C ABI signature or `@repr(C)` layout",
            .labels = &labels,
            .notes = &notes,
        });
    }

    /// Propagates synthetic `@c_import` module namespace metadata onto `target_sym_idx` when `init_expr_id` resolved a C module.
    fn bindCImportModuleToSymbolIfPresent(
        self: *TypeChecker,
        target_sym_idx: SymbolIndex,
        init_expr_id: NodeIndex,
    ) void {
        if (target_sym_idx.isNone() or init_expr_id.isNone()) return;
        const is_c_import_call = init_expr_id.asInt() < self.ast_arena.countNodes() and blk_ci: {
            const expr_node = self.ast_arena.getNode(init_expr_id);
            if ((expr_node.tag != .call_expr and expr_node.tag != .generic_call) or expr_node.lhs.tag != .node) {
                break :blk_ci false;
            }
            const callee_id = NodeIndex.fromInt(expr_node.lhs.payload);
            if (callee_id.asInt() >= self.ast_arena.countNodes()) break :blk_ci false;
            const callee_node = self.ast_arena.getNode(callee_id);
            if (callee_node.tag != .ident_expr or callee_node.main_token.isNone() or
                self.token_buffer.getToken(callee_node.main_token).kind != .at or
                callee_node.lhs.tag != .token)
            {
                break :blk_ci false;
            }
            const intr_name = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                TokenIndex.fromInt(callee_node.lhs.payload),
            );
            break :blk_ci std.mem.eql(u8, intr_name, "c_import");
        };
        const target_mut = self.sym_table.getSymbolMut(target_sym_idx);
        var is_module_binding = is_c_import_call;
        if (init_expr_id.asInt() < self.node_symbols.len) {
            const init_sym_idx = self.node_symbols[init_expr_id.asInt()];
            if (!init_sym_idx.isNone() and init_sym_idx.asInt() < self.sym_table.countSymbols()) {
                const init_sym = self.sym_table.getSymbol(init_sym_idx).*;
                if (init_sym.kind == .module_sym and !init_sym.target_scope.isNone()) {
                    target_mut.target_scope = init_sym.target_scope;
                    target_mut.target_symbol = init_sym_idx;
                    is_module_binding = true;
                }
            }
        }
        if (is_module_binding) {
            const ident_class = lexer.classifyIdentifierOrKeyword(target_mut.name_text);
            if (ident_class.case_style == .snake_case and ident_class.is_canonical) {
                if (self.diagnostic_sink) |sink| {
                    var diag_idx: usize = 0;
                    while (diag_idx < sink.diagnostics.items.len) {
                        const existing = sink.diagnostics.items[diag_idx];
                        if (existing.code == .w0201_non_canonical_identifier_case and
                            existing.primary_span.file_id == target_mut.decl_span.file_id and
                            existing.primary_span.start_byte == target_mut.decl_span.start_byte and
                            existing.primary_span.end_byte == target_mut.decl_span.end_byte)
                        {
                            _ = sink.diagnostics.orderedRemove(diag_idx);
                            sink.warning_count -|= 1;
                        } else {
                            diag_idx += 1;
                        }
                    }
                }
            }
        }
    }

    /// Extracts the first identifier or dotted-path argument inside `[arg_start .. attr_end)`.
    fn extractAttrIdentPathTokens(
        self: *const TypeChecker,
        arg_start: usize,
        attr_end: usize,
        out_tokens: *[8]TokenIndex,
    ) usize {
        var count: usize = 0;
        var has_open_paren = false;
        var cur = arg_start;
        while (cur < attr_end) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size > 1 or sub.token.isNone() or
                sub.token.asInt() >= self.token_buffer.countTokens())
            {
                continue;
            }
            const kind = self.token_buffer.getToken(sub.token).kind;
            if (kind == .lparen) {
                has_open_paren = true;
                continue;
            }
            if (!has_open_paren) continue;
            if (kind == .rparen or kind == .comma) break;
            if (symbol_resolver.isIdentifierToken(kind) or kind == .kw_async) {
                if (count < out_tokens.len) {
                    out_tokens[count] = sub.token;
                    count += 1;
                }
            }
        }
        return count;
    }

    /// Parses and validates Phase 8 FFI contract attributes on `fn_sym_idx` and its parameters, populating `sym_table.ffi_contracts`.
    fn extractAndValidateFnFfiContract(
        self: *TypeChecker,
        fn_sym_idx: SymbolIndex,
        param_types: []const TypeId,
        param_specs: []const symbol_resolver.FnParamSpec,
        ret_ty: TypeId,
    ) !void {
        const fn_sym = self.sym_table.getSymbol(fn_sym_idx).*;
        if (fn_sym.flags.is_extern) {
            for (param_types, 0..) |param_ty, p_ord| {
                const p_span = if (p_ord < param_specs.len and !param_specs[p_ord].name.isNone()) blk_sp: {
                    const p_sym = self.sym_table.lookupInScopeDirect(
                        fn_sym.target_scope,
                        param_specs[p_ord].name,
                        NamespaceMask.VALUE_ONLY,
                    );
                    break :blk_sp if (!p_sym.isNone()) self.sym_table.getSymbol(p_sym).decl_span else fn_sym.decl_span;
                } else fn_sym.decl_span;
                try self.checkCAbiBoundaryType(param_ty, p_span);
            }
            const fn_ast = self.ast_arena.getNode(fn_sym.ast_node);
            const ret_span = if (fn_ast.lhs.tag == .node)
                self.getAstNodeSpan(NodeIndex.fromInt(fn_ast.lhs.payload))
            else
                fn_sym.decl_span;
            try self.checkCAbiBoundaryType(ret_ty, ret_span);
        }

        var contract: symbol_resolver.FfiFnContract = if (self.sym_table.getFfiContract(fn_sym_idx)) |existing|
            existing.*
        else
            .{};
        contract.param_contracts = &.{};

        var param_contracts = try self.allocator.alloc(symbol_resolver.FfiParamContract, param_types.len);
        defer if (param_contracts.len > 0) self.allocator.free(param_contracts);
        @memset(param_contracts, .{});
        var has_any_param_contract = false;
        var has_any_fn_contract = self.sym_table.getFfiContract(fn_sym_idx) != null;

        if (!fn_sym.cst_node.isNone() and fn_sym.cst_node.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = fn_sym.cst_node.asInt();
            const root_rec = self.cst_arena.getNode(fn_sym.cst_node);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, root_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );

            var current_param_ord: usize = 0;
            var cursor: usize = start_idx + 1;
            while (cursor < end_idx) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cursor)));
                if (sub.kind == .block or sub.kind == .fn_expr_body) break;
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens() and
                    self.token_buffer.getToken(sub.token).kind == .lbrace)
                {
                    break;
                }

                if (sub.kind == .fn_param) {
                    const param_end = @min(cursor + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    if (!self.hasDotDotDotInCstRange(cursor, param_end) and current_param_ord < param_contracts.len) {
                        var p_cur = cursor + 1;
                        while (p_cur < param_end) : (p_cur += 1) {
                            const p_sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(p_cur)));
                            if (p_sub.kind == .attribute) {
                                const attr_end = @min(p_cur + @max(@as(usize, p_sub.subtree_size), 1), param_end);
                                if (try self.applyParamFfiAttributeCst(
                                    p_cur,
                                    attr_end,
                                    current_param_ord,
                                    param_types,
                                    param_specs,
                                    &param_contracts[current_param_ord],
                                )) {
                                    has_any_param_contract = true;
                                }
                                if (p_sub.subtree_size > 1) p_cur += @as(usize, p_sub.subtree_size) - 1;
                            }
                        }
                        current_param_ord += 1;
                    }
                    cursor = param_end;
                    continue;
                }

                if (sub.kind == .attribute) {
                    const attr_end = @min(cursor + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    if (try self.applyFnHeaderOrReturnFfiAttributeCst(
                        fn_sym.scope_id,
                        cursor,
                        attr_end,
                        ret_ty,
                        &contract,
                    )) {
                        has_any_fn_contract = true;
                    }
                    cursor = attr_end;
                    continue;
                }
                cursor += 1;
            }
        }

        if (contract.is_ret_may_be_null and contract.is_ret_non_null) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                fn_sym.decl_span,
                "cannot combine contradictory `@may_be_null` and `@non_null` contracts on the same return value",
                "conflicting nullability contracts",
            );
        }

        if (has_any_fn_contract or has_any_param_contract) {
            try self.sym_table.setFfiContract(
                fn_sym_idx,
                contract,
                if (has_any_param_contract) param_contracts else &.{},
            );
        }
    }

    /// Parses one `.attribute` CST node on a function header or return type into `contract`.
    fn applyFnHeaderOrReturnFfiAttributeCst(
        self: *TypeChecker,
        fn_enclosing_scope: ScopeId,
        attr_start: usize,
        attr_end: usize,
        ret_ty: TypeId,
        contract: *symbol_resolver.FfiFnContract,
    ) !bool {
        var name_tok: TokenIndex = .none;
        var name_pos: usize = attr_start;
        var cur = attr_start + 1;
        while (cur < attr_end) : (cur += 1) {
            const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                leaf.token.asInt() < self.token_buffer.countTokens())
            {
                const kind = self.token_buffer.getToken(leaf.token).kind;
                if (symbol_resolver.isIdentifierToken(kind)) {
                    name_tok = leaf.token;
                    name_pos = cur;
                    break;
                }
            }
        }
        if (name_tok.isNone()) return false;
        const attr_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok);
        const attr_span = self.token_buffer.getTokenSpan(self.file_id, name_tok);

        const attr_kind = FN_FFI_ATTR_MAP.get(attr_name) orelse return false;
        switch (attr_kind) {
            .trusted => {
                contract.is_trusted = true;
                return true;
            },
            .owned_by_caller => {
                contract.is_ret_owned_by_caller = true;
                if (!ret_ty.isError() and ret_ty == .unit_ty) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        attr_span,
                        "`@owned_by_caller` requires a non-`unit` pointer or handle return type",
                        "function returns `unit`",
                    );
                }
                return true;
            },
            .may_be_null => {
                contract.is_ret_may_be_null = true;
                return true;
            },
            .non_null => {
                contract.is_ret_non_null = true;
                return true;
            },
            .null_terminated => {
                contract.is_ret_null_terminated = true;
                return true;
            },
            .thread_local => {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    attr_span,
                    "`@thread_local` is only permitted on `extern static` variable declarations",
                    "invalid `@thread_local` on function",
                );
                return false;
            },
            .free_with => {
                var path_toks: [8]TokenIndex = undefined;
                const seg_count = self.extractAttrIdentPathTokens(name_pos + 1, attr_end, &path_toks);
                if (seg_count == 0) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        attr_span,
                        "`@free_with` requires a deallocator function identifier (`@free_with(dealloc_fn)`)",
                        "missing deallocator function argument",
                    );
                    return true;
                }
                const target_tok = path_toks[seg_count - 1];
                const target_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, target_tok);
                const target_span = self.token_buffer.getTokenSpan(self.file_id, target_tok);
                const lookup_scope = if (seg_count > 1)
                    try symbol_resolver.resolveModulePathSegments(
                        self.sym_table,
                        self.interner,
                        self.file_id,
                        fn_enclosing_scope,
                        fn_enclosing_scope,
                        path_toks[0 .. seg_count - 1],
                        self.source,
                        self.token_buffer,
                        self.diagnostic_sink,
                    )
                else
                    fn_enclosing_scope;
                if (!lookup_scope.isNone() and target_lex.len > 0) {
                    const target_sym_id = try self.interner.intern(target_lex);
                    const lookup_res = if (seg_count == 1)
                        self.sym_table.lookupLexical(lookup_scope, target_sym_id, NamespaceMask.VALUE_ONLY)
                    else
                        self.sym_table.lookupInTargetScope(
                            lookup_scope,
                            fn_enclosing_scope,
                            target_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        );
                    switch (lookup_res) {
                        .found => |found_idx| {
                            self.sym_table.markSymbolUsed(found_idx);
                            var resolved_idx = found_idx;
                            const found_sym = self.sym_table.getSymbol(found_idx).*;
                            if (found_sym.kind == .use_alias_sym and !found_sym.target_symbol.isNone()) {
                                resolved_idx = found_sym.target_symbol;
                            }
                            if (self.sym_table.getSymbol(resolved_idx).kind != .fn_sym) {
                                try self.emitDiagnosticSimple(
                                    .e0401_type_mismatch,
                                    target_span,
                                    "`@free_with` target must resolve to a function declaration",
                                    "not a function symbol",
                                );
                            } else {
                                contract.ret_free_with_sym = resolved_idx;
                                contract.is_ret_owned_by_caller = true;
                            }
                        },
                        .private_error => |priv_idx| {
                            if (self.diagnostic_sink) |sink| {
                                try symbol_resolver.emitPrivateAccessDiagnostic(
                                    sink,
                                    self.sym_table.getSymbol(priv_idx),
                                    target_span,
                                );
                            }
                        },
                        .not_found => {
                            if (self.diagnostic_sink) |sink| {
                                try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                    sink,
                                    self.interner,
                                    target_lex,
                                    target_span,
                                    self.sym_table.suggestClosestSymbol(
                                        lookup_scope,
                                        target_lex,
                                        NamespaceMask.VALUE_ONLY,
                                    ),
                                );
                            }
                        },
                    }
                }
                return true;
            },
        }
    }

    /// Parses one `.attribute` CST node on parameter `param_ordinal` into `out_contract`.
    fn applyParamFfiAttributeCst(
        self: *TypeChecker,
        attr_start: usize,
        attr_end: usize,
        param_ordinal: usize,
        param_types: []const TypeId,
        param_specs: []const symbol_resolver.FnParamSpec,
        out_contract: *symbol_resolver.FfiParamContract,
    ) !bool {
        var name_tok: TokenIndex = .none;
        var name_pos: usize = attr_start;
        var cur = attr_start + 1;
        while (cur < attr_end) : (cur += 1) {
            const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                leaf.token.asInt() < self.token_buffer.countTokens())
            {
                const kind = self.token_buffer.getToken(leaf.token).kind;
                if (symbol_resolver.isIdentifierToken(kind)) {
                    name_tok = leaf.token;
                    name_pos = cur;
                    break;
                }
            }
        }
        if (name_tok.isNone()) return false;
        const attr_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok);
        const attr_span = self.token_buffer.getTokenSpan(self.file_id, name_tok);

        const attr_kind = PARAM_FFI_ATTR_MAP.get(attr_name) orelse return false;
        switch (attr_kind) {
            .null_terminated => {
                out_contract.is_null_terminated = true;
                return true;
            },
            .consumes => {
                out_contract.is_consumes = true;
                return true;
            },
            .escapes => {
                out_contract.is_escapes = true;
                return true;
            },
            .borrowed => {
                out_contract.is_borrowed = true;
                return true;
            },
            .out_param => {
                out_contract.is_out_param = true;
                return true;
            },
            .may_be_null => {
                out_contract.is_may_be_null = true;
                if (out_contract.is_non_null) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        attr_span,
                        "cannot combine contradictory `@may_be_null` and `@non_null` contracts on the same parameter",
                        "conflicting parameter nullability contracts",
                    );
                }
                return true;
            },
            .non_null => {
                out_contract.is_non_null = true;
                if (out_contract.is_may_be_null) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        attr_span,
                        "cannot combine contradictory `@may_be_null` and `@non_null` contracts on the same parameter",
                        "conflicting parameter nullability contracts",
                    );
                }
                return true;
            },
            .slice_len, .byte_len => {
                const is_slice_len = attr_kind == .slice_len;
                var path_toks: [8]TokenIndex = undefined;
                const seg_count = self.extractAttrIdentPathTokens(name_pos + 1, attr_end, &path_toks);
                if (seg_count != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        attr_span,
                        "`@slice_len` / `@byte_len` requires a single integer parameter name from the same signature",
                        "expected `@slice_len(len_param)` or `@byte_len(len_param)`",
                    );
                    return true;
                }
                const len_tok = path_toks[0];
                const len_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, len_tok);
                const len_span = self.token_buffer.getTokenSpan(self.file_id, len_tok);
                var matched_ordinal: ?usize = null;
                for (param_specs, 0..) |p_spec, idx| {
                    if (!p_spec.is_variadic and idx < param_types.len and std.mem.eql(u8, p_spec.name_text, len_name)) {
                        matched_ordinal = idx;
                        break;
                    }
                }
                if (matched_ordinal) |ord| {
                    const len_ty = self.pool.unwrapRefinementBase(self.pool.unwrapUnderlyingType(param_types[ord]));
                    if (ord == param_ordinal or ord > std.math.maxInt(u8) or
                        (!len_ty.isError() and !len_ty.isIntegerPrimitive()))
                    {
                        try self.emitDiagnosticSimple(
                            .e0401_type_mismatch,
                            len_span,
                            "`@slice_len` / `@byte_len` parameter reference must name a distinct integer parameter",
                            "expected integer length parameter here",
                        );
                    } else {
                        if (is_slice_len) {
                            out_contract.has_slice_len = true;
                        } else {
                            out_contract.has_byte_len = true;
                        }
                        out_contract.len_param_ordinal = @intCast(ord);
                    }
                } else {
                    try self.emitDiagnosticSimple(
                        .e0403_unresolved_symbol,
                        len_span,
                        "unknown parameter referenced in `@slice_len` / `@byte_len` contract",
                        "parameter name not found in this function signature",
                    );
                }
                return true;
            },
        }
    }

    /// Returns `true` if the shallow parameter header of `[cst_start .. cst_end)` contains a `.dotdotdot` variadic marker,
    /// skipping nested callable types, type/default annotations after `:`/`=`/`->`, and expression blocks.
    fn hasDotDotDotInCstRange(self: *const TypeChecker, cst_start: usize, cst_end: usize) bool {
        if (cst_start >= cst_end or cst_start >= self.cst_arena.countNodes()) return false;
        const root_kind = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cst_start))).kind;
        var cur = cst_start;
        while (cur < cst_end) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (cur > cst_start and (sub.kind == .fn_type or sub.kind == .closure_type or sub.kind == .block)) {
                cur += @max(@as(usize, sub.subtree_size), 1);
                continue;
            }
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const tok_kind = self.token_buffer.getToken(sub.token).kind;
                if (tok_kind == .dotdotdot) return true;
                if (root_kind == .fn_param and (tok_kind == .colon or tok_kind == .eq)) return false;
                if (root_kind == .fn_type and tok_kind == .arrow) return false;
            }
            cur += 1;
        }
        return false;
    }

    /// Returns `true` if a `subscript` declaration CST contains an `inout` accessor arm.
    fn hasSubscriptInoutArmInCst(self: *const TypeChecker, sub_cst: CstNodeIndex) bool {
        if (sub_cst.isNone() or sub_cst.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = sub_cst.asInt();
        const rec = self.cst_arena.getNode(sub_cst);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const node = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (node.kind == .subscript_arm) {
                const arm_end = @min(cur + @max(@as(usize, node.subtree_size), 1), end_idx);
                var arm_cur = cur + 1;
                while (arm_cur < arm_end) : (arm_cur += 1) {
                    const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(arm_cur)));
                    if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                        leaf.token.asInt() < self.token_buffer.countTokens())
                    {
                        const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, leaf.token);
                        if (std.mem.eql(u8, lex, "inout")) return true;
                        break;
                    }
                }
            }
        }
        return false;
    }

    /// Registers a generic `[T: Bound]` or `[const N: usize]` parameter inside `fn_scope`.
    fn registerGenericTypeParamFromCst(
        self: *TypeChecker,
        fn_scope: ScopeId,
        cst_start: usize,
        cst_end: usize,
    ) !void {
        var is_const_param = false;
        var name_tok: TokenIndex = .none;
        var eq_pos: ?usize = null;

        var cur = cst_start + 1;
        while (cur < cst_end) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
            if (!is_leaf or sub.flags.is_missing_or_injected or sub.token.isNone()) continue;
            if (sub.token.asInt() >= self.token_buffer.countTokens()) continue;
            const kind = self.token_buffer.getToken(sub.token).kind;
            if (kind == .kw_const) {
                is_const_param = true;
            } else if (name_tok.isNone() and symbol_resolver.isIdentifierToken(kind)) {
                name_tok = sub.token;
            } else if (kind == .eq and eq_pos == null) {
                eq_pos = cur;
                break;
            }
        }
        if (name_tok.isNone()) return;

        const name_str = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok);
        if (name_str.len == 0) return;
        const name_sym = try self.interner.intern(name_str);
        const bound_search_end = eq_pos orelse cst_end;
        const bound_ast = self.findFirstAstInCstRange(cst_start + 1, bound_search_end);
        const bound_ty = if (!bound_ast.isNone() and isTypeAstTag(self.ast_arena.getNode(bound_ast).tag)) blk: {
            const saved_in_fn_sig = self.is_in_fn_signature;
            if (!is_const_param) self.is_in_fn_signature = false;
            defer self.is_in_fn_signature = saved_in_fn_sig;
            break :blk try self.resolveTypeAst(bound_ast);
        } else TypeId.group_copy;

        const param_ty = if (is_const_param)
            bound_ty
        else
            try self.pool.internTypeParam(bound_ty, name_sym);

        _ = try self.sym_table.defineSymbol(.{
            .name = name_sym,
            .name_text = self.interner.get(name_sym),
            .kind = if (is_const_param) .const_param_sym else .type_param_sym,
            .namespace = if (is_const_param) .const_ns else .type_ns,
            .visibility = .private,
            .flags = .{ .is_used = true },
            .scope_id = fn_scope,
            .decl_span = self.token_buffer.getTokenSpan(self.file_id, name_tok),
            .type_id = param_ty,
        }, self.diagnostic_sink);
    }

    /// Extracts a single `.fn_param` parameter binding, its `TypeId` + `ParamMode`, and its `FnParamSpec`.
    fn extractFnParamFromCst(
        self: *TypeChecker,
        fn_sym_idx: SymbolIndex,
        fn_scope: ScopeId,
        cst_start: usize,
        cst_end: usize,
        ordinal: u16,
        prev_spec: ?symbol_resolver.FnParamSpec,
    ) !struct { ty: TypeId, mode: ParamMode, spec: symbol_resolver.FnParamSpec } {
        var name_tok: TokenIndex = .none;
        var is_mut = false;
        var is_local_var = if (prev_spec) |ps| ps.is_local_var else false;
        var is_builder_param = if (prev_spec) |ps| ps.is_builder else false;
        var is_comptime_param = false;
        var is_local_param = false;
        var has_amp = false;
        var is_self_param = false;
        var mode: ParamMode = .let_mode;
        var colon_pos: ?usize = null;

        var cur = cst_start + 1;
        while (cur < cst_end) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .attribute) {
                const attr_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), cst_end);
                var attr_cur = cur + 1;
                while (attr_cur < attr_end) : (attr_cur += 1) {
                    const attr_leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(attr_cur)));
                    if (attr_leaf.subtree_size > 1 or attr_leaf.token.isNone() or
                        attr_leaf.token.asInt() >= self.token_buffer.countTokens()) continue;
                    const attr_kind = self.token_buffer.getToken(attr_leaf.token).kind;
                    if (symbol_resolver.isIdentifierToken(attr_kind)) {
                        const attr_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, attr_leaf.token);
                        if (std.mem.eql(u8, attr_lex, "local")) is_local_param = true;
                        if (std.mem.eql(u8, attr_lex, "builder")) is_builder_param = true;
                        break;
                    }
                }
                if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                continue;
            }
            const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
            if (!is_leaf or sub.flags.is_missing_or_injected or sub.token.isNone()) continue;
            if (sub.token.asInt() >= self.token_buffer.countTokens()) continue;
            const tok_kind = self.token_buffer.getToken(sub.token).kind;
            if (tok_kind == .colon) {
                colon_pos = cur;
                break;
            }
            if (tok_kind == .kw_comptime) {
                is_comptime_param = true;
            } else if (tok_kind == .kw_var) {
                is_local_var = true;
                is_mut = true;
            } else if (tok_kind == .amp) {
                has_amp = true;
            } else if (tok_kind == .kw_mut) {
                is_mut = true;
                if (!has_amp) mode = .inout_mode;
            } else if (tok_kind == .kw_own) {
                mode = .sink_mode;
            } else if (name_tok.isNone() and
                (symbol_resolver.isIdentifierToken(tok_kind) or
                    tok_kind == .kw_self_val or
                    tok_kind == .underscore))
            {
                name_tok = sub.token;
                if (tok_kind == .kw_self_val) is_self_param = true;
            }
        }

        if (is_local_var) is_mut = true;

        if (is_comptime_param and ordinal < 64 and !fn_sym_idx.isNone()) {
            self.sym_table.getSymbolMut(fn_sym_idx).is_comptime_param_mask |= (@as(u64, 1) << @intCast(ordinal));
        }

        // Locate direct top-level `=` default delimiter inside `.fn_param` (`SE-07`):
        var eq_pos: ?usize = null;
        var eq_scan = if (colon_pos) |c_pos| c_pos + 1 else cst_start + 1;
        while (eq_scan < cst_end) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(eq_scan)));
            const step: usize = @max(@as(usize, sub.subtree_size), 1);
            if (step == 1 and !sub.flags.is_bracketed and !sub.flags.is_missing_or_injected and
                !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(sub.token).kind == .eq)
            {
                eq_pos = eq_scan;
                break;
            }
            eq_scan += step;
        }

        const ty_search_start = if (colon_pos) |c_pos| c_pos + 1 else cst_start + 1;
        const ty_search_end = eq_pos orelse cst_end;
        const ty_ast = self.findFirstAstInCstRange(ty_search_start, ty_search_end);
        const default_ast: NodeIndex = if (eq_pos) |ep| self.findFirstAstInCstRange(ep + 1, cst_end) else .none;

        var is_caller_loc_default = if (prev_spec) |ps| ps.is_caller_location_default else false;
        if (!is_caller_loc_default and !default_ast.isNone()) {
            const def_node = self.ast_arena.getNode(default_ast);
            if ((def_node.tag == .call_expr or def_node.tag == .generic_call) and def_node.lhs.tag == .node) {
                const callee_n = self.ast_arena.getNode(NodeIndex.fromInt(def_node.lhs.payload));
                if (callee_n.tag == .ident_expr and !callee_n.main_token.isNone() and
                    self.token_buffer.getToken(callee_n.main_token).kind == .at and callee_n.lhs.tag == .token)
                {
                    const intr_lex = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        TokenIndex.fromInt(callee_n.lhs.payload),
                    );
                    if (std.mem.eql(u8, intr_lex, "caller_location")) {
                        is_caller_loc_default = true;
                    }
                }
            }
        }

        if (colon_pos) |c_pos| {
            // Check for `@builder` attribute inside the type position (`children: @builder |&mut Scope|`):
            var attr_scan = c_pos + 1;
            while (attr_scan < ty_search_end) : (attr_scan += 1) {
                const a_sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(attr_scan)));
                if (a_sub.kind == .attribute) {
                    const a_end = @min(attr_scan + @max(@as(usize, a_sub.subtree_size), 1), ty_search_end);
                    var a_cur = attr_scan + 1;
                    while (a_cur < a_end) : (a_cur += 1) {
                        const a_leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(a_cur)));
                        if (a_leaf.subtree_size <= 1 and !a_leaf.token.isNone() and
                            a_leaf.token.asInt() < self.token_buffer.countTokens() and
                            symbol_resolver.isIdentifierToken(self.token_buffer.getToken(a_leaf.token).kind))
                        {
                            if (std.mem.eql(u8, symbol_resolver.extractTokenSlice(self.source, self.token_buffer, a_leaf.token), "builder")) {
                                is_builder_param = true;
                            }
                            break;
                        }
                    }
                    if (a_sub.subtree_size > 1) attr_scan += @as(usize, a_sub.subtree_size) - 1;
                }
            }

            const mode_scan_end = if (!ty_ast.isNone() and !self.ast_arena.getCstOrigin(ty_ast).isNone())
                @min(@as(usize, self.ast_arena.getCstOrigin(ty_ast).asInt()), ty_search_end)
            else
                ty_search_end;
            var mode_cur = c_pos + 1;
            while (mode_cur < mode_scan_end) : (mode_cur += 1) {
                const mode_sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(mode_cur)));
                if (mode_sub.subtree_size > 1 or mode_sub.flags.is_bracketed or
                    mode_sub.flags.is_missing_or_injected or mode_sub.token.isNone() or
                    mode_sub.token.asInt() >= self.token_buffer.countTokens())
                {
                    continue;
                }
                const m_kind = self.token_buffer.getToken(mode_sub.token).kind;
                const m_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, mode_sub.token);
                if (m_kind == .kw_own or std.mem.eql(u8, m_lex, "sink")) {
                    mode = .sink_mode;
                } else if (std.mem.eql(u8, m_lex, "inout")) {
                    mode = .inout_mode;
                    is_mut = true;
                } else if (std.mem.eql(u8, m_lex, "set")) {
                    mode = .set_mode;
                    is_mut = true;
                } else if (m_kind == .kw_let) {
                    mode = .let_mode;
                }
            }
        }
        if (!ty_ast.isNone() and self.ast_arena.getNode(ty_ast).tag == .mode_type) {
            const m_tok = self.ast_arena.getNode(ty_ast).main_token;
            if (!m_tok.isNone() and m_tok.asInt() < self.token_buffer.countTokens()) {
                const m_kind = self.token_buffer.getToken(m_tok).kind;
                const m_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, m_tok);
                if (m_kind == .kw_own or std.mem.eql(u8, m_lex, "sink")) {
                    mode = .sink_mode;
                } else if (std.mem.eql(u8, m_lex, "inout")) {
                    mode = .inout_mode;
                    is_mut = true;
                } else if (std.mem.eql(u8, m_lex, "set")) {
                    mode = .set_mode;
                    is_mut = true;
                }
            }
        }
        var param_ty: TypeId = .unit_ty;
        if (!ty_ast.isNone() and isTypeAstTag(self.ast_arena.getNode(ty_ast).tag)) {
            param_ty = try self.resolveTypeAst(ty_ast);
        } else if (is_self_param) {
            const self_type_sym = try self.interner.intern("Self");
            switch (self.sym_table.lookupLexical(fn_scope, self_type_sym, NamespaceMask.TYPE_ONLY)) {
                .found => |found_self_idx| {
                    const base_self_ty = self.sym_table.getSymbol(found_self_idx).type_id;
                    param_ty = if (has_amp and !base_self_ty.isError())
                        try self.pool.internRef(base_self_ty, is_mut)
                    else
                        base_self_ty;
                },
                else => {},
            }
        }

        if (self.pool.isOutRef(param_ty)) {
            mode = .set_mode;
        } else if (self.pool.getTag(param_ty) == .closure_ty and
            (if (self.pool.getFnSignatureView(param_ty)) |cl_sig| cl_sig.capture_tier != .copy_tier else false))
        {
            mode = .sink_mode;
        }

        const param_decl_span = if (!name_tok.isNone())
            self.token_buffer.getTokenSpan(self.file_id, name_tok)
        else if (!ty_ast.isNone())
            self.getAstNodeSpan(ty_ast)
        else
            Span.init(self.file_id, 0, 0);

        const param_tag = self.pool.getTag(param_ty);
        if (is_local_var and (param_tag == .ref_ty or param_tag == .mut_ref_ty or has_amp)) {
            try self.emitDiagnosticSimple(
                .e0421_non_copy_value_parameter,
                param_decl_span,
                "`var` parameter modifier is only permitted on by-value `Copy` or `own` parameters, not references",
                "remove `var` from reference parameter binding",
            );
        }

        // Enforce `ADR-22B` `E0421`: bare by-value `x: T` requires `T: Copy` (Pass-1 `fn_sym`s are checked in `verifyAllPass1FnParamModes`):
        const is_fn_extern = !fn_sym_idx.isNone() and self.sym_table.getSymbol(fn_sym_idx).flags.is_extern;
        const is_fn_test = !fn_sym_idx.isNone() and self.sym_table.getSymbol(fn_sym_idx).extra_flags.is_test;
        if (self.has_completed_pass1 and mode == .let_mode and !is_fn_extern and !is_fn_test and !is_comptime_param and
            !param_ty.isError() and param_tag != .ref_ty and param_tag != .mut_ref_ty and
            param_tag != .raw_ptr_ty and param_tag != .slice_ty and param_tag != .soa_slice_ty and
            param_tag != .fn_ty and
            param_tag != .bind_once_group_var and param_tag != .bind_many_any_var)
        {
            if (!self.isCopyType(param_ty)) {
                var ty_buf: [96]u8 = undefined;
                const ty_str = self.pool.formatType(param_ty, self.sym_table, &ty_buf);
                const pname = if (!name_tok.isNone())
                    symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok)
                else
                    "x";
                var msg_buf: [240]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "by-value parameter `{s}: {s}` requires `{s}: Copy`; borrow as `{s}: &{s}` or move as `{s}: own {s}`",
                    .{ pname, ty_str, ty_str, pname, ty_str, pname, ty_str },
                ) catch "non-`Copy` parameter cannot be passed bare by value; use `&T` or `own T`";
                try self.emitDiagnosticSimple(
                    .e0421_non_copy_value_parameter,
                    param_decl_span,
                    msg,
                    "help: write `&T` to borrow or `own T` to transfer ownership",
                );
            }
        }

        const owner_def: DefId = if (!fn_sym_idx.isNone())
            self.sym_table.getSymbol(fn_sym_idx).def_id
        else
            .NONE;
        var param_name_sym: SymbolId = .none;
        var param_name_text: []const u8 = "";

        if (!name_tok.isNone()) {
            const name_str = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok);
            if (name_str.len > 0 and !std.mem.eql(u8, name_str, "_")) {
                param_name_sym = try self.interner.intern(name_str);
                param_name_text = self.interner.get(param_name_sym);
                const param_sym_idx = try self.sym_table.defineSymbol(.{
                    .name = param_name_sym,
                    .name_text = param_name_text,
                    .kind = .param_sym,
                    .namespace = .value_ns,
                    .visibility = .private,
                    .flags = .{ .is_mut = is_mut and !has_amp, .is_comptime = is_comptime_param },
                    .scope_id = fn_scope,
                    .cst_node = CstNodeIndex.fromInt(@intCast(cst_start)),
                    .decl_span = self.token_buffer.getTokenSpan(self.file_id, name_tok),
                    .type_id = param_ty,
                    .member_ordinal = ordinal,
                    .contract_flags = .{ .is_local_only = is_local_param or is_builder_param },
                }, self.diagnostic_sink);
                try self.validateSymbolAttributes(param_sym_idx, owner_def);
            }
        }
        return .{
            .ty = param_ty,
            .mode = mode,
            .spec = .{
                .name = param_name_sym,
                .name_text = param_name_text,
                .has_default = (eq_pos != null and (!default_ast.isNone() or is_caller_loc_default)),
                .is_positional_only = if (prev_spec) |ps| ps.is_positional_only else false,
                .is_keyword_only = if (prev_spec) |ps| ps.is_keyword_only else false,
                .is_local_var = is_local_var,
                .is_builder = is_builder_param,
                .is_caller_location_default = is_caller_loc_default,
                .default_ast_node = default_ast,
                .decl_file_id = self.file_id,
                .owner_def_id = owner_def,
            },
        };
    }

    // -------------------- Type AST Resolution ---------------------

    /// Resolves a type expression AST node into its canonical `TypeId` in `self.pool`.
    pub fn resolveTypeAst(self: *TypeChecker, type_node_id: NodeIndex) anyerror!TypeId {
        if (type_node_id.isNone() or type_node_id.asInt() >= self.ast_arena.countNodes()) return .err_ty;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return self.recordNodeType(type_node_id, .err_ty);
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const ast_node = self.ast_arena.getNode(type_node_id);
        const allow_opaque_here = self.is_allowing_opaque_type;
        self.is_allowing_opaque_type = false;

        const resolved: TypeId = switch (ast_node.tag) {
            .type_hole => .err_ty,
            .prim_type => blk: {
                const lexeme = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    ast_node.main_token,
                );
                if (symbol_resolver.BUILTIN_TYPE_AND_GROUP_MAP.get(lexeme)) |builtin_ty| {
                    if (builtin_ty == .opaque_ty and !allow_opaque_here) {
                        try self.emitDiagnosticSimple(
                            .e0425_invalid_opaque_type_usage,
                            self.getAstNodeSpan(type_node_id),
                            "`opaque` is unsized and may only appear behind a raw pointer (`*opaque` or `*mut opaque`)",
                            "use `*opaque` or `*mut opaque` instead of bare `opaque`",
                        );
                        break :blk .err_ty;
                    }
                    if (!builtin_ty.isBuiltinGroup()) break :blk builtin_ty;
                }
                break :blk .err_ty;
            },
            .optional_type => blk: {
                if (ast_node.lhs.tag != .node) break :blk .err_ty;
                const inner_ty = try self.resolveTypeAst(NodeIndex.fromInt(ast_node.lhs.payload));
                break :blk try self.pool.internOptional(inner_ty);
            },
            .result_type => blk: {
                if (ast_node.lhs.tag != .node or ast_node.rhs.tag != .node) break :blk .err_ty;
                const ok_ty = try self.resolveTypeAst(NodeIndex.fromInt(ast_node.lhs.payload));
                const err_ast_id = NodeIndex.fromInt(ast_node.rhs.payload);
                const err_ty = try self.resolveTypeAst(err_ast_id);
                if (!err_ty.isError()) {
                    const err_tag = self.pool.getTag(err_ty);
                    if (err_ty.isBuiltinGroup() or err_tag == .builtin_group or err_tag == .user_group or
                        err_tag == .bind_once_group_var or err_tag == .bind_many_any_var)
                    {
                        try self.emitDiagnosticSimple(
                            .e0427_invalid_error_composition,
                            self.getAstNodeSpan(err_ast_id),
                            "error operand `E` of `T!E` must be a concrete runtime error type, not a Constrained Type Group",
                            "use a concrete `enum` or `struct` error type",
                        );
                        break :blk .err_ty;
                    }
                }
                break :blk try self.pool.internResult(ok_ty, err_ty);
            },
            .ref_type => blk: {
                if (ast_node.lhs.tag != .node) break :blk .err_ty;
                const inner_ty = try self.resolveTypeAst(NodeIndex.fromInt(ast_node.lhs.payload));
                const main_lex = if (!ast_node.main_token.isNone() and
                    ast_node.main_token.asInt() < self.token_buffer.countTokens())
                    symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ast_node.main_token)
                else
                    "";
                if (std.mem.eql(u8, main_lex, "out")) {
                    break :blk try self.pool.internOutRef(inner_ty);
                }
                const is_mut = self.hasMutKeywordInCst(self.ast_arena.getCstOrigin(type_node_id));
                break :blk try self.pool.internRef(inner_ty, is_mut);
            },
            .ptr_type => blk: {
                if (ast_node.lhs.tag != .node) break :blk .err_ty;
                const inner_ast_id = NodeIndex.fromInt(ast_node.lhs.payload);
                const inner_tag = self.ast_arena.getNode(inner_ast_id).tag;
                if (inner_tag == .prim_type or inner_tag == .named_type or inner_tag == .ptr_type) {
                    self.is_allowing_opaque_type = true;
                }
                const inner_ty = resolve_ptr_inner: {
                    defer self.is_allowing_opaque_type = false;
                    break :resolve_ptr_inner try self.resolveTypeAst(inner_ast_id);
                };
                const is_mut = self.hasMutKeywordInCst(self.ast_arena.getCstOrigin(type_node_id));
                break :blk try self.pool.internRawPtr(inner_ty, is_mut);
            },
            .slice_type => blk: {
                if (ast_node.lhs.tag != .node) break :blk .err_ty;
                const elem_ty = try self.resolveTypeAst(NodeIndex.fromInt(ast_node.lhs.payload));
                break :blk try self.pool.internSlice(elem_ty, false);
            },
            .array_type => blk: {
                if (ast_node.lhs.tag != .node) break :blk .err_ty;
                const elem_ty = try self.resolveTypeAst(NodeIndex.fromInt(ast_node.lhs.payload));
                if (ast_node.rhs.tag != .node) {
                    break :blk try self.pool.internArray(elem_ty, 0, false);
                }
                const len_expr_id = NodeIndex.fromInt(ast_node.rhs.payload);

                // Check for symbolic `[const N: usize]` generic array length (`[T; N]`):
                if (try self.findConstParamInExpr(len_expr_id, 0)) |const_param_sym_idx| {
                    self.pure_comptime_depth += 1;
                    defer self.pure_comptime_depth -= 1;
                    _ = try self.synthExpr(len_expr_id);
                    if (self.ast_arena.getNode(len_expr_id).tag != .ident_expr) {
                        try self.emitDiagnosticSimple(
                            .e0503_forbidden_comptime_operation,
