                    const grp_sym_id = try self.interner.intern(lexeme);
                    if (self.active_bind_once_vars.get(grp_sym_id.asInt())) |existing_var| {
                        break :blk existing_var;
                    }
                    const bind_once_var = try self.pool.internBindOnceVar(raw_ty, grp_sym_id);
                    try self.active_bind_once_vars.put(self.allocator, grp_sym_id.asInt(), bind_once_var);
                    break :blk bind_once_var;
                }
                break :blk raw_ty;
            },
            .generic_type => blk: {
                const name_lexeme = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    ast_node.main_token,
                );
                const arg_slice: []const u32 = if (ast_node.lhs.tag == .extra and ast_node.rhs.tag == .extra)
                    self.ast_arena.getExtraSlice(ExtraIndex.fromInt(ast_node.lhs.payload), ast_node.rhs.payload)
                else
                    &.{};

                if (std.mem.eql(u8, name_lexeme, "Result")) {
                    const ok_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .unit_ty;
                    const err_ty_arg = if (arg_slice.len >= 2) blk_err: {
                        const err_node_id = NodeIndex.fromInt(arg_slice[1]);
                        const resolved_err = try self.resolveTypeAst(err_node_id);
                        if (!resolved_err.isError()) {
                            const err_tag = self.pool.getTag(resolved_err);
                            if (resolved_err.isBuiltinGroup() or err_tag == .builtin_group or err_tag == .user_group) {
                                try self.emitDiagnosticSimple(
                                    .e0427_invalid_error_composition,
                                    self.getAstNodeSpan(err_node_id),
                                    "error argument `E` of `Result[T, E]` must be a concrete runtime error type",
                                    "use a concrete `enum` or `struct` error type",
                                );
                                break :blk_err .err_ty;
                            }
                        }
                        break :blk_err resolved_err;
                    } else .err_ty;
                    break :blk try self.pool.internResult(ok_ty, err_ty_arg);
                }
                if (std.mem.eql(u8, name_lexeme, "Option")) {
                    const payload_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .unit_ty;
                    break :blk try self.pool.internOptional(payload_ty);
                }
                if (std.mem.eql(u8, name_lexeme, "TaskGroup")) {
                    const err_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .never_ty;
                    break :blk try self.pool.internTaskGroup(err_ty);
                }
                if (std.mem.eql(u8, name_lexeme, "TaskHandle")) {
                    const val_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .unit_ty;
                    break :blk try self.pool.internTaskHandle(val_ty);
                }
                if (std.mem.eql(u8, name_lexeme, "Future")) {
                    const out_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .unit_ty;
                    break :blk try self.pool.internFuture(out_ty, 0);
                }

                const base_ty = try self.resolveNamedOrGroupTypeRaw(type_node_id);
                const resolved_base_sym = self.last_resolved_type_sym;
                if (base_ty == .task_group_base_ty) {
                    const err_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .never_ty;
                    break :blk try self.pool.internTaskGroup(err_ty);
                }
                if (base_ty == .task_handle_base_ty) {
                    const val_ty = if (arg_slice.len >= 1)
                        try self.resolveTypeAst(NodeIndex.fromInt(arg_slice[0]))
                    else
                        .unit_ty;
                    break :blk try self.pool.internTaskHandle(val_ty);
                }
                if (base_ty.isError()) break :blk .err_ty;

                var base_sym_idx = if (!resolved_base_sym.isNone())
                    resolved_base_sym
                else
                    (self.sym_table.type_to_symbol.get(base_ty.toU32()) orelse .none);
                if (!base_sym_idx.isNone()) {
                    const candidate_sym = self.sym_table.getSymbol(base_sym_idx).*;
                    if (candidate_sym.kind == .use_alias_sym and !candidate_sym.target_symbol.isNone()) {
                        base_sym_idx = candidate_sym.target_symbol;
                    }
                }
                const g_specs = if (!base_sym_idx.isNone())
                    self.sym_table.getGenericParamSpecs(base_sym_idx)
                else
                    &.{};

                var resolved_args: std.ArrayListUnmanaged(TypeId) = .empty;
                defer resolved_args.deinit(self.allocator);
                for (arg_slice, 0..) |raw_arg_ast, i| {
                    const arg_ast_id = NodeIndex.fromInt(raw_arg_ast);
                    const is_const_slot = i < g_specs.len and g_specs[i].is_const;
                    if (is_const_slot or !isTypeAstTag(self.ast_arena.getNode(arg_ast_id).tag)) {
                        self.pure_comptime_depth += 1;
                        defer self.pure_comptime_depth -= 1;
                        _ = try self.synthExpr(arg_ast_id);
                        const c_val = (try self.evalConstIntExpr(arg_ast_id, true)) orelse 0;
                        try resolved_args.append(self.allocator, try self.pool.internConstIntArg(c_val));
                    } else {
                        try resolved_args.append(self.allocator, try self.resolveTypeAst(arg_ast_id));
                    }
                }
                // Fill omitted trailing generic defaults (`SE-10A`):
                try self.appendResolvedTrailingGenericDefaults(
                    base_sym_idx,
                    &resolved_args,
                    self.getAstNodeSpan(type_node_id),
                );
                if (resolved_args.items.len == 0) break :blk base_ty;

                const base_node = self.pool.getNode(base_ty);
                const is_parameterized_alias = !base_sym_idx.isNone() and g_specs.len > 0 and
                    (self.sym_table.getSymbol(base_sym_idx).kind == .type_alias_sym or
                        (base_node.tag != .struct_ty and base_node.tag != .enum_ty and base_node.tag != .union_ty));
                if (is_parameterized_alias) {
                    const alias_sym = self.sym_table.getSymbol(base_sym_idx).*;
                    var alias_subst: NominalTypeSubst = .{};
                    if (!alias_sym.target_scope.isNone()) {
                        var arg_i: usize = 0;
                        for (self.sym_table.getScopeMembers(alias_sym.target_scope)) |mem_idx| {
                            if (arg_i >= resolved_args.items.len or alias_subst.len >= NominalTypeSubst.MAX_PARAMS) break;
                            const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                            if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError()) {
                                const arg_ty = resolved_args.items[arg_i];
                                if (arg_i < arg_slice.len and arg_i < g_specs.len and
                                    g_specs[arg_i].has_explicit_bound and
                                    !arg_ty.isError() and !self.pool.getFlags(arg_ty).has_type_vars)
                                {
                                    const grp_ty = TypeId.fromInt(self.pool.getNode(mem_sym.type_id).lhs);
                                    var sat = checkGroupSatisfaction(
                                        self.pool,
                                        self.sym_table,
                                        self.target_layout,
                                        arg_ty,
                                        grp_ty,
                                    );
                                    if (sat == .rejected and self.pool.getTag(grp_ty) == .trait_ty) {
                                        if (try self.hasTraitImplementation(arg_ty, grp_ty, 0)) sat = .matched_exact;
                                    }
                                    if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
                                        try self.emitGroupConstraintError(
                                            self.getAstNodeSpan(NodeIndex.fromInt(arg_slice[arg_i])),
                                            arg_ty,
                                            grp_ty,
                                            sat == .rejected_distinct_without_tilde,
                                        );
                                    }
                                }
                                alias_subst.keys[alias_subst.len] = mem_sym.type_id;
                                alias_subst.vals[alias_subst.len] = arg_ty;
                                alias_subst.len += 1;
                                arg_i += 1;
                            } else if (mem_sym.kind == .const_param_sym and !mem_sym.name.isNone()) {
                                alias_subst.const_syms[alias_subst.len] = mem_sym.name;
                                alias_subst.vals[alias_subst.len] = resolved_args.items[arg_i];
                                alias_subst.len += 1;
                                arg_i += 1;
                            }
                        }
                    }
                    const subst_ty = try alias_subst.applyMut(self.allocator, self.pool, base_ty);
                    if (!subst_ty.isError() and !self.pool.getFlags(subst_ty).has_type_vars) {
                        const subst_node = self.pool.getNode(subst_ty);
                        if ((subst_node.tag == .struct_ty or subst_node.tag == .enum_ty or subst_node.tag == .union_ty) and
                            self.pool.getGenericTypeArgs(subst_ty).len > 0)
                        {
                            const nom_sym_idx = SymbolIndex.fromInt(subst_node.rhs);
                            if (!nom_sym_idx.isNone()) {
                                try self.sym_table.type_to_symbol.put(self.allocator, subst_ty.toU32(), nom_sym_idx);
                                if (subst_ty.toU32() < self.pool.nodes.len) {
                                    const tier = classifyOwnershipTier(self.pool, self.sym_table, subst_ty);
                                    self.pool.nodes.items(.flags)[subst_ty.toU32()].is_copy = (tier == .copy_tier);
                                    self.pool.nodes.items(.flags)[subst_ty.toU32()].has_drop = (tier == .auto_drop_tier);
                                }
                            }
                        }
                    }
                    break :blk subst_ty;
                }
                if (base_node.tag == .struct_ty or base_node.tag == .enum_ty or base_node.tag == .union_ty) {
                    break :blk try self.internNominalWithResolvedArgs(base_ty, resolved_args.items);
                }
                break :blk base_ty;
            },
            else => .err_ty,
        };
        return self.recordNodeType(type_node_id, resolved);
    }

    /// Interns an instantiated nominal container (`base_ty[resolved_args]`) and updates its ownership flags.
    fn internNominalWithResolvedArgs(
        self: *TypeChecker,
        base_ty: TypeId,
        resolved_args: []const TypeId,
    ) !TypeId {
        if (base_ty.isError() or resolved_args.len == 0) return base_ty;
        const base_node = self.pool.getNode(base_ty);
        if (base_node.tag != .struct_ty and base_node.tag != .enum_ty and base_node.tag != .union_ty) {
            return base_ty;
        }
        const base_sym_idx = SymbolIndex.fromInt(base_node.rhs);
        const base_name = if (!base_sym_idx.isNone())
            self.sym_table.getSymbol(base_sym_idx).name_text
        else
            "";
        var has_non_copy_arg = false;
        for (resolved_args) |arg_ty| {
            if (arg_ty.isError()) return .err_ty;
            if (classifyOwnershipTier(self.pool, self.sym_table, arg_ty) != .copy_tier) {
                has_non_copy_arg = true;
            }
        }
        var provisional_is_copy = base_node.flags.is_copy and !has_non_copy_arg;
        var provisional_has_drop = base_node.flags.has_drop;
        if (COPY_BUILTIN_NOMINAL_MAP.has(base_name)) {
            provisional_is_copy = true;
            provisional_has_drop = false;
        } else if (LINEAR_BUILTIN_TYPE_MAP.has(base_name)) {
            provisional_is_copy = false;
            provisional_has_drop = false;
        } else if (AUTO_DROP_CONTAINER_MAP.has(base_name)) {
            provisional_is_copy = false;
            provisional_has_drop = true;
        }
        const inst_ty = try self.pool.internNominalInstantiation(
            base_ty,
            resolved_args,
            provisional_is_copy,
            provisional_has_drop,
        );
        if (!inst_ty.isError() and !base_sym_idx.isNone()) {
            try self.sym_table.type_to_symbol.put(self.allocator, inst_ty.toU32(), base_sym_idx);
            if (!self.pool.getFlags(inst_ty).has_type_vars and inst_ty.toU32() < self.pool.nodes.len) {
                const final_tier = classifyOwnershipTier(self.pool, self.sym_table, inst_ty);
                self.pool.nodes.items(.flags)[inst_ty.toU32()].is_copy = (final_tier == .copy_tier);
                self.pool.nodes.items(.flags)[inst_ty.toU32()].has_drop = (final_tier == .auto_drop_tier);
            }
        }
        return inst_ty;
    }

    /// Substitutes generic `.type_param` occurrences in `member_ty` using `nominal_ty`'s concrete type arguments.
    fn substituteNominalMemberType(
        self: *TypeChecker,
        nominal_ty: TypeId,
        member_ty: TypeId,
    ) !TypeId {
        if (member_ty.isPrimitiveOrSentinel() or !self.pool.getFlags(member_ty).has_type_vars) {
            return member_ty;
        }
        const nom_subst = NominalTypeSubst.init(
            self.pool,
            self.sym_table,
            self.pool.unwrapUnderlyingType(nominal_ty),
        );
        if (nom_subst.len == 0) return member_ty;
        const subst_ty = try nom_subst.applyMut(self.allocator, self.pool, member_ty);
        if (!subst_ty.isError() and !self.pool.getFlags(subst_ty).has_type_vars) {
            const subst_node = self.pool.getNode(subst_ty);
            if ((subst_node.tag == .struct_ty or subst_node.tag == .enum_ty or subst_node.tag == .union_ty) and
                self.pool.getGenericTypeArgs(subst_ty).len > 0)
            {
                const sym_idx = SymbolIndex.fromInt(subst_node.rhs);
                if (!sym_idx.isNone()) {
                    try self.sym_table.type_to_symbol.put(self.allocator, subst_ty.toU32(), sym_idx);
                    if (subst_ty.toU32() < self.pool.nodes.len) {
                        const tier = classifyOwnershipTier(self.pool, self.sym_table, subst_ty);
                        self.pool.nodes.items(.flags)[subst_ty.toU32()].is_copy = (tier == .copy_tier);
                        self.pool.nodes.items(.flags)[subst_ty.toU32()].has_drop = (tier == .auto_drop_tier);
                    }
                }
            }
        }
        return subst_ty;
    }

    /// Searches `expr_id` for a reference to a generic `.const_param_sym` or `comptime` `.param_sym`.
    fn findConstParamInExpr(
        self: *TypeChecker,
        expr_id: NodeIndex,
        depth: u32,
    ) anyerror!?SymbolIndex {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes() or depth >= MAX_TYPE_DEPTH) {
            return null;
        }
        const node = self.ast_arena.getNode(expr_id);
        switch (node.tag) {
            .ident_expr => {
                if (!node.main_token.isNone() and
                    self.token_buffer.getToken(node.main_token).kind == .at) return null;
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, node.main_token);
                if (lex.len == 0) return null;
                const sym_id = try self.interner.intern(lex);
                switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.ALL)) {
                    .found => |sym_idx| {
                        const found_sym = self.sym_table.getSymbol(sym_idx);
                        if (found_sym.kind == .const_param_sym or
                            (found_sym.kind == .param_sym and found_sym.flags.is_comptime))
                        {
                            return sym_idx;
                        }
                    },
                    else => {},
                }
                return null;
            },
            .unary_expr => {
                if (node.lhs.tag == .node) {
                    return self.findConstParamInExpr(NodeIndex.fromInt(node.lhs.payload), depth + 1);
                }
                return null;
            },
            .binary_expr => {
                if (node.lhs.tag == .node) {
                    if (try self.findConstParamInExpr(NodeIndex.fromInt(node.lhs.payload), depth + 1)) |found| {
                        return found;
                    }
                }
                if (node.rhs.tag == .node) {
                    return self.findConstParamInExpr(NodeIndex.fromInt(node.rhs.payload), depth + 1);
                }
                return null;
            },
            else => return null,
        }
    }

    /// Evaluates a compile-time constant integer or boolean AST expression to `i128` (`E0502`/`E0503`/`E0507`/`E0509`).
    pub fn evalConstIntExpr(
        self: *TypeChecker,
        expr_id: NodeIndex,
        is_emitting_diags: bool,
    ) anyerror!?i128 {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return null;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return null;
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const ast_node = self.ast_arena.getNode(expr_id);
        switch (ast_node.tag) {
            .bool_lit => {
                const is_true = !ast_node.main_token.isNone() and
                    self.token_buffer.getToken(ast_node.main_token).kind == .kw_true;
                return if (is_true) 1 else 0;
            },
            .char_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ast_node.main_token);
                if (extractCharLiteralCodepoint(lex)) |cp| return @as(i128, cp);
                return null;
            },
            .byte_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ast_node.main_token);
                if (lexer.extractByteLiteralValue(lex)) |byte_val| return @as(i128, byte_val);
                return null;
            },
            .int_lit => {
                const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ast_node.main_token);
                const parsed = extractIntLiteralValue(lex) orelse {
                    if (is_emitting_diags) {
                        try self.emitDiagnosticSimple(
                            .e0502_integer_constant_overflow,
                            self.getAstNodeSpan(expr_id),
                            "integer literal overflows 128-bit constant evaluator range",
                            "constant integer literal overflow",
                        );
                    }
                    return null;
                };
                if (parsed.is_above_i128_max) {
                    const is_checked_u128 = expr_id.asInt() < self.node_types.len and
                        self.node_types[expr_id.asInt()] == .u128_ty;
                    if (is_emitting_diags and !is_checked_u128) {
                        try self.emitDiagnosticSimple(
                            .e0502_integer_constant_overflow,
                            self.getAstNodeSpan(expr_id),
                            "constant integer exceeds signed 128-bit evaluator range",
                            "constant integer overflow",
                        );
                    }
                    return null;
                }
                return parsed.value;
            },
            .unary_expr => {
                if (ast_node.lhs.tag != .node) return null;
                const inner_id = NodeIndex.fromInt(ast_node.lhs.payload);
                const op_kind = self.token_buffer.getToken(ast_node.main_token).kind;
                if (op_kind == .kw_comptime) {
                    return self.evalConstIntExpr(inner_id, is_emitting_diags);
                }
                if (op_kind == .minus and self.ast_arena.getNode(inner_id).tag == .int_lit) {
                    const lex = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        self.ast_arena.getNode(inner_id).main_token,
                    );
                    if (extractIntLiteralValue(lex)) |parsed| {
                        const min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;
                        if (parsed.is_above_i128_max and parsed.magnitude == min_abs) {
                            return std.math.minInt(i128);
                        }
                        if (!parsed.is_above_i128_max) return -parsed.value;
                    }
                }
                const inner_val = (try self.evalConstIntExpr(inner_id, is_emitting_diags)) orelse return null;
                return switch (op_kind) {
                    .minus => std.math.negate(inner_val) catch {
                        if (is_emitting_diags) {
                            try self.emitDiagnosticSimple(
                                .e0502_integer_constant_overflow,
                                self.getAstNodeSpan(expr_id),
                                "compile-time negation overflowed",
                                "arithmetic overflow during constant evaluation",
                            );
                        }
                        return null;
                    },
                    .tilde => ~inner_val,
                    .bang, .kw_not => if (self.ast_arena.getNode(inner_id).tag == .bool_lit or
                        (inner_id.asInt() < self.node_types.len and self.node_types[inner_id.asInt()] == .bool_ty))
                        (if (inner_val == 0) @as(i128, 1) else @as(i128, 0))
                    else
                        ~inner_val,
                    else => null,
                };
            },
            .binary_expr => {
                if (ast_node.lhs.tag != .node or ast_node.rhs.tag != .node) return null;
                const lhs_id = NodeIndex.fromInt(ast_node.lhs.payload);
                const rhs_id = NodeIndex.fromInt(ast_node.rhs.payload);
                const op_kind = self.token_buffer.getToken(ast_node.main_token).kind;

                if (op_kind == .kw_and) {
                    const lhs_val = (try self.evalConstIntExpr(lhs_id, is_emitting_diags)) orelse return null;
                    if (lhs_val == 0) return 0;
                    const rhs_val = (try self.evalConstIntExpr(rhs_id, is_emitting_diags)) orelse return null;
                    return if (rhs_val != 0) 1 else 0;
                }
                if (op_kind == .kw_or) {
                    const lhs_val = (try self.evalConstIntExpr(lhs_id, is_emitting_diags)) orelse return null;
                    if (lhs_val != 0) return 1;
                    const rhs_val = (try self.evalConstIntExpr(rhs_id, is_emitting_diags)) orelse return null;
                    return if (rhs_val != 0) 1 else 0;
                }

                // String literal equality (`attr.method == "GET"`):
                if ((op_kind == .eqeq or op_kind == .bang_eq) and
                    self.ast_arena.getNode(lhs_id).tag == .string_lit and
                    self.ast_arena.getNode(rhs_id).tag == .string_lit)
                {
                    const lhs_lex = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        self.ast_arena.getNode(lhs_id).main_token,
                    );
                    const rhs_lex = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        self.ast_arena.getNode(rhs_id).main_token,
                    );
                    const is_eq = std.mem.eql(u8, lhs_lex, rhs_lex);
                    return if (op_kind == .eqeq)
                        (if (is_eq) @as(i128, 1) else @as(i128, 0))
                    else
                        (if (!is_eq) @as(i128, 1) else @as(i128, 0));
                }

                const lhs_val = (try self.evalConstIntExpr(lhs_id, is_emitting_diags)) orelse return null;
                const rhs_val = (try self.evalConstIntExpr(rhs_id, is_emitting_diags)) orelse return null;

                return switch (op_kind) {
                    .plus => std.math.add(i128, lhs_val, rhs_val) catch {
                        if (is_emitting_diags) {
                            try self.emitDiagnosticSimple(
                                .e0502_integer_constant_overflow,
                                self.getAstNodeSpan(expr_id),
                                "compile-time addition overflowed",
                                "integer overflow in constant expression",
                            );
                        }
                        return null;
                    },
                    .plus_percent => lhs_val +% rhs_val,
                    .plus_pipe => lhs_val +| rhs_val,
                    .minus => std.math.sub(i128, lhs_val, rhs_val) catch {
                        if (is_emitting_diags) {
                            try self.emitDiagnosticSimple(
                                .e0502_integer_constant_overflow,
                                self.getAstNodeSpan(expr_id),
                                "compile-time subtraction overflowed",
                                "integer overflow in constant expression",
                            );
                        }
                        return null;
                    },
                    .minus_percent => lhs_val -% rhs_val,
                    .minus_pipe => lhs_val -| rhs_val,
                    .star => std.math.mul(i128, lhs_val, rhs_val) catch {
                        if (is_emitting_diags) {
                            try self.emitDiagnosticSimple(
                                .e0502_integer_constant_overflow,
                                self.getAstNodeSpan(expr_id),
                                "compile-time multiplication overflowed",
                                "integer overflow in constant expression",
                            );
                        }
                        return null;
                    },
                    .star_percent => lhs_val *% rhs_val,
                    .star_pipe => lhs_val *| rhs_val,
                    .slash => blk: {
                        if (rhs_val == 0) {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0507_comptime_arithmetic_trap,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time division by zero",
                                    "divisor evaluated to `0` at compile time",
                                );
                            }
                            break :blk null;
                        }
                        break :blk std.math.divTrunc(i128, lhs_val, rhs_val) catch {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0502_integer_constant_overflow,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time division overflowed",
                                    "signed division overflow in constant expression",
                                );
                            }
                            break :blk null;
                        };
                    },
                    .percent => blk: {
                        if (rhs_val == 0) {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0507_comptime_arithmetic_trap,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time remainder by zero",
                                    "modulus evaluated to `0` at compile time",
                                );
                            }
                            break :blk null;
                        }
                        break :blk std.math.rem(i128, lhs_val, rhs_val) catch null;
                    },
                    .shl => blk: {
                        if (rhs_val < 0 or rhs_val >= 128) {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0507_comptime_arithmetic_trap,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time shift count out of bounds (`0..127`)",
                                    "invalid shift count at compile time",
                                );
                            }
                            break :blk null;
                        }
                        break :blk std.math.shlExact(i128, lhs_val, @intCast(rhs_val)) catch {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0502_integer_constant_overflow,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time left shift overflowed",
                                    "shifted bits overflowed constant integer width",
                                );
                            }
                            break :blk null;
                        };
                    },
                    .shr => blk: {
                        if (rhs_val < 0 or rhs_val >= 128) {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0507_comptime_arithmetic_trap,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time shift count out of bounds (`0..127`)",
                                    "invalid shift count at compile time",
                                );
                            }
                            break :blk null;
                        }
                        break :blk lhs_val >> @intCast(rhs_val);
                    },
                    .amp => lhs_val & rhs_val,
                    .pipe => lhs_val | rhs_val,
                    .caret => lhs_val ^ rhs_val,
                    .eqeq => if (lhs_val == rhs_val) 1 else 0,
                    .bang_eq => if (lhs_val != rhs_val) 1 else 0,
                    .lt => if (lhs_val < rhs_val) 1 else 0,
                    .le => if (lhs_val <= rhs_val) 1 else 0,
                    .gt => if (lhs_val > rhs_val) 1 else 0,
                    .ge => if (lhs_val >= rhs_val) 1 else 0,
                    else => null,
                };
            },
            .ident_expr, .path_expr => {
                const resolved_sym_idx = try self.lookupExprSymbolQuiet(expr_id);
                if (resolved_sym_idx.isNone()) return null;
                const sym = self.sym_table.getSymbol(resolved_sym_idx).*;
                switch (sym.kind) {
                    .const_sym => {
                        for (self.active_const_eval[0..self.active_const_eval_len]) |active_sym| {
                            if (active_sym == resolved_sym_idx) {
                                if (is_emitting_diags) {
                                    try self.emitDiagnosticSimple(
                                        .e0509_comptime_evaluation_cycle,
                                        self.getAstNodeSpan(expr_id),
                                        "cyclic compile-time constant evaluation detected",
                                        "constant depends on itself in an evaluation cycle",
                                    );
                                }
                                return null;
                            }
                        }
                        if (self.active_const_eval_len >= self.active_const_eval.len) {
                            if (is_emitting_diags) {
                                try self.emitDiagnosticSimple(
                                    .e0508_comptime_resource_limit_exceeded,
                                    self.getAstNodeSpan(expr_id),
                                    "compile-time constant dependency depth exceeded `64`",
                                    "constant evaluation chain too deep",
                                );
                            }
                            return null;
                        }
                        if (sym.decl_span.file_id != self.file_id or sym.ast_node.isNone()) return null;
                        const c_node = self.ast_arena.getNode(sym.ast_node);
                        if (c_node.rhs.tag != .node) return null;

                        self.active_const_eval[self.active_const_eval_len] = resolved_sym_idx;
                        self.active_const_eval_len += 1;
                        defer self.active_const_eval_len -= 1;

                        const saved_scope = self.current_scope;
                        self.current_scope = sym.scope_id;
                        defer self.current_scope = saved_scope;

                        return self.evalConstIntExpr(NodeIndex.fromInt(c_node.rhs.payload), is_emitting_diags);
                    },
                    .const_param_sym => return null,
                    .param_sym, .local_let_sym, .local_var_sym => {
                        if (sym.flags.is_comptime) return null;
                        if (is_emitting_diags) {
                            try self.emitDiagnosticSimple(
                                .e0503_forbidden_comptime_operation,
                                self.getAstNodeSpan(expr_id),
                                "compile-time constant expression cannot read runtime variable",
                                "non-`comptime` binding referenced in compile-time expression",
                            );
                        }
                        return null;
                    },
                    else => return null,
                }
            },
            .call_expr, .generic_call => {
                if (ast_node.lhs.tag != .node) return null;
                const callee_node = self.ast_arena.getNode(NodeIndex.fromInt(ast_node.lhs.payload));
                if (callee_node.tag != .ident_expr or callee_node.main_token.isNone() or
                    self.token_buffer.getToken(callee_node.main_token).kind != .at or
                    callee_node.lhs.tag != .token)
                {
                    return null;
                }
                const intr_name = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    TokenIndex.fromInt(callee_node.lhs.payload),
                );
                const intr_kind = INTRINSIC_NAME_MAP.get(intr_name) orelse return null;
                const raw_items = self.getNodeExtraSlice(expr_id, true);
                var type_args: [4]TypeId = undefined;
                var type_arg_count: usize = 0;
                var val_args: [4]NodeIndex = undefined;
                var val_arg_count: usize = 0;
                for (raw_items) |raw_item| {
                    const item_id = NodeIndex.fromInt(raw_item);
                    if (item_id.asInt() >= self.ast_arena.countNodes()) continue;
                    if (isTypeAstTag(self.ast_arena.getNode(item_id).tag)) {
                        if (type_arg_count < type_args.len) {
                            type_args[type_arg_count] = try self.resolveTypeAst(item_id);
                            type_arg_count += 1;
                        }
                    } else if (val_arg_count < val_args.len) {
                        val_args[val_arg_count] = item_id;
                        val_arg_count += 1;
                    }
                }

                switch (intr_kind) {
                    .size_of => {
                        if (type_arg_count != 1 or type_args[0].isError() or
                            self.pool.getFlags(type_args[0]).has_type_vars) return null;
                        return @intCast(self.computeTypeLayout(type_args[0], self.target_layout).byte_size);
                    },
                    .align_of => {
                        if (type_arg_count != 1 or type_args[0].isError() or
                            self.pool.getFlags(type_args[0]).has_type_vars) return null;
                        return @intCast(self.computeTypeLayout(type_args[0], self.target_layout).align_bytes);
                    },
                    .implements => {
                        if (type_arg_count != 2 or type_args[0].isError() or type_args[1].isError() or
                            self.pool.getFlags(type_args[0]).has_type_vars) return null;
                        return if (try self.hasTraitImplementation(type_args[0], type_args[1], 0)) 1 else 0;
                    },
                    .has_field => {
                        if (type_arg_count != 1 or val_arg_count != 1 or type_args[0].isError() or
                            self.pool.getFlags(type_args[0]).has_type_vars) return null;
                        const name_node = self.ast_arena.getNode(val_args[0]);
                        if (name_node.tag != .string_lit) return null;
                        const raw_lit = symbol_resolver.extractTokenSlice(
                            self.source,
                            self.token_buffer,
                            name_node.main_token,
                        );
                        if (raw_lit.len < 2) return null;
                        const field_name = raw_lit[1 .. raw_lit.len - 1];
                        return if (try self.hasTypeMember(type_args[0], field_name)) 1 else 0;
                    },
                    else => return null,
                }
            },
            else => return null,
        }
    }

    /// Returns `true` if `target_ty` has an accessible field or method named `member_name`.
    fn hasTypeMember(self: *TypeChecker, target_ty: TypeId, member_name: []const u8) !bool {
        const unwrapped = self.unwrapRefType(target_ty);
        const node = self.pool.getNode(unwrapped);
        if ((node.tag == .slice_ty or node.tag == .array_ty or node.tag == .soa_slice_ty or
            node.tag == .soa_array_ty or unwrapped == .str_ty) and std.mem.eql(u8, member_name, "len"))
        {
            return true;
        }
        if (node.tag == .struct_ty or node.tag == .union_ty or node.tag == .bit_field_ty or
            node.tag == .enum_ty or node.tag == .trait_ty)
        {
            const nom_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(node.rhs)).*;
            if (!nom_sym.target_scope.isNone()) {
                const sym_id = try self.interner.intern(member_name);
                switch (self.sym_table.lookupInTargetScope(
                    nom_sym.target_scope,
                    self.current_scope,
                    sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => return true,
                    else => return false,
                }
            }
        }
        return false;
    }

    /// Quietly resolves `.ident_expr` or `.path_expr` to its `SymbolIndex` without emitting diagnostics.
    fn lookupExprSymbolQuiet(self: *TypeChecker, expr_id: NodeIndex) !SymbolIndex {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.tag == .ident_expr) {
            if (!ast_node.main_token.isNone() and
                self.token_buffer.getToken(ast_node.main_token).kind == .at) return .none;
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ast_node.main_token);
            if (lex.len == 0) return .none;
            const sym_id = try self.interner.intern(lex);
            return switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.ALL)) {
                .found => |idx| idx,
                else => .none,
            };
        }
        if (ast_node.tag == .path_expr) {
            const raw_segs = self.getNodeExtraSlice(expr_id, false);
            if (raw_segs.len == 0) return .none;
            const seg_tokens = try self.allocator.alloc(TokenIndex, raw_segs.len);
            defer self.allocator.free(seg_tokens);
            for (raw_segs, 0..) |raw_tok, i| {
                seg_tokens[i] = TokenIndex.fromInt(raw_tok);
            }
            const target_scope = try symbol_resolver.resolveModulePathSegments(
                self.sym_table,
                self.interner,
                self.file_id,
                self.current_scope,
                self.current_scope,
                seg_tokens[0 .. seg_tokens.len - 1],
                self.source,
                self.token_buffer,
                null,
            );
            if (target_scope.isNone()) return .none;
            const last_lex = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                seg_tokens[seg_tokens.len - 1],
            );
            const last_sym_id = try self.interner.intern(last_lex);
            return switch (self.sym_table.lookupInTargetScope(
                target_scope,
                self.current_scope,
                last_sym_id,
                NamespaceMask.ALL,
            )) {
                .found => |idx| idx,
                else => .none,
            };
        }
        if (ast_node.tag == .field_access and ast_node.lhs.tag == .node) {
            var rev_tokens: [16]TokenIndex = undefined;
            var rev_len: usize = 0;
            var cur_id = expr_id;
            while (!cur_id.isNone() and cur_id.asInt() < self.ast_arena.countNodes() and rev_len < rev_tokens.len) {
                const cur_node = self.ast_arena.getNode(cur_id);
                if (cur_node.tag == .field_access and cur_node.lhs.tag == .node and cur_node.rhs.tag == .token) {
                    rev_tokens[rev_len] = TokenIndex.fromInt(cur_node.rhs.payload);
                    rev_len += 1;
                    cur_id = NodeIndex.fromInt(cur_node.lhs.payload);
                } else if (cur_node.tag == .ident_expr and !cur_node.main_token.isNone()) {
                    rev_tokens[rev_len] = cur_node.main_token;
                    rev_len += 1;
                    var seg_tokens: [16]TokenIndex = undefined;
                    var idx: usize = 0;
                    while (idx < rev_len) : (idx += 1) {
                        seg_tokens[idx] = rev_tokens[rev_len - 1 - idx];
                    }
                    const target_scope = try symbol_resolver.resolveModulePathSegments(
                        self.sym_table,
                        self.interner,
                        self.file_id,
                        self.current_scope,
                        self.current_scope,
                        seg_tokens[0 .. rev_len - 1],
                        self.source,
                        self.token_buffer,
                        null,
                    );
                    if (target_scope.isNone()) return .none;
                    const last_lex = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        seg_tokens[rev_len - 1],
                    );
                    const last_sym_id = try self.interner.intern(last_lex);
                    return switch (self.sym_table.lookupInTargetScope(
                        target_scope,
                        self.current_scope,
                        last_sym_id,
                        NamespaceMask.ALL,
                    )) {
                        .found => |found_idx| found_idx,
                        else => .none,
                    };
                } else {
                    break;
                }
            }
        }
        return .none;
    }

    /// Lazily populates the 8 `cx.meta` reflection mirror types, fields, variants, and methods (`DR-05` §3.3).
    pub fn ensureReflectionMirrorTypes(self: *TypeChecker) !void {
        if (self.has_reflection_mirrors and !self.mirror_type_info_ty.isError()) return;

        const meta_scope = try self.sym_table.ensureCxMetaScope(self.interner);
        const lookupMetaSym = struct {
            fn get(checker: *TypeChecker, scope: ScopeId, name: []const u8) !SymbolIndex {
                const sym_id = try checker.interner.intern(name);
                return checker.sym_table.lookupInScopeDirect(scope, sym_id, NamespaceMask.TYPE_ONLY);
            }
        }.get;

        const meta_id_sym = try lookupMetaSym(self, meta_scope, "MetaId");
        const prim_kind_sym = try lookupMetaSym(self, meta_scope, "PrimKind");
        const field_info_sym = try lookupMetaSym(self, meta_scope, "FieldInfo");
        const struct_info_sym = try lookupMetaSym(self, meta_scope, "StructInfo");
        const variant_info_sym = try lookupMetaSym(self, meta_scope, "VariantInfo");
        const enum_info_sym = try lookupMetaSym(self, meta_scope, "EnumInfo");
        const type_kind_sym = try lookupMetaSym(self, meta_scope, "TypeKind");
        const type_info_sym = try lookupMetaSym(self, meta_scope, "TypeInfo");

        // Reuse existing `InternPool` handles if another `TypeChecker` on the same `SymbolTable` populated them:
        if (!self.sym_table.getSymbol(type_info_sym).type_id.isError()) {
            self.mirror_meta_id_ty = self.sym_table.getSymbol(meta_id_sym).type_id;
            self.mirror_prim_kind_ty = self.sym_table.getSymbol(prim_kind_sym).type_id;
            self.mirror_field_info_ty = self.sym_table.getSymbol(field_info_sym).type_id;
            self.mirror_struct_info_ty = self.sym_table.getSymbol(struct_info_sym).type_id;
            self.mirror_variant_info_ty = self.sym_table.getSymbol(variant_info_sym).type_id;
            self.mirror_enum_info_ty = self.sym_table.getSymbol(enum_info_sym).type_id;
            self.mirror_type_kind_ty = self.sym_table.getSymbol(type_kind_sym).type_id;
            self.mirror_type_info_ty = self.sym_table.getSymbol(type_info_sym).type_id;
            self.has_reflection_mirrors = true;
            return;
        }

        const bindNominal = struct {
            fn run(checker: *TypeChecker, tag: TypeTag, sym_idx: SymbolIndex, ordinal_seed: u32) !TypeId {
                const tid = try checker.pool.internNominal(tag, 0xFFFF_0000 | ordinal_seed, sym_idx, true, false, false);
                checker.sym_table.getSymbolMut(sym_idx).type_id = tid;
                try checker.sym_table.type_to_symbol.put(checker.allocator, tid.toU32(), sym_idx);
                return tid;
            }
        }.run;

        const addField = struct {
            fn run(checker: *TypeChecker, scope: ScopeId, name: []const u8, ty: TypeId, ord: u16) !void {
                const field_id = try checker.interner.intern(name);
                _ = try checker.sym_table.defineSymbol(.{
                    .name = field_id,
                    .name_text = checker.interner.get(field_id),
                    .kind = .field_sym,
                    .namespace = .value_ns,
                    .visibility = .public,
                    .flags = .{ .is_pub = true, .is_used = true, .is_builtin = true },
                    .scope_id = scope,
                    .type_id = ty,
                    .member_ordinal = ord,
                }, null);
            }
        }.run;

        const addVariant = struct {
            fn run(checker: *TypeChecker, scope: ScopeId, name: []const u8, payload: TypeId, ord: u16) !void {
                const variant_id = try checker.interner.intern(name);
                _ = try checker.sym_table.defineSymbol(.{
                    .name = variant_id,
                    .name_text = checker.interner.get(variant_id),
                    .kind = .enum_variant_sym,
                    .namespace = .value_ns,
                    .visibility = .public,
                    .flags = .{ .is_pub = true, .is_used = true, .is_builtin = true },
                    .scope_id = scope,
                    .type_id = payload,
                    .member_ordinal = ord,
                }, null);
            }
        }.run;

        self.mirror_meta_id_ty = try bindNominal(self, .struct_ty, meta_id_sym, 1);
        self.mirror_prim_kind_ty = try bindNominal(self, .enum_ty, prim_kind_sym, 2);
        self.mirror_field_info_ty = try bindNominal(self, .struct_ty, field_info_sym, 3);
        self.mirror_struct_info_ty = try bindNominal(self, .struct_ty, struct_info_sym, 4);
        self.mirror_variant_info_ty = try bindNominal(self, .struct_ty, variant_info_sym, 5);
        self.mirror_enum_info_ty = try bindNominal(self, .struct_ty, enum_info_sym, 6);
        self.mirror_type_kind_ty = try bindNominal(self, .enum_ty, type_kind_sym, 7);
        self.mirror_type_info_ty = try bindNominal(self, .struct_ty, type_info_sym, 8);

        // `MetaId { raw_id: u32 }`:
        try addField(self, self.sym_table.getSymbol(meta_id_sym).target_scope, "raw_id", .u32_ty, 0);

        // `PrimKind` 19 variants (`DR-05` §3.3):
        const prim_variants = [_][]const u8{
            "Bool", "I8",   "I16", "I32",  "I64",   "I128",  "Isize",
            "U8",   "U16",  "U32", "U64",  "U128",  "Usize", "F32",
            "F64",  "Char", "Str", "Unit", "Never",
        };
        const prim_scope = self.sym_table.getSymbol(prim_kind_sym).target_scope;
        for (prim_variants, 0..) |variant_name, i| {
            try addVariant(self, prim_scope, variant_name, .unit_ty, @intCast(i));
        }

        // `FieldInfo`:
        const field_info_scope = self.sym_table.getSymbol(field_info_sym).target_scope;
        try addField(self, field_info_scope, "index", .u32_ty, 0);
        try addField(self, field_info_scope, "name", .str_ty, 1);
        try addField(self, field_info_scope, "ty_id", self.mirror_meta_id_ty, 2);
        try addField(self, field_info_scope, "byte_offset", .usize_ty, 3);
        try addField(self, field_info_scope, "is_pub", .bool_ty, 4);
        try addField(self, field_info_scope, "has_default", .bool_ty, 5);

        // `FieldInfo.get_attr[A](&self) -> A?`:
        const get_attr_fn_scope = try self.sym_table.scope_arena.allocScope(
            .fn_scope,
            field_info_scope,
            .NONE,
            .none,
            .{ .is_comptime_context = true },
        );
        const attr_param_sym_id = try self.interner.intern("A");
        const attr_type_param = try self.pool.internTypeParam(.group_copy, attr_param_sym_id);
        _ = try self.sym_table.defineSymbol(.{
            .name = attr_param_sym_id,
            .name_text = self.interner.get(attr_param_sym_id),
            .kind = .type_param_sym,
            .namespace = .type_ns,
            .visibility = .private,
            .flags = .{ .is_used = true, .is_builtin = true },
            .scope_id = get_attr_fn_scope,
            .type_id = attr_type_param,
        }, null);
        const field_info_ref_ty = try self.pool.internRef(self.mirror_field_info_ty, false);
        const opt_attr_ty = try self.pool.internOptional(attr_type_param);
        const get_attr_fn_ty = try self.pool.internFn(
            .fn_ty,
            &[_]TypeId{field_info_ref_ty},
            &[_]ParamMode{.let_mode},
            opt_attr_ty,
            false,
        );
        const get_attr_id = try self.interner.intern("get_attr");
        _ = try self.sym_table.defineSymbol(.{
            .name = get_attr_id,
            .name_text = self.interner.get(get_attr_id),
            .kind = .fn_sym,
            .namespace = .value_ns,
            .visibility = .public,
            .flags = .{
                .is_pub = true,
                .is_used = true,
                .is_builtin = true,
                .is_prototype_only = true,
                .is_comptime = true,
            },
            .scope_id = field_info_scope,
            .target_scope = get_attr_fn_scope,
            .type_id = get_attr_fn_ty,
        }, null);

        // `StructInfo`:
        const field_slice_ty = try self.pool.internSlice(self.mirror_field_info_ty, false);
        const struct_info_scope = self.sym_table.getSymbol(struct_info_sym).target_scope;
        try addField(self, struct_info_scope, "fields", field_slice_ty, 0);
        try addField(self, struct_info_scope, "is_repr_c", .bool_ty, 1);
        try addField(self, struct_info_scope, "is_soa_compatible", .bool_ty, 2);

        // `VariantInfo`:
        const variant_info_scope = self.sym_table.getSymbol(variant_info_sym).target_scope;
        try addField(self, variant_info_scope, "index", .u32_ty, 0);
        try addField(self, variant_info_scope, "name", .str_ty, 1);
        try addField(self, variant_info_scope, "discriminant", .i128_ty, 2);
        try addField(self, variant_info_scope, "fields", field_slice_ty, 3);

        // `EnumInfo`:
        const variant_slice_ty = try self.pool.internSlice(self.mirror_variant_info_ty, false);
        const enum_info_scope = self.sym_table.getSymbol(enum_info_sym).target_scope;
        try addField(self, enum_info_scope, "tag_ty", self.mirror_prim_kind_ty, 0);
        try addField(self, enum_info_scope, "variants", variant_slice_ty, 1);
        try addField(self, enum_info_scope, "is_niche_optimized", .bool_ty, 2);

        // `TypeKind`:
        const type_kind_scope = self.sym_table.getSymbol(type_kind_sym).target_scope;
        const arr_tup_ty = try self.pool.internTuple(&[_]TypeId{ self.mirror_meta_id_ty, .usize_ty });
        const res_tup_ty = try self.pool.internTuple(&[_]TypeId{ self.mirror_meta_id_ty, self.mirror_meta_id_ty });
        const ptr_tup_ty = try self.pool.internTuple(&[_]TypeId{ self.mirror_meta_id_ty, .bool_ty });
        const bf_tup_ty = try self.pool.internTuple(&[_]TypeId{ self.mirror_meta_id_ty, .u16_ty });
        try addVariant(self, type_kind_scope, "Primitive", self.mirror_prim_kind_ty, 0);
        try addVariant(self, type_kind_scope, "Struct", self.mirror_struct_info_ty, 1);
        try addVariant(self, type_kind_scope, "Enum", self.mirror_enum_info_ty, 2);
        try addVariant(self, type_kind_scope, "Array", arr_tup_ty, 3);
        try addVariant(self, type_kind_scope, "Slice", self.mirror_meta_id_ty, 4);
        try addVariant(self, type_kind_scope, "Option", self.mirror_meta_id_ty, 5);
        try addVariant(self, type_kind_scope, "Result", res_tup_ty, 6);
        try addVariant(self, type_kind_scope, "Pointer", ptr_tup_ty, 7);
        try addVariant(self, type_kind_scope, "SoaSlice", self.mirror_meta_id_ty, 8);
        try addVariant(self, type_kind_scope, "BitField", bf_tup_ty, 9);

        // `TypeInfo` + `as_struct` / `as_enum`:
        const type_info_scope = self.sym_table.getSymbol(type_info_sym).target_scope;
        try addField(self, type_info_scope, "id", self.mirror_meta_id_ty, 0);
        try addField(self, type_info_scope, "name", .str_ty, 1);
        try addField(self, type_info_scope, "qualified_name", .str_ty, 2);
        try addField(self, type_info_scope, "size", .usize_ty, 3);
        try addField(self, type_info_scope, "alignment", .usize_ty, 4);
        try addField(self, type_info_scope, "kind", self.mirror_type_kind_ty, 5);

        const type_info_ref_ty = try self.pool.internRef(self.mirror_type_info_ty, false);
        const as_struct_ty = try self.pool.internFn(
            .fn_ty,
            &[_]TypeId{type_info_ref_ty},
            &[_]ParamMode{.let_mode},
            self.mirror_struct_info_ty,
            false,
        );
        const as_struct_id = try self.interner.intern("as_struct");
        _ = try self.sym_table.defineSymbol(.{
            .name = as_struct_id,
            .name_text = self.interner.get(as_struct_id),
            .kind = .fn_sym,
            .namespace = .value_ns,
            .visibility = .public,
            .flags = .{
                .is_pub = true,
                .is_used = true,
                .is_builtin = true,
                .is_prototype_only = true,
                .is_comptime = true,
            },
            .scope_id = type_info_scope,
            .type_id = as_struct_ty,
        }, null);

        const as_enum_ty = try self.pool.internFn(
            .fn_ty,
            &[_]TypeId{type_info_ref_ty},
            &[_]ParamMode{.let_mode},
            self.mirror_enum_info_ty,
            false,
        );
        const as_enum_id = try self.interner.intern("as_enum");
        _ = try self.sym_table.defineSymbol(.{
            .name = as_enum_id,
            .name_text = self.interner.get(as_enum_id),
            .kind = .fn_sym,
            .namespace = .value_ns,
            .visibility = .public,
            .flags = .{
                .is_pub = true,
                .is_used = true,
                .is_builtin = true,
                .is_prototype_only = true,
                .is_comptime = true,
            },
            .scope_id = type_info_scope,
            .type_id = as_enum_ty,
        }, null);

        self.has_reflection_mirrors = true;
    }

    /// Resolves a `.named_type` AST node to its underlying `SymbolRecord.type_id` without wrapping in `bind_once_group_var`.
    fn resolveNamedOrGroupTypeRaw(self: *TypeChecker, type_node_id: NodeIndex) !TypeId {
        self.last_resolved_type_sym = .none;
        const ast_node = self.ast_arena.getNode(type_node_id);
        const type_cst = self.ast_arena.getCstOrigin(type_node_id);

        // Check if `type_cst` has leading `module.` path segments:
        var seg_tokens: std.ArrayListUnmanaged(TokenIndex) = .empty;
        defer seg_tokens.deinit(self.allocator);
        if (!type_cst.isNone() and type_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = type_cst.asInt();
            const rec = self.cst_arena.getNode(type_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.kind == .type_args and sub.subtree_size > 1) break;
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (is_leaf and !sub.flags.is_missing_or_injected and
                    !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const kind = self.token_buffer.getToken(sub.token).kind;
                    if (symbol_resolver.isIdentifierToken(kind) or kind == .kw_self_type or
                        kind == .prim_type or kind == .kw_async)
                    {
                        try seg_tokens.append(self.allocator, sub.token);
                    }
                }
            }
        }
        const seg_count = seg_tokens.items.len;

        const target_tok = if (seg_count > 0) seg_tokens.items[seg_count - 1] else ast_node.main_token;
        const target_lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, target_tok);
        if (target_lexeme.len == 0) return .err_ty;

        if (seg_count <= 1) {
            if (symbol_resolver.BUILTIN_TYPE_AND_GROUP_MAP.get(target_lexeme)) |builtin_ty| {
                return builtin_ty;
            }
        } else {
            const root_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, seg_tokens.items[0]);
            if (std.mem.eql(u8, root_lex, "cx") or
                (std.mem.eql(u8, root_lex, "core") and self.sym_table.isCoreAllowedForFile(self.file_id)))
            {
                if (symbol_resolver.BUILTIN_TYPE_AND_GROUP_MAP.get(target_lexeme)) |builtin_ty| {
                    if (builtin_ty.toU32() >= TypeId.source_loc_ty.toU32() and
                        builtin_ty.toU32() <= TypeId.task_handle_base_ty.toU32())
                    {
                        return builtin_ty;
                    }
                }
            }
        }

        if (REFLECTION_MIRROR_NAME_MAP.has(target_lexeme)) {
            try self.ensureReflectionMirrorTypes();
        }

        const target_sym_id = try self.interner.intern(target_lexeme);
        const target_span = self.token_buffer.getTokenSpan(self.file_id, target_tok);

        const lookup_scope = if (seg_count > 1)
            try symbol_resolver.resolveModulePathSegments(
                self.sym_table,
                self.interner,
                self.file_id,
                self.current_scope,
                self.current_scope,
                seg_tokens.items[0 .. seg_count - 1],
                self.source,
                self.token_buffer,
                self.diagnostic_sink,
            )
        else
            self.current_scope;

        if (lookup_scope.isNone()) return .err_ty;

        const lookup_res = if (seg_count <= 1)
            self.sym_table.lookupLexical(lookup_scope, target_sym_id, NamespaceMask.TYPE_ONLY)
        else
            self.sym_table.lookupInTargetScope(
                lookup_scope,
                self.current_scope,
                target_sym_id,
                NamespaceMask.TYPE_ONLY,
            );

        switch (lookup_res) {
            .found => |sym_idx| {
                defer self.last_resolved_type_sym = sym_idx;
                self.sym_table.markSymbolUsed(sym_idx);
                const sym = self.sym_table.getSymbol(sym_idx);
                if (sym.type_id.isError() and sym.kind == .trait_sym) {
                    return self.ensureTraitSymbolTypeId(sym_idx);
                }
                if (sym.type_id.isError() and
                    (sym.kind == .struct_sym or sym.kind == .enum_sym) and
                    sym.flags.is_builtin)
                {
                    if (REFLECTION_MIRROR_NAME_MAP.has(sym.name_text)) {
                        try self.ensureReflectionMirrorTypes();
                        return self.sym_table.getSymbol(sym_idx).type_id;
                    }
                    return self.ensureBuiltinStubSymbolType(sym_idx);
                }
                if (sym.type_id.isError() and
                    (sym.kind == .type_alias_sym or sym.kind == .distinct_type_sym or
                        sym.kind == .refined_type_sym or sym.kind == .type_group_sym))
                {
                    const resolved_alias = try self.resolveTypeAliasSymbol(sym_idx);
                    self.sym_table.getSymbolMut(sym_idx).type_id = resolved_alias;
                    return resolved_alias;
                }
                return sym.type_id;
            },
            .private_error => |priv_idx| {
                if (self.diagnostic_sink) |sink| {
                    try symbol_resolver.emitPrivateAccessDiagnostic(
                        sink,
                        self.sym_table.getSymbol(priv_idx),
                        target_span,
                    );
                }
                return .err_ty;
            },
            .not_found => {
                // Allow unqualified `TypeInfo` / `FieldInfo` fallback into `cx.meta` when not shadowed:
                if (seg_count <= 1 and REFLECTION_MIRROR_NAME_MAP.has(target_lexeme)) {
                    const meta_scope = try self.sym_table.ensureCxMetaScope(self.interner);
                    const meta_sym_idx = self.sym_table.lookupInScopeDirect(
                        meta_scope,
                        target_sym_id,
                        NamespaceMask.TYPE_ONLY,
                    );
                    if (!meta_sym_idx.isNone()) {
                        return self.sym_table.getSymbol(meta_sym_idx).type_id;
                    }
                }
                // Lazily synthesize built-in `Context`, `@linear` resources, `AutoDrop` containers, and `Copy` handles:
                if (seg_count <= 1) {
                    if (try self.ensureBuiltinStdNominalType(target_lexeme)) |builtin_nom_ty| {
                        return builtin_nom_ty;
                    }
                }
                if (self.diagnostic_sink) |sink| {
                    const suggestion = if (seg_count <= 1)
                        self.sym_table.suggestClosestSymbol(
                            self.current_scope,
                            target_lexeme,
                            NamespaceMask.TYPE_ONLY,
                        )
                    else
                        self.sym_table.suggestClosestInScope(
                            lookup_scope,
                            target_lexeme,
                            NamespaceMask.TYPE_ONLY,
                        );
                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                        sink,
                        self.interner,
                        target_lexeme,
                        target_span,
                        suggestion,
                    );
                }
                return .err_ty;
            },
        }
    }

    /// Lazily synthesizes built-in `Context`, `@linear` resource, `AutoDrop` container, and `Copy` handle nominals.
    fn ensureBuiltinStdNominalType(self: *TypeChecker, type_name: []const u8) anyerror!?TypeId {
        const is_context = std.mem.eql(u8, type_name, "Context");
        const is_allocator = std.mem.eql(u8, type_name, "Allocator");
        const is_linear = LINEAR_BUILTIN_TYPE_MAP.has(type_name);
        const is_auto_drop = AUTO_DROP_CONTAINER_MAP.has(type_name);
        const is_copy_handle = COPY_BUILTIN_NOMINAL_MAP.has(type_name);
        if (!is_context and !is_allocator and !is_linear and !is_auto_drop and !is_copy_handle) {
            return null;
        }

        const target_scope = self.sym_table.prelude_scope;
        if (target_scope.isNone()) return null;
        const sym_id = try self.interner.intern(type_name);
        const existing_idx = self.sym_table.lookupInScopeDirect(target_scope, sym_id, NamespaceMask.TYPE_ONLY);
        if (!existing_idx.isNone()) {
            const existing_ty = self.sym_table.getSymbol(existing_idx).type_id;
            if (!existing_ty.isError()) return existing_ty;
        }

        const member_scope = try self.sym_table.scope_arena.allocScope(
            .nominal_type_scope,
            target_scope,
            .NONE,
            .none,
            .{},
        );
        const is_copy_nom = is_allocator or is_copy_handle;
        const sym_idx = if (!existing_idx.isNone()) blk_existing: {
            self.sym_table.getSymbolMut(existing_idx).target_scope = member_scope;
            if (is_linear) self.sym_table.getSymbolMut(existing_idx).contract_flags.is_linear = true;
            break :blk_existing existing_idx;
        } else try self.sym_table.defineSymbol(.{
            .name = sym_id,
            .name_text = self.interner.get(sym_id),
            .kind = .struct_sym,
            .namespace = .type_ns,
            .visibility = .public,
            .flags = .{ .is_pub = true, .is_used = true, .is_builtin = true },
            .scope_id = target_scope,
            .target_scope = member_scope,
            .contract_flags = .{ .is_linear = is_linear },
        }, null);

        const nom_ty = try self.pool.internNominal(
            .struct_ty,
            0xFE00_0000 | (sym_idx.asInt() & 0x00FF_FFFF),
            sym_idx,
            is_copy_nom,
            false,
            false,
        );
        if (is_auto_drop and nom_ty.toU32() < self.pool.nodes.len) {
            self.pool.nodes.items(.flags)[nom_ty.toU32()].has_drop = true;
            self.pool.nodes.items(.flags)[nom_ty.toU32()].is_copy = false;
        }
        self.sym_table.getSymbolMut(sym_idx).type_id = nom_ty;
        try self.sym_table.type_to_symbol.put(self.allocator, nom_ty.toU32(), sym_idx);
        if (std.mem.eql(u8, type_name, "BumpArena")) {
            self.builtin_bump_arena_ty = nom_ty;
        }

        // Define local helper to register synthetic built-in struct fields on `owner_scope`:
        const addSyntheticField = struct {
            //! Local helper namespace for synthetic built-in `.field_sym` registration.

            /// Interns `field_name` and registers a public built-in `.field_sym` in `owner_scope`.
            fn run(
                checker: *TypeChecker,
                owner_scope: ScopeId,
                field_name: []const u8,
                field_ty: TypeId,
                ordinal: u16,
            ) !void {
                const field_id = try checker.interner.intern(field_name);
                _ = try checker.sym_table.defineSymbol(.{
                    .name = field_id,
                    .name_text = checker.interner.get(field_id),
                    .kind = .field_sym,
                    .namespace = .value_ns,
                    .visibility = .public,
                    .flags = .{ .is_pub = true, .is_used = true, .is_builtin = true },
                    .scope_id = owner_scope,
                    .type_id = field_ty,
                    .member_ordinal = ordinal,
                }, null);
            }
        }.run;

        if (is_context) {
            for (ContextFieldLayout.CANONICAL_FIELDS) |slot| {
                const slot_ty = (try self.resolveContextSeamFieldType(slot.name)) orelse .err_ty;
                try addSyntheticField(self, member_scope, slot.name, slot_ty, slot.slot_ordinal);
            }
            if (nom_ty.toU32() < self.pool.nodes.len) {
                self.pool.nodes.items(.flags)[nom_ty.toU32()].is_copy = false;
            }
        } else if (std.mem.eql(u8, type_name, "Span16")) {
            try addSyntheticField(self, member_scope, "off", .u16_ty, 0);
            try addSyntheticField(self, member_scope, "len", .u16_ty, 1);
        } else if (std.mem.eql(u8, type_name, "SlotKey")) {
            try addSyntheticField(self, member_scope, "index", .u32_ty, 0);
            try addSyntheticField(self, member_scope, "generation", .u32_ty, 1);
        } else if (is_allocator or is_linear or is_copy_handle) {
            try addSyntheticField(self, member_scope, "_handle", .usize_ty, 0);
        } else if (is_auto_drop) {
            try addSyntheticField(self, member_scope, "_ptr", .usize_ty, 0);
            try addSyntheticField(self, member_scope, "_len", .usize_ty, 1);
            try addSyntheticField(self, member_scope, "_cap", .usize_ty, 2);
        }
        return nom_ty;
    }

    /// Lazily interns `TypeId` and variants for standalone `cx.*` built-in type stubs (`Ordering`, `File`, `Allocator`).
    fn ensureBuiltinStubSymbolType(self: *TypeChecker, sym_idx: SymbolIndex) !TypeId {
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (!sym.type_id.isError()) return sym.type_id;

        if (sym.kind == .struct_sym) {
            if (try self.ensureBuiltinStdNominalType(sym.name_text)) |std_nom_ty| {
                self.sym_table.getSymbolMut(sym_idx).type_id = std_nom_ty;
                if (self.sym_table.type_to_symbol.get(std_nom_ty.toU32())) |canon_sym_idx| {
                    const canon_sym = self.sym_table.getSymbol(canon_sym_idx).*;
                    self.sym_table.getSymbolMut(sym_idx).target_scope = canon_sym.target_scope;
                    self.sym_table.getSymbolMut(sym_idx).contract_flags = canon_sym.contract_flags;
                }
                return std_nom_ty;
            }
            const struct_scope = if (!sym.target_scope.isNone())
                sym.target_scope
            else
                try self.sym_table.scope_arena.allocScope(.nominal_type_scope, sym.scope_id, .NONE, .none, .{});
            self.sym_table.getSymbolMut(sym_idx).target_scope = struct_scope;
            const tid = try self.pool.internNominal(
                .struct_ty,
                0xFD00_0000 | (sym_idx.asInt() & 0x00FF_FFFF),
                sym_idx,
                true,
                false,
                false,
            );
            self.sym_table.getSymbolMut(sym_idx).type_id = tid;
            try self.sym_table.type_to_symbol.put(self.allocator, tid.toU32(), sym_idx);
            return tid;
        }

        const enum_scope = if (!sym.target_scope.isNone())
            sym.target_scope
        else
            try self.sym_table.scope_arena.allocScope(.nominal_type_scope, sym.scope_id, .NONE, .none, .{});
        self.sym_table.getSymbolMut(sym_idx).target_scope = enum_scope;
        const enum_ty = try self.pool.internNominal(
            .enum_ty,
            0xFD00_0000 | (sym_idx.asInt() & 0x00FF_FFFF),
            sym_idx,
            true,
            false,
            false,
        );
        self.sym_table.getSymbolMut(sym_idx).type_id = enum_ty;
        try self.sym_table.type_to_symbol.put(self.allocator, enum_ty.toU32(), sym_idx);

        if (std.mem.eql(u8, sym.name_text, "Ordering") and
            self.sym_table.getScopeMembers(enum_scope).len == 0)
        {
            const is_atomic_ordering = !sym.scope_id.isNone() and
                sym.scope_id == self.sym_table.cx_atomic_scope;
            const variants: []const []const u8 = if (is_atomic_ordering)
                &.{ "Relaxed", "Consume", "Acquire", "Release", "AcqRel", "SeqCst" }
            else
                &.{ "Less", "Equal", "Greater" };
            for (variants, 0..) |var_name, ord_idx| {
                const var_id = try self.interner.intern(var_name);
                _ = try self.sym_table.defineSymbol(.{
                    .name = var_id,
                    .name_text = self.interner.get(var_id),
                    .kind = .enum_variant_sym,
                    .namespace = .value_ns,
                    .visibility = .public,
                    .flags = .{ .is_pub = true, .is_used = true, .is_builtin = true },
                    .scope_id = enum_scope,
                    .type_id = .unit_ty,
                    .member_ordinal = @intCast(ord_idx),
                }, null);
            }
        }
        return enum_ty;
    }

    /// Resolves the canonical `TypeId` for a 10-slot `Context` field (`DR-08` §5.3, `DR-20` Seam #2, `DR-21` `SE-08`).
    pub fn resolveContextSeamFieldType(self: *TypeChecker, field_name: []const u8) anyerror!?TypeId {
        const layout = ContextFieldLayout.fromFieldName(field_name) orelse return null;
        return switch (layout.kind) {
            .allocator, .temp_allocator => (try self.ensureBuiltinStdNominalType("Allocator")) orelse .usize_ty,
            .scratch => blk: {
                const bump_ty = if (!self.builtin_bump_arena_ty.isError())
                    self.builtin_bump_arena_ty
                else
                    (try self.ensureBuiltinStdNominalType("BumpArena")) orelse .usize_ty;
                break :blk try self.pool.internArray(bump_ty, 2, false);
            },
            .rng_seed => .u64_ty,
            .trace_sink => try self.pool.internOptional(try self.pool.internRawPtr(.u8_ty, true)),
            .logger => (try self.ensureBuiltinStdNominalType("Logger")) orelse .usize_ty,
            .diagnostics => (try self.ensureBuiltinStdNominalType("DiagSink")) orelse .usize_ty,
            .cancel_token => (try self.ensureBuiltinStdNominalType("CancelToken")) orelse .usize_ty,
            .reactor => (try self.ensureBuiltinStdNominalType("Reactor")) orelse
                try self.pool.internRawPtr(.u8_ty, false),
            .reactor_ctx => (try self.ensureBuiltinStdNominalType("ReactorCtx")) orelse
                try self.pool.internRawPtr(.u8_ty, true),
        };
    }

    /// Returns `true` if `cst_id` contains a direct `.kw_mut` token leaf.
    fn hasMutKeywordInCst(self: *const TypeChecker, cst_id: CstNodeIndex) bool {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = cst_id.asInt();
        const rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(sub.token).kind == .kw_mut)
            {
                return true;
            }
            cur += @max(@as(usize, sub.subtree_size), 1);
        }
        return false;
    }

    /// Returns `true` if `cst_id` contains a direct `.kw_var` or `.kw_mut` token leaf.
    fn hasVarOrMutKeywordInCst(self: *const TypeChecker, cst_id: CstNodeIndex) bool {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = cst_id.asInt();
        const rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const tok_kind = self.token_buffer.getToken(sub.token).kind;
                if (tok_kind == .kw_var or tok_kind == .kw_mut) return true;
            }
            cur += @max(@as(usize, sub.subtree_size), 1);
        }
        return false;
    }

    /// Extracts inclusive `[min_val, max_val]` integer bounds from a literal, constant, or range pattern AST node.
    pub fn extractPatternRangeBounds(self: *const TypeChecker, pat_node_id: NodeIndex) ?Interval128 {
        if (pat_node_id.isNone() or pat_node_id.asInt() >= self.ast_arena.countNodes()) return null;
        const pat_node = self.ast_arena.getNode(pat_node_id);
        if (pat_node.tag == .variant_pat and self.getNodeExtraSlice(pat_node_id, false).len == 0) {
            const const_sym_idx = self.resolvePatternConstSymbolQuiet(pat_node_id) orelse return null;
            const const_val = self.evalReadOnlyConstSymbolInt(const_sym_idx, 0) orelse return null;
            return .{ .min_val = const_val, .max_val = const_val };
        }
        if (pat_node.tag == .bind_pat) {
            const const_sym_idx = self.resolveBindPatConstOrVariantQuiet(pat_node_id, false) orelse return null;
            if (self.sym_table.getSymbol(const_sym_idx).kind != .const_sym) return null;
            const const_val = self.evalReadOnlyConstSymbolInt(const_sym_idx, 0) orelse return null;
            return .{ .min_val = const_val, .max_val = const_val };
        }
        if (pat_node.tag != .lit_pat) return null;

        // Single literal pattern (`42` or `-5`):
        if (pat_node.lhs.tag == .none and pat_node.rhs.tag == .none) {
            const single_val = self.extractSignedPatternTokenValue(
                pat_node.main_token,
                self.ast_arena.getCstOrigin(pat_node_id),
            ) orelse return null;
            return .{ .min_val = single_val, .max_val = single_val };
        }

        // Range pattern (`lhs = .node(low_pat)`, `main_token = range_tok`, `rhs = .token(end_tok)`):
        if (pat_node.lhs.tag != .node or pat_node.rhs.tag != .token) return null;
        const low_pat_id = NodeIndex.fromInt(pat_node.lhs.payload);
        const low_pat = self.ast_arena.getNode(low_pat_id);
        const low_val = if (low_pat.tag == .variant_pat) blk_low: {
            const low_sym = self.resolvePatternConstSymbolQuiet(low_pat_id) orelse return null;
            break :blk_low self.evalReadOnlyConstSymbolInt(low_sym, 0) orelse return null;
        } else self.extractSignedPatternTokenValue(
            low_pat.main_token,
            self.ast_arena.getCstOrigin(low_pat_id),
        ) orelse return null;

        const end_tok = TokenIndex.fromInt(pat_node.rhs.payload);
        const high_raw = self.extractSignedEndTokenValue(
            end_tok,
            pat_node.main_token,
            self.ast_arena.getCstOrigin(pat_node_id),
        ) orelse return null;

        const range_kind = self.token_buffer.getToken(pat_node.main_token).kind;
        if (range_kind == .dotdot) {
            if (high_raw <= low_val) return .{ .min_val = 1, .max_val = 0 };
            return .{ .min_val = low_val, .max_val = high_raw - 1 };
        }
        return .{ .min_val = low_val, .max_val = high_raw };
    }

    /// Extracts order-preserving biased `i128` interval bounds (`val ^ (1 << 127)`) for `u128` match patterns.
    fn extractBiasedU128PatternRangeBounds(self: *const TypeChecker, pat_node_id: NodeIndex) ?Interval128 {
        if (pat_node_id.isNone() or pat_node_id.asInt() >= self.ast_arena.countNodes()) return null;
        const pat_node = self.ast_arena.getNode(pat_node_id);
        const sign_bias: u128 = @as(u128, 1) << 127;
        if (pat_node.tag == .variant_pat and self.getNodeExtraSlice(pat_node_id, false).len == 0) {
            const const_sym_idx = self.resolvePatternConstSymbolQuiet(pat_node_id) orelse return null;
            const const_val = self.evalReadOnlyConstSymbolInt(const_sym_idx, 0) orelse return null;
            if (const_val < 0) return null;
            const biased: i128 = @bitCast(@as(u128, @intCast(const_val)) ^ sign_bias);
            return .{ .min_val = biased, .max_val = biased };
        }
        if (pat_node.tag == .bind_pat) {
            const const_sym_idx = self.resolveBindPatConstOrVariantQuiet(pat_node_id, false) orelse return null;
            if (self.sym_table.getSymbol(const_sym_idx).kind != .const_sym) return null;
            const const_val = self.evalReadOnlyConstSymbolInt(const_sym_idx, 0) orelse return null;
            if (const_val < 0) return null;
            const biased: i128 = @bitCast(@as(u128, @intCast(const_val)) ^ sign_bias);
            return .{ .min_val = biased, .max_val = biased };
        }
        if (pat_node.tag != .lit_pat) return null;

        if (pat_node.lhs.tag == .none and pat_node.rhs.tag == .none) {
            const single_u = self.extractUnsignedPatternTokenValue(pat_node.main_token) orelse return null;
            const biased: i128 = @bitCast(single_u ^ sign_bias);
            return .{ .min_val = biased, .max_val = biased };
        }

        if (pat_node.lhs.tag != .node or pat_node.rhs.tag != .token) return null;
        const low_pat_id = NodeIndex.fromInt(pat_node.lhs.payload);
        const low_pat = self.ast_arena.getNode(low_pat_id);
        const low_u = if (low_pat.tag == .variant_pat) blk_low_u: {
            const low_sym = self.resolvePatternConstSymbolQuiet(low_pat_id) orelse return null;
            const low_i = self.evalReadOnlyConstSymbolInt(low_sym, 0) orelse return null;
            if (low_i < 0) return null;
            break :blk_low_u @as(u128, @intCast(low_i));
        } else self.extractUnsignedPatternTokenValue(low_pat.main_token) orelse return null;
        const end_tok = TokenIndex.fromInt(pat_node.rhs.payload);
        const high_raw_u = self.extractUnsignedEndTokenValue(
            end_tok,
            pat_node.main_token,
            self.ast_arena.getCstOrigin(pat_node_id),
        ) orelse return null;

        const range_kind = self.token_buffer.getToken(pat_node.main_token).kind;
        const high_u = if (range_kind == .dotdot) blk: {
            if (high_raw_u <= low_u) return .{ .min_val = 1, .max_val = 0 };
            break :blk high_raw_u - 1;
        } else high_raw_u;
        if (low_u > high_u) return .{ .min_val = 1, .max_val = 0 };
        return .{
            .min_val = @bitCast(low_u ^ sign_bias),
            .max_val = @bitCast(high_u ^ sign_bias),
        };
    }

    /// Evaluates a non-negative pattern literal or constant token (`int_lit`, `char_lit`, `const_ident`) to `u128`.
    fn extractUnsignedPatternTokenValue(self: *const TypeChecker, tok_idx: TokenIndex) ?u128 {
        if (tok_idx.isNone() or tok_idx.asInt() >= self.token_buffer.countTokens()) return null;
        const kind = self.token_buffer.getToken(tok_idx).kind;
        if (kind == .int_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            if (lex.len > 0 and lex[0] == '-') return null;
            const parsed = extractIntLiteralValue(lex) orelse return null;
            return parsed.magnitude;
        }
        if (kind == .char_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            if (extractCharLiteralCodepoint(lex)) |cp| return @as(u128, cp);
        }
        if (kind == .byte_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            if (lexer.extractByteLiteralValue(lex)) |byte_val| return @as(u128, byte_val);
        }
        if (symbol_resolver.isIdentifierToken(kind)) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            if (self.interner.lookup(lex)) |sym_id| {
                if (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_OR_CONST) == .found) {
                    const found_idx = switch (self.sym_table.lookupLexical(
                        self.current_scope,
                        sym_id,
                        NamespaceMask.VALUE_OR_CONST,
                    )) {
                        .found => |idx| idx,
                        else => .none,
                    };
                    if (!found_idx.isNone() and self.sym_table.getSymbol(found_idx).kind == .const_sym) {
                        if (self.evalReadOnlyConstSymbolInt(found_idx, 0)) |const_val| {
                            if (const_val >= 0) return @intCast(const_val);
                        }
                    }
                }
            }
        }
        return null;
    }

    /// Evaluates the upper-bound token of an unsigned `u128` range pattern, rejecting leading `-`.
    fn extractUnsignedEndTokenValue(
        self: *const TypeChecker,
        end_tok: TokenIndex,
        range_tok: TokenIndex,
        range_cst: CstNodeIndex,
    ) ?u128 {
        if (end_tok.isNone() or end_tok.asInt() >= self.token_buffer.countTokens()) return null;
        if (!range_cst.isNone() and range_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = range_cst.asInt();
            const rec = self.cst_arena.getNode(range_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var is_after_range = false;
            var cur = start_idx;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    if (sub.token == range_tok) {
                        is_after_range = true;
                    } else if (sub.token == end_tok) {
                        break;
                    } else if (is_after_range and self.token_buffer.getToken(sub.token).kind == .minus) {
                        return null;
                    }
                }
            }
        }
        return self.extractUnsignedPatternTokenValue(end_tok);
    }

    /// Evaluates a pattern literal token (with optional leading `-` inside `pat_cst`) to `i128`.
    fn extractSignedPatternTokenValue(
        self: *const TypeChecker,
        tok_idx: TokenIndex,
        pat_cst: CstNodeIndex,
    ) ?i128 {
        if (tok_idx.isNone() or tok_idx.asInt() >= self.token_buffer.countTokens()) return null;
        const kind = self.token_buffer.getToken(tok_idx).kind;
        const min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;
        if (kind == .minus) {
            // Find the numeric token immediately following `-` inside `pat_cst` or `token_buffer`:
            if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
                const start_idx: usize = pat_cst.asInt();
                const rec = self.cst_arena.getNode(pat_cst);
                const end_idx: usize = @min(
                    start_idx + @max(@as(usize, rec.subtree_size), 1),
                    self.cst_arena.countNodes(),
                );
                var has_seen_minus = false;
                var cur = start_idx;
                while (cur < end_idx) : (cur += 1) {
                    const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                    if (sub.subtree_size <= 1 and !sub.token.isNone() and
                        sub.token.asInt() < self.token_buffer.countTokens())
                    {
                        if (sub.token == tok_idx) {
                            has_seen_minus = true;
                        } else if (has_seen_minus and self.token_buffer.getToken(sub.token).kind == .int_lit) {
                            const lex = symbol_resolver.extractTokenSlice(
                                self.source,
                                self.token_buffer,
                                sub.token,
                            );
                            const parsed = extractIntLiteralValue(lex) orelse return null;
                            if (parsed.magnitude > min_abs) return null;
                            if (parsed.magnitude == min_abs) return std.math.minInt(i128);
                            return -@as(i128, @intCast(parsed.magnitude));
                        } else if (has_seen_minus and
                            symbol_resolver.isIdentifierToken(self.token_buffer.getToken(sub.token).kind))
                        {
                            const lex = symbol_resolver.extractTokenSlice(
                                self.source,
                                self.token_buffer,
                                sub.token,
                            );
                            const sym_id = self.interner.lookup(lex) orelse return null;
                            const val = switch (self.sym_table.lookupLexical(
                                self.current_scope,
                                sym_id,
                                NamespaceMask.VALUE_OR_CONST,
                            )) {
                                .found => |idx| self.evalReadOnlyConstSymbolInt(idx, 0) orelse return null,
                                else => return null,
                            };
                            return std.math.negate(val) catch null;
                        }
                    }
                }
            }
            return null;
        }
        if (kind == .int_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            const parsed = extractIntLiteralValue(lex) orelse return null;
            if (parsed.is_above_i128_max) return null;
            return parsed.value;
        }
        if (kind == .char_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            if (extractCharLiteralCodepoint(lex)) |cp| return @as(i128, cp);
        }
        if (kind == .byte_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            if (lexer.extractByteLiteralValue(lex)) |byte_val| return @as(i128, byte_val);
        }
        if (symbol_resolver.isIdentifierToken(kind)) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, tok_idx);
            const sym_id = self.interner.lookup(lex) orelse return null;
            return switch (self.sym_table.lookupLexical(
                self.current_scope,
                sym_id,
                NamespaceMask.VALUE_OR_CONST,
            )) {
                .found => |idx| self.evalReadOnlyConstSymbolInt(idx, 0),
                else => null,
            };
        }
        return null;
    }

    /// Evaluates the upper-bound token of a range pattern (checking for `-` between `range_tok` and `end_tok`).
    fn extractSignedEndTokenValue(
        self: *const TypeChecker,
        end_tok: TokenIndex,
        range_tok: TokenIndex,
        range_cst: CstNodeIndex,
    ) ?i128 {
        if (end_tok.isNone() or end_tok.asInt() >= self.token_buffer.countTokens()) return null;
        var is_neg = false;
        if (!range_cst.isNone() and range_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = range_cst.asInt();
            const rec = self.cst_arena.getNode(range_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var is_after_range = false;
            var cur = start_idx;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    if (sub.token == range_tok) {
                        is_after_range = true;
                    } else if (sub.token == end_tok) {
                        break;
                    } else if (is_after_range and self.token_buffer.getToken(sub.token).kind == .minus) {
                        is_neg = true;
                    }
                }
            }
        }
        const kind = self.token_buffer.getToken(end_tok).kind;
        if (kind == .int_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, end_tok);
            const parsed = extractIntLiteralValue(lex) orelse return null;
            if (is_neg) {
                const min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;
                if (parsed.magnitude > min_abs) return null;
                if (parsed.magnitude == min_abs) return std.math.minInt(i128);
                return -@as(i128, @intCast(parsed.magnitude));
            }
            if (parsed.is_above_i128_max) return null;
            return parsed.value;
        }
        if (kind == .char_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, end_tok);
            if (extractCharLiteralCodepoint(lex)) |cp| return @as(i128, cp);
        }
        if (kind == .byte_lit) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, end_tok);
            if (lexer.extractByteLiteralValue(lex)) |byte_val| return @as(i128, byte_val);
        }
        if (symbol_resolver.isIdentifierToken(kind)) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, end_tok);
            if (self.interner.lookup(lex)) |sym_id| {
                switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_OR_CONST)) {
                    .found => |found_idx| {
                        if (self.sym_table.getSymbol(found_idx).kind == .const_sym) {
                            if (self.evalReadOnlyConstSymbolInt(found_idx, 0)) |const_val| {
                                return if (is_neg) std.math.negate(const_val) catch null else const_val;
                            }
                        }
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    /// Quietly resolves a bare `.bind_pat` (without `mut` or `ref`) to an in-scope `.const_sym` or `.enum_variant_sym`.
    fn resolveBindPatConstOrVariantQuiet(
        self: *const TypeChecker,
        pat_id: NodeIndex,
        is_decl_mut: bool,
    ) ?SymbolIndex {
        if (is_decl_mut or pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return null;
        const pat_node = self.ast_arena.getNode(pat_id);
        if (pat_node.tag != .bind_pat) return null;
        const pat_cst = self.ast_arena.getCstOrigin(pat_id);
        if (self.hasVarOrMutKeywordInCst(pat_cst)) return null;
        if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = pat_cst.asInt();
            const rec = self.cst_arena.getNode(pat_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const tok_kind = self.token_buffer.getToken(sub.token).kind;
                    if (tok_kind == .amp or tok_kind == .kw_own) return null;
                }
            }
        }
        const name_str = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, pat_node.main_token);
        if (name_str.len == 0 or std.mem.eql(u8, name_str, "_")) return null;
        const sym_id = self.interner.lookup(name_str) orelse return null;
        switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_OR_CONST)) {
            .found => |sym_idx| {
                const sym_kind = self.sym_table.getSymbol(sym_idx).kind;
                if (sym_kind == .const_sym or sym_kind == .enum_variant_sym) return sym_idx;
            },
            else => {},
        }
        return null;
    }

    /// Quietly resolves a zero-payload `.variant_pat` (`MAX_RETRIES`, `mod.MAX_RETRIES`) to a `.const_sym`.
    fn resolvePatternConstSymbolQuiet(self: *const TypeChecker, pat_id: NodeIndex) ?SymbolIndex {
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return null;
        const pat_node = self.ast_arena.getNode(pat_id);
        if (pat_node.tag != .variant_pat) return null;
        if (!pat_node.main_token.isNone() and pat_node.main_token.asInt() < self.token_buffer.countTokens() and
            self.token_buffer.getToken(pat_node.main_token).kind == .dot)
        {
            return null;
        }

        var seg_tokens: [16]TokenIndex = undefined;
        var seg_count: usize = 0;
        const pat_cst = self.ast_arena.getCstOrigin(pat_id);
        if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = pat_cst.asInt();
            const rec = self.cst_arena.getNode(pat_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (is_leaf and !sub.flags.is_missing_or_injected and
                    !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const kind = self.token_buffer.getToken(sub.token).kind;
                    if (kind == .lparen or kind == .lbrace or kind == .dotdot or kind == .dotdoteq) break;
                    if (symbol_resolver.isIdentifierToken(kind) and seg_count < seg_tokens.len) {
                        seg_tokens[seg_count] = sub.token;
                        seg_count += 1;
                    }
                }
            }
        } else if (!pat_node.main_token.isNone()) {
            seg_tokens[0] = pat_node.main_token;
            seg_count = 1;
        }
        if (seg_count == 0) return null;

        if (seg_count == 1) {
            const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, seg_tokens[0]);
            const sym_id = self.interner.lookup(lex) orelse return null;
            return switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_OR_CONST)) {
                .found => |idx| if (self.sym_table.getSymbol(idx).kind == .const_sym) idx else null,
                else => null,
            };
        }

        var cur_scope = self.current_scope;
        var seg_idx: usize = 0;
        while (seg_idx + 1 < seg_count) : (seg_idx += 1) {
            const seg_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, seg_tokens[seg_idx]);
            if (seg_idx == 0 and std.mem.eql(u8, seg_lex, "pkg")) {
                cur_scope = self.sym_table.resolveCallerPackageRootScope(self.file_id, cur_scope);
                continue;
            }
            if (seg_idx == 0 and std.mem.eql(u8, seg_lex, "core") and
                !self.sym_table.isCoreAllowedForFile(self.file_id))
            {
                return null;
            }
            const seg_sym_id = self.interner.lookup(seg_lex) orelse return null;
            const found_seg = if (seg_idx == 0)
                switch (self.sym_table.lookupLexical(cur_scope, seg_sym_id, NamespaceMask.TYPE_OR_VALUE)) {
                    .found => |idx| idx,
                    else => blk_root: {
                        if (self.sym_table.lookupExternalPackageScope(self.file_id, seg_sym_id)) |ext_scope| {
                            cur_scope = ext_scope;
                            continue;
                        }
                        break :blk_root SymbolIndex.none;
                    },
                }
            else switch (self.sym_table.lookupInTargetScope(
                cur_scope,
                self.current_scope,
                seg_sym_id,
                NamespaceMask.TYPE_OR_VALUE,
            )) {
                .found => |idx| idx,
                else => SymbolIndex.none,
            };
            if (found_seg.isNone()) return null;
            cur_scope = self.sym_table.getSymbol(found_seg).target_scope;
            if (cur_scope.isNone()) return null;
        }
        const last_lex = symbol_resolver.extractTokenSlice(
            self.source,
            self.token_buffer,
            seg_tokens[seg_count - 1],
        );
        const last_sym_id = self.interner.lookup(last_lex) orelse return null;
        return switch (self.sym_table.lookupInTargetScope(
            cur_scope,
            self.current_scope,
            last_sym_id,
            NamespaceMask.VALUE_OR_CONST,
        )) {
            .found => |idx| if (self.sym_table.getSymbol(idx).kind == .const_sym) idx else null,
            else => null,
        };
    }

    /// Evaluates an integer `.const_sym` initializer in a read-only manner (`depth < 32`).
    fn evalReadOnlyConstSymbolInt(
        self: *const TypeChecker,
        sym_idx: SymbolIndex,
        depth: u32,
    ) ?i128 {
        if (depth >= 32 or sym_idx.isNone()) return null;
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (sym.kind != .const_sym or sym.ast_node.isNone()) return null;
        if (sym.decl_span.file_id == self.file_id) {
            if (sym.ast_node.asInt() >= self.ast_arena.countNodes()) return null;
            const c_node = self.ast_arena.getNode(sym.ast_node);
            if (c_node.rhs.tag != .node) return null;
            return self.evalReadOnlyConstExprInt(
                self.source,
                self.token_buffer,
                self.ast_arena,
                sym.scope_id,
                NodeIndex.fromInt(c_node.rhs.payload),
                depth + 1,
            );
        }
        if (self.db) |db_ptr| {
            const ext_in = db_ptr.source_inputs.getPtr(sym.decl_span.file_id.asInt()) orelse return null;
            const ext_parsed = db_ptr.parsed_artifacts.getPtr(sym.decl_span.file_id.asInt()) orelse return null;
            if (sym.ast_node.asInt() >= ext_parsed.ast_arena.countNodes()) return null;
            const c_node = ext_parsed.ast_arena.getNode(sym.ast_node);
            if (c_node.rhs.tag != .node) return null;
            return self.evalReadOnlyConstExprInt(
                ext_in.owned_text,
                &ext_parsed.token_buffer,
                &ext_parsed.ast_arena,
                sym.scope_id,
                NodeIndex.fromInt(c_node.rhs.payload),
                depth + 1,
            );
        }
        return null;
    }

    /// Read-only integer constant expression evaluator for `extractPatternRangeBounds` (`depth < 32`).
    fn evalReadOnlyConstExprInt(
        self: *const TypeChecker,
        src: []const u8,
        toks: *const TokenBuffer,
        ast: *const AstArena,
        scope_id: ScopeId,
        expr_id: NodeIndex,
        depth: u32,
    ) ?i128 {
        if (depth >= 32 or expr_id.isNone() or expr_id.asInt() >= ast.countNodes()) return null;
        const node = ast.getNode(expr_id);
        return switch (node.tag) {
            .int_lit => {
                const lex = symbol_resolver.extractTokenSlice(src, toks, node.main_token);
                const parsed = extractIntLiteralValue(lex) orelse return null;
                if (parsed.is_above_i128_max) return null;
                return parsed.value;
            },
            .char_lit => {
                const lex = symbol_resolver.extractTokenSlice(src, toks, node.main_token);
                return if (extractCharLiteralCodepoint(lex)) |cp| @as(i128, cp) else null;
            },
            .byte_lit => {
                const lex = symbol_resolver.extractTokenSlice(src, toks, node.main_token);
                return if (lexer.extractByteLiteralValue(lex)) |byte_val| @as(i128, byte_val) else null;
            },
            .unary_expr => {
                if (node.lhs.tag != .node or node.main_token.isNone() or
                    node.main_token.asInt() >= toks.countTokens()) return null;
                const op_kind = toks.getToken(node.main_token).kind;
                const inner_id = NodeIndex.fromInt(node.lhs.payload);
                if (op_kind == .tilde) {
                    const inner_val = self.evalReadOnlyConstExprInt(src, toks, ast, scope_id, inner_id, depth + 1) orelse
                        return null;
                    return ~inner_val;
                }
                if (op_kind == .minus) {
                    const inner_node = ast.getNode(inner_id);
                    if (inner_node.tag == .int_lit) {
                        const lex = symbol_resolver.extractTokenSlice(src, toks, inner_node.main_token);
                        const parsed = extractIntLiteralValue(lex) orelse return null;
                        const min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;
                        if (parsed.magnitude > min_abs) return null;
                        if (parsed.magnitude == min_abs) return std.math.minInt(i128);
                        return -@as(i128, @intCast(parsed.magnitude));
                    }
                    const inner_val = self.evalReadOnlyConstExprInt(src, toks, ast, scope_id, inner_id, depth + 1) orelse
                        return null;
                    return std.math.negate(inner_val) catch null;
                }
                if (op_kind == .kw_comptime) {
                    return self.evalReadOnlyConstExprInt(src, toks, ast, scope_id, inner_id, depth + 1);
                }
                return null;
            },
            .binary_expr => {
                if (node.lhs.tag != .node or node.rhs.tag != .node or node.main_token.isNone() or
                    node.main_token.asInt() >= toks.countTokens()) return null;
                const lhs_val = self.evalReadOnlyConstExprInt(
                    src,
                    toks,
                    ast,
                    scope_id,
                    NodeIndex.fromInt(node.lhs.payload),
                    depth + 1,
                ) orelse return null;
                const rhs_val = self.evalReadOnlyConstExprInt(
                    src,
                    toks,
                    ast,
                    scope_id,
                    NodeIndex.fromInt(node.rhs.payload),
                    depth + 1,
                ) orelse return null;
                return switch (toks.getToken(node.main_token).kind) {
                    .plus => std.math.add(i128, lhs_val, rhs_val) catch null,
                    .minus => std.math.sub(i128, lhs_val, rhs_val) catch null,
                    .star => std.math.mul(i128, lhs_val, rhs_val) catch null,
                    .slash => if (rhs_val != 0) std.math.divTrunc(i128, lhs_val, rhs_val) catch null else null,
                    .percent => if (rhs_val != 0) std.math.rem(i128, lhs_val, rhs_val) catch null else null,
                    .shl => if (rhs_val >= 0 and rhs_val < 128)
                        std.math.shlExact(i128, lhs_val, @intCast(rhs_val)) catch null
                    else
                        null,
                    .shr => if (rhs_val >= 0 and rhs_val < 128) lhs_val >> @intCast(rhs_val) else null,
                    .amp => lhs_val & rhs_val,
                    .pipe => lhs_val | rhs_val,
                    .caret => lhs_val ^ rhs_val,
                    else => null,
                };
            },
            .ident_expr => {
                const lex = symbol_resolver.extractTokenSlice(src, toks, node.main_token);
                const sym_id = self.interner.lookup(lex) orelse return null;
                return switch (self.sym_table.lookupLexical(scope_id, sym_id, NamespaceMask.VALUE_OR_CONST)) {
                    .found => |idx| self.evalReadOnlyConstSymbolInt(idx, depth + 1),
                    else => null,
                };
            },
            else => null,
        };
    }

    // -------- Pass 2: Spine-Local Bidirectional Body Check --------

    /// Type-checks all function, constant, and top-level `comptime { … }` bodies declared in `self.file_id`.
    pub fn checkFileBodies(self: *TypeChecker) !void {
        const sym_count = self.sym_table.countSymbols();
        var idx: u32 = 0;
        while (idx < sym_count) : (idx += 1) {
            const sym_idx = SymbolIndex.fromInt(idx);
            if (self.isSymbolCfgDisabled(sym_idx)) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.flags.is_builtin or sym.flags.is_imported) continue;
            if (!sym.decl_span.file_id.isNone() and sym.decl_span.file_id != self.file_id) continue;

            if (sym.kind == .fn_sym) {
                try self.checkFnDeclBody(sym_idx);
            } else if (sym.kind == .const_sym) {
                try self.checkConstInitializer(sym_idx);
            }
        }

        if (self.sym_table.file_module_scopes.get(self.file_id.asInt())) |mod_scope| {
            if (self.ast_arena.countNodes() > 0) {
                try self.checkModuleComptimeBlocks(.root, mod_scope);
            }
            try symbol_resolver.checkUnusedBindingsInScope(
                self.sym_table,
                mod_scope,
                self.interner,
                self.diagnostic_sink,
            );
        }
    }

    /// Recursively checks top-level `comptime { … }` blocks (`AstTag.block`) in `container_id` and inline `mod` items.
    fn checkModuleComptimeBlocks(
        self: *TypeChecker,
        container_id: NodeIndex,
        mod_scope: ScopeId,
    ) anyerror!void {
        if (container_id.isNone() or container_id.asInt() >= self.ast_arena.countNodes()) return;
        const container = self.ast_arena.getNode(container_id);
        const item_slice: []const u32 = if (container_id == .root) blk: {
            if (container.lhs.tag == .extra and container.rhs.tag == .extra and container.rhs.payload > 0) {
                break :blk self.ast_arena.getExtraSlice(
                    ExtraIndex.fromInt(container.lhs.payload),
                    container.rhs.payload,
                );
            }
            break :blk &.{};
        } else self.getNodeExtraSlice(container_id, true);

        for (item_slice) |raw_item_idx| {
            const item_idx = NodeIndex.fromInt(raw_item_idx);
            if (item_idx.asInt() >= self.ast_arena.countNodes()) continue;
            const item_cst = self.ast_arena.getCstOrigin(item_idx);
            if (!(try self.evaluateCstNodeCfgAttributesMode(item_cst, false))) continue;
            const item_node = self.ast_arena.getNode(item_idx);
            if (item_node.tag == .block) {
                try self.checkPureComptimeBlock(item_idx, mod_scope);
            } else if (item_node.tag == .mod_decl and item_node.rhs.tag == .extra) {
                for (self.sym_table.getScopeMembers(mod_scope)) |mem_idx| {
                    if (self.isSymbolCfgDisabled(mem_idx)) continue;
                    const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind == .module_sym and mem_sym.ast_node == item_idx and
                        !mem_sym.target_scope.isNone())
                    {
                        try self.checkModuleComptimeBlocks(item_idx, mem_sym.target_scope);
                        break;
                    }
                }
            }
        }
    }

    /// Type-checks a module-level `comptime { … }` block in `mod_scope` under `pure_comptime_depth`.
    fn checkPureComptimeBlock(
        self: *TypeChecker,
        block_id: NodeIndex,
        mod_scope: ScopeId,
    ) !void {
        const saved_scope = self.current_scope;
        const prev_pure_depth = self.pure_comptime_depth;
        const prev_boundary = self.comptime_boundary_scope_depth;
        self.current_scope = mod_scope;
        if (prev_pure_depth == 0) {
            self.comptime_boundary_scope_depth = if (mod_scope.isNone())
                0
            else
                self.sym_table.scope_arena.getScope(mod_scope).depth;
        }
        self.pure_comptime_depth = prev_pure_depth + 1;
        defer {
            self.current_scope = saved_scope;
            self.pure_comptime_depth = prev_pure_depth;
            self.comptime_boundary_scope_depth = prev_boundary;
        }
        _ = try self.checkBlock(block_id, .unit_ty, false);
    }

    /// Type-checks the body of a single `DefId` in isolation (used by `CompilerDb.typecheckBody`).
    pub fn checkDefBody(self: *TypeChecker, def_id: DefId) !void {
        if (def_id.isNone()) return;
        const matched_top_ast = self.findTopLevelDefAstNode(def_id.itemIndex());

        if (self.sym_table.def_to_symbol.get(def_id.asInt())) |sym_idx| {
            if (self.isSymbolCfgDisabled(sym_idx)) return;
            // Refresh `ast_node` and `cst_node` from `self.ast_arena` in case preceding function bodies shifted:
            if (!matched_top_ast.isNone()) {
                const sym_mut = self.sym_table.getSymbolMut(sym_idx);
                sym_mut.ast_node = matched_top_ast;
                sym_mut.cst_node = self.ast_arena.getCstOrigin(matched_top_ast);
            }
            const sym = self.sym_table.getSymbol(sym_idx).*;
            if (sym.kind == .fn_sym) {
                if (!sym.target_scope.isNone()) {
                    const param_specs = self.sym_table.getFnParamSpecs(sym_idx);
                    for (self.sym_table.getScopeMembers(sym.target_scope)) |mem_idx| {
                        const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind == .param_sym) {
                            self.sym_table.getSymbolMut(mem_idx).flags.is_used =
                                mem_sym.member_ordinal < param_specs.len and
                                param_specs[mem_sym.member_ordinal].is_used_by_default;
                        }
                    }
                }
                try self.checkFnDeclBody(sym_idx);
            } else if (sym.kind == .const_sym) {
                try self.checkConstInitializer(sym_idx);
            }
        } else if (!matched_top_ast.isNone()) {
            if (!(try self.evaluateCstNodeCfgAttributesMode(self.ast_arena.getCstOrigin(matched_top_ast), false))) return;
            const top_tag = self.ast_arena.getNode(matched_top_ast).tag;
            if (top_tag == .block) {
                const mod_scope = self.sym_table.file_module_scopes.get(self.file_id.asInt()) orelse
                    self.sym_table.prelude_scope;
                try self.checkPureComptimeBlock(matched_top_ast, mod_scope);
            } else if (top_tag == .impl_decl) {
                const impl_members = self.getNodeExtraSlice(matched_top_ast, true);
                var mem_cursor: usize = 0;
                var sym_raw: u32 = 0;
                while (sym_raw < self.sym_table.symbols.items.len) : (sym_raw += 1) {
                    const cand_sym_idx = SymbolIndex.fromInt(sym_raw);
                    if (self.isSymbolCfgDisabled(cand_sym_idx)) continue;
                    const cand_sym = self.sym_table.getSymbol(cand_sym_idx).*;
                    if (cand_sym.owner_def_id != def_id) continue;
                    if (cand_sym.kind != .fn_sym and cand_sym.kind != .const_sym) continue;

                    while (mem_cursor < impl_members.len) {
                        const mem_ast_idx = NodeIndex.fromInt(impl_members[mem_cursor]);
                        mem_cursor += 1;
                        if (mem_ast_idx.asInt() >= self.ast_arena.countNodes()) continue;
                        const mem_ast = self.ast_arena.getNode(mem_ast_idx);
                        const is_kind_match = (cand_sym.kind == .fn_sym and
                            (mem_ast.tag == .fn_decl or mem_ast.tag == .subscript_decl)) or
                            (cand_sym.kind == .const_sym and mem_ast.tag == .const_decl);
                        if (!is_kind_match) continue;
                        const sym_mut = self.sym_table.getSymbolMut(cand_sym_idx);
                        sym_mut.ast_node = mem_ast_idx;
                        sym_mut.cst_node = self.ast_arena.getCstOrigin(mem_ast_idx);
                        break;
                    }

                    if (cand_sym.kind == .fn_sym) {
                        if (!cand_sym.target_scope.isNone()) {
                            const param_specs = self.sym_table.getFnParamSpecs(cand_sym_idx);
                            for (self.sym_table.getScopeMembers(cand_sym.target_scope)) |param_idx| {
                                const param_sym = self.sym_table.getSymbol(param_idx).*;
                                if (param_sym.kind == .param_sym) {
                                    self.sym_table.getSymbolMut(param_idx).flags.is_used =
                                        param_sym.member_ordinal < param_specs.len and
                                        param_specs[param_sym.member_ordinal].is_used_by_default;
                                }
                            }
                        }
                        try self.checkFnDeclBody(cand_sym_idx);
                    } else if (cand_sym.kind == .const_sym) {
                        try self.checkConstInitializer(cand_sym_idx);
                    }
                }
            }
        }
    }

    /// Checks a `const` declaration's initializer expression against its explicit type under `pure_comptime_depth`.
    fn checkConstInitializer(self: *TypeChecker, raw_const_sym_idx: SymbolIndex) !void {
        var const_sym_idx = raw_const_sym_idx;
        const initial_sym = self.sym_table.getSymbol(const_sym_idx).*;
        if (!initial_sym.def_id.isNone() and initial_sym.owner_def_id.isNone()) {
            if (self.sym_table.def_to_symbol.get(initial_sym.def_id.asInt())) |live_idx| {
                const_sym_idx = live_idx;
            }
            if (initial_sym.def_id.fileId() == self.file_id) {
                const fresh_ast = self.findTopLevelDefAstNode(initial_sym.def_id.itemIndex());
                if (!fresh_ast.isNone()) {
                    const sym_mut = self.sym_table.getSymbolMut(const_sym_idx);
                    sym_mut.ast_node = fresh_ast;
                    sym_mut.cst_node = self.ast_arena.getCstOrigin(fresh_ast);
                }
            }
        }
        const sym = self.sym_table.getSymbol(const_sym_idx).*;
        if (sym.ast_node.isNone()) return;
        const c_node = self.ast_arena.getNode(sym.ast_node);
        if (c_node.rhs.tag != .node) return;

        const saved_scope = self.current_scope;
        const prev_pure_depth = self.pure_comptime_depth;
        const prev_boundary = self.comptime_boundary_scope_depth;
        self.current_scope = sym.scope_id;
        if (prev_pure_depth == 0) {
            self.comptime_boundary_scope_depth = if (sym.scope_id.isNone())
                0
            else
                self.sym_table.scope_arena.getScope(sym.scope_id).depth;
        }
        self.pure_comptime_depth = prev_pure_depth + 1;
        defer {
            self.current_scope = saved_scope;
            self.pure_comptime_depth = prev_pure_depth;
            self.comptime_boundary_scope_depth = prev_boundary;
        }

        const init_node_id = NodeIndex.fromInt(c_node.rhs.payload);
        if (!sym.type_id.isError()) {
            _ = try self.checkExpr(init_node_id, sym.type_id);
        } else {
            const inferred_ty = try self.synthExpr(init_node_id);
            self.sym_table.getSymbolMut(const_sym_idx).type_id = self.materializeUntypedType(inferred_ty);
        }
        self.bindCImportModuleToSymbolIfPresent(const_sym_idx, init_node_id);

        const resolved_const_ty = self.sym_table.getSymbol(const_sym_idx).type_id;
        if ((resolved_const_ty.isIntegerPrimitive() or resolved_const_ty == .bool_ty) and
            self.active_const_eval_len < self.active_const_eval.len)
        {
            self.active_const_eval[self.active_const_eval_len] = const_sym_idx;
            self.active_const_eval_len += 1;
            defer self.active_const_eval_len -= 1;
            _ = try self.evalConstIntExpr(init_node_id, true);
        }
    }

    /// Type-checks a block-local `const NAME: T = EXPR;` declaration (`DR-05` Showcases A & B).
    fn checkLocalConstDecl(self: *TypeChecker, decl_id: NodeIndex) anyerror!TypeId {
        const decl_node = self.ast_arena.getNode(decl_id);
        const decl_cst = self.ast_arena.getCstOrigin(decl_id);

        var name_tok: TokenIndex = .none;
        if (!decl_cst.isNone() and decl_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = decl_cst.asInt();
            const rec = self.cst_arena.getNode(decl_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const tok_kind = self.token_buffer.getToken(sub.token).kind;
                    if (tok_kind == .colon or tok_kind == .eq) break;
                    if (symbol_resolver.isIdentifierToken(tok_kind)) {
                        name_tok = sub.token;
                        break;
                    }
                }
            }
        }

        const declared_ty: TypeId = if (decl_node.lhs.tag == .node)
            try self.resolveTypeAst(NodeIndex.fromInt(decl_node.lhs.payload))
        else
            .err_ty;

        var final_ty: TypeId = declared_ty;
        if (decl_node.rhs.tag == .node) {
            const prev_pure_depth = self.pure_comptime_depth;
            const prev_boundary = self.comptime_boundary_scope_depth;
            if (prev_pure_depth == 0) {
                self.comptime_boundary_scope_depth = if (self.current_scope.isNone())
                    0
                else
                    self.sym_table.scope_arena.getScope(self.current_scope).depth;
            }
            self.pure_comptime_depth = prev_pure_depth + 1;
            defer {
                self.pure_comptime_depth = prev_pure_depth;
                self.comptime_boundary_scope_depth = prev_boundary;
            }

            const init_id = NodeIndex.fromInt(decl_node.rhs.payload);
            if (!declared_ty.isError()) {
                final_ty = try self.checkExpr(init_id, declared_ty);
            } else {
                final_ty = self.materializeUntypedType(try self.synthExpr(init_id));
            }
        }

        if (!name_tok.isNone()) {
            const name_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, name_tok);
            if (name_lex.len > 0) {
                const name_sym = try self.interner.intern(name_lex);
                const created_idx = try self.sym_table.defineSymbol(.{
                    .name = name_sym,
                    .name_text = self.interner.get(name_sym),
                    .kind = .const_sym,
                    .namespace = .const_ns,
                    .visibility = .private,
                    .flags = .{ .is_comptime = true },
                    .scope_id = self.current_scope,
                    .ast_node = decl_id,
                    .cst_node = decl_cst,
                    .decl_span = self.token_buffer.getTokenSpan(self.file_id, name_tok),
                    .type_id = final_ty,
                }, self.diagnostic_sink);
                if (decl_node.rhs.tag == .node) {
                    self.bindCImportModuleToSymbolIfPresent(created_idx, NodeIndex.fromInt(decl_node.rhs.payload));
                }
                self.recordNodeSymbol(decl_id, created_idx);
            }
        }
        return self.recordNodeType(decl_id, .unit_ty);
    }

    /// Defines, resolves the signature of, and type-checks a block-local `fn` declaration (`decl_id`).
    fn checkLocalFnDecl(self: *TypeChecker, decl_id: NodeIndex) anyerror!TypeId {
        const decl_node = self.ast_arena.getNode(decl_id);
        const decl_cst = self.ast_arena.getCstOrigin(decl_id);
        const name_lex = self.extractFnDeclNameFromCst(decl_cst, decl_node.main_token);
        if (name_lex.len > 0) {
            const header_meta = try symbol_resolver.extractItemHeaderMetadataValidated(
                self.source,
                self.file_id,
                self.token_buffer,
                self.cst_arena,
                decl_cst,
                decl_node.main_token,
                self.diagnostic_sink,
            );
            const name_sym = try self.interner.intern(name_lex);
            const fn_sym_idx = try self.sym_table.defineSymbol(.{
                .name = name_sym,
                .name_text = self.interner.get(name_sym),
                .kind = .fn_sym,
                .namespace = .value_ns,
                .visibility = header_meta.visibility,
                .flags = header_meta.flags,
                .extra_flags = header_meta.extra_flags,
                .scope_id = self.current_scope,
                .ast_node = decl_id,
                .cst_node = decl_cst,
                .decl_span = self.getAstNodeSpan(decl_id),
                .contract_flags = header_meta.contract_flags,
                .max_stack_bytes = header_meta.max_stack_bytes,
                .cap_emits_mask = header_meta.cap_emits_mask,
                .cap_clears_mask = header_meta.cap_clears_mask,
                .explicit_align_log2_plus1 = header_meta.explicit_align_log2_plus1,
                .has_cfg_attr = header_meta.has_cfg_attr,
            }, self.diagnostic_sink);
            self.recordNodeSymbol(decl_id, fn_sym_idx);
            try self.resolveFnSignatureSymbol(fn_sym_idx);
            try self.checkFnDeclBody(fn_sym_idx);
        }
        return self.recordNodeType(decl_id, .unit_ty);
    }

    /// Type-checks the body block of a function, test, benchmark, or `subscript` symbol (`raw_fn_sym_idx`).
    pub fn checkFnDeclBody(self: *TypeChecker, raw_fn_sym_idx: SymbolIndex) !void {
        var fn_sym_idx = raw_fn_sym_idx;
        const initial_sym = self.sym_table.getSymbol(fn_sym_idx).*;
        if (!initial_sym.def_id.isNone() and initial_sym.owner_def_id.isNone()) {
            if (self.sym_table.def_to_symbol.get(initial_sym.def_id.asInt())) |live_idx| {
                if (live_idx != fn_sym_idx) {
                    fn_sym_idx = live_idx;
                    const live_rec = self.sym_table.getSymbol(fn_sym_idx).*;
                    if (!live_rec.target_scope.isNone()) {
                        const p_specs = self.sym_table.getFnParamSpecs(fn_sym_idx);
                        for (self.sym_table.getScopeMembers(live_rec.target_scope)) |mem_idx| {
                            const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                            if (mem_sym.kind == .param_sym) {
                                self.sym_table.getSymbolMut(mem_idx).flags.is_used =
                                    mem_sym.member_ordinal < p_specs.len and
                                    p_specs[mem_sym.member_ordinal].is_used_by_default;
                            }
                        }
                    }
                }
            }
            if (initial_sym.def_id.fileId() == self.file_id) {
                const fresh_ast = self.findTopLevelDefAstNode(initial_sym.def_id.itemIndex());
                if (!fresh_ast.isNone()) {
                    const sym_mut = self.sym_table.getSymbolMut(fn_sym_idx);
                    sym_mut.ast_node = fresh_ast;
                    sym_mut.cst_node = self.ast_arena.getCstOrigin(fresh_ast);
                }
            }
        }
        try self.resolveFnSignatureSymbol(fn_sym_idx);
        const fn_sym = self.sym_table.getSymbol(fn_sym_idx).*;
        if (fn_sym.ast_node.isNone()) return;

        const fn_ast = self.ast_arena.getNode(fn_sym.ast_node);
        const sig_view = self.pool.getFnSignatureView(fn_sym.type_id) orelse return;
        const saved_scope = self.current_scope;
        const saved_ret_ty = self.current_fn_ret_ty;
        const saved_defer_depth = self.defer_depth;
        const saved_defer_loop_depth = self.defer_inner_loop_depth;
        const prev_pure_depth = self.pure_comptime_depth;
        const prev_boundary = self.comptime_boundary_scope_depth;
        const saved_extern = self.is_extern_fn;
        const saved_unsafe_depth = self.unsafe_depth;
        const saved_builder_depth = self.active_builder_depth;
        const saved_in_sub = self.is_in_subscript_arm;
        const saved_in_sub_inout = self.is_in_subscript_inout_arm;
        const saved_sub_elem = self.current_subscript_elem_ty;
        const saved_sub_yield = self.subscript_yield_count;
        const saved_in_async = self.is_in_async;
        const saved_nursery_depth = self.nursery_scope_depth;
        defer {
            self.current_scope = saved_scope;
            self.current_fn_ret_ty = saved_ret_ty;
            self.defer_depth = saved_defer_depth;
            self.defer_inner_loop_depth = saved_defer_loop_depth;
            self.pure_comptime_depth = prev_pure_depth;
            self.comptime_boundary_scope_depth = prev_boundary;
            self.is_extern_fn = saved_extern;
            self.unsafe_depth = saved_unsafe_depth;
            self.active_builder_depth = saved_builder_depth;
            self.is_in_subscript_arm = saved_in_sub;
            self.is_in_subscript_inout_arm = saved_in_sub_inout;
            self.current_subscript_elem_ty = saved_sub_elem;
            self.subscript_yield_count = saved_sub_yield;
            self.is_in_async = saved_in_async;
            self.nursery_scope_depth = saved_nursery_depth;
        }

        const fn_decl_cst = if (!fn_sym.cst_node.isNone())
            fn_sym.cst_node
        else
            self.ast_arena.getCstOrigin(fn_sym.ast_node);
        if (self.hasUnsafeKeywordInBlockCst(fn_decl_cst)) {
            self.unsafe_depth += 1;
        }
        if (sig_view.contracts.has_builder and sig_view.paramCount() > 0) {
            const param_specs = self.sym_table.getFnParamSpecs(fn_sym_idx);
            var has_pushed_builder = false;
            for (param_specs, 0..) |p_spec, p_ord| {
                if (p_spec.is_builder and p_ord < sig_view.paramCount()) {
                    const scope_ty = self.unwrapRefType(sig_view.getParamType(p_ord));
                    if (!scope_ty.isError() and self.active_builder_depth < self.active_builder_stack.len) {
                        self.active_builder_stack[self.active_builder_depth] = scope_ty;
                        self.active_builder_depth += 1;
                        has_pushed_builder = true;
                    }
                    break;
                }
            }
            if (!has_pushed_builder and self.active_builder_depth < self.active_builder_stack.len) {
                const scope_ty = self.unwrapRefType(sig_view.getParamType(0));
                if (!scope_ty.isError()) {
                    self.active_builder_stack[self.active_builder_depth] = scope_ty;
                    self.active_builder_depth += 1;
                }
            }
        }

        if (fn_sym.flags.is_comptime) {
            if (prev_pure_depth == 0) {
                self.comptime_boundary_scope_depth = if (fn_sym.scope_id.isNone())
                    0
                else
                    self.sym_table.scope_arena.getScope(fn_sym.scope_id).depth;
            }
            self.pure_comptime_depth = prev_pure_depth + 1;
        }
        self.is_extern_fn = fn_sym.flags.is_extern;
        self.is_in_async = sig_view.is_async;
        self.nursery_scope_depth = null;
        self.defer_depth = 0;
        self.defer_inner_loop_depth = 0;
        self.loop_frame_depth = 0;
        self.bracket_len_depth = 0;
        self.is_direct_positive_cond = false;
        self.is_dominating_walrus_pos = false;
        self.is_negated_is_context = false;
        self.has_following_and_conjunct = false;
        self.active_default_param_max_ordinal = null;
        self.current_scope = if (!fn_sym.target_scope.isNone()) fn_sym.target_scope else fn_sym.scope_id;
        self.current_fn_ret_ty = sig_view.ret_ty;

        // `SE-21`: Check `subscript(…) -> Elem { let { … } inout { … } }` accessor arms:
        if (fn_ast.tag == .subscript_decl) {
            if (fn_ast.rhs.tag != .extra) return;
            const extra_start: usize = fn_ast.rhs.payload;
            if (extra_start >= self.ast_arena.extra_data.items.len) return;
            const arm_count: usize = self.ast_arena.extra_data.items[extra_start];
            const self_sym_id = try self.interner.intern("self");
            const self_type_sym_id = try self.interner.intern("Self");
            const has_explicit_self = !self.sym_table.lookupInScopeDirect(
                self.current_scope,
                self_sym_id,
                NamespaceMask.VALUE_ONLY,
            ).isNone();
            const enclosing_self_ty: TypeId = switch (self.sym_table.lookupLexical(
                fn_sym.scope_id,
                self_type_sym_id,
                NamespaceMask.TYPE_ONLY,
            )) {
                .found => |self_ty_idx| try self.ensureTypeSymbolResolved(self_ty_idx),
                else => .err_ty,
            };

            const base_fn_scope = self.current_scope;
            var arm_idx: usize = 0;
            while (arm_idx < arm_count) : (arm_idx += 1) {
                const pair_base = extra_start + 1 + arm_idx * 2;
                if (pair_base + 1 >= self.ast_arena.extra_data.items.len) break;
                const arm_mode = self.ast_arena.extra_data.items[pair_base];
                const arm_blk_id = NodeIndex.fromInt(self.ast_arena.extra_data.items[pair_base + 1]);
                if (arm_blk_id.isNone() or arm_blk_id.asInt() >= self.ast_arena.countNodes()) continue;

                const arm_scope = try self.sym_table.scope_arena.allocScope(
                    .block_scope,
                    base_fn_scope,
                    .NONE,
                    self.file_id,
                    .{},
                );
                if (!has_explicit_self and !enclosing_self_ty.isError()) {
                    const arm_self_ty = try self.pool.internRef(enclosing_self_ty, arm_mode == 1);
                    _ = try self.sym_table.defineSymbol(.{
                        .name = self_sym_id,
                        .name_text = self.interner.get(self_sym_id),
                        .kind = .param_sym,
                        .namespace = .value_ns,
                        .visibility = .private,
                        .flags = .{ .is_used = true },
                        .scope_id = arm_scope,
                        .decl_span = fn_sym.decl_span,
                        .type_id = arm_self_ty,
                    }, null);
                }

                self.current_scope = arm_scope;
                self.is_in_subscript_arm = true;
                self.is_in_subscript_inout_arm = (arm_mode == 1);
                self.current_subscript_elem_ty = sig_view.ret_ty;
                self.subscript_yield_count = 0;

                const arm_ty = try self.checkBlock(arm_blk_id, .unit_ty, true);
                if (!arm_ty.isError() and arm_ty != .never_ty) {
                    if (self.subscript_yield_count == 0) {
                        try self.emitDiagnosticSimple(
                            .e0401_type_mismatch,
                            self.getAstNodeSpan(arm_blk_id),
                            "`subscript` accessor arm must yield an element via `yield expr;`",
                            "missing `yield` statement in `subscript` arm",
                        );
                    } else {
                        try self.verifySubscriptArmYieldPaths(arm_blk_id);
                    }
                }
                try symbol_resolver.checkUnusedBindingsInScope(
                    self.sym_table,
                    arm_scope,
                    self.interner,
                    self.diagnostic_sink,
                );
            }
            self.current_scope = base_fn_scope;
            if (!fn_sym.target_scope.isNone()) {
                try symbol_resolver.checkUnusedBindingsInScope(
                    self.sym_table,
                    fn_sym.target_scope,
                    self.interner,
                    self.diagnostic_sink,
                );
            }
            return;
        }

        if (fn_ast.rhs.tag != .node) return;
        const body_block_id = NodeIndex.fromInt(fn_ast.rhs.payload);
        if (body_block_id.isNone() or body_block_id.asInt() >= self.ast_arena.countNodes()) return;

        _ = try self.checkBlock(body_block_id, sig_view.ret_ty, true);

        if (!fn_sym.target_scope.isNone()) {
            try symbol_resolver.checkUnusedBindingsInScope(
                self.sym_table,
                fn_sym.target_scope,
                self.interner,
                self.diagnostic_sink,
            );
        }
    }

    // ----------------- Block & Statement Checking -----------------

    /// Type-checks a `.block` AST node against `expected_ty` (`is_fn_body = true` for top-level function blocks).
    fn checkBlock(
        self: *TypeChecker,
        block_id: NodeIndex,
        expected_ty: TypeId,
        is_fn_body: bool,
    ) anyerror!TypeId {
        if (block_id.isNone() or block_id.asInt() >= self.ast_arena.countNodes()) return .err_ty;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return self.recordNodeType(block_id, .err_ty);
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const block_node = self.ast_arena.getNode(block_id);
        if (block_node.tag == .expr_hole) return self.recordNodeType(block_id, .err_ty);
        if (block_node.tag != .block) {
            return if (expected_ty.isError())
                self.synthExpr(block_id)
            else
                self.checkExpr(block_id, expected_ty);
        }

        const block_cst = self.ast_arena.getCstOrigin(block_id);
        const is_async_block = !is_fn_body and self.hasAsyncKeywordInBlockCst(block_cst);
        const inner_expected_ty: TypeId = if (is_async_block)
            (self.pool.getFutureOutputType(expected_ty) orelse .err_ty)
        else
            expected_ty;

        const saved_scope = self.current_scope;
        const saved_pos = self.is_direct_positive_cond;
        const saved_walrus = self.is_dominating_walrus_pos;
        const saved_neg = self.is_negated_is_context;
        const saved_unsafe_depth = self.unsafe_depth;
        const saved_in_async = self.is_in_async;
        const saved_ret_ty = self.current_fn_ret_ty;
        const saved_defer_depth = self.defer_depth;
        const saved_loop_depth = self.loop_frame_depth;
        if (self.hasUnsafeKeywordInBlockCst(block_cst)) {
            self.unsafe_depth += 1;
        }
        if (is_async_block) {
            self.is_in_async = true;
            self.current_fn_ret_ty = inner_expected_ty;
            self.defer_depth = 0;
            self.loop_frame_depth = 0;
        }
        const block_scope = if (is_fn_body)
            self.current_scope
        else
            try self.sym_table.scope_arena.allocScope(
                .block_scope,
                self.current_scope,
                .NONE,
                self.file_id,
                .{},
            );
        self.current_scope = block_scope;
        self.is_direct_positive_cond = false;
        self.is_dominating_walrus_pos = false;
        self.is_negated_is_context = false;
        defer {
            self.current_scope = saved_scope;
            self.is_direct_positive_cond = saved_pos;
            self.is_dominating_walrus_pos = saved_walrus;
            self.is_negated_is_context = saved_neg;
            self.unsafe_depth = saved_unsafe_depth;
            self.is_in_async = saved_in_async;
            self.current_fn_ret_ty = saved_ret_ty;
            self.defer_depth = saved_defer_depth;
            self.loop_frame_depth = saved_loop_depth;
        }

        const stmt_slice = self.getNodeExtraSlice(block_id, false);
        var has_diverged = false;

        for (stmt_slice) |raw_stmt_id| {
            const stmt_id = NodeIndex.fromInt(raw_stmt_id);
            if (!(try self.evaluateCstNodeCfgAttributesMode(self.ast_arena.getCstOrigin(stmt_id), true))) {
                _ = self.recordNodeType(stmt_id, .unit_ty);
                continue;
            }
            const stmt_ty = try self.checkStmt(stmt_id);
            if (stmt_ty == .never_ty) {
                has_diverged = true;
            }
        }

        var result_ty: TypeId = if (has_diverged) .never_ty else .unit_ty;
        if (block_node.rhs.tag == .node) {
            const tail_id = NodeIndex.fromInt(block_node.rhs.payload);
            if (!inner_expected_ty.isError() and inner_expected_ty != .unit_ty) {
                result_ty = try self.checkExpr(tail_id, inner_expected_ty);
            } else if (inner_expected_ty == .unit_ty) {
                const tail_ty = try self.synthExpr(tail_id);
                if (tail_ty == .never_ty) {
                    result_ty = .never_ty;
                } else if (!tail_ty.isError() and tail_ty != .unit_ty) {
                    if (self.isMustUseTypeOrCall(tail_id, tail_ty)) {
                        try self.emitUnhandledMustUseError(self.getAstNodeSpan(tail_id), tail_ty);
                    } else if (is_fn_body) {
                        try self.emitTypeMismatch(
                            self.getAstNodeSpan(tail_id),
                            .unit_ty,
                            self.materializeUntypedType(tail_ty),
                        );
                    } else {
                        result_ty = self.materializeUntypedType(tail_ty);
                    }
                }
            } else {
                const tail_ty = try self.synthExpr(tail_id);
                result_ty = self.materializeUntypedType(tail_ty);
            }
        } else if (!has_diverged and !inner_expected_ty.isError() and inner_expected_ty != .unit_ty) {
            try self.emitTypeMismatch(self.getAstNodeSpan(block_id), inner_expected_ty, .unit_ty);
            result_ty = .err_ty;
        }

        if (!is_fn_body) {
            try symbol_resolver.checkUnusedBindingsInScope(
                self.sym_table,
                block_scope,
                self.interner,
                self.diagnostic_sink,
            );
        }
        if (is_async_block) {
            const async_out_ty = if (!result_ty.isError())
                result_ty
            else if (!inner_expected_ty.isError())
                inner_expected_ty
            else
                .err_ty;
            const fut_ty = try self.pool.internFuture(async_out_ty, 0);
            if (!expected_ty.isError() and !fut_ty.isError()) {
                if (!(try self.checkTypeCompatibility(block_id, fut_ty, expected_ty))) {
                    return self.recordNodeType(block_id, .err_ty);
                }
            }
            return self.recordNodeType(block_id, fut_ty);
        }
        return self.recordNodeType(block_id, result_ty);
    }

    /// Type-checks a single statement inside a block, returning `.never_ty` if the statement diverges.
    fn checkStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        if (stmt_id.isNone() or stmt_id.asInt() >= self.ast_arena.countNodes()) return .err_ty;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return self.recordNodeType(stmt_id, .err_ty);
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const stmt_node = self.ast_arena.getNode(stmt_id);

        return switch (stmt_node.tag) {
            .stmt_hole, .expr_hole, .item_hole => self.recordNodeType(stmt_id, .err_ty),
            .local_var_decl => self.checkLocalVarDecl(stmt_id),
            .const_decl => self.checkLocalConstDecl(stmt_id),
            .fn_decl => self.checkLocalFnDecl(stmt_id),
            .struct_decl,
            .bit_field_decl,
            .enum_decl,
            .union_decl,
            .type_alias_decl,
            .trait_decl,
            .impl_decl,
            .use_decl,
            .test_decl,
            .bench_decl,
            .subscript_decl,
            .extern_block_decl,
            .extern_static_decl,
            => self.recordNodeType(stmt_id, .unit_ty),
            .yield_stmt => self.checkYieldStmt(stmt_id),
            .defer_stmt => self.checkDeferStmt(stmt_id),
            .return_stmt => self.checkReturnStmt(stmt_id),
            .break_stmt => self.checkBreakStmt(stmt_id),
            .continue_stmt => self.checkContinueStmt(stmt_id),
            .for_stmt => self.synthOrCheckForExpr(stmt_id, .err_ty),
            .while_stmt => self.synthOrCheckWhileExpr(stmt_id, .err_ty),
            .assign_stmt => self.checkAssignStmt(stmt_id),
            else => blk: {
                const expr_ty = try self.synthExpr(stmt_id);
                // Enforce `@must_use` / `Result[T, E]` handling on discarded expression statements (`E0413`, `DR-07` Section 2.4):
                if (!expr_ty.isError() and expr_ty != .unit_ty and expr_ty != .never_ty) {
                    if (self.isMustUseTypeOrCall(stmt_id, expr_ty)) {
                        try self.emitUnhandledMustUseError(self.getAstNodeSpan(stmt_id), expr_ty);
                    }
                }
                break :blk self.recordNodeType(stmt_id, expr_ty);
            },
        };
    }

    /// Returns `true` if `block_cst` carries a leading `unsafe` keyword leaf (`unsafe { … }`).
    fn hasUnsafeKeywordInBlockCst(self: *const TypeChecker, block_cst: CstNodeIndex) bool {
        if (block_cst.isNone() or block_cst.asInt() >= self.cst_arena.countNodes()) return false;
        var target_cst = block_cst;
        var unwrap_steps: u32 = 0;
        while (unwrap_steps < 4 and !target_cst.isNone() and target_cst.asInt() < self.cst_arena.countNodes()) : (unwrap_steps += 1) {
            const outer_rec = self.cst_arena.getNode(target_cst);
            if (outer_rec.kind != .local_decl_stmt and outer_rec.kind != .expr_stmt) break;
            const outer_start: usize = target_cst.asInt();
            const outer_end: usize = @min(
                outer_start + @max(@as(usize, outer_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var inner_found: CstNodeIndex = .none;
            var scan_cur = outer_start + 1;
            while (scan_cur < outer_end) {
                const sub_id = CstNodeIndex.fromInt(@intCast(scan_cur));
                const sub = self.cst_arena.getNode(sub_id);
                const step: usize = @max(@as(usize, sub.subtree_size), 1);
                if (sub.kind == .block or sub.kind == .expr_stmt or sub.kind == .local_decl_stmt) {
                    inner_found = sub_id;
                    break;
                }
                scan_cur += step;
            }
            if (inner_found.isNone()) break;
            target_cst = inner_found;
        }
        const start_idx: usize = target_cst.asInt();
        const rec = self.cst_arena.getNode(target_cst);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size > 1) {
                if (sub.kind == .attribute) {
                    cur += @as(usize, sub.subtree_size) - 1;
                    continue;
                }
                break;
            }
            if (!sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens()) {
                const tok_kind = self.token_buffer.getToken(sub.token).kind;
                if (tok_kind == .kw_unsafe) return true;
                if (tok_kind == .lbrace) break;
            }
        }
        return false;
    }

    /// Returns `true` if `block_cst` carries a leading `async` keyword leaf (`async { … }`).
    fn hasAsyncKeywordInBlockCst(self: *const TypeChecker, block_cst: CstNodeIndex) bool {
        if (block_cst.isNone() or block_cst.asInt() >= self.cst_arena.countNodes()) return false;
        var target_cst = block_cst;
        var unwrap_steps: u32 = 0;
        while (unwrap_steps < 4 and !target_cst.isNone() and target_cst.asInt() < self.cst_arena.countNodes()) : (unwrap_steps += 1) {
            const outer_rec = self.cst_arena.getNode(target_cst);
            if (outer_rec.kind != .local_decl_stmt and outer_rec.kind != .expr_stmt) break;
            const outer_start: usize = target_cst.asInt();
            const outer_end: usize = @min(
                outer_start + @max(@as(usize, outer_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var inner_found: CstNodeIndex = .none;
            var scan_cur = outer_start + 1;
            while (scan_cur < outer_end) {
                const sub_id = CstNodeIndex.fromInt(@intCast(scan_cur));
                const sub = self.cst_arena.getNode(sub_id);
                const step: usize = @max(@as(usize, sub.subtree_size), 1);
                if (sub.kind == .block or sub.kind == .expr_stmt or sub.kind == .local_decl_stmt) {
                    inner_found = sub_id;
                    break;
                }
                scan_cur += step;
            }
            if (inner_found.isNone()) break;
            target_cst = inner_found;
        }
        const start_idx: usize = target_cst.asInt();
        const rec = self.cst_arena.getNode(target_cst);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.subtree_size > 1) {
                if (sub.kind == .attribute) {
                    cur += @as(usize, sub.subtree_size) - 1;
                    continue;
                }
                break;
            }
            if (!sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens()) {
                const tok_kind = self.token_buffer.getToken(sub.token).kind;
                if (tok_kind == .kw_async) return true;
                if (tok_kind == .lbrace) break;
            }
        }
        return false;
    }

    /// Abstract count of `yield` executions along non-diverging paths inside a `subscript` arm.
    const YieldPathSummary = struct {
        /// `true` if at least one non-diverging path has executed zero `yield` statements.
        has_zero: bool = false,
        /// `true` if at least one non-diverging path has executed exactly one `yield` statement.
        has_one: bool = false,
        /// `true` if at least one non-diverging path has executed two or more `yield` statements.
        has_many: bool = false,

        /// Returns `true` when every path reaching this program point has diverged.
        inline fn isDiverged(self: YieldPathSummary) bool {
            return !self.has_zero and !self.has_one and !self.has_many;
        }

        /// Computes the lattice join across two control-flow branches.
        inline fn join(lhs: YieldPathSummary, rhs: YieldPathSummary) YieldPathSummary {
            return .{
                .has_zero = lhs.has_zero or rhs.has_zero,
                .has_one = lhs.has_one or rhs.has_one,
                .has_many = lhs.has_many or rhs.has_many,
            };
        }
    };

    /// Verifies that every non-diverging path through `arm_blk_id` executes `yield` exactly once.
    fn verifySubscriptArmYieldPaths(self: *TypeChecker, arm_blk_id: NodeIndex) anyerror!void {
        var has_emitted_dup_err = false;
        const exit_summary = try self.analyzeSubscriptYieldPaths(
            arm_blk_id,
            .{ .has_zero = true },
            &has_emitted_dup_err,
            0,
        );
        if (exit_summary.has_zero) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(arm_blk_id),
                "`subscript` accessor arm has a non-diverging control-flow path that exits without `yield`",
                "ensure every non-diverging branch yields an element via `yield expr;`",
            );
        } else if (exit_summary.has_many and !has_emitted_dup_err) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(arm_blk_id),
                "`subscript` accessor arm may execute `yield` multiple times along a single path",
                "each `subscript` invocation must execute `yield` at most once",
            );
        }
    }

    /// Computes the outgoing `YieldPathSummary` of `node_id` given `incoming` path state.
    fn analyzeSubscriptYieldPaths(
        self: *TypeChecker,
        node_id: NodeIndex,
        incoming: YieldPathSummary,
        has_emitted_dup_err: *bool,
        depth: u32,
    ) anyerror!YieldPathSummary {
        if (depth >= MAX_TYPE_DEPTH or node_id.isNone() or node_id.asInt() >= self.ast_arena.countNodes()) {
            return incoming;
        }
        if (incoming.isDiverged()) return incoming;

        const ast_node = self.ast_arena.getNode(node_id);
        switch (ast_node.tag) {
            .fn_decl,
            .subscript_decl,
            .closure_expr,
            .struct_decl,
            .bit_field_decl,
            .enum_decl,
            .union_decl,
            .trait_decl,
            .impl_decl,
            .type_alias_decl,
            .use_decl,
            .test_decl,
            .bench_decl,
            .defer_stmt,
            => return incoming,
            .return_stmt, .unreachable_expr => return .{},
            .yield_stmt => {
                var after_val = incoming;
                if (ast_node.lhs.tag == .node) {
                    after_val = try self.analyzeSubscriptYieldPaths(
                        NodeIndex.fromInt(ast_node.lhs.payload),
                        incoming,
                        has_emitted_dup_err,
                        depth + 1,
                    );
                }
                if (after_val.isDiverged()) return .{};
                if ((after_val.has_one or after_val.has_many) and !has_emitted_dup_err.*) {
                    has_emitted_dup_err.* = true;
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(node_id),
                        "`subscript` accessor arm cannot execute multiple `yield` statements along one path",
                        "second `yield` reached after an earlier `yield` in the same arm",
                    );
                }
                return .{
                    .has_zero = false,
                    .has_one = after_val.has_zero,
                    .has_many = after_val.has_one or after_val.has_many,
                };
            },
            .block => {
                var cur_state = incoming;
                for (self.getNodeExtraSlice(node_id, false)) |raw_stmt| {
                    const stmt_id = NodeIndex.fromInt(raw_stmt);
                    if (!(try self.evaluateCstNodeCfgAttributesMode(self.ast_arena.getCstOrigin(stmt_id), true))) {
                        continue;
                    }
                    cur_state = try self.analyzeSubscriptYieldPaths(stmt_id, cur_state, has_emitted_dup_err, depth + 1);
                    if (stmt_id.asInt() < self.node_types.len and self.node_types[stmt_id.asInt()] == .never_ty) {
                        cur_state = .{};
                    }
                }
                if (ast_node.rhs.tag == .node) {
                    const tail_id = NodeIndex.fromInt(ast_node.rhs.payload);
                    cur_state = try self.analyzeSubscriptYieldPaths(tail_id, cur_state, has_emitted_dup_err, depth + 1);
                }
                if (node_id.asInt() < self.node_types.len and self.node_types[node_id.asInt()] == .never_ty) {
                    return .{};
                }
                return cur_state;
            },
            .if_expr => {
                const cond_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
                const after_cond = if (!cond_id.isNone())
                    try self.analyzeSubscriptYieldPaths(cond_id, incoming, has_emitted_dup_err, depth + 1)
                else
                    incoming;
                if (after_cond.isDiverged()) return .{};
                const folded_cond = if (!cond_id.isNone()) try self.evalConstIntExpr(cond_id, false) else null;

                if (ast_node.rhs.tag == .node) {
                    const then_id = NodeIndex.fromInt(ast_node.rhs.payload);
                    if (folded_cond) |const_flag| {
                        return if (const_flag != 0)
                            self.analyzeSubscriptYieldPaths(then_id, after_cond, has_emitted_dup_err, depth + 1)
                        else
                            after_cond;
                    }
                    const then_state = try self.analyzeSubscriptYieldPaths(
                        then_id,
                        after_cond,
                        has_emitted_dup_err,
                        depth + 1,
                    );
                    return YieldPathSummary.join(then_state, after_cond);
                }

                const branches = self.getNodeExtraSlice(node_id, true);
                const then_id = if (branches.len >= 1) NodeIndex.fromInt(branches[0]) else .none;
                const else_id = if (branches.len >= 2) NodeIndex.fromInt(branches[1]) else .none;
                if (folded_cond) |const_flag| {
                    return if (const_flag != 0)
                        self.analyzeSubscriptYieldPaths(then_id, after_cond, has_emitted_dup_err, depth + 1)
                    else
                        self.analyzeSubscriptYieldPaths(else_id, after_cond, has_emitted_dup_err, depth + 1);
                }
                const then_state = try self.analyzeSubscriptYieldPaths(then_id, after_cond, has_emitted_dup_err, depth + 1);
                const else_state = try self.analyzeSubscriptYieldPaths(else_id, after_cond, has_emitted_dup_err, depth + 1);
                return YieldPathSummary.join(then_state, else_state);
            },
            .match_expr => {
                const scr_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
                const after_scr = if (!scr_id.isNone())
                    try self.analyzeSubscriptYieldPaths(scr_id, incoming, has_emitted_dup_err, depth + 1)
                else
                    incoming;
                if (after_scr.isDiverged()) return .{};
                const arm_entries = self.getNodeExtraSlice(node_id, true);
                const arm_count = arm_entries.len / 2;
                if (arm_count == 0) return after_scr;
                var joined: YieldPathSummary = .{};
                for (0..arm_count) |arm_i| {
                    const body_id = NodeIndex.fromInt(arm_entries[arm_i * 2 + 1]);
                    const arm_state = try self.analyzeSubscriptYieldPaths(body_id, after_scr, has_emitted_dup_err, depth + 1);
                    joined = YieldPathSummary.join(joined, arm_state);
                }
                return joined;
            },
            .while_stmt, .for_stmt => {
                const body_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;
                const body_state = try self.analyzeSubscriptYieldPaths(body_id, incoming, has_emitted_dup_err, depth + 1);
                const has_body_yield = body_state.has_one or body_state.has_many or
                    (incoming.has_zero and !body_state.has_zero and !body_state.isDiverged());
                if (has_body_yield) {
                    const second_iter = try self.analyzeSubscriptYieldPaths(body_id, body_state, has_emitted_dup_err, depth + 1);
                    return YieldPathSummary.join(incoming, YieldPathSummary.join(body_state, second_iter));
                }
                return YieldPathSummary.join(incoming, body_state);
            },
            .loop_expr => {
                const body_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
                const body_state = try self.analyzeSubscriptYieldPaths(body_id, incoming, has_emitted_dup_err, depth + 1);
                if (!body_state.isDiverged()) {
                    _ = try self.analyzeSubscriptYieldPaths(body_id, body_state, has_emitted_dup_err, depth + 1);
                }
                if (node_id.asInt() < self.node_types.len and self.node_types[node_id.asInt()] == .never_ty) {
                    return .{};
                }
                return body_state;
            },
            else => {
                if (node_id.asInt() < self.node_types.len and self.node_types[node_id.asInt()] == .never_ty) {
                    return .{};
                }
                return incoming;
            },
        }
    }

    /// Type-checks `yield expr;` inside a `subscript` `let` or `inout` accessor arm (`SE-21`).
    fn checkYieldStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        const val_id = if (stmt_node.lhs.tag == .node) NodeIndex.fromInt(stmt_node.lhs.payload) else .none;
        if (!self.is_in_subscript_arm) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(stmt_id),
                "`yield` is only permitted inside a `subscript` `let` or `inout` accessor arm",
                "unexpected `yield` outside `subscript` arm",
            );
            if (!val_id.isNone()) _ = try self.synthExpr(val_id);
            return self.recordNodeType(stmt_id, .unit_ty);
        }
        self.subscript_yield_count += 1;
        if (!val_id.isNone()) {
            const elem_node = self.pool.getNode(self.pool.unwrapUnderlyingType(self.current_subscript_elem_ty));
            const base_elem_ty = if (elem_node.tag == .ref_ty or elem_node.tag == .mut_ref_ty)
                TypeId.fromInt(elem_node.lhs)
            else
                self.current_subscript_elem_ty;
            const val_node = self.ast_arena.getNode(val_id);
            const is_amp_yield = val_node.tag == .unary_expr and !val_node.main_token.isNone() and
                self.token_buffer.getToken(val_node.main_token).kind == .amp;
            const expected_yield_ty = if (elem_node.tag == .ref_ty or elem_node.tag == .mut_ref_ty or is_amp_yield)
                try self.pool.internRef(base_elem_ty, self.is_in_subscript_inout_arm)
            else
                base_elem_ty;
            const yielded_ty = try self.checkExpr(val_id, expected_yield_ty);
            if (!yielded_ty.isError() and self.is_in_subscript_inout_arm) {
                const is_mut_ref_yield = self.pool.getTag(self.pool.unwrapUnderlyingType(yielded_ty)) == .mut_ref_ty;
                if (!is_mut_ref_yield and !self.isMutableAssignablePlace(val_id)) {
                    try self.emitDiagnosticSimple(
                        .e0305_exclusivity_violation,
                        self.getAstNodeSpan(val_id),
                        "`inout` `subscript` arm must `yield` a mutable place expression",
                        "cannot yield immutable or temporary value from `inout` arm",
                    );
                }
            }
        }
        return self.recordNodeType(stmt_id, .unit_ty);
    }

    /// Type-checks `let`/`var` local declarations, including `: Type = Expr`, `let … else { … }` (`E0412`), and `let _ = result` (`E0414`).
    fn checkLocalVarDecl(self: *TypeChecker, decl_id: NodeIndex) anyerror!TypeId {
        const decl_node = self.ast_arena.getNode(decl_id);
        const decl_cst = self.ast_arena.getCstOrigin(decl_id);
        const pat_id = if (decl_node.lhs.tag == .node) NodeIndex.fromInt(decl_node.lhs.payload) else .none;
        const is_var = !decl_node.main_token.isNone() and
            self.token_buffer.getToken(decl_node.main_token).kind == .kw_var;
        const has_recovered_let_mut = !decl_node.main_token.isNone() and
            decl_node.main_token.asInt() + 1 < self.token_buffer.countTokens() and
            self.token_buffer.getToken(TokenIndex.fromInt(decl_node.main_token.asInt() + 1)).kind == .kw_mut;
        const is_mut = is_var or has_recovered_let_mut;

        // Locate optional explicit `: Type`, `= Expr`, and `else { … }` inside `decl_cst`:
        var explicit_ty_ast: NodeIndex = .none;
        var init_expr_ast: NodeIndex = .none;
        var else_block_ast: NodeIndex = .none;

        if (!decl_cst.isNone() and decl_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = decl_cst.asInt();
            const rec = self.cst_arena.getNode(decl_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var colon_cst_pos: ?usize = null;
            var eq_cst_pos: ?usize = null;
            var pat_end_pos: usize = start_idx + 1;
            if (!pat_id.isNone()) {
                const pat_cst = self.ast_arena.getCstOrigin(pat_id);
                if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
                    const pat_rec = self.cst_arena.getNode(pat_cst);
                    pat_end_pos = @min(
                        @as(usize, pat_cst.asInt()) + @max(@as(usize, pat_rec.subtree_size), 1),
                        end_idx,
                    );
                }
            }

            var cur = pat_end_pos;
            while (cur < end_idx) {
                const sub_id = CstNodeIndex.fromInt(@intCast(cur));
                const sub = self.cst_arena.getNode(sub_id);
                if (sub.kind == .let_else_branch) {
                    const branch_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    else_block_ast = self.findFirstAstInCstRange(cur + 1, branch_end);
                    cur = branch_end;
                    continue;
                }
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (is_leaf and !sub.flags.is_missing_or_injected and
                    !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const kind = self.token_buffer.getToken(sub.token).kind;
                    if (kind == .colon and colon_cst_pos == null and eq_cst_pos == null) {
                        colon_cst_pos = cur;
                    } else if (kind == .eq and eq_cst_pos == null) {
                        eq_cst_pos = cur;
                    }
                }
                cur += 1;
            }

            if (colon_cst_pos) |c_pos| {
                const search_end = eq_cst_pos orelse end_idx;
                explicit_ty_ast = self.findFirstAstInCstRange(c_pos + 1, search_end);
            }
            if (eq_cst_pos != null and decl_node.rhs.tag == .node) {
                init_expr_ast = NodeIndex.fromInt(decl_node.rhs.payload);
            } else if (colon_cst_pos != null and eq_cst_pos == null and decl_node.rhs.tag == .node) {
                explicit_ty_ast = NodeIndex.fromInt(decl_node.rhs.payload);
            }
        } else if (decl_node.rhs.tag == .node) {
            const rhs_id = NodeIndex.fromInt(decl_node.rhs.payload);
            if (isTypeAstTag(self.ast_arena.getNode(rhs_id).tag)) {
                explicit_ty_ast = rhs_id;
            } else {
                init_expr_ast = rhs_id;
            }
        }

        var declared_ty: TypeId = .err_ty;
        if (!explicit_ty_ast.isNone()) {
            declared_ty = try self.resolveTypeAst(explicit_ty_ast);
        }

        var val_ty: TypeId = declared_ty;
        if (!init_expr_ast.isNone()) {
            if (!declared_ty.isError()) {
                val_ty = try self.checkExpr(init_expr_ast, declared_ty);
            } else {
                const raw_init_ty = try self.synthExpr(init_expr_ast);
                val_ty = self.materializeUntypedType(raw_init_ty);
            }
        }

        // [1] Reject bare `let _ = fallible_expr;` without `catch` (`E0414`, `DR-07` Section 2.4):
        if (!pat_id.isNone() and !init_expr_ast.isNone() and !val_ty.isError()) {
            const init_ast = self.ast_arena.getNode(init_expr_ast);
            const is_catch_handled = init_ast.tag == .binary_expr and
                !init_ast.main_token.isNone() and
                self.token_buffer.getToken(init_ast.main_token).kind == .kw_catch;
            if (self.hasWildcardDiscardOfResult(pat_id, val_ty) or
                (self.ast_arena.getNode(pat_id).tag == .wildcard_pat and
                    !is_catch_handled and
                    self.isMustUseTypeOrCall(init_expr_ast, val_ty)))
            {
                try self.emitDiagnosticSimple(
                    .e0414_bare_wildcard_result_discard,
                    self.getAstNodeSpan(decl_id),
                    "discarding `@must_use` or `Result[T, E]` with `let _ = …` is forbidden",
                    "handle the error explicitly with `let _ = expr catch {};` or propagate with `?`",
                );
            }
        }

        // [2] Verify `let Pat = Expr else { … };` diverging block (`E0412`, `DR-07` Section 2.2):
        if (!else_block_ast.isNone()) {
            const else_ty = try self.checkBlock(else_block_ast, .unit_ty, false);
            if (!else_ty.isError() and else_ty != .never_ty) {
                try self.emitDiagnosticSimple(
                    .e0412_let_else_not_diverging,
                    self.getAstNodeSpan(else_block_ast),
                    "`let … else` fallback block must diverge (`never`)",
                    "this `else` block falls through; add `return`, `break`, `continue`, or a diverging call",
                );
            }
        }

        // [3] Bind pattern variables in `self.current_scope` and validate any leading `@Schema` attributes:
        const sym_count_before = self.sym_table.countSymbols();
        if (!pat_id.isNone()) {
            try self.bindPattern(
                pat_id,
                val_ty,
                is_mut,
                self.isScrutineeMutRefBindable(init_expr_ast, val_ty),
            );
        }
        const sym_count_after = self.sym_table.countSymbols();
        if (sym_count_after > sym_count_before and !init_expr_ast.isNone()) {
            const bound_mod_idx = SymbolIndex.fromInt(@intCast(sym_count_before));
            self.bindCImportModuleToSymbolIfPresent(bound_mod_idx, init_expr_ast);
        }
        if (sym_count_after > sym_count_before and !decl_cst.isNone() and
            decl_cst.asInt() < self.cst_arena.countNodes())
        {
            const first_bound_idx = SymbolIndex.fromInt(@intCast(sym_count_before));
            const start_idx: usize = decl_cst.asInt();
            const rec = self.cst_arena.getNode(decl_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const leaf_kind = self.token_buffer.getToken(sub.token).kind;
                    if (leaf_kind == .kw_let or leaf_kind == .kw_var) break;
                }
                if (sub.kind == .attribute) {
                    const attr_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    try self.validateSingleAttributeCst(first_bound_idx, .NONE, cur, attr_end);
                    if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                }
            }
        }
        return self.recordNodeType(decl_id, .unit_ty);
    }

    /// Returns `true` if `pat_id` discards a `Result[T, E]` via `_` (directly or nested inside a tuple/slice/`@` pattern).
    fn hasWildcardDiscardOfResult(self: *const TypeChecker, pat_id: NodeIndex, val_ty: TypeId) bool {
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes() or val_ty.isError()) return false;
        const pat_node = self.ast_arena.getNode(pat_id);
        if (pat_node.tag == .wildcard_pat) {
            return self.pool.getTag(val_ty) == .result_ty;
        }
        if (pat_node.tag == .at_pat and pat_node.rhs.tag == .node) {
            return self.hasWildcardDiscardOfResult(NodeIndex.fromInt(pat_node.rhs.payload), val_ty);
        }
        if (pat_node.tag == .slice_pat) {
            const unwrapped = self.unwrapRefType(val_ty);
            const scr_node = self.pool.getNode(unwrapped);
            if (scr_node.tag == .slice_ty or scr_node.tag == .array_ty) {
                const elem_ty = TypeId.fromInt(scr_node.lhs);
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    const sub_id = NodeIndex.fromInt(raw_sub);
                    if (self.isSliceRestPatternNode(sub_id)) continue;
                    if (self.hasWildcardDiscardOfResult(sub_id, elem_ty)) return true;
                }
            }
            return false;
        }
        if (pat_node.tag == .tuple_pat) {
            const sub_pats = self.getNodeExtraSlice(pat_id, false);
            if (sub_pats.len == 1 and !hasShallowCommaInTupleCst(
                self.cst_arena,
                self.token_buffer,
                self.ast_arena.getCstOrigin(pat_id),
            )) {
                return self.hasWildcardDiscardOfResult(NodeIndex.fromInt(sub_pats[0]), val_ty);
            }
            if (self.pool.getTag(val_ty) == .tuple_ty) {
                const elem_types = self.pool.getTupleElements(val_ty);
                for (sub_pats, 0..) |raw_sub, i| {
                    if (i < elem_types.len) {
                        if (self.hasWildcardDiscardOfResult(NodeIndex.fromInt(raw_sub), TypeId.fromInt(elem_types[i]))) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /// Type-checks `defer` and `errdefer |err|` statements (`DR-07` Section 2.3).
    fn checkDeferStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        const is_errdefer = !stmt_node.main_token.isNone() and
            self.token_buffer.getToken(stmt_node.main_token).kind == .kw_errdefer;

        const saved_scope = self.current_scope;
        const defer_scope = try self.sym_table.scope_arena.allocScope(
            .catch_or_errdefer_scope,
            self.current_scope,
            .NONE,
            self.file_id,
            .{},
        );
        self.current_scope = defer_scope;
        defer self.current_scope = saved_scope;

        if (is_errdefer) {
            const fn_ret_node = self.pool.getNode(self.pool.unwrapUnderlyingType(self.current_fn_ret_ty));
            const err_payload_ty: TypeId = if (fn_ret_node.tag == .result_ty)
                TypeId.fromInt(fn_ret_node.rhs)
            else if (fn_ret_node.tag == .optional_ty)
                .unit_ty
            else blk: {
                if (!self.current_fn_ret_ty.isError()) {
                    try self.emitDiagnosticSimple(
                        .e0410_try_outside_fallible_fn,
                        self.getAstNodeSpan(stmt_id),
                        "`errdefer` is only permitted inside functions returning `Result[T, E]` or `T?`",
                        "enclosing function does not return a fallible type",
                    );
                }
                break :blk .err_ty;
            };

            if (stmt_node.lhs.tag == .token) {
                const cap_tok = TokenIndex.fromInt(stmt_node.lhs.payload);
                const cap_str = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, cap_tok);
                if (cap_str.len > 0 and !std.mem.eql(u8, cap_str, "_")) {
                    const cap_sym = try self.interner.intern(cap_str);
                    _ = try self.sym_table.defineSymbol(.{
                        .name = cap_sym,
                        .name_text = self.interner.get(cap_sym),
                        .kind = .local_var_sym,
                        .namespace = .value_ns,
                        .visibility = .private,
                        .flags = .{},
                        .scope_id = defer_scope,
                        .decl_span = self.token_buffer.getTokenSpan(self.file_id, cap_tok),
                        .type_id = err_payload_ty,
                    }, self.diagnostic_sink);
                }
            }
        }

        if (stmt_node.rhs.tag == .node) {
            // Forbid `return`, uncaught `?`, and outer-loop `break`/`continue` inside `defer` / `errdefer`:
            const saved_inner_loop_depth = self.defer_inner_loop_depth;
            self.defer_depth += 1;
            self.defer_inner_loop_depth = 0;
            defer {
                self.defer_depth -= 1;
                self.defer_inner_loop_depth = saved_inner_loop_depth;
            }

            const body_id = NodeIndex.fromInt(stmt_node.rhs.payload);
            if (self.ast_arena.getNode(body_id).tag == .block) {
                _ = try self.checkBlock(body_id, .unit_ty, true);
            } else {
                const expr_ty = try self.synthExpr(body_id);
                if (!expr_ty.isError() and expr_ty != .unit_ty and expr_ty != .never_ty) {
                    if (self.isMustUseTypeOrCall(body_id, expr_ty)) {
                        try self.emitUnhandledMustUseError(self.getAstNodeSpan(body_id), expr_ty);
                    }
                }
            }
        }
        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, defer_scope, self.interner, self.diagnostic_sink);
        return self.recordNodeType(stmt_id, .unit_ty);
    }

    /// Type-checks `return [expr];` against `self.current_fn_ret_ty`, rejecting `return` inside `defer` / `errdefer`.
    fn checkReturnStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        if (self.defer_depth > 0) {
            try self.emitDiagnosticSimple(
                .e0412_let_else_not_diverging,
                self.getAstNodeSpan(stmt_id),
                "`return` is forbidden inside `defer` and `errdefer` cleanup blocks",
                "cannot return from an enclosing function while inside `defer` / `errdefer`",
            );
        }
        const stmt_node = self.ast_arena.getNode(stmt_id);
        if (stmt_node.lhs.tag == .node) {
            const ret_expr_id = NodeIndex.fromInt(stmt_node.lhs.payload);
            const checked_ret_ty = try self.checkExpr(ret_expr_id, self.current_fn_ret_ty);
            if (self.nursery_scope_depth != null) {
                const fallback_ret = if (ret_expr_id.asInt() < self.node_types.len)
                    self.node_types[ret_expr_id.asInt()]
                else
                    TypeId.err_ty;
                try self.rejectNurseryHandleEscapeType(
                    self.getAstNodeSpan(ret_expr_id),
                    if (!checked_ret_ty.isError()) checked_ret_ty else fallback_ret,
                );
            }
        } else if (!self.current_fn_ret_ty.isError() and self.current_fn_ret_ty != .unit_ty) {
            try self.emitTypeMismatch(self.getAstNodeSpan(stmt_id), self.current_fn_ret_ty, .unit_ty);
        }
        return self.recordNodeType(stmt_id, .never_ty);
    }

    /// Interns an optional `:label` token (stripping any leading `:`) into `SymbolId`.
    fn internLoopLabelToken(self: *TypeChecker, label_tok: TokenIndex) !SymbolId {
        if (label_tok.isNone() or label_tok.asInt() >= self.token_buffer.countTokens()) return .none;
        const raw_lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, label_tok);
        const clean_lexeme = if (raw_lexeme.len > 0 and raw_lexeme[0] == ':') raw_lexeme[1..] else raw_lexeme;
        if (clean_lexeme.len == 0) return .none;
        return self.interner.intern(clean_lexeme);
    }

    /// Resolves the target `LoopFrame` for `break` or `continue`, validating `:label` (`E0403`),
    /// `defer` bounds (`E0412`), and labeled `match` rules (`E0437`).
    fn resolveTargetLoopFrame(
        self: *TypeChecker,
        stmt_id: NodeIndex,
        label_op: PackedOperand,
        is_break: bool,
    ) !?*LoopFrame {
        const kw_name = if (is_break) "break" else "continue";
        if (label_op.tag == .token) {
            const label_tok = TokenIndex.fromInt(label_op.payload);
            const label_sym = try self.internLoopLabelToken(label_tok);
            if (!label_sym.isNone()) {
                var idx: usize = self.loop_frame_depth;
                while (idx > 0) {
                    idx -= 1;
                    if (self.loop_frames[idx].label == label_sym) {
                        if (is_break and self.loop_frames[idx].is_labeled_match) {
                            try self.emitDiagnosticSimple(
                                .e0437_invalid_labeled_match_continue,
                                self.getAstNodeSpan(stmt_id),
                                "cannot `break` from a labeled `match`; " ++
                                    "write `continue :label next_state` to re-dispatch or return an arm value directly",
                                "`break` cannot target a labeled `match`",
                            );
                            return null;
                        }
                        if (self.defer_depth > self.loop_frames[idx].defer_depth_at_entry) {
                            var defer_buf: [128]u8 = undefined;
                            const defer_msg = std.fmt.bufPrint(
                                &defer_buf,
                                "`{s}` cannot escape an enclosing `defer` or `errdefer` block",
                                .{kw_name},
                            ) catch "control-flow jump out of `defer` / `errdefer` is forbidden";
                            try self.emitDiagnosticSimple(
                                .e0412_let_else_not_diverging,
                                self.getAstNodeSpan(stmt_id),
                                defer_msg,
                                "control-flow jump out of `defer` / `errdefer` is forbidden",
                            );
                        }
                        return &self.loop_frames[idx];
                    }
                }
                const label_text = self.interner.get(label_sym);
                var msg_buf: [160]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "undeclared loop or `match` label `:{s}` in `{s}`",
                    .{ label_text, kw_name },
                ) catch "undeclared loop or `match` label";
                try self.emitDiagnosticSimple(
                    .e0403_unresolved_symbol,
                    self.token_buffer.getTokenSpan(self.file_id, label_tok),
                    msg,
                    "no enclosing `for`, `while`, `loop`, or `match` carries this `:label`",
                );
                return null;
            }
        }

        var nearest_loop_idx: ?usize = null;
        var scan_idx: usize = self.loop_frame_depth;
        while (scan_idx > 0) {
            scan_idx -= 1;
            if (!self.loop_frames[scan_idx].is_labeled_match) {
                nearest_loop_idx = scan_idx;
                break;
            }
        }

        const target_idx = nearest_loop_idx orelse {
            if (self.loop_frame_depth > 0) {
                var match_buf: [160]u8 = undefined;
                const match_msg = std.fmt.bufPrint(
                    &match_buf,
                    "unlabeled `{s}` cannot target a labeled `match`; write `continue :label next_state`",
                    .{kw_name},
                ) catch "unlabeled jump cannot target labeled `match`";
                try self.emitDiagnosticSimple(
                    .e0437_invalid_labeled_match_continue,
                    self.getAstNodeSpan(stmt_id),
                    match_msg,
                    "unlabeled control-flow jump inside labeled `match`",
                );
                return null;
            }
            var out_buf: [128]u8 = undefined;
            const out_msg = std.fmt.bufPrint(
                &out_buf,
                "`{s}` cannot be used outside of an enclosing `for`, `while`, or `loop`",
                .{kw_name},
            ) catch "loop control-flow jump outside of loop";
            try self.emitDiagnosticSimple(
                .e0412_let_else_not_diverging,
                self.getAstNodeSpan(stmt_id),
                out_msg,
                "not inside a loop",
            );
            return null;
        };

        const top_frame = &self.loop_frames[target_idx];
        if (self.defer_depth > top_frame.defer_depth_at_entry) {
            var defer_buf: [128]u8 = undefined;
            const defer_msg = std.fmt.bufPrint(
                &defer_buf,
                "`{s}` cannot escape an enclosing `defer` or `errdefer` block",
                .{kw_name},
            ) catch "control-flow jump out of `defer` / `errdefer` is forbidden";
            try self.emitDiagnosticSimple(
                .e0412_let_else_not_diverging,
                self.getAstNodeSpan(stmt_id),
                defer_msg,
                "control-flow jump out of `defer` / `errdefer` is forbidden",
            );
        }
        return top_frame;
    }

    /// Type-checks `break [:label] [expr];`, unifying value breaks and rejecting mixed bare/value breaks (`SE-05`, `SE-06`).
    fn checkBreakStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        const target_opt = try self.resolveTargetLoopFrame(stmt_id, stmt_node.rhs, true);
        if (stmt_node.lhs.tag == .node) {
            const val_id = NodeIndex.fromInt(stmt_node.lhs.payload);
            if (target_opt) |frame| {
                if (frame.is_comptime_for) {
                    try self.emitDiagnosticSimple(
                        .e0412_let_else_not_diverging,
                        self.getAstNodeSpan(stmt_id),
                        "cannot break with a value from `comptime for`",
                        "`comptime for` unrolls at compile time and cannot evaluate to an optional break value",
                    );
                    _ = try self.synthExpr(val_id);
                    return self.recordNodeType(stmt_id, .never_ty);
                }
                const val_tag = self.ast_arena.getNode(val_id).tag;
                if (!frame.break_ty.isError() and frame.break_ty != .never_ty) {
                    if (val_tag == .contextual_variant or val_tag == .closure_expr) {
                        if (frame.has_bare_break) {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                self.getAstNodeSpan(stmt_id),
                                "cannot mix bare `break;` and value `break expr;` targeting the same loop",
                                "previous bare `break;` expects unit loop exit, found value `break`",
                            );
                        }
                        frame.has_value_break = true;
                        _ = try self.checkExpr(val_id, frame.break_ty);
                    } else {
                        const synth_brk_ty = try self.synthExpr(val_id);
                        if (synth_brk_ty != .never_ty) {
                            if (frame.has_bare_break) {
                                try self.emitDiagnosticSimple(
                                    .e0401_type_mismatch,
                                    self.getAstNodeSpan(stmt_id),
                                    "cannot mix bare `break;` and value `break expr;` targeting the same loop",
                                    "previous bare `break;` expects unit loop exit, found value `break`",
                                );
                            }
                            frame.has_value_break = true;
                            if (!synth_brk_ty.isError()) {
                                if (try self.checkTypeCompatibility(val_id, synth_brk_ty, frame.break_ty)) {
                                    _ = self.recordNodeType(val_id, frame.break_ty);
                                } else {
                                    _ = self.recordNodeType(val_id, .err_ty);
                                }
                            }
                        }
                    }
                } else {
                    const brk_ty = try self.synthExpr(val_id);
                    if (brk_ty != .never_ty) {
                        if (frame.has_bare_break) {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                self.getAstNodeSpan(stmt_id),
                                "cannot mix bare `break;` and value `break expr;` targeting the same loop",
                                "previous bare `break;` expects unit loop exit, found value `break`",
                            );
                        }
                        frame.has_value_break = true;
                        frame.break_ty = self.materializeUntypedType(brk_ty);
                    }
                }
            } else {
                _ = try self.synthExpr(val_id);
            }
        } else if (target_opt) |frame| {
            if (frame.has_value_break) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(stmt_id),
                    "cannot mix bare `break;` and value `break expr;` targeting the same loop",
                    "loop already yields a value via `break expr;`",
                );
            }
            frame.has_bare_break = true;
            if (frame.break_ty == .never_ty) {
                frame.break_ty = .unit_ty;
            }
        }
        return self.recordNodeType(stmt_id, .never_ty);
    }

    /// Type-checks `continue [:label] [expr];`, validating `:label`, `defer` boundaries, and `SE-23` labeled `match` dispatch (`E0437`).
    fn checkContinueStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        if (stmt_node.rhs.tag == .node) {
            const val_id = NodeIndex.fromInt(stmt_node.rhs.payload);
            if (stmt_node.lhs.tag != .token) {
                try self.emitDiagnosticSimple(
                    .e0437_invalid_labeled_match_continue,
                    self.getAstNodeSpan(stmt_id),
                    "`continue` with a replacement value requires an explicit `:label` targeting an enclosing labeled `match`",
                    "missing `:label` on valued `continue`",
                );
                _ = try self.synthExpr(val_id);
                return self.recordNodeType(stmt_id, .never_ty);
            }
            if (try self.resolveTargetLoopFrame(stmt_id, stmt_node.lhs, false)) |frame| {
                if (!frame.is_labeled_match) {
                    try self.emitDiagnosticSimple(
                        .e0437_invalid_labeled_match_continue,
                        self.getAstNodeSpan(stmt_id),
                        "loop `continue` does not accept a value; only labeled `match` supports `continue :label expr`",
                        "cannot pass value to loop `continue`",
                    );
                    _ = try self.synthExpr(val_id);
                } else {
                    _ = try self.checkExpr(val_id, frame.match_scrutinee_ty);
                    try self.labeled_match_continues.put(self.allocator, stmt_id.asInt(), frame.match_ast_node);
                }
            } else {
                _ = try self.synthExpr(val_id);
            }
            return self.recordNodeType(stmt_id, .never_ty);
        }

        if (try self.resolveTargetLoopFrame(stmt_id, stmt_node.lhs, false)) |frame| {
            if (frame.is_labeled_match) {
                try self.emitDiagnosticSimple(
                    .e0437_invalid_labeled_match_continue,
                    self.getAstNodeSpan(stmt_id),
                    "`continue` targeting a labeled `match` requires a replacement scrutinee expression (`continue :label next_state`)",
                    "missing replacement scrutinee expression after `continue :label`",
                );
            }
        }
        return self.recordNodeType(stmt_id, .never_ty);
    }

    /// Type-checks `for [:label] [& [mut]] pat [, idx] in iter { … }` in statement or expression position (`SE-05`, `SE-06`).
    fn synthOrCheckForExpr(
        self: *TypeChecker,
        stmt_id: NodeIndex,
        expected_ty: TypeId,
    ) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        const is_comptime_for = !stmt_node.main_token.isNone() and
            self.token_buffer.getToken(stmt_node.main_token).kind == .kw_comptime;
        const extra = self.getNodeExtraSlice(stmt_id, false);
        const pat_id = if (extra.len >= 1) NodeIndex.fromInt(extra[0]) else .none;
        const iter_id = if (extra.len >= 2) NodeIndex.fromInt(extra[1]) else .none;
        const index_tok = if (extra.len >= 3) TokenIndex.fromInt(extra[2]) else .none;
        const label_tok = if (extra.len >= 4) TokenIndex.fromInt(extra[3]) else .none;
        const ref_mode: u32 = if (extra.len >= 5) extra[4] else 0;

        const saved_scope = self.current_scope;
        var elem_ty: TypeId = .err_ty;
        if (!iter_id.isNone()) {
            const iter_ty = eval_iter: {
                const prev_pos = self.is_direct_positive_cond;
                const prev_walrus = self.is_dominating_walrus_pos;
                self.is_direct_positive_cond = false;
                self.is_dominating_walrus_pos = false;
                defer {
                    self.is_direct_positive_cond = prev_pos;
                    self.is_dominating_walrus_pos = prev_walrus;
                }
                if (is_comptime_for) {
                    const prev_pure_depth = self.pure_comptime_depth;
                    const prev_boundary = self.comptime_boundary_scope_depth;
                    if (prev_pure_depth == 0) {
                        self.comptime_boundary_scope_depth = if (saved_scope.isNone())
                            0
                        else
                            self.sym_table.scope_arena.getScope(saved_scope).depth;
                    }
                    self.pure_comptime_depth = prev_pure_depth + 1;
                    defer {
                        self.pure_comptime_depth = prev_pure_depth;
                        self.comptime_boundary_scope_depth = prev_boundary;
                    }
                    break :eval_iter try self.synthExpr(iter_id);
                }
                break :eval_iter try self.synthExpr(iter_id);
            };

            if (ref_mode == 2 and !iter_ty.isError()) {
                const iter_tag = self.pool.getTag(self.pool.unwrapUnderlyingType(iter_ty));
                const is_valid_mut_iter = iter_tag == .mut_ref_ty or
                    (iter_tag != .ref_ty and
                        !(iter_tag == .raw_ptr_ty and self.pool.getNode(self.pool.unwrapUnderlyingType(iter_ty)).rhs == 0) and
                        (!self.isAssignablePlace(iter_id) or self.isMutableAssignablePlace(iter_id)));
                if (!is_valid_mut_iter) {
                    try self.emitDiagnosticSimple(
                        .e0305_exclusivity_violation,
                        self.getAstNodeSpan(iter_id),
                        "cannot iterate by `&mut` over an immutable collection or `&T` borrow",
                        "expected `&mut` collection or mutable `var` container for `for &mut` loop",
                    );
                }
            }

            const unwrapped_iter = self.unwrapRefType(iter_ty);
            const iter_node = self.pool.getNode(unwrapped_iter);
            const raw_elem_ty: TypeId = switch (iter_node.tag) {
                .slice_ty, .soa_slice_ty, .array_ty, .soa_array_ty => TypeId.fromInt(iter_node.lhs),
                .tuple_ty => blk: {
                    const elems = self.pool.getTupleElements(unwrapped_iter);
                    break :blk if (elems.len > 0) TypeId.fromInt(elems[0]) else .unit_ty;
                },
                .struct_ty => blk: {
                    const gen_args = self.pool.getGenericTypeArgs(unwrapped_iter);
                    if (gen_args.len >= 1) break :blk TypeId.fromInt(gen_args[0]);
                    break :blk self.materializeUntypedType(unwrapped_iter);
                },
                else => self.materializeUntypedType(unwrapped_iter),
            };
            elem_ty = if (ref_mode == 1 and !raw_elem_ty.isError())
                try self.pool.internRef(raw_elem_ty, false)
            else if (ref_mode == 2 and !raw_elem_ty.isError())
                try self.pool.internRef(raw_elem_ty, true)
            else
                raw_elem_ty;
        }

        const loop_scope = try self.sym_table.scope_arena.allocScope(
            .loop_scope,
            saved_scope,
            .NONE,
            self.file_id,
            .{},
        );
        self.current_scope = loop_scope;
        defer self.current_scope = saved_scope;

        if (self.defer_depth > 0) self.defer_inner_loop_depth += 1;
        defer if (self.defer_depth > 0) {
            self.defer_inner_loop_depth -= 1;
        };

        var initial_break_ty: TypeId = .never_ty;
        if (!expected_ty.isError()) {
            const exp_unwrapped = self.pool.unwrapUnderlyingType(expected_ty);
            if (self.pool.getTag(exp_unwrapped) == .optional_ty) {
                initial_break_ty = TypeId.fromInt(self.pool.getNode(exp_unwrapped).lhs);
            }
        }
        const label_sym = try self.internLoopLabelToken(label_tok);
        const pushed_frame = self.loop_frame_depth < self.loop_frames.len;
        if (pushed_frame) {
            self.loop_frames[self.loop_frame_depth] = .{
                .label = label_sym,
                .break_ty = initial_break_ty,
                .is_unconditional_loop = false,
                .is_comptime_for = is_comptime_for,
                .defer_depth_at_entry = self.defer_depth,
            };
            self.loop_frame_depth += 1;
        }

        if (!pat_id.isNone()) {
            const prev_binding_ct = self.is_binding_comptime;
            if (is_comptime_for) self.is_binding_comptime = true;
            defer self.is_binding_comptime = prev_binding_ct;
            try self.bindPattern(
                pat_id,
                elem_ty,
                false,
                ref_mode == 2 or self.pool.getTag(self.pool.unwrapUnderlyingType(elem_ty)) == .mut_ref_ty,
            );
        }
        if (!index_tok.isNone() and index_tok.asInt() < self.token_buffer.countTokens()) {
            const idx_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, index_tok);
            if (idx_name.len > 0 and !std.mem.eql(u8, idx_name, "_")) {
                const idx_sym_id = try self.interner.intern(idx_name);
                _ = try self.sym_table.defineSymbol(.{
                    .name = idx_sym_id,
                    .name_text = self.interner.get(idx_sym_id),
                    .kind = .local_let_sym,
                    .namespace = .value_ns,
                    .visibility = .private,
                    .flags = .{
                        .is_comptime = is_comptime_for or self.pure_comptime_depth > 0,
                    },
                    .scope_id = loop_scope,
                    .decl_span = self.token_buffer.getTokenSpan(self.file_id, index_tok),
                    .type_id = .usize_ty,
                }, self.diagnostic_sink);
            }
        }
        if (stmt_node.rhs.tag == .node) {
            _ = try self.checkBlock(NodeIndex.fromInt(stmt_node.rhs.payload), .unit_ty, true);
        }

        var result_ty: TypeId = .unit_ty;
        if (pushed_frame) {
            self.loop_frame_depth -= 1;
            const popped = self.loop_frames[self.loop_frame_depth];
            if (popped.has_value_break) {
                const inner_ty = if (popped.break_ty.isError() or popped.break_ty == .never_ty)
                    .unit_ty
                else
                    self.materializeUntypedType(popped.break_ty);
                result_ty = try self.pool.internOptional(inner_ty);
            }
        }
        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, loop_scope, self.interner, self.diagnostic_sink);
        return self.recordNodeType(stmt_id, result_ty);
    }

    /// Type-checks `while [:label] cond { … }` in statement or expression position (`SE-01`, `SE-02`, `SE-05`, `SE-06`).
    fn synthOrCheckWhileExpr(
        self: *TypeChecker,
        stmt_id: NodeIndex,
        expected_ty: TypeId,
    ) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        var cond_id: NodeIndex = .none;
        var label_tok: TokenIndex = .none;
        if (stmt_node.lhs.tag == .extra) {
            const pair = self.getNodeExtraSlice(stmt_id, false);
            if (pair.len >= 1) cond_id = NodeIndex.fromInt(pair[0]);
            if (pair.len >= 2) label_tok = TokenIndex.fromInt(pair[1]);
        } else if (stmt_node.lhs.tag == .node) {
            cond_id = NodeIndex.fromInt(stmt_node.lhs.payload);
        }

        const saved_scope = self.current_scope;
        const cond_scope = try self.sym_table.scope_arena.allocScope(
            .condition_scope,
            saved_scope,
            .NONE,
            self.file_id,
            .{},
        );
        const loop_scope = try self.sym_table.scope_arena.allocScope(
            .loop_scope,
            cond_scope,
            .NONE,
            self.file_id,
            .{},
        );
        defer self.current_scope = saved_scope;

        if (self.defer_depth > 0) self.defer_inner_loop_depth += 1;
        defer if (self.defer_depth > 0) {
            self.defer_inner_loop_depth -= 1;
        };

        var initial_break_ty: TypeId = .never_ty;
        if (!expected_ty.isError()) {
            const exp_unwrapped = self.pool.unwrapUnderlyingType(expected_ty);
            if (self.pool.getTag(exp_unwrapped) == .optional_ty) {
                initial_break_ty = TypeId.fromInt(self.pool.getNode(exp_unwrapped).lhs);
            }
        }
        const label_sym = try self.internLoopLabelToken(label_tok);
        const pushed_frame = self.loop_frame_depth < self.loop_frames.len;
        if (pushed_frame) {
            self.loop_frames[self.loop_frame_depth] = .{
                .label = label_sym,
                .break_ty = initial_break_ty,
                .is_unconditional_loop = false,
                .is_comptime_for = false,
                .defer_depth_at_entry = self.defer_depth,
            };
            self.loop_frame_depth += 1;
        }

        self.current_scope = cond_scope;
        if (!cond_id.isNone()) {
            try self.checkConditionHeader(cond_id);
        }

        self.current_scope = loop_scope;
        if (stmt_node.rhs.tag == .node) {
            _ = try self.checkBlock(NodeIndex.fromInt(stmt_node.rhs.payload), .unit_ty, true);
        }

        var result_ty: TypeId = .unit_ty;
        if (pushed_frame) {
            self.loop_frame_depth -= 1;
            const popped = self.loop_frames[self.loop_frame_depth];
            if (popped.has_value_break) {
                const inner_ty = if (popped.break_ty.isError() or popped.break_ty == .never_ty)
                    .unit_ty
                else
                    self.materializeUntypedType(popped.break_ty);
                result_ty = try self.pool.internOptional(inner_ty);
            }
        }
        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, loop_scope, self.interner, self.diagnostic_sink);
        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, cond_scope, self.interner, self.diagnostic_sink);
        return self.recordNodeType(stmt_id, result_ty);
    }

    /// Type-checks `loop [:label] { … }`, returning `T` on value break, `()` on bare break, or `never` (`SE-06`).
    fn synthOrCheckLoopExpr(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_ty: TypeId,
    ) anyerror!TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const label_tok = if (ast_node.rhs.tag == .token) TokenIndex.fromInt(ast_node.rhs.payload) else .none;
        const label_sym = try self.internLoopLabelToken(label_tok);
        const initial_break_ty: TypeId = if (!expected_ty.isError() and expected_ty != .unit_ty)
            expected_ty
        else
            .never_ty;

        if (self.defer_depth > 0) self.defer_inner_loop_depth += 1;
        defer if (self.defer_depth > 0) {
            self.defer_inner_loop_depth -= 1;
        };

        const pushed_frame = self.loop_frame_depth < self.loop_frames.len;
        if (pushed_frame) {
            self.loop_frames[self.loop_frame_depth] = .{
                .label = label_sym,
                .break_ty = initial_break_ty,
                .is_unconditional_loop = true,
                .defer_depth_at_entry = self.defer_depth,
            };
            self.loop_frame_depth += 1;
        }

        if (ast_node.lhs.tag == .node) {
            _ = try self.checkBlock(NodeIndex.fromInt(ast_node.lhs.payload), .unit_ty, false);
        }

        var result_ty: TypeId = .never_ty;
        if (pushed_frame) {
            self.loop_frame_depth -= 1;
            const popped = self.loop_frames[self.loop_frame_depth];
            if (popped.has_value_break) {
                result_ty = self.materializeUntypedType(popped.break_ty);
            } else if (popped.has_bare_break) {
                result_ty = .unit_ty;
            }
        }
        return self.recordNodeType(expr_id, result_ty);
    }

    /// Static place path descriptor for `SE-15` parallel destructuring disjointness checks.
    const StaticPlacePath = struct {
        root_sym: SymbolIndex = .none,
        steps: [8]u64 = .{ 0, 0, 0, 0, 0, 0, 0, 0 },
        step_len: u8 = 0,
        span: Span = .{ .file_id = .none, .start_byte = 0, .end_byte = 0 },
    };

    /// Returns `true` if `expr_id` is a syntactically assignable lvalue place (not an rvalue literal, binary op, or call).
    fn isAssignablePlace(self: *const TypeChecker, expr_id: NodeIndex) bool {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return true;
        const node = self.ast_arena.getNode(expr_id);
        return switch (node.tag) {
            .wildcard_pat, .expr_hole, .stmt_hole, .incomplete_member_access => true,
            .ident_expr => blk: {
                if (expr_id.asInt() >= self.node_symbols.len) break :blk true;
                const sym_idx = self.node_symbols[expr_id.asInt()];
                if (sym_idx.isNone()) break :blk true;
                const resolved_idx = self.unwrapAliasSymbolIdx(sym_idx);
                const kind = self.sym_table.getSymbol(resolved_idx).kind;
                break :blk kind == .local_let_sym or kind == .local_var_sym or
                    kind == .param_sym or kind == .extern_static_sym;
            },
            .self_val, .deref_expr => true,
            .field_access => if (node.lhs.tag == .node) blk: {
                const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                if (lhs_id.asInt() < self.node_types.len) {
                    const base_tag = self.pool.getTag(self.pool.unwrapUnderlyingType(self.node_types[lhs_id.asInt()]));
                    if (base_tag == .ref_ty or base_tag == .mut_ref_ty) break :blk true;
                }
                break :blk self.isAssignablePlace(lhs_id);
            } else false,
            .index_expr => if (node.lhs.tag == .node) blk: {
                const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                if (lhs_id.asInt() < self.node_types.len) {
                    const base_tag = self.pool.getTag(self.pool.unwrapUnderlyingType(self.node_types[lhs_id.asInt()]));
                    if (base_tag == .ref_ty or base_tag == .mut_ref_ty or
                        base_tag == .slice_ty or base_tag == .soa_slice_ty) break :blk true;
                }
                if (expr_id.asInt() < self.node_symbols.len and !self.node_symbols[expr_id.asInt()].isNone()) {
                    break :blk true;
                }
                break :blk self.isAssignablePlace(lhs_id);
            } else false,
            .tuple_lit => blk: {
                const elems = self.getNodeExtraSlice(expr_id, false);
                if (elems.len == 1 and !hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(expr_id),
                )) {
                    break :blk self.isAssignablePlace(NodeIndex.fromInt(elems[0]));
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Returns `true` if `expr_id` is a mutable lvalue place (`var` root, `&mut`/`&out` deref, `*mut` deref, or `inout` `subscript`).
    fn isMutableAssignablePlace(self: *const TypeChecker, expr_id: NodeIndex) bool {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return true;
        if (expr_id.asInt() < self.node_types.len and self.node_types[expr_id.asInt()].isError()) return true;
        const node = self.ast_arena.getNode(expr_id);
        return switch (node.tag) {
            .wildcard_pat, .expr_hole, .stmt_hole, .incomplete_member_access => true,
            .ident_expr, .self_val => blk: {
                if (expr_id.asInt() >= self.node_symbols.len) break :blk true;
                const sym_idx = self.node_symbols[expr_id.asInt()];
                if (sym_idx.isNone()) break :blk true;
                const resolved_idx = self.unwrapAliasSymbolIdx(sym_idx);
                const sym = self.sym_table.getSymbol(resolved_idx).*;
                if (sym.type_id.isError()) break :blk true;
                break :blk sym.flags.is_mut;
            },
            .deref_expr => if (node.lhs.tag == .node) blk: {
                const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                if (lhs_id.asInt() >= self.node_types.len) break :blk true;
                const ptr_ty = self.node_types[lhs_id.asInt()];
                if (ptr_ty.isError()) break :blk true;
                const ptr_node = self.pool.getNode(self.pool.unwrapUnderlyingType(ptr_ty));
                break :blk ptr_node.tag == .mut_ref_ty or (ptr_node.tag == .raw_ptr_ty and ptr_node.rhs == 1);
            } else false,
            .field_access => if (node.lhs.tag == .node) blk: {
                const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                if (lhs_id.asInt() >= self.node_types.len) break :blk true;
                const base_ty = self.node_types[lhs_id.asInt()];
                if (base_ty.isError()) break :blk true;
                const base_tag = self.pool.getTag(self.pool.unwrapUnderlyingType(base_ty));
                if (base_tag == .mut_ref_ty) break :blk true;
                if (base_tag == .ref_ty or base_tag == .raw_ptr_ty) break :blk false;
                break :blk self.isMutableAssignablePlace(lhs_id);
            } else false,
            .index_expr => if (node.lhs.tag == .node) blk: {
                const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                if (lhs_id.asInt() >= self.node_types.len) break :blk true;
                const base_ty = self.node_types[lhs_id.asInt()];
                if (base_ty.isError()) break :blk true;
                const base_node = self.pool.getNode(self.pool.unwrapUnderlyingType(base_ty));
                if (expr_id.asInt() < self.node_symbols.len) {
                    const sub_sym_idx = self.node_symbols[expr_id.asInt()];
                    if (!sub_sym_idx.isNone()) {
                        const sub_sym = self.sym_table.getSymbol(sub_sym_idx).*;
                        if (!sub_sym.flags.is_mut) break :blk false;
                        if (base_node.tag == .mut_ref_ty) break :blk true;
                        if (base_node.tag == .ref_ty) break :blk false;
                        break :blk self.isMutableAssignablePlace(lhs_id);
                    }
                }
                if (base_node.tag == .mut_ref_ty) break :blk true;
                if (base_node.tag == .raw_ptr_ty) break :blk base_node.rhs != 0;
                if (base_node.tag == .ref_ty) break :blk false;
                break :blk self.isMutableAssignablePlace(lhs_id);
            } else false,
            .tuple_lit => blk: {
                const elems = self.getNodeExtraSlice(expr_id, false);
                if (elems.len == 1 and !hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(expr_id),
                )) {
                    break :blk self.isMutableAssignablePlace(NodeIndex.fromInt(elems[0]));
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Extracts a `StaticPlacePath` for `SE-15` pairwise disjointness verification on parallel assignment targets.
    fn extractStaticPlacePath(self: *TypeChecker, expr_id: NodeIndex) !StaticPlacePath {
        var path: StaticPlacePath = .{ .span = self.getAstSubtreeSpan(expr_id) };
        try self.populateStaticPlacePathBounded(expr_id, &path, 0);
        return path;
    }

    /// Recursively populates `path` from `expr_id` up to `MAX_TYPE_DEPTH`.
    fn populateStaticPlacePathBounded(
        self: *TypeChecker,
        expr_id: NodeIndex,
        path: *StaticPlacePath,
        depth: u32,
    ) !void {
        if (depth >= MAX_TYPE_DEPTH or expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return;
        const node = self.ast_arena.getNode(expr_id);
        switch (node.tag) {
            .ident_expr, .self_val => {
                if (expr_id.asInt() < self.node_symbols.len) {
                    path.root_sym = self.node_symbols[expr_id.asInt()];
                }
            },
            .deref_expr => {
                if (node.lhs.tag == .node) {
                    try self.populateStaticPlacePathBounded(NodeIndex.fromInt(node.lhs.payload), path, depth + 1);
                    if (path.step_len < path.steps.len) {
                        path.steps[path.step_len] = 0x01_0000_0000;
                        path.step_len += 1;
                    }
                }
            },
            .field_access => {
                if (node.lhs.tag == .node) {
                    const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                    try self.populateStaticPlacePathBounded(lhs_id, path, depth + 1);
                    if (lhs_id.asInt() < self.node_types.len and path.step_len < path.steps.len) {
                        const base_tag = self.pool.getTag(self.pool.unwrapUnderlyingType(self.node_types[lhs_id.asInt()]));
                        if (base_tag == .ref_ty or base_tag == .mut_ref_ty) {
                            path.steps[path.step_len] = 0x01_0000_0000;
                            path.step_len += 1;
                        }
                    }
                    if (node.rhs.tag == .token and path.step_len < path.steps.len) {
                        const fld_tok = TokenIndex.fromInt(node.rhs.payload);
                        const fld_str = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, fld_tok);
                        const fld_sym = try self.interner.intern(fld_str);
                        path.steps[path.step_len] = 0x02_0000_0000 | @as(u64, fld_sym.asInt());
                        path.step_len += 1;
                    }
                }
            },
            .index_expr => {
                if (node.lhs.tag == .node) {
                    const lhs_id = NodeIndex.fromInt(node.lhs.payload);
                    try self.populateStaticPlacePathBounded(lhs_id, path, depth + 1);
                    if (lhs_id.asInt() < self.node_types.len and path.step_len < path.steps.len) {
                        const base_tag = self.pool.getTag(self.pool.unwrapUnderlyingType(self.node_types[lhs_id.asInt()]));
                        if (base_tag == .ref_ty or base_tag == .mut_ref_ty) {
                            path.steps[path.step_len] = 0x01_0000_0000;
                            path.step_len += 1;
                        }
                    }
                    if (path.step_len < path.steps.len) {
                        if (node.rhs.tag == .node) {
                            const idx_id = NodeIndex.fromInt(node.rhs.payload);
                            if (try self.evalConstIntExpr(idx_id, false)) |const_idx| {
                                path.steps[path.step_len] = 0x03_0000_0000 | @as(u64, @as(u32, @truncate(@as(u128, @bitCast(const_idx)))));
                            } else {
                                const idx_span = self.getAstSubtreeSpan(idx_id);
                                const raw_slice = if (idx_span.end_byte <= self.source.len and idx_span.start_byte <= idx_span.end_byte)
                                    std.mem.trim(u8, self.source[idx_span.start_byte..idx_span.end_byte], " \t\r\n")
                                else
                                    "";
                                const idx_sym = try self.interner.intern(raw_slice);
                                path.steps[path.step_len] = 0x04_0000_0000 | @as(u64, idx_sym.asInt());
                            }
                        } else {
                            const full_span = self.getAstSubtreeSpan(expr_id);
                            const raw_slice = if (full_span.end_byte <= self.source.len and full_span.start_byte <= full_span.end_byte)
                                std.mem.trim(u8, self.source[full_span.start_byte..full_span.end_byte], " \t\r\n")
                            else
                                "";
                            const idx_sym = try self.interner.intern(raw_slice);
                            path.steps[path.step_len] = 0x04_0000_0000 | @as(u64, idx_sym.asInt());
                        }
                        path.step_len += 1;
                    }
                }
            },
            .tuple_lit => {
                const elems = self.getNodeExtraSlice(expr_id, false);
                if (elems.len == 1 and !hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(expr_id),
                )) {
                    try self.populateStaticPlacePathBounded(NodeIndex.fromInt(elems[0]), path, depth + 1);
                }
            },
            else => {},
        }
    }

    /// Validates a `_` discard target against `@linear` (`E0304`) and `@must_use` / `Result` (`E0414`).
    fn validateWildcardAssignDiscard(
        self: *TypeChecker,
        discard_span: Span,
        rhs_expr_opt: NodeIndex,
        discarded_ty: TypeId,
    ) !void {
        if (discarded_ty.isError()) return;
        const mat_ty = self.materializeUntypedType(discarded_ty);
        if (hasLinearObligation(self.pool, self.sym_table, mat_ty)) {
            try self.emitDiagnosticSimple(
                .e0304_resource_or_memory_leak,
                discard_span,
                "cannot discard `@linear` obligation with `_`",
                "consume the `@linear` value via its consuming method instead of discarding it",
            );
            return;
        }
        const is_catch_handled = !rhs_expr_opt.isNone() and blk: {
            const rhs_node = self.ast_arena.getNode(rhs_expr_opt);
            break :blk rhs_node.tag == .binary_expr and !rhs_node.main_token.isNone() and
                self.token_buffer.getToken(rhs_node.main_token).kind == .kw_catch;
        };
        if (self.pool.getTag(self.pool.unwrapUnderlyingType(mat_ty)) == .result_ty or
            (!rhs_expr_opt.isNone() and !is_catch_handled and self.isMustUseTypeOrCall(rhs_expr_opt, mat_ty)))
        {
            try self.emitDiagnosticSimple(
                .e0414_bare_wildcard_result_discard,
                discard_span,
                "discarding `@must_use` or `Result[T, E]` with `_ = …` is forbidden",
                "handle the error explicitly with `catch` or propagate with `?`",
            );
        }
    }

    /// Recursively checks an `SE-15` parallel destructuring LHS target against `rhs_ty`, collecting leaf paths.
    fn checkParallelAssignTargetBounded(
        self: *TypeChecker,
        target_id: NodeIndex,
        rhs_ty: TypeId,
        leaf_paths: *std.ArrayListUnmanaged(StaticPlacePath),
        depth: u32,
    ) anyerror!void {
        if (depth >= MAX_TYPE_DEPTH or target_id.isNone() or target_id.asInt() >= self.ast_arena.countNodes()) return;
        const target_node = self.ast_arena.getNode(target_id);
        _ = self.recordNodeType(target_id, rhs_ty);

        switch (target_node.tag) {
            .wildcard_pat => {
                try self.validateWildcardAssignDiscard(self.getAstNodeSpan(target_id), .none, rhs_ty);
                return;
            },
            .tuple_lit => {
                const elems = self.getNodeExtraSlice(target_id, false);
                if (elems.len == 1 and !hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(target_id),
                )) {
                    try self.checkParallelAssignTargetBounded(NodeIndex.fromInt(elems[0]), rhs_ty, leaf_paths, depth + 1);
                    return;
                }
                const unwrapped = self.pool.unwrapUnderlyingType(rhs_ty);
                if (!unwrapped.isError() and self.pool.getTag(unwrapped) != .tuple_ty) {
                    const dummy_tup = try self.pool.internTuple(&.{});
                    try self.emitTypeMismatch(self.getAstSubtreeSpan(target_id), unwrapped, dummy_tup);
                }
                const tup_elems = self.pool.getTupleElements(unwrapped);
                if (!unwrapped.isError() and self.pool.getTag(unwrapped) == .tuple_ty and elems.len != tup_elems.len) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstSubtreeSpan(target_id),
                        "parallel tuple destructuring arity does not match right-hand tuple type",
                        "mismatched element count in parallel assignment",
                    );
                }
                for (elems, 0..) |raw_elem, i| {
                    const elem_ty = if (i < tup_elems.len) TypeId.fromInt(tup_elems[i]) else .err_ty;
                    try self.checkParallelAssignTargetBounded(NodeIndex.fromInt(raw_elem), elem_ty, leaf_paths, depth + 1);
                }
                return;
            },
            .array_lit => {
                const elems = self.getNodeExtraSlice(target_id, false);
                const unwrapped = self.unwrapRefType(self.pool.unwrapUnderlyingType(rhs_ty));
                const rhs_node = self.pool.getNode(unwrapped);
                const elem_ty: TypeId = if (rhs_node.tag == .array_ty or rhs_node.tag == .slice_ty)
                    TypeId.fromInt(rhs_node.lhs)
                else blk: {
                    if (!unwrapped.isError()) {
                        const expected_arr = try self.pool.internArray(.i32_ty, @intCast(elems.len), false);
                        try self.emitTypeMismatch(self.getAstSubtreeSpan(target_id), unwrapped, expected_arr);
                    }
                    break :blk .err_ty;
                };
                if (rhs_node.tag == .array_ty and (rhs_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0 and elems.len != rhs_node.rhs) {
                    const found_arr = if (elem_ty.isError()) .err_ty else try self.pool.internArray(elem_ty, @intCast(elems.len), false);
                    try self.emitTypeMismatch(self.getAstSubtreeSpan(target_id), unwrapped, found_arr);
                }
                for (elems) |raw_elem| {
                    try self.checkParallelAssignTargetBounded(NodeIndex.fromInt(raw_elem), elem_ty, leaf_paths, depth + 1);
                }
                return;
            },
            .struct_lit => {
                const unwrapped = self.pool.unwrapUnderlyingType(rhs_ty);
                const struct_node = self.pool.getNode(unwrapped);
                const struct_scope: ScopeId = if (struct_node.tag == .struct_ty)
                    self.sym_table.getSymbol(SymbolIndex.fromInt(struct_node.rhs)).target_scope
                else blk: {
                    if (!unwrapped.isError()) {
                        try self.emitDiagnosticSimple(
                            .e0401_type_mismatch,
                            self.getAstSubtreeSpan(target_id),
                            "struct destructuring assignment requires a struct right-hand side",
                            "right-hand expression is not a struct",
                        );
                    }
                    break :blk .none;
                };
                const field_exprs = self.getNodeExtraSlice(target_id, true);
                const lit_cst = self.ast_arena.getCstOrigin(target_id);
                var has_dotdot_rest = false;
                var field_name_tokens: std.ArrayListUnmanaged(TokenIndex) = .empty;
                defer field_name_tokens.deinit(self.allocator);
                if (!lit_cst.isNone() and lit_cst.asInt() < self.cst_arena.countNodes()) {
                    const start_idx: usize = lit_cst.asInt();
                    const rec = self.cst_arena.getNode(lit_cst);
                    const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
                    var cur = start_idx + 1;
                    while (cur < end_idx) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                        if (sub.kind == .field_init) {
                            const f_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                            var f_cur = cur + 1;
                            while (f_cur < f_end) : (f_cur += 1) {
                                const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(f_cur)));
                                if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                                    leaf.token.asInt() < self.token_buffer.countTokens())
                                {
                                    const tok_kind = self.token_buffer.getToken(leaf.token).kind;
                                    if (tok_kind == .dotdot) {
                                        has_dotdot_rest = true;
                                        break;
                                    }
                                    if (symbol_resolver.isIdentifierToken(tok_kind)) {
                                        try field_name_tokens.append(self.allocator, leaf.token);
                                        break;
                                    }
                                }
                            }
                            cur = f_end;
                            continue;
                        }
                        if (sub.subtree_size <= 1 and !sub.token.isNone() and
                            sub.token.asInt() < self.token_buffer.countTokens() and
                            self.token_buffer.getToken(sub.token).kind == .dotdot)
                        {
                            has_dotdot_rest = true;
                        }
                        cur += 1;
                    }
                }
                var seen_field_syms: std.AutoHashMapUnmanaged(u32, void) = .empty;
                defer seen_field_syms.deinit(self.allocator);
                const count = @min(field_exprs.len, field_name_tokens.items.len);
                var idx: usize = 0;
                while (idx < count) : (idx += 1) {
                    const f_tok = field_name_tokens.items[idx];
                    const f_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, f_tok);
                    var f_ty: TypeId = .err_ty;
                    if (!struct_scope.isNone()) {
                        const f_sym_id = try self.interner.intern(f_name);
                        switch (self.sym_table.lookupInTargetScope(
                            struct_scope,
                            self.current_scope,
                            f_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        )) {
                            .found => |f_sym_idx| {
                                self.sym_table.markSymbolUsed(f_sym_idx);
                                try seen_field_syms.put(self.allocator, f_sym_idx.asInt(), {});
                                f_ty = try self.substituteNominalMemberType(
                                    unwrapped,
                                    self.sym_table.getSymbol(f_sym_idx).type_id,
                                );
                            },
                            .private_error => |priv_idx| {
                                try seen_field_syms.put(self.allocator, priv_idx.asInt(), {});
                                if (self.diagnostic_sink) |sink| {
                                    try symbol_resolver.emitPrivateAccessDiagnostic(
                                        sink,
                                        self.sym_table.getSymbol(priv_idx),
                                        self.token_buffer.getTokenSpan(self.file_id, f_tok),
                                    );
                                }
                            },
                            .not_found => {
                                if (self.diagnostic_sink) |sink| {
                                    const suggestion = self.sym_table.suggestClosestInScope(
                                        struct_scope,
                                        f_name,
                                        NamespaceMask.VALUE_ONLY,
                                    );
                                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                        sink,
                                        self.interner,
                                        f_name,
                                        self.token_buffer.getTokenSpan(self.file_id, f_tok),
                                        suggestion,
                                    );
                                }
                            },
                        }
                    }
                    try self.checkParallelAssignTargetBounded(
                        NodeIndex.fromInt(field_exprs[idx]),
                        f_ty,
                        leaf_paths,
                        depth + 1,
                    );
                }
                if (!struct_scope.isNone()) {
                    const struct_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(struct_node.rhs)).*;
                    for (self.sym_table.getScopeMembers(struct_scope)) |mem_idx| {
                        if (self.isSymbolCfgDisabled(mem_idx)) continue;
                        const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        if (seen_field_syms.contains(mem_idx.asInt())) continue;
                        const omitted_ty = try self.substituteNominalMemberType(unwrapped, mem_sym.type_id);
                        if (!has_dotdot_rest) {
                            var miss_buf: [200]u8 = undefined;
                            const miss_msg = std.fmt.bufPrint(
                                &miss_buf,
                                "missing field `{s}` in `{s}` parallel destructuring target; add `, ..` to ignore remaining fields",
                                .{ mem_sym.name_text, struct_sym.name_text },
                            ) catch "missing field in struct destructuring target; add `..`";
                            try self.emitDiagnosticSimple(
                                .e0432_missing_struct_field_initializer,
                                self.getAstSubtreeSpan(target_id),
                                miss_msg,
                                "omitted field requires explicit `..`",
                            );
                        } else if (!omitted_ty.isError() and hasLinearObligation(self.pool, self.sym_table, omitted_ty)) {
                            var lin_buf: [200]u8 = undefined;
                            const lin_msg = std.fmt.bufPrint(
                                &lin_buf,
                                "cannot discard `@linear` field `{s}` with `..` in parallel destructuring assignment",
                                .{mem_sym.name_text},
                            ) catch "cannot discard `@linear` field with `..`";
                            try self.emitDiagnosticSimple(
                                .e0304_resource_or_memory_leak,
                                self.getAstSubtreeSpan(target_id),
                                lin_msg,
                                "destructure and consume every `@linear` field explicitly",
                            );
                        }
                    }
                }
                return;
            },
            else => {},
        }

        // Leaf place target in parallel assignment:
        const leaf_ty = try self.synthExpr(target_id);
        if (!self.isAssignablePlace(target_id) or !self.isMutableAssignablePlace(target_id)) {
            try self.emitDiagnosticSimple(
                .e0434_invalid_parallel_assign_target,
                self.getAstSubtreeSpan(target_id),
                "parallel assignment target must be a mutable assignable place (`var` binding, `&mut`, `&out`, or `*mut`)",
                "not a mutable assignable place",
            );
            return;
        }
        if (!leaf_ty.isError() and !rhs_ty.isError()) {
            _ = try self.checkTypeCompatibility(target_id, rhs_ty, leaf_ty);
        }
        const place_path = try self.extractStaticPlacePath(target_id);
        for (leaf_paths.items) |prev_path| {
            if (isStaticPlacePairPotentiallyAliasing(place_path, prev_path)) {
                try self.emitDiagnosticSimple(
                    .e0305_exclusivity_violation,
                    place_path.span,
                    "duplicate or overlapping place target in parallel destructuring assignment",
                    "conflicts with an earlier target in the same parallel assignment",
                );
                break;
            }
        }
        try leaf_paths.append(self.allocator, place_path);
    }

    /// Returns `true` if `lhs_path` and `rhs_path` may alias at runtime (`SE-15`).
    fn isStaticPlacePairPotentiallyAliasing(lhs_path: StaticPlacePath, rhs_path: StaticPlacePath) bool {
        if (lhs_path.root_sym.isNone() or lhs_path.root_sym != rhs_path.root_sym) return false;
        const min_steps = @min(lhs_path.step_len, rhs_path.step_len);
        for (0..min_steps) |step_i| {
            const lhs_step = lhs_path.steps[step_i];
            const rhs_step = rhs_path.steps[step_i];
            if (lhs_step == rhs_step) continue;
            const lhs_tag = lhs_step >> 32;
            const rhs_tag = rhs_step >> 32;
            const is_lhs_idx = lhs_tag == 0x03 or lhs_tag == 0x04;
            const is_rhs_idx = rhs_tag == 0x03 or rhs_tag == 0x04;
            if (is_lhs_idx and is_rhs_idx and (lhs_tag == 0x04 or rhs_tag == 0x04)) {
                return true;
            }
            return false;
        }
        return true;
    }

    /// Type-checks `lhs = rhs;`, `_ = rhs;`, `SE-15` parallel destructuring `(a, b) = (b, a);`, or compound assignments (`+=`, `-=`, etc.).
    fn checkAssignStmt(self: *TypeChecker, stmt_id: NodeIndex) anyerror!TypeId {
        const stmt_node = self.ast_arena.getNode(stmt_id);
        const lhs_id = if (stmt_node.lhs.tag == .node) NodeIndex.fromInt(stmt_node.lhs.payload) else .none;
        const rhs_id = if (stmt_node.rhs.tag == .node) NodeIndex.fromInt(stmt_node.rhs.payload) else .none;
        if (lhs_id.isNone()) {
            if (!rhs_id.isNone()) _ = try self.synthExpr(rhs_id);
            return self.recordNodeType(stmt_id, .unit_ty);
        }

        const lhs_node = self.ast_arena.getNode(lhs_id);
        if (lhs_node.tag == .wildcard_pat) {
            if (!rhs_id.isNone()) {
                const rhs_ty = try self.synthExpr(rhs_id);
                _ = self.recordNodeType(lhs_id, rhs_ty);
                try self.validateWildcardAssignDiscard(self.getAstNodeSpan(stmt_id), rhs_id, rhs_ty);
            }
            return self.recordNodeType(stmt_id, .unit_ty);
        }

        const is_parallel_destructure = switch (lhs_node.tag) {
            .tuple_lit => blk: {
                const elems = self.getNodeExtraSlice(lhs_id, false);
                break :blk elems.len != 1 or hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(lhs_id),
                );
            },
            .array_lit, .struct_lit => true,
            else => false,
        };
        if (is_parallel_destructure) {
            if (!stmt_node.main_token.isNone() and
                self.token_buffer.getToken(stmt_node.main_token).kind != .eq)
            {
                try self.emitDiagnosticSimple(
                    .e0434_invalid_parallel_assign_target,
                    self.getAstNodeSpan(stmt_id),
                    "compound assignment operators (`+=`, `-=`, …) cannot be used with parallel destructuring targets",
                    "only `=` is permitted on destructuring targets",
                );
            }
            const rhs_ty = if (!rhs_id.isNone())
                self.materializeUntypedType(try self.synthExpr(rhs_id))
            else
                .err_ty;
            var leaf_paths: std.ArrayListUnmanaged(StaticPlacePath) = .empty;
            defer leaf_paths.deinit(self.allocator);
            try self.checkParallelAssignTargetBounded(lhs_id, rhs_ty, &leaf_paths, 0);
            return self.recordNodeType(stmt_id, .unit_ty);
        }

        const lhs_ty = try self.synthExpr(lhs_id);
        if (!lhs_ty.isError()) {
            if (!self.isAssignablePlace(lhs_id)) {
                try self.emitDiagnosticSimple(
                    .e0434_invalid_parallel_assign_target,
                    self.getAstSubtreeSpan(lhs_id),
                    "invalid assignment target; left-hand side is not an assignable place",
                    "cannot assign to an rvalue expression",
                );
            } else if (!self.isMutableAssignablePlace(lhs_id)) {
                try self.emitDiagnosticSimple(
                    .e0305_exclusivity_violation,
                    self.getAstSubtreeSpan(lhs_id),
                    "cannot mutate immutable `let` binding, shared `&T` borrow, or read-only `*T` pointer",
                    "target place is not mutable",
                );
            }
        }
        if (!rhs_id.isNone()) {
            const assigned_ty = if (!lhs_ty.isError())
                try self.checkExpr(rhs_id, lhs_ty)
            else
                try self.synthExpr(rhs_id);
            if (self.nursery_scope_depth) |n_depth| {
                const check_ty = if (!assigned_ty.isError()) assigned_ty else lhs_ty;
                if (self.hasNurseryScopedHandle(check_ty, 0)) {
                    if (self.resolveRootPlaceScopeDepth(lhs_id)) |dst_depth| {
                        if (dst_depth < n_depth) {
                            try self.emitDiagnosticSimple(
                                .e0309_concurrent_exclusivity_or_escape,
                                self.getAstNodeSpan(stmt_id),
                                "cannot store `TaskGroup` or `TaskHandle` into a binding outside the `task_group` nursery scope",
                                "nursery handle escapes enclosing `task_group` scope here",
                            );
                        }
                    }
                }
            }
        }
        return self.recordNodeType(stmt_id, .unit_ty);
    }

    /// Checks a boolean `if` / `while` condition header (`SE-01` `is` & `SE-02` `:=`).
    fn checkConditionHeader(self: *TypeChecker, cond_node_id: NodeIndex) !void {
        if (cond_node_id.isNone() or cond_node_id.asInt() >= self.ast_arena.countNodes()) return;

        const prev_pos = self.is_direct_positive_cond;
        const prev_walrus = self.is_dominating_walrus_pos;
        const prev_neg = self.is_negated_is_context;
        const prev_and = self.has_following_and_conjunct;
        self.is_direct_positive_cond = true;
        self.is_dominating_walrus_pos = true;
        self.is_negated_is_context = false;
        self.has_following_and_conjunct = false;
        defer {
            self.is_direct_positive_cond = prev_pos;
            self.is_dominating_walrus_pos = prev_walrus;
            self.is_negated_is_context = prev_neg;
            self.has_following_and_conjunct = prev_and;
        }
        _ = try self.checkExpr(cond_node_id, .bool_ty);
    }

    // ---------------------- Pattern Binding -----------------------

    /// Returns `true` if `sub_pat_id` inside a `.slice_pat` is a `..` or `..rest` spread element.
    fn isSliceRestPatternNode(self: *const TypeChecker, sub_pat_id: NodeIndex) bool {
        if (sub_pat_id.isNone() or sub_pat_id.asInt() >= self.ast_arena.countNodes()) return false;
        const sub_pat = self.ast_arena.getNode(sub_pat_id);
        if (sub_pat.tag == .wildcard_pat and !sub_pat.main_token.isNone() and
            sub_pat.main_token.asInt() < self.token_buffer.countTokens())
        {
            return self.token_buffer.getToken(sub_pat.main_token).kind == .dotdot;
        }
        if (sub_pat.tag == .bind_pat and sub_pat.lhs.tag == .token) {
            const dotdot_tok = TokenIndex.fromInt(sub_pat.lhs.payload);
            if (!dotdot_tok.isNone() and dotdot_tok.asInt() < self.token_buffer.countTokens()) {
                return self.token_buffer.getToken(dotdot_tok).kind == .dotdot;
            }
        }
        return false;
    }

    /// Returns `true` if `pat_id` introduces one or more named variable bindings (`SE-01` `E0214` check).
    fn hasPatternBindings(self: *const TypeChecker, pat_id: NodeIndex, depth: u32) bool {
        if (depth >= MAX_TYPE_DEPTH) return false;
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return false;
        const pat_node = self.ast_arena.getNode(pat_id);
        return switch (pat_node.tag) {
            .bind_pat => blk: {
                const name_str = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    pat_node.main_token,
                );
                if (name_str.len == 0 or std.mem.eql(u8, name_str, "_")) break :blk false;
                if (self.interner.lookup(name_str)) |sym_id| {
                    switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_OR_CONST)) {
                        .found => |sym_idx| {
                            const sym = self.sym_table.getSymbol(sym_idx);
                            if (sym.kind == .enum_variant_sym or sym.kind == .const_sym) break :blk false;
                        },
                        else => {},
                    }
                }
                break :blk true;
            },
            .at_pat => blk: {
                const name_str = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    pat_node.main_token,
                );
                if (name_str.len > 0 and !std.mem.eql(u8, name_str, "_")) break :blk true;
                if (pat_node.rhs.tag == .node) {
                    break :blk self.hasPatternBindings(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1);
                }
                break :blk false;
            },
            .or_pat => (pat_node.lhs.tag == .node and
                self.hasPatternBindings(NodeIndex.fromInt(pat_node.lhs.payload), depth + 1)) or
                (pat_node.rhs.tag == .node and
                    self.hasPatternBindings(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1)),
            .tuple_pat, .variant_pat, .struct_pat, .slice_pat => blk: {
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    if (self.hasPatternBindings(NodeIndex.fromInt(raw_sub), depth + 1)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Returns `true` if `pat_id` contains any non-`&` value binding (`SE-01` `@linear` move check).
    fn hasByValuePatternBinding(self: *const TypeChecker, pat_id: NodeIndex, depth: u32) bool {
        if (depth >= MAX_TYPE_DEPTH) return false;
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return false;
        const pat_node = self.ast_arena.getNode(pat_id);
        return switch (pat_node.tag) {
            .bind_pat => blk: {
                const name_str = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    pat_node.main_token,
                );
                if (name_str.len == 0 or std.mem.eql(u8, name_str, "_")) break :blk false;
                if (self.resolveBindPatConstOrVariantQuiet(pat_id, false) != null) break :blk false;
                const pat_cst = self.ast_arena.getCstOrigin(pat_id);
                if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
                    const start_idx: usize = pat_cst.asInt();
                    const rec = self.cst_arena.getNode(pat_cst);
                    const end_idx: usize = @min(
                        start_idx + @max(@as(usize, rec.subtree_size), 1),
                        self.cst_arena.countNodes(),
                    );
                    var cur = start_idx;
                    while (cur < end_idx) : (cur += 1) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                        if (sub.subtree_size <= 1 and !sub.token.isNone() and
                            sub.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tok_kind = self.token_buffer.getToken(sub.token).kind;
                            if (tok_kind == .amp) break :blk false;
                        }
                    }
                }
                break :blk true;
            },
            .at_pat => blk: {
                var is_ref_at = false;
                if (pat_node.lhs.tag == .token) {
                    const mod_tok = TokenIndex.fromInt(pat_node.lhs.payload);
                    if (!mod_tok.isNone() and mod_tok.asInt() < self.token_buffer.countTokens()) {
                        const mod_kind = self.token_buffer.getToken(mod_tok).kind;
                        if (mod_kind == .amp) is_ref_at = true;
                    }
                }
                if (!is_ref_at) break :blk true;
                if (pat_node.rhs.tag == .node) {
                    break :blk self.hasByValuePatternBinding(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1);
                }
                break :blk false;
            },
            .or_pat => (pat_node.lhs.tag == .node and
                self.hasByValuePatternBinding(NodeIndex.fromInt(pat_node.lhs.payload), depth + 1)) or
                (pat_node.rhs.tag == .node and
                    self.hasByValuePatternBinding(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1)),
            .tuple_pat, .variant_pat, .struct_pat, .slice_pat => blk: {
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    if (self.hasByValuePatternBinding(NodeIndex.fromInt(raw_sub), depth + 1)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Quietly peeks the payload `TypeId` of a `.variant_pat` without emitting diagnostics.
    fn peekVariantPatPayloadTypeQuiet(self: *TypeChecker, pat_id: NodeIndex, scrutinee_ty: TypeId) !TypeId {
        const unwrapped = self.unwrapRefType(scrutinee_ty);
        if (unwrapped.isError()) return .err_ty;
        const var_name = self.extractVariantPatName(pat_id);
        const scr_node = self.pool.getNode(unwrapped);
        switch (scr_node.tag) {
            .optional_ty => {
                if (std.mem.eql(u8, var_name, "Some")) {
                    return TypeId.fromInt(scr_node.lhs);
                } else if (std.mem.eql(u8, var_name, "None")) {
                    return .unit_ty;
                }
            },
            .result_ty => {
                if (std.mem.eql(u8, var_name, "Ok")) {
                    return TypeId.fromInt(scr_node.lhs);
                } else if (std.mem.eql(u8, var_name, "Err")) {
                    return TypeId.fromInt(scr_node.rhs);
                }
            },
            .enum_ty => {
                const enum_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(scr_node.rhs));
                if (!enum_sym.target_scope.isNone()) {
                    if (self.interner.lookup(var_name)) |var_sym_id| {
                        const v_idx = self.sym_table.lookupInScopeDirect(
                            enum_sym.target_scope,
                            var_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        );
                        if (!v_idx.isNone()) {
                            return self.substituteNominalMemberType(
                                unwrapped,
                                self.sym_table.getSymbol(v_idx).type_id,
                            );
                        }
                    }
                }
            },
            else => {},
        }
        return .err_ty;
    }

    /// Returns `true` if `pat_id` binds any `@linear` leaf field by value (`SE-01` `is … and` guard check).
    fn hasByValueLinearPatternBinding(
        self: *TypeChecker,
        pat_id: NodeIndex,
        scrutinee_ty: TypeId,
        depth: u32,
    ) anyerror!bool {
        if (depth >= MAX_TYPE_DEPTH or scrutinee_ty.isError()) return false;
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return false;
        const pat_node = self.ast_arena.getNode(pat_id);
        return switch (pat_node.tag) {
            .bind_pat => blk: {
                if (!self.hasByValuePatternBinding(pat_id, depth)) break :blk false;
                const mat_ty = self.materializeUntypedType(scrutinee_ty);
                break :blk !mat_ty.isError() and
                    classifyOwnershipTier(self.pool, self.sym_table, mat_ty) == .linear_tier;
            },
            .at_pat => blk: {
                var is_ref_at = false;
                const pat_cst = self.ast_arena.getCstOrigin(pat_id);
                if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
                    const start_idx: usize = pat_cst.asInt();
                    const rec = self.cst_arena.getNode(pat_cst);
                    const end_idx: usize = @min(
                        start_idx + @max(@as(usize, rec.subtree_size), 1),
                        self.cst_arena.countNodes(),
                    );
                    var cur = start_idx;
                    while (cur < end_idx) : (cur += 1) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                        if (sub.subtree_size <= 1 and !sub.token.isNone() and
                            sub.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tok_kind = self.token_buffer.getToken(sub.token).kind;
                            if (tok_kind == .at) break;
                            if (tok_kind == .amp) is_ref_at = true;
                        }
                    }
                } else if (pat_node.lhs.tag == .token) {
                    const mod_tok = TokenIndex.fromInt(pat_node.lhs.payload);
                    if (!mod_tok.isNone() and mod_tok.asInt() < self.token_buffer.countTokens()) {
                        const mod_kind = self.token_buffer.getToken(mod_tok).kind;
                        if (mod_kind == .amp) is_ref_at = true;
                    }
                }
                const mat_ty = self.materializeUntypedType(scrutinee_ty);
                if (!is_ref_at and !mat_ty.isError() and
                    classifyOwnershipTier(self.pool, self.sym_table, mat_ty) == .linear_tier)
                {
                    break :blk true;
                }
                if (pat_node.rhs.tag == .node) {
                    break :blk try self.hasByValueLinearPatternBinding(
                        NodeIndex.fromInt(pat_node.rhs.payload),
                        scrutinee_ty,
                        depth + 1,
                    );
                }
                break :blk false;
            },
            .or_pat => blk: {
                if (pat_node.lhs.tag == .node and try self.hasByValueLinearPatternBinding(
                    NodeIndex.fromInt(pat_node.lhs.payload),
                    scrutinee_ty,
                    depth + 1,
                )) break :blk true;
                if (pat_node.rhs.tag == .node and try self.hasByValueLinearPatternBinding(
                    NodeIndex.fromInt(pat_node.rhs.payload),
                    scrutinee_ty,
                    depth + 1,
                )) break :blk true;
                break :blk false;
            },
            .tuple_pat => blk: {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                if (sub_pats.len == 1 and !hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(pat_id),
                )) {
                    break :blk try self.hasByValueLinearPatternBinding(
                        NodeIndex.fromInt(sub_pats[0]),
                        scrutinee_ty,
                        depth + 1,
                    );
                }
                const unwrapped = self.unwrapRefType(scrutinee_ty);
                const elem_types = self.pool.getTupleElements(unwrapped);
                for (sub_pats, 0..) |raw_sub, i| {
                    const sub_ty = if (i < elem_types.len) TypeId.fromInt(elem_types[i]) else .err_ty;
                    if (try self.hasByValueLinearPatternBinding(NodeIndex.fromInt(raw_sub), sub_ty, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .variant_pat => blk: {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                if (sub_pats.len == 0) break :blk false;
                const payload_ty = try self.peekVariantPatPayloadTypeQuiet(pat_id, scrutinee_ty);
                if (sub_pats.len == 1) {
                    break :blk try self.hasByValueLinearPatternBinding(
                        NodeIndex.fromInt(sub_pats[0]),
                        payload_ty,
                        depth + 1,
                    );
                }
                const elem_types = self.pool.getTupleElements(payload_ty);
                for (sub_pats, 0..) |raw_sub, i| {
                    const sub_ty = if (i < elem_types.len) TypeId.fromInt(elem_types[i]) else payload_ty;
                    if (try self.hasByValueLinearPatternBinding(NodeIndex.fromInt(raw_sub), sub_ty, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .struct_pat => blk: {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                const unwrapped = self.unwrapRefType(scrutinee_ty);
                const struct_node = self.pool.getNode(unwrapped);
                const struct_scope: ScopeId = if (struct_node.tag == .struct_ty)
                    self.sym_table.getSymbol(SymbolIndex.fromInt(struct_node.rhs)).target_scope
                else
                    .none;
                for (sub_pats) |raw_sub| {
                    const sub_pat_id = NodeIndex.fromInt(raw_sub);
                    const sub_pat = self.ast_arena.getNode(sub_pat_id);
                    var field_ty: TypeId = .err_ty;
                    if (!struct_scope.isNone() and !sub_pat.main_token.isNone()) {
                        const field_name = symbol_resolver.extractTokenSlice(
                            self.source,
                            self.token_buffer,
                            sub_pat.main_token,
                        );
                        if (self.interner.lookup(field_name)) |field_sym_id| {
                            const f_sym_idx = self.sym_table.lookupInScopeDirect(
                                struct_scope,
                                field_sym_id,
                                NamespaceMask.VALUE_ONLY,
                            );
                            if (!f_sym_idx.isNone()) {
                                field_ty = try self.substituteNominalMemberType(
                                    unwrapped,
                                    self.sym_table.getSymbol(f_sym_idx).type_id,
                                );
                            }
                        }
                    }
                    if (try self.hasByValueLinearPatternBinding(sub_pat_id, field_ty, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .slice_pat => blk: {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                const unwrapped = self.unwrapRefType(scrutinee_ty);
                const scr_node = self.pool.getNode(unwrapped);
                const elem_ty: TypeId = if (scr_node.tag == .slice_ty or scr_node.tag == .array_ty)
                    TypeId.fromInt(scr_node.lhs)
                else
                    .err_ty;
                for (sub_pats) |raw_sub| {
                    const sub_id = NodeIndex.fromInt(raw_sub);
                    if (self.isSliceRestPatternNode(sub_id)) continue;
                    if (try self.hasByValueLinearPatternBinding(sub_id, elem_ty, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Validates a `.lit_pat` literal or range pattern against `scrutinee_ty` (`E0401`).
    fn validateLiteralPatternType(self: *TypeChecker, pat_id: NodeIndex, scrutinee_ty: TypeId) !void {
        const base_scr = self.pool.unwrapRefinementBase(self.unwrapRefType(scrutinee_ty));
        if (base_scr.isError()) return;
        const pat_node = self.ast_arena.getNode(pat_id);
        if (pat_node.main_token.isNone() or pat_node.main_token.asInt() >= self.token_buffer.countTokens()) return;

        switch (self.token_buffer.getToken(pat_node.main_token).kind) {
            .kw_true, .kw_false => {
                if (base_scr != .bool_ty) {
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, .bool_ty);
                }
            },
            .string_lit => {
                if (base_scr != .str_ty) {
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, .str_ty);
                }
            },
            .char_lit => {
                if (base_scr != .char_ty) {
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, .char_ty);
                }
            },
            .byte_lit => {
                if (base_scr != .u8_ty and base_scr != .untyped_int_ty) {
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, .u8_ty);
                }
            },
            .byte_string_lit => {
                const scr_node = self.pool.getNode(base_scr);
                const is_byte_seq = (scr_node.tag == .slice_ty or scr_node.tag == .array_ty) and
                    TypeId.fromInt(scr_node.lhs) == .u8_ty;
                if (!is_byte_seq) {
                    const expected_bytes = try self.pool.internRef(
                        try self.pool.internSlice(.u8_ty, false),
                        false,
                    );
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, expected_bytes);
                }
            },
            .float_lit => {
                if (!base_scr.isFloatPrimitive() and base_scr != .untyped_float_ty) {
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, .f64_ty);
                }
            },
            .int_lit, .minus => {
                if (!base_scr.isIntegerPrimitive() and base_scr != .untyped_int_ty and
                    !self.isIntegerBoundedVar(base_scr))
                {
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), base_scr, .i32_ty);
                }
            },
            else => {},
        }
    }

    /// Returns `true` if `scr_expr_id` (of type `scr_ty`) permits `&mut` pattern bindings (`E0305`).
    fn isScrutineeMutRefBindable(
        self: *const TypeChecker,
        scr_expr_id: NodeIndex,
        scr_ty: TypeId,
    ) bool {
        if (scr_ty.isError()) return true;
        const scr_node = self.pool.getNode(self.pool.unwrapUnderlyingType(scr_ty));
        if (scr_node.tag == .mut_ref_ty) return true;
        if (scr_node.tag == .ref_ty) return false;
        if (scr_node.tag == .raw_ptr_ty and scr_node.rhs == 0) return false;
        if (scr_expr_id.isNone()) return true;
        return !self.isAssignablePlace(scr_expr_id) or self.isMutableAssignablePlace(scr_expr_id);
    }

    /// Computes child `is_scrutinee_mut` when pattern matching steps through `scrutinee_ty`.
    fn isChildScrutineeMut(
        self: *const TypeChecker,
        scrutinee_ty: TypeId,
        is_parent_mut: bool,
    ) bool {
        if (scrutinee_ty.isError()) return true;
        const scr_node = self.pool.getNode(self.pool.unwrapUnderlyingType(scrutinee_ty));
        if (scr_node.tag == .mut_ref_ty) return true;
        if (scr_node.tag == .ref_ty) return false;
        if (scr_node.tag == .raw_ptr_ty and scr_node.rhs == 0) return false;
        return is_parent_mut;
    }

    /// Binds variables introduced by `pat_id` against `scrutinee_ty` in `self.current_scope`.
    fn bindPattern(
        self: *TypeChecker,
        pat_id: NodeIndex,
        scrutinee_ty: TypeId,
        is_decl_mut: bool,
        is_scrutinee_mut: bool,
    ) anyerror!void {
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return;
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const pat_node = self.ast_arena.getNode(pat_id);
        _ = self.recordNodeType(pat_id, scrutinee_ty);

        switch (pat_node.tag) {
            .wildcard_pat, .pattern_hole => return,
            .lit_pat => {
                try self.validateLiteralPatternType(pat_id, scrutinee_ty);
                return;
            },
            .or_pat => {
                if (pat_node.lhs.tag == .node) {
                    try self.bindPattern(
                        NodeIndex.fromInt(pat_node.lhs.payload),
                        scrutinee_ty,
                        is_decl_mut,
                        is_scrutinee_mut,
                    );
                }
                if (pat_node.rhs.tag == .node) {
                    try self.bindPattern(
                        NodeIndex.fromInt(pat_node.rhs.payload),
                        scrutinee_ty,
                        is_decl_mut,
                        is_scrutinee_mut,
                    );
                }
            },
            .bind_pat => {
                const name_str = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    pat_node.main_token,
                );
                if (name_str.len == 0 or std.mem.eql(u8, name_str, "_")) return;

                if (self.resolveBindPatConstOrVariantQuiet(pat_id, is_decl_mut)) |resolved_idx| {
                    self.sym_table.markSymbolUsed(resolved_idx);
                    self.recordNodeSymbol(pat_id, resolved_idx);
                    const resolved_sym = self.sym_table.getSymbol(resolved_idx).*;
                    const unwrapped_scr = self.unwrapRefType(scrutinee_ty);
                    if (resolved_sym.kind == .const_sym and
                        !unwrapped_scr.isError() and !resolved_sym.type_id.isError())
                    {
                        _ = try self.checkTypeCompatibility(pat_id, resolved_sym.type_id, unwrapped_scr);
                    }
                    return;
                }

                const pat_cst = self.ast_arena.getCstOrigin(pat_id);
                const has_explicit_mut_kw = self.hasMutKeywordInCst(pat_cst);
                var is_mut = is_decl_mut or self.hasVarOrMutKeywordInCst(pat_cst);
                var has_amp = false;
                var bound_ty = self.materializeUntypedType(scrutinee_ty);
                if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
                    const start_idx: usize = pat_cst.asInt();
                    const rec = self.cst_arena.getNode(pat_cst);
                    const end_idx: usize = @min(
                        start_idx + @max(@as(usize, rec.subtree_size), 1),
                        self.cst_arena.countNodes(),
                    );
                    var cur = start_idx;
                    while (cur < end_idx) : (cur += 1) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                        if (sub.subtree_size <= 1 and !sub.token.isNone() and
                            sub.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tok_kind = self.token_buffer.getToken(sub.token).kind;
                            if (tok_kind == .amp) {
                                has_amp = true;
                                bound_ty = try self.pool.internRef(bound_ty, has_explicit_mut_kw);
                                is_mut = is_decl_mut;
                                break;
                            }
                        }
                    }
                }

                if (has_amp and has_explicit_mut_kw and !scrutinee_ty.isError() and !is_scrutinee_mut) {
                    try self.emitDiagnosticSimple(
                        .e0305_exclusivity_violation,
                        self.getAstNodeSpan(pat_id),
                        "cannot bind `&mut` pattern from an immutable binding or `&T` borrow",
                        "scrutinee place is not mutable",
                    );
                }

                const name_sym = try self.interner.intern(name_str);
                const bound_idx = try self.sym_table.defineSymbol(.{
                    .name = name_sym,
                    .name_text = self.interner.get(name_sym),
                    .kind = .local_var_sym,
                    .namespace = .value_ns,
                    .visibility = .private,
                    .flags = .{
                        .is_mut = is_mut,
                        .is_comptime = self.is_binding_comptime or self.pure_comptime_depth > 0,
                    },
                    .scope_id = self.current_scope,
                    .decl_span = self.token_buffer.getTokenSpan(self.file_id, pat_node.main_token),
                    .ast_node = pat_id,
                    .cst_node = pat_cst,
                    .type_id = bound_ty,
                }, self.diagnostic_sink);
                self.recordNodeSymbol(pat_id, bound_idx);
            },
            .tuple_pat => {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                if (sub_pats.len == 1 and !hasShallowCommaInTupleCst(
                    self.cst_arena,
                    self.token_buffer,
                    self.ast_arena.getCstOrigin(pat_id),
                )) {
                    try self.bindPattern(
                        NodeIndex.fromInt(sub_pats[0]),
                        scrutinee_ty,
                        is_decl_mut,
                        is_scrutinee_mut,
                    );
                    return;
                }
                const child_scr_mut = self.isChildScrutineeMut(scrutinee_ty, is_scrutinee_mut);
                const unwrapped = self.unwrapRefType(scrutinee_ty);
                const elem_types = self.pool.getTupleElements(unwrapped);
                for (sub_pats, 0..) |raw_sub, i| {
                    const sub_ty = if (i < elem_types.len)
                        TypeId.fromInt(elem_types[i])
                    else
                        .err_ty;
                    try self.bindPattern(
                        NodeIndex.fromInt(raw_sub),
                        sub_ty,
                        is_decl_mut,
                        self.isChildScrutineeMut(sub_ty, child_scr_mut),
                    );
                }
            },
            .variant_pat => {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                const child_scr_mut = self.isChildScrutineeMut(scrutinee_ty, is_scrutinee_mut);
                const payload_ty = try self.resolveVariantPatPayloadType(pat_id, scrutinee_ty);
                if (sub_pats.len == 0) return;
                if (sub_pats.len == 1) {
                    try self.bindPattern(
                        NodeIndex.fromInt(sub_pats[0]),
                        payload_ty,
                        is_decl_mut,
                        self.isChildScrutineeMut(payload_ty, child_scr_mut),
                    );
                } else {
                    const elem_types = self.pool.getTupleElements(payload_ty);
                    for (sub_pats, 0..) |raw_sub, i| {
                        const sub_ty = if (i < elem_types.len)
                            TypeId.fromInt(elem_types[i])
                        else
                            payload_ty;
                        try self.bindPattern(
                            NodeIndex.fromInt(raw_sub),
                            sub_ty,
                            is_decl_mut,
                            self.isChildScrutineeMut(sub_ty, child_scr_mut),
                        );
                    }
                }
            },
            .struct_pat => {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                const child_scr_mut = self.isChildScrutineeMut(scrutinee_ty, is_scrutinee_mut);
                const unwrapped = self.unwrapRefType(scrutinee_ty);
                const struct_node = self.pool.getNode(unwrapped);
                const struct_scope: ScopeId = if (struct_node.tag == .struct_ty) blk: {
                    const struct_sym_idx = SymbolIndex.fromInt(struct_node.rhs);
                    self.recordNodeSymbol(pat_id, struct_sym_idx);
                    break :blk self.sym_table.getSymbol(struct_sym_idx).target_scope;
                } else .none;

                for (sub_pats) |raw_sub| {
                    const sub_pat_id = NodeIndex.fromInt(raw_sub);
                    const sub_pat = self.ast_arena.getNode(sub_pat_id);
                    var field_ty: TypeId = .err_ty;
                    if (!struct_scope.isNone() and !sub_pat.main_token.isNone()) {
                        const field_name = symbol_resolver.extractTokenSlice(
                            self.source,
                            self.token_buffer,
                            sub_pat.main_token,
                        );
                        if (self.interner.lookup(field_name)) |field_sym_id| {
                            switch (self.sym_table.lookupInTargetScope(
                                struct_scope,
                                self.current_scope,
                                field_sym_id,
                                NamespaceMask.VALUE_ONLY,
                            )) {
                                .found => |f_sym_idx| {
                                    self.sym_table.markSymbolUsed(f_sym_idx);
                                    field_ty = try self.substituteNominalMemberType(
                                        unwrapped,
                                        self.sym_table.getSymbol(f_sym_idx).type_id,
                                    );
                                },
                                .private_error => |priv_idx| {
                                    if (self.diagnostic_sink) |sink| {
                                        try symbol_resolver.emitPrivateAccessDiagnostic(
                                            sink,
                                            self.sym_table.getSymbol(priv_idx),
                                            self.token_buffer.getTokenSpan(self.file_id, sub_pat.main_token),
                                        );
                                    }
                                },
                                .not_found => {},
                            }
                        }
                    }
                    try self.bindPattern(
                        sub_pat_id,
                        field_ty,
                        is_decl_mut,
                        self.isChildScrutineeMut(field_ty, child_scr_mut),
                    );
                }
            },
            .at_pat => {
                const name_str = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    pat_node.main_token,
                );
                const pat_cst = self.ast_arena.getCstOrigin(pat_id);
                var is_mut = is_decl_mut;
                var has_mut_kw = false;
                var is_ref = false;
                if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
                    const start_idx: usize = pat_cst.asInt();
                    const rec = self.cst_arena.getNode(pat_cst);
                    const end_idx: usize = @min(
                        start_idx + @max(@as(usize, rec.subtree_size), 1),
                        self.cst_arena.countNodes(),
                    );
                    var cur = start_idx;
                    while (cur < end_idx) : (cur += 1) {
                        const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                        if (sub.subtree_size <= 1 and !sub.token.isNone() and
                            sub.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tok_kind = self.token_buffer.getToken(sub.token).kind;
                            if (tok_kind == .at) break;
                            if (tok_kind == .kw_var or tok_kind == .kw_mut) is_mut = true;
                            if (tok_kind == .kw_mut) has_mut_kw = true;
                            if (tok_kind == .amp) is_ref = true;
                        }
                    }
                } else if (pat_node.lhs.tag == .token) {
                    const mod_tok = TokenIndex.fromInt(pat_node.lhs.payload);
                    if (!mod_tok.isNone() and mod_tok.asInt() < self.token_buffer.countTokens()) {
                        const mod_kind = self.token_buffer.getToken(mod_tok).kind;
                        if (mod_kind == .kw_var or mod_kind == .kw_mut) is_mut = true;
                        if (mod_kind == .kw_mut) has_mut_kw = true;
                        if (mod_kind == .amp) is_ref = true;
                    }
                }

                if (name_str.len > 0 and !std.mem.eql(u8, name_str, "_")) {
                    var bound_ty = self.materializeUntypedType(scrutinee_ty);
                    if (is_ref and !bound_ty.isError()) {
                        if (has_mut_kw and !is_scrutinee_mut) {
                            try self.emitDiagnosticSimple(
                                .e0305_exclusivity_violation,
                                self.getAstNodeSpan(pat_id),
                                "cannot bind `&mut` `@` pattern from an immutable binding or `&T` borrow",
                                "scrutinee place is not mutable",
                            );
                        }
                        bound_ty = try self.pool.internRef(bound_ty, has_mut_kw);
                        is_mut = is_decl_mut;
                    } else if (pat_node.rhs.tag == .node and
                        classifyOwnershipTier(self.pool, self.sym_table, bound_ty) == .linear_tier and
                        self.hasByValuePatternBinding(NodeIndex.fromInt(pat_node.rhs.payload), 0))
                    {
                        try self.emitDiagnosticSimple(
                            .e0304_resource_or_memory_leak,
                            self.getAstNodeSpan(pat_id),
                            "cannot duplicate `@linear` value across both `name @` and by-value subpattern",
                            "use `&name @ …` to borrow while destructuring",
                        );
                    }
                    const name_sym = try self.interner.intern(name_str);
                    const bound_idx = try self.sym_table.defineSymbol(.{
                        .name = name_sym,
                        .name_text = self.interner.get(name_sym),
                        .kind = .local_var_sym,
                        .namespace = .value_ns,
                        .visibility = .private,
                        .flags = .{
                            .is_mut = is_mut,
                            .is_comptime = self.is_binding_comptime or self.pure_comptime_depth > 0,
                        },
                        .scope_id = self.current_scope,
                        .decl_span = self.token_buffer.getTokenSpan(self.file_id, pat_node.main_token),
                        .ast_node = pat_id,
                        .cst_node = pat_cst,
                        .type_id = bound_ty,
                    }, self.diagnostic_sink);
                    self.recordNodeSymbol(pat_id, bound_idx);
                }
                if (pat_node.rhs.tag == .node) {
                    try self.bindPattern(
                        NodeIndex.fromInt(pat_node.rhs.payload),
                        scrutinee_ty,
                        is_decl_mut,
                        is_scrutinee_mut,
                    );
                }
            },
            .slice_pat => {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                const child_scr_mut = self.isChildScrutineeMut(scrutinee_ty, is_scrutinee_mut);
                const unwrapped = self.unwrapRefType(scrutinee_ty);
                const scr_node = self.pool.getNode(unwrapped);
                const is_valid_slice_scr = scr_node.tag == .slice_ty or scr_node.tag == .array_ty;
                if (!unwrapped.isError() and !is_valid_slice_scr) {
                    const expected_slice = try self.pool.internRef(
                        try self.pool.internSlice(.i32_ty, false),
                        false,
                    );
                    try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), expected_slice, scrutinee_ty);
                }
                const elem_ty: TypeId = if (is_valid_slice_scr) TypeId.fromInt(scr_node.lhs) else .err_ty;

                var rest_count: usize = 0;
                var fixed_count: usize = 0;
                for (sub_pats) |raw_sub| {
                    const sub_id = NodeIndex.fromInt(raw_sub);
                    if (self.isSliceRestPatternNode(sub_id)) {
                        rest_count += 1;
                        if (rest_count > 1) {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                self.getAstNodeSpan(sub_id),
                                "slice pattern may contain at most one `..` rest spread",
                                "duplicate `..` rest pattern in slice pattern",
                            );
                        }
                        const sub_node = self.ast_arena.getNode(sub_id);
                        if (sub_node.tag == .bind_pat) {
                            const rest_name = symbol_resolver.extractTokenSlice(
                                self.source,
                                self.token_buffer,
                                sub_node.main_token,
                            );
                            const rest_cst = self.ast_arena.getCstOrigin(sub_id);
                            const has_rest_mut_kw = self.hasMutKeywordInCst(rest_cst);
                            const has_rest_var_kw = self.hasVarOrMutKeywordInCst(rest_cst) and !has_rest_mut_kw;
                            if (has_rest_mut_kw and !scrutinee_ty.isError() and !child_scr_mut) {
                                try self.emitDiagnosticSimple(
                                    .e0305_exclusivity_violation,
                                    self.getAstNodeSpan(sub_id),
                                    "cannot bind `&mut` rest subslice from an immutable container or `&[T]` slice",
                                    "scrutinee slice is not mutable",
                                );
                            }
                            const subslice_ty: TypeId = if (elem_ty.isError())
                                .err_ty
                            else
                                try self.pool.internRef(
                                    try self.pool.internSlice(elem_ty, false),
                                    child_scr_mut and has_rest_mut_kw,
                                );
                            _ = self.recordNodeType(sub_id, subslice_ty);
                            if (rest_name.len > 0 and !std.mem.eql(u8, rest_name, "_")) {
                                const rest_sym_id = try self.interner.intern(rest_name);
                                const rest_sym_idx = try self.sym_table.defineSymbol(.{
                                    .name = rest_sym_id,
                                    .name_text = self.interner.get(rest_sym_id),
                                    .kind = .local_var_sym,
                                    .namespace = .value_ns,
                                    .visibility = .private,
                                    .flags = .{
                                        .is_mut = is_decl_mut or has_rest_var_kw,
                                        .is_comptime = self.is_binding_comptime or self.pure_comptime_depth > 0,
                                    },
                                    .scope_id = self.current_scope,
                                    .decl_span = self.token_buffer.getTokenSpan(self.file_id, sub_node.main_token),
                                    .ast_node = sub_id,
                                    .cst_node = rest_cst,
                                    .type_id = subslice_ty,
                                }, self.diagnostic_sink);
                                self.recordNodeSymbol(sub_id, rest_sym_idx);
                            }
                        }
                    } else {
                        fixed_count += 1;
                        try self.bindPattern(
                            sub_id,
                            elem_ty,
                            is_decl_mut,
                            self.isChildScrutineeMut(elem_ty, child_scr_mut),
                        );
                    }
                }
                if (scr_node.tag == .array_ty and (scr_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0) {
                    const arr_len: usize = scr_node.rhs;
                    if ((rest_count == 0 and fixed_count != arr_len) or
                        (rest_count > 0 and fixed_count > arr_len))
                    {
                        const found_arr = if (elem_ty.isError())
                            .err_ty
                        else
                            try self.pool.internArray(elem_ty, @intCast(fixed_count), false);
                        try self.emitTypeMismatch(self.getAstNodeSpan(pat_id), unwrapped, found_arr);
                    }
                }
            },
            else => {},
        }
    }

    /// Resolves the payload `TypeId` of a `.variant_pat` (`Some(x)`, `Ok(x)`, `Err(e)`, or `Enum.Variant(x)`).
    fn resolveVariantPatPayloadType(
        self: *TypeChecker,
        pat_id: NodeIndex,
        scrutinee_ty: TypeId,
    ) !TypeId {
        const unwrapped = self.unwrapRefType(scrutinee_ty);
        if (unwrapped.isError()) return .err_ty;
        const var_name = self.extractVariantPatName(pat_id);
        const scr_node = self.pool.getNode(unwrapped);

        switch (scr_node.tag) {
            .optional_ty => {
                if (std.mem.eql(u8, var_name, "Some")) {
                    return TypeId.fromInt(scr_node.lhs);
                } else if (std.mem.eql(u8, var_name, "None")) {
                    return .unit_ty;
                }
            },
            .result_ty => {
                if (std.mem.eql(u8, var_name, "Ok")) {
                    return TypeId.fromInt(scr_node.lhs);
                } else if (std.mem.eql(u8, var_name, "Err")) {
                    return TypeId.fromInt(scr_node.rhs);
                }
            },
            .enum_ty => {
                const enum_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(scr_node.rhs));
                if (!enum_sym.target_scope.isNone()) {
                    if (self.interner.lookup(var_name)) |var_sym_id| {
                        const v_idx = self.sym_table.lookupInScopeDirect(
                            enum_sym.target_scope,
                            var_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        );
                        if (!v_idx.isNone()) {
                            self.sym_table.markSymbolUsed(v_idx);
                            self.recordNodeSymbol(pat_id, v_idx);
                            return self.substituteNominalMemberType(
                                unwrapped,
                                self.sym_table.getSymbol(v_idx).type_id,
                            );
                        }
                    }
                }
            },
            else => {},
        }

        if (self.getNodeExtraSlice(pat_id, false).len == 0) {
            if (self.resolvePatternConstSymbolQuiet(pat_id)) |const_idx| {
                self.sym_table.markSymbolUsed(const_idx);
                self.recordNodeSymbol(pat_id, const_idx);
                const const_ty = self.sym_table.getSymbol(const_idx).type_id;
                if (!const_ty.isError() and !unwrapped.isError()) {
                    _ = try self.checkTypeCompatibility(pat_id, const_ty, unwrapped);
                }
                return .unit_ty;
            }
            const pat_node = self.ast_arena.getNode(pat_id);
            const has_leading_dot = !pat_node.main_token.isNone() and
                pat_node.main_token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(pat_node.main_token).kind == .dot;
            if (!has_leading_dot and
                scr_node.tag != .optional_ty and scr_node.tag != .result_ty and scr_node.tag != .enum_ty)
            {
                if (self.diagnostic_sink) |sink| {
                    const suggestion = self.sym_table.suggestClosestSymbol(
                        self.current_scope,
                        var_name,
                        NamespaceMask.VALUE_OR_CONST,
                    );
                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                        sink,
                        self.interner,
                        var_name,
                        self.getAstNodeSpan(pat_id),
                        suggestion,
                    );
                }
                return .err_ty;
            }
        }

        var expected_buf: [96]u8 = undefined;
        const expected_str = self.pool.formatType(unwrapped, self.sym_table, &expected_buf);
        var msg_buf: [192]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "variant pattern `.{s}` does not exist on scrutinee type `{s}`",
            .{ var_name, expected_str },
        ) catch "unresolved variant pattern on scrutinee type";
        try self.emitDiagnosticSimple(
            .e0407_invalid_contextual_variant,
            self.getAstNodeSpan(pat_id),
            msg,
            "variant not found on scrutinee type",
        );
        return .err_ty;
    }

    /// Extracts the variant identifier text from a `.variant_pat` AST node.
    fn extractVariantPatName(self: *const TypeChecker, pat_id: NodeIndex) []const u8 {
        const pat_node = self.ast_arena.getNode(pat_id);
        const pat_cst = self.ast_arena.getCstOrigin(pat_id);
        var last_ident_tok: TokenIndex = pat_node.main_token;

        if (!pat_cst.isNone() and pat_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = pat_cst.asInt();
            const rec = self.cst_arena.getNode(pat_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (is_leaf and !sub.flags.is_missing_or_injected and
                    !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const kind = self.token_buffer.getToken(sub.token).kind;
                    if (kind == .lparen or kind == .lbrace) break;
                    if (symbol_resolver.isIdentifierToken(kind)) {
                        last_ident_tok = sub.token;
                    }
                }
            }
        }
        return symbol_resolver.extractTokenSlice(self.source, self.token_buffer, last_ident_tok);
    }

    // ------- Bidirectional Expression Synthesis & Checking --------

    /// Checking mode ($\Gamma \vdash e \Leftarrow T$): verifies `expr_id` against `expected_ty`.
    pub fn checkExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) anyerror!TypeId {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return .err_ty;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return self.recordNodeType(expr_id, .err_ty);
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        if (expected_ty.isError()) {
            return self.synthExpr(expr_id);
        }

        const expr_node = self.ast_arena.getNode(expr_id);
        switch (expr_node.tag) {
            .expr_hole, .type_hole, .item_hole, .stmt_hole, .pattern_hole => {
                return self.recordNodeType(expr_id, .err_ty);
            },
            .contextual_variant => {
                return self.checkContextualVariant(expr_id, expected_ty);
            },
            .int_lit => {
                return self.checkIntLiteralAgainstExpected(expr_id, false, expected_ty);
            },
            .string_lit => {
                if (self.pool.unwrapUnderlyingType(expected_ty) == .fmt_args_ty) {
                    const fmt_ty = try self.synthOrCheckStringLit(expr_id, true);
                    return self.recordNodeType(expr_id, fmt_ty);
                }
            },
            .unary_expr => {
                if (!expr_node.main_token.isNone() and expr_node.lhs.tag == .node) {
                    const op_kind = self.token_buffer.getToken(expr_node.main_token).kind;
                    if (op_kind == .kw_comptime) {
                        return self.synthOrCheckComptimePrefixExpr(expr_id, expected_ty);
                    }
                    if (op_kind == .kw_own) {
                        const inner_id = NodeIndex.fromInt(expr_node.lhs.payload);
                        const prev_own = self.is_in_explicit_own_expr;
                        self.is_in_explicit_own_expr = true;
                        defer self.is_in_explicit_own_expr = prev_own;
                        const res_ty = try self.checkExpr(inner_id, expected_ty);
                        return self.recordNodeType(expr_id, res_ty);
                    }
                    if (op_kind == .minus) {
                        const inner_id = NodeIndex.fromInt(expr_node.lhs.payload);
                        if (self.ast_arena.getNode(inner_id).tag == .int_lit) {
                            const res_ty = try self.checkIntLiteralAgainstExpected(inner_id, true, expected_ty);
                            return self.recordNodeType(expr_id, res_ty);
                        }
                    }
                    if (op_kind == .amp and self.classifyAmpUnaryModifier(self.ast_arena.getCstOrigin(expr_id)) == .normal_ref) {
                        const inner_id = NodeIndex.fromInt(expr_node.lhs.payload);
                        const is_mut = self.hasDirectMutLeafAfterAmp(self.ast_arena.getCstOrigin(expr_id));
                        if (self.ast_arena.getNode(inner_id).tag == .array_lit) {
                            const exp_node = self.pool.getNode(expected_ty);
                            const slice_elem_opt: ?TypeId = if (exp_node.tag == .slice_ty)
                                TypeId.fromInt(exp_node.lhs)
                            else if (exp_node.tag == .ref_ty or (exp_node.tag == .mut_ref_ty and is_mut and exp_node.rhs == 0)) blk_ref: {
                                const inner_exp = self.pool.getNode(TypeId.fromInt(exp_node.lhs));
                                if (inner_exp.tag == .slice_ty) break :blk_ref TypeId.fromInt(inner_exp.lhs);
                                break :blk_ref null;
                            } else null;
                            if (slice_elem_opt) |slice_elem_ty| {
                                const arr_ty = try self.checkArrayLitWithElemType(inner_id, slice_elem_ty, null);
                                _ = try self.pool.internRef(arr_ty, is_mut);
                                return self.recordNodeType(expr_id, expected_ty);
                            }
                        }
                    }
                }
            },
            .block => {
                return self.checkBlock(expr_id, expected_ty, false);
            },
            .if_expr => {
                return self.synthOrCheckIfExpr(expr_id, expected_ty);
            },
            .match_expr => {
                return self.synthOrCheckMatchExpr(expr_id, expected_ty, false);
            },
            .for_stmt => {
                const for_ty = try self.synthOrCheckForExpr(expr_id, expected_ty);
                if (for_ty.isError() or for_ty == .never_ty) {
                    return self.recordNodeType(expr_id, if (for_ty == .never_ty) expected_ty else .err_ty);
                }
                if (try self.checkTypeCompatibility(expr_id, for_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .while_stmt => {
                const while_ty = try self.synthOrCheckWhileExpr(expr_id, expected_ty);
                if (while_ty.isError() or while_ty == .never_ty) {
                    return self.recordNodeType(expr_id, if (while_ty == .never_ty) expected_ty else .err_ty);
                }
                if (try self.checkTypeCompatibility(expr_id, while_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .loop_expr => {
                const loop_ty = try self.synthOrCheckLoopExpr(expr_id, expected_ty);
                if (loop_ty.isError() or loop_ty == .never_ty) {
                    return self.recordNodeType(expr_id, if (loop_ty == .never_ty) expected_ty else .err_ty);
                }
                if (try self.checkTypeCompatibility(expr_id, loop_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .with_expr => {
                return self.synthOrCheckWithExpr(expr_id, expected_ty);
            },
            .walrus_expr => {
                const walrus_ty = try self.synthOrCheckWalrusExpr(expr_id, expected_ty);
                if (walrus_ty.isError() or walrus_ty == .never_ty) {
                    return self.recordNodeType(expr_id, if (walrus_ty == .never_ty) expected_ty else .err_ty);
                }
                if (try self.checkTypeCompatibility(expr_id, walrus_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .tuple_lit => {
                if (self.pool.getTag(expected_ty) == .tuple_ty) {
                    const elem_nodes = self.getNodeExtraSlice(expr_id, false);
                    const expected_elems = self.pool.getTupleElements(expected_ty);
                    if (elem_nodes.len == expected_elems.len) {
                        const saved_walrus = self.is_dominating_walrus_pos;
                        self.is_dominating_walrus_pos = false;
                        defer self.is_dominating_walrus_pos = saved_walrus;
                        for (elem_nodes, 0..) |raw_elem, i| {
                            _ = try self.checkExpr(
                                NodeIndex.fromInt(raw_elem),
                                TypeId.fromInt(expected_elems[i]),
                            );
                        }
                        return self.recordNodeType(expr_id, expected_ty);
                    }
                }
            },
            .array_lit => {
                const exp_node = self.pool.getNode(expected_ty);
                if (exp_node.tag == .array_ty) {
                    const elem_expected = TypeId.fromInt(exp_node.lhs);
                    const actual_arr_ty = try self.checkArrayLitWithElemType(
                        expr_id,
                        elem_expected,
                        exp_node.rhs,
                    );
                    if (actual_arr_ty.isError()) return self.recordNodeType(expr_id, .err_ty);
                    if (try self.checkTypeCompatibility(expr_id, actual_arr_ty, expected_ty)) {
                        return self.recordNodeType(expr_id, expected_ty);
                    }
                    return self.recordNodeType(expr_id, .err_ty);
                }
            },
            .struct_lit => {
                const actual_struct_ty = try self.synthOrCheckStructLit(expr_id, expected_ty);
                if (actual_struct_ty.isError()) return self.recordNodeType(expr_id, .err_ty);
                if (try self.checkTypeCompatibility(expr_id, actual_struct_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .binary_expr => {
                if (!expr_node.main_token.isNone()) {
                    const bin_op = self.token_buffer.getToken(expr_node.main_token).kind;
                    if (bin_op == .kw_catch) {
                        return self.synthCatchExpr(expr_id, expected_ty);
                    }
                    if (bin_op == .kw_orelse) {
                        return self.synthOrelseExpr(expr_id, expected_ty);
                    }
                    if ((expected_ty.isIntegerPrimitive() or expected_ty.isFloatPrimitive()) and
                        isValuePreservingNumericBinOp(bin_op))
                    {
                        const bin_ty = try self.synthOrCheckBinaryExpr(expr_id, expected_ty);
                        if (bin_ty.isError() or bin_ty == .never_ty) {
                            return self.recordNodeType(expr_id, if (bin_ty == .never_ty) expected_ty else .err_ty);
                        }
                        if (try self.checkTypeCompatibility(expr_id, bin_ty, expected_ty)) {
                            return self.recordNodeType(expr_id, expected_ty);
                        }
                        return self.recordNodeType(expr_id, .err_ty);
                    }
                }
            },
            .method_call => {
                const method_ty = try self.synthOrCheckMethodCallExpr(expr_id, expected_ty);
                if (method_ty.isError() or method_ty == .never_ty) {
                    return self.recordNodeType(expr_id, if (method_ty == .never_ty) expected_ty else .err_ty);
                }
                if (try self.checkTypeCompatibility(expr_id, method_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .closure_expr => {
                const clos_ty = try self.synthOrCheckClosureExpr(expr_id, expected_ty);
                if (clos_ty.isError()) return self.recordNodeType(expr_id, .err_ty);
                if (try self.checkTypeCompatibility(expr_id, clos_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            .await_expr => {
                const aw_ty = try self.synthOrCheckAwaitExpr(expr_id, expected_ty);
                if (aw_ty.isError() or aw_ty == .never_ty) {
                    return self.recordNodeType(expr_id, if (aw_ty == .never_ty) expected_ty else .err_ty);
                }
                if (try self.checkTypeCompatibility(expr_id, aw_ty, expected_ty)) {
                    return self.recordNodeType(expr_id, expected_ty);
                }
                return self.recordNodeType(expr_id, .err_ty);
            },
            else => {},
        }

        // Subsumption rule ($\Rightarrow$ followed by compatibility/refinement check):
        const synth_ty = try self.synthExpr(expr_id);
        if (synth_ty.isError() or synth_ty == .never_ty) {
            return self.recordNodeType(expr_id, if (synth_ty == .never_ty) expected_ty else .err_ty);
        }

        if (try self.checkTypeCompatibility(expr_id, synth_ty, expected_ty)) {
            return self.recordNodeType(expr_id, expected_ty);
        }
        return self.recordNodeType(expr_id, .err_ty);
    }

    /// Synthesis mode ($\Gamma \vdash e \Rightarrow T$): infers the principal `TypeId` of `expr_id`.
    pub fn synthExpr(self: *TypeChecker, expr_id: NodeIndex) anyerror!TypeId {
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return .err_ty;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return self.recordNodeType(expr_id, .err_ty);
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const ast_node = self.ast_arena.getNode(expr_id);
        const prev_pos_cond = self.is_direct_positive_cond;
        if (ast_node.tag != .binary_expr and ast_node.tag != .is_expr) {
            self.is_direct_positive_cond = false;
        }
        defer self.is_direct_positive_cond = prev_pos_cond;

        const inferred: TypeId = switch (ast_node.tag) {
            .expr_hole, .type_hole, .item_hole, .stmt_hole, .pattern_hole, .incomplete_member_access => .err_ty,
            .bool_lit => .bool_ty,
            .char_lit => .char_ty,
            .byte_lit => .u8_ty,
            .byte_string_lit => blk: {
                const lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ast_node.main_token);
                const cooked = lexer.cookStringLiteral(self.allocator, lexeme) catch null;
                defer if (cooked) |bytes| self.allocator.free(bytes);
                const byte_len: u32 = if (cooked) |bytes| @intCast(bytes.len) else 0;
                const arr_ty = try self.pool.internArray(.u8_ty, byte_len, false);
                break :blk try self.pool.internRef(arr_ty, false);
            },
            .string_lit => try self.synthOrCheckStringLit(expr_id, false),
            .int_lit => try self.synthIntLiteral(expr_id, false),
            .float_lit => self.synthFloatLiteral(expr_id),
            .self_val => blk: {
                const self_sym = try self.interner.intern("self");
                switch (self.sym_table.lookupLexical(self.current_scope, self_sym, NamespaceMask.VALUE_ONLY)) {
                    .found => |sym_idx| {
                        self.sym_table.markSymbolUsed(sym_idx);
                        self.recordNodeSymbol(expr_id, sym_idx);
                        try self.checkComptimeSymbolAccess(expr_id, sym_idx);
                        break :blk self.sym_table.getSymbol(sym_idx).type_id;
                    },
                    else => break :blk .err_ty,
                }
            },
            .ident_expr, .path_expr => try self.synthIdentOrPathExpr(expr_id),
            .contextual_variant => blk: {
                const var_tok = if (ast_node.lhs.tag == .token)
                    TokenIndex.fromInt(ast_node.lhs.payload)
                else
                    ast_node.main_token;
                const var_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, var_tok);
                var msg_buf: [160]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "cannot infer contextual variant `.{s}` without an expected `enum`, `T?`, or `T!E` type",
                    .{var_name},
                ) catch "cannot infer contextual variant without an expected type";
                try self.emitDiagnosticSimple(
                    .e0407_invalid_contextual_variant,
                    self.getAstNodeSpan(expr_id),
                    msg,
                    "add an explicit type annotation or qualify the enum name",
                );
                break :blk .err_ty;
            },
            .tuple_lit => blk: {
                const elem_nodes = self.getNodeExtraSlice(expr_id, false);
                if (elem_nodes.len == 0) break :blk .unit_ty;
                const elem_types = try self.allocator.alloc(TypeId, elem_nodes.len);
                defer self.allocator.free(elem_types);
                const saved_walrus = self.is_dominating_walrus_pos;
                self.is_dominating_walrus_pos = false;
                defer self.is_dominating_walrus_pos = saved_walrus;
                for (elem_nodes, 0..) |raw_elem, i| {
                    const e_ty = try self.synthExpr(NodeIndex.fromInt(raw_elem));
                    elem_types[i] = self.materializeUntypedType(e_ty);
                }
                break :blk try self.pool.internTuple(elem_types);
            },
            .array_lit => try self.checkArrayLitWithElemType(expr_id, .err_ty, null),
            .struct_lit => try self.synthStructLit(expr_id),
            .unary_expr => try self.synthUnaryExpr(expr_id),
            .deref_expr => try self.synthDerefExpr(expr_id),
            .binary_expr => try self.synthBinaryExpr(expr_id),
            .pipe_expr => try self.synthPipeExpr(expr_id),
            .try_expr => try self.synthTryExpr(expr_id),
            .cast_expr => blk: {
                const dst_ty = if (ast_node.rhs.tag == .node)
                    try self.resolveTypeAst(NodeIndex.fromInt(ast_node.rhs.payload))
                else
                    .err_ty;
                const src_ty = if (ast_node.lhs.tag == .node) blk_src: {
                    const lhs_id = NodeIndex.fromInt(ast_node.lhs.payload);
                    if (!dst_ty.isError()) {
                        const lhs_tag = self.ast_arena.getNode(lhs_id).tag;
                        const dst_node = self.pool.getNode(dst_ty);
                        if (lhs_tag == .contextual_variant) {
                            const ctx_target = if (dst_node.tag == .distinct_ty)
                                TypeId.fromInt(dst_node.lhs)
                            else
                                dst_ty;
                            break :blk_src try self.checkExpr(lhs_id, ctx_target);
                        }
                        if (dst_node.tag == .distinct_ty and
                            (lhs_tag == .int_lit or lhs_tag == .float_lit))
                        {
                            break :blk_src try self.checkExpr(lhs_id, TypeId.fromInt(dst_node.lhs));
                        }
                        if (dst_node.tag == .raw_ptr_ty and lhs_tag == .int_lit) {
                            break :blk_src try self.checkExpr(lhs_id, .usize_ty);
                        }
                    }
                    break :blk_src try self.synthExpr(lhs_id);
                } else .err_ty;
                try self.validateCastExpr(expr_id, src_ty, dst_ty);
                if (self.pure_comptime_depth > 0 and !src_ty.isError() and !dst_ty.isError()) {
                    const src_node = self.pool.getNode(src_ty);
                    const dst_node = self.pool.getNode(dst_ty);
                    const is_src_ptr = src_node.tag == .raw_ptr_ty or src_node.tag == .ref_ty or
                        src_node.tag == .mut_ref_ty;
                    const is_dst_ptr = dst_node.tag == .raw_ptr_ty or dst_node.tag == .ref_ty or
                        dst_node.tag == .mut_ref_ty;
                    const is_src_int = src_ty.isIntegerPrimitive() or src_ty == .untyped_int_ty;
                    const is_dst_int = dst_ty.isIntegerPrimitive() or dst_ty == .untyped_int_ty;
                    if ((is_src_ptr and is_dst_int) or (is_src_int and is_dst_ptr) or
                        (is_src_ptr and is_dst_ptr and src_node.lhs != dst_node.lhs))
                    {
                        try self.emitDiagnosticSimple(
                            .e0503_forbidden_comptime_operation,
                            self.getAstNodeSpan(expr_id),
                            "pointer-to-integer or type-punning pointer cast is forbidden in `comptime` evaluation",
                            "unsafe pointer reinterpretation is disallowed at compile time",
                        );
                    }
                }
                break :blk dst_ty;
            },
            .field_access => try self.synthFieldAccess(expr_id),
            .index_expr => try self.synthIndexExpr(expr_id),
            .call_expr, .generic_call, .incomplete_call => try self.synthCallExpr(expr_id),
            .method_call => try self.synthMethodCallExpr(expr_id),
            .block => try self.checkBlock(expr_id, .err_ty, false),
            .if_expr => try self.synthOrCheckIfExpr(expr_id, .err_ty),
            .match_expr => try self.synthOrCheckMatchExpr(expr_id, .err_ty, false),
            .for_stmt => try self.synthOrCheckForExpr(expr_id, .err_ty),
            .while_stmt => try self.synthOrCheckWhileExpr(expr_id, .err_ty),
            .loop_expr => try self.synthOrCheckLoopExpr(expr_id, .err_ty),
            .return_stmt => try self.checkReturnStmt(expr_id),
            .break_stmt => try self.checkBreakStmt(expr_id),
            .continue_stmt => try self.checkContinueStmt(expr_id),
            .walrus_expr => try self.synthOrCheckWalrusExpr(expr_id, .err_ty),
            .is_expr => try self.synthIsExpr(expr_id),
            .range_expr => try self.synthRangeExpr(expr_id),
            .dollar_expr => try self.synthDollarExpr(expr_id),
            .context_expr => try self.synthContextExpr(expr_id),
            .with_expr => try self.synthOrCheckWithExpr(expr_id, .err_ty),
            .unreachable_expr => .never_ty,
            .closure_expr => try self.synthClosureExpr(expr_id),
            .await_expr => try self.synthOrCheckAwaitExpr(expr_id, .err_ty),
            else => .err_ty,
        };
        return self.recordNodeType(expr_id, inferred);
    }

    /// Type-checks postfix `expr.await` (`AstTag.await_expr`), enforcing `E0438` and unwrapping `Future[T]` -> `T`.
    fn synthOrCheckAwaitExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        if (!self.is_in_async) {
            if (self.diagnostic_sink) |sink| {
                const span = self.getAstNodeSpan(expr_id);
                const labels = [1]LabeledSpan{.{
                    .span = span,
                    .label = "`.await` requires an enclosing `async` context",
                    .style = .primary,
                }};
                const notes = [1][]const u8{"help: mark the enclosing function or closure `async`"};
                _ = try sink.emit(.{
                    .code = .e0438_await_outside_async_context,
                    .severity = .err,
                    .primary_span = span,
                    .message = "`.await` is only allowed inside an `async fn`, `async` closure, `async` block, or `async test`",
                    .labels = &labels,
                    .notes = &notes,
                });
            }
        }
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        const inner_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const fut_ty = if (!expected_ty.isError()) blk_fut: {
            const inner_tag = self.ast_arena.getNode(inner_id).tag;
            if (inner_tag == .block and self.hasAsyncKeywordInBlockCst(self.ast_arena.getCstOrigin(inner_id))) {
                const exp_fut = try self.pool.internFuture(expected_ty, 0);
                break :blk_fut try self.checkExpr(inner_id, exp_fut);
            }
            break :blk_fut try self.synthExpr(inner_id);
        } else try self.synthExpr(inner_id);

        if (fut_ty.isError() or fut_ty == .never_ty) return fut_ty;
        if (try self.extractAwaitableOutputType(fut_ty)) |out_ty| {
            return self.materializeUntypedType(out_ty);
        }

        var ty_buf: [96]u8 = undefined;
        const ty_str = self.pool.formatType(fut_ty, self.sym_table, &ty_buf);
        var msg_buf: [224]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "`.await` requires a `Future[T]` or `async` expression, found `{s}`",
            .{ty_str},
        ) catch "`.await` requires a `Future[T]` or `async` expression";
        try self.emitDiagnosticSimple(
            .e0401_type_mismatch,
            self.getAstNodeSpan(expr_id),
            msg,
            "not an awaitable `Future` expression",
        );
        return .err_ty;
    }

    /// Unwraps `Future[T]`, `YieldNow`, `Poll[T]`, or nominal `poll(&mut self) -> Poll[T]` awaitables to `T`.
    fn extractAwaitableOutputType(self: *TypeChecker, raw_ty: TypeId) !?TypeId {
        const ty = self.pool.unwrapUnderlyingType(raw_ty);
        if (ty.isError()) return .err_ty;
        if (self.pool.getFutureOutputType(ty)) |out_ty| return out_ty;
        const node = self.pool.getNode(ty);
        if (node.tag == .struct_ty or node.tag == .enum_ty) {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < self.sym_table.symbols.items.len) {
                const sym = self.sym_table.getSymbol(sym_idx).*;
                if (std.mem.eql(u8, sym.name_text, "YieldNow")) {
                    return .unit_ty;
                } else if (std.mem.eql(u8, sym.name_text, "Poll")) {
                    const args = self.pool.getGenericTypeArgs(ty);
                    return if (args.len >= 1) TypeId.fromInt(args[0]) else .unit_ty;
                }
                if (!sym.target_scope.isNone()) {
                    if (self.interner.lookup("poll")) |poll_id| {
                        const poll_idx = self.sym_table.lookupInScopeDirect(
                            sym.target_scope,
                            poll_id,
                            NamespaceMask.VALUE_ONLY,
                        );
                        if (!poll_idx.isNone()) {
                            try self.resolveFnSignatureSymbol(poll_idx);
                            const poll_ty = try self.substituteNominalMemberType(
                                ty,
                                self.sym_table.getSymbol(poll_idx).type_id,
                            );
                            if (self.pool.getFnSignatureView(poll_ty)) |p_sig| {
                                const ret_unwrapped = self.pool.unwrapUnderlyingType(p_sig.ret_ty);
                                const ret_node = self.pool.getNode(ret_unwrapped);
                                if (ret_node.tag == .enum_ty) {
                                    const ret_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(ret_node.rhs)).*;
                                    if (std.mem.eql(u8, ret_sym.name_text, "Poll")) {
                                        const p_args = self.pool.getGenericTypeArgs(ret_unwrapped);
                                        return if (p_args.len >= 1) TypeId.fromInt(p_args[0]) else .unit_ty;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    /// Returns `true` if `mod_scope` is the built-in or `core.async` (`cx.async`) module scope.
    fn isBuiltinAsyncModuleScope(self: *const TypeChecker, mod_scope: ScopeId) bool {
        if (mod_scope.isNone() or self.sym_table.cx_root_scope.isNone()) return false;
        if (self.interner.lookup("async")) |async_id| {
            const idx = self.sym_table.lookupInScopeDirect(
                self.sym_table.cx_root_scope,
                async_id,
                NamespaceMask.VALUE_ONLY,
            );
            if (!idx.isNone() and self.sym_table.getSymbol(idx).target_scope == mod_scope) {
                return true;
            }
        }
        return false;
    }

    /// Returns `true` if `raw_ty` is built-in `TaskGroup[E]` or nominal `core.async.TaskGroup[E]`.
    fn isTaskGroupLikeType(self: *const TypeChecker, raw_ty: TypeId) bool {
        const ty = self.pool.unwrapUnderlyingType(raw_ty);
        if (ty.isError()) return false;
        if (self.pool.isTaskGroupType(ty)) return true;
        const node = self.pool.getNode(ty);
        if (node.tag == .struct_ty) {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < self.sym_table.symbols.items.len) {
                const sym = self.sym_table.getSymbol(sym_idx).*;
                return isStdCoreOrBuiltinSymbol(self.sym_table, sym) and
                    std.mem.eql(u8, sym.name_text, "TaskGroup");
            }
        }
        return false;
    }

    /// Extracts the error `TypeId` `E` from built-in or nominal `TaskGroup[E]`.
    fn extractTaskGroupErrorType(self: *const TypeChecker, raw_ty: TypeId) ?TypeId {
        const ty = self.pool.unwrapUnderlyingType(raw_ty);
        if (self.pool.getTaskGroupErrorType(ty)) |err_ty| return err_ty;
        if (!self.isTaskGroupLikeType(ty)) return null;
        const args = self.pool.getGenericTypeArgs(ty);
        return if (args.len >= 1) TypeId.fromInt(args[0]) else .never_ty;
    }

    /// Returns `true` if `raw_ty` is built-in `TaskHandle[T]` or nominal `core.async.TaskHandle[T]`.
    fn isTaskHandleLikeType(self: *const TypeChecker, raw_ty: TypeId) bool {
        const ty = self.pool.unwrapUnderlyingType(raw_ty);
        if (ty.isError()) return false;
        if (self.pool.isTaskHandleType(ty)) return true;
        const node = self.pool.getNode(ty);
        if (node.tag == .struct_ty) {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < self.sym_table.symbols.items.len) {
                const sym = self.sym_table.getSymbol(sym_idx).*;
                return isStdCoreOrBuiltinSymbol(self.sym_table, sym) and
                    std.mem.eql(u8, sym.name_text, "TaskHandle");
            }
        }
        return false;
    }

    /// Extracts the payload `TypeId` `T` from built-in or nominal `TaskHandle[T]`.
    fn extractTaskHandleValueType(self: *const TypeChecker, raw_ty: TypeId) ?TypeId {
        const ty = self.pool.unwrapUnderlyingType(raw_ty);
        if (self.pool.getTaskHandleValueType(ty)) |val_ty| return val_ty;
        if (!self.isTaskHandleLikeType(ty)) return null;
        const args = self.pool.getGenericTypeArgs(ty);
        return if (args.len >= 1) TypeId.fromInt(args[0]) else .unit_ty;
    }

    /// Returns `true` if `raw_ty` or any nested field/element/variant contains a `TaskGroup` or `TaskHandle`.
    fn hasNurseryScopedHandle(self: *const TypeChecker, raw_ty: TypeId, depth: u32) bool {
        return self.hasNurseryScopedHandleWithSubst(raw_ty, &NominalTypeSubst.EMPTY, depth);
    }

    /// Recursive nursery-handle escape detector propagating `NominalTypeSubst` across nominal containers (`E0309`).
    fn hasNurseryScopedHandleWithSubst(
        self: *const TypeChecker,
        raw_ty: TypeId,
        parent_subst: *const NominalTypeSubst,
        depth: u32,
    ) bool {
        if (depth >= 16 or raw_ty.isError()) return false;
        const subst_ty = parent_subst.resolve(raw_ty);
        if (subst_ty.isError()) return false;
        const ty = self.pool.unwrapUnderlyingType(subst_ty);
        if (self.isTaskGroupLikeType(ty) or self.isTaskHandleLikeType(ty)) return true;
        const node = self.pool.getNode(ty);
        return switch (node.tag) {
            .ref_ty,
            .mut_ref_ty,
            .raw_ptr_ty,
            .optional_ty,
            .array_ty,
            .soa_array_ty,
            .slice_ty,
            .soa_slice_ty,
            .future_ty,
            => self.hasNurseryScopedHandleWithSubst(TypeId.fromInt(node.lhs), parent_subst, depth + 1),
            .result_ty => self.hasNurseryScopedHandleWithSubst(TypeId.fromInt(node.lhs), parent_subst, depth + 1) or
                self.hasNurseryScopedHandleWithSubst(TypeId.fromInt(node.rhs), parent_subst, depth + 1),
            .tuple_ty => blk: {
                for (self.pool.getTupleElements(ty)) |elem_raw| {
                    if (self.hasNurseryScopedHandleWithSubst(
                        TypeId.fromInt(elem_raw),
                        parent_subst,
                        depth + 1,
                    )) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .struct_ty, .enum_ty, .union_ty => blk: {
                for (self.pool.getGenericTypeArgs(ty)) |arg_raw| {
                    if (self.hasNurseryScopedHandleWithSubst(
                        TypeId.fromInt(arg_raw),
                        parent_subst,
                        depth + 1,
                    )) {
                        break :blk true;
                    }
                }
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() < self.sym_table.symbols.items.len) {
                    const sym = self.sym_table.getSymbol(sym_idx).*;
                    if (!sym.target_scope.isNone()) {
                        const child_subst = NominalTypeSubst.fromNominal(
                            self.pool,
                            self.sym_table,
                            ty,
                            sym,
                            parent_subst,
                        );
                        const active_subst = if (child_subst.len > 0) &child_subst else parent_subst;
                        for (self.sym_table.getScopeMembers(sym.target_scope)) |mem_idx| {
                            const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                            if (mem_sym.kind != .field_sym and mem_sym.kind != .enum_variant_sym) continue;
                            if (self.hasNurseryScopedHandleWithSubst(
                                mem_sym.type_id,
                                active_subst,
                                depth + 1,
                            )) {
                                break :blk true;
                            }
                        }
                    }
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Emits `E0309` when a `TaskGroup` or `TaskHandle` escapes its enclosing `task_group` nursery via return.
    fn rejectNurseryHandleEscapeType(self: *TypeChecker, span: Span, ret_ty: TypeId) !void {
        if (self.hasNurseryScopedHandle(ret_ty, 0)) {
            try self.emitDiagnosticSimple(
                .e0309_concurrent_exclusivity_or_escape,
                span,
                "`TaskGroup` and `TaskHandle` cannot escape their enclosing `task_group` nursery scope",
                "structured concurrency handle returned out of `task_group` here",
            );
        }
    }

    /// Resolves the lexical scope depth of the root variable underlying place `expr_id` (`null` if non-local).
    fn resolveRootPlaceScopeDepth(self: *const TypeChecker, expr_id: NodeIndex) ?u16 {
        var cur = expr_id;
        var steps: u32 = 0;
        while (steps < 32 and !cur.isNone() and cur.asInt() < self.ast_arena.countNodes()) : (steps += 1) {
            const node = self.ast_arena.getNode(cur);
            switch (node.tag) {
                .ident_expr, .self_val => {
                    if (cur.asInt() >= self.node_symbols.len) return null;
                    const sym_idx = self.node_symbols[cur.asInt()];
                    if (sym_idx.isNone()) return null;
                    const sym = self.sym_table.getSymbol(sym_idx).*;
                    if (sym.scope_id.isNone()) return 0;
                    return self.sym_table.scope_arena.getScope(sym.scope_id).depth;
                },
                .field_access, .index_expr, .deref_expr => {
                    if (node.lhs.tag != .node) return null;
                    cur = NodeIndex.fromInt(node.lhs.payload);
                },
                else => return null,
            }
        }
        return null;
    }

    /// Type-checks built-in / `core.async` `task_group(…)`, `yield_now()`, and `block_on(…)` calls.
    fn tryCheckStructuredAsyncEntryCall(
        self: *TypeChecker,
        call_id: NodeIndex,
        callee_id: NodeIndex,
        resolved_fn_idx: SymbolIndex,
        fn_name: []const u8,
        explicit_type_args: []const NodeIndex,
        args: []const NodeIndex,
    ) !?TypeId {
        // Resolve `use` aliases to their canonical target symbol:
        var canon_idx = resolved_fn_idx;
        if (!canon_idx.isNone()) {
            const raw_sym = self.sym_table.getSymbol(canon_idx).*;
            if (raw_sym.kind == .use_alias_sym and !raw_sym.target_symbol.isNone()) {
                canon_idx = raw_sym.target_symbol;
            }
        }

        // Only intercept user symbols when they belong to `core.async` / `cx.async` or built-in prelude:
        if (!canon_idx.isNone()) {
            const fn_sym = self.sym_table.getSymbol(canon_idx).*;
            if (fn_sym.kind == .param_sym or fn_sym.kind == .local_let_sym or fn_sym.kind == .local_var_sym) {
                return null;
            }
            if (!fn_sym.flags.is_builtin and !self.isBuiltinAsyncModuleScope(fn_sym.scope_id)) {
                const pkg_id = self.sym_table.getFilePackageId(fn_sym.decl_span.file_id);
                if (pkg_id != .std_core) {
                    return null;
                }
            }
        }

        if (std.mem.eql(u8, fn_name, "yield_now") or
            std.mem.eql(u8, fn_name, "block_on") or
            std.mem.eql(u8, fn_name, "task_group"))
        {
            if (!resolved_fn_idx.isNone()) {
                self.sym_table.markSymbolUsed(resolved_fn_idx);
                self.recordNodeSymbol(call_id, resolved_fn_idx);
                if (!callee_id.isNone()) self.recordNodeSymbol(callee_id, resolved_fn_idx);
            }
        }

        if (std.mem.eql(u8, fn_name, "yield_now")) {
            if (explicit_type_args.len != 0 or args.len != 0) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(call_id),
                    "`yield_now` expects 0 type arguments and 0 value arguments `()`",
                    "expected `yield_now()`",
                );
                for (explicit_type_args) |type_node| _ = try self.resolveTypeAst(type_node);
                for (args) |arg_node_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_node_id));
                return .err_ty;
            }
            const fut_ty = try self.pool.internFuture(.unit_ty, if (!canon_idx.isNone()) canon_idx.asInt() else 0);
            if (!callee_id.isNone()) _ = self.recordNodeType(callee_id, fut_ty);
            return fut_ty;
        }

        if (std.mem.eql(u8, fn_name, "block_on")) {
            if (explicit_type_args.len > 1 or args.len != 1) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(call_id),
                    "`block_on` expects 1 `Future[T]` or `async` argument (`block_on(fut)`)",
                    "expected single future argument here",
                );
                for (explicit_type_args) |type_node| _ = try self.resolveTypeAst(type_node);
                for (args) |arg_node_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_node_id));
                return .err_ty;
            }
            const explicit_out_ty: TypeId = if (explicit_type_args.len == 1)
                try self.resolveTypeAst(explicit_type_args[0])
            else
                .err_ty;
            const arg_id = self.unwrapCallArgExpr(args[0]);
            const arg_ty = if (!explicit_out_ty.isError())
                try self.checkExpr(arg_id, try self.pool.internFuture(explicit_out_ty, 0))
            else
                try self.synthExpr(arg_id);
            if (arg_id != args[0]) _ = self.recordNodeType(args[0], arg_ty);
            try self.verifyCallSiteOwnArgument(arg_id, arg_ty);
            if (arg_ty.isError()) return .err_ty;
            if (try self.extractAwaitableOutputType(arg_ty)) |out_ty| {
                const mat_out = self.materializeUntypedType(out_ty);
                const inst_arr = [1]TypeId{mat_out};
                try self.recordCallInstantiation(call_id, &inst_arr);
                return mat_out;
            }
            if (self.pool.getFnSignatureView(self.pool.unwrapUnderlyingType(arg_ty))) |cb_sig| {
                if (cb_sig.paramCount() == 0 and cb_sig.is_async) {
                    const mat_out = self.materializeUntypedType(cb_sig.ret_ty);
                    const inst_arr = [1]TypeId{mat_out};
                    try self.recordCallInstantiation(call_id, &inst_arr);
                    return mat_out;
                }
            }
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(arg_id),
                "`block_on` requires a `Future[T]` or zero-argument `async` closure",
                "expected `Future[T]` here",
            );
            return .err_ty;
        }

        if (std.mem.eql(u8, fn_name, "task_group")) {
            if (explicit_type_args.len > 1 or args.len != 1) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(call_id),
                    "`task_group` expects 1 nursery callback (`task_group(|group| { … })`)",
                    "expected `|group| { … }` nursery callback",
                );
                for (explicit_type_args) |type_node| _ = try self.resolveTypeAst(type_node);
                for (args) |arg_node_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_node_id));
                return .err_ty;
            }
            const err_ty: TypeId = if (explicit_type_args.len == 1)
                try self.resolveTypeAst(explicit_type_args[0])
            else
                .never_ty;
            const tg_ty = try self.pool.internTaskGroup(err_ty);
            const tg_mut_ref = try self.pool.internRef(tg_ty, true);
            const cb_param_tys = [1]TypeId{tg_mut_ref};
            const cb_param_modes = [1]ParamMode{.inout_mode};
            const expected_cb_ty = try self.pool.internClosureSignatureExt(
                &cb_param_tys,
                &cb_param_modes,
                .err_ty,
                .{},
                .copy_tier,
                false,
                false,
                true,
            );
            const cb_arg_id = self.unwrapCallArgExpr(args[0]);
            const prev_nursery_cb = self.is_in_nursery_cb_arg;
            self.is_in_nursery_cb_arg = true;
            defer self.is_in_nursery_cb_arg = prev_nursery_cb;

            const cb_ty = if (self.ast_arena.getNode(cb_arg_id).tag == .closure_expr)
                try self.synthOrCheckClosureExpr(cb_arg_id, expected_cb_ty)
            else
                try self.synthExpr(cb_arg_id);
            _ = self.recordNodeType(cb_arg_id, cb_ty);
            if (cb_arg_id != args[0]) _ = self.recordNodeType(args[0], cb_ty);
            if (cb_ty.isError()) return .err_ty;

            const cb_sig = self.pool.getFnSignatureView(self.pool.unwrapUnderlyingType(cb_ty)) orelse {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(cb_arg_id),
                    "`task_group` argument must be a closure `|group| { … }`",
                    "expected nursery closure here",
                );
                return .err_ty;
            };
            if (cb_sig.paramCount() != 1) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(cb_arg_id),
                    "`task_group` nursery closure must accept exactly 1 `group` parameter (`|group| { … }`)",
                    "expected 1-parameter nursery closure",
                );
                return .err_ty;
            }
            var raw_res_ty = self.materializeUntypedType(cb_sig.ret_ty);
            if (self.pool.getFutureOutputType(raw_res_ty)) |unwrapped_fut_out| {
                raw_res_ty = unwrapped_fut_out;
            }
            try self.rejectNurseryHandleEscapeType(self.getAstNodeSpan(cb_arg_id), raw_res_ty);
            const final_out_ty = if (err_ty != .never_ty and !err_ty.isError() and
                self.pool.getTag(self.pool.unwrapUnderlyingType(raw_res_ty)) != .result_ty)
                try self.pool.internResult(raw_res_ty, err_ty)
            else
                raw_res_ty;
            const inst_arr = [1]TypeId{final_out_ty};
            try self.recordCallInstantiation(call_id, &inst_arr);
            return try self.pool.internFuture(final_out_ty, 0);
        }

        return null;
    }

    /// Type-checks `group.spawn(task)` and `group.spawn_local(task)`, enforcing `E0309` concurrency rules.
    fn checkTaskGroupSpawnCall(
        self: *TypeChecker,
        call_id: NodeIndex,
        recv_ty: TypeId,
        raw_arg_id: NodeIndex,
        is_local_spawn: bool,
    ) !TypeId {
        _ = recv_ty;
        const cb_arg = self.unwrapCallArgExpr(raw_arg_id);
        const cb_node = self.ast_arena.getNode(cb_arg);
        var spawned_ty: TypeId = .unit_ty;

        if (cb_node.tag == .block) {
            const saved_in_async = self.is_in_async;
            if (self.hasAsyncKeywordInBlockCst(self.ast_arena.getCstOrigin(cb_arg))) {
                self.is_in_async = true;
            }
            defer self.is_in_async = saved_in_async;
            const blk_ty = self.materializeUntypedType(try self.synthExpr(cb_arg));
            spawned_ty = self.pool.getFutureOutputType(blk_ty) orelse blk_ty;
            try self.builder_block_calls.put(self.allocator, call_id.asInt(), .unit_ty);
        } else {
            const cb_ty = try self.synthExpr(cb_arg);
            if (cb_arg != raw_arg_id) _ = self.recordNodeType(raw_arg_id, cb_ty);
            if (!cb_ty.isError()) {
                if (try self.extractAwaitableOutputType(cb_ty)) |fut_out_ty| {
                    spawned_ty = self.materializeUntypedType(fut_out_ty);
                } else if (self.pool.getFnSignatureView(self.pool.unwrapUnderlyingType(cb_ty))) |cb_sig| {
                    if (cb_sig.paramCount() != 0) {
                        try self.emitDiagnosticSimple(
                            .e0401_type_mismatch,
                            self.getAstNodeSpan(cb_arg),
                            "spawned task closure must accept 0 parameters (`async || { … }` or `|| { … }`)",
                            "expected 0-parameter task closure",
                        );
                    }
                    spawned_ty = self.pool.getFutureOutputType(cb_sig.ret_ty) orelse
                        self.materializeUntypedType(cb_sig.ret_ty);
                } else {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(cb_arg),
                        "`TaskGroup.spawn` expects a `Future[T]`, `async` block, or zero-argument task closure",
                        "expected `Future[T]` or task closure here",
                    );
                }
            }
        }

        if (!spawned_ty.isError() and !is_local_spawn) {
            if (self.explainNonSendOrSyncType(spawned_ty, false, 0)) |reason| {
                try self.emitDiagnosticSimple(
                    .e0309_concurrent_exclusivity_or_escape,
                    self.getAstNodeSpan(cb_arg),
                    reason,
                    "spawned task return type is not `Send` across worker threads",
                );
            }
        }
        try self.inspectSpawnedSubtreeCaptures(cb_arg, is_local_spawn);
        return self.pool.internTaskHandle(spawned_ty);
    }

    /// Inspects `spawn_arg_id`'s CST/AST subtree for `!Send`/`!Sync`/raw-ptr/`@thread_local`/short-lived borrows (`E0309`).
    fn inspectSpawnedSubtreeCaptures(
        self: *TypeChecker,
        spawn_arg_id: NodeIndex,
        is_local_spawn: bool,
    ) !void {
        const arg_cst = self.ast_arena.getCstOrigin(spawn_arg_id);
        if (arg_cst.isNone() or arg_cst.asInt() >= self.cst_arena.countNodes()) return;

        const arg_node = self.ast_arena.getNode(spawn_arg_id);
        const is_own_closure = (arg_node.tag == .closure_expr and self.hasOwnKeywordBeforePipeInCst(arg_cst)) or
            (arg_node.tag == .unary_expr and !arg_node.main_token.isNone() and
                self.token_buffer.getToken(arg_node.main_token).kind == .kw_own);
        const caller_depth: u16 = if (self.current_scope.isNone())
            0
        else
            self.sym_table.scope_arena.getScope(self.current_scope).depth;

        const cst_start: usize = arg_cst.asInt();
        const cst_rec = self.cst_arena.getNode(arg_cst);
        const cst_end: usize = @min(
            cst_start + @max(@as(usize, cst_rec.subtree_size), 1),
            self.cst_to_ast.len,
        );

        var reported_syms: std.AutoHashMapUnmanaged(u32, void) = .empty;
        defer reported_syms.deinit(self.allocator);
        var has_reported_expr_violation = false;

        for (self.cst_to_ast[cst_start..cst_end], cst_start..cst_end) |mapped_ast, cur_cst_raw| {
            if (mapped_ast.isNone() or mapped_ast.asInt() >= self.ast_arena.countNodes()) continue;

            // [1] Reject passing raw pointers or `!Send` expressions directly into `group.spawn(…)`:
            if (!is_local_spawn and !has_reported_expr_violation and mapped_ast != spawn_arg_id) {
                const sub_ty = if (mapped_ast.asInt() < self.node_types.len)
                    self.node_types[mapped_ast.asInt()]
                else
                    TypeId.err_ty;
                if (!sub_ty.isError() and self.pool.getTag(self.pool.unwrapUnderlyingType(sub_ty)) == .raw_ptr_ty) {
                    has_reported_expr_violation = true;
                    try self.emitDiagnosticSimple(
                        .e0309_concurrent_exclusivity_or_escape,
                        self.getAstNodeSpan(mapped_ast),
                        "`TaskGroup.spawn` cannot capture or pass raw pointers (`*T` / `*mut T`) across worker threads",
                        "raw pointer is not `Send`; use `group.spawn_local` for single-thread tasks",
                    );
                    continue;
                }
            }

            if (mapped_ast.asInt() >= self.node_symbols.len) continue;
            const sym_idx = self.node_symbols[mapped_ast.asInt()];
            if (sym_idx.isNone() or reported_syms.contains(sym_idx.asInt())) continue;
            const sym = self.sym_table.getSymbol(sym_idx).*;

            // [2] Reject `@thread_local` statics/bindings in cross-thread `group.spawn`:
            const has_ffi_tls = if (self.sym_table.getFfiContract(sym_idx)) |fc| fc.is_thread_local else false;
            if (!is_local_spawn and
                (sym.extra_flags.is_thread_local or has_ffi_tls or self.hasAttrNameOnSymbolCst(sym, "thread_local")))
            {
                try reported_syms.put(self.allocator, sym_idx.asInt(), {});
                try self.emitDiagnosticSimple(
                    .e0309_concurrent_exclusivity_or_escape,
                    self.getAstNodeSpan(mapped_ast),
                    "`TaskGroup.spawn` cannot access `@thread_local` state across worker threads; use `spawn_local`",
                    "`@thread_local` binding accessed inside cross-thread task here",
                );
                continue;
            }

            if (sym.kind != .local_let_sym and sym.kind != .local_var_sym and sym.kind != .param_sym) continue;
            const sym_depth: u16 = if (sym.scope_id.isNone())
                0
            else
                self.sym_table.scope_arena.getScope(sym.scope_id).depth;

            // Skip bindings declared *inside* the spawned closure/block itself:
            if (sym_depth > caller_depth) continue;

            // Determine whether this outer variable is moved (`own`), copied by value, or borrowed:
            const is_explicit_own_use = self.isAstWrappedInExplicitOwn(spawn_arg_id, mapped_ast, cur_cst_raw);
            const is_moved_or_copied = is_explicit_own_use or
                (is_own_closure and self.pool.getTag(self.pool.unwrapUnderlyingType(sym.type_id)) != .ref_ty and
                    self.pool.getTag(self.pool.unwrapUnderlyingType(sym.type_id)) != .mut_ref_ty) or
                (arg_node.tag != .closure_expr and arg_node.tag != .block and
                    !self.isAstAddressTakenInParent(spawn_arg_id, mapped_ast, cur_cst_raw) and
                    self.isCopyType(sym.type_id) and !self.pool.getFlags(sym.type_id).has_regions);

            // [3] Reject capturing the enclosing `TaskGroup` handle itself inside a child task (`E0309`):
            const unwrapped_sym_ty = self.unwrapRefType(self.pool.unwrapUnderlyingType(sym.type_id));
            if (self.isTaskGroupLikeType(unwrapped_sym_ty)) {
                try reported_syms.put(self.allocator, sym_idx.asInt(), {});
                try self.emitDiagnosticSimple(
                    .e0309_concurrent_exclusivity_or_escape,
                    self.getAstNodeSpan(mapped_ast),
                    "spawned task cannot capture its enclosing `TaskGroup`; create a nested `task_group` inside the task instead",
                    "enclosing `TaskGroup` captured by spawned task here",
                );
                continue;
            }

            // [4] Parent-region / nursery scope check (`E0309`): borrowed variables must outlive `nursery_scope_depth`:
            if (!is_moved_or_copied or self.pool.getFlags(sym.type_id).has_regions) {
                if (self.nursery_scope_depth) |n_depth| {
                    if (sym_depth > n_depth) {
                        try reported_syms.put(self.allocator, sym_idx.asInt(), {});
                        try self.emitDiagnosticSimple(
                            .e0309_concurrent_exclusivity_or_escape,
                            self.getAstNodeSpan(mapped_ast),
                            "spawned task cannot borrow variable declared in an inner sub-block shorter than `task_group`",
                            "borrowed variable goes out of scope before `task_group` joins child tasks",
                        );
                        continue;
                    }
                }
            }

            // [5] Cross-thread `Send` / `Sync` check for `group.spawn(…)`:
            if (!is_local_spawn) {
                const sym_unwrapped = self.pool.unwrapUnderlyingType(sym.type_id);
                const sym_tag = self.pool.getTag(sym_unwrapped);
                const is_shared_borrow = (!is_moved_or_copied and
                    !self.isAstMutablyBorrowedInParent(spawn_arg_id, mapped_ast, cur_cst_raw) and
                    sym_tag != .mut_ref_ty) or sym_tag == .ref_ty;
                const check_ty = if (sym_tag == .ref_ty or sym_tag == .mut_ref_ty)
                    TypeId.fromInt(self.pool.getNode(sym_unwrapped).lhs)
                else
                    sym_unwrapped;
                if (self.explainNonSendOrSyncType(check_ty, is_shared_borrow, 0)) |reason| {
                    try reported_syms.put(self.allocator, sym_idx.asInt(), {});
                    try self.emitDiagnosticSimple(
                        .e0309_concurrent_exclusivity_or_escape,
                        self.getAstNodeSpan(mapped_ast),
                        reason,
                        if (is_shared_borrow)
                            "shared `&T` capture across `TaskGroup.spawn` requires `T: Sync`"
                        else
                            "value captured or moved into `TaskGroup.spawn` requires `T: Send`",
                    );
                }
            }
        }
    }

    /// Returns an explanation when `raw_ty` violates `Send` (`is_requiring_sync = false`) or `Sync` (`true`).
    fn explainNonSendOrSyncType(
        self: *const TypeChecker,
        raw_ty: TypeId,
        is_requiring_sync: bool,
        depth: u32,
    ) ?[]const u8 {
        if (explainNonSendOrSyncTypeWithPool(self.pool, self.sym_table, raw_ty, is_requiring_sync, depth)) |reason| {
            return reason;
        }
        if (depth >= 16 or raw_ty.isError()) return null;
        const ty = self.pool.unwrapUnderlyingType(raw_ty);
        if (ty.isError() or ty.isSizedPrimitive()) return null;
        const node = self.pool.getNode(ty);
        if (node.tag == .struct_ty or node.tag == .enum_ty or node.tag == .union_ty) {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < self.sym_table.symbols.items.len) {
                const sym = self.sym_table.getSymbol(sym_idx).*;
                if (self.hasAttrNameOnSymbolCst(sym, "not_send")) {
                    return "non-`Send` type cannot cross worker threads in `TaskGroup.spawn`; use `group.spawn_local`";
                }
                if (is_requiring_sync and self.hasAttrNameOnSymbolCst(sym, "not_sync")) {
                    return "shared `&T` capture in `TaskGroup.spawn` requires `T: Sync` (non-atomic interior mutability is `!Sync`)";
                }
            }
        }
        return null;
    }

    /// Returns `true` if `sym`'s CST declaration carries `@<attr_name>`.
    fn hasAttrNameOnSymbolCst(self: *const TypeChecker, sym: SymbolRecord, attr_name: []const u8) bool {
        if (sym.decl_span.file_id != self.file_id or sym.cst_node.isNone() or
            sym.cst_node.asInt() >= self.cst_arena.countNodes())
        {
            return false;
        }
        const start_idx: usize = sym.cst_node.asInt();
        const rec = self.cst_arena.getNode(sym.cst_node);
        const end_idx: usize = @min(start_idx + @max(@as(usize, rec.subtree_size), 1), self.cst_arena.countNodes());
        var cur = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .attribute) {
                const attr_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                var attr_cur = cur + 1;
                while (attr_cur < attr_end) : (attr_cur += 1) {
                    const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(attr_cur)));
                    if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                        leaf.token.asInt() < self.token_buffer.countTokens())
                    {
                        const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, leaf.token);
                        if (std.mem.eql(u8, lex, attr_name)) return true;
                    }
                }
                if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
            } else if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const tok_kind = self.token_buffer.getToken(sub.token).kind;
                if (tok_kind == .lbrace or tok_kind == .semi or tok_kind == .eq) break;
            }
        }
        return false;
    }

    /// Returns `true` if `target_ast` inside `root_ast` is directly wrapped in `own <target_ast>`.
    fn isAstWrappedInExplicitOwn(
        self: *const TypeChecker,
        root_ast: NodeIndex,
        target_ast: NodeIndex,
        target_cst_raw: usize,
    ) bool {
        _ = root_ast;
        if (target_cst_raw == 0) return false;
        var scan_back: usize = target_cst_raw;
        var steps: usize = 0;
        while (scan_back > 0 and steps < 6) : (steps += 1) {
            scan_back -= 1;
            const prev_cst = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(scan_back)));
            if (prev_cst.subtree_size <= 1 and !prev_cst.token.isNone() and
                prev_cst.token.asInt() < self.token_buffer.countTokens())
            {
                return self.token_buffer.getToken(prev_cst.token).kind == .kw_own;
            }
            if (scan_back < self.cst_to_ast.len) {
                const cand_ast = self.cst_to_ast[scan_back];
                if (!cand_ast.isNone() and cand_ast != target_ast) {
                    const cand_node = self.ast_arena.getNode(cand_ast);
                    if (cand_node.tag == .unary_expr and cand_node.lhs.tag == .node and
                        NodeIndex.fromInt(cand_node.lhs.payload) == target_ast and
                        !cand_node.main_token.isNone() and
                        self.token_buffer.getToken(cand_node.main_token).kind == .kw_own)
                    {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /// Returns `true` if `target_ast` is directly preceded by `&` or `&mut` in `root_ast`.
    fn isAstAddressTakenInParent(
        self: *const TypeChecker,
        root_ast: NodeIndex,
        target_ast: NodeIndex,
        target_cst_raw: usize,
    ) bool {
        _ = root_ast;
        _ = target_ast;
        var scan_back: usize = target_cst_raw;
        var steps: usize = 0;
        while (scan_back > 0 and steps < 6) : (steps += 1) {
            scan_back -= 1;
            const prev_cst = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(scan_back)));
            if (prev_cst.subtree_size <= 1 and !prev_cst.token.isNone() and
                prev_cst.token.asInt() < self.token_buffer.countTokens())
            {
                const tok_kind = self.token_buffer.getToken(prev_cst.token).kind;
                if (tok_kind == .amp) return true;
                if (tok_kind == .kw_mut) continue;
                break;
            }
        }
        return false;
    }

    /// Returns `true` if `target_ast` is directly preceded by `&mut` in `root_ast`.
    fn isAstMutablyBorrowedInParent(
        self: *const TypeChecker,
        root_ast: NodeIndex,
        target_ast: NodeIndex,
        target_cst_raw: usize,
    ) bool {
        _ = root_ast;
        _ = target_ast;
        var has_seen_mut = false;
        var scan_back: usize = target_cst_raw;
        var steps: usize = 0;
        while (scan_back > 0 and steps < 6) : (steps += 1) {
            scan_back -= 1;
            const prev_cst = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(scan_back)));
            if (prev_cst.subtree_size <= 1 and !prev_cst.token.isNone() and
                prev_cst.token.asInt() < self.token_buffer.countTokens())
            {
                const tok_kind = self.token_buffer.getToken(prev_cst.token).kind;
                if (tok_kind == .kw_mut) {
                    has_seen_mut = true;
                    continue;
                }
                if (tok_kind == .amp) return has_seen_mut;
                break;
            }
        }
        return false;
    }

    /// Synthesizes postfix `ptr.*` (`deref_expr`), enforcing `unsafe` on raw pointers and `E0425` on `*opaque` (`ADR-22F`).
    fn synthDerefExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        const inner_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const operand_ty = try self.synthExpr(inner_id);
        if (operand_ty.isError()) return .err_ty;
        const op_node = self.pool.getNode(self.pool.unwrapUnderlyingType(operand_ty));
        switch (op_node.tag) {
            .ref_ty, .mut_ref_ty => return TypeId.fromInt(op_node.lhs),
            .raw_ptr_ty => {
                const pointee_ty = TypeId.fromInt(op_node.lhs);
                if (self.pool.unwrapUnderlyingType(pointee_ty) == .opaque_ty) {
                    try self.emitDiagnosticSimple(
                        .e0425_invalid_opaque_type_usage,
                        self.getAstNodeSpan(expr_id),
                        "cannot dereference raw pointer to unsized `opaque` type; cast to a typed pointer first",
                        "`*opaque` / `*mut opaque` cannot be dereferenced",
                    );
                    return .err_ty;
                }
                if (self.unsafe_depth == 0 and self.pure_comptime_depth == 0) {
                    const deref_cst = self.ast_arena.getCstOrigin(expr_id);
                    const has_cst_err = !deref_cst.isNone() and
                        deref_cst.asInt() < self.cst_arena.countNodes() and
                        self.cst_arena.getNode(deref_cst).flags.has_error;
                    if (!has_cst_err) {
                        try self.emitDiagnosticSimple(
                            .e0324_package_capability_violation,
                            self.getAstNodeSpan(expr_id),
                            "dereferencing a raw pointer requires an `unsafe` block or `unsafe fn`",
                            "raw pointer dereference outside `unsafe` context",
                        );
                    }
                }
                return pointee_ty;
            },
            else => {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(expr_id),
                    "cannot dereference non-pointer / non-reference value",
                    "expected `&T`, `&mut T`, `&out T`, `*T`, or `*mut T`",
                );
                return .err_ty;
            },
        }
    }

    /// Validates `expr as TargetTy` against the exhaustive CoreX cast safety whitelist (`ADR-22D`, `E0401`/`E0405`/`E0406`/`E0423`).
    fn validateCastExpr(self: *TypeChecker, expr_id: NodeIndex, src_ty: TypeId, dst_ty: TypeId) !void {
        if (src_ty.isError() or dst_ty.isError()) return;

        // [0] Forbid stripping `@secret` classification via `as` (`E0405`):
        if (self.pool.getFlags(src_ty).is_secret and !self.pool.getFlags(dst_ty).is_secret) {
            try self.emitDiagnosticSimple(
                .e0405_distinct_type_mixing,
                self.getAstNodeSpan(expr_id),
                "cannot strip `@secret` classification via `as` cast",
                "`@secret` taint cannot be removed with `as`",
            );
            return;
        }
        if (src_ty == dst_ty) return;

        // [1] Forbid casting into a range-refined type (`T is min..=max`) via `as` (`E0406`):
        const dst_base = self.pool.unwrapRefinementBase(dst_ty);
        if (dst_ty != dst_base) {
            try self.emitDiagnosticSimple(
                .e0406_range_refinement_violation,
                self.getAstNodeSpan(expr_id),
                "cannot cast into range-refined type via `as`; use `.narrow[Target]()` or `.try_narrow[Target]()`",
                "`as` cannot bypass range refinement predicate",
            );
            return;
        }

        // [2] Forbid casting into safe references or compiler-managed types (`E0401`):
        const dst_tag = self.pool.getTag(dst_base);
        const is_forbidden_builtin_dst = dst_base == .source_loc_ty or
            dst_base == .fmt_args_ty or
            dst_base == .fmt_spec_ty or
            dst_base == .opaque_ty or
            dst_base == .never_ty or
            dst_base == .bencher_ty;
        if (is_forbidden_builtin_dst or
            dst_tag == .ref_ty or
            dst_tag == .mut_ref_ty or
            dst_tag == .closure_ty or
            dst_tag == .trait_ty or
            dst_tag == .dyn_trait_ty)
        {
            try self.emitTypeMismatch(
                self.getAstNodeSpan(expr_id),
                dst_ty,
                self.materializeUntypedType(src_ty),
            );
            return;
        }

        const src_base = self.pool.unwrapRefinementBase(src_ty);
        if (src_base == dst_base) return;
        const src_tag = self.pool.getTag(src_base);

        // Allow polymorphic type variables in generic bodies once unsafe target categories are ruled out:
        if (src_tag == .type_param or src_tag == .bind_once_group_var or src_tag == .bind_many_any_var or
            dst_tag == .type_param or dst_tag == .bind_once_group_var or dst_tag == .bind_many_any_var)
        {
            return;
        }

        // [3] `distinct` wrap (`T as DistinctT`) and unwrap (`DistinctT as T`):
        if (dst_tag == .distinct_ty) {
            const dst_inner = TypeId.fromInt(self.pool.getNode(dst_base).lhs);
            if (src_ty == dst_inner or
                (self.pool.getTag(dst_inner) != .refined_ty and src_base == dst_inner))
            {
                return;
            }
            if (self.pool.getTag(dst_inner) == .refined_ty and
                src_base == self.pool.unwrapRefinementBase(dst_inner))
            {
                try self.emitDiagnosticSimple(
                    .e0406_range_refinement_violation,
                    self.getAstNodeSpan(expr_id),
                    "cannot wrap unrefined value into `distinct` over range-refined type via `as`; narrow first",
                    "underlying range refinement has not been proven",
                );
                return;
            }
            try self.emitTypeMismatch(
                self.getAstNodeSpan(expr_id),
                dst_ty,
                self.materializeUntypedType(src_ty),
            );
            return;
        }
        if (src_tag == .distinct_ty) {
            const src_inner = TypeId.fromInt(self.pool.getNode(src_base).lhs);
            if (dst_base == src_inner or dst_base == self.pool.unwrapRefinementBase(src_inner)) {
                return;
            }
            try self.emitTypeMismatch(
                self.getAstNodeSpan(expr_id),
                dst_ty,
                self.materializeUntypedType(src_ty),
            );
            return;
        }

        // [4] `bit_field` <-> `BackingInt` exact-width cast (`ADR-22D`):
        if (src_tag == .bit_field_ty) {
            const bf_base = self.pool.unwrapNominalInstantiationBase(src_base);
            const backing_ty = self.pool.unwrapUnderlyingType(TypeId.fromInt(self.pool.getNode(bf_base).lhs));
            const bf_bits = self.computeBitFieldBackingBits(backing_ty);
            const dst_bits: ?u32 = if (getTargetPrimitiveIntBits(dst_base, self.target_layout)) |bits|
                @as(u32, bits)
            else
                null;
            const is_ok = dst_base == backing_ty or
                (dst_base.isIntegerPrimitive() and bf_bits != null and dst_bits == bf_bits);
            if (!is_ok) {
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    self.getAstNodeSpan(expr_id),
                    "`bit_field` can only be cast to its exact-width backing type",
                    "target width does not match `bit_field` backing width",
                );
            }
            return;
        }
        if (dst_tag == .bit_field_ty) {
            const bf_base = self.pool.unwrapNominalInstantiationBase(dst_base);
            const backing_ty = self.pool.unwrapUnderlyingType(TypeId.fromInt(self.pool.getNode(bf_base).lhs));
            const bf_bits = self.computeBitFieldBackingBits(backing_ty);
            const src_bits: ?u32 = if (getTargetPrimitiveIntBits(src_base, self.target_layout)) |bits|
                @as(u32, bits)
            else
                null;
            const is_ok = src_base == backing_ty or src_base == .untyped_int_ty or
                (src_base.isIntegerPrimitive() and bf_bits != null and src_bits == bf_bits);
            if (!is_ok) {
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    self.getAstNodeSpan(expr_id),
                    "value cast to `bit_field` must match its exact backing bit width",
                    "source width does not match `bit_field` backing width",
                );
            }
            return;
        }

        // [5] Backed `enum` -> `Int` (`dst_bits >= backing_bits`) and reject `Int as Enum` / unbacked `enum as Int`:
        if (src_tag == .enum_ty) {
            if (self.pool.getEnumBackingIntType(src_base)) |backing_int| {
                const backing_bits = getTargetPrimitiveIntBits(backing_int, self.target_layout);
                const dst_bits = getTargetPrimitiveIntBits(dst_base, self.target_layout);
                const is_ok = dst_base.isIntegerPrimitive() and backing_bits != null and
                    dst_bits != null and dst_bits.? >= backing_bits.?;
                if (!is_ok) {
                    try self.emitDiagnosticSimple(
                        .e0423_invalid_bitfield_or_enum_cast,
                        self.getAstNodeSpan(expr_id),
                        "backed `enum` can only be cast via `as` to an integer at least as wide as its backing type",
                        "narrowing or non-integer cast of backed `enum`",
                    );
                }
            } else {
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    self.getAstNodeSpan(expr_id),
                    "cannot cast unbacked or payload-bearing `enum` to an integer; add `: Int` backing type",
                    "`enum` lacks an explicit integer backing type",
                );
            }
            return;
        }
        if (dst_tag == .enum_ty) {
            try self.emitDiagnosticSimple(
                .e0423_invalid_bitfield_or_enum_cast,
                self.getAstNodeSpan(expr_id),
                "cannot cast raw value directly to `enum` via `as`; match or construct a variant explicitly",
                "unchecked cast to `enum` is forbidden",
            );
            return;
        }

        // [6] `bool as Int` (`ADR-22D`: `false -> 0`, `true -> 1` for any `Integer`; reject non-integer targets):
        if (src_base == .bool_ty) {
            if (!dst_base.isIntegerPrimitive()) {
                try self.emitDiagnosticSimple(
                    .e0423_invalid_bitfield_or_enum_cast,
                    self.getAstNodeSpan(expr_id),
                    "`bool` can only be cast via `as` to an integer type (`false -> 0`, `true -> 1`)",
                    "non-integer target in `bool as …` cast",
                );
            }
            return;
        }

        // [7] Numeric & `char` scalar casts:
        const is_src_int = src_base.isIntegerPrimitive() or src_base == .untyped_int_ty;
        const is_src_flt = src_base.isFloatPrimitive() or src_base == .untyped_float_ty;
        if ((is_src_int or is_src_flt) and (dst_base.isIntegerPrimitive() or dst_base.isFloatPrimitive())) {
            return;
        }
        if (src_base == .u8_ty and dst_base == .char_ty) return;
        if (src_base == .char_ty and (dst_base == .u32_ty or dst_base == .usize_ty)) return;

        // [8] Raw pointer and safe-reference-to-raw-pointer/address casts:
        if (src_tag == .raw_ptr_ty and
            (dst_tag == .raw_ptr_ty or dst_base == .usize_ty or dst_base == .isize_ty))
        {
            return;
        }
        if ((src_base == .usize_ty or src_base == .isize_ty or src_base == .untyped_int_ty) and
            dst_tag == .raw_ptr_ty)
        {
            return;
        }
        if (src_tag == .ref_ty and
            ((dst_tag == .raw_ptr_ty and self.pool.getNode(dst_base).rhs == 0) or
                dst_base == .usize_ty or dst_base == .isize_ty))
        {
            return;
        }
        if (src_tag == .mut_ref_ty and
            (dst_tag == .raw_ptr_ty or dst_base == .usize_ty or dst_base == .isize_ty))
        {
            return;
        }

        // [9] Reject all other unrelated / composite casts (`E0401`):
        try self.emitTypeMismatch(
            self.getAstNodeSpan(expr_id),
            dst_ty,
            self.materializeUntypedType(src_ty),
        );
    }

    /// Returns the bit width of a `bit_field` backing type (`uN`, `usize`, or `[u8; N]`), or `null` if invalid.
    fn computeBitFieldBackingBits(self: *const TypeChecker, backing_ty: TypeId) ?u32 {
        if (backing_ty.isUnsignedIntPrimitive()) {
            return if (getTargetPrimitiveIntBits(backing_ty, self.target_layout)) |bit_width| @as(u32, bit_width) else null;
        }
        const b_node = self.pool.getNode(backing_ty);
        if (b_node.tag == .array_ty and
            self.pool.unwrapUnderlyingType(TypeId.fromInt(b_node.lhs)) == .u8_ty and
            (b_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0 and b_node.rhs > 0)
        {
            return b_node.rhs * 8;
        }
        return null;
    }

    /// Synthesizes or checks `comptime { … }`, `comptime if …`, `comptime match …`, or `comptime expr` (`DR-05` §3.2).
    fn synthOrCheckComptimePrefixExpr(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_ty: TypeId,
    ) anyerror!TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return self.recordNodeType(expr_id, .err_ty);
        const inner_id = NodeIndex.fromInt(ast_node.lhs.payload);
        if (inner_id.isNone() or inner_id.asInt() >= self.ast_arena.countNodes()) {
            return self.recordNodeType(expr_id, .err_ty);
        }

        const inner_tag = self.ast_arena.getNode(inner_id).tag;
        if (inner_tag == .if_expr) {
            const branch_ty = try self.synthOrCheckComptimeIfNode(inner_id, expected_ty);
            return self.recordNodeType(expr_id, branch_ty);
        }
        if (inner_tag == .match_expr) {
            self.comptime_branch_guard_depth += 1;
            defer self.comptime_branch_guard_depth -= 1;
            const match_ty = try self.synthOrCheckMatchExpr(inner_id, expected_ty, true);
            return self.recordNodeType(expr_id, match_ty);
        }

        const prev_pure_depth = self.pure_comptime_depth;
        const prev_boundary = self.comptime_boundary_scope_depth;
        if (prev_pure_depth == 0) {
            self.comptime_boundary_scope_depth = if (self.current_scope.isNone())
                0
            else
                self.sym_table.scope_arena.getScope(self.current_scope).depth;
        }
        self.pure_comptime_depth = prev_pure_depth + 1;
        defer {
            self.pure_comptime_depth = prev_pure_depth;
            self.comptime_boundary_scope_depth = prev_boundary;
        }

        const res_ty = if (!expected_ty.isError())
            try self.checkExpr(inner_id, expected_ty)
        else
            try self.synthExpr(inner_id);
        return self.recordNodeType(expr_id, res_ty);
    }

    /// Evaluates a `comptime if` (and chained `else if`) condition at compile time, pruning statically dead branches.
    fn synthOrCheckComptimeIfNode(
        self: *TypeChecker,
        if_node_id: NodeIndex,
        expected_ty: TypeId,
    ) anyerror!TypeId {
        const ast_node = self.ast_arena.getNode(if_node_id);
        const saved_scope = self.current_scope;
        const if_scope = try self.sym_table.scope_arena.allocScope(
            .condition_scope,
            self.current_scope,
            .NONE,
            self.file_id,
            .{},
        );
        self.current_scope = if_scope;
        defer self.current_scope = saved_scope;

        var folded_cond: ?i128 = null;
        if (ast_node.lhs.tag == .node) {
            const cond_id = NodeIndex.fromInt(ast_node.lhs.payload);
            const prev_pure_depth = self.pure_comptime_depth;
            const prev_boundary = self.comptime_boundary_scope_depth;
            if (prev_pure_depth == 0) {
                self.comptime_boundary_scope_depth = if (saved_scope.isNone())
                    0
                else
                    self.sym_table.scope_arena.getScope(saved_scope).depth;
            }
            self.pure_comptime_depth = prev_pure_depth + 1;
            defer {
                self.pure_comptime_depth = prev_pure_depth;
                self.comptime_boundary_scope_depth = prev_boundary;
            }

            try self.checkConditionHeader(cond_id);
            folded_cond = try self.evalConstIntExpr(cond_id, false);
        }

        if (ast_node.rhs.tag == .node) {
            const then_id = NodeIndex.fromInt(ast_node.rhs.payload);
            if (folded_cond == null or folded_cond.? != 0) {
                if (folded_cond == null) self.comptime_branch_guard_depth += 1;
                defer if (folded_cond == null) {
                    self.comptime_branch_guard_depth -= 1;
                };
                _ = try self.checkBlock(then_id, .unit_ty, false);
                try symbol_resolver.checkUnusedBindingsInScope(
                    self.sym_table,
                    if_scope,
                    self.interner,
                    self.diagnostic_sink,
                );
            }
            return self.recordNodeType(if_node_id, .unit_ty);
        }

        const branches = self.getNodeExtraSlice(if_node_id, true);
        const then_id = if (branches.len >= 1) NodeIndex.fromInt(branches[0]) else .none;
        const else_id = if (branches.len >= 2) NodeIndex.fromInt(branches[1]) else .none;

        if (folded_cond) |const_flag| {
            if (const_flag != 0) {
                const taken_then_ty = if (!expected_ty.isError())
                    try self.checkBlock(then_id, expected_ty, false)
                else
                    try self.checkBlock(then_id, .err_ty, false);
                try symbol_resolver.checkUnusedBindingsInScope(
                    self.sym_table,
                    if_scope,
                    self.interner,
                    self.diagnostic_sink,
                );
                const mat_then = if (taken_then_ty == .never_ty)
                    (if (!expected_ty.isError()) expected_ty else .never_ty)
                else
                    self.materializeUntypedType(taken_then_ty);
                return self.recordNodeType(if_node_id, mat_then);
            }

            self.current_scope = saved_scope;
            if (else_id.isNone()) return self.recordNodeType(if_node_id, .unit_ty);
            const taken_else_ty = if (self.ast_arena.getNode(else_id).tag == .if_expr)
                try self.synthOrCheckComptimeIfNode(else_id, expected_ty)
            else
                try self.checkBlock(else_id, expected_ty, false);
            const mat_else = if (taken_else_ty == .never_ty)
                (if (!expected_ty.isError()) expected_ty else .never_ty)
            else
                self.materializeUntypedType(taken_else_ty);
            return self.recordNodeType(if_node_id, mat_else);
        }

        // Unfolded polymorphic `comptime if`: check both branches under `comptime_branch_guard_depth`:
        self.comptime_branch_guard_depth += 1;
        defer self.comptime_branch_guard_depth -= 1;

        const then_ty = if (!expected_ty.isError())
            try self.checkBlock(then_id, expected_ty, false)
        else
            try self.checkBlock(then_id, .err_ty, false);
        try symbol_resolver.checkUnusedBindingsInScope(
            self.sym_table,
            if_scope,
            self.interner,
            self.diagnostic_sink,
        );

        self.current_scope = saved_scope;
        const branch_expected = if (!expected_ty.isError())
            expected_ty
        else if (then_ty != .never_ty)
            self.materializeUntypedType(then_ty)
        else
            .err_ty;

        const else_ty = if (!else_id.isNone()) blk: {
            if (self.ast_arena.getNode(else_id).tag == .if_expr) {
                break :blk try self.synthOrCheckComptimeIfNode(else_id, branch_expected);
            }
            break :blk try self.checkBlock(else_id, branch_expected, false);
        } else .unit_ty;

        const final_ty = if (then_ty == .never_ty)
            else_ty
        else if (else_ty == .never_ty)
            then_ty
        else
            self.materializeUntypedType(then_ty);
        return self.recordNodeType(if_node_id, final_ty);
    }

    /// Synthesizes a closure expression (`|p1, p2| body`), binding parameters inside a dedicated `.fn_scope`.
    fn synthClosureExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        return self.synthOrCheckClosureExpr(expr_id, .err_ty);
    }

    /// Synthesizes or contextually checks a closure expression (`|p1: T1, …| -> R body`) inside `.fn_scope`.
    fn synthOrCheckClosureExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const saved_scope = self.current_scope;
        const saved_ret_ty = self.current_fn_ret_ty;
        const saved_defer_depth = self.defer_depth;
        const saved_defer_loop_depth = self.defer_inner_loop_depth;
        const saved_loop_depth = self.loop_frame_depth;
        const saved_pos = self.is_direct_positive_cond;
        const saved_walrus = self.is_dominating_walrus_pos;
        const saved_neg = self.is_negated_is_context;
        const saved_in_async = self.is_in_async;
        const saved_nursery_cb = self.is_in_nursery_cb_arg;
        const saved_nursery_depth = self.nursery_scope_depth;
        const expr_cst_early = self.ast_arena.getCstOrigin(expr_id);
        const is_async_closure_hdr = self.hasAsyncKeywordBeforePipeInCst(expr_cst_early);
        const is_nursery_cb = saved_nursery_cb;
        self.is_in_nursery_cb_arg = false;
        const closure_scope = try self.sym_table.scope_arena.allocScope(
            .fn_scope,
            self.current_scope,
            .NONE,
            self.file_id,
            .{},
        );
        self.current_scope = closure_scope;
        self.current_fn_ret_ty = .err_ty;
        self.defer_depth = 0;
        self.defer_inner_loop_depth = 0;
        self.loop_frame_depth = 0;
        self.is_direct_positive_cond = false;
        self.is_dominating_walrus_pos = false;
        self.is_negated_is_context = false;
        self.is_in_async = is_async_closure_hdr or is_nursery_cb;
        if (is_nursery_cb) {
            self.nursery_scope_depth = self.sym_table.scope_arena.getScope(closure_scope).depth;
        }
        defer {
            self.current_scope = saved_scope;
            self.current_fn_ret_ty = saved_ret_ty;
            self.defer_depth = saved_defer_depth;
            self.defer_inner_loop_depth = saved_defer_loop_depth;
            self.loop_frame_depth = saved_loop_depth;
            self.is_direct_positive_cond = saved_pos;
            self.is_dominating_walrus_pos = saved_walrus;
            self.is_negated_is_context = saved_neg;
            self.is_in_async = saved_in_async;
            self.is_in_nursery_cb_arg = saved_nursery_cb;
            self.nursery_scope_depth = saved_nursery_depth;
        }

        const param_tokens = self.getNodeExtraSlice(expr_id, false);
        const param_count = param_tokens.len;
        const param_types = try self.allocator.alloc(TypeId, param_count);
        defer if (param_types.len > 0) self.allocator.free(param_types);
        const param_modes = try self.allocator.alloc(ParamMode, param_count);
        defer if (param_modes.len > 0) self.allocator.free(param_modes);
        const param_is_mut = try self.allocator.alloc(bool, param_count);
        defer if (param_is_mut.len > 0) self.allocator.free(param_is_mut);
        const has_explicit_mode = try self.allocator.alloc(bool, param_count);
        defer if (has_explicit_mode.len > 0) self.allocator.free(has_explicit_mode);
        @memset(param_types, .err_ty);
        @memset(param_modes, .let_mode);
        @memset(param_is_mut, false);
        @memset(has_explicit_mode, false);

        var explicit_ret_ty: ?TypeId = null;
        const expr_cst = self.ast_arena.getCstOrigin(expr_id);
        const body_cst = if (ast_node.rhs.tag == .node)
            self.ast_arena.getCstOrigin(NodeIndex.fromInt(ast_node.rhs.payload))
        else
            CstNodeIndex.none;
        if (!expr_cst.isNone() and expr_cst.asInt() < self.cst_arena.countNodes()) {
            const cst_start: usize = expr_cst.asInt();
            const cst_rec = self.cst_arena.getNode(expr_cst);
            const full_end: usize = @min(
                cst_start + @max(@as(usize, cst_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            const header_end: usize = if (!body_cst.isNone() and body_cst.asInt() > cst_start)
                @min(@as(usize, body_cst.asInt()), full_end)
            else
                full_end;
            var cursor: usize = cst_start + 1;
            var param_ord: usize = 0;
            while (cursor < header_end) {
                const sub_rec = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cursor)));
                const sub_end = @min(cursor + @max(@as(usize, sub_rec.subtree_size), 1), header_end);
                if (sub_rec.kind == .closure_param and param_ord < param_count) {
                    var colon_pos: ?usize = null;
                    var has_amp = false;
                    var is_local_var = false;
                    var is_mut = false;
                    var mode: ParamMode = .let_mode;
                    var is_mode_explicit = false;
                    var p_cur: usize = cursor + 1;
                    while (p_cur < sub_end) : (p_cur += 1) {
                        const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(p_cur)));
                        const is_leaf = leaf.subtree_size <= 1 and !leaf.flags.is_bracketed;
                        if (!is_leaf or leaf.flags.is_missing_or_injected or leaf.token.isNone() or
                            leaf.token.asInt() >= self.token_buffer.countTokens()) continue;
                        const t_kind = self.token_buffer.getToken(leaf.token).kind;
                        if (t_kind == .colon) {
                            colon_pos = p_cur;
                            break;
                        }
                        if (t_kind == .amp) {
                            has_amp = true;
                        } else if (t_kind == .kw_var) {
                            is_local_var = true;
                            is_mut = true;
                        } else if (t_kind == .kw_mut) {
                            is_mut = true;
                            if (!has_amp) {
                                mode = .inout_mode;
                                is_mode_explicit = true;
                            }
                        } else if (t_kind == .kw_own) {
                            mode = .sink_mode;
                            is_mode_explicit = true;
                        }
                    }
                    if (colon_pos) |c_pos| {
                        const ty_ast = self.findFirstAstInCstRange(c_pos + 1, sub_end);
                        if (!ty_ast.isNone() and self.ast_arena.getNode(ty_ast).tag == .mode_type) {
                            const m_tok = self.ast_arena.getNode(ty_ast).main_token;
                            if (!m_tok.isNone() and m_tok.asInt() < self.token_buffer.countTokens()) {
                                const m_kind = self.token_buffer.getToken(m_tok).kind;
                                const m_lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, m_tok);
                                if (m_kind == .kw_own or std.mem.eql(u8, m_lex, "sink")) {
                                    mode = .sink_mode;
                                    is_mode_explicit = true;
                                } else if (std.mem.eql(u8, m_lex, "inout")) {
                                    mode = .inout_mode;
                                    is_mut = true;
                                    is_mode_explicit = true;
                                } else if (std.mem.eql(u8, m_lex, "set")) {
                                    mode = .set_mode;
                                    is_mut = true;
                                    is_mode_explicit = true;
                                }
                            }
                        }
                        if (!ty_ast.isNone() and isTypeAstTag(self.ast_arena.getNode(ty_ast).tag)) {
                            param_types[param_ord] = try self.resolveTypeAst(ty_ast);
                            if (self.pool.isOutRef(param_types[param_ord])) {
                                mode = .set_mode;
                                is_mode_explicit = true;
                            } else if (self.pool.getTag(param_types[param_ord]) == .closure_ty and
                                (if (self.pool.getFnSignatureView(param_types[param_ord])) |cl_sig|
                                    cl_sig.capture_tier != .copy_tier
                                else
                                    false))
                            {
                                mode = .sink_mode;
                                is_mode_explicit = true;
                            }
                        }
                        const p_ty = param_types[param_ord];
                        const p_tag = self.pool.getTag(p_ty);
                        const p_tok = TokenIndex.fromInt(param_tokens[param_ord]);
                        const p_span = if (!p_tok.isNone() and p_tok.asInt() < self.token_buffer.countTokens())
                            self.token_buffer.getTokenSpan(self.file_id, p_tok)
                        else
                            self.getAstNodeSpan(expr_id);
                        if (is_local_var and (p_tag == .ref_ty or p_tag == .mut_ref_ty or has_amp)) {
                            try self.emitDiagnosticSimple(
                                .e0421_non_copy_value_parameter,
                                p_span,
                                "`var` parameter modifier is only permitted on by-value `Copy` or `own` parameters, not references",
                                "remove `var` from reference parameter binding",
                            );
                        }
                        if (mode == .let_mode and !p_ty.isError() and
                            p_tag != .ref_ty and p_tag != .mut_ref_ty and p_tag != .raw_ptr_ty and
                            p_tag != .slice_ty and p_tag != .soa_slice_ty and p_tag != .fn_ty and
                            p_tag != .bind_once_group_var and p_tag != .bind_many_any_var and
                            !self.isCopyType(p_ty))
                        {
                            try self.emitDiagnosticSimple(
                                .e0421_non_copy_value_parameter,
                                p_span,
                                "closure parameter of non-`Copy` type cannot be passed bare by value; use `&T` or `own T`",
                                "borrow with `&` or take ownership with `own`",
                            );
                        }
                    }
                    param_modes[param_ord] = mode;
                    param_is_mut[param_ord] = is_local_var or (is_mut and !has_amp);
                    has_explicit_mode[param_ord] = is_mode_explicit;
                    param_ord += 1;
                    cursor = sub_end;
                    continue;
                }
                if (sub_rec.kind == .return_type) {
                    const ret_ast = self.findFirstAstInCstRange(cursor + 1, sub_end);
                    if (!ret_ast.isNone() and isTypeAstTag(self.ast_arena.getNode(ret_ast).tag)) {
                        self.is_in_return_type_pos = true;
                        defer self.is_in_return_type_pos = false;
                        explicit_ret_ty = try self.resolveTypeAst(ret_ast);
                    }
                    cursor = sub_end;
                    continue;
                }
                cursor += 1;
            }
        }

        const exp_sig = if (!expected_ty.isError())
            self.pool.getFnSignatureView(self.pool.unwrapUnderlyingType(expected_ty))
        else
            null;
        for (param_tokens, 0..) |raw_tok, i| {
            if (param_types[i].isError()) {
                if (exp_sig) |es| {
                    if (i < es.paramCount() and !self.pool.getFlags(es.getParamType(i)).has_type_vars) {
                        param_types[i] = es.getParamType(i);
                        if (!has_explicit_mode[i]) {
                            param_modes[i] = es.getParamMode(i);
                            if (param_modes[i] == .inout_mode or param_modes[i] == .set_mode) {
                                param_is_mut[i] = true;
                            }
                        }
                    }
                }
            }
            const param_tok = TokenIndex.fromInt(raw_tok);
            if (!param_tok.isNone() and param_tok.asInt() < self.token_buffer.countTokens()) {
                const param_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, param_tok);
                if (param_name.len > 0 and !std.mem.eql(u8, param_name, "_")) {
                    const param_sym = try self.interner.intern(param_name);
                    _ = try self.sym_table.defineSymbol(.{
                        .name = param_sym,
                        .name_text = self.interner.get(param_sym),
                        .kind = .param_sym,
                        .namespace = .value_ns,
                        .visibility = .private,
                        .flags = .{ .is_used = true, .is_mut = param_is_mut[i] },
                        .scope_id = closure_scope,
                        .decl_span = self.token_buffer.getTokenSpan(self.file_id, param_tok),
                        .type_id = param_types[i],
                        .member_ordinal = @intCast(i),
                    }, self.diagnostic_sink);
                }
            }
        }

        const has_builder_attr = self.hasBuilderAttrBeforePipeInCst(expr_cst) or
            (exp_sig != null and exp_sig.?.contracts.has_builder);
        var has_pushed_builder = false;
        if (has_builder_attr and param_types.len > 0 and !param_types[0].isError()) {
            const p0_node = self.pool.getNode(self.pool.unwrapUnderlyingType(param_types[0]));
            const state_ty = if (p0_node.tag == .ref_ty or p0_node.tag == .mut_ref_ty)
                TypeId.fromInt(p0_node.lhs)
            else
                param_types[0];
            if (!state_ty.isError() and self.active_builder_depth < self.active_builder_stack.len) {
                self.active_builder_stack[self.active_builder_depth] = state_ty;
                self.active_builder_depth += 1;
                has_pushed_builder = true;
            }
        }
        defer if (has_pushed_builder) {
            self.active_builder_depth -= 1;
        };

        const target_ret_ty: TypeId = if (explicit_ret_ty) |er|
            er
        else if (exp_sig) |es|
            (if (!es.ret_ty.isError() and !self.pool.getFlags(es.ret_ty).has_type_vars) es.ret_ty else .err_ty)
        else
            .err_ty;
        self.current_fn_ret_ty = target_ret_ty;

        const body_ty: TypeId = if (ast_node.rhs.tag == .node) blk: {
            const body_node = NodeIndex.fromInt(ast_node.rhs.payload);
            if (!target_ret_ty.isError()) {
                const checked_ty = try self.checkExpr(body_node, target_ret_ty);
                break :blk if (checked_ty.isError() and explicit_ret_ty == null) .err_ty else target_ret_ty;
            }
            break :blk self.materializeUntypedType(try self.synthExpr(body_node));
        } else .unit_ty;
        if (is_nursery_cb and !body_ty.isError()) {
            const tail_span = if (ast_node.rhs.tag == .node)
                self.getAstNodeSpan(NodeIndex.fromInt(ast_node.rhs.payload))
            else
                self.getAstNodeSpan(expr_id);
            try self.rejectNurseryHandleEscapeType(tail_span, body_ty);
        }

        var max_capture_tier: OwnershipTier = .copy_tier;
        var has_linear_cap = false;
        var has_any_outer_capture = false;
        const is_own_closure = self.hasOwnKeywordBeforePipeInCst(expr_cst);
        const is_async_closure = self.hasAsyncKeywordBeforePipeInCst(expr_cst);
        if (!expr_cst.isNone() and expr_cst.asInt() < self.cst_arena.countNodes()) {
            const closure_depth = self.sym_table.scope_arena.getScope(closure_scope).depth;
            const cst_start: usize = expr_cst.asInt();
            const cst_rec = self.cst_arena.getNode(expr_cst);
            const cst_end: usize = @min(
                cst_start + @max(@as(usize, cst_rec.subtree_size), 1),
                self.cst_to_ast.len,
            );
            for (self.cst_to_ast[cst_start..cst_end]) |mapped_ast| {
                if (mapped_ast.isNone() or mapped_ast.asInt() >= self.node_symbols.len) continue;
                const cap_sym_idx = self.node_symbols[mapped_ast.asInt()];
                if (cap_sym_idx.isNone()) continue;
                const cap_sym = self.sym_table.getSymbol(cap_sym_idx).*;
                if ((cap_sym.kind == .local_let_sym or cap_sym.kind == .local_var_sym or
                    cap_sym.kind == .param_sym) and !cap_sym.scope_id.isNone())
                {
                    const sym_depth = self.sym_table.scope_arena.getScope(cap_sym.scope_id).depth;
                    if (sym_depth < closure_depth) {
                        has_any_outer_capture = true;
                        if (is_own_closure) {
                            const cap_tier = classifyOwnershipTier(self.pool, self.sym_table, cap_sym.type_id);
                            if (@backingInt(cap_tier) > @backingInt(max_capture_tier)) {
                                max_capture_tier = cap_tier;
                            }
                            if (hasLinearObligation(self.pool, self.sym_table, cap_sym.type_id)) {
                                has_linear_cap = true;
                            }
                        }
                    }
                }
            }
        }
        if (is_own_closure and max_capture_tier == .copy_tier) {
            max_capture_tier = .auto_drop_tier;
        }

        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, closure_scope, self.interner, self.diagnostic_sink);
        return self.pool.internClosureSignatureExt(
            param_types,
            param_modes,
            body_ty,
            .{ .has_builder = has_builder_attr },
            max_capture_tier,
            has_linear_cap,
            is_async_closure,
            has_any_outer_capture or is_own_closure,
        );
    }

    /// Returns `true` if closure CST `cst_id` carries a leading `own` capture modifier before `|`.
    fn hasOwnKeywordBeforePipeInCst(self: *const TypeChecker, cst_id: CstNodeIndex) bool {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = cst_id.asInt();
        const root_rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, root_rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var cur: usize = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .attribute) {
                if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                continue;
            }
            if (sub.subtree_size > 1 or sub.token.isNone() or
                sub.token.asInt() >= self.token_buffer.countTokens()) continue;
            const kind = self.token_buffer.getToken(sub.token).kind;
            if (kind == .kw_own) return true;
            if (kind == .pipe or kind == .pipepipe or kind == .lbrace) break;
        }
        return false;
    }

    /// Returns `true` if closure CST `cst_id` carries a leading `async` modifier before `|`.
    fn hasAsyncKeywordBeforePipeInCst(self: *const TypeChecker, cst_id: CstNodeIndex) bool {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = cst_id.asInt();
        const root_rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, root_rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var cur: usize = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .attribute) {
                if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                continue;
            }
            if (sub.subtree_size > 1 or sub.token.isNone() or
                sub.token.asInt() >= self.token_buffer.countTokens()) continue;
            const kind = self.token_buffer.getToken(sub.token).kind;
            if (kind == .kw_async) return true;
            if (kind == .pipe or kind == .pipepipe or kind == .lbrace) break;
        }
        return false;
    }

    /// Returns `true` if closure CST `cst_id` carries a `@builder` attribute before `|`.
    fn hasBuilderAttrBeforePipeInCst(self: *const TypeChecker, cst_id: CstNodeIndex) bool {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = cst_id.asInt();
        const root_rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, root_rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var cur: usize = start_idx + 1;
        while (cur < end_idx) : (cur += 1) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .attribute) {
                const attr_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                var attr_cur = cur + 1;
                while (attr_cur < attr_end) : (attr_cur += 1) {
                    const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(attr_cur)));
                    if (leaf.subtree_size > 1 or leaf.token.isNone() or
                        leaf.token.asInt() >= self.token_buffer.countTokens()) continue;
                    const kind = self.token_buffer.getToken(leaf.token).kind;
                    if (symbol_resolver.isIdentifierToken(kind)) {
                        const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, leaf.token);
                        if (std.mem.eql(u8, lex, "builder")) return true;
                        break;
                    }
                }
                if (sub.subtree_size > 1) cur += @as(usize, sub.subtree_size) - 1;
                continue;
            }
            if (sub.subtree_size <= 1 and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const kind = self.token_buffer.getToken(sub.token).kind;
                if (kind == .pipe or kind == .pipepipe or kind == .lbrace) break;
            }
        }
        return false;
    }

    /// Type-checks `[e_0, …, e_k]` or `[val; count]` array literals with optional expected element type and length.
    fn checkArrayLitWithElemType(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_elem_ty: TypeId,
        expected_rhs_opt: ?u32,
    ) !TypeId {
        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus;

        const elem_nodes = self.getNodeExtraSlice(expr_id, false);
        const has_expected_elem = !expected_elem_ty.isError();
        if (elem_nodes.len == 0) {
            const empty_elem = if (has_expected_elem) expected_elem_ty else .i32_ty;
            return self.recordNodeType(expr_id, try self.pool.internArray(empty_elem, 0, false));
        }

        const arr_cst = self.ast_arena.getCstOrigin(expr_id);
        if (elem_nodes.len == 2 and hasShallowSemicolonInArrayCst(self.cst_arena, self.token_buffer, arr_cst)) {
            const val_id = NodeIndex.fromInt(elem_nodes[0]);
            const count_id = NodeIndex.fromInt(elem_nodes[1]);
            const resolved_elem_ty = if (has_expected_elem)
                try self.checkExpr(val_id, expected_elem_ty)
            else
                self.materializeUntypedType(try self.synthExpr(val_id));

            if (try self.findConstParamInExpr(count_id, 0)) |const_param_sym_idx| {
                self.pure_comptime_depth += 1;
                defer self.pure_comptime_depth -= 1;
                _ = try self.checkExpr(count_id, .usize_ty);
                if (self.ast_arena.getNode(count_id).tag != .ident_expr) {
                    try self.emitDiagnosticSimple(
                        .e0503_forbidden_comptime_operation,
                        self.getAstNodeSpan(count_id),
                        "compound dependent array repeat count requires a named `const` binding; only direct `[val; N]` is supported",
                        "compound `const` parameter expression in repeat count",
                    );
                    return self.recordNodeType(expr_id, .err_ty);
                }
                const sym_arr = try self.pool.internSymbolicArray(
                    if (has_expected_elem) expected_elem_ty else resolved_elem_ty,
                    self.sym_table.getSymbol(const_param_sym_idx).name,
                    false,
                );
                return self.recordNodeType(expr_id, sym_arr);
            }

            const count_ty = blk_cnt: {
                self.pure_comptime_depth += 1;
                defer self.pure_comptime_depth -= 1;
                break :blk_cnt try self.checkExpr(count_id, .usize_ty);
            };
            if (count_ty.isError()) return self.recordNodeType(expr_id, .err_ty);
            const count_val = (try self.evalConstIntExpr(count_id, true)) orelse {
                return self.recordNodeType(expr_id, .err_ty);
            };
            if (count_val < 0 or count_val > 0x7FFF_FFFF) {
                try self.emitDiagnosticSimple(
                    .e0502_integer_constant_overflow,
                    self.getAstNodeSpan(count_id),
                    "array repeat count must fit within `0..=2147483647`",
                    "invalid negative or overflowing repeat count",
                );
                return self.recordNodeType(expr_id, .err_ty);
            }
            _ = expected_rhs_opt;
            const elem_final = if (has_expected_elem) expected_elem_ty else resolved_elem_ty;
            const rep_ty = try self.pool.internArray(elem_final, @intCast(count_val), false);
            return self.recordNodeType(expr_id, rep_ty);
        }

        const elem_ty = if (has_expected_elem) blk_exp: {
            for (elem_nodes) |raw_elem| {
                _ = try self.checkExpr(NodeIndex.fromInt(raw_elem), expected_elem_ty);
            }
            break :blk_exp expected_elem_ty;
        } else blk_inf: {
            const first_ty = self.materializeUntypedType(
                try self.synthExpr(NodeIndex.fromInt(elem_nodes[0])),
            );
            for (elem_nodes[1..]) |raw_elem| {
                _ = try self.checkExpr(NodeIndex.fromInt(raw_elem), first_ty);
            }
            break :blk_inf first_ty;
        };
        const arr_ty = try self.pool.internArray(elem_ty, @intCast(elem_nodes.len), false);
        return self.recordNodeType(expr_id, arr_ty);
    }

    /// Type-checks any `{expr[=][:spec]}` interpolation segments inside a `.string_lit` (`SE-12` & `SE-13`).
    fn synthOrCheckStringLit(self: *TypeChecker, expr_id: NodeIndex, is_fmt_args_target: bool) !TypeId {
        const str_node = self.ast_arena.getNode(expr_id);
        const ret_ty: TypeId = if (is_fmt_args_target) .fmt_args_ty else .str_ty;
        if (str_node.main_token.isNone() or str_node.main_token.asInt() >= self.token_buffer.countTokens()) {
            return ret_ty;
        }
        const tok_span = self.token_buffer.getTokenSpan(self.file_id, str_node.main_token);
        const lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, str_node.main_token);
        if (isRawStringLexeme(lexeme)) {
            if (is_fmt_args_target) {
                try self.recordStringInterpMeta(expr_id, &.{}, true, false, 1);
            }
            return ret_ty;
        }

        const delim_width: usize = if (lexeme.len >= 6 and
            std.mem.startsWith(u8, lexeme, "\"\"\"") and
            std.mem.endsWith(u8, lexeme, "\"\"\""))
            3
        else if (lexeme.len >= 2 and lexeme[0] == '"' and lexeme[lexeme.len - 1] == '"')
            1
        else
            0;
        if (delim_width == 0) {
            if (is_fmt_args_target) {
                try self.recordStringInterpMeta(expr_id, &.{}, true, false, 1);
            }
            return ret_ty;
        }

        const body = lexeme[delim_width .. lexeme.len - delim_width];
        var holes_list: std.ArrayListUnmanaged(InterpHoleSpec) = .empty;
        defer holes_list.deinit(self.allocator);

        var scan_pos: usize = 0;
        while (scanNextInterpolationSegment(body, scan_pos)) |seg| {
            scan_pos = seg.after_close;
            const raw_hole = body[seg.expr_start..seg.expr_end];
            const split = splitInterpolationHole(raw_hole);

            const fmt_spec: lexer.FmtSpec = if (split.spec_slice) |spec_raw| blk_spec: {
                if (lexer.parseFormatSpec(spec_raw, split.has_debug_eq)) |parsed_spec| {
                    break :blk_spec parsed_spec;
                } else |_| {
                    const spec_start_byte: u32 = tok_span.start_byte +
                        @as(u32, @intCast(delim_width + seg.expr_start + split.spec_offset));
                    const spec_span = Span.init(
                        self.file_id,
                        @min(spec_start_byte, tok_span.end_byte),
                        @min(spec_start_byte + @max(@as(u32, @intCast(spec_raw.len)), 1), tok_span.end_byte),
                    );
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        spec_span,
                        "malformed format specifier in string interpolation",
                        "expected `[[fill]align][sign][#][0][width][.prec][type]` (`?`, `x`, `X`, `b`, `o`, `e`, `E`, `f`, `p`)",
                    );
                    break :blk_spec lexer.FmtSpec.pack(
                        ' ',
                        .none,
                        .default,
                        false,
                        false,
                        if (split.has_debug_eq) .debug else .display,
                        split.has_debug_eq,
                        null,
                        null,
                    );
                }
            } else lexer.FmtSpec.pack(
                ' ',
                .none,
                .default,
                false,
                false,
                if (split.has_debug_eq) .debug else .display,
                split.has_debug_eq,
                null,
                null,
            );

            const expr_trimmed = std.mem.trim(u8, split.expr_slice, " \t\r\n");
            if (expr_trimmed.len == 0) continue;

            const wrapper_prefix = "fn __cx_interp__() {\n";
            const wrapper_suffix = "\n}\n";
            const wrapped_src = try std.mem.concat(
                self.allocator,
                u8,
                &[_][]const u8{ wrapper_prefix, split.expr_slice, wrapper_suffix },
            );
            defer self.allocator.free(wrapped_src);

            var sub_tokens = TokenBuffer.init(self.allocator);
            defer sub_tokens.deinit();
            var sub_cst = LosslessCstArena.init(self.allocator);
            defer sub_cst.deinit();
            var sub_ast = AstArena.init(self.allocator);
            defer sub_ast.deinit();
            var sub_diags = DiagnosticSink.init(self.allocator);
            defer sub_diags.deinit();

            _ = try parser.parseSource(
                wrapped_src,
                self.file_id,
                &sub_tokens,
                &sub_cst,
                &sub_ast,
                &sub_diags,
                self.interner,
            );

            var hole_ty: TypeId = .err_ty;
            if (sub_ast.countNodes() > 1) {
                var sub_checker = try TypeChecker.init(
                    self.allocator,
                    self.interner,
                    self.pool,
                    self.sym_table,
                    self.file_id,
                    wrapped_src,
                    &sub_tokens,
                    &sub_cst,
                    &sub_ast,
                    &sub_diags,
                );
                defer sub_checker.deinit();
                sub_checker.current_scope = self.current_scope;
                sub_checker.current_fn_ret_ty = self.current_fn_ret_ty;
                sub_checker.defer_depth = self.defer_depth;
                sub_checker.unsafe_depth = self.unsafe_depth;
                sub_checker.pure_comptime_depth = self.pure_comptime_depth;
                sub_checker.comptime_boundary_scope_depth = self.comptime_boundary_scope_depth;
                sub_checker.is_in_async = self.is_in_async;
                sub_checker.nursery_scope_depth = self.nursery_scope_depth;
                sub_checker.target_layout = self.target_layout;
                sub_checker.db = self.db;

                const root_node = sub_ast.getNode(.root);
                if (root_node.lhs.tag == .extra and root_node.rhs.tag == .extra and root_node.rhs.payload > 0) {
                    const root_items = sub_ast.getExtraSlice(
                        ExtraIndex.fromInt(root_node.lhs.payload),
                        root_node.rhs.payload,
                    );
                    const fn_node = sub_ast.getNode(NodeIndex.fromInt(root_items[0]));
                    if (fn_node.rhs.tag == .node) {
                        const raw_hole_ty = try sub_checker.checkBlock(
                            NodeIndex.fromInt(fn_node.rhs.payload),
                            .err_ty,
                            false,
                        );
                        hole_ty = sub_checker.materializeUntypedType(raw_hole_ty);
                    }
                }
            }

            const base_in_file: u32 = tok_span.start_byte + @as(u32, @intCast(delim_width + seg.expr_start));
            if (self.diagnostic_sink) |main_sink| {
                const prefix_u32: u32 = @intCast(wrapper_prefix.len);
                for (sub_diags.asSlice()) |sub_diag| {
                    if (sub_diag.severity != .err) continue;
                    const rebased_start = if (sub_diag.primary_span.start_byte >= prefix_u32)
                        base_in_file + (sub_diag.primary_span.start_byte - prefix_u32)
                    else
                        tok_span.start_byte;
                    const span_len = sub_diag.primary_span.end_byte -| sub_diag.primary_span.start_byte;
                    const rebased_span = Span.init(
                        self.file_id,
                        @min(rebased_start, tok_span.end_byte),
                        @min(rebased_start + @max(span_len, 1), tok_span.end_byte),
                    );
                    const msg_copy = try main_sink.arena.asAllocator().dupe(u8, sub_diag.message);
                    const lbl_text = if (sub_diag.labels.len > 0)
                        try main_sink.arena.asAllocator().dupe(u8, sub_diag.labels[0].label)
                    else
                        "in interpolated string expression";
                    const labels = [1]LabeledSpan{
                        .{ .span = rebased_span, .label = lbl_text, .style = .primary },
                    };
                    _ = try main_sink.emit(.{
                        .code = sub_diag.code,
                        .severity = sub_diag.severity,
                        .primary_span = rebased_span,
                        .message = msg_copy,
                        .labels = &labels,
                    });
                }
            }

            const hole_span = Span.init(
                self.file_id,
                @min(base_in_file, tok_span.end_byte),
                @min(base_in_file + @max(@as(u32, @intCast(seg.expr_end - seg.expr_start)), 1), tok_span.end_byte),
            );
            if (!hole_ty.isError()) {
                try self.validateFormatSpecAgainstType(hole_span, hole_ty, fmt_spec);
            }

            const debug_prefix_sym: SymbolId = if (split.has_debug_eq)
                try self.interner.intern(split.debug_prefix_slice)
            else
                .none;
            const sub_expr_span = Span.init(
                self.file_id,
                @min(base_in_file, tok_span.end_byte),
                @min(
                    base_in_file + @max(@as(u32, @intCast(split.expr_slice.len)), 1),
                    tok_span.end_byte,
                ),
            );
            try holes_list.append(self.allocator, .{
                .hole_index = @intCast(holes_list.items.len),
                .has_debug_eq = split.has_debug_eq,
                .spec = fmt_spec,
                .expr_type_id = hole_ty,
                .expr_span = sub_expr_span,
                .raw_expr_text = debug_prefix_sym,
            });
        }

        if (holes_list.items.len > 0 or is_fmt_args_target) {
            try self.recordStringInterpMeta(
                expr_id,
                holes_list.items,
                is_fmt_args_target,
                delim_width == 3,
                @intCast(delim_width),
            );
        }
        return ret_ty;
    }

    /// Stores `StringInterpMeta` for `expr_id` in `self.string_interps`, freeing any overwritten slice.
    fn recordStringInterpMeta(
        self: *TypeChecker,
        expr_id: NodeIndex,
        holes: []const InterpHoleSpec,
        is_fmt_args_mode: bool,
        is_multiline: bool,
        delimiter_width: u8,
    ) !void {
        const owned_holes: []InterpHoleSpec = if (holes.len > 0)
            try self.allocator.dupe(InterpHoleSpec, holes)
        else
            &.{};
        errdefer if (owned_holes.len > 0) self.allocator.free(owned_holes);
        if (try self.string_interps.fetchPut(self.allocator, expr_id.asInt(), .{
            .is_fmt_args_mode = is_fmt_args_mode,
            .is_multiline = is_multiline,
            .delimiter_width = delimiter_width,
            .holes = owned_holes,
        })) |prev_kv| {
            if (prev_kv.value.holes.len > 0) {
                self.allocator.free(prev_kv.value.holes);
            }
        }
    }

    /// Validates `fmt_spec` presentation verb and flags against `hole_ty` (`SE-12`, `E0431`).
    fn validateFormatSpecAgainstType(
        self: *TypeChecker,
        hole_span: Span,
        hole_ty: TypeId,
        fmt_spec: lexer.FmtSpec,
    ) !void {
        const verb = fmt_spec.extractTypeCode();

        // [1] `@secret` values cannot be formatted with `Display` or raw numeric verbs (`E0431`):
        if (self.pool.getFlags(hole_ty).is_secret) {
            if (verb != .debug) {
                try self.emitDiagnosticSimple(
                    .e0431_invalid_format_specifier,
                    hole_span,
                    "cannot format `@secret` value without redacted `:?` (`Debug`) presentation",
                    "`@secret` value would leak via non-`Debug` format specifier",
                );
                return;
            }
            const debug_idx = try self.lookupAndEnsureTraitByName("Debug");
            if (!debug_idx.isNone()) {
                const debug_ty = self.sym_table.getSymbol(debug_idx).type_id;
                if (!(try self.hasTraitImplementation(hole_ty, debug_ty, 0))) {
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        hole_span,
                        "`@secret` type has no custom redacted `Debug` implementation for `:?` formatting",
                        "implement custom redacted `Debug` before formatting `@secret` type",
                    );
                    return;
                }
            }
        }

        const base_ty = self.pool.unwrapRefinementBase(hole_ty);
        const base_node = self.pool.getNode(base_ty);
        switch (verb) {
            .lower_hex, .upper_hex, .binary, .octal => {
                const is_int_ok = base_ty.isIntegerPrimitive() or
                    self.isIntegerBoundedVar(base_ty);
                if (!is_int_ok) {
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        hole_span,
                        "integer radix format specifier (`x`, `X`, `b`, `o`) requires an integer operand",
                        "non-integer expression used with integer format verb",
                    );
                }
            },
            .lower_exp, .upper_exp, .fixed => {
                if (!base_ty.isFloatPrimitive()) {
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        hole_span,
                        "floating-point format specifier (`e`, `E`, `f`) requires an `f32` or `f64` operand",
                        "non-float expression used with floating-point format verb",
                    );
                }
            },
            .pointer => {
                const is_ptr_ok = base_node.tag == .raw_ptr_ty or
                    base_node.tag == .ref_ty or
                    base_node.tag == .mut_ref_ty or
                    base_node.tag == .fn_ty;
                if (!is_ptr_ok) {
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        hole_span,
                        "pointer format specifier (`p`) requires a pointer, reference, or function pointer",
                        "non-pointer expression used with `:p` format verb",
                    );
                }
            },
            .debug => {
                if (base_ty == .opaque_ty) {
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        hole_span,
                        "unsized `opaque` type cannot be formatted",
                        "invalid `opaque` operand in format string",
                    );
                }
            },
            .display => {
                if (base_ty == .opaque_ty) {
                    try self.emitDiagnosticSimple(
                        .e0431_invalid_format_specifier,
                        hole_span,
                        "unsized `opaque` type cannot be formatted",
                        "invalid `opaque` operand in format string",
                    );
                    return;
                }
                if (fmt_spec.extractSignMode() != .default or fmt_spec.hasZeroPad()) {
                    const is_num = base_ty.isIntegerPrimitive() or base_ty.isFloatPrimitive() or
                        self.isIntegerBoundedVar(base_ty);
                    if (!is_num) {
                        try self.emitDiagnosticSimple(
                            .e0431_invalid_format_specifier,
                            hole_span,
                            "numeric sign (`+`/`-`) or zero-padding (`0`) flag requires a numeric operand",
                            "numeric format flag applied to non-numeric expression",
                        );
                    }
                }
            },
        }
    }

    /// Synthesizes the `TypeId` of an integer literal (`int_lit`), verifying suffix bounds (`E0502`).
    fn synthIntLiteral(self: *TypeChecker, lit_id: NodeIndex, is_negated: bool) !TypeId {
        const lit_node = self.ast_arena.getNode(lit_id);
        if (!lit_node.main_token.isNone() and lit_node.main_token.asInt() < self.token_buffer.countTokens() and
            self.token_buffer.getToken(lit_node.main_token).flags.has_lexer_error)
        {
            return .err_ty;
        }
        const lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, lit_node.main_token);
        const parsed = extractIntLiteralValue(lexeme) orelse {
            try self.emitDiagnosticSimple(
                .e0502_integer_constant_overflow,
                self.getAstNodeSpan(lit_id),
                "integer literal overflows maximum representable width",
                "literal value exceeds 128-bit integer capacity",
            );
            return .err_ty;
        };

        const i128_min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;
        if (parsed.is_above_i128_max) {
            if (is_negated and parsed.magnitude == i128_min_abs) {
                if (parsed.suffix_ty) |suffix_ty| {
                    if (suffix_ty != .i128_ty) {
                        try self.emitDiagnosticSimple(
                            .e0502_integer_constant_overflow,
                            self.getAstNodeSpan(lit_id),
                            "integer literal out of range for explicit suffix type",
                            "literal value does not fit in target integer type",
                        );
                    }
                    return suffix_ty;
                }
                return .i128_ty;
            }
            if (!is_negated and parsed.suffix_ty == .u128_ty) {
                return .u128_ty;
            }
            try self.emitDiagnosticSimple(
                .e0502_integer_constant_overflow,
                self.getAstNodeSpan(lit_id),
                "integer literal overflows signed 128-bit integer range",
                "literal value exceeds signed 128-bit capacity",
            );
            return .err_ty;
        }

        const signed_val: i128 = if (is_negated) -parsed.value else parsed.value;
        if (parsed.suffix_ty) |suffix_ty| {
            if (getPrimitiveIntBounds(suffix_ty)) |bounds| {
                if (signed_val < bounds.min_val or signed_val > bounds.max_val) {
                    try self.emitDiagnosticSimple(
                        .e0502_integer_constant_overflow,
                        self.getAstNodeSpan(lit_id),
                        "integer literal out of range for explicit suffix type",
                        "literal value does not fit in target integer type",
                    );
                }
            }
            return suffix_ty;
        }
        return .untyped_int_ty;
    }

    /// Checks an integer literal (possibly negated) against `expected_ty` (`E0502` / `E0406`).
    fn checkIntLiteralAgainstExpected(
        self: *TypeChecker,
        lit_id: NodeIndex,
        is_negated: bool,
        expected_ty: TypeId,
    ) !TypeId {
        const lit_node = self.ast_arena.getNode(lit_id);
        if (!lit_node.main_token.isNone() and lit_node.main_token.asInt() < self.token_buffer.countTokens() and
            self.token_buffer.getToken(lit_node.main_token).flags.has_lexer_error)
        {
            return self.recordNodeType(lit_id, .err_ty);
        }
        const lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, lit_node.main_token);
        const parsed = extractIntLiteralValue(lexeme) orelse {
            try self.emitDiagnosticSimple(
                .e0502_integer_constant_overflow,
                self.getAstNodeSpan(lit_id),
                "integer literal overflows maximum representable width",
                "literal value exceeds integer capacity",
            );
            return self.recordNodeType(lit_id, .err_ty);
        };

        const exp_node = self.pool.getNode(expected_ty);
        const exp_base_ty = self.pool.unwrapRefinementBase(expected_ty);
        const i128_min_abs: u128 = @as(u128, @intCast(std.math.maxInt(i128))) + 1;

        if (parsed.is_above_i128_max) {
            if (!is_negated and exp_base_ty == .u128_ty and self.pool.getRefinementBounds(expected_ty) == null) {
                return self.recordNodeType(lit_id, expected_ty);
            }
            if (is_negated and parsed.magnitude == i128_min_abs and exp_base_ty == .i128_ty) {
                if (self.pool.getRefinementBounds(expected_ty)) |ref_bounds| {
                    if (std.math.minInt(i128) < ref_bounds.min_val) {
                        try self.emitRangeRefinementError(
                            self.getAstNodeSpan(lit_id),
                            expected_ty,
                            std.math.minInt(i128),
                            ref_bounds.min_val,
                            ref_bounds.max_val,
                        );
                        return self.recordNodeType(lit_id, .err_ty);
                    }
                }
                return self.recordNodeType(lit_id, expected_ty);
            }
            try self.emitDiagnosticSimple(
                .e0502_integer_constant_overflow,
                self.getAstNodeSpan(lit_id),
                "integer literal out of bounds for target integer type",
                "literal overflows target integer range",
            );
            return self.recordNodeType(lit_id, .err_ty);
        }

        const signed_val: i128 = if (is_negated) -parsed.value else parsed.value;
        if (parsed.suffix_ty) |suffix_ty| {
            const is_var = exp_node.tag == .bind_once_group_var or
                exp_node.tag == .bind_many_any_var or
                exp_node.tag == .type_param;
            if (!is_var and suffix_ty != expected_ty and suffix_ty != exp_base_ty) {
                try self.emitTypeMismatch(self.getAstNodeSpan(lit_id), expected_ty, suffix_ty);
                return self.recordNodeType(lit_id, .err_ty);
            }
        }

        // [1] Check `T is low..=high` range refinement (`E0406`, `DR-04` Section 1.5):
        if (self.pool.getRefinementBounds(expected_ty)) |ref_bounds| {
            if (signed_val < ref_bounds.min_val or signed_val > ref_bounds.max_val) {
                try self.emitRangeRefinementError(
                    self.getAstNodeSpan(lit_id),
                    expected_ty,
                    signed_val,
                    ref_bounds.min_val,
                    ref_bounds.max_val,
                );
                return self.recordNodeType(lit_id, .err_ty);
            }
            return self.recordNodeType(lit_id, expected_ty);
        }

        // [2] Reject implicit coercion into `distinct` newtype without constructor/cast (`E0405`):
        if (self.pool.getTag(expected_ty) == .distinct_ty) {
            try self.emitDistinctMixingError(
                self.getAstNodeSpan(lit_id),
                expected_ty,
                parsed.suffix_ty orelse .i32_ty,
            );
            return self.recordNodeType(lit_id, .err_ty);
        }

        // [2b] Accept base-10 integer literals carrying explicit `_f32` / `_f64` float suffixes (`SE-13`):
        if (parsed.suffix_ty) |suffix_ty| {
            if ((suffix_ty == .f32_ty or suffix_ty == .f64_ty) and
                (suffix_ty == expected_ty or suffix_ty == exp_base_ty))
            {
                return self.recordNodeType(lit_id, expected_ty);
            }
        }

        // [3] Check primitive integer bounds (`E0502`):
        if (getPrimitiveIntBounds(expected_ty)) |prim_bounds| {
            if (signed_val < prim_bounds.min_val or signed_val > prim_bounds.max_val) {
                try self.emitDiagnosticSimple(
                    .e0502_integer_constant_overflow,
                    self.getAstNodeSpan(lit_id),
                    "integer literal out of bounds for target integer type",
                    "literal overflows target integer range",
                );
                return self.recordNodeType(lit_id, .err_ty);
            }
            return self.recordNodeType(lit_id, expected_ty);
        }

        // [4] Check satisfaction if `expected_ty` is a Type Group variable:
        if (exp_node.tag == .bind_once_group_var or
            exp_node.tag == .bind_many_any_var or
            exp_node.tag == .type_param)
        {
            const group_ty = TypeId.fromInt(exp_node.lhs);
            const check_cand = parsed.suffix_ty orelse .untyped_int_ty;
            if (checkGroupSatisfaction(
                self.pool,
                self.sym_table,
                self.target_layout,
                check_cand,
                group_ty,
            ) != .rejected) {
                return self.recordNodeType(lit_id, expected_ty);
            }
        }

        try self.emitTypeMismatch(
            self.getAstNodeSpan(lit_id),
            expected_ty,
            parsed.suffix_ty orelse .i32_ty,
        );
        return self.recordNodeType(lit_id, .err_ty);
    }

    /// Synthesizes the `TypeId` of a floating-point literal (`float_lit`, `SE-13` `_f32`/`_f64` suffixes).
    fn synthFloatLiteral(self: *const TypeChecker, lit_id: NodeIndex) TypeId {
        const lit_node = self.ast_arena.getNode(lit_id);
        const lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, lit_node.main_token);
        if (lexer.extractNumericSuffix(lexeme)) |parsed| {
            if (parsed.suffix_type) |suffix_ty| {
                if (suffix_ty.isFloatPrimitive()) return suffix_ty;
            }
            return .untyped_float_ty;
        } else |_| {}
        if (std.mem.endsWith(u8, lexeme, "f32")) return .f32_ty;
        if (std.mem.endsWith(u8, lexeme, "f64")) return .f64_ty;
        return .untyped_float_ty;
    }

    /// Unwraps `.use_alias_sym` hops up to a bounded depth (`16`) to reach the defining `SymbolIndex`.
    fn unwrapAliasSymbolIdx(self: *const TypeChecker, sym_idx: SymbolIndex) SymbolIndex {
        var cur = sym_idx;
        var hops: u8 = 0;
        while (!cur.isNone() and cur.asInt() < self.sym_table.countSymbols() and hops < 16) : (hops += 1) {
            const sym = self.sym_table.getSymbol(cur).*;
            if (sym.kind != .use_alias_sym or sym.target_symbol.isNone()) break;
            cur = sym.target_symbol;
        }
        return cur;
    }

    /// Enforces `unsafe` on `extern static mut` and unannotated (non-`@trusted`) `extern static` accesses (`DR-10` §2.3).
    fn checkExternStaticAccess(self: *TypeChecker, expr_id: NodeIndex, sym_idx: SymbolIndex) !void {
        if (sym_idx.isNone() or self.is_in_raw_addr_of) return;
        const resolved_idx = self.unwrapAliasSymbolIdx(sym_idx);
        if (resolved_idx.isNone() or resolved_idx.asInt() >= self.sym_table.countSymbols()) return;
        const sym = self.sym_table.getSymbol(resolved_idx).*;
        if (sym.kind != .extern_static_sym) return;

        if (self.pure_comptime_depth > 0) {
            try self.emitDiagnosticSimple(
                .e0503_forbidden_comptime_operation,
                self.getAstNodeSpan(expr_id),
                "cannot access foreign `extern static` variable during `comptime` evaluation",
                "foreign linker global is unavailable at compile time",
            );
            return;
        }
        if (self.unsafe_depth > 0) return;

        const is_trusted = if (self.sym_table.getFfiContract(resolved_idx)) |contract|
            (contract.is_trusted and !contract.is_unsafe_extern)
        else
            false;
        if (sym.flags.is_mut) {
            try self.emitDiagnosticSimple(
                .e0324_package_capability_violation,
                self.getAstNodeSpan(expr_id),
                "accessing mutable foreign `extern static mut` requires an `unsafe` block or `unsafe fn`",
                "mutable foreign static accessed outside `unsafe` context",
            );
        } else if (!is_trusted) {
            try self.emitDiagnosticSimple(
                .e0324_package_capability_violation,
                self.getAstNodeSpan(expr_id),
                "reading untrusted foreign `extern static` requires an `unsafe` block or `@trusted` contract",
                "foreign static accessed outside `unsafe` context",
            );
        }
    }

    /// Rejects reading outer non-`comptime` runtime variables inside a pure `comptime` context (`E0503`).
    fn checkComptimeSymbolAccess(
        self: *TypeChecker,
        expr_id: NodeIndex,
        sym_idx: SymbolIndex,
    ) !void {
        if (self.pure_comptime_depth == 0 or sym_idx.isNone()) return;
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (sym.kind == .param_sym or sym.kind == .local_let_sym or sym.kind == .local_var_sym) {
            if (sym.flags.is_comptime) return;
            const sym_depth: u16 = if (sym.scope_id.isNone())
                0
            else
                self.sym_table.scope_arena.getScope(sym.scope_id).depth;
            if (sym_depth <= self.comptime_boundary_scope_depth) {
                try self.emitDiagnosticSimple(
                    .e0503_forbidden_comptime_operation,
                    self.getAstNodeSpan(expr_id),
                    "cannot read non-`comptime` runtime variable inside `comptime` evaluation",
                    "runtime variable referenced in `comptime` context",
                );
            }
        }
    }

    /// Resolves an `.ident_expr` or `.path_expr` in value/constant/enum namespace (`E0403` / `E0409`).
    fn synthIdentOrPathExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.tag == .ident_expr) {
            if (!ast_node.main_token.isNone() and
                self.token_buffer.getToken(ast_node.main_token).kind == .at)
            {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(expr_id),
                    "compiler intrinsic must be invoked as a call expression",
                    "add `(…)` or `[T](…)` to invoke this intrinsic",
                );
                return .err_ty;
            }
            const lexeme = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                ast_node.main_token,
            );
            if (lexeme.len == 0) return .err_ty;
            const sym_id = try self.interner.intern(lexeme);
            const span = self.token_buffer.getTokenSpan(self.file_id, ast_node.main_token);

            switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.ALL)) {
                .found => |sym_idx| {
                    self.sym_table.markSymbolUsed(sym_idx);
                    self.recordNodeSymbol(expr_id, sym_idx);
                    try self.checkComptimeSymbolAccess(expr_id, sym_idx);
                    try self.checkExternStaticAccess(expr_id, sym_idx);
                    const target_idx = self.unwrapAliasSymbolIdx(sym_idx);
                    const sym = self.sym_table.getSymbol(target_idx).*;
                    if (self.active_default_param_max_ordinal) |max_ord| {
                        if (sym.kind == .param_sym) {
                            if (sym.scope_id == self.current_scope and sym.member_ordinal >= max_ord) {
                                var msg_buf: [192]u8 = undefined;
                                const msg = std.fmt.bufPrint(
                                    &msg_buf,
                                    "default parameter initializer cannot reference parameter `{s}` declared at or after it",
                                    .{lexeme},
                                ) catch "default parameter initializer cannot reference later parameter";
                                try self.emitDiagnosticSimple(
                                    .e0403_unresolved_symbol,
                                    span,
                                    msg,
                                    "only earlier parameters may be referenced in a default argument",
                                );
                                return .err_ty;
                            }
                            if (!sym.type_id.isError() and !self.isCopyType(sym.type_id)) {
                                var copy_msg_buf: [192]u8 = undefined;
                                const copy_msg = std.fmt.bufPrint(
                                    &copy_msg_buf,
                                    "default parameter initializer cannot reference non-`Copy` parameter `{s}` by value",
                                    .{lexeme},
                                ) catch "default parameter initializer cannot copy non-`Copy` parameter";
                                try self.emitDiagnosticSimple(
                                    .e0304_resource_or_memory_leak,
                                    span,
                                    copy_msg,
                                    "default arguments may only copy `Copy` parameters (`DR-21` `SE-07`)",
                                );
                            }
                        }
                    }
                    if (sym.kind == .fn_sym and sym.type_id.isError()) {
                        try self.resolveFnSignatureSymbol(target_idx);
                    }
                    return self.sym_table.getSymbol(target_idx).type_id;
                },
                .private_error => |priv_idx| {
                    if (self.diagnostic_sink) |sink| {
                        try symbol_resolver.emitPrivateAccessDiagnostic(
                            sink,
                            self.sym_table.getSymbol(priv_idx),
                            span,
                        );
                    }
                    return .err_ty;
                },
                .not_found => {
                    if (self.diagnostic_sink) |sink| {
                        const suggestion = self.sym_table.suggestClosestSymbol(
                            self.current_scope,
                            lexeme,
                            NamespaceMask.VALUE_OR_CONST,
                        );
                        try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                            sink,
                            self.interner,
                            lexeme,
                            span,
                            suggestion,
                        );
                    }
                    return .err_ty;
                },
            }
        }

        // `.path_expr` (`mod.item` or `Enum.Variant`):
        const raw_segs = self.getNodeExtraSlice(expr_id, false);
        if (raw_segs.len == 0) return .err_ty;

        const seg_tokens = try self.allocator.alloc(TokenIndex, raw_segs.len);
        defer self.allocator.free(seg_tokens);
        for (raw_segs, 0..) |raw_tok, i| {
            seg_tokens[i] = TokenIndex.fromInt(raw_tok);
        }

        const last_tok = seg_tokens[seg_tokens.len - 1];
        const last_lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, last_tok);
        const last_span = self.token_buffer.getTokenSpan(self.file_id, last_tok);

        const target_scope = try symbol_resolver.resolveModulePathSegments(
            self.sym_table,
            self.interner,
            self.file_id,
            self.current_scope,
            self.current_scope,
            seg_tokens[0 .. seg_tokens.len - 1],
            self.source,
            self.token_buffer,
            self.diagnostic_sink,
        );
        if (target_scope.isNone()) return .err_ty;

        const last_sym_id = try self.interner.intern(last_lexeme);
        switch (self.sym_table.lookupInTargetScope(
            target_scope,
            self.current_scope,
            last_sym_id,
            NamespaceMask.ALL,
        )) {
            .found => |sym_idx| {
                self.sym_table.markSymbolUsed(sym_idx);
                self.recordNodeSymbol(expr_id, sym_idx);
                try self.checkComptimeSymbolAccess(expr_id, sym_idx);
                try self.checkExternStaticAccess(expr_id, sym_idx);
                const target_idx = self.unwrapAliasSymbolIdx(sym_idx);
                const sym = self.sym_table.getSymbol(target_idx).*;
                if (sym.kind == .fn_sym and sym.type_id.isError()) {
                    try self.resolveFnSignatureSymbol(target_idx);
                } else if (sym.kind == .enum_variant_sym) {
                    for (self.sym_table.symbols.items) |cand_sym| {
                        if (cand_sym.kind == .enum_sym and cand_sym.target_scope == target_scope) {
                            if (sym.type_id == .unit_ty) return cand_sym.type_id;
                            const param_tys = [_]TypeId{sym.type_id};
                            const param_modes = [_]ParamMode{.let_mode};
                            return self.pool.internFn(.fn_ty, &param_tys, &param_modes, cand_sym.type_id, false);
                        }
                    }
                }
                return self.sym_table.getSymbol(target_idx).type_id;
            },
            .private_error => |priv_idx| {
                if (self.diagnostic_sink) |sink| {
                    try symbol_resolver.emitPrivateAccessDiagnostic(
                        sink,
                        self.sym_table.getSymbol(priv_idx),
                        last_span,
                    );
                }
                return .err_ty;
            },
            .not_found => {
                if (self.diagnostic_sink) |sink| {
                    const suggestion = self.sym_table.suggestClosestInScope(
                        target_scope,
                        last_lexeme,
                        NamespaceMask.ALL,
                    );
                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                        sink,
                        self.interner,
                        last_lexeme,
                        last_span,
                        suggestion,
                    );
                }
                return .err_ty;
            },
        }
    }

    /// Emits `E0419` on any `.named_arg` passed to a positional tuple-variant constructor.
    fn rejectNamedArgsInRawSlice(self: *TypeChecker, raw_args: []const u32) !void {
        for (raw_args) |raw_arg| {
            const arg_id = NodeIndex.fromInt(raw_arg);
            if (!arg_id.isNone() and arg_id.asInt() < self.ast_arena.countNodes()) {
                const arg_node = self.ast_arena.getNode(arg_id);
                if (arg_node.tag == .named_arg) {
                    try self.emitDiagnosticSimple(
                        .e0419_invalid_call_arguments,
                        self.token_buffer.getTokenSpan(self.file_id, arg_node.main_token),
                        "tuple variant constructor does not accept named arguments",
                        "pass variant payload arguments positionally",
                    );
                }
            }
        }
    }

    /// Emits `E0419` on any `.named_arg` in `args` passed to a positional tuple-variant constructor.
    fn rejectNamedArgsInNodeSlice(self: *TypeChecker, args: []const NodeIndex) !void {
        for (args) |arg_id| {
            if (!arg_id.isNone() and arg_id.asInt() < self.ast_arena.countNodes()) {
                const arg_node = self.ast_arena.getNode(arg_id);
                if (arg_node.tag == .named_arg) {
                    try self.emitDiagnosticSimple(
                        .e0419_invalid_call_arguments,
                        self.token_buffer.getTokenSpan(self.file_id, arg_node.main_token),
                        "tuple variant constructor does not accept named arguments",
                        "pass variant payload arguments positionally",
                    );
                }
            }
        }
    }

    /// Checks a contextual `.Variant` or `.Variant(args)` expression against `expected_ty` (`E0407`, `DR-04` / `DR-07`).
    fn checkContextualVariant(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_ty: TypeId,
    ) !TypeId {
        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus;

        const expr_node = self.ast_arena.getNode(expr_id);
        const var_tok = if (expr_node.lhs.tag == .token)
            TokenIndex.fromInt(expr_node.lhs.payload)
        else
            expr_node.main_token;
        const var_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, var_tok);
        const arg_nodes = self.getNodeExtraSlice(expr_id, true);
        try self.rejectNamedArgsInRawSlice(arg_nodes);

        const exp_node = self.pool.getNode(expected_ty);
        switch (exp_node.tag) {
            .optional_ty => {
                const payload_ty = TypeId.fromInt(exp_node.lhs);
                if (std.mem.eql(u8, var_name, "None")) {
                    if (arg_nodes.len > 0) {
                        try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), .unit_ty, payload_ty);
                    }
                    return self.recordNodeType(expr_id, expected_ty);
                }
                if (std.mem.eql(u8, var_name, "Some")) {
                    if (arg_nodes.len == 1) {
                        const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(arg_nodes[0]));
                        _ = try self.checkExpr(val_arg, payload_ty);
                    } else {
                        try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), payload_ty, .unit_ty);
                    }
                    return self.recordNodeType(expr_id, expected_ty);
                }
            },
            .result_ty => {
                const ok_ty = TypeId.fromInt(exp_node.lhs);
                const err_ty_arg = TypeId.fromInt(exp_node.rhs);
                if (std.mem.eql(u8, var_name, "Ok")) {
                    if (arg_nodes.len == 1 and ok_ty != .unit_ty) {
                        const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(arg_nodes[0]));
                        _ = try self.checkExpr(val_arg, ok_ty);
                    } else if (arg_nodes.len == 1 and ok_ty == .unit_ty) {
                        const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(arg_nodes[0]));
                        const extra_ty = self.materializeUntypedType(try self.synthExpr(val_arg));
                        if (extra_ty != .unit_ty) {
                            try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), .unit_ty, extra_ty);
                        }
                    } else if (arg_nodes.len > 1) {
                        try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), ok_ty, .unit_ty);
                    } else if (ok_ty != .unit_ty) {
                        try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), ok_ty, .unit_ty);
                    }
                    return self.recordNodeType(expr_id, expected_ty);
                }
                if (std.mem.eql(u8, var_name, "Err")) {
                    if (arg_nodes.len == 1 and err_ty_arg != .unit_ty) {
                        const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(arg_nodes[0]));
                        _ = try self.checkExpr(val_arg, err_ty_arg);
                    } else if (arg_nodes.len == 1 and err_ty_arg == .unit_ty) {
                        const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(arg_nodes[0]));
                        const extra_ty = self.materializeUntypedType(try self.synthExpr(val_arg));
                        if (extra_ty != .unit_ty) {
                            try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), .unit_ty, extra_ty);
                        }
                    } else if (arg_nodes.len > 1) {
                        try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), err_ty_arg, .unit_ty);
                    } else if (err_ty_arg != .unit_ty) {
                        try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), err_ty_arg, .unit_ty);
                    }
                    return self.recordNodeType(expr_id, expected_ty);
                }
            },
            .enum_ty => {
                const enum_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(exp_node.rhs)).*;
                if (!enum_sym.target_scope.isNone()) {
                    if (self.interner.lookup(var_name)) |var_sym_id| {
                        const v_idx = self.sym_table.lookupInScopeDirect(
                            enum_sym.target_scope,
                            var_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        );
                        if (!v_idx.isNone()) {
                            self.sym_table.markSymbolUsed(v_idx);
                            self.recordNodeSymbol(expr_id, v_idx);
                            const v_sym = self.sym_table.getSymbol(v_idx).*;
                            const var_payload_ty = try self.substituteNominalMemberType(
                                expected_ty,
                                v_sym.type_id,
                            );
                            if (var_payload_ty == .unit_ty) {
                                if (arg_nodes.len > 0) {
                                    for (arg_nodes) |raw_arg| {
                                        const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(raw_arg));
                                        _ = try self.synthExpr(val_arg);
                                    }
                                    try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), .unit_ty, expected_ty);
                                }
                            } else if (self.pool.getTag(var_payload_ty) == .tuple_ty) {
                                const tup_elems = self.pool.getTupleElements(var_payload_ty);
                                if (arg_nodes.len != tup_elems.len) {
                                    try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), var_payload_ty, .unit_ty);
                                }
                                for (arg_nodes, 0..) |raw_arg, i| {
                                    const exp_elem = if (i < tup_elems.len)
                                        TypeId.fromInt(tup_elems[i])
                                    else
                                        .err_ty;
                                    const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(raw_arg));
                                    _ = try self.checkExpr(val_arg, exp_elem);
                                }
                            } else if (arg_nodes.len == 1) {
                                const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(arg_nodes[0]));
                                _ = try self.checkExpr(val_arg, var_payload_ty);
                            } else {
                                for (arg_nodes) |raw_arg| {
                                    const val_arg = self.unwrapCallArgExpr(NodeIndex.fromInt(raw_arg));
                                    _ = try self.synthExpr(val_arg);
                                }
                                if (!var_payload_ty.isError()) {
                                    try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), var_payload_ty, .unit_ty);
                                }
                            }
                            return self.recordNodeType(expr_id, expected_ty);
                        }
                    }
                }
            },
            else => {},
        }

        // Emit `E0407` unresolved contextual variant:
        var expected_buf: [96]u8 = undefined;
        const expected_str = self.pool.formatType(expected_ty, self.sym_table, &expected_buf);
        var msg_buf: [192]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "contextual variant `.{s}` does not exist on expected type `{s}`",
            .{ var_name, expected_str },
        ) catch "unresolved contextual variant for expected type";
        try self.emitDiagnosticSimple(
            .e0407_invalid_contextual_variant,
            self.getAstNodeSpan(expr_id),
            msg,
            "variant not found on expected type",
        );
        return self.recordNodeType(expr_id, .err_ty);
    }

    /// Synthesizes a `StructLiteral` expression (`Point { x: 1, y: 2 }`).
    fn synthStructLit(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        return self.synthOrCheckStructLit(expr_id, .err_ty);
    }

    /// Synthesizes or checks a `StructLiteral` expression, inferring or substituting generic nominal arguments.
    fn synthOrCheckStructLit(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_ty: TypeId,
    ) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        const path_node_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const path_tag = self.ast_arena.getNode(path_node_id).tag;
        var struct_ty: TypeId = if (path_tag == .generic_type)
            try self.resolveTypeAst(path_node_id)
        else if (path_tag == .field_access or path_tag == .generic_call or path_tag == .ident_expr) blk_dot: {
            switch (try self.classifyDotReceiver(path_node_id)) {
                .type_ns => |resolved_ty| break :blk_dot resolved_ty,
                .poisoned => return .err_ty,
                .module_ns, .value_expr => break :blk_dot try self.resolveNamedOrGroupTypeRaw(path_node_id),
            }
        } else try self.resolveNamedOrGroupTypeRaw(path_node_id);
        if (struct_ty.isError()) return .err_ty;

        if (!expected_ty.isError()) {
            const exp_unwrapped = self.pool.unwrapUnderlyingType(expected_ty);
            const act_unwrapped = self.pool.unwrapUnderlyingType(struct_ty);
            const exp_node = self.pool.getNode(exp_unwrapped);
            const act_node = self.pool.getNode(act_unwrapped);
            if ((act_node.tag == .struct_ty or act_node.tag == .union_ty) and
                act_node.tag == exp_node.tag and
                act_node.rhs == exp_node.rhs and
                self.pool.getGenericTypeArgs(act_unwrapped).len == 0 and
                self.pool.getGenericTypeArgs(exp_unwrapped).len > 0)
            {
                struct_ty = exp_unwrapped;
            }
        }

        const unwrapped_struct_ty = self.pool.unwrapUnderlyingType(struct_ty);
        const struct_node = self.pool.getNode(unwrapped_struct_ty);
        const target_scope: ScopeId = if (struct_node.tag == .struct_ty or
            struct_node.tag == .union_ty or struct_node.tag == .bit_field_ty)
            self.sym_table.getSymbol(SymbolIndex.fromInt(struct_node.rhs)).target_scope
        else
            .none;

        var header_type_params: [16]TypeId = undefined;
        var header_param_count: usize = 0;
        const is_uninstantiated_generic = !target_scope.isNone() and
            self.pool.getGenericTypeArgs(unwrapped_struct_ty).len == 0;
        if (is_uninstantiated_generic) {
            for (self.sym_table.getScopeMembers(target_scope)) |mem_idx| {
                const mem_sym = self.sym_table.getSymbol(mem_idx);
                if (mem_sym.kind == .type_param_sym and header_param_count < header_type_params.len) {
                    header_type_params[header_param_count] = mem_sym.type_id;
                    header_param_count += 1;
                }
            }
        }
        var inferred_subst: SubstitutionMap = .{};
        defer inferred_subst.deinit(self.allocator);

        const field_exprs = self.getNodeExtraSlice(expr_id, true);
        const lit_cst = self.ast_arena.getCstOrigin(expr_id);

        // Extract `.field_init` field name tokens in order from `lit_cst`, stopping before `..` / `..base` (`SE-14`):
        var field_name_tokens: std.ArrayListUnmanaged(TokenIndex) = .empty;
        defer field_name_tokens.deinit(self.allocator);
        var has_dotdot_rest = false;
        if (!lit_cst.isNone() and lit_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = lit_cst.asInt();
            const rec = self.cst_arena.getNode(lit_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var cur = start_idx + 1;
            while (cur < end_idx) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.kind == .field_init) {
                    const f_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    var f_cur = cur + 1;
                    while (f_cur < f_end) : (f_cur += 1) {
                        const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(f_cur)));
                        const is_leaf = leaf.subtree_size <= 1 and !leaf.flags.is_bracketed;
                        if (is_leaf and !leaf.flags.is_missing_or_injected and !leaf.token.isNone() and
                            leaf.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tok_kind = self.token_buffer.getToken(leaf.token).kind;
                            if (tok_kind == .dotdot) {
                                has_dotdot_rest = true;
                                break;
                            }
                            if (symbol_resolver.isIdentifierToken(tok_kind)) {
                                try field_name_tokens.append(self.allocator, leaf.token);
                                break;
                            }
                        }
                    }
                    cur = f_end;
                    continue;
                }
                cur += 1;
            }
        }

        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus;

        const explicit_field_count: usize = if (has_dotdot_rest)
            @min(field_exprs.len, field_name_tokens.items.len)
        else
            field_exprs.len;
        const spread_expr_id: NodeIndex = if (has_dotdot_rest and field_exprs.len > field_name_tokens.items.len)
            NodeIndex.fromInt(field_exprs[field_exprs.len - 1])
        else
            .none;

        var mentioned_fields: std.AutoHashMapUnmanaged(u32, void) = .empty;
        defer mentioned_fields.deinit(self.allocator);

        for (field_exprs[0..explicit_field_count], 0..) |raw_val_expr, i| {
            const val_expr_id = NodeIndex.fromInt(raw_val_expr);
            var expected_field_ty: TypeId = .err_ty;
            if (!target_scope.isNone() and i < field_name_tokens.items.len) {
                const f_tok = field_name_tokens.items[i];
                const f_span = self.token_buffer.getTokenSpan(self.file_id, f_tok);
                const f_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, f_tok);
                const f_sym_id = try self.interner.intern(f_name);
                switch (self.sym_table.lookupInTargetScope(
                    target_scope,
                    self.current_scope,
                    f_sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => |f_sym_idx| {
                        self.sym_table.markSymbolUsed(f_sym_idx);
                        try mentioned_fields.put(self.allocator, f_sym_idx.asInt(), {});
                        expected_field_ty = try self.substituteNominalMemberType(
                            unwrapped_struct_ty,
                            self.sym_table.getSymbol(f_sym_idx).type_id,
                        );
                    },
                    .private_error => |priv_idx| {
                        try mentioned_fields.put(self.allocator, priv_idx.asInt(), {});
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitFieldVisibilityDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                f_span,
                            );
                        }
                        expected_field_ty = try self.substituteNominalMemberType(
                            unwrapped_struct_ty,
                            self.sym_table.getSymbol(priv_idx).type_id,
                        );
                    },
                    .not_found => {
                        if (self.diagnostic_sink) |sink| {
                            const suggestion = self.sym_table.suggestClosestInScope(
                                target_scope,
                                f_name,
                                NamespaceMask.VALUE_ONLY,
                            );
                            try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                sink,
                                self.interner,
                                f_name,
                                f_span,
                                suggestion,
                            );
                        }
                    },
                }
            }
            if (!expected_field_ty.isError()) {
                if (header_param_count > 0 and self.pool.getFlags(expected_field_ty).has_type_vars) {
                    const current_expected = try inferred_subst.apply(self.pool, expected_field_ty);
                    if (!self.pool.getFlags(current_expected).has_type_vars) {
                        _ = try self.checkExpr(val_expr_id, current_expected);
                    } else {
                        const val_ty = self.materializeUntypedType(try self.synthExpr(val_expr_id));
                        if (!val_ty.isError()) {
                            _ = try self.unifyParamTypeWithArg(
                                expected_field_ty,
                                val_ty,
                                self.getAstNodeSpan(val_expr_id),
                                &inferred_subst,
                                true,
                            );
                        }
                    }
                } else {
                    _ = try self.checkExpr(val_expr_id, expected_field_ty);
                }
            } else {
                _ = try self.synthExpr(val_expr_id);
            }
        }

        var is_own_spread = false;
        var spread_base_id: NodeIndex = spread_expr_id;
        if (!spread_expr_id.isNone()) {
            const spread_node = self.ast_arena.getNode(spread_expr_id);
            if (spread_node.tag == .unary_expr and !spread_node.main_token.isNone() and
                self.token_buffer.getToken(spread_node.main_token).kind == .kw_own and
                spread_node.lhs.tag == .node)
            {
                is_own_spread = true;
                spread_base_id = NodeIndex.fromInt(spread_node.lhs.payload);
            }
            if (header_param_count > 0 and struct_ty == unwrapped_struct_ty) {
                const prev_own = self.is_in_explicit_own_expr;
                if (is_own_spread) self.is_in_explicit_own_expr = true;
                const spread_ty = blk_sp: {
                    defer self.is_in_explicit_own_expr = prev_own;
                    break :blk_sp self.materializeUntypedType(try self.synthExpr(spread_base_id));
                };
                _ = self.recordNodeType(spread_expr_id, spread_ty);
                if (!spread_ty.isError()) {
                    const generic_self_ty = try self.internNominalWithResolvedArgs(
                        unwrapped_struct_ty,
                        header_type_params[0..header_param_count],
                    );
                    _ = try self.unifyParamTypeWithArg(
                        generic_self_ty,
                        spread_ty,
                        self.getAstNodeSpan(spread_expr_id),
                        &inferred_subst,
                        true,
                    );
                }
            }
        }

        if (header_param_count > 0 and struct_ty == unwrapped_struct_ty) {
            var inferred_args: [16]TypeId = undefined;
            var has_all_inferred = true;
            var p_idx: usize = 0;
            while (p_idx < header_param_count) : (p_idx += 1) {
                if (inferred_subst.lookup(header_type_params[p_idx])) |bound_arg| {
                    inferred_args[p_idx] = self.materializeUntypedType(bound_arg);
                } else {
                    has_all_inferred = false;
                    break;
                }
            }
            if (has_all_inferred) {
                struct_ty = try self.internNominalWithResolvedArgs(
                    unwrapped_struct_ty,
                    inferred_args[0..header_param_count],
                );
            }
        }

        if (!spread_expr_id.isNone() and !(header_param_count > 0 and struct_ty == unwrapped_struct_ty)) {
            if (self.getNodeType(spread_expr_id).isError()) {
                _ = try self.checkExpr(spread_expr_id, struct_ty);
            }
        }

        // Enforce `SE-14` mandatory struct initialization, `..` defaults, and `..base` / `..own base` MVS soundness:
        if (struct_node.tag == .struct_ty and !target_scope.isNone()) {
            const final_unwrapped = self.pool.unwrapUnderlyingType(struct_ty);
            const lit_span = self.getAstNodeSpan(expr_id);
            const struct_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(struct_node.rhs)).*;
            for (self.sym_table.getScopeMembers(target_scope)) |mem_idx| {
                if (self.isSymbolCfgDisabled(mem_idx)) continue;
                const f_sym = self.sym_table.getSymbol(mem_idx).*;
                if (f_sym.kind != .field_sym) continue;
                const subst_f_ty = try self.substituteNominalMemberType(final_unwrapped, f_sym.type_id);

                if (mentioned_fields.contains(mem_idx.asInt())) {
                    if (!spread_expr_id.isNone() and is_own_spread and !subst_f_ty.isError() and
                        hasLinearObligation(self.pool, self.sym_table, subst_f_ty))
                    {
                        var msg_buf: [192]u8 = undefined;
                        const msg = std.fmt.bufPrint(
                            &msg_buf,
                            "cannot override `@linear` field `{s}` when spreading `..own` base value",
                            .{f_sym.name_text},
                        ) catch "overriding `@linear` field in `..own` spread would leak obligation";
                        try self.emitDiagnosticSimple(
                            .e0304_resource_or_memory_leak,
                            self.getAstNodeSpan(spread_expr_id),
                            msg,
                            "`@linear` field must be consumed explicitly before reconstructing",
                        );
                    }
                    continue;
                }

                const is_accessible = switch (self.sym_table.lookupInTargetScope(
                    target_scope,
                    self.current_scope,
                    f_sym.name,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => true,
                    else => false,
                };

                if (!spread_expr_id.isNone()) {
                    if (!is_accessible) {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitFieldVisibilityDiagnostic(
                                sink,
                                self.sym_table.getSymbol(mem_idx),
                                self.getAstNodeSpan(spread_expr_id),
                            );
                        }
                        continue;
                    }
                    if (!is_own_spread and !subst_f_ty.isError() and !self.isCopyType(subst_f_ty)) {
                        var ty_buf: [96]u8 = undefined;
                        const ty_str = self.pool.formatType(subst_f_ty, self.sym_table, &ty_buf);
                        var msg_buf: [224]u8 = undefined;
                        const msg = std.fmt.bufPrint(
                            &msg_buf,
                            "unmentioned field `{s}` of non-`Copy` type `{s}` cannot be copied by `..`; use `..own` to move",
                            .{ f_sym.name_text, ty_str },
                        ) catch "unmentioned non-`Copy` field requires `..own` struct spread";
                        const base_span = self.getAstNodeSpan(spread_base_id);
                        const insert_span = Span.init(base_span.file_id, base_span.start_byte, base_span.start_byte);
                        try self.emitDiagnosticWithSingleFix(
                            .e0420_missing_call_site_own,
                            base_span,
                            msg,
                            "requires `own` move here",
                            "add `own` to move non-`Copy` fields from base",
                            insert_span,
                            "own ",
                        );
                        break;
                    }
                    continue;
                }

                const has_field_default = f_sym.flags.is_builtin or self.hasDefaultEqInFieldCst(f_sym.cst_node);
                if (has_field_default and has_dotdot_rest) continue;
                if (!is_accessible and !has_field_default) {
                    if (self.diagnostic_sink) |sink| {
                        try symbol_resolver.emitFieldVisibilityDiagnostic(
                            sink,
                            self.sym_table.getSymbol(mem_idx),
                            lit_span,
                        );
                    }
                    continue;
                }
                if (has_field_default and !has_dotdot_rest) {
                    var def_msg_buf: [224]u8 = undefined;
                    const def_msg = std.fmt.bufPrint(
                        &def_msg_buf,
                        "missing field `{s}` in `{s}` literal; write `, ..` (or `{{ .. }}`) to fill defaulted fields",
                        .{ f_sym.name_text, struct_sym.name_text },
                    ) catch "missing defaulted field in struct literal; add `..`";
                    try self.emitDiagnosticSimple(
                        .e0432_missing_struct_field_initializer,
                        lit_span,
                        def_msg,
                        "omitted defaulted field requires explicit `..`",
                    );
                    continue;
                }
                var miss_msg_buf: [200]u8 = undefined;
                const miss_msg = std.fmt.bufPrint(
                    &miss_msg_buf,
                    "missing initializer for field `{s}` in `{s}` struct literal",
                    .{ f_sym.name_text, struct_sym.name_text },
                ) catch "missing required field initializer in struct literal";
                try self.emitDiagnosticSimple(
                    .e0432_missing_struct_field_initializer,
                    lit_span,
                    miss_msg,
                    "field has no default value and must be initialized",
                );
            }
        }
        return struct_ty;
    }

    /// Returns `true` if `.struct_field` CST `field_cst` declares an `= expr` default initializer (`SE-14`).
    fn hasDefaultEqInFieldCst(self: *const TypeChecker, field_cst: CstNodeIndex) bool {
        if (field_cst.isNone() or field_cst.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = field_cst.asInt();
        const rec = self.cst_arena.getNode(field_cst);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var bracket_depth: u32 = 0;
        var cur = start_idx + 1;
        while (cur < end_idx) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind == .attribute) {
                cur += @max(@as(usize, sub.subtree_size), 1);
                continue;
            }
            const step: usize = @max(@as(usize, sub.subtree_size), 1);
            if (step == 1 and !sub.flags.is_missing_or_injected and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const kind = self.token_buffer.getToken(sub.token).kind;
                switch (kind) {
                    .lbracket, .lparen, .lbrace => bracket_depth += 1,
                    .rbracket, .rparen, .rbrace => bracket_depth -|= 1,
                    .eq => if (bracket_depth == 0) return true,
                    else => {},
                }
            }
            cur += step;
        }
        return false;
    }

    /// Direct modifier kind immediately following `&` inside a `.prefix_expr` CST subtree (`ADR-22B` & `ADR-22F`).
    const AmpUnaryModifier = enum(u2) {
        normal_ref,
        out_ref,
        raw_const,
        raw_mut,
    };

    /// Classifies `&place`, `&mut place`, `&out place`, `&raw place`, and `&raw mut place` in O(1) (`ADR-22F`).
    fn classifyAmpUnaryModifier(self: *const TypeChecker, cst_id: CstNodeIndex) AmpUnaryModifier {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return .normal_ref;
        const start_idx: usize = cst_id.asInt();
        const rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var has_seen_amp = false;
        var has_seen_raw = false;
        var cur = start_idx + 1;
        while (cur < end_idx) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind != .token_leaf) break;
            if (!sub.flags.is_missing_or_injected and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens())
            {
                const kind = self.token_buffer.getToken(sub.token).kind;
                if (!has_seen_amp) {
                    if (kind == .amp) has_seen_amp = true;
                } else if (has_seen_raw) {
                    if (kind == .kw_mut) return .raw_mut;
                    return .raw_const;
                } else if (kind == .ident) {
                    const lex = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, sub.token);
                    if (std.mem.eql(u8, lex, "out")) return .out_ref;
                    if (std.mem.eql(u8, lex, "raw")) {
                        has_seen_raw = true;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            cur += @max(@as(usize, sub.subtree_size), 1);
        }
        return if (has_seen_raw) .raw_const else .normal_ref;
    }

    /// Returns `true` if `&mut …` has a direct `mut` `.token_leaf` before its operand subtree.
    fn hasDirectMutLeafAfterAmp(self: *const TypeChecker, cst_id: CstNodeIndex) bool {
        if (cst_id.isNone() or cst_id.asInt() >= self.cst_arena.countNodes()) return false;
        const start_idx: usize = cst_id.asInt();
        const rec = self.cst_arena.getNode(cst_id);
        const end_idx: usize = @min(
            start_idx + @max(@as(usize, rec.subtree_size), 1),
            self.cst_arena.countNodes(),
        );
        var cur = start_idx + 1;
        while (cur < end_idx) {
            const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
            if (sub.kind != .token_leaf) break;
            if (!sub.flags.is_missing_or_injected and !sub.token.isNone() and
                sub.token.asInt() < self.token_buffer.countTokens() and
                self.token_buffer.getToken(sub.token).kind == .kw_mut)
            {
                return true;
            }
            cur += @max(@as(usize, sub.subtree_size), 1);
        }
        return false;
    }

    /// Synthesizes a unary prefix expression (`-x`, `not b`, `~n`, `own v`, `&x`, `&mut x`, `&out x`, `&raw [mut] x`, `comptime e`).
    fn synthUnaryExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        const inner_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const op_kind = self.token_buffer.getToken(ast_node.main_token).kind;

        switch (op_kind) {
            .kw_comptime => return self.synthOrCheckComptimePrefixExpr(expr_id, .err_ty),
            .kw_own => {
                const prev_own = self.is_in_explicit_own_expr;
                self.is_in_explicit_own_expr = true;
                defer self.is_in_explicit_own_expr = prev_own;
                return self.synthExpr(inner_id);
            },
            .minus => {
                if (self.ast_arena.getNode(inner_id).tag == .int_lit) {
                    return self.synthIntLiteral(inner_id, true);
                }
                const operand_ty = try self.synthExpr(inner_id);
                if (operand_ty.isError()) return .err_ty;
                const base_ty = self.pool.unwrapRefinementBase(operand_ty);
                if (base_ty == .untyped_int_ty or base_ty == .untyped_float_ty or
                    base_ty.isSignedIntPrimitive() or base_ty.isFloatPrimitive())
                {
                    return base_ty;
                }
                try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), .i32_ty, operand_ty);
                return .err_ty;
            },
            .kw_not => {
                const saved_pos = self.is_direct_positive_cond;
                const saved_walrus = self.is_dominating_walrus_pos;
                const saved_neg = self.is_negated_is_context;
                self.is_direct_positive_cond = false;
                self.is_dominating_walrus_pos = false;
                self.is_negated_is_context = true;
                defer {
                    self.is_direct_positive_cond = saved_pos;
                    self.is_dominating_walrus_pos = saved_walrus;
                    self.is_negated_is_context = saved_neg;
                }
                const operand_ty = try self.checkExpr(inner_id, .bool_ty);
                return if (operand_ty.isError()) .err_ty else .bool_ty;
            },
            .tilde => {
                const operand_ty = try self.synthExpr(inner_id);
                if (operand_ty.isError()) return .err_ty;
                const base_ty = self.pool.unwrapRefinementBase(operand_ty);
                if (base_ty == .untyped_int_ty or base_ty.isIntegerPrimitive() or
                    self.isIntegerBoundedVar(base_ty))
                {
                    return base_ty;
                }
                const under_ty = self.pool.unwrapUnderlyingType(operand_ty);
                const under_node = self.pool.getNode(under_ty);
                if (under_node.tag == .bit_field_ty) return operand_ty;
                if (under_node.tag == .array_ty) {
                    const lane_ty = self.pool.unwrapRefinementBase(TypeId.fromInt(under_node.lhs));
                    if (lane_ty.isIntegerPrimitive()) return operand_ty;
                }
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(expr_id),
                    "bitwise NOT `~` requires an integer, `bit_field`, or integer SIMD/array operand; use `not` for `bool`",
                    "invalid operand for bitwise `~`",
                );
                return .err_ty;
            },
            .bang => {
                const saved_pos = self.is_direct_positive_cond;
                const saved_walrus = self.is_dominating_walrus_pos;
                const saved_neg = self.is_negated_is_context;
                self.is_direct_positive_cond = false;
                self.is_dominating_walrus_pos = false;
                self.is_negated_is_context = true;
                defer {
                    self.is_direct_positive_cond = saved_pos;
                    self.is_dominating_walrus_pos = saved_walrus;
                    self.is_negated_is_context = saved_neg;
                }
                const operand_ty = try self.synthExpr(inner_id);
                if (operand_ty.isError()) return .err_ty;
                if (operand_ty == .bool_ty or operand_ty.isIntegerPrimitive() or operand_ty == .untyped_int_ty) {
                    return operand_ty;
                }
                try self.emitTypeMismatch(self.getAstNodeSpan(expr_id), .bool_ty, operand_ty);
                return .err_ty;
            },
            .amp => {
                const expr_cst = self.ast_arena.getCstOrigin(expr_id);
                const amp_mod = self.classifyAmpUnaryModifier(expr_cst);
                const is_raw_addr = (amp_mod == .raw_const or amp_mod == .raw_mut);
                const saved_raw_addr = self.is_in_raw_addr_of;
                if (is_raw_addr) self.is_in_raw_addr_of = true;
                const operand_ty = blk_amp_op: {
                    defer self.is_in_raw_addr_of = saved_raw_addr;
                    break :blk_amp_op self.materializeUntypedType(try self.synthExpr(inner_id));
                };
                switch (amp_mod) {
                    .raw_const => {
                        if (!operand_ty.isError() and !self.isAssignablePlace(inner_id)) {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                self.getAstNodeSpan(expr_id),
                                "`&raw` requires an addressable memory place rather than a temporary rvalue",
                                "cannot take raw address of temporary value",
                            );
                        }
                        return self.pool.internRawPtr(operand_ty, false);
                    },
                    .raw_mut => {
                        if (!operand_ty.isError()) {
                            if (!self.isAssignablePlace(inner_id)) {
                                try self.emitDiagnosticSimple(
                                    .e0401_type_mismatch,
                                    self.getAstNodeSpan(expr_id),
                                    "`&raw mut` requires an addressable mutable memory place",
                                    "cannot take mutable raw address of temporary value",
                                );
                            } else if (!self.isMutableAssignablePlace(inner_id)) {
                                try self.emitDiagnosticSimple(
                                    .e0305_exclusivity_violation,
                                    self.getAstNodeSpan(expr_id),
                                    "`&raw mut` requires a mutable `var`, `&mut`, or `*mut` place",
                                    "place is immutable (`let` or shared borrow)",
                                );
                            }
                        }
                        return self.pool.internRawPtr(operand_ty, true);
                    },
                    .out_ref => {
                        if (!operand_ty.isError() and
                            (!self.isAssignablePlace(inner_id) or !self.isMutableAssignablePlace(inner_id)))
                        {
                            try self.emitDiagnosticSimple(
                                .e0422_out_param_contract_violation,
                                self.getAstNodeSpan(expr_id),
                                "`&out` argument must reference a mutable `var`, `&mut`, or `&out` place",
                                "cannot pass immutable binding or temporary rvalue as `&out`",
                            );
                        }
                        return self.pool.internOutRef(operand_ty);
                    },
                    .normal_ref => {
                        const is_mut = self.hasDirectMutLeafAfterAmp(expr_cst);
                        if (is_mut and !operand_ty.isError() and
                            self.isAssignablePlace(inner_id) and !self.isMutableAssignablePlace(inner_id))
                        {
                            try self.emitDiagnosticSimple(
                                .e0305_exclusivity_violation,
                                self.getAstNodeSpan(expr_id),
                                "cannot take mutable `&mut` borrow of an immutable binding, `&T`, or read-only `*T` place",
                                "place is immutable; declare with `var` or borrow via `&`",
                            );
                        }
                        return self.pool.internRef(operand_ty, is_mut);
                    },
                }
            },
            .star => return self.synthDerefExpr(expr_id),
            .ident => {
                const op_lex = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    ast_node.main_token,
                );
                if (std.mem.eql(u8, op_lex, "yield")) {
                    return self.checkExpr(inner_id, self.current_fn_ret_ty);
                }
                return self.synthExpr(inner_id);
            },
            else => return self.synthExpr(inner_id),
        }
    }

    /// Returns `true` when `op_kind` is a homogeneous numeric/bitwise binary operator preserving operand type `T`.
    fn isValuePreservingNumericBinOp(op_kind: TokenKind) bool {
        return switch (op_kind) {
            .plus,
            .minus,
            .star,
            .slash,
            .percent,
            .plus_percent,
            .minus_percent,
            .star_percent,
            .plus_pipe,
            .minus_pipe,
            .star_pipe,
            .amp,
            .pipe,
            .caret,
            .shl,
            .shr,
            => true,
            else => false,
        };
    }

    /// Returns `true` when `operand_id` is an introduction, control-flow join, or operator form checkable top-down.
    fn isTopDownNumericOperand(self: *const TypeChecker, operand_id: NodeIndex) bool {
        if (operand_id.isNone() or operand_id.asInt() >= self.ast_arena.countNodes()) return false;
        const node = self.ast_arena.getNode(operand_id);
        return switch (node.tag) {
            .int_lit,
            .float_lit,
            .if_expr,
            .match_expr,
            .block,
            .with_expr,
            .loop_expr,
            .for_stmt,
            .while_stmt,
            .walrus_expr,
            => true,
            .binary_expr => !node.main_token.isNone() and
                (self.token_buffer.getToken(node.main_token).kind == .kw_catch or
                    self.token_buffer.getToken(node.main_token).kind == .kw_orelse or
                    isValuePreservingNumericBinOp(self.token_buffer.getToken(node.main_token).kind)),
            .unary_expr => !node.main_token.isNone() and
                (self.token_buffer.getToken(node.main_token).kind == .minus or
                    self.token_buffer.getToken(node.main_token).kind == .kw_comptime),
            else => false,
        };
    }

    /// Synthesizes a binary infix expression, enforcing `distinct` isolation (`E0405`), `expr is Pattern`, and `catch`.
    fn synthBinaryExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        return self.synthOrCheckBinaryExpr(expr_id, .err_ty);
    }

    /// Synthesizes or checks a binary infix expression under optional numeric `expected_ty`.
    fn synthOrCheckBinaryExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const op_kind = self.token_buffer.getToken(ast_node.main_token).kind;
        const was_direct_pos = self.is_direct_positive_cond;

        if (op_kind == .kw_catch) {
            const saved_pos = self.is_direct_positive_cond;
            self.is_direct_positive_cond = false;
            defer self.is_direct_positive_cond = saved_pos;
            return self.synthCatchExpr(expr_id, expected_ty);
        }
        if (op_kind == .kw_orelse) {
            const saved_pos = self.is_direct_positive_cond;
            self.is_direct_positive_cond = false;
            defer self.is_direct_positive_cond = saved_pos;
            return self.synthOrelseExpr(expr_id, expected_ty);
        }

        const lhs_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
        const rhs_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;

        if (op_kind == .kw_is) {
            return self.synthIsExpr(expr_id);
        }

        if (op_kind == .kw_and) {
            const saved_and = self.has_following_and_conjunct;
            self.has_following_and_conjunct = true;
            _ = try self.checkExpr(lhs_id, .bool_ty);
            self.has_following_and_conjunct = saved_and;
            const saved_rhs_walrus = self.is_dominating_walrus_pos;
            if (!was_direct_pos) {
                self.is_dominating_walrus_pos = false;
            }
            defer self.is_dominating_walrus_pos = saved_rhs_walrus;
            _ = try self.checkExpr(rhs_id, .bool_ty);
            return .bool_ty;
        }

        const saved_pos = self.is_direct_positive_cond;
        self.is_direct_positive_cond = false;
        defer self.is_direct_positive_cond = saved_pos;

        if (op_kind == .kw_or or op_kind == .pipepipe) {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            _ = try self.checkExpr(lhs_id, .bool_ty);
            _ = try self.checkExpr(rhs_id, .bool_ty);
            return .bool_ty;
        }

        const is_lhs_ctx_var = !lhs_id.isNone() and
            self.ast_arena.getNode(lhs_id).tag == .contextual_variant;
        const is_rhs_ctx_var = !rhs_id.isNone() and
            self.ast_arena.getNode(rhs_id).tag == .contextual_variant;
        const has_numeric_expected = (expected_ty.isIntegerPrimitive() or expected_ty.isFloatPrimitive()) and
            isValuePreservingNumericBinOp(op_kind);

        var lhs_ty: TypeId = .err_ty;
        var rhs_ty: TypeId = .err_ty;
        if (is_lhs_ctx_var and !is_rhs_ctx_var) {
            rhs_ty = self.materializeUntypedType(try self.synthExpr(rhs_id));
            lhs_ty = if (!rhs_ty.isError())
                try self.checkExpr(lhs_id, rhs_ty)
            else
                try self.synthExpr(lhs_id);
        } else if (is_rhs_ctx_var and !is_lhs_ctx_var) {
            lhs_ty = self.materializeUntypedType(try self.synthExpr(lhs_id));
            rhs_ty = if (!lhs_ty.isError())
                try self.checkExpr(rhs_id, lhs_ty)
            else
                try self.synthExpr(rhs_id);
        } else {
            lhs_ty = if (has_numeric_expected and self.isTopDownNumericOperand(lhs_id))
                try self.checkExpr(lhs_id, expected_ty)
            else
                try self.synthExpr(lhs_id);
            rhs_ty = if (has_numeric_expected and self.isTopDownNumericOperand(rhs_id))
                try self.checkExpr(rhs_id, expected_ty)
            else
                try self.synthExpr(rhs_id);
        }
        if (lhs_ty.isError() or rhs_ty.isError()) return .err_ty;

        // [1] Reject mixing `distinct` newtype with its base type or another `distinct` type (`E0405`, `DR-04` Section 1.4):
        const is_lhs_distinct = self.pool.getTag(lhs_ty) == .distinct_ty;
        const is_rhs_distinct = self.pool.getTag(rhs_ty) == .distinct_ty;
        if ((is_lhs_distinct or is_rhs_distinct) and lhs_ty != rhs_ty) {
            try self.emitDistinctMixingError(self.getAstNodeSpan(expr_id), lhs_ty, rhs_ty);
            return .err_ty;
        }

        // [2] Unwrap zero-cost `is` range refinements (`T is low..=high` widens to `T` under arithmetic, `DR-04` Section 1.5):
        const lhs_base = self.pool.unwrapRefinementBase(lhs_ty);
        const rhs_base = self.pool.unwrapRefinementBase(rhs_ty);

        const unified_ty: TypeId = blk: {
            if (lhs_base == rhs_base) break :blk lhs_base;
            if (lhs_base == .untyped_int_ty and (rhs_base.isIntegerPrimitive() or
                self.isIntegerBoundedVar(rhs_base)))
            {
                _ = try self.checkExpr(lhs_id, rhs_base);
                break :blk rhs_base;
            }
            if (rhs_base == .untyped_int_ty and (lhs_base.isIntegerPrimitive() or
                self.isIntegerBoundedVar(lhs_base)))
            {
                _ = try self.checkExpr(rhs_id, lhs_base);
                break :blk lhs_base;
            }
            if (lhs_base == .untyped_float_ty and rhs_base.isFloatPrimitive()) break :blk rhs_base;
            if (rhs_base == .untyped_float_ty and lhs_base.isFloatPrimitive()) break :blk lhs_base;

            try self.emitTypeMismatch(
                self.getAstNodeSpan(rhs_id),
                self.materializeUntypedType(lhs_ty),
                self.materializeUntypedType(rhs_ty),
            );
            break :blk .err_ty;
        };

        if (unified_ty.isError()) return .err_ty;

        return switch (op_kind) {
            .eqeq, .bang_eq, .lt, .le, .gt, .ge => .bool_ty,
            .eq,
            .plus_eq,
            .minus_eq,
            .star_eq,
            .slash_eq,
            .percent_eq,
            .amp_eq,
            .pipe_eq,
            .caret_eq,
            .shl_eq,
            .shr_eq,
            => .unit_ty,
            else => unified_ty,
        };
    }

    /// Synthesizes postfix `expr?` (`try_expr`), enforcing `E0410`, `@from` `FromError`, and `@derive(From)` (`SE-10B`).
    fn synthTryExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        const inner_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const operand_ty = try self.synthExpr(inner_id);
        if (operand_ty.isError()) return .err_ty;

        if (self.defer_depth > 0) {
            try self.emitDiagnosticSimple(
                .e0410_try_outside_fallible_fn,
                self.getAstNodeSpan(expr_id),
                "uncaught `?` operator cannot propagate out of a `defer` or `errdefer` block",
                "handle fallible operations locally inside `defer` / `errdefer` with `catch`",
            );
            const op_node_defer = self.pool.getNode(self.pool.unwrapUnderlyingType(operand_ty));
            return switch (op_node_defer.tag) {
                .optional_ty, .result_ty => TypeId.fromInt(op_node_defer.lhs),
                else => .err_ty,
            };
        }

        const op_node = self.pool.getNode(self.pool.unwrapUnderlyingType(operand_ty));
        const unwrapped_fn_ret_ty = self.pool.unwrapUnderlyingType(self.current_fn_ret_ty);
        const fn_ret_node = self.pool.getNode(unwrapped_fn_ret_ty);

        switch (op_node.tag) {
            .optional_ty => {
                const payload_ty = TypeId.fromInt(op_node.lhs);
                if (!unwrapped_fn_ret_ty.isError() and fn_ret_node.tag != .optional_ty) {
                    try self.emitDiagnosticSimple(
                        .e0410_try_outside_fallible_fn,
                        self.getAstNodeSpan(expr_id),
                        "`?` on optional `T?` requires enclosing function to return an optional `U?`",
                        "enclosing function does not return an optional type",
                    );
                } else {
                    try self.try_conversions.put(self.allocator, expr_id.asInt(), .NONE);
                }
                return payload_ty;
            },
            .result_ty => {
                const ok_ty = TypeId.fromInt(op_node.lhs);
                const inner_err_ty = TypeId.fromInt(op_node.rhs);

                if (!unwrapped_fn_ret_ty.isError() and fn_ret_node.tag != .result_ty) {
                    try self.emitDiagnosticSimple(
                        .e0410_try_outside_fallible_fn,
                        self.getAstNodeSpan(expr_id),
                        "`?` on `T!E` requires enclosing function to return `U!F`",
                        "enclosing function does not return `Result`",
                    );
                    return ok_ty;
                }

                var conv_def_id: DefId = .NONE;
                if (fn_ret_node.tag == .result_ty) {
                    const outer_err_ty = TypeId.fromInt(fn_ret_node.rhs);
                    if (!inner_err_ty.isError() and !outer_err_ty.isError() and inner_err_ty != outer_err_ty) {
                        const pair_key = packFromErrorPair(inner_err_ty, outer_err_ty);
                        if (self.sym_table.from_error_fn_defs.get(pair_key)) |fn_def| {
                            conv_def_id = fn_def;
                        } else if (self.pool.getDerivedFromVariant(inner_err_ty, outer_err_ty)) |variant_ord| {
                            try self.try_from_variants.put(self.allocator, expr_id.asInt(), variant_ord);
                        } else if (self.sym_table.from_error_pairs.contains(pair_key)) {
                            conv_def_id = .NONE;
                        } else {
                            var src_buf: [64]u8 = undefined;
                            var dst_buf: [64]u8 = undefined;
                            const src_name = self.pool.formatType(inner_err_ty, self.sym_table, &src_buf);
                            const dst_name = self.pool.formatType(outer_err_ty, self.sym_table, &dst_buf);
                            var msg_buf: [192]u8 = undefined;
                            const msg = std.fmt.bufPrint(
                                &msg_buf,
                                "cannot convert error `{s}` to `{s}` via `?`; missing `@from` or `@derive(From)` conversion",
                                .{ src_name, dst_name },
                            ) catch "missing `@from` error conversion for `?` operator";
                            try self.emitDiagnosticSimple(
                                .e0411_missing_from_error_conversion,
                                self.getAstNodeSpan(expr_id),
                                msg,
                                "add `@derive(From)` on the target error enum or define `@from fn …`",
                            );
                        }
                    }
                }
                try self.try_conversions.put(self.allocator, expr_id.asInt(), conv_def_id);
                return ok_ty;
            },
            else => {
                try self.emitDiagnosticSimple(
                    .e0410_try_outside_fallible_fn,
                    self.getAstNodeSpan(expr_id),
                    "the `?` operator can only be applied to `T!E` or `T?` values",
                    "operand is not a fallible `Result` or optional type",
                );
                return .err_ty;
            },
        }
    }

    /// Unwraps `.named_arg` (`label: expr`) to its underlying value `NodeIndex`.
    fn unwrapCallArgExpr(self: *const TypeChecker, raw_arg_id: NodeIndex) NodeIndex {
        if (raw_arg_id.isNone() or raw_arg_id.asInt() >= self.ast_arena.countNodes()) return raw_arg_id;
        const arg_node = self.ast_arena.getNode(raw_arg_id);
        if (arg_node.tag == .named_arg and arg_node.lhs.tag == .node) {
            return NodeIndex.fromInt(arg_node.lhs.payload);
        }
        return raw_arg_id;
    }

    /// Computes the full CST subtree `Span` of `node_id` (falling back to `getAstNodeSpan`).
    fn getAstSubtreeSpan(self: *const TypeChecker, node_id: NodeIndex) Span {
        if (node_id.isNone() or node_id.asInt() >= self.ast_arena.countNodes()) {
            return Span.init(self.file_id, 0, 0);
        }
        const cst_origin = self.ast_arena.getCstOrigin(node_id);
        if (!cst_origin.isNone() and cst_origin.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = cst_origin.asInt();
            const rec = self.cst_arena.getNode(cst_origin);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var min_byte: u32 = std.math.maxInt(u32);
            var max_byte: u32 = 0;
            var has_tok = false;
            var cur = start_idx;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                const is_leaf = sub.subtree_size <= 1 and !sub.flags.is_bracketed;
                if (is_leaf and !sub.flags.is_missing_or_injected and
                    !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const tok_span = self.token_buffer.getTokenSpan(self.file_id, sub.token);
                    if (tok_span.start_byte < min_byte) min_byte = tok_span.start_byte;
                    if (tok_span.end_byte > max_byte) max_byte = tok_span.end_byte;
                    has_tok = true;
                }
            }
            if (has_tok and min_byte <= max_byte) {
                return Span.init(self.file_id, min_byte, max_byte);
            }
        }
        return self.getAstNodeSpan(node_id);
    }

    /// Synthesizes or checks `fallible_expr catch [|err|] fallback` (`DR-07` §2.2 & `DR-21` `SE-03`).
    fn synthCatchExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        const saved_pos = self.is_direct_positive_cond;
        self.is_direct_positive_cond = false;
        defer self.is_direct_positive_cond = saved_pos;

        const ast_node = self.ast_arena.getNode(expr_id);
        const lhs_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
        const rhs_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;

        const lhs_ty = try self.synthExpr(lhs_id);
        const lhs_node = self.pool.getNode(self.pool.unwrapUnderlyingType(lhs_ty));
        var ok_ty: TypeId = .err_ty;
        var err_payload_ty: TypeId = .err_ty;

        switch (lhs_node.tag) {
            .result_ty => {
                ok_ty = TypeId.fromInt(lhs_node.lhs);
                err_payload_ty = TypeId.fromInt(lhs_node.rhs);
            },
            .optional_ty => {
                ok_ty = TypeId.fromInt(lhs_node.lhs);
                err_payload_ty = .unit_ty;
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(expr_id),
                    "`catch` requires a `Result[T, E]` operand; use `orelse` for optional `T?`",
                    "replace `catch` with `orelse` on optional `T?`",
                );
            },
            else => {
                if (!lhs_ty.isError()) {
                    try self.emitDiagnosticSimple(
                        .e0410_try_outside_fallible_fn,
                        self.getAstNodeSpan(lhs_id),
                        "`catch` requires a `Result[T, E]` left-hand operand",
                        "expression is not a `Result` value",
                    );
                }
            },
        }

        const saved_scope = self.current_scope;
        const catch_scope = try self.sym_table.scope_arena.allocScope(
            .catch_or_errdefer_scope,
            self.current_scope,
            .NONE,
            self.file_id,
            .{},
        );
        self.current_scope = catch_scope;
        defer self.current_scope = saved_scope;

        // Bind optional `|err|` capture token inside `expr_id`'s CST:
        const catch_cst = self.ast_arena.getCstOrigin(expr_id);
        if (!catch_cst.isNone() and catch_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = catch_cst.asInt();
            const rec = self.cst_arena.getNode(catch_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var is_after_catch = false;
            var is_after_open_pipe = false;
            var cur = start_idx + 1;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens())
                {
                    if (sub.token == ast_node.main_token) {
                        is_after_catch = true;
                    } else if (is_after_catch and self.token_buffer.getToken(sub.token).kind == .pipe) {
                        if (is_after_open_pipe) break;
                        is_after_open_pipe = true;
                    } else if (is_after_open_pipe and
                        symbol_resolver.isIdentifierToken(self.token_buffer.getToken(sub.token).kind))
                    {
                        const cap_name = symbol_resolver.extractTokenSlice(
                            self.source,
                            self.token_buffer,
                            sub.token,
                        );
                        if (cap_name.len > 0 and !std.mem.eql(u8, cap_name, "_")) {
                            const cap_sym = try self.interner.intern(cap_name);
                            _ = try self.sym_table.defineSymbol(.{
                                .name = cap_sym,
                                .name_text = self.interner.get(cap_sym),
                                .kind = .local_var_sym,
                                .namespace = .value_ns,
                                .visibility = .private,
                                .flags = .{},
                                .scope_id = catch_scope,
                                .decl_span = self.token_buffer.getTokenSpan(self.file_id, sub.token),
                                .type_id = err_payload_ty,
                            }, self.diagnostic_sink);
                        }
                        break;
                    }
                }
            }
        }

        const target_ty = if (!expected_ty.isError()) expected_ty else ok_ty;
        if (!rhs_id.isNone()) {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            if (!target_ty.isError()) {
                _ = try self.checkExpr(rhs_id, target_ty);
            } else {
                _ = try self.synthExpr(rhs_id);
            }
        }
        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, catch_scope, self.interner, self.diagnostic_sink);
        return self.recordNodeType(expr_id, target_ty);
    }

    /// Synthesizes or checks `opt_expr orelse fallback` (`DR-21` `SE-03`).
    fn synthOrelseExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        const saved_pos = self.is_direct_positive_cond;
        self.is_direct_positive_cond = false;
        defer self.is_direct_positive_cond = saved_pos;

        const ast_node = self.ast_arena.getNode(expr_id);
        const lhs_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
        const rhs_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;

        const lhs_ty = try self.synthExpr(lhs_id);
        const lhs_node = self.pool.getNode(self.pool.unwrapUnderlyingType(lhs_ty));
        var payload_ty: TypeId = .err_ty;
        if (lhs_node.tag == .optional_ty) {
            payload_ty = TypeId.fromInt(lhs_node.lhs);
        } else if (!lhs_ty.isError()) {
            if (lhs_node.tag == .result_ty) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(lhs_id),
                    "`orelse` requires an optional `T?` operand; use `catch` for `Result[T, E]`",
                    "expected optional `T?`, found `Result`",
                );
            } else {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(lhs_id),
                    "`orelse` requires an optional `T?` left-hand operand",
                    "expression is not an optional `T?` value",
                );
            }
        }

        const target_ty = if (!expected_ty.isError()) expected_ty else payload_ty;
        var rhs_ty: TypeId = .err_ty;
        if (!rhs_id.isNone()) {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            rhs_ty = if (!target_ty.isError())
                try self.checkExpr(rhs_id, target_ty)
            else
                try self.synthExpr(rhs_id);
        }
        const final_ty = if (!target_ty.isError()) target_ty else self.materializeUntypedType(rhs_ty);
        return self.recordNodeType(expr_id, final_ty);
    }

    /// Synthesizes or checks parenthesized `([var] ident [: Type] := expr)` (`DR-21` `SE-02`).
    fn synthOrCheckWalrusExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const ident_tok = if (ast_node.lhs.tag == .token)
            TokenIndex.fromInt(ast_node.lhs.payload)
        else
            ast_node.main_token;

        var is_var = false;
        var type_node_id: NodeIndex = .none;
        var init_expr_id: NodeIndex = .none;
        if (ast_node.rhs.tag == .extra) {
            const base_idx: usize = ast_node.rhs.payload;
            if (base_idx + 3 <= self.ast_arena.extra_data.items.len) {
                const extra_items = self.ast_arena.extra_data.items[base_idx .. base_idx + 3];
                is_var = (extra_items[0] != 0);
                type_node_id = NodeIndex.fromInt(extra_items[1]);
                init_expr_id = NodeIndex.fromInt(extra_items[2]);
            }
        }

        const is_valid_walrus_pos = self.is_dominating_walrus_pos;
        if (!is_valid_walrus_pos) {
            try self.emitDiagnosticSimple(
                .e0215_invalid_walrus_position,
                self.getAstNodeSpan(expr_id),
                "walrus binding `:=` is only permitted in a dominating `if` or `while` condition",
                "declare with `let` or `var` before the expression instead",
            );
        }

        const annot_ty = if (!type_node_id.isNone()) try self.resolveTypeAst(type_node_id) else .err_ty;
        const target_init_ty = if (!annot_ty.isError()) annot_ty else expected_ty;
        const raw_init_ty = eval_rhs: {
            const saved_pos = self.is_direct_positive_cond;
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_direct_positive_cond = false;
            self.is_dominating_walrus_pos = false;
            defer {
                self.is_direct_positive_cond = saved_pos;
                self.is_dominating_walrus_pos = saved_walrus;
            }
            break :eval_rhs if (!target_init_ty.isError())
                try self.checkExpr(init_expr_id, target_init_ty)
            else
                try self.synthExpr(init_expr_id);
        };
        const bound_ty = if (!annot_ty.isError()) annot_ty else self.materializeUntypedType(raw_init_ty);

        if (!bound_ty.isError() and hasLinearObligation(self.pool, self.sym_table, bound_ty)) {
            try self.emitDiagnosticSimple(
                .e0304_resource_or_memory_leak,
                self.getAstNodeSpan(expr_id),
                "`@linear` resource cannot be bound via `:=` inside a condition; bind with `let` and `defer`",
                "`@linear` resource cannot be bound inline with `:=`",
            );
        }

        if (!ident_tok.isNone() and ident_tok.asInt() < self.token_buffer.countTokens()) {
            const name_str = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, ident_tok);
            if (name_str.len > 0 and !std.mem.eql(u8, name_str, "_")) {
                const name_sym = try self.interner.intern(name_str);
                const bound_idx = try self.sym_table.defineSymbol(.{
                    .name = name_sym,
                    .name_text = self.interner.get(name_sym),
                    .kind = if (is_var) .local_var_sym else .local_let_sym,
                    .namespace = .value_ns,
                    .visibility = .private,
                    .flags = .{
                        .is_mut = is_var,
                        .is_used = !is_valid_walrus_pos,
                        .is_comptime = self.pure_comptime_depth > 0,
                    },
                    .scope_id = self.current_scope,
                    .decl_span = self.token_buffer.getTokenSpan(self.file_id, ident_tok),
                    .ast_node = expr_id,
                    .cst_node = self.ast_arena.getCstOrigin(expr_id),
                    .type_id = bound_ty,
                }, self.diagnostic_sink);
                self.recordNodeSymbol(expr_id, bound_idx);
            }
        }

        if (!expected_ty.isError() and !bound_ty.isError() and bound_ty != expected_ty) {
            _ = try self.checkTypeCompatibility(expr_id, bound_ty, expected_ty);
        }
        return self.recordNodeType(expr_id, bound_ty);
    }

    /// Returns `true` if `pat_id` or any descendant pattern is a `.pattern_hole` recovery node.
    fn hasPatternHoleInSubtree(self: *const TypeChecker, pat_id: NodeIndex, depth: u32) bool {
        if (depth >= MAX_TYPE_DEPTH or pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) {
            return false;
        }
        const pat_node = self.ast_arena.getNode(pat_id);
        return switch (pat_node.tag) {
            .pattern_hole => true,
            .at_pat => pat_node.rhs.tag == .node and
                self.hasPatternHoleInSubtree(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1),
            .or_pat => (pat_node.lhs.tag == .node and
                self.hasPatternHoleInSubtree(NodeIndex.fromInt(pat_node.lhs.payload), depth + 1)) or
                (pat_node.rhs.tag == .node and
                    self.hasPatternHoleInSubtree(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1)),
            .tuple_pat, .variant_pat, .struct_pat, .slice_pat => blk: {
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    if (self.hasPatternHoleInSubtree(NodeIndex.fromInt(raw_sub), depth + 1)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// Marks all symbols bound inside `pat_id` as used to suppress cascading `W0402` after `E0418`.
    fn markPatternBoundSymbolsUsed(self: *TypeChecker, pat_id: NodeIndex, depth: u32) void {
        if (depth >= MAX_TYPE_DEPTH or pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) {
            return;
        }
        if (pat_id.asInt() < self.node_symbols.len) {
            const sym_idx = self.node_symbols[pat_id.asInt()];
            if (!sym_idx.isNone()) self.sym_table.markSymbolUsed(sym_idx);
        }
        const pat_node = self.ast_arena.getNode(pat_id);
        switch (pat_node.tag) {
            .at_pat => {
                if (pat_node.rhs.tag == .node) {
                    self.markPatternBoundSymbolsUsed(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1);
                }
            },
            .or_pat => {
                if (pat_node.lhs.tag == .node) {
                    self.markPatternBoundSymbolsUsed(NodeIndex.fromInt(pat_node.lhs.payload), depth + 1);
                }
                if (pat_node.rhs.tag == .node) {
                    self.markPatternBoundSymbolsUsed(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1);
                }
            },
            .tuple_pat, .variant_pat, .struct_pat, .slice_pat => {
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    self.markPatternBoundSymbolsUsed(NodeIndex.fromInt(raw_sub), depth + 1);
                }
            },
            else => {},
        }
    }

    /// Synthesizes `scrutinee is [not] Pattern`, enforcing `E0214`, `E0304`, and `E0418` (`DR-21` `SE-01`).
    fn synthIsExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const is_not = !ast_node.main_token.isNone() and
            ast_node.main_token.asInt() < self.token_buffer.countTokens() and
            self.token_buffer.getToken(ast_node.main_token).kind == .kw_not;
        const scrutinee_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
        const pat_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;

        const scr_ty = eval_scr: {
            const saved_pos = self.is_direct_positive_cond;
            self.is_direct_positive_cond = false;
            defer self.is_direct_positive_cond = saved_pos;
            break :eval_scr self.materializeUntypedType(try self.synthExpr(scrutinee_id));
        };
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) {
            return self.recordNodeType(expr_id, .bool_ty);
        }
        const is_scr_mut = self.isScrutineeMutRefBindable(scrutinee_id, scr_ty);

        // Unwrap single-element parenthesized pattern `(ident)` when checking for bare `E0418` binding:
        var check_pat_id = pat_id;
        while (!check_pat_id.isNone() and check_pat_id.asInt() < self.ast_arena.countNodes() and
            self.ast_arena.getNode(check_pat_id).tag == .tuple_pat)
        {
            const sub_pats = self.getNodeExtraSlice(check_pat_id, false);
            if (sub_pats.len == 1 and !hasShallowCommaInTupleCst(
                self.cst_arena,
                self.token_buffer,
                self.ast_arena.getCstOrigin(check_pat_id),
            )) {
                check_pat_id = NodeIndex.fromInt(sub_pats[0]);
            } else {
                break;
            }
        }

        const check_pat_node = self.ast_arena.getNode(check_pat_id);
        if (check_pat_node.tag == .bind_pat and
            self.resolveBindPatConstOrVariantQuiet(check_pat_id, false) == null)
        {
            const bind_name = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                check_pat_node.main_token,
            );
            if (bind_name.len > 0 and !std.mem.eql(u8, bind_name, "_")) {
                if (self.diagnostic_sink) |sink| {
                    const expr_span = self.getAstSubtreeSpan(expr_id);
                    const scr_span = self.getAstSubtreeSpan(scrutinee_id);
                    const scr_slice = if (scr_span.end_byte <= self.source.len and scr_span.start_byte <= scr_span.end_byte)
                        self.source[scr_span.start_byte..scr_span.end_byte]
                    else
                        "expr";
                    var rep_buf: [256]u8 = undefined;
                    const rep_str = std.fmt.bufPrint(&rep_buf, "({s} := {s})", .{ bind_name, scr_slice }) catch "(_ := expr)";
                    const rep_id = try self.interner.intern(rep_str);
                    const edit = [1]TextEdit{.{
                        .file_id = expr_span.file_id,
                        .start_byte = expr_span.start_byte,
                        .end_byte = expr_span.end_byte,
                        .replacement_id = rep_id,
                    }};
                    const fix = [1]SuggestedFix{.{
                        .message = "use parenthesized walrus `:=` for irrefutable inline binding",
                        .applicability = .machine_applicable,
                        .priority = .syntax_canonicalization,
                        .edits = &edit,
                    }};
                    const labels = [1]LabeledSpan{.{
                        .span = self.getAstNodeSpan(check_pat_id),
                        .label = "irrefutable variable binding is not allowed in `is`",
                        .style = .primary,
                    }};
                    _ = try sink.emit(.{
                        .code = .e0418_irrefutable_is_binding,
                        .severity = .err,
                        .primary_span = expr_span,
                        .message = "bare irrefutable binding pattern in `is` expression; use `:=` instead",
                        .labels = &labels,
                        .suggestions = &fix,
                    });
                }
                try self.bindPattern(pat_id, scr_ty, false, is_scr_mut);
                self.markPatternBoundSymbolsUsed(pat_id, 0);
                return self.recordNodeType(expr_id, .bool_ty);
            }
        }

        if (!scr_ty.isError() and !self.hasPatternHoleInSubtree(pat_id, 0) and
            self.isPatternIrrefutable(pat_id, 0))
        {
            try self.emitDiagnosticSimple(
                .e0418_irrefutable_is_binding,
                self.getAstNodeSpan(pat_id),
                "irrefutable pattern in `is` expression always matches; use `let` destructuring or `:=` instead",
                "irrefutable pattern is not allowed in `is`",
            );
            try self.bindPattern(pat_id, scr_ty, false, is_scr_mut);
            self.markPatternBoundSymbolsUsed(pat_id, 0);
            return self.recordNodeType(expr_id, .bool_ty);
        }

        const has_binds = self.hasPatternBindings(pat_id, 0);
        if (has_binds and (is_not or self.is_negated_is_context or !self.is_direct_positive_cond)) {
            try self.emitDiagnosticSimple(
                .e0214_invalid_condition_binding,
                self.getAstNodeSpan(pat_id),
                "pattern bindings in `is` are only permitted along a positive `if` or `while` condition spine",
                "cannot bind pattern variables under `is not`, `not`, `or`, or outside a condition",
            );
            const saved_scope = self.current_scope;
            const temp_scope = try self.sym_table.scope_arena.allocScope(
                .block_scope,
                self.current_scope,
                .NONE,
                self.file_id,
                .{},
            );
            self.current_scope = temp_scope;
            defer self.current_scope = saved_scope;
            try self.bindPattern(pat_id, scr_ty, false, is_scr_mut);
            return self.recordNodeType(expr_id, .bool_ty);
        }

        if (!scr_ty.isError() and self.has_following_and_conjunct and
            try self.hasByValueLinearPatternBinding(pat_id, scr_ty, 0))
        {
            try self.emitDiagnosticSimple(
                .e0304_resource_or_memory_leak,
                self.getAstNodeSpan(pat_id),
                "moving `@linear` payload in `is` before `and` may leak if the guard is false; borrow with `&`",
                "use `&` or `&mut` binding when followed by an `and` guard",
            );
        }

        try self.bindPattern(pat_id, scr_ty, false, is_scr_mut);
        return self.recordNodeType(expr_id, .bool_ty);
    }

    /// Synthesizes `[start]..[=][end]` range expressions (`DR-21` `SE-04`).
    fn synthRangeExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const start_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
        const end_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;

        const saved_pos = self.is_direct_positive_cond;
        self.is_direct_positive_cond = false;
        defer self.is_direct_positive_cond = saved_pos;

        const has_start = !start_id.isNone();
        const has_end = !end_id.isNone();
        const start_ty = if (has_start) self.pool.unwrapRefinementBase(try self.synthExpr(start_id)) else .usize_ty;
        const end_ty = if (has_end) self.pool.unwrapRefinementBase(try self.synthExpr(end_id)) else .usize_ty;
        if (start_ty.isError() or end_ty.isError()) return self.recordNodeType(expr_id, .err_ty);

        if (!has_start and !has_end) {
            return self.recordNodeType(expr_id, .usize_ty);
        }
        if (has_start and !has_end) {
            if (start_ty != .untyped_int_ty and !start_ty.isIntegerPrimitive() and !self.isIntegerBoundedVar(start_ty)) {
                try self.emitTypeMismatch(self.getAstNodeSpan(start_id), .usize_ty, start_ty);
                return self.recordNodeType(expr_id, .err_ty);
            }
            return self.recordNodeType(expr_id, start_ty);
        }
        if (!has_start and has_end) {
            if (end_ty != .untyped_int_ty and !end_ty.isIntegerPrimitive() and !self.isIntegerBoundedVar(end_ty)) {
                try self.emitTypeMismatch(self.getAstNodeSpan(end_id), .usize_ty, end_ty);
                return self.recordNodeType(expr_id, .err_ty);
            }
            return self.recordNodeType(expr_id, end_ty);
        }

        if (start_ty == end_ty) return self.recordNodeType(expr_id, start_ty);
        if (start_ty == .untyped_int_ty and (end_ty.isIntegerPrimitive() or self.isIntegerBoundedVar(end_ty))) {
            _ = try self.checkExpr(start_id, end_ty);
            return self.recordNodeType(expr_id, end_ty);
        }
        if (end_ty == .untyped_int_ty and (start_ty.isIntegerPrimitive() or self.isIntegerBoundedVar(start_ty))) {
            _ = try self.checkExpr(end_id, start_ty);
            return self.recordNodeType(expr_id, start_ty);
        }
        try self.emitTypeMismatch(
            self.getAstNodeSpan(end_id),
            self.materializeUntypedType(start_ty),
            self.materializeUntypedType(end_ty),
        );
        return self.recordNodeType(expr_id, .err_ty);
    }

    /// Synthesizes `$` end-relative length inside `[ … ]` brackets (`DR-21` `SE-04`, `E0416`).
    fn synthDollarExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        if (self.bracket_len_depth == 0 or !self.bracket_len_stack[self.bracket_len_depth - 1]) {
            try self.emitDiagnosticSimple(
                .e0416_invalid_dollar_length_expr,
                self.getAstNodeSpan(expr_id),
                "`$` length shorthand is only valid inside `[ … ]` index/slice brackets on a length-bearing container",
                "`$` cannot be used outside slice, array, `str`, or `Vec` brackets",
            );
            return self.recordNodeType(expr_id, .err_ty);
        }
        return self.recordNodeType(expr_id, .usize_ty);
    }

    /// Synthesizes the `context` keyword expression as `&Context` (`DR-21` `SE-08`).
    fn synthContextExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        if (self.is_extern_fn) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(expr_id),
                "`context` is not available inside `extern` FFI functions",
                "`extern` functions do not carry an implicit CoreX `Context` parameter",
            );
        }
        const ctx_struct_ty = (try self.ensureBuiltinStdNominalType("Context")) orelse .unit_ty;
        return self.recordNodeType(expr_id, try self.pool.internRef(ctx_struct_ty, false));
    }

    /// Synthesizes or checks `with context.<slot> = val, … { body }` (`DR-21` `SE-08`).
    fn synthOrCheckWithExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        if (self.is_extern_fn) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(expr_id),
                "`with context` overrides are not permitted inside `extern` FFI functions",
                "`extern` functions do not carry an implicit CoreX `Context` parameter",
            );
        }
        const ast_node = self.ast_arena.getNode(expr_id);
        const body_id = if (ast_node.rhs.tag == .node) NodeIndex.fromInt(ast_node.rhs.payload) else .none;

        const saved_pos = self.is_direct_positive_cond;
        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_direct_positive_cond = false;
        self.is_dominating_walrus_pos = false;
        defer {
            self.is_direct_positive_cond = saved_pos;
            self.is_dominating_walrus_pos = saved_walrus;
        }

        if (ast_node.lhs.tag == .extra) {
            const base_idx: usize = ast_node.lhs.payload;
            if (base_idx < self.ast_arena.extra_data.items.len) {
                const count: usize = self.ast_arena.extra_data.items[base_idx];
                const needed_end = base_idx + 1 + count * 2;
                if (needed_end <= self.ast_arena.extra_data.items.len) {
                    const pair_words = self.ast_arena.extra_data.items[base_idx + 1 .. needed_end];
                    var seen_slots_mask: u16 = 0;
                    var i: usize = 0;
                    while (i < count) : (i += 1) {
                        const slot_tok = TokenIndex.fromInt(pair_words[i * 2]);
                        const val_id = NodeIndex.fromInt(pair_words[i * 2 + 1]);
                        const slot_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, slot_tok);
                        const slot_span = self.token_buffer.getTokenSpan(self.file_id, slot_tok);

                        const slot_layout = CONTEXT_FIELD_LAYOUT_MAP.get(slot_name) orelse {
                            var msg_buf: [160]u8 = undefined;
                            const msg = std.fmt.bufPrint(
                                &msg_buf,
                                "unknown `context` slot `{s}` in `with` override",
                                .{slot_name},
                            ) catch "unknown `context` slot in `with` override";
                            try self.emitDiagnosticSimple(
                                .e0403_unresolved_symbol,
                                slot_span,
                                msg,
                                "expected `allocator`, `temp_allocator`, `logger`, `diagnostics`, `cancel_token`, `reactor`, or `reactor_ctx`",
                            );
                            _ = try self.synthExpr(val_id);
                            continue;
                        };
                        const slot_kind = slot_layout.kind;

                        if (!slot_kind.isWithOverridable()) {
                            var msg_buf: [192]u8 = undefined;
                            const msg = std.fmt.bufPrint(
                                &msg_buf,
                                "internal `context.{s}` slot cannot be overridden via `with`",
                                .{slot_name},
                            ) catch "internal `context` slot cannot be overridden via `with`";
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                slot_span,
                                msg,
                                "only `allocator`, `temp_allocator`, `logger`, `diagnostics`, " ++
                                    "`cancel_token`, `reactor`, and `reactor_ctx` are overridable",
                            );
                            _ = try self.synthExpr(val_id);
                            continue;
                        }

                        const slot_bit: u16 = @as(u16, 1) << @intCast(@backingInt(slot_kind));
                        if ((seen_slots_mask & slot_bit) != 0) {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                slot_span,
                                "duplicate `context` slot override in the same `with` header",
                                "slot already overridden earlier in this `with` block",
                            );
                        }
                        seen_slots_mask |= slot_bit;

                        const slot_ty = (try self.resolveContextSeamFieldType(slot_name)) orelse .err_ty;
                        const val_ty = try self.synthExpr(val_id);
                        if (!val_ty.isError() and !slot_ty.isError()) {
                            const val_unwrapped = self.pool.unwrapUnderlyingType(val_ty);
                            const val_node = self.pool.getNode(val_unwrapped);
                            var is_coercible_handle = false;
                            if (slot_kind == .allocator or slot_kind == .temp_allocator) {
                                if (val_node.tag == .mut_ref_ty) {
                                    const inner_ty = self.pool.unwrapUnderlyingType(TypeId.fromInt(val_node.lhs));
                                    const inner_node = self.pool.getNode(inner_ty);
                                    if (inner_node.tag == .struct_ty) {
                                        const inner_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(inner_node.rhs)).*;
                                        if (CONTEXT_ALLOCATOR_NOMINAL_MAP.has(inner_sym.name_text)) {
                                            is_coercible_handle = true;
                                        } else if (!inner_sym.target_scope.isNone()) {
                                            if (self.interner.lookup("as_handle")) |handle_sym_id| {
                                                if (!self.sym_table.lookupInScopeDirect(
                                                    inner_sym.target_scope,
                                                    handle_sym_id,
                                                    NamespaceMask.VALUE_ONLY,
                                                ).isNone()) {
                                                    is_coercible_handle = true;
                                                }
                                            }
                                        }
                                    }
                                }
                            } else if (slot_kind == .logger or slot_kind == .diagnostics or
                                slot_kind == .cancel_token or slot_kind == .reactor or
                                slot_kind == .reactor_ctx)
                            {
                                if (val_node.tag == .raw_ptr_ty or
                                    (val_node.tag == .optional_ty and
                                        self.pool.getTag(TypeId.fromInt(val_node.lhs)) == .raw_ptr_ty))
                                {
                                    is_coercible_handle = true;
                                } else if (val_node.tag == .ref_ty or val_node.tag == .mut_ref_ty) {
                                    const is_ref_mode_ok = (slot_kind != .diagnostics and
                                        slot_kind != .reactor_ctx) or val_node.tag == .mut_ref_ty;
                                    const inner_ty = self.pool.unwrapUnderlyingType(TypeId.fromInt(val_node.lhs));
                                    const inner_node = self.pool.getNode(inner_ty);
                                    if (inner_ty == slot_ty) {
                                        is_coercible_handle = is_ref_mode_ok;
                                    } else if (is_ref_mode_ok and inner_node.tag == .struct_ty) {
                                        const inner_sym_idx = SymbolIndex.fromInt(inner_node.rhs);
                                        if (!inner_sym_idx.isNone() and
                                            inner_sym_idx.asInt() < self.sym_table.symbols.items.len)
                                        {
                                            const inner_sym = self.sym_table.getSymbol(inner_sym_idx).*;
                                            const is_matching_nominal = switch (slot_kind) {
                                                .logger => std.mem.eql(u8, inner_sym.name_text, "Logger"),
                                                .diagnostics => CONTEXT_DIAGNOSTICS_NOMINAL_MAP.has(
                                                    inner_sym.name_text,
                                                ),
                                                .cancel_token => std.mem.eql(u8, inner_sym.name_text, "CancelToken"),
                                                .reactor => std.mem.eql(u8, inner_sym.name_text, "Reactor") or
                                                    std.mem.eql(u8, inner_sym.name_text, "ReactorVTable"),
                                                .reactor_ctx => std.mem.eql(u8, inner_sym.name_text, "ReactorCtx"),
                                                else => false,
                                            };
                                            if (is_matching_nominal) {
                                                is_coercible_handle = true;
                                            } else if (!inner_sym.target_scope.isNone()) {
                                                if (self.interner.lookup("as_handle")) |handle_sym_id| {
                                                    if (!self.sym_table.lookupInScopeDirect(
                                                        inner_sym.target_scope,
                                                        handle_sym_id,
                                                        NamespaceMask.VALUE_ONLY,
                                                    ).isNone()) {
                                                        is_coercible_handle = true;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            if (!is_coercible_handle and val_unwrapped != slot_ty) {
                                _ = try self.checkTypeCompatibility(val_id, val_ty, slot_ty);
                            }
                        }
                    }
                }
            }
        }

        return self.recordNodeType(expr_id, try self.checkBlock(body_id, expected_ty, false));
    }

    /// Classification of the receiver prefix of a Unified `.` chain (`ADR-21C`).
    const DotReceiverClass = union(enum) {
        /// Runtime or compile-time value expression evaluated via `synthExpr`.
        value_expr,
        /// Module namespace scope (`cx`, `cx.mem`, `mod_a`, `mod_a.sub`).
        module_ns: ScopeId,
        /// Static type namespace (`Status`, `mod_a.Point`, `Vec[i32]`, `Self`, `u32`).
        type_ns: TypeId,
        /// Static resolution failed and already emitted a diagnostic.
        poisoned,
    };

    /// Resolves a lazy nominal/alias/stub type `SymbolIndex` to its concrete `TypeId`.
    fn ensureTypeSymbolResolved(self: *TypeChecker, sym_idx: SymbolIndex) !TypeId {
        if (sym_idx.isNone()) return .err_ty;
        const sym = self.sym_table.getSymbol(sym_idx).*;
        if (!sym.type_id.isError()) return sym.type_id;
        if (sym.kind == .trait_sym) {
            return self.ensureTraitSymbolTypeId(sym_idx);
        }
        if ((sym.kind == .struct_sym or sym.kind == .enum_sym) and sym.flags.is_builtin) {
            if (REFLECTION_MIRROR_NAME_MAP.has(sym.name_text)) {
                try self.ensureReflectionMirrorTypes();
                return self.sym_table.getSymbol(sym_idx).type_id;
            }
            return self.ensureBuiltinStubSymbolType(sym_idx);
        }
        if (sym.kind == .type_alias_sym or sym.kind == .distinct_type_sym or
            sym.kind == .refined_type_sym or sym.kind == .type_group_sym)
        {
            const resolved_alias = try self.resolveTypeAliasSymbol(sym_idx);
            self.sym_table.getSymbolMut(sym_idx).type_id = resolved_alias;
            return resolved_alias;
        }
        return sym.type_id;
    }

    /// Classifies `recv_id` under Unified `.` (`ADR-21C`) before falling back to `synthExpr`.
    fn classifyDotReceiver(self: *TypeChecker, recv_id: NodeIndex) anyerror!DotReceiverClass {
        if (recv_id.isNone() or recv_id.asInt() >= self.ast_arena.countNodes()) return .value_expr;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return .value_expr;
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const recv_node = self.ast_arena.getNode(recv_id);
        switch (recv_node.tag) {
            .ident_expr => {
                if (recv_node.main_token.isNone() or
                    recv_node.main_token.asInt() >= self.token_buffer.countTokens())
                {
                    return .value_expr;
                }
                if (self.token_buffer.getToken(recv_node.main_token).kind == .at) return .value_expr;
                const lexeme = symbol_resolver.extractTokenSlice(
                    self.source,
                    self.token_buffer,
                    recv_node.main_token,
                );
                if (lexeme.len == 0) return .value_expr;
                const span = self.token_buffer.getTokenSpan(self.file_id, recv_node.main_token);
                if (std.mem.eql(u8, lexeme, "pkg")) {
                    return .{
                        .module_ns = self.sym_table.resolveCallerPackageRootScope(self.file_id, self.current_scope),
                    };
                }
                const sym_id = try self.interner.intern(lexeme);

                // [1] Local / lexical value or `@c_import` const bindings take precedence; `.module_sym` yields `.module_ns`:
                switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_OR_CONST)) {
                    .found => |val_idx| {
                        const val_sym = self.sym_table.getSymbol(val_idx).*;
                        if (val_sym.kind == .module_sym) {
                            self.sym_table.markSymbolUsed(val_idx);
                            self.recordNodeSymbol(recv_id, val_idx);
                            if (!val_sym.target_scope.isNone()) {
                                return .{ .module_ns = val_sym.target_scope };
                            }
                            if (self.sym_table.lookupExternalPackageScope(self.file_id, sym_id)) |ext_scope| {
                                return .{ .module_ns = ext_scope };
                            }
                            return .{ .module_ns = val_sym.target_scope };
                        }
                        if (!val_sym.target_scope.isNone() and
                            (val_sym.kind == .const_sym or val_sym.kind == .local_let_sym or val_sym.kind == .local_var_sym))
                        {
                            self.sym_table.markSymbolUsed(val_idx);
                            self.recordNodeSymbol(recv_id, val_idx);
                            return .{ .module_ns = val_sym.target_scope };
                        }
                        return .value_expr;
                    },
                    .private_error => |priv_idx| {
                        if (self.sym_table.getSymbol(priv_idx).kind == .module_sym) {
                            if (self.diagnostic_sink) |sink| {
                                try symbol_resolver.emitPrivateAccessDiagnostic(
                                    sink,
                                    self.sym_table.getSymbol(priv_idx),
                                    span,
                                );
                            }
                            return .poisoned;
                        }
                        return .value_expr;
                    },
                    .not_found => {},
                }

                // [2] Root namespaces (`cx`, `core` with `E0218` gate, or declared dependency / root modules):
                if (std.mem.eql(u8, lexeme, "cx") or
                    std.mem.eql(u8, lexeme, "core"))
                {
                    const root_scope = try self.sym_table.resolveRootNamespaceScope(
                        self.interner,
                        self.current_scope,
                        lexeme,
                        span,
                        self.diagnostic_sink,
                    );
                    if (!root_scope.isNone()) {
                        const prelude_mod = self.sym_table.lookupInScopeDirect(
                            self.sym_table.prelude_scope,
                            sym_id,
                            NamespaceMask.VALUE_ONLY,
                        );
                        if (!prelude_mod.isNone()) {
                            self.sym_table.markSymbolUsed(prelude_mod);
                            self.recordNodeSymbol(recv_id, prelude_mod);
                        }
                        return .{ .module_ns = root_scope };
                    }
                    if (std.mem.eql(u8, lexeme, "core") and !self.sym_table.isCoreAllowedForFile(self.file_id)) {
                        return .poisoned;
                    }
                }
                if (self.sym_table.lookupExternalPackageScope(self.file_id, sym_id)) |ext_scope| {
                    return .{ .module_ns = ext_scope };
                }

                // [3] Built-in primitive types (`u32`, `i64`, `f64`, `usize`, `bool`, `str`, `char`):
                if (symbol_resolver.BUILTIN_TYPE_AND_GROUP_MAP.get(lexeme)) |builtin_ty| {
                    if (!builtin_ty.isBuiltinGroup()) {
                        _ = self.recordNodeType(recv_id, builtin_ty);
                        return .{ .type_ns = builtin_ty };
                    }
                }

                // [4] Lexical type symbols (`Status`, `Point`, `Self`, imported nominal types):
                switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.TYPE_ONLY)) {
                    .found => |ty_idx| {
                        self.sym_table.markSymbolUsed(ty_idx);
                        self.recordNodeSymbol(recv_id, ty_idx);
                        const resolved_ty = try self.ensureTypeSymbolResolved(ty_idx);
                        _ = self.recordNodeType(recv_id, resolved_ty);
                        return .{ .type_ns = resolved_ty };
                    },
                    .private_error => |priv_idx| {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitPrivateAccessDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                span,
                            );
                        }
                        return .poisoned;
                    },
                    .not_found => {
                        if (lexeme[0] >= 'A' and lexeme[0] <= 'Z') {
                            if (REFLECTION_MIRROR_NAME_MAP.has(lexeme)) {
                                try self.ensureReflectionMirrorTypes();
                                const meta_scope = try self.sym_table.ensureCxMetaScope(self.interner);
                                const m_idx = self.sym_table.lookupInScopeDirect(
                                    meta_scope,
                                    sym_id,
                                    NamespaceMask.TYPE_ONLY,
                                );
                                if (!m_idx.isNone()) {
                                    const m_ty = self.sym_table.getSymbol(m_idx).type_id;
                                    self.recordNodeSymbol(recv_id, m_idx);
                                    _ = self.recordNodeType(recv_id, m_ty);
                                    return .{ .type_ns = m_ty };
                                }
                            }
                            if (try self.ensureBuiltinStdNominalType(lexeme)) |builtin_nom_ty| {
                                if (self.sym_table.type_to_symbol.get(builtin_nom_ty.toU32())) |builtin_sym_idx| {
                                    self.sym_table.markSymbolUsed(builtin_sym_idx);
                                    self.recordNodeSymbol(recv_id, builtin_sym_idx);
                                }
                                _ = self.recordNodeType(recv_id, builtin_nom_ty);
                                return .{ .type_ns = builtin_nom_ty };
                            }
                        }
                        return .value_expr;
                    },
                }
            },
            .field_access => {
                if (recv_node.lhs.tag != .node or recv_node.rhs.tag != .token) return .value_expr;
                const parent_id = NodeIndex.fromInt(recv_node.lhs.payload);
                const seg_tok = TokenIndex.fromInt(recv_node.rhs.payload);
                const seg_lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, seg_tok);
                const seg_span = self.token_buffer.getTokenSpan(self.file_id, seg_tok);

                switch (try self.classifyDotReceiver(parent_id)) {
                    .value_expr, .type_ns => return .value_expr,
                    .poisoned => return .poisoned,
                    .module_ns => |mod_scope| {
                        if (mod_scope.isNone() or seg_lexeme.len == 0) return .poisoned;
                        const seg_sym_id = try self.interner.intern(seg_lexeme);
                        switch (self.sym_table.lookupInTargetScope(
                            mod_scope,
                            self.current_scope,
                            seg_sym_id,
                            NamespaceMask.TYPE_OR_VALUE,
                        )) {
                            .found => |sym_idx| {
                                self.sym_table.markSymbolUsed(sym_idx);
                                self.recordNodeSymbol(recv_id, sym_idx);
                                const sym = self.sym_table.getSymbol(sym_idx).*;
                                if (sym.kind == .module_sym) {
                                    return .{ .module_ns = sym.target_scope };
                                }
                                if (sym.namespace == .type_ns) {
                                    const resolved_ty = try self.ensureTypeSymbolResolved(sym_idx);
                                    _ = self.recordNodeType(recv_id, resolved_ty);
                                    return .{ .type_ns = resolved_ty };
                                }
                                return .value_expr;
                            },
                            .private_error => |priv_idx| {
                                if (self.diagnostic_sink) |sink| {
                                    try symbol_resolver.emitPrivateAccessDiagnostic(
                                        sink,
                                        self.sym_table.getSymbol(priv_idx),
                                        seg_span,
                                    );
                                }
                                return .poisoned;
                            },
                            .not_found => {
                                if (mod_scope == self.sym_table.cx_root_scope and
                                    std.mem.eql(u8, seg_lexeme, "async"))
                                {
                                    const async_scope = try self.sym_table.scope_arena.allocScope(
                                        .module_scope,
                                        mod_scope,
                                        .NONE,
                                        .none,
                                        .{},
                                    );
                                    const async_mod_idx = try self.sym_table.defineSymbol(.{
                                        .name = seg_sym_id,
                                        .name_text = self.interner.get(seg_sym_id),
                                        .kind = .module_sym,
                                        .namespace = .value_ns,
                                        .visibility = .public,
                                        .flags = .{ .is_pub = true, .is_used = true, .is_builtin = true },
                                        .scope_id = mod_scope,
                                        .target_scope = async_scope,
                                    }, null);
                                    self.recordNodeSymbol(recv_id, async_mod_idx);
                                    return .{ .module_ns = async_scope };
                                }
                                if (self.diagnostic_sink) |sink| {
                                    const suggestion = self.sym_table.suggestClosestInScope(
                                        mod_scope,
                                        seg_lexeme,
                                        NamespaceMask.ALL,
                                    );
                                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                        sink,
                                        self.interner,
                                        seg_lexeme,
                                        seg_span,
                                        suggestion,
                                    );
                                }
                                return .poisoned;
                            },
                        }
                    },
                }
            },
            .generic_call => {
                if (recv_node.lhs.tag != .node) return .value_expr;
                const base_id = NodeIndex.fromInt(recv_node.lhs.payload);
                const raw_items = self.getNodeExtraSlice(recv_id, true);
                const base_node = self.ast_arena.getNode(base_id);
                if (base_node.tag == .ident_expr and !base_node.main_token.isNone()) {
                    const base_lex = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        base_node.main_token,
                    );
                    if (std.mem.eql(u8, base_lex, "Option") and raw_items.len == 1) {
                        const inner_ty = try self.resolveTypeAst(NodeIndex.fromInt(raw_items[0]));
                        const opt_ty = try self.pool.internOptional(inner_ty);
                        _ = self.recordNodeType(recv_id, opt_ty);
                        return .{ .type_ns = opt_ty };
                    }
                    if (std.mem.eql(u8, base_lex, "Result") and raw_items.len == 2) {
                        const ok_ty = try self.resolveTypeAst(NodeIndex.fromInt(raw_items[0]));
                        const err_arg_ty = try self.resolveTypeAst(NodeIndex.fromInt(raw_items[1]));
                        const res_ty = try self.pool.internResult(ok_ty, err_arg_ty);
                        _ = self.recordNodeType(recv_id, res_ty);
                        return .{ .type_ns = res_ty };
                    }
                    if (std.mem.eql(u8, base_lex, "TaskGroup") and raw_items.len == 1) {
                        const err_arg_ty = try self.resolveTypeAst(NodeIndex.fromInt(raw_items[0]));
                        const tg_ty = try self.pool.internTaskGroup(err_arg_ty);
                        _ = self.recordNodeType(recv_id, tg_ty);
                        return .{ .type_ns = tg_ty };
                    }
                    if (std.mem.eql(u8, base_lex, "TaskHandle") and raw_items.len == 1) {
                        const val_arg_ty = try self.resolveTypeAst(NodeIndex.fromInt(raw_items[0]));
                        const th_ty = try self.pool.internTaskHandle(val_arg_ty);
                        _ = self.recordNodeType(recv_id, th_ty);
                        return .{ .type_ns = th_ty };
                    }
                }
                switch (try self.classifyDotReceiver(base_id)) {
                    .poisoned => return .poisoned,
                    .type_ns => |base_ty| {
                        var full_args: std.ArrayListUnmanaged(TypeId) = .empty;
                        defer full_args.deinit(self.allocator);
                        for (raw_items) |raw_item| {
                            try full_args.append(self.allocator, try self.resolveTypeAst(NodeIndex.fromInt(raw_item)));
                        }
                        const base_node_rec = self.pool.getNode(self.pool.unwrapUnderlyingType(base_ty));
                        if (base_node_rec.tag == .struct_ty or base_node_rec.tag == .enum_ty or
                            base_node_rec.tag == .union_ty or base_node_rec.tag == .trait_ty)
                        {
                            const base_sym_idx = SymbolIndex.fromInt(base_node_rec.rhs);
                            if (!base_sym_idx.isNone()) {
                                try self.appendResolvedTrailingGenericDefaults(
                                    base_sym_idx,
                                    &full_args,
                                    self.getAstNodeSpan(recv_id),
                                );
                            }
                        }
                        const inst_ty = try self.internNominalWithResolvedArgs(base_ty, full_args.items);
                        _ = self.recordNodeType(recv_id, inst_ty);
                        return .{ .type_ns = inst_ty };
                    },
                    .value_expr, .module_ns => return .value_expr,
                }
            },
            .prim_type, .named_type, .generic_type => {
                return .{ .type_ns = try self.resolveTypeAst(recv_id) };
            },
            .call_expr => {
                if (recv_node.lhs.tag == .node) {
                    const callee_id = NodeIndex.fromInt(recv_node.lhs.payload);
                    const callee_node = self.ast_arena.getNode(callee_id);
                    if (callee_node.tag == .ident_expr and !callee_node.main_token.isNone() and
                        self.token_buffer.getToken(callee_node.main_token).kind == .at)
                    {
                        const intr_tok = if (callee_node.lhs.tag == .token)
                            TokenIndex.fromInt(callee_node.lhs.payload)
                        else
                            callee_node.main_token;
                        if (std.mem.eql(
                            u8,
                            symbol_resolver.extractTokenSlice(self.source, self.token_buffer, intr_tok),
                            "c_import",
                        )) {
                            _ = try self.synthExpr(recv_id);
                            if (recv_id.asInt() < self.node_symbols.len) {
                                const mod_idx = self.node_symbols[recv_id.asInt()];
                                if (!mod_idx.isNone() and mod_idx.asInt() < self.sym_table.countSymbols()) {
                                    const mod_sym = self.sym_table.getSymbol(mod_idx).*;
                                    if (mod_sym.kind == .module_sym and !mod_sym.target_scope.isNone()) {
                                        return .{ .module_ns = mod_sym.target_scope };
                                    }
                                }
                            }
                            return .poisoned;
                        }
                    }
                }
                return .value_expr;
            },
            else => return .value_expr,
        }
    }

    /// Shared capability intersection across union-bounded slice/text type parameters (`SE-09`, e.g., `[Data: str | &[u8]]`).
    const UnionSliceCaps = struct {
        /// `true` when every union member supports `.len()` -> `usize` and `.is_empty()` -> `bool`.
        has_len_and_empty: bool = false,
        /// `true` when every union member supports `.as_bytes()` -> `&[u8]`.
        has_as_bytes: bool = false,
        /// Shared element `TypeId` across all union members (`.err_ty` when heterogeneous or non-slice).
        shared_elem_ty: TypeId = .err_ty,
    };

    /// Computes shared slice/string capabilities for union-bounded type variables (`[Data: str | &[u8]]`, `SE-09`).
    fn getSharedUnionSliceCapabilities(self: *const TypeChecker, ty: TypeId) UnionSliceCaps {
        const node = self.pool.getNode(ty);
        if (node.tag != .type_param and node.tag != .bind_once_group_var and node.tag != .bind_many_any_var) {
            return .{};
        }
        const grp_ty = TypeId.fromInt(node.lhs);
        const grp_node = self.pool.getNode(grp_ty);
        if (grp_node.tag != .user_group or grp_node.rhs == INTERSECT_GROUP_SENTINEL) return .{};
        const view = self.pool.getUserGroupView(grp_ty) orelse return .{};

        var member_count: usize = 0;
        var common_elem: TypeId = .err_ty;
        var is_elem_homogeneous = true;
        var is_all_byte_backed = true;

        const combined_prim_mask = view.prim_mask | view.tilde_prim_mask;
        var prim_idx: u32 = 0;
        while (prim_idx <= 18) : (prim_idx += 1) {
            const prim_tid = TypeId.fromInt(prim_idx);
            if (!TypeGroupMask.containsPrimitive(combined_prim_mask, prim_tid)) continue;
            if (prim_tid != .str_ty) return .{};
            if (member_count == 0) {
                common_elem = .u8_ty;
            } else if (common_elem != .u8_ty) {
                is_elem_homogeneous = false;
            }
            member_count += 1;
        }

        const lists = [2][]const u32{ view.exact_members, view.tilde_members };
        for (lists) |mem_list| {
            for (mem_list) |raw_mem| {
                const unwrapped_mem = self.unwrapRefType(self.pool.unwrapUnderlyingType(TypeId.fromInt(raw_mem)));
                var mem_elem: TypeId = .err_ty;
                var is_mem_bytes_ok = false;
                if (unwrapped_mem == .str_ty) {
                    mem_elem = .u8_ty;
                    is_mem_bytes_ok = true;
                } else {
                    const mem_node = self.pool.getNode(unwrapped_mem);
                    if (mem_node.tag == .slice_ty or mem_node.tag == .array_ty) {
                        mem_elem = TypeId.fromInt(mem_node.lhs);
                        is_mem_bytes_ok = mem_elem == .u8_ty or
                            self.pool.explainIntoBytesViolation(mem_elem, self.sym_table, self.target_layout) == null;
                    } else {
                        return .{};
                    }
                }
                if (member_count == 0) {
                    common_elem = mem_elem;
                } else if (common_elem != mem_elem) {
                    is_elem_homogeneous = false;
                }
                if (!is_mem_bytes_ok) is_all_byte_backed = false;
                member_count += 1;
            }
        }

        if (member_count == 0) return .{};
        return .{
            .has_len_and_empty = true,
            .has_as_bytes = is_all_byte_backed,
            .shared_elem_ty = if (is_elem_homogeneous) common_elem else .err_ty,
        };
    }

    /// Synthesizes `.field_access` (`s.field`, `tup.0`, `mod.ITEM`, `Type.CONST`, `Enum.Variant`, or `#soa` column slice).
    fn synthFieldAccess(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node or ast_node.rhs.tag != .token) return .err_ty;
        const recv_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const member_tok = TokenIndex.fromInt(ast_node.rhs.payload);
        const member_lexeme = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, member_tok);
        const member_span = self.token_buffer.getTokenSpan(self.file_id, member_tok);

        // [0] Unified `.` module & static type namespace access (`ADR-21C`):
        switch (try self.classifyDotReceiver(recv_id)) {
            .poisoned => return .err_ty,
            .module_ns => |mod_scope| {
                if (mod_scope.isNone() or member_lexeme.len == 0) return .err_ty;
                const member_sym_id = try self.interner.intern(member_lexeme);
                switch (self.sym_table.lookupInTargetScope(
                    mod_scope,
                    self.current_scope,
                    member_sym_id,
                    NamespaceMask.ALL,
                )) {
                    .found => |sym_idx| {
                        self.sym_table.markSymbolUsed(sym_idx);
                        self.recordNodeSymbol(expr_id, sym_idx);
                        try self.checkComptimeSymbolAccess(expr_id, sym_idx);
                        try self.checkExternStaticAccess(expr_id, sym_idx);
                        const target_idx = self.unwrapAliasSymbolIdx(sym_idx);
                        const sym = self.sym_table.getSymbol(target_idx).*;
                        if (sym.kind == .fn_sym and sym.type_id.isError()) {
                            try self.resolveFnSignatureSymbol(target_idx);
                        }
                        return self.sym_table.getSymbol(target_idx).type_id;
                    },
                    .private_error => |priv_idx| {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitPrivateAccessDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                member_span,
                            );
                        }
                        return .err_ty;
                    },
                    .not_found => {
                        if (self.diagnostic_sink) |sink| {
                            const suggestion = self.sym_table.suggestClosestInScope(
                                mod_scope,
                                member_lexeme,
                                NamespaceMask.ALL,
                            );
                            try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                sink,
                                self.interner,
                                member_lexeme,
                                member_span,
                                suggestion,
                            );
                        }
                        return .err_ty;
                    },
                }
            },
            .type_ns => |static_ty| {
                if (static_ty.isError()) return .err_ty;
                const unwrapped_static = self.pool.unwrapUnderlyingType(static_ty);
                const static_base = self.pool.unwrapRefinementBase(unwrapped_static);
                if (static_base.isIntegerPrimitive()) {
                    if (INT_ASSOC_CONST_MAP.get(member_lexeme)) |int_assoc| {
                        return switch (int_assoc) {
                            .bits => .u32_ty,
                            .min, .max => static_base,
                        };
                    }
                } else if (static_base.isFloatPrimitive()) {
                    if (FLOAT_ASSOC_CONST_MAP.get(member_lexeme)) |float_assoc| {
                        return switch (float_assoc) {
                            .bits => .u32_ty,
                            else => static_base,
                        };
                    }
                }

                const static_node = self.pool.getNode(unwrapped_static);
                if (static_node.tag == .optional_ty) {
                    if (std.mem.eql(u8, member_lexeme, "None")) {
                        return static_ty;
                    } else if (std.mem.eql(u8, member_lexeme, "Some")) {
                        const param_tys = [1]TypeId{TypeId.fromInt(static_node.lhs)};
                        const param_modes = [1]ParamMode{.let_mode};
                        return self.pool.internFn(.fn_ty, &param_tys, &param_modes, static_ty, false);
                    }
                } else if (static_node.tag == .result_ty) {
                    if (std.mem.eql(u8, member_lexeme, "Ok")) {
                        const param_tys = [1]TypeId{TypeId.fromInt(static_node.lhs)};
                        const param_modes = [1]ParamMode{.let_mode};
                        return self.pool.internFn(.fn_ty, &param_tys, &param_modes, static_ty, false);
                    } else if (std.mem.eql(u8, member_lexeme, "Err")) {
                        const param_tys = [1]TypeId{TypeId.fromInt(static_node.rhs)};
                        const param_modes = [1]ParamMode{.let_mode};
                        return self.pool.internFn(.fn_ty, &param_tys, &param_modes, static_ty, false);
                    }
                } else if (static_node.tag == .struct_ty or static_node.tag == .enum_ty or
                    static_node.tag == .union_ty or static_node.tag == .bit_field_ty or
                    static_node.tag == .trait_ty)
                {
                    const owner_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(static_node.rhs)).*;
                    if (!owner_sym.target_scope.isNone()) {
                        const member_sym_id = try self.interner.intern(member_lexeme);
                        switch (self.sym_table.lookupInTargetScope(
                            owner_sym.target_scope,
                            self.current_scope,
                            member_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        )) {
                            .found => |m_idx| {
                                self.sym_table.markSymbolUsed(m_idx);
                                self.recordNodeSymbol(expr_id, m_idx);
                                const m_sym = self.sym_table.getSymbol(m_idx).*;
                                if (m_sym.kind == .enum_variant_sym) {
                                    const var_payload = try self.substituteNominalMemberType(
                                        unwrapped_static,
                                        m_sym.type_id,
                                    );
                                    if (var_payload == .unit_ty) return static_ty;
                                    const param_tys = [_]TypeId{var_payload};
                                    const param_modes = [_]ParamMode{.let_mode};
                                    return self.pool.internFn(.fn_ty, &param_tys, &param_modes, static_ty, false);
                                }
                                if (m_sym.kind == .fn_sym and m_sym.type_id.isError()) {
                                    try self.resolveFnSignatureSymbol(m_idx);
                                }
                                return self.substituteNominalMemberType(
                                    unwrapped_static,
                                    self.sym_table.getSymbol(m_idx).type_id,
                                );
                            },
                            .private_error => |priv_idx| {
                                if (self.diagnostic_sink) |sink| {
                                    try symbol_resolver.emitPrivateAccessDiagnostic(
                                        sink,
                                        self.sym_table.getSymbol(priv_idx),
                                        member_span,
                                    );
                                }
                                return .err_ty;
                            },
                            .not_found => {
                                if (self.diagnostic_sink) |sink| {
                                    const suggestion = self.sym_table.suggestClosestInScope(
                                        owner_sym.target_scope,
                                        member_lexeme,
                                        NamespaceMask.VALUE_ONLY,
                                    );
                                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                        sink,
                                        self.interner,
                                        member_lexeme,
                                        member_span,
                                        suggestion,
                                    );
                                }
                                return .err_ty;
                            },
                        }
                    }
                }
                if (self.diagnostic_sink) |sink| {
                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                        sink,
                        self.interner,
                        member_lexeme,
                        member_span,
                        null,
                    );
                }
                return .err_ty;
            },
            .value_expr => {},
        }

        const raw_recv_ty = try self.synthExpr(recv_id);
        if (raw_recv_ty.isError()) return .err_ty;
        const unwrapped_raw_recv = self.pool.unwrapUnderlyingType(raw_recv_ty);

        // `ADR-22F`: raw pointers never auto-dereference on `.` field access (require explicit `ptr.*.field` in `unsafe`):
        if (self.pool.getTag(unwrapped_raw_recv) == .raw_ptr_ty) {
            var ptr_msg_buf: [200]u8 = undefined;
            const ptr_msg = std.fmt.bufPrint(
                &ptr_msg_buf,
                "raw pointer does not auto-dereference on field access; write `ptr.*.{s}` inside `unsafe`",
                .{member_lexeme},
            ) catch "raw pointer does not auto-dereference on field access; use `.*` inside `unsafe`";
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                member_span,
                ptr_msg,
                "explicit `.*` dereference required on raw pointer",
            );
            return .err_ty;
        }

        const recv_ty = self.unwrapRefType(raw_recv_ty);
        const recv_node = self.pool.getNode(recv_ty);

        // [0b] Built-in `SourceLoc` (`.source_loc_ty`, `SE-17`) inline `.rodata` descriptor fields:
        if (recv_ty == .source_loc_ty) {
            if (std.mem.eql(u8, member_lexeme, "file") or std.mem.eql(u8, member_lexeme, "fn_name")) {
                return .str_ty;
            }
            if (std.mem.eql(u8, member_lexeme, "line") or std.mem.eql(u8, member_lexeme, "col")) {
                return .u32_ty;
            }
        }

        // [1] Tuple index access (`tup.0`, `tup.1`):
        if (recv_node.tag == .tuple_ty and self.token_buffer.getToken(member_tok).kind == .int_lit) {
            var is_canonical_digits = member_lexeme.len > 0 and
                !(member_lexeme.len > 1 and member_lexeme[0] == '0');
            if (is_canonical_digits) {
                for (member_lexeme) |byte_ch| {
                    if (byte_ch < '0' or byte_ch > '9') {
                        is_canonical_digits = false;
                        break;
                    }
                }
            }
            if (!is_canonical_digits) {
                var inv_buf: [192]u8 = undefined;
                const inv_msg = std.fmt.bufPrint(
                    &inv_buf,
                    "invalid tuple index `{s}`; expected canonical decimal index without leading zeros or suffixes",
                    .{member_lexeme},
                ) catch "invalid tuple index; expected canonical decimal index";
                try self.emitDiagnosticSimple(
                    .e0403_unresolved_symbol,
                    member_span,
                    inv_msg,
                    "tuple index must be a plain decimal integer (`0`, `1`, …)",
                );
                return .err_ty;
            }
            const elems = self.pool.getTupleElements(recv_ty);
            if (extractIntLiteralValue(member_lexeme)) |parsed| {
                if (parsed.value >= 0 and parsed.value < elems.len) {
                    return TypeId.fromInt(elems[@intCast(parsed.value)]);
                }
            }
            var oob_buf: [160]u8 = undefined;
            const oob_msg = std.fmt.bufPrint(
                &oob_buf,
                "tuple index `{s}` is out of bounds for tuple of length {d}",
                .{ member_lexeme, elems.len },
            ) catch "tuple index out of bounds";
            try self.emitDiagnosticSimple(
                .e0403_unresolved_symbol,
                member_span,
                oob_msg,
                "tuple element index out of bounds",
            );
            return .err_ty;
        }

        // [2] `#soa [S]` or `#soa [S; N]` column slice projection (`DR-04` Section 2.1):
        if (recv_node.tag == .soa_slice_ty or recv_node.tag == .soa_array_ty) {
            if (std.mem.eql(u8, member_lexeme, "len")) {
                try self.emitDiagnosticWithSingleFix(
                    .e0424_retired_slice_field_access,
                    member_span,
                    "bare `.len` property access is retired; call `.len()` method instead",
                    "replace `.len` with `.len()`",
                    "call `.len()` method",
                    member_span,
                    "len()",
                );
                return .usize_ty;
            }
            const elem_ty = TypeId.fromInt(recv_node.lhs);
            const elem_node = self.pool.getNode(elem_ty);
            if (elem_node.tag == .struct_ty) {
                const struct_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(elem_node.rhs)).*;
                if (!struct_sym.target_scope.isNone()) {
                    const f_sym_id = try self.interner.intern(member_lexeme);
                    const f_idx = self.sym_table.lookupInScopeDirect(
                        struct_sym.target_scope,
                        f_sym_id,
                        NamespaceMask.VALUE_ONLY,
                    );
                    if (!f_idx.isNone()) {
                        self.sym_table.markSymbolUsed(f_idx);
                        self.recordNodeSymbol(expr_id, f_idx);
                        const col_ty = try self.substituteNominalMemberType(
                            elem_ty,
                            self.sym_table.getSymbol(f_idx).type_id,
                        );
                        return self.pool.internSlice(col_ty, false);
                    }
                }
            }
        }

        // [3] Retired `.len` and `.ptr` properties on slices, arrays, `str`, and union-bounded slices (`ADR-22D`, `E0424`):
        const union_caps = self.getSharedUnionSliceCapabilities(recv_ty);
        if (recv_node.tag == .slice_ty or recv_node.tag == .array_ty or recv_ty == .str_ty or union_caps.has_len_and_empty) {
            if (std.mem.eql(u8, member_lexeme, "len")) {
                try self.emitDiagnosticWithSingleFix(
                    .e0424_retired_slice_field_access,
                    member_span,
                    "bare `.len` property access is retired; call `.len()` method instead",
                    "replace `.len` with `.len()`",
                    "call `.len()` method",
                    member_span,
                    "len()",
                );
                return .usize_ty;
            }
            if (std.mem.eql(u8, member_lexeme, "ptr")) {
                const is_mut_recv = self.pool.getTag(unwrapped_raw_recv) == .mut_ref_ty or
                    (self.pool.getTag(unwrapped_raw_recv) != .ref_ty and self.isMutableAssignablePlace(recv_id));
                const repl = if (is_mut_recv and recv_ty != .str_ty) "as_mut_ptr()" else "as_ptr()";
                try self.emitDiagnosticWithSingleFix(
                    .e0424_retired_slice_field_access,
                    member_span,
                    "bare `.ptr` property access is retired; call `.as_ptr()` or `.as_mut_ptr()` instead",
                    "replace `.ptr` with pointer accessor method",
                    "call `.as_ptr()` / `.as_mut_ptr()`",
                    member_span,
                    repl,
                );
                const ptr_elem_ty = if (recv_ty == .str_ty)
                    .u8_ty
                else if (recv_node.tag == .slice_ty or recv_node.tag == .array_ty)
                    TypeId.fromInt(recv_node.lhs)
                else if (!union_caps.shared_elem_ty.isError())
                    union_caps.shared_elem_ty
                else
                    .u8_ty;
                return self.pool.internRawPtr(ptr_elem_ty, is_mut_recv and recv_ty != .str_ty);
            }
        }

        // [4] Nominal `struct`, `union`, or `bit_field` member access:
        if (recv_node.tag == .struct_ty or recv_node.tag == .union_ty or recv_node.tag == .bit_field_ty) {
            const type_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(recv_node.rhs)).*;
            if (!type_sym.target_scope.isNone()) {
                const member_sym_id = try self.interner.intern(member_lexeme);
                switch (self.sym_table.lookupInTargetScope(
                    type_sym.target_scope,
                    self.current_scope,
                    member_sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => |f_idx| {
                        self.sym_table.markSymbolUsed(f_idx);
                        self.recordNodeSymbol(expr_id, f_idx);
                        return self.substituteNominalMemberType(
                            recv_ty,
                            self.sym_table.getSymbol(f_idx).type_id,
                        );
                    },
                    .private_error => |priv_idx| {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitPrivateAccessDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                member_span,
                            );
                        }
                        return .err_ty;
                    },
                    .not_found => {
                        if (isContextType(self.pool, self.sym_table, recv_ty)) {
                            if (try self.resolveContextSeamFieldType(member_lexeme)) |ctx_field_ty| {
                                return ctx_field_ty;
                            }
                        }
                        if (self.diagnostic_sink) |sink| {
                            const suggestion = self.sym_table.suggestClosestInScope(
                                type_sym.target_scope,
                                member_lexeme,
                                NamespaceMask.VALUE_ONLY,
                            );
                            try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                sink,
                                self.interner,
                                member_lexeme,
                                member_span,
                                suggestion,
                            );
                        }
                        return .err_ty;
                    },
                }
            }
        }
        if (!self.pool.getFlags(recv_ty).has_type_vars) {
            if (self.diagnostic_sink) |sink| {
                try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                    sink,
                    self.interner,
                    member_lexeme,
                    member_span,
                    null,
                );
            }
        }
        return .err_ty;
    }

    /// Synthesizes `base[index]`, `base[i, j]` (`SE-21` `subscript`), and `base[low..high]` (`DR-21` `SE-04`, `SE-09`).
    fn synthIndexExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const base_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;

        var idx_buf: [8]NodeIndex = undefined;
        var dyn_idx_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer dyn_idx_nodes.deinit(self.allocator);
        const idx_nodes: []const NodeIndex = if (ast_node.rhs.tag == .node) blk_one: {
            idx_buf[0] = NodeIndex.fromInt(ast_node.rhs.payload);
            break :blk_one idx_buf[0..1];
        } else if (ast_node.rhs.tag == .extra) blk_many: {
            const raw_extra = self.getNodeExtraSlice(expr_id, true);
            if (raw_extra.len <= idx_buf.len) {
                for (raw_extra, 0..) |raw_id, i| idx_buf[i] = NodeIndex.fromInt(raw_id);
                break :blk_many idx_buf[0..raw_extra.len];
            }
            try dyn_idx_nodes.ensureTotalCapacity(self.allocator, raw_extra.len);
            for (raw_extra) |raw_id| dyn_idx_nodes.appendAssumeCapacity(NodeIndex.fromInt(raw_id));
            break :blk_many dyn_idx_nodes.items;
        } else &.{};
        const idx_id: NodeIndex = if (idx_nodes.len == 1) idx_nodes[0] else .none;

        const raw_base_ty = try self.synthExpr(base_id);
        const unwrapped_raw_base = self.pool.unwrapUnderlyingType(raw_base_ty);
        const base_ty = self.unwrapRefType(unwrapped_raw_base);
        const base_node = self.pool.getNode(base_ty);
        const union_caps = self.getSharedUnionSliceCapabilities(base_ty);

        const is_mut_place = self.pool.getTag(unwrapped_raw_base) == .mut_ref_ty or
            (self.pool.getTag(unwrapped_raw_base) != .ref_ty and self.isMutableAssignablePlace(base_id));

        const is_len_capable: bool = switch (base_node.tag) {
            .slice_ty, .soa_slice_ty, .array_ty, .soa_array_ty => true,
            .struct_ty => blk_len: {
                const s_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(base_node.rhs)).*;
                if (std.mem.eql(u8, s_sym.name_text, "Map") or
                    std.mem.eql(u8, s_sym.name_text, "HashMap") or
                    std.mem.eql(u8, s_sym.name_text, "BTreeMap"))
                {
                    break :blk_len false;
                }
                if (std.mem.eql(u8, s_sym.name_text, "Vec") or
                    std.mem.eql(u8, s_sym.name_text, "SoaVec") or
                    std.mem.eql(u8, s_sym.name_text, "String"))
                {
                    break :blk_len true;
                }
                if (!s_sym.target_scope.isNone()) {
                    if (self.interner.lookup("len")) |len_sym_id| {
                        if (!self.sym_table.lookupInScopeDirect(
                            s_sym.target_scope,
                            len_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        ).isNone()) {
                            break :blk_len true;
                        }
                    }
                }
                break :blk_len false;
            },
            else => base_ty.isError() or base_ty == .str_ty or union_caps.has_len_and_empty,
        };

        const pushed_bracket = self.bracket_len_depth < self.bracket_len_stack.len;
        if (pushed_bracket) {
            self.bracket_len_stack[self.bracket_len_depth] = is_len_capable;
            self.bracket_len_depth += 1;
        }
        defer if (pushed_bracket) {
            self.bracket_len_depth -= 1;
        };

        // [0] Custom `subscript` declaration lookup on nominal / trait-bounded receivers (`SE-21`):
        var sub_owner_scope: ScopeId = .none;
        if (base_node.tag == .struct_ty or base_node.tag == .enum_ty or
            base_node.tag == .union_ty or base_node.tag == .trait_ty)
        {
            sub_owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(base_node.rhs)).target_scope;
        } else if (base_node.tag == .type_param or base_node.tag == .bind_once_group_var or
            base_node.tag == .bind_many_any_var)
        {
            const bound_node = self.pool.getNode(TypeId.fromInt(base_node.lhs));
            if (bound_node.tag == .trait_ty) {
                sub_owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(bound_node.rhs)).target_scope;
            }
        }
        if (!sub_owner_scope.isNone()) {
            if (self.interner.lookup("subscript")) |sub_sym_id| {
                switch (self.sym_table.lookupInTargetScope(
                    sub_owner_scope,
                    self.current_scope,
                    sub_sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => |sub_idx| {
                        self.sym_table.markSymbolUsed(sub_idx);
                        self.recordNodeSymbol(expr_id, sub_idx);
                        const sub_sym = self.sym_table.getSymbol(sub_idx).*;
                        var raw_sub_ret: TypeId = .err_ty;
                        if (sub_sym.flags.is_overload) {
                            if (self.sym_table.getOverloadSet(sub_owner_scope, sub_sym_id)) |ov_set| {
                                if (ov_set.members.items.len > 1) {
                                    raw_sub_ret = try self.resolveAndCheckOverloadCall(
                                        expr_id,
                                        ov_set.members.items,
                                        &.{},
                                        idx_nodes,
                                    );
                                    raw_sub_ret = try self.substituteNominalMemberType(base_ty, raw_sub_ret);
                                }
                            }
                        }
                        if (raw_sub_ret.isError() and !sub_sym.flags.is_overload) {
                            try self.resolveFnSignatureSymbol(sub_idx);
                            const sub_fn_ty = try self.substituteNominalMemberType(
                                base_ty,
                                self.sym_table.getSymbol(sub_idx).type_id,
                            );
                            raw_sub_ret = try self.checkCallArgumentsAgainstFn(
                                expr_id,
                                sub_fn_ty,
                                sub_idx,
                                null,
                                &.{},
                                idx_nodes,
                            );
                        }
                        if (!raw_sub_ret.isError()) {
                            const ret_node = self.pool.getNode(raw_sub_ret);
                            if (ret_node.tag == .ref_ty or ret_node.tag == .mut_ref_ty) {
                                const inner_ty = TypeId.fromInt(ret_node.lhs);
                                const inner_tag = self.pool.getTag(inner_ty);
                                if (inner_tag != .slice_ty and inner_tag != .soa_slice_ty) {
                                    return inner_ty;
                                }
                            }
                        }
                        return raw_sub_ret;
                    },
                    .private_error => |priv_idx| {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitPrivateAccessDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                self.getAstNodeSpan(expr_id),
                            );
                        }
                        for (idx_nodes) |arg_node_id| _ = try self.synthExpr(arg_node_id);
                        return .err_ty;
                    },
                    .not_found => {},
                }
            }
        }

        if (idx_nodes.len > 1) {
            for (idx_nodes) |arg_node_id| _ = try self.synthExpr(arg_node_id);
            if (!base_ty.isError()) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(expr_id),
                    "multi-argument indexing `a[i, j]` requires a `subscript` accessor declaration on the receiver type",
                    "no `subscript` accessor found on receiver type",
                );
            }
            return .err_ty;
        }

        const is_range_index = !idx_id.isNone() and
            idx_id.asInt() < self.ast_arena.countNodes() and
            self.ast_arena.getNode(idx_id).tag == .range_expr;

        if (!idx_id.isNone()) {
            const saved_pos = self.is_direct_positive_cond;
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_direct_positive_cond = false;
            self.is_dominating_walrus_pos = false;
            defer {
                self.is_direct_positive_cond = saved_pos;
                self.is_dominating_walrus_pos = saved_walrus;
            }
            const idx_ty = try self.synthExpr(idx_id);
            const idx_base = self.pool.unwrapRefinementBase(idx_ty);
            if (is_range_index and idx_base == .untyped_int_ty) {
                const range_node = self.ast_arena.getNode(idx_id);
                if (range_node.lhs.tag == .node) {
                    _ = try self.checkExpr(NodeIndex.fromInt(range_node.lhs.payload), .usize_ty);
                }
                if (range_node.rhs.tag == .node) {
                    _ = try self.checkExpr(NodeIndex.fromInt(range_node.rhs.payload), .usize_ty);
                }
                _ = self.recordNodeType(idx_id, .usize_ty);
            } else if (!is_range_index and idx_base == .untyped_int_ty) {
                _ = try self.checkExpr(idx_id, .usize_ty);
            } else if (!idx_base.isError() and idx_base != .untyped_int_ty and
                !idx_base.isIntegerPrimitive() and !self.isIntegerBoundedVar(idx_base))
            {
                try self.emitTypeMismatch(self.getAstNodeSpan(idx_id), .usize_ty, idx_ty);
            }
        }
        if (base_ty.isError()) return .err_ty;

        if (is_range_index) {
            if (base_ty == .str_ty) return .str_ty;
            if (union_caps.has_len_and_empty and !union_caps.shared_elem_ty.isError()) {
                return base_ty;
            }
            switch (base_node.tag) {
                .slice_ty, .array_ty => {
                    const elem_ty = TypeId.fromInt(base_node.lhs);
                    const slice_ty = try self.pool.internSlice(elem_ty, false);
                    return self.pool.internRef(slice_ty, is_mut_place);
                },
                .soa_slice_ty, .soa_array_ty => {
                    const elem_ty = TypeId.fromInt(base_node.lhs);
                    const slice_ty = try self.pool.internSlice(elem_ty, true);
                    return self.pool.internRef(slice_ty, is_mut_place);
                },
                .struct_ty => {
                    const s_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(base_node.rhs)).*;
                    if (std.mem.eql(u8, s_sym.name_text, "String")) return .str_ty;
                    const gen_args = self.pool.getGenericTypeArgs(base_ty);
                    if (gen_args.len >= 1) {
                        const elem_ty = TypeId.fromInt(gen_args[0]);
                        const slice_ty = try self.pool.internSlice(
                            elem_ty,
                            std.mem.eql(u8, s_sym.name_text, "SoaVec"),
                        );
                        return self.pool.internRef(slice_ty, is_mut_place);
                    }
                    return .err_ty;
                },
                else => return .err_ty,
            }
        }

        if (base_ty == .str_ty) return .u8_ty;
        if (!union_caps.shared_elem_ty.isError()) return union_caps.shared_elem_ty;
        return switch (base_node.tag) {
            .slice_ty, .soa_slice_ty, .array_ty, .soa_array_ty => TypeId.fromInt(base_node.lhs),
            .raw_ptr_ty => blk_raw_idx: {
                const pointee_ty = TypeId.fromInt(base_node.lhs);
                if (self.pool.unwrapUnderlyingType(pointee_ty) == .opaque_ty) {
                    try self.emitDiagnosticSimple(
                        .e0425_invalid_opaque_type_usage,
                        self.getAstNodeSpan(expr_id),
                        "cannot index raw pointer to unsized `opaque` type; cast to a typed pointer first",
                        "`*opaque` / `*mut opaque` cannot be indexed",
                    );
                    break :blk_raw_idx .err_ty;
                }
                if (self.unsafe_depth == 0 and self.pure_comptime_depth == 0) {
                    const idx_cst = self.ast_arena.getCstOrigin(expr_id);
                    const has_cst_err = !idx_cst.isNone() and
                        idx_cst.asInt() < self.cst_arena.countNodes() and
                        self.cst_arena.getNode(idx_cst).flags.has_error;
                    if (!has_cst_err) {
                        try self.emitDiagnosticSimple(
                            .e0324_package_capability_violation,
                            self.getAstNodeSpan(expr_id),
                            "indexing a raw pointer requires an `unsafe` block or `unsafe fn`",
                            "raw pointer indexing outside `unsafe` context",
                        );
                    }
                }
                break :blk_raw_idx pointee_ty;
            },
            .struct_ty => blk_elem: {
                const s_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(base_node.rhs)).*;
                if (std.mem.eql(u8, s_sym.name_text, "String")) break :blk_elem .u8_ty;
                const gen_args = self.pool.getGenericTypeArgs(base_ty);
                if (gen_args.len >= 1) break :blk_elem TypeId.fromInt(gen_args[0]);
                break :blk_elem .err_ty;
            },
            else => .err_ty,
        };
    }

    /// Synthesizes `lhs |> rhs` pipeline calls (`lhs |> f`, `lhs |> f(a_1, …)`, and `lhs |> obj.m(a_1, …)`).
    fn synthPipeExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node or ast_node.rhs.tag != .node) return .err_ty;
        const lhs_id = NodeIndex.fromInt(ast_node.lhs.payload);
        const rhs_id = NodeIndex.fromInt(ast_node.rhs.payload);
        const rhs_node = self.ast_arena.getNode(rhs_id);

        if (rhs_node.tag == .method_call) {
            if (rhs_node.lhs.tag != .node) return .err_ty;
            const recv_id = NodeIndex.fromInt(rhs_node.lhs.payload);
            const raw_items = self.getNodeExtraSlice(rhs_id, true);
            if (raw_items.len == 0) return .err_ty;
            const member_tok = TokenIndex.fromInt(raw_items[0]);
            const member_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, member_tok);
            const member_span = self.token_buffer.getTokenSpan(self.file_id, member_tok);

            var type_arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
            defer type_arg_nodes.deinit(self.allocator);
            var arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
            defer arg_nodes.deinit(self.allocator);
            try arg_nodes.append(self.allocator, lhs_id);
            for (raw_items[1..]) |raw_item| {
                const item_id = NodeIndex.fromInt(raw_item);
                if (item_id.asInt() >= self.ast_arena.countNodes()) continue;
                if (isTypeAstTag(self.ast_arena.getNode(item_id).tag)) {
                    try type_arg_nodes.append(self.allocator, item_id);
                } else {
                    try arg_nodes.append(self.allocator, item_id);
                }
            }

            // Support static `lhs |> mod.func(…)` and `lhs |> Type.assoc_fn[T](…)` under Unified `.`:
            switch (try self.classifyDotReceiver(recv_id)) {
                .poisoned => {
                    for (type_arg_nodes.items) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                    for (arg_nodes.items) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                    return .err_ty;
                },
                .module_ns => |mod_scope| {
                    if (!mod_scope.isNone()) {
                        const fn_sym_id = try self.interner.intern(member_name);
                        switch (self.sym_table.lookupInTargetScope(
                            mod_scope,
                            self.current_scope,
                            fn_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        )) {
                            .found => |fn_idx| {
                                self.sym_table.markSymbolUsed(fn_idx);
                                self.recordNodeSymbol(rhs_id, fn_idx);
                                self.recordNodeSymbol(expr_id, fn_idx);
                                try self.resolveFnSignatureSymbol(fn_idx);
                                const ret_ty = try self.checkCallArgumentsAgainstFn(
                                    expr_id,
                                    self.sym_table.getSymbol(fn_idx).type_id,
                                    fn_idx,
                                    null,
                                    type_arg_nodes.items,
                                    arg_nodes.items,
                                );
                                _ = self.recordNodeType(rhs_id, ret_ty);
                                return ret_ty;
                            },
                            .private_error => |priv_idx| {
                                if (self.diagnostic_sink) |sink| {
                                    try symbol_resolver.emitPrivateAccessDiagnostic(
                                        sink,
                                        self.sym_table.getSymbol(priv_idx),
                                        member_span,
                                    );
                                }
                                return .err_ty;
                            },
                            .not_found => {},
                        }
                    }
                },
                .type_ns => |static_ty| {
                    const unwrapped_static = self.pool.unwrapUnderlyingType(static_ty);
                    const static_node = self.pool.getNode(unwrapped_static);
                    if (static_node.tag == .struct_ty or static_node.tag == .enum_ty or
                        static_node.tag == .union_ty or static_node.tag == .trait_ty)
                    {
                        const owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(static_node.rhs)).target_scope;
                        if (!owner_scope.isNone()) {
                            const fn_sym_id = try self.interner.intern(member_name);
                            if (self.sym_table.lookupInTargetScope(
                                owner_scope,
                                self.current_scope,
                                fn_sym_id,
                                NamespaceMask.VALUE_ONLY,
                            ) == .found) {
                                const m_idx = self.sym_table.lookupInScopeDirect(
                                    owner_scope,
                                    fn_sym_id,
                                    NamespaceMask.VALUE_ONLY,
                                );
                                self.sym_table.markSymbolUsed(m_idx);
                                self.recordNodeSymbol(rhs_id, m_idx);
                                self.recordNodeSymbol(expr_id, m_idx);
                                try self.resolveFnSignatureSymbol(m_idx);
                                const subst_fn_ty = try self.substituteNominalMemberType(
                                    unwrapped_static,
                                    self.sym_table.getSymbol(m_idx).type_id,
                                );
                                const ret_ty = try self.checkCallArgumentsAgainstFn(
                                    expr_id,
                                    subst_fn_ty,
                                    m_idx,
                                    null,
                                    type_arg_nodes.items,
                                    arg_nodes.items,
                                );
                                _ = self.recordNodeType(rhs_id, ret_ty);
                                return ret_ty;
                            }
                        }
                    }
                },
                .value_expr => {},
            }

            const recv_ty = try self.synthExpr(recv_id);
            if (recv_ty.isError()) {
                for (type_arg_nodes.items) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                for (arg_nodes.items) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                return .err_ty;
            }

            const unwrapped_recv = self.unwrapRefType(recv_ty);
            const recv_node = self.pool.getNode(unwrapped_recv);
            var lookup_owner_scope: ScopeId = .none;
            if (recv_node.tag == .struct_ty or recv_node.tag == .enum_ty or
                recv_node.tag == .union_ty or recv_node.tag == .trait_ty)
            {
                lookup_owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(recv_node.rhs)).target_scope;
            } else if (recv_node.tag == .type_param or recv_node.tag == .bind_once_group_var or
                recv_node.tag == .bind_many_any_var)
            {
                const bound_node = self.pool.getNode(TypeId.fromInt(recv_node.lhs));
                if (bound_node.tag == .trait_ty) {
                    lookup_owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(bound_node.rhs)).target_scope;
                }
            }
            if (!lookup_owner_scope.isNone()) {
                const method_sym_id = try self.interner.intern(member_name);
                switch (self.sym_table.lookupInTargetScope(
                    lookup_owner_scope,
                    self.current_scope,
                    method_sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => |m_idx| {
                        self.sym_table.markSymbolUsed(m_idx);
                        self.recordNodeSymbol(rhs_id, m_idx);
                        self.recordNodeSymbol(expr_id, m_idx);
                        try self.resolveFnSignatureSymbol(m_idx);
                        const m_ty = self.sym_table.getSymbol(m_idx).type_id;
                        const ret_ty = try self.checkCallArgumentsAgainstFn(
                            expr_id,
                            m_ty,
                            m_idx,
                            recv_id,
                            type_arg_nodes.items,
                            arg_nodes.items,
                        );
                        _ = self.recordNodeType(rhs_id, ret_ty);
                        return ret_ty;
                    },
                    .private_error => |priv_idx| {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitPrivateAccessDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                member_span,
                            );
                        }
                        return .err_ty;
                    },
                    .not_found => {},
                }
            }
            for (type_arg_nodes.items) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
            for (arg_nodes.items) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            return .err_ty;
        }

        var callee_id: NodeIndex = rhs_id;
        var type_arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer type_arg_nodes.deinit(self.allocator);
        var arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer arg_nodes.deinit(self.allocator);
        try arg_nodes.append(self.allocator, lhs_id);

        if (rhs_node.tag == .call_expr or rhs_node.tag == .generic_call or rhs_node.tag == .incomplete_call) {
            if (rhs_node.lhs.tag == .node) callee_id = NodeIndex.fromInt(rhs_node.lhs.payload);
            const raw_items = self.getNodeExtraSlice(rhs_id, true);
            for (raw_items) |raw_item| {
                const item_id = NodeIndex.fromInt(raw_item);
                if (item_id.asInt() >= self.ast_arena.countNodes()) continue;
                if (isTypeAstTag(self.ast_arena.getNode(item_id).tag)) {
                    try type_arg_nodes.append(self.allocator, item_id);
                } else {
                    try arg_nodes.append(self.allocator, item_id);
                }
            }
        }
        if (self.ast_arena.getNode(callee_id).tag == .generic_call and
            self.ast_arena.getNode(callee_id).lhs.tag == .node)
        {
            const inner_gen = callee_id;
            callee_id = NodeIndex.fromInt(self.ast_arena.getNode(inner_gen).lhs.payload);
            for (self.getNodeExtraSlice(inner_gen, true)) |raw_item| {
                const item_id = NodeIndex.fromInt(raw_item);
                if (item_id.asInt() < self.ast_arena.countNodes()) {
                    try type_arg_nodes.append(self.allocator, item_id);
                }
            }
        }

        const callee_node = self.ast_arena.getNode(callee_id);
        if (callee_node.tag == .ident_expr and !callee_node.main_token.isNone() and
            self.token_buffer.getToken(callee_node.main_token).kind == .at)
        {
            return self.synthIntrinsicCall(expr_id, callee_id, type_arg_nodes.items, arg_nodes.items);
        }
        if (callee_node.tag == .ident_expr) {
            const name_str = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                callee_node.main_token,
            );
            if (self.interner.lookup(name_str)) |sym_id| {
                switch (self.sym_table.lookupLexical(self.current_scope, sym_id, NamespaceMask.VALUE_ONLY)) {
                    .found => |found_idx| {
                        const found_sym = self.sym_table.getSymbol(found_idx).*;
                        if (found_sym.flags.is_overload) {
                            if (self.sym_table.getOverloadSet(found_sym.scope_id, sym_id)) |ov_set| {
                                if (ov_set.members.items.len > 1) {
                                    return self.resolveAndCheckOverloadCall(
                                        expr_id,
                                        ov_set.members.items,
                                        type_arg_nodes.items,
                                        arg_nodes.items,
                                    );
                                }
                            }
                        }
                    },
                    else => {},
                }
            }
        }

        const callee_ty = try self.synthExpr(callee_id);
        const callee_sym_idx = if (callee_id.asInt() < self.node_symbols.len)
            self.node_symbols[callee_id.asInt()]
        else
            SymbolIndex.none;
        if (!callee_sym_idx.isNone()) {
            self.recordNodeSymbol(expr_id, callee_sym_idx);
        }
        if (callee_ty.isError()) {
            for (type_arg_nodes.items) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
            for (arg_nodes.items) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            return .err_ty;
        }
        return self.checkCallArgumentsAgainstFn(
            expr_id,
            callee_ty,
            callee_sym_idx,
            null,
            type_arg_nodes.items,
            arg_nodes.items,
        );
    }

    /// Synthesizes a function, intrinsic, or generic function call (`call_expr`, `generic_call`, `incomplete_call`).
    fn synthCallExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        var callee_id = NodeIndex.fromInt(ast_node.lhs.payload);

        // Partition extra slice into explicit `[TypeArgs]` and `(CallArgs)`, unwrapping nested `.generic_call` callees:
        const raw_items = self.getNodeExtraSlice(expr_id, true);
        var type_arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer type_arg_nodes.deinit(self.allocator);
        var arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer arg_nodes.deinit(self.allocator);
        if (ast_node.tag != .generic_call and
            self.ast_arena.getNode(callee_id).tag == .generic_call and
            self.ast_arena.getNode(callee_id).lhs.tag == .node)
        {
            const inner_gen = callee_id;
            callee_id = NodeIndex.fromInt(self.ast_arena.getNode(inner_gen).lhs.payload);
            for (self.getNodeExtraSlice(inner_gen, true)) |gen_item| {
                const gen_node_id = NodeIndex.fromInt(gen_item);
                if (gen_node_id.asInt() < self.ast_arena.countNodes()) {
                    try type_arg_nodes.append(self.allocator, gen_node_id);
                }
            }
        }
        for (raw_items) |raw_item| {
            const item_id = NodeIndex.fromInt(raw_item);
            if (item_id.asInt() >= self.ast_arena.countNodes()) continue;
            if (isTypeAstTag(self.ast_arena.getNode(item_id).tag)) {
                try type_arg_nodes.append(self.allocator, item_id);
                continue;
            }
            try arg_nodes.append(self.allocator, item_id);
        }
        if (raw_items.len == 0 and ast_node.rhs.tag == .node) {
            const single_rhs = NodeIndex.fromInt(ast_node.rhs.payload);
            if (single_rhs.asInt() < self.ast_arena.countNodes()) {
                if (isTypeAstTag(self.ast_arena.getNode(single_rhs).tag)) {
                    try type_arg_nodes.append(self.allocator, single_rhs);
                } else {
                    try arg_nodes.append(self.allocator, single_rhs);
                }
            }
        }
        const explicit_type_args = type_arg_nodes.items;
        const args = arg_nodes.items;
        const callee_node = self.ast_arena.getNode(callee_id);

        // [1] Dispatch `@intrinsic` calls (`DR-05` §3.3):
        if (callee_node.tag == .ident_expr and !callee_node.main_token.isNone() and
            self.token_buffer.getToken(callee_node.main_token).kind == .at)
        {
            return self.synthIntrinsicCall(expr_id, callee_id, explicit_type_args, args);
        }

        // [1b] Dispatch `@constructor` calls on nominal `TypeName(args)` / `TypeName[T](args)` (`SE-22`):
        if (callee_node.tag == .ident_expr or callee_node.tag == .field_access or callee_node.tag == .path_expr) {
            if ((try self.classifyDotReceiver(callee_id)) == .type_ns) {
                const raw_ctor_ty = switch (try self.classifyDotReceiver(callee_id)) {
                    .type_ns => |ty| ty,
                    else => .err_ty,
                };
                const unwrapped_ctor_ty = self.pool.unwrapUnderlyingType(raw_ctor_ty);
                const ctor_node = self.pool.getNode(unwrapped_ctor_ty);
                if (ctor_node.tag == .struct_ty or ctor_node.tag == .enum_ty or ctor_node.tag == .union_ty) {
                    const owner_sym_idx = SymbolIndex.fromInt(ctor_node.rhs);
                    const owner_sym = self.sym_table.getSymbol(owner_sym_idx).*;
                    if (!owner_sym.target_scope.isNone()) {
                        var ctor_candidates: std.ArrayListUnmanaged(SymbolIndex) = .empty;
                        defer ctor_candidates.deinit(self.allocator);
                        var first_private_ctor: SymbolIndex = .none;
                        for (self.sym_table.getScopeMembers(owner_sym.target_scope)) |mem_idx| {
                            if (self.isSymbolCfgDisabled(mem_idx)) continue;
                            const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                            if (mem_sym.kind != .fn_sym or !mem_sym.extra_flags.is_constructor) continue;
                            switch (self.sym_table.lookupInTargetScope(
                                owner_sym.target_scope,
                                self.current_scope,
                                mem_sym.name,
                                NamespaceMask.VALUE_ONLY,
                            )) {
                                .found => try ctor_candidates.append(self.allocator, mem_idx),
                                .private_error => |priv_idx| {
                                    if (first_private_ctor.isNone()) first_private_ctor = priv_idx;
                                },
                                .not_found => {},
                            }
                        }
                        if (ctor_candidates.items.len > 0) {
                            var owner_tp_count: usize = 0;
                            for (self.sym_table.getScopeMembers(owner_sym.target_scope)) |mem_idx| {
                                if (self.sym_table.getSymbol(mem_idx).kind == .type_param_sym) owner_tp_count += 1;
                            }
                            var inst_owner_ty = unwrapped_ctor_ty;
                            var remaining_type_args: []const NodeIndex = explicit_type_args;
                            if (owner_tp_count > 0 and explicit_type_args.len > 0) {
                                const take_n = @min(owner_tp_count, explicit_type_args.len);
                                var owner_args: std.ArrayListUnmanaged(TypeId) = .empty;
                                defer owner_args.deinit(self.allocator);
                                for (explicit_type_args[0..take_n]) |t_node| {
                                    try owner_args.append(self.allocator, try self.resolveTypeAst(t_node));
                                }
                                try self.appendResolvedTrailingGenericDefaults(
                                    owner_sym_idx,
                                    &owner_args,
                                    self.getAstNodeSpan(expr_id),
                                );
                                inst_owner_ty = try self.internNominalWithResolvedArgs(unwrapped_ctor_ty, owner_args.items);
                                remaining_type_args = explicit_type_args[take_n..];
                            }
                            if (ctor_candidates.items.len > 1) {
                                const ov_ret = try self.resolveAndCheckOverloadCall(
                                    expr_id,
                                    ctor_candidates.items,
                                    remaining_type_args,
                                    args,
                                );
                                if (expr_id.asInt() < self.node_symbols.len and !self.node_symbols[expr_id.asInt()].isNone()) {
                                    self.recordNodeSymbol(callee_id, self.node_symbols[expr_id.asInt()]);
                                }
                                return self.substituteNominalMemberType(inst_owner_ty, ov_ret);
                            }
                            const ctor_idx = ctor_candidates.items[0];
                            self.sym_table.markSymbolUsed(ctor_idx);
                            self.recordNodeSymbol(callee_id, ctor_idx);
                            self.recordNodeSymbol(expr_id, ctor_idx);
                            try self.checkComptimeSymbolAccess(expr_id, ctor_idx);
                            try self.resolveFnSignatureSymbol(ctor_idx);
                            const subst_ctor_ty = try self.substituteNominalMemberType(
                                inst_owner_ty,
                                self.sym_table.getSymbol(ctor_idx).type_id,
                            );
                            _ = self.recordNodeType(callee_id, subst_ctor_ty);
                            return self.checkCallArgumentsAgainstFn(
                                expr_id,
                                subst_ctor_ty,
                                ctor_idx,
                                null,
                                remaining_type_args,
                                args,
                            );
                        } else if (!first_private_ctor.isNone()) {
                            if (self.diagnostic_sink) |sink| {
                                try symbol_resolver.emitPrivateAccessDiagnostic(
                                    sink,
                                    self.sym_table.getSymbol(first_private_ctor),
                                    self.getAstNodeSpan(callee_id),
                                );
                            }
                            for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                            for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                            return .err_ty;
                        }
                    }
                }
            }
        }

        // [2] Check if `callee_id` resolves to an `@overload` set or built-in async entry point:
        if (callee_node.tag == .ident_expr) {
            const name_str = symbol_resolver.extractTokenSlice(
                self.source,
                self.token_buffer,
                callee_node.main_token,
            );
            if (self.interner.lookup(name_str)) |sym_id| {
                switch (self.sym_table.lookupLexical(
                    self.current_scope,
                    sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => |found_idx| {
                        const found_sym = self.sym_table.getSymbol(found_idx).*;
                        if (found_sym.flags.is_overload) {
                            if (self.sym_table.getOverloadSet(found_sym.scope_id, sym_id)) |ov_set| {
                                if (ov_set.members.items.len > 1) {
                                    return self.resolveAndCheckOverloadCall(
                                        expr_id,
                                        ov_set.members.items,
                                        explicit_type_args,
                                        args,
                                    );
                                }
                            }
                        }
                        if (try self.tryCheckStructuredAsyncEntryCall(
                            expr_id,
                            callee_id,
                            found_idx,
                            name_str,
                            explicit_type_args,
                            args,
                        )) |handled_async_ty| {
                            return handled_async_ty;
                        }
                    },
                    else => {},
                }
            }
        }

        const callee_ty = try self.synthExpr(callee_id);
        const callee_sym_idx = if (callee_id.asInt() < self.node_symbols.len)
            self.node_symbols[callee_id.asInt()]
        else
            SymbolIndex.none;
        if (!callee_sym_idx.isNone()) {
            self.recordNodeSymbol(expr_id, callee_sym_idx);
            const resolved_sym = self.sym_table.getSymbol(callee_sym_idx).*;
            if (resolved_sym.flags.is_overload) {
                if (self.sym_table.getOverloadSet(resolved_sym.scope_id, resolved_sym.name)) |ov_set| {
                    if (ov_set.members.items.len > 1) {
                        return self.resolveAndCheckOverloadCall(
                            expr_id,
                            ov_set.members.items,
                            explicit_type_args,
                            args,
                        );
                    }
                }
            }
        }
        if (callee_ty.isError()) {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            for (explicit_type_args) |type_node_id| {
                _ = try self.resolveTypeAst(type_node_id);
            }
            for (args) |arg_id| {
                _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            }
            return .err_ty;
        }

        return self.checkCallArgumentsAgainstFn(
            expr_id,
            callee_ty,
            callee_sym_idx,
            null,
            explicit_type_args,
            args,
        );
    }

    /// Validates that `target_ty` (and its non-`Option` transitive fields/elements) can be safely zero-initialized via `@default_init[T]()`.
    fn validateDefaultInitType(
        self: *TypeChecker,
        target_ty: TypeId,
        span: Span,
        depth: u32,
    ) anyerror!bool {
        if (target_ty.isError() or depth >= MAX_TYPE_DEPTH) return true;
        if (target_ty == .opaque_ty or self.pool.unwrapUnderlyingType(target_ty) == .opaque_ty) {
            try self.emitDiagnosticSimple(
                .e0425_invalid_opaque_type_usage,
                span,
                "cannot instantiate unsized `opaque` type with `@default_init`",
                "`opaque` cannot be instantiated by value",
            );
            return false;
        }

        const ty_node = self.pool.getNode(target_ty);
        // `Option[T]` (`T?`) default-initializes to `.None` without synthesizing an inner `T`:
        if (ty_node.tag == .optional_ty) return true;

        if (self.pool.getFlags(target_ty).is_secret) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                span,
                "cannot synthesize `@secret` value via `@default_init`",
                "`@secret` types require explicit construction",
            );
            return false;
        }
        if (classifyOwnershipTier(self.pool, self.sym_table, target_ty) == .linear_tier) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                span,
                "cannot synthesize `@linear` resource via `@default_init`",
                "`@linear` obligation types cannot be zero-initialized",
            );
            return false;
        }

        if (self.pool.getRefinementBounds(target_ty)) |bounds| {
            if (0 < bounds.min_val or 0 > bounds.max_val) {
                try self.emitDiagnosticSimple(
                    .e0406_range_refinement_violation,
                    span,
                    "cannot zero-initialize range-refined type via `@default_init` because `0` is outside its valid range",
                    "`0` violates range refinement bounds",
                );
                return false;
            }
            return self.validateDefaultInitType(self.pool.unwrapRefinementBase(target_ty), span, depth + 1);
        }

        if (target_ty == .source_loc_ty or
            target_ty == .fmt_args_ty or
            target_ty == .fmt_spec_ty or
            target_ty == .never_ty or
            target_ty == .bencher_ty or
            self.pool.isTaskGroupType(target_ty) or
            self.pool.isTaskHandleType(target_ty))
        {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                span,
                "cannot zero-initialize compiler-managed runtime handle or `never` type via `@default_init`",
                "type has non-zeroable safety invariants",
            );
            return false;
        }

        switch (ty_node.tag) {
            .type_param, .bind_once_group_var, .bind_many_any_var, .raw_ptr_ty => return true,
            .ref_ty,
            .mut_ref_ty,
            .slice_ty,
            .soa_slice_ty,
            .fn_ty,
            .closure_ty,
            .trait_ty,
            .dyn_trait_ty,
            => {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    span,
                    "cannot zero-initialize safe reference, callable, slice, or trait object via `@default_init`",
                    "type has non-zeroable safety invariants",
                );
                return false;
            },
            .distinct_ty => {
                return self.validateDefaultInitType(TypeId.fromInt(ty_node.lhs), span, depth + 1);
            },
            .tuple_ty => {
                for (self.pool.getTupleElements(target_ty)) |raw_elem| {
                    if (!(try self.validateDefaultInitType(TypeId.fromInt(raw_elem), span, depth + 1))) {
                        return false;
                    }
                }
                return true;
            },
            .array_ty, .soa_array_ty => {
                if ((ty_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0 and ty_node.rhs == 0) return true;
                return self.validateDefaultInitType(TypeId.fromInt(ty_node.lhs), span, depth + 1);
            },
            .struct_ty => {
                const struct_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(ty_node.rhs)).*;
                if (!struct_sym.target_scope.isNone()) {
                    for (self.sym_table.getScopeMembers(struct_sym.target_scope)) |mem_idx| {
                        const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind != .field_sym) continue;
                        const subst_field_ty = try self.substituteNominalMemberType(target_ty, mem_sym.type_id);
                        if (!(try self.validateDefaultInitType(subst_field_ty, span, depth + 1))) {
                            return false;
                        }
                    }
                }
                return true;
            },
            else => return true,
        }
    }

    /// Type-checks all 12 Phase 5 `@intrinsic` calls (`DR-05` §3.3).
    fn synthIntrinsicCall(
        self: *TypeChecker,
        call_id: NodeIndex,
        callee_id: NodeIndex,
        type_arg_nodes: []const NodeIndex,
        val_args: []const NodeIndex,
    ) !TypeId {
        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus;

        const callee_node = self.ast_arena.getNode(callee_id);
        const intr_tok = if (callee_node.lhs.tag == .token)
            TokenIndex.fromInt(callee_node.lhs.payload)
        else
            callee_node.main_token;
        const intr_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, intr_tok);

        const type_args = try self.allocator.alloc(TypeId, type_arg_nodes.len);
        defer if (type_args.len > 0) self.allocator.free(type_args);
        for (type_arg_nodes, 0..) |type_node_id, i| {
            type_args[i] = try self.resolveTypeAst(type_node_id);
        }
        if (type_arg_nodes.len > 0) {
            try self.recordCallInstantiation(call_id, type_args);
        }

        const intr_kind = INTRINSIC_NAME_MAP.get(intr_name) orelse {
            var msg_buf: [160]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &msg_buf,
                "unknown compiler intrinsic `@{s}`",
                .{intr_name},
            ) catch "unknown compiler intrinsic";
            try self.emitDiagnosticSimple(
                .e0403_unresolved_symbol,
                self.getAstNodeSpan(callee_id),
                msg,
                "unrecognized `@intrinsic` name",
            );
            for (val_args) |arg_id| {
                _ = try self.synthExpr(arg_id);
            }
            return .err_ty;
        };

        switch (intr_kind) {
            .size_of, .align_of => {
                if (type_arg_nodes.len != 1 or val_args.len != 0) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "intrinsic expects exactly 1 type argument `[T]` and 0 value arguments `()`",
                        "expected `@size_of[T]()` / `@align_of[T]()`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                } else if (self.pool.unwrapUnderlyingType(type_args[0]) == .opaque_ty) {
                    try self.emitDiagnosticSimple(
                        .e0425_invalid_opaque_type_usage,
                        self.getAstNodeSpan(type_arg_nodes[0]),
                        "cannot compute `@size_of` or `@align_of` of unsized `opaque` type",
                        "`opaque` has no known size or alignment",
                    );
                }
                return self.recordNodeType(callee_id, .usize_ty);
            },
            .type_name => {
                if (type_arg_nodes.len != 1 or val_args.len != 0) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@type_name` expects 1 type argument `[T]` and 0 value arguments `()`",
                        "expected `@type_name[T]()`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                }
                return self.recordNodeType(callee_id, .str_ty);
            },
            .default_init => {
                if (type_arg_nodes.len != 1 or val_args.len != 0) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@default_init` expects 1 type argument `[T]` and 0 value arguments `()`",
                        "expected `@default_init[T]()`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .err_ty;
                }
                if (!(try self.validateDefaultInitType(type_args[0], self.getAstNodeSpan(type_arg_nodes[0]), 0))) {
                    return .err_ty;
                }
                return self.recordNodeType(callee_id, type_args[0]);
            },
            .c_import => {
                if (type_arg_nodes.len != 0 or val_args.len != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@c_import` expects 0 type arguments and 1 `comptime` `str` header path argument",
                        "expected `@c_import(\"header.h\")`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .err_ty;
                }
                const header_arg_id = self.unwrapCallArgExpr(val_args[0]);
                const prev_pure = self.pure_comptime_depth;
                const prev_bound = self.comptime_boundary_scope_depth;
                if (prev_pure == 0) {
                    self.comptime_boundary_scope_depth = if (self.current_scope.isNone())
                        0
                    else
                        self.sym_table.scope_arena.getScope(self.current_scope).depth;
                }
                self.pure_comptime_depth = prev_pure + 1;
                {
                    defer {
                        self.pure_comptime_depth = prev_pure;
                        self.comptime_boundary_scope_depth = prev_bound;
                    }
                    _ = try self.checkExpr(header_arg_id, .str_ty);
                }

                var resolved_raw_lit: ?[]const u8 = null;
                const direct_node = self.ast_arena.getNode(header_arg_id);
                if (direct_node.tag == .string_lit) {
                    resolved_raw_lit = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        direct_node.main_token,
                    );
                } else if ((direct_node.tag == .ident_expr or direct_node.tag == .path_expr) and
                    header_arg_id.asInt() < self.node_symbols.len)
                {
                    const c_sym_idx = self.unwrapAliasSymbolIdx(self.node_symbols[header_arg_id.asInt()]);
                    if (!c_sym_idx.isNone() and self.sym_table.getSymbol(c_sym_idx).kind == .const_sym) {
                        const c_sym = self.sym_table.getSymbol(c_sym_idx).*;
                        const c_ast = c_sym.ast_node;
                        if (c_sym.decl_span.file_id == self.file_id and
                            !c_ast.isNone() and c_ast.asInt() < self.ast_arena.countNodes())
                        {
                            const c_decl_node = self.ast_arena.getNode(c_ast);
                            if (c_decl_node.rhs.tag == .node and
                                c_decl_node.rhs.payload < self.ast_arena.countNodes())
                            {
                                const rhs_node = self.ast_arena.getNode(NodeIndex.fromInt(c_decl_node.rhs.payload));
                                if (rhs_node.tag == .string_lit) {
                                    resolved_raw_lit = symbol_resolver.extractTokenSlice(
                                        self.source,
                                        self.token_buffer,
                                        rhs_node.main_token,
                                    );
                                }
                            }
                        } else if (c_sym.decl_span.file_id != self.file_id and
                            !c_sym.decl_span.file_id.isNone())
                        {
                            if (self.db) |compiler_db| {
                                if (try compiler_db.getExternalFileSyntaxView(c_sym.decl_span.file_id)) |ext_view| {
                                    if (!c_ast.isNone() and c_ast.asInt() < ext_view.ast_arena.countNodes()) {
                                        const ext_decl = ext_view.ast_arena.getNode(c_ast);
                                        if (ext_decl.rhs.tag == .node and
                                            ext_decl.rhs.payload < ext_view.ast_arena.countNodes())
                                        {
                                            const ext_rhs = ext_view.ast_arena.getNode(
                                                NodeIndex.fromInt(ext_decl.rhs.payload),
                                            );
                                            if (ext_rhs.tag == .string_lit) {
                                                resolved_raw_lit = symbol_resolver.extractTokenSlice(
                                                    ext_view.source,
                                                    ext_view.tokens,
                                                    ext_rhs.main_token,
                                                );
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                const raw_lit = resolved_raw_lit orelse {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(header_arg_id),
                        "`@c_import` header path must be a compile-time string literal",
                        "expected string literal path here",
                    );
                    return .err_ty;
                };
                const cooked_path = lexer.cookStringLiteral(self.allocator, raw_lit) catch null;
                defer if (cooked_path) |bytes| self.allocator.free(bytes);
                const header_path = cooked_path orelse
                    (if (raw_lit.len >= 2) raw_lit[1 .. raw_lit.len - 1] else "");

                if (self.sym_table.getFilePackageId(self.file_id).asInt() >= 2 and
                    !isValidSandboxedCImportRelPath(header_path))
                {
                    try self.emitDiagnosticSimple(
                        .e0326_embed_path_escape,
                        self.getAstNodeSpan(header_arg_id),
                        "external package `@c_import` header path cannot be absolute or escape its `.cxtree` root",
                        "header path escapes package sandbox root",
                    );
                    return .err_ty;
                }

                const pre_diag_len = if (self.diagnostic_sink) |sink| sink.diagnostics.items.len else 0;
                var mod_sym_idx: SymbolIndex = self.sym_table.c_import_modules.get(header_path) orelse .none;
                if (self.sym_table.c_import_loader) |loader_fn| {
                    const loaded_sym = try loader_fn(
                        self.sym_table,
                        self.interner,
                        self.file_id,
                        header_path,
                        self.diagnostic_sink,
                    );
