                            const msg = std.fmt.bufPrint(
                                &msg_buf,
                                "`@bit_cast` size mismatch: source `{s}` is {d} byte(s) whereas destination `{s}` is {d} byte(s)",
                                .{ src_str, src_layout.byte_size, dst_str, dst_layout.byte_size },
                            ) catch "`@bit_cast` source and destination types have different byte sizes";
                            try self.emitDiagnosticSimple(
                                .e0315_wire_layout_contract_violation,
                                self.getAstNodeSpan(call_id),
                                msg,
                                "source and destination byte sizes must match exactly",
                            );
                        }
                    }
                }
                return self.recordNodeType(callee_id, dst_ty);
            },
            .from_bytes, .view_bytes => {
                const is_view = (intr_kind == .view_bytes);
                if (type_arg_nodes.len != 1 or val_args.len != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "wire byte intrinsic expects 1 type argument `[T]` and 1 byte slice/array argument `(bytes)`",
                        "expected `@from_bytes[T](bytes)` or `@view_bytes[T](bytes)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .err_ty;
                }
                const target_ty = type_args[0];
                const raw_bytes_ty = try self.synthExpr(val_args[0]);
                const unwrapped_bytes = self.unwrapRefType(raw_bytes_ty);
                const bytes_node = self.pool.getNode(unwrapped_bytes);

                if (!raw_bytes_ty.isError()) {
                    const is_u8_slice = bytes_node.tag == .slice_ty and TypeId.fromInt(bytes_node.lhs) == .u8_ty;
                    const is_u8_array = bytes_node.tag == .array_ty and TypeId.fromInt(bytes_node.lhs) == .u8_ty;
                    if (!is_u8_slice and !is_u8_array) {
                        const expected_slice = try self.pool.internRef(
                            try self.pool.internSlice(.u8_ty, false),
                            false,
                        );
                        try self.emitTypeMismatch(self.getAstNodeSpan(val_args[0]), expected_slice, raw_bytes_ty);
                    } else if (is_u8_array and (bytes_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0 and
                        !target_ty.isError() and !self.pool.getFlags(target_ty).has_type_vars)
                    {
                        const target_size = self.computeTypeLayout(target_ty, self.target_layout).byte_size;
                        if (@as(u64, bytes_node.rhs) != target_size) {
                            var ty_buf: [64]u8 = undefined;
                            const ty_str = self.pool.formatType(target_ty, self.sym_table, &ty_buf);
                            var msg_buf: [240]u8 = undefined;
                            const msg = std.fmt.bufPrint(
                                &msg_buf,
                                "byte array length ({d} byte(s)) does not match `sizeof({s})` ({d} byte(s))",
                                .{ bytes_node.rhs, ty_str, target_size },
                            ) catch "fixed byte array length does not match target `FromBytes` byte size";
                            try self.emitDiagnosticSimple(
                                .e0315_wire_layout_contract_violation,
                                self.getAstNodeSpan(val_args[0]),
                                msg,
                                "wire transmutation requires exact byte size match",
                            );
                        }
                    }
                }

                if (!target_ty.isError() and !self.pool.getFlags(target_ty).has_type_vars) {
                    if (self.pool.explainFromBytesViolation(target_ty, self.sym_table, self.target_layout)) |viol| {
                        try self.emitWireLayoutViolation(
                            self.getAstNodeSpan(type_arg_nodes[0]),
                            target_ty,
                            "FromBytes",
                            viol,
                        );
                    }
                }
                const payload_ty = if (is_view) try self.pool.internRef(target_ty, false) else target_ty;
                const opt_res_ty = try self.pool.internOptional(payload_ty);
                return self.recordNodeType(callee_id, opt_res_ty);
            },
            .atomic_fence => {
                if (type_arg_nodes.len != 0 or val_args.len > 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@atomic_fence` expects 0 type arguments and 0 or 1 ordering argument",
                        "expected `@atomic_fence()` or `@atomic_fence(order)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .unit_ty;
                }
                if (val_args.len == 1) {
                    try self.checkAtomicOrderingArg(val_args[0]);
                }
                return self.recordNodeType(callee_id, .unit_ty);
            },
            .atomic_load => {
                if (type_arg_nodes.len > 1 or val_args.len == 0 or val_args.len > 2) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@atomic_load` expects `(ptr)` or `(ptr, order)`",
                        "expected `@atomic_load(&slot)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return if (type_arg_nodes.len == 1) type_args[0] else .err_ty;
                }
                const pointee_ty = try self.checkAtomicPtrArg(
                    val_args[0],
                    if (type_arg_nodes.len == 1) type_args[0] else null,
                    false,
                    false,
                );
                if (val_args.len == 2) {
                    try self.checkAtomicOrderingArg(val_args[1]);
                }
                return self.recordNodeType(callee_id, pointee_ty);
            },
            .atomic_store => {
                if (type_arg_nodes.len > 1 or val_args.len < 2 or val_args.len > 3) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@atomic_store` expects `(ptr, val)` or `(ptr, val, order)`",
                        "expected `@atomic_store(&mut slot, val)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .unit_ty;
                }
                const pointee_ty = try self.checkAtomicPtrArg(
                    val_args[0],
                    if (type_arg_nodes.len == 1) type_args[0] else null,
                    true,
                    false,
                );
                if (!pointee_ty.isError()) {
                    _ = try self.checkExpr(val_args[1], pointee_ty);
                } else {
                    _ = try self.synthExpr(val_args[1]);
                }
                if (val_args.len == 3) {
                    try self.checkAtomicOrderingArg(val_args[2]);
                }
                return self.recordNodeType(callee_id, .unit_ty);
            },
            .atomic_rmw_add, .atomic_rmw_sub, .atomic_rmw_xchg => {
                const requires_int = (intr_kind != .atomic_rmw_xchg);
                if (type_arg_nodes.len > 1 or val_args.len < 2 or val_args.len > 3) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "atomic RMW intrinsic expects `(ptr, operand)` or `(ptr, operand, order)`",
                        "expected `@atomic_rmw_*(ptr, val)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return if (type_arg_nodes.len == 1) type_args[0] else .err_ty;
                }
                const pointee_ty = try self.checkAtomicPtrArg(
                    val_args[0],
                    if (type_arg_nodes.len == 1) type_args[0] else null,
                    true,
                    requires_int,
                );
                if (!pointee_ty.isError()) {
                    _ = try self.checkExpr(val_args[1], pointee_ty);
                } else {
                    _ = try self.synthExpr(val_args[1]);
                }
                if (val_args.len == 3) {
                    try self.checkAtomicOrderingArg(val_args[2]);
                }
                return self.recordNodeType(callee_id, pointee_ty);
            },
            .atomic_cmpxchg => {
                if (type_arg_nodes.len > 1 or val_args.len < 3 or val_args.len > 6) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@atomic_cmpxchg` expects `(ptr, expected, desired[, succ_ord, fail_ord, is_weak])`",
                        "expected `@atomic_cmpxchg(&mut slot, expected, desired)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .err_ty;
                }
                const pointee_ty = try self.checkAtomicPtrArg(
                    val_args[0],
                    if (type_arg_nodes.len == 1) type_args[0] else null,
                    true,
                    false,
                );
                if (!pointee_ty.isError()) {
                    _ = try self.checkExpr(val_args[1], pointee_ty);
                    _ = try self.checkExpr(val_args[2], pointee_ty);
                } else {
                    _ = try self.synthExpr(val_args[1]);
                    _ = try self.synthExpr(val_args[2]);
                }
                if (val_args.len >= 4) try self.checkAtomicOrderingArg(val_args[3]);
                if (val_args.len >= 5) try self.checkAtomicOrderingArg(val_args[4]);
                if (val_args.len == 6) {
                    const weak_ty = try self.synthExpr(val_args[5]);
                    const weak_base = self.pool.unwrapRefinementBase(weak_ty);
                    if (weak_base == .untyped_int_ty) {
                        _ = try self.checkExpr(val_args[5], .u8_ty);
                    } else if (!weak_base.isError() and weak_base != .u8_ty and weak_base != .bool_ty) {
                        try self.emitTypeMismatch(self.getAstNodeSpan(val_args[5]), .u8_ty, weak_ty);
                    }
                }
                if (pointee_ty.isError()) return .err_ty;
                const pair_ty = try self.pool.internTuple(&.{ pointee_ty, .bool_ty });
                return self.recordNodeType(callee_id, pair_ty);
            },
            .simd_splat => {
                if (type_arg_nodes.len != 1 or val_args.len != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@simd_splat` expects 1 vector type argument `[Vec]` and 1 lane value `(val)`",
                        "expected `@simd_splat[[T; N]](val)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return if (type_arg_nodes.len >= 1) type_args[0] else .err_ty;
                }
                const vec_ty = type_args[0];
                const lane_ty = self.extractSimdVectorLaneType(vec_ty, self.getAstNodeSpan(type_arg_nodes[0])) catch .err_ty;
                if (!lane_ty.isError()) {
                    _ = try self.checkExpr(val_args[0], lane_ty);
                } else {
                    _ = try self.synthExpr(val_args[0]);
                }
                return self.recordNodeType(callee_id, vec_ty);
            },
            .simd_add, .simd_sub, .simd_mul => {
                if (type_arg_nodes.len > 1 or val_args.len != 2) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "SIMD arithmetic intrinsic expects 2 vector arguments `(lhs, rhs)`",
                        "expected `@simd_*(lhs, rhs)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return if (type_arg_nodes.len == 1) type_args[0] else .err_ty;
                }
                const lhs_ty = if (type_arg_nodes.len == 1 and !type_args[0].isError()) blk_vec: {
                    _ = try self.checkExpr(val_args[0], type_args[0]);
                    break :blk_vec type_args[0];
                } else self.materializeUntypedType(try self.synthExpr(val_args[0]));
                _ = try self.extractSimdVectorLaneType(lhs_ty, self.getAstNodeSpan(val_args[0]));
                if (!lhs_ty.isError()) {
                    _ = try self.checkExpr(val_args[1], lhs_ty);
                } else {
                    _ = try self.synthExpr(val_args[1]);
                }
                return self.recordNodeType(callee_id, lhs_ty);
            },
            .simd_reduce_add => {
                if (type_arg_nodes.len > 1 or val_args.len != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@simd_reduce_add` expects 1 vector argument `(vec)`",
                        "expected `@simd_reduce_add(vec)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .err_ty;
                }
                const vec_ty = if (type_arg_nodes.len == 1 and !type_args[0].isError()) blk_rvec: {
                    _ = try self.checkExpr(val_args[0], type_args[0]);
                    break :blk_rvec type_args[0];
                } else self.materializeUntypedType(try self.synthExpr(val_args[0]));
                const lane_ty = try self.extractSimdVectorLaneType(vec_ty, self.getAstNodeSpan(val_args[0]));
                return self.recordNodeType(callee_id, lane_ty);
            },
            .panic => {
                if (type_arg_nodes.len != 0 or val_args.len != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@panic` expects 0 type arguments and 1 `FmtArgs` / `str` message `(msg)`",
                        "expected `@panic(\"message\")`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .never_ty;
                }
                _ = try self.checkExpr(val_args[0], .fmt_args_ty);
                return self.recordNodeType(callee_id, .never_ty);
            },
            .trap => {
                if (type_arg_nodes.len != 0 or val_args.len != 0) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@trap` expects 0 type arguments and 0 value arguments `()`",
                        "expected `@trap()`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                }
                return self.recordNodeType(callee_id, .never_ty);
            },
            .poll_reload => {
                if (type_arg_nodes.len > 1 or val_args.len > 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@poll_reload` expects `()` or `(&mut app_state)`",
                        "expected `@poll_reload()` or `@poll_reload(&mut state)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .bool_ty;
                }
                if (val_args.len == 1) {
                    const state_arg_ty = if (type_arg_nodes.len == 1 and !type_args[0].isError()) blk_st: {
                        const exp_mut_ref = try self.pool.internRef(type_args[0], true);
                        _ = try self.checkExpr(val_args[0], exp_mut_ref);
                        break :blk_st exp_mut_ref;
                    } else try self.synthExpr(val_args[0]);
                    if (!state_arg_ty.isError() and !self.pool.getFlags(state_arg_ty).has_type_vars) {
                        const st_node = self.pool.getNode(self.pool.unwrapUnderlyingType(state_arg_ty));
                        if (st_node.tag != .mut_ref_ty) {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                self.getAstNodeSpan(val_args[0]),
                                "`@poll_reload` state argument must be an exclusive mutable reference `&mut S`",
                                "expected `&mut S` here",
                            );
                        }
                    }
                }
                return self.recordNodeType(callee_id, .bool_ty);
            },
            .sys_exit => {
                if (type_arg_nodes.len != 0 or val_args.len != 1) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@sys_exit` expects 0 type arguments and 1 `(code: i32)` argument",
                        "expected `@sys_exit(code)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .never_ty;
                }
                _ = try self.checkExpr(val_args[0], .i32_ty);
                return self.recordNodeType(callee_id, .never_ty);
            },
            .sys_write => {
                if (type_arg_nodes.len != 0 or val_args.len != 2) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        "`@sys_write` expects `(fd: i32, buf: [u8] | &[u8] | str)` returning `isize`",
                        "expected `@sys_write(fd, buf)`",
                    );
                    for (val_args) |arg_id| _ = try self.synthExpr(arg_id);
                    return .isize_ty;
                }
                _ = try self.checkExpr(val_args[0], .i32_ty);
                const buf_ty = try self.synthExpr(val_args[1]);
                if (!buf_ty.isError() and !self.pool.getFlags(buf_ty).has_type_vars) {
                    const unwrapped_buf = self.unwrapRefType(buf_ty);
                    const buf_node = self.pool.getNode(unwrapped_buf);
                    const is_valid_buf = unwrapped_buf == .str_ty or
                        (buf_node.tag == .slice_ty and TypeId.fromInt(buf_node.lhs) == .u8_ty) or
                        (buf_node.tag == .array_ty and TypeId.fromInt(buf_node.lhs) == .u8_ty and
                            (self.pool.getTag(buf_ty) == .ref_ty or self.pool.getTag(buf_ty) == .mut_ref_ty));
                    if (!is_valid_buf) {
                        const expected_slice = try self.pool.internSlice(.u8_ty, false);
                        try self.emitTypeMismatch(self.getAstNodeSpan(val_args[1]), expected_slice, buf_ty);
                    }
                }
                return self.recordNodeType(callee_id, .isize_ty);
            },
        }
    }

    /// Type-checks an optional memory ordering argument (`u8` / integer or fieldless `Ordering` enum).
    fn checkAtomicOrderingArg(self: *TypeChecker, arg_id: NodeIndex) !void {
        const ord_ty = try self.synthExpr(arg_id);
        if (ord_ty.isError() or self.pool.getFlags(ord_ty).has_type_vars) return;
        const unwrapped = self.pool.unwrapUnderlyingType(ord_ty);
        if (unwrapped == .untyped_int_ty) {
            _ = try self.checkExpr(arg_id, .u8_ty);
            return;
        }
        if (unwrapped.isIntegerPrimitive()) return;
        if (self.pool.getTag(unwrapped) == .enum_ty) return;
        try self.emitTypeMismatch(self.getAstNodeSpan(arg_id), .u8_ty, ord_ty);
    }

    /// Validates a pointer/reference target for `@atomic_*` intrinsics and returns the pointee `TypeId`.
    fn checkAtomicPtrArg(
        self: *TypeChecker,
        ptr_arg_id: NodeIndex,
        explicit_pointee: ?TypeId,
        is_mut_required: bool,
        is_integer_required: bool,
    ) !TypeId {
        const ptr_ty = try self.synthExpr(ptr_arg_id);
        if (ptr_ty.isError()) return explicit_pointee orelse .err_ty;
        const unwrapped_ptr = self.pool.unwrapUnderlyingType(ptr_ty);
        if (self.pool.getFlags(unwrapped_ptr).has_type_vars) {
            return explicit_pointee orelse blk_inner: {
                const p_node = self.pool.getNode(unwrapped_ptr);
                if (p_node.tag == .ref_ty or p_node.tag == .mut_ref_ty or p_node.tag == .raw_ptr_ty) {
                    break :blk_inner TypeId.fromInt(p_node.lhs);
                }
                break :blk_inner .err_ty;
            };
        }
        const ptr_node = self.pool.getNode(unwrapped_ptr);
        const is_valid_ptr = ptr_node.tag == .ref_ty or ptr_node.tag == .mut_ref_ty or ptr_node.tag == .raw_ptr_ty;
        if (!is_valid_ptr) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(ptr_arg_id),
                "atomic intrinsic first argument must be a reference (`&T` / `&mut T`) or raw pointer (`*T` / `*mut T`)",
                "expected pointer or reference to atomic slot",
            );
            return explicit_pointee orelse .err_ty;
        }
        const is_mut_ptr = ptr_node.tag == .mut_ref_ty or (ptr_node.tag == .raw_ptr_ty and ptr_node.rhs != 0);
        if (is_mut_required and !is_mut_ptr) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(ptr_arg_id),
                "mutating atomic intrinsic requires `&mut T` or `*mut T` target",
                "immutable pointer passed to atomic store/RMW",
            );
        }
        const pointee_ty = TypeId.fromInt(ptr_node.lhs);
        if (explicit_pointee) |exp_ty| {
            if (!exp_ty.isError() and pointee_ty != exp_ty) {
                try self.emitTypeMismatch(self.getAstNodeSpan(ptr_arg_id), exp_ty, pointee_ty);
            }
        }
        const base_pointee = self.pool.unwrapUnderlyingType(pointee_ty);
        if (!base_pointee.isError() and !self.pool.getFlags(base_pointee).has_type_vars) {
            const p_tag = self.pool.getTag(base_pointee);
            const is_int = base_pointee.isIntegerPrimitive() and base_pointee != .i128_ty and base_pointee != .u128_ty;
            const is_scalar = is_int or base_pointee == .bool_ty or p_tag == .raw_ptr_ty or
                p_tag == .ref_ty or p_tag == .fn_ty or p_tag == .enum_ty;
            if ((is_integer_required and !is_int) or (!is_integer_required and !is_scalar)) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(ptr_arg_id),
                    "atomic target type must be an atomic-width integer, `bool`, fieldless `enum`, or thin pointer",
                    "unsupported atomic value type",
                );
            }
        }
        return pointee_ty;
    }

    /// Validates that `vec_ty` unwraps to `[Lane; N]` with power-of-two `N` (`2..64`) and numeric `Lane`.
    fn extractSimdVectorLaneType(self: *TypeChecker, vec_ty: TypeId, err_span: Span) !TypeId {
        if (vec_ty.isError()) return .err_ty;
        const unwrapped = self.pool.unwrapUnderlyingType(vec_ty);
        if (self.pool.getFlags(unwrapped).has_type_vars) {
            const v_node = self.pool.getNode(unwrapped);
            if (v_node.tag == .array_ty) return TypeId.fromInt(v_node.lhs);
            return .err_ty;
        }
        const vec_node = self.pool.getNode(unwrapped);
        if (vec_node.tag != .array_ty or (vec_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                err_span,
                "SIMD intrinsic requires a fixed-width vector `[Lane; N]` where `N` is a power of two (`2..64`)",
                "expected SIMD vector type `[Lane; N]`",
            );
            return .err_ty;
        }
        const lane_count = vec_node.rhs;
        const lane_ty = TypeId.fromInt(vec_node.lhs);
        const lane_base = self.pool.unwrapUnderlyingType(lane_ty);
        const is_valid_lane = (lane_base.isIntegerPrimitive() and lane_base != .i128_ty and lane_base != .u128_ty) or
            lane_base == .f32_ty or lane_base == .f64_ty;
        const is_valid_width = lane_count >= 2 and lane_count <= 64 and std.math.isPowerOfTwo(lane_count);
        if (!is_valid_lane or !is_valid_width) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                err_span,
                "SIMD vector `[Lane; N]` requires numeric lane (`i8..i64`, `u8..u64`, `f32`, `f64`) and power-of-two `N` (`2..64`)",
                "invalid SIMD lane type or lane count",
            );
            return .err_ty;
        }
        return lane_ty;
    }

    /// Emits `E0315` (`e0315_wire_layout_contract_violation`) with exact field/padding byte-offset details.
    fn emitWireLayoutViolation(
        self: *TypeChecker,
        span: Span,
        root_ty: TypeId,
        contract_name: []const u8,
        violation: WireLayoutViolation,
    ) !void {
        if (self.diagnostic_sink == null) return;
        var root_buf: [80]u8 = undefined;
        const root_str = self.pool.formatType(root_ty, self.sym_table, &root_buf);
        const member_label: []const u8 = if (violation.field_name.len > 0) violation.field_name else root_str;

        var msg_buf: [280]u8 = undefined;
        const msg: []const u8 = switch (violation.reason) {
            .secret_type => std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` contains `@secret` data (`{s}`) and cannot satisfy `{s}`",
                .{ root_str, member_label, contract_name },
            ) catch "type contains `@secret` data and cannot cross raw byte boundaries",
            .non_copy_ownership => std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` owns `AutoDrop` or `@linear` resource (`{s}`) and cannot satisfy `{s}`",
                .{ root_str, member_label, contract_name },
            ) catch "non-`Copy` resource type cannot satisfy wire layout contract",
            .indirection_or_handle => std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` contains pointer, reference, or slice indirection at byte offset {d} and cannot satisfy `{s}`",
                .{ root_str, violation.byte_offset, contract_name },
            ) catch "indirection type cannot satisfy wire layout contract",
            .invalid_bit_patterns => if (violation.field_name.len > 0)
                std.fmt.bufPrint(
                    &msg_buf,
                    "type `{s}` cannot satisfy `{s}`: member `{s}` at byte offset {d} has invalid bit patterns",
                    .{ root_str, contract_name, violation.field_name, violation.byte_offset },
                ) catch "field has invalid bit patterns for `FromBytes`"
            else
                std.fmt.bufPrint(
                    &msg_buf,
                    "type `{s}` (at byte offset {d}) has invalid bit patterns and cannot satisfy `{s}`",
                    .{ root_str, violation.byte_offset, contract_name },
                ) catch "type has invalid bit patterns for `FromBytes`",
            .refinement_narrows_domain => std.fmt.bufPrint(
                &msg_buf,
                "range-refined type `{s}` (`{s}` at byte offset {d}) restricts valid bit patterns and cannot satisfy `{s}`",
                .{ root_str, member_label, violation.byte_offset, contract_name },
            ) catch "range-refined type cannot satisfy `FromBytes`",
            .unzeroed_inter_field_padding => std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` has {d} uninitialized padding byte(s) before field `{s}` at byte offset {d}; add `@zero_pad` for `{s}`",
                .{ root_str, violation.padding_bytes, violation.field_name, violation.byte_offset, contract_name },
            ) catch "type has uninitialized inter-field padding bytes; add `@zero_pad` for `IntoBytes`",
            .unzeroed_tail_padding => std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` has {d} uninitialized trailing padding byte(s) at byte offset {d}; add `@zero_pad` for `{s}`",
                .{ root_str, violation.padding_bytes, violation.byte_offset, contract_name },
            ) catch "type has uninitialized trailing padding bytes; add `@zero_pad` for `IntoBytes`",
            .union_requires_zero_pad => std.fmt.bufPrint(
                &msg_buf,
                "union `{s}` (at byte offset {d}) may contain uninitialized variant tail bytes; add `@zero_pad` for `{s}`",
                .{ member_label, violation.byte_offset, contract_name },
            ) catch "union requires `@zero_pad` to satisfy `IntoBytes`",
            .size_mismatch => std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` byte size ({d}) does not match expected wire layout size ({d})",
                .{ root_str, violation.byte_offset, violation.padding_bytes },
            ) catch "wire layout byte size mismatch",
        };

        try self.emitDiagnosticSimple(
            .e0315_wire_layout_contract_violation,
            span,
            msg,
            "violates `FromBytes` / `IntoBytes` wire layout contract",
        );
    }

    /// Synthesizes `receiver.method(args)` (`method_call`).
    fn synthMethodCallExpr(self: *TypeChecker, expr_id: NodeIndex) !TypeId {
        return self.synthOrCheckMethodCallExpr(expr_id, .err_ty);
    }

    /// Computes the full source `Span` covered by `node_id`'s CST subtree (falling back to `getAstNodeSpan`).
    fn computeFullAstSubtreeSpan(self: *const TypeChecker, node_id: NodeIndex) Span {
        const cst_id = self.ast_arena.getCstOrigin(node_id);
        if (!cst_id.isNone() and cst_id.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = cst_id.asInt();
            const rec = self.cst_arena.getNode(cst_id);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var first_tok: TokenIndex = .none;
            var last_tok: TokenIndex = .none;
            var cur: usize = start_idx;
            while (cur < end_idx) : (cur += 1) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (sub.subtree_size <= 1 and !sub.flags.is_missing_or_injected and
                    !sub.token.isNone() and sub.token.asInt() < self.token_buffer.countTokens())
                {
                    const tok_rec = self.token_buffer.getToken(sub.token);
                    if (!tok_rec.flags.is_synthesized) {
                        if (first_tok.isNone()) first_tok = sub.token;
                        last_tok = sub.token;
                    }
                }
            }
            if (!first_tok.isNone() and !last_tok.isNone()) {
                const first_rec = self.token_buffer.getToken(first_tok);
                const last_rec = self.token_buffer.getToken(last_tok);
                const byte_start = first_rec.byte_offset;
                const byte_end = last_rec.byte_offset +| last_rec.byte_len;
                if (byte_end >= byte_start) {
                    return Span.init(self.file_id, byte_start, byte_end);
                }
            }
        }
        return self.getAstNodeSpan(node_id);
    }

    /// Synthesizes or checks `receiver.method(args)` (including Unified `.` module/type/static calls, `ADR-21C`).
    fn synthOrCheckMethodCallExpr(self: *TypeChecker, expr_id: NodeIndex, expected_ty: TypeId) !TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        if (ast_node.lhs.tag != .node) return .err_ty;
        const recv_id = NodeIndex.fromInt(ast_node.lhs.payload);

        const raw_items = self.getNodeExtraSlice(expr_id, true);
        if (raw_items.len == 0) return .err_ty;
        const member_tok = TokenIndex.fromInt(raw_items[0]);
        const member_name = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, member_tok);
        const member_span = self.token_buffer.getTokenSpan(self.file_id, member_tok);

        var type_arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer type_arg_nodes.deinit(self.allocator);
        var arg_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer arg_nodes.deinit(self.allocator);
        for (raw_items[1..]) |raw_item| {
            const item_id = NodeIndex.fromInt(raw_item);
            if (item_id.asInt() >= self.ast_arena.countNodes()) continue;
            if (isTypeAstTag(self.ast_arena.getNode(item_id).tag)) {
                try type_arg_nodes.append(self.allocator, item_id);
                continue;
            }
            try arg_nodes.append(self.allocator, item_id);
        }
        const explicit_type_args = type_arg_nodes.items;
        const args = arg_nodes.items;

        switch (try self.classifyDotReceiver(recv_id)) {
            .poisoned => {
                for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                return .err_ty;
            },
            .module_ns => |mod_scope| {
                if (mod_scope.isNone() or member_name.len == 0) {
                    for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                    for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                    return .err_ty;
                }
                const sym_id = try self.interner.intern(member_name);
                switch (self.sym_table.lookupInTargetScope(
                    mod_scope,
                    self.current_scope,
                    sym_id,
                    NamespaceMask.VALUE_ONLY,
                )) {
                    .found => |fn_idx| {
                        var overload_candidates: std.ArrayListUnmanaged(SymbolIndex) = .empty;
                        defer overload_candidates.deinit(self.allocator);
                        for (self.sym_table.getScopeMembers(mod_scope)) |cand_idx| {
                            const cand_sym = self.sym_table.getSymbol(cand_idx).*;
                            if (cand_sym.name == sym_id and cand_sym.kind == .fn_sym and cand_sym.flags.is_overload) {
                                try overload_candidates.append(self.allocator, cand_idx);
                            }
                        }
                        if (overload_candidates.items.len > 1 or
                            self.sym_table.getSymbol(fn_idx).flags.is_overload)
                        {
                            return self.resolveAndCheckOverloadCall(
                                expr_id,
                                overload_candidates.items,
                                explicit_type_args,
                                args,
                            );
                        }
                        self.sym_table.markSymbolUsed(fn_idx);
                        self.recordNodeSymbol(expr_id, fn_idx);
                        try self.checkComptimeSymbolAccess(expr_id, fn_idx);
                        if (self.sym_table.getSymbol(fn_idx).kind == .fn_sym) {
                            try self.resolveFnSignatureSymbol(fn_idx);
                        }
                        if (try self.tryCheckStructuredAsyncEntryCall(
                            expr_id,
                            .none,
                            fn_idx,
                            member_name,
                            explicit_type_args,
                            args,
                        )) |handled_mod_async_ty| {
                            return handled_mod_async_ty;
                        }
                        return self.checkCallArgumentsAgainstFn(
                            expr_id,
                            self.sym_table.getSymbol(fn_idx).type_id,
                            fn_idx,
                            null,
                            explicit_type_args,
                            args,
                        );
                    },
                    .private_error => |priv_idx| {
                        if (self.diagnostic_sink) |sink| {
                            try symbol_resolver.emitPrivateAccessDiagnostic(
                                sink,
                                self.sym_table.getSymbol(priv_idx),
                                member_span,
                            );
                        }
                        for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                        for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                        return .err_ty;
                    },
                    .not_found => {
                        if (self.isBuiltinAsyncModuleScope(mod_scope)) {
                            if (try self.tryCheckStructuredAsyncEntryCall(
                                expr_id,
                                .none,
                                .none,
                                member_name,
                                explicit_type_args,
                                args,
                            )) |builtin_async_ty| {
                                return builtin_async_ty;
                            }
                        }
                        if (self.diagnostic_sink) |sink| {
                            const suggestion = self.sym_table.suggestClosestInScope(
                                mod_scope,
                                member_name,
                                NamespaceMask.VALUE_ONLY,
                            );
                            try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                sink,
                                self.interner,
                                member_name,
                                member_span,
                                suggestion,
                            );
                        }
                        for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                        for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                        return .err_ty;
                    },
                }
            },
            .type_ns => |raw_static_ty| {
                const static_ty = if (!expected_ty.isError() and
                    (self.pool.getTag(raw_static_ty) == .struct_ty or
                        self.pool.getTag(raw_static_ty) == .enum_ty or
                        self.pool.getTag(raw_static_ty) == .union_ty) and
                    self.pool.getGenericTypeArgs(raw_static_ty).len == 0 and
                    self.pool.getNode(expected_ty).tag == self.pool.getNode(raw_static_ty).tag and
                    self.pool.getNode(expected_ty).rhs == self.pool.getNode(raw_static_ty).rhs and
                    self.pool.getGenericTypeArgs(expected_ty).len > 0)
                    expected_ty
                else
                    raw_static_ty;

                if (static_ty.isError()) {
                    for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                    for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                    return .err_ty;
                }

                // [A] Primitive integer/float endian byte constructors (`u32.from_le_bytes(b)`, `from_be_bytes`, `from_ne_bytes`):
                const prim_base = self.pool.unwrapUnderlyingType(static_ty);
                if ((prim_base.isIntegerPrimitive() or prim_base.isFloatPrimitive()) and
                    (std.mem.eql(u8, member_name, "from_le_bytes") or
                        std.mem.eql(u8, member_name, "from_be_bytes") or
                        std.mem.eql(u8, member_name, "from_ne_bytes")))
                {
                    const byte_len: u32 = @intCast(self.computeTypeLayout(prim_base, self.target_layout).byte_size);
                    const byte_arr_ty = try self.pool.internArray(.u8_ty, byte_len, false);
                    for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                    if (args.len != 1) {
                        try self.emitDiagnosticSimple(
                            .e0401_type_mismatch,
                            self.getAstNodeSpan(expr_id),
                            "endian byte constructor expects exactly 1 `[u8; N]` argument",
                            "expected `[u8; N]` byte array here",
                        );
                        for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                        return static_ty;
                    }
                    const val_arg = self.unwrapCallArgExpr(args[0]);
                    _ = try self.checkExpr(val_arg, byte_arr_ty);
                    return static_ty;
                }

                const unwrapped_static = self.pool.unwrapUnderlyingType(static_ty);
                const static_node = self.pool.getNode(unwrapped_static);

                // [B] Built-in `Option[T].Some(v)` and `Result[T, E].Ok(v)` / `.Err(e)` constructors:
                if (static_node.tag == .optional_ty and std.mem.eql(u8, member_name, "Some")) {
                    const saved_walrus = self.is_dominating_walrus_pos;
                    self.is_dominating_walrus_pos = false;
                    defer self.is_dominating_walrus_pos = saved_walrus;
                    try self.rejectNamedArgsInNodeSlice(args);
                    const payload_ty = TypeId.fromInt(static_node.lhs);
                    if (args.len == 1) {
                        _ = try self.checkExpr(self.unwrapCallArgExpr(args[0]), payload_ty);
                    } else {
                        for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                    }
                    return static_ty;
                }
                if (static_node.tag == .result_ty and
                    (std.mem.eql(u8, member_name, "Ok") or std.mem.eql(u8, member_name, "Err")))
                {
                    const saved_walrus = self.is_dominating_walrus_pos;
                    self.is_dominating_walrus_pos = false;
                    defer self.is_dominating_walrus_pos = saved_walrus;
                    try self.rejectNamedArgsInNodeSlice(args);
                    const payload_ty = if (std.mem.eql(u8, member_name, "Ok"))
                        TypeId.fromInt(static_node.lhs)
                    else
                        TypeId.fromInt(static_node.rhs);
                    if (args.len == 1) {
                        _ = try self.checkExpr(self.unwrapCallArgExpr(args[0]), payload_ty);
                    } else {
                        for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                    }
                    return static_ty;
                }

                // [C] Nominal `enum` tuple variant constructor or `struct`/`enum`/`union`/`trait` associated function:
                if (static_node.tag == .struct_ty or static_node.tag == .enum_ty or
                    static_node.tag == .union_ty or static_node.tag == .trait_ty)
                {
                    const owner_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(static_node.rhs)).*;
                    if (!owner_sym.target_scope.isNone()) {
                        const mem_sym_id = try self.interner.intern(member_name);
                        switch (self.sym_table.lookupInTargetScope(
                            owner_sym.target_scope,
                            self.current_scope,
                            mem_sym_id,
                            NamespaceMask.VALUE_ONLY,
                        )) {
                            .found => |m_idx| {
                                self.sym_table.markSymbolUsed(m_idx);
                                self.recordNodeSymbol(expr_id, m_idx);
                                const m_sym = self.sym_table.getSymbol(m_idx).*;
                                if (m_sym.kind == .enum_variant_sym) {
                                    const saved_walrus = self.is_dominating_walrus_pos;
                                    self.is_dominating_walrus_pos = false;
                                    defer self.is_dominating_walrus_pos = saved_walrus;
                                    try self.rejectNamedArgsInNodeSlice(args);
                                    for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                                    var subst = SubstitutionMap{};
                                    defer subst.deinit(self.allocator);
                                    const gen_args = self.pool.getGenericTypeArgs(unwrapped_static);
                                    if (gen_args.len > 0) {
                                        var tp_ord: usize = 0;
                                        for (self.sym_table.getScopeMembers(owner_sym.target_scope)) |tp_idx| {
                                            const tp_sym = self.sym_table.getSymbol(tp_idx).*;
                                            if (tp_sym.kind == .type_param_sym and !tp_sym.type_id.isError()) {
                                                if (tp_ord < gen_args.len) {
                                                    try subst.put(
                                                        self.allocator,
                                                        tp_sym.type_id,
                                                        TypeId.fromInt(gen_args[tp_ord]),
                                                        member_span,
                                                    );
                                                }
                                                tp_ord += 1;
                                            }
                                        }
                                    }
                                    const raw_payload_ty = try subst.apply(self.pool, m_sym.type_id);
                                    if (args.len == 1) {
                                        const val_arg = self.unwrapCallArgExpr(args[0]);
                                        if (self.pool.getFlags(raw_payload_ty).has_type_vars) {
                                            const arg_ty = self.materializeUntypedType(try self.synthExpr(val_arg));
                                            _ = try self.unifyParamTypeWithArg(
                                                raw_payload_ty,
                                                arg_ty,
                                                self.getAstNodeSpan(val_arg),
                                                &subst,
                                                true,
                                            );
                                        } else {
                                            _ = try self.checkExpr(val_arg, raw_payload_ty);
                                        }
                                    } else if (args.len > 1 and self.pool.getTag(raw_payload_ty) == .tuple_ty) {
                                        const tup_elems = self.pool.getTupleElements(raw_payload_ty);
                                        for (args, 0..) |arg_id, arg_i| {
                                            const val_arg = self.unwrapCallArgExpr(arg_id);
                                            const elem_ty = if (arg_i < tup_elems.len)
                                                TypeId.fromInt(tup_elems[arg_i])
                                            else
                                                .err_ty;
                                            if (self.pool.getFlags(elem_ty).has_type_vars) {
                                                const arg_ty = self.materializeUntypedType(try self.synthExpr(val_arg));
                                                _ = try self.unifyParamTypeWithArg(
                                                    elem_ty,
                                                    arg_ty,
                                                    self.getAstNodeSpan(val_arg),
                                                    &subst,
                                                    true,
                                                );
                                            } else {
                                                _ = try self.checkExpr(val_arg, elem_ty);
                                            }
                                        }
                                    } else {
                                        for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                                    }
                                    if (gen_args.len == 0) {
                                        var inferred_tps: std.ArrayListUnmanaged(TypeId) = .empty;
                                        defer inferred_tps.deinit(self.allocator);
                                        for (self.sym_table.getScopeMembers(owner_sym.target_scope)) |tp_idx| {
                                            const tp_sym = self.sym_table.getSymbol(tp_idx).*;
                                            if (tp_sym.kind == .type_param_sym and !tp_sym.type_id.isError()) {
                                                try inferred_tps.append(
                                                    self.allocator,
                                                    try subst.apply(self.pool, tp_sym.type_id),
                                                );
                                            }
                                        }
                                        if (inferred_tps.items.len > 0) {
                                            try self.recordCallInstantiation(expr_id, inferred_tps.items);
                                            return self.internNominalWithResolvedArgs(unwrapped_static, inferred_tps.items);
                                        }
                                    } else {
                                        var inst_tps: std.ArrayListUnmanaged(TypeId) = .empty;
                                        defer inst_tps.deinit(self.allocator);
                                        for (gen_args) |raw_tp| {
                                            try inst_tps.append(self.allocator, TypeId.fromInt(raw_tp));
                                        }
                                        try self.recordCallInstantiation(expr_id, inst_tps.items);
                                    }
                                    return static_ty;
                                }

                                try self.checkComptimeSymbolAccess(expr_id, m_idx);
                                if (m_sym.kind == .fn_sym) {
                                    try self.resolveFnSignatureSymbol(m_idx);
                                }
                                const subst_fn_ty = try self.substituteNominalMemberType(
                                    unwrapped_static,
                                    self.sym_table.getSymbol(m_idx).type_id,
                                );
                                return self.checkCallArgumentsAgainstFn(
                                    expr_id,
                                    subst_fn_ty,
                                    m_idx,
                                    null,
                                    explicit_type_args,
                                    args,
                                );
                            },
                            .private_error => |priv_idx| {
                                if (self.diagnostic_sink) |sink| {
                                    try symbol_resolver.emitPrivateAccessDiagnostic(
                                        sink,
                                        self.sym_table.getSymbol(priv_idx),
                                        member_span,
                                    );
                                }
                                for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                                return .err_ty;
                            },
                            .not_found => {
                                if (self.diagnostic_sink) |sink| {
                                    const suggestion = self.sym_table.suggestClosestInScope(
                                        owner_sym.target_scope,
                                        member_name,
                                        NamespaceMask.VALUE_ONLY,
                                    );
                                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                                        sink,
                                        self.interner,
                                        member_name,
                                        member_span,
                                        suggestion,
                                    );
                                }
                                for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                                return .err_ty;
                            },
                        }
                    }
                }

                if (self.diagnostic_sink) |sink| {
                    try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                        sink,
                        self.interner,
                        member_name,
                        member_span,
                        null,
                    );
                }
                for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                return .err_ty;
            },
            .value_expr => {},
        }

        const recv_ty = try self.synthExpr(recv_id);
        if (recv_ty.isError()) {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
            for (args) |arg_id| {
                _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            }
            return .err_ty;
        }

        const unwrapped_raw_recv = self.pool.unwrapUnderlyingType(recv_ty);
        if (self.pool.getTag(unwrapped_raw_recv) == .raw_ptr_ty) {
            var ptr_msg_buf: [208]u8 = undefined;
            const ptr_msg = std.fmt.bufPrint(
                &ptr_msg_buf,
                "raw pointer does not auto-dereference on method call; write `ptr.*.{s}(…)` inside `unsafe`",
                .{member_name},
            ) catch "raw pointer does not auto-dereference on method call; use `.*` inside `unsafe`";
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                member_span,
                ptr_msg,
                "explicit `.*` dereference required on raw pointer",
            );
            for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
            for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            return .err_ty;
        }

        const unwrapped_recv = self.unwrapRefType(recv_ty);
        const recv_node = self.pool.getNode(unwrapped_recv);

        // [0] Retired `Option.unwrap()` / `Option.unwrap_or(d)` migration autofix (`DR-21` `SE-03`):
        if (recv_node.tag == .optional_ty and
            (std.mem.eql(u8, member_name, "unwrap") or std.mem.eql(u8, member_name, "unwrap_or")))
        {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            const inner_ty = TypeId.fromInt(recv_node.lhs);
            const is_unwrap_or = std.mem.eql(u8, member_name, "unwrap_or");
            if (is_unwrap_or and args.len == 1) {
                _ = try self.checkExpr(self.unwrapCallArgExpr(args[0]), inner_ty);
            } else {
                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            }
            if (self.diagnostic_sink) |sink| {
                const call_span = self.computeFullAstSubtreeSpan(expr_id);
                const recv_span = self.computeFullAstSubtreeSpan(recv_id);
                const recv_src = if (recv_span.end_byte > recv_span.start_byte and
                    @as(usize, recv_span.end_byte) <= self.source.len)
                    self.source[recv_span.start_byte..recv_span.end_byte]
                else
                    "opt";
                var repl_buf: [256]u8 = undefined;
                const repl_str: []const u8 = if (is_unwrap_or and args.len == 1) blk_repl: {
                    const arg_span = self.computeFullAstSubtreeSpan(self.unwrapCallArgExpr(args[0]));
                    const arg_src = if (arg_span.end_byte > arg_span.start_byte and
                        @as(usize, arg_span.end_byte) <= self.source.len)
                        self.source[arg_span.start_byte..arg_span.end_byte]
                    else
                        "default";
                    break :blk_repl std.fmt.bufPrint(&repl_buf, "{s} orelse {s}", .{ recv_src, arg_src }) catch
                        "opt orelse default";
                } else std.fmt.bufPrint(&repl_buf, "{s} orelse unreachable", .{recv_src}) catch
                    "opt orelse unreachable";

                const repl_id = try self.interner.intern(repl_str);
                const labels = [1]LabeledSpan{.{
                    .span = member_span,
                    .label = if (is_unwrap_or)
                        "replace `.unwrap_or(d)` with `orelse d`"
                    else
                        "replace `.unwrap()` with `orelse unreachable`",
                    .style = .primary,
                }};
                const edits = [1]TextEdit{.{
                    .file_id = call_span.file_id,
                    .start_byte = call_span.start_byte,
                    .end_byte = call_span.end_byte,
                    .replacement_id = repl_id,
                }};
                const fixes = [1]SuggestedFix{.{
                    .message = if (is_unwrap_or)
                        "rewrite `.unwrap_or(…)` using `orelse`"
                    else
                        "rewrite `.unwrap()` using `orelse unreachable`",
                    .applicability = .machine_applicable,
                    .priority = .syntax_canonicalization,
                    .edits = &edits,
                }};
                _ = try sink.emit(.{
                    .code = .e0403_unresolved_symbol,
                    .severity = .err,
                    .primary_span = member_span,
                    .message = if (is_unwrap_or)
                        "`Option.unwrap_or` is retired in CoreX; use `opt orelse fallback`"
                    else
                        "`Option.unwrap` is retired in CoreX; use `opt orelse unreachable`",
                    .labels = &labels,
                    .suggestions = &fixes,
                });
            }
            return inner_ty;
        }

        // [0b] Built-in `Bencher`, `TaskGroup[E]`, and `TaskHandle[T]` methods (`SE-16`, `SE-20`):
        if (unwrapped_recv == .bencher_ty and explicit_type_args.len == 0) {
            if (std.mem.eql(u8, member_name, "iter") and args.len == 1) {
                const cb_arg = self.unwrapCallArgExpr(args[0]);
                if (self.ast_arena.getNode(cb_arg).tag == .block) {
                    _ = try self.synthExpr(cb_arg);
                    try self.builder_block_calls.put(self.allocator, expr_id.asInt(), .unit_ty);
                } else {
                    const cb_ty = try self.synthExpr(cb_arg);
                    if (!cb_ty.isError()) {
                        if (self.pool.getFnSignatureView(self.pool.unwrapUnderlyingType(cb_ty))) |cb_sig| {
                            if (cb_sig.paramCount() != 0) {
                                try self.emitDiagnosticSimple(
                                    .e0401_type_mismatch,
                                    self.getAstNodeSpan(cb_arg),
                                    "`Bencher.iter` callback must take 0 parameters (`|| { … }`)",
                                    "expected 0-parameter benchmark closure",
                                );
                            }
                        } else {
                            try self.emitDiagnosticSimple(
                                .e0401_type_mismatch,
                                self.getAstNodeSpan(cb_arg),
                                "`Bencher.iter` expects a closure `|| { … }` or function `fn() -> T`",
                                "expected callable benchmark body",
                            );
                        }
                    }
                }
                return .unit_ty;
            }
            if (std.mem.eql(u8, member_name, "bytes") and args.len == 1) {
                _ = try self.checkExpr(self.unwrapCallArgExpr(args[0]), .u64_ty);
                return .unit_ty;
            }
        }
        if (self.isTaskGroupLikeType(unwrapped_recv) and explicit_type_args.len == 0) {
            if (TASK_GROUP_METHOD_MAP.get(member_name)) |tg_method| {
                switch (tg_method) {
                    .spawn, .spawn_local => {
                        if (args.len == 1) {
                            return self.checkTaskGroupSpawnCall(
                                expr_id,
                                unwrapped_recv,
                                args[0],
                                tg_method == .spawn_local,
                            );
                        }
                    },
                    .cancel, .cancel_all => {
                        if (args.len == 0) return .unit_ty;
                    },
                    .is_cancelled => {
                        if (args.len == 0) return .bool_ty;
                    },
                }
            }
        }
        if (self.isTaskHandleLikeType(unwrapped_recv) and explicit_type_args.len == 0) {
            if ((std.mem.eql(u8, member_name, "join") or std.mem.eql(u8, member_name, "cancel")) and args.len == 0) {
                if (self.pool.getTag(unwrapped_raw_recv) == .ref_ty or
                    self.pool.getTag(unwrapped_raw_recv) == .mut_ref_ty)
                {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        member_span,
                        "`TaskHandle.join` and `TaskHandle.cancel` consume `own self` by value, not by reference",
                        "cannot consume `@linear` `TaskHandle` behind a reference",
                    );
                    return .err_ty;
                }
                if (std.mem.eql(u8, member_name, "cancel")) {
                    return self.pool.internFuture(.unit_ty, 0);
                }
                const out_ty = self.extractTaskHandleValueType(unwrapped_recv) orelse .err_ty;
                return self.pool.internFuture(out_ty, 0);
            }
        }

        // [1] Built-in `.len()`, `.is_empty()`, `.as_ptr()`, `.as_mut_ptr()`, and `.as_bytes()` methods (`ADR-22D`, `SE-09`):
        const union_caps = self.getSharedUnionSliceCapabilities(unwrapped_recv);
        const is_slice_or_str = recv_node.tag == .slice_ty or recv_node.tag == .array_ty or
            recv_node.tag == .soa_slice_ty or recv_node.tag == .soa_array_ty or
            unwrapped_recv == .str_ty or union_caps.has_len_and_empty;
        if (is_slice_or_str and explicit_type_args.len == 0 and args.len == 0) {
            if (std.mem.eql(u8, member_name, "len")) {
                return .usize_ty;
            }
            if (std.mem.eql(u8, member_name, "is_empty")) {
                return .bool_ty;
            }
            if (std.mem.eql(u8, member_name, "as_ptr")) {
                if (unwrapped_recv == .str_ty) {
                    return self.pool.internRawPtr(.u8_ty, false);
                }
                if (recv_node.tag == .slice_ty or recv_node.tag == .array_ty) {
                    return self.pool.internRawPtr(TypeId.fromInt(recv_node.lhs), false);
                }
                if (!union_caps.shared_elem_ty.isError()) {
                    return self.pool.internRawPtr(union_caps.shared_elem_ty, false);
                }
            }
            if (std.mem.eql(u8, member_name, "as_mut_ptr") and
                (recv_node.tag == .slice_ty or recv_node.tag == .array_ty))
            {
                const is_mut_recv = self.pool.getTag(unwrapped_raw_recv) == .mut_ref_ty or
                    (self.pool.getTag(unwrapped_raw_recv) != .ref_ty and self.isMutableAssignablePlace(recv_id));
                if (!is_mut_recv) {
                    try self.emitDiagnosticSimple(
                        .e0305_exclusivity_violation,
                        member_span,
                        "cannot obtain mutable raw pointer via `.as_mut_ptr()` from immutable slice or array",
                        "receiver requires `&mut [T]` or mutable `var` binding",
                    );
                }
                return self.pool.internRawPtr(TypeId.fromInt(recv_node.lhs), true);
            }
            if (std.mem.eql(u8, member_name, "as_bytes")) {
                if (unwrapped_recv == .str_ty or union_caps.has_as_bytes) {
                    const byte_slice_ty = try self.pool.internSlice(.u8_ty, false);
                    return self.pool.internRef(byte_slice_ty, false);
                }
                if (recv_node.tag == .slice_ty or recv_node.tag == .array_ty) {
                    const elem_ty = self.materializeUntypedType(TypeId.fromInt(recv_node.lhs));
                    if (!elem_ty.isError() and !self.pool.getFlags(elem_ty).has_type_vars) {
                        if (self.pool.explainIntoBytesViolation(elem_ty, self.sym_table, self.target_layout)) |viol| {
                            try self.emitWireLayoutViolation(self.getAstNodeSpan(expr_id), elem_ty, "IntoBytes", viol);
                        }
                    }
                    const byte_slice_ty = try self.pool.internSlice(.u8_ty, false);
                    return self.pool.internRef(byte_slice_ty, false);
                }
            }
        }

        // [1b] Primitive endian byte projections (`val.to_le_bytes()`, `to_be_bytes()`, `to_ne_bytes()`):
        const recv_prim_base = self.pool.unwrapUnderlyingType(self.pool.unwrapRefinementBase(unwrapped_recv));
        if ((recv_prim_base.isIntegerPrimitive() or recv_prim_base.isFloatPrimitive() or
            recv_prim_base == .untyped_int_ty or recv_prim_base == .untyped_float_ty) and
            (std.mem.eql(u8, member_name, "to_le_bytes") or
                std.mem.eql(u8, member_name, "to_be_bytes") or
                std.mem.eql(u8, member_name, "to_ne_bytes")) and
            explicit_type_args.len == 0 and args.len == 0)
        {
            const mat_prim = self.materializeUntypedType(recv_prim_base);
            if (recv_prim_base == .untyped_int_ty or recv_prim_base == .untyped_float_ty) {
                _ = try self.checkExpr(recv_id, mat_prim);
            }
            const byte_len: u32 = @intCast(self.computeTypeLayout(mat_prim, self.target_layout).byte_size);
            return self.pool.internArray(.u8_ty, byte_len, false);
        }

        // [2] Built-in `.narrow[Dst]()` / `.narrow()` and `.try_narrow[Dst]()` / `.try_narrow()` (`D-11`):
        const recv_int_base = self.pool.unwrapRefinementBase(unwrapped_recv);
        const is_narrow = std.mem.eql(u8, member_name, "narrow");
        const is_try_narrow = std.mem.eql(u8, member_name, "try_narrow");
        if ((is_narrow or is_try_narrow) and
            (recv_int_base.isIntegerPrimitive() or recv_int_base == .untyped_int_ty))
        {
            if (explicit_type_args.len > 1 or args.len != 0) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(expr_id),
                    "`.narrow` / `.try_narrow` expects at most 1 type argument `[Dst]` and 0 value arguments `()`",
                    "expected `val.narrow[Dst]()` or `val.narrow()`",
                );
                for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                return .err_ty;
            }
            if (recv_int_base == .untyped_int_ty) {
                _ = try self.checkExpr(recv_id, .i32_ty);
            }

            var dst_ty: TypeId = .err_ty;
            if (explicit_type_args.len == 1) {
                dst_ty = try self.resolveTypeAst(explicit_type_args[0]);
            } else if (!expected_ty.isError()) {
                if (is_narrow) {
                    dst_ty = expected_ty;
                } else if (self.pool.getTag(expected_ty) == .optional_ty) {
                    dst_ty = TypeId.fromInt(self.pool.getNode(expected_ty).lhs);
                }
            }
            if (dst_ty.isError()) {
                if (explicit_type_args.len == 0) {
                    try self.emitDiagnosticSimple(
                        .e0401_type_mismatch,
                        member_span,
                        "cannot infer target integer type for narrowing call; specify `[Dst]` or add a type annotation",
                        "specify `.narrow[Dst]()` / `.try_narrow[Dst]()` here",
                    );
                }
                return .err_ty;
            }

            const dst_base = self.pool.unwrapRefinementBase(dst_ty);
            if (!dst_base.isIntegerPrimitive()) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    if (explicit_type_args.len == 1) self.getAstNodeSpan(explicit_type_args[0]) else member_span,
                    "narrowing target type must be a primitive or range-refined integer type",
                    "expected integer target type here",
                );
                return .err_ty;
            }

            const prim_bounds = getTargetPrimitiveIntBounds(dst_base, self.target_layout);
            const base_min: i128 = if (prim_bounds) |bounds| bounds.min_val else 0;
            const base_max: i128 = if (prim_bounds) |bounds| bounds.max_val else 0;
            const ref_bounds = self.pool.getRefinementBounds(dst_ty);

            const one_arg = [1]TypeId{dst_ty};
            try self.recordCallInstantiation(expr_id, &one_arg);
            try self.narrow_calls.put(self.allocator, expr_id.asInt(), .{
                .kind = if (is_try_narrow) .try_narrow else .narrow,
                .src_ty = self.materializeUntypedType(unwrapped_recv),
                .dst_ty = dst_ty,
                .min_val = if (ref_bounds) |bounds| @max(base_min, bounds.min_val) else base_min,
                .max_val = if (ref_bounds) |bounds| @min(base_max, bounds.max_val) else base_max,
            });
            return if (is_try_narrow) try self.pool.internOptional(dst_ty) else dst_ty;
        }

        // [3] User or `impl` method lookup on nominal / trait-bounded receivers:
        var lookup_owner_scope: ScopeId = .none;
        if (recv_node.tag == .struct_ty or recv_node.tag == .enum_ty or
            recv_node.tag == .union_ty or recv_node.tag == .trait_ty)
        {
            lookup_owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(recv_node.rhs)).target_scope;
        } else if (recv_node.tag == .type_param or recv_node.tag == .bind_once_group_var or
            recv_node.tag == .bind_many_any_var)
        {
            const bound_node = self.pool.getNode(TypeId.fromInt(recv_node.lhs));
            if (bound_node.tag == .trait_ty) {
                lookup_owner_scope = self.sym_table.getSymbol(SymbolIndex.fromInt(bound_node.rhs)).target_scope;
            }
        }

        if (!lookup_owner_scope.isNone()) {
            const method_sym_id = try self.interner.intern(member_name);
            switch (self.sym_table.lookupInTargetScope(
                lookup_owner_scope,
                self.current_scope,
                method_sym_id,
                NamespaceMask.VALUE_ONLY,
            )) {
                .found => |m_idx| {
                    self.sym_table.markSymbolUsed(m_idx);
                    self.recordNodeSymbol(expr_id, m_idx);
                    try self.resolveFnSignatureSymbol(m_idx);
                    const m_ty = try self.substituteNominalMemberType(
                        unwrapped_recv,
                        self.sym_table.getSymbol(m_idx).type_id,
                    );
                    return self.checkCallArgumentsAgainstFn(
                        expr_id,
                        m_ty,
                        m_idx,
                        recv_id,
                        explicit_type_args,
                        args,
                    );
                },
                .private_error => |priv_idx| {
                    if (self.diagnostic_sink) |sink| {
                        try symbol_resolver.emitPrivateAccessDiagnostic(
                            sink,
                            self.sym_table.getSymbol(priv_idx),
                            member_span,
                        );
                    }
                    return .err_ty;
                },
                .not_found => {},
            }
        }

        // [4] Built-in `.as_bytes()` wire projection on `IntoBytes` values / `&T` (`D-01`, `E0315`):
        if (std.mem.eql(u8, member_name, "as_bytes") and explicit_type_args.len == 0 and args.len == 0) {
            const mat_recv = self.materializeUntypedType(unwrapped_recv);
            if (!mat_recv.isError() and !self.pool.getFlags(mat_recv).has_type_vars) {
                if (self.pool.explainIntoBytesViolation(mat_recv, self.sym_table, self.target_layout)) |viol| {
                    try self.emitWireLayoutViolation(self.getAstNodeSpan(expr_id), mat_recv, "IntoBytes", viol);
                }
            }
            const byte_slice_ty = try self.pool.internSlice(.u8_ty, false);
            return self.pool.internRef(byte_slice_ty, false);
        }

        if (!self.pool.getFlags(unwrapped_recv).has_type_vars) {
            if (self.diagnostic_sink) |sink| {
                const suggestion = if (!lookup_owner_scope.isNone())
                    self.sym_table.suggestClosestInScope(
                        lookup_owner_scope,
                        member_name,
                        NamespaceMask.VALUE_ONLY,
                    )
                else
                    null;
                try symbol_resolver.emitUnresolvedSymbolDiagnostic(
                    sink,
                    self.interner,
                    member_name,
                    member_span,
                    suggestion,
                );
            }
        }

        {
            const saved_walrus = self.is_dominating_walrus_pos;
            self.is_dominating_walrus_pos = false;
            defer self.is_dominating_walrus_pos = saved_walrus;
            for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
            for (args) |arg_id| {
                _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            }
        }
        return .err_ty;
    }

    /// Resolves an `@overload` candidate set against `args`, emitting `E0400` on ambiguity (`DR-02` Section 1.2).
    fn resolveAndCheckOverloadCall(
        self: *TypeChecker,
        call_id: NodeIndex,
        candidates: []const SymbolIndex,
        explicit_type_args: []const NodeIndex,
        args: []const NodeIndex,
    ) !TypeId {
        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus;

        const explicit_tys = try self.allocator.alloc(TypeId, explicit_type_args.len);
        defer if (explicit_tys.len > 0) self.allocator.free(explicit_tys);
        for (explicit_type_args, 0..) |type_node_id, i| {
            explicit_tys[i] = try self.resolveTypeAst(type_node_id);
        }

        const arg_types = try self.allocator.alloc(TypeId, args.len);
        defer if (arg_types.len > 0) self.allocator.free(arg_types);
        for (args, 0..) |arg_id, i| {
            const val_arg_id = self.unwrapCallArgExpr(arg_id);
            const val_tag = self.ast_arena.getNode(val_arg_id).tag;
            if (val_tag == .contextual_variant or val_tag == .closure_expr) {
                arg_types[i] = .err_ty;
            } else {
                arg_types[i] = try self.synthExpr(val_arg_id);
            }
        }

        const MatchScore = enum(u8) {
            none = 0,
            group_or_tilde = 1,
            exact = 2,
        };

        var best_score: MatchScore = .none;
        var best_candidate: SymbolIndex = .none;
        var is_ambiguous = false;

        for (candidates) |cand_idx| {
            if (self.isSymbolCfgDisabled(cand_idx)) continue;
            try self.resolveFnSignatureSymbol(cand_idx);
            const cand_sym = self.sym_table.getSymbol(cand_idx).*;
            const cand_ty = cand_sym.type_id;
            const sig = self.pool.getFnSignatureView(cand_ty) orelse continue;
            const param_count = sig.paramCount();
            const cand_specs = self.sym_table.getFnParamSpecs(cand_idx);

            var cand_tps: std.ArrayListUnmanaged(TypeId) = .empty;
            defer cand_tps.deinit(self.allocator);
            var fallback_names: std.ArrayListUnmanaged([]const u8) = .empty;
            defer fallback_names.deinit(self.allocator);
            if (!cand_sym.target_scope.isNone()) {
                for (self.sym_table.getScopeMembers(cand_sym.target_scope)) |mem_idx| {
                    const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError()) {
                        try cand_tps.append(self.allocator, mem_sym.type_id);
                    } else if (mem_sym.kind == .param_sym and cand_specs.len == 0) {
                        try fallback_names.append(self.allocator, mem_sym.name_text);
                    }
                }
            }
            if (explicit_tys.len > cand_tps.items.len) continue;

            var subst = SubstitutionMap{};
            defer subst.deinit(self.allocator);
            var has_tp_bounds_matched = true;
            for (explicit_tys, 0..) |exp_ty, tp_i| {
                if (exp_ty.isError()) continue;
                const tp_id = cand_tps.items[tp_i];
                const grp_ty = TypeId.fromInt(self.pool.getNode(tp_id).lhs);
                var sat = checkGroupSatisfaction(
                    self.pool,
                    self.sym_table,
                    self.target_layout,
                    exp_ty,
                    grp_ty,
                );
                if (sat == .rejected and self.pool.getTag(grp_ty) == .trait_ty) {
                    if (try self.hasTraitImplementation(exp_ty, grp_ty, 0)) {
                        sat = .matched_exact;
                    }
                }
                if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
                    has_tp_bounds_matched = false;
                    break;
                }
                try subst.put(self.allocator, tp_id, exp_ty, self.getAstNodeSpan(explicit_type_args[tp_i]));
            }
            if (!has_tp_bounds_matched) continue;

            const slot_to_arg = try self.allocator.alloc(?usize, param_count);
            defer if (slot_to_arg.len > 0) self.allocator.free(slot_to_arg);
            @memset(slot_to_arg, null);

            var has_seen_named = false;
            var is_slot_map_valid = true;
            for (args, 0..) |raw_arg_id, src_idx| {
                const raw_node = self.ast_arena.getNode(raw_arg_id);
                if (raw_node.tag == .named_arg) {
                    has_seen_named = true;
                    const label_text = symbol_resolver.extractTokenSlice(
                        self.source,
                        self.token_buffer,
                        raw_node.main_token,
                    );
                    var found_slot: ?usize = null;
                    var p_idx: usize = 0;
                    while (p_idx < param_count) : (p_idx += 1) {
                        const p_name: []const u8 = if (p_idx < cand_specs.len)
                            cand_specs[p_idx].name_text
                        else if (p_idx < fallback_names.items.len)
                            fallback_names.items[p_idx]
                        else
                            "";
                        if (p_name.len > 0 and std.mem.eql(u8, p_name, label_text)) {
                            if (p_idx < cand_specs.len and cand_specs[p_idx].is_positional_only) {
                                break;
                            }
                            found_slot = p_idx;
                            break;
                        }
                    }
                    if (found_slot == null or slot_to_arg[found_slot.?] != null) {
                        is_slot_map_valid = false;
                        break;
                    }
                    slot_to_arg[found_slot.?] = src_idx;
                } else {
                    const is_kw_only_slot = src_idx < cand_specs.len and cand_specs[src_idx].is_keyword_only;
                    if (has_seen_named or is_kw_only_slot or src_idx >= param_count or slot_to_arg[src_idx] != null) {
                        is_slot_map_valid = false;
                        break;
                    }
                    slot_to_arg[src_idx] = src_idx;
                }
            }
            if (!is_slot_map_valid) continue;

            var check_idx: usize = 0;
            while (check_idx < param_count) : (check_idx += 1) {
                if (slot_to_arg[check_idx] == null) {
                    if (check_idx >= cand_specs.len or !cand_specs[check_idx].has_default) {
                        is_slot_map_valid = false;
                        break;
                    }
                }
            }
            if (!is_slot_map_valid) continue;

            var cand_score: MatchScore = .exact;
            var has_all_matched = true;

            var p_i: usize = 0;
            while (p_i < param_count) : (p_i += 1) {
                const src_idx = slot_to_arg[p_i] orelse continue;
                const param_ty = try subst.apply(self.pool, sig.getParamType(p_i));
                const raw_arg_ty = arg_types[src_idx];
                const val_arg_id = self.unwrapCallArgExpr(args[src_idx]);
                const val_tag = self.ast_arena.getNode(val_arg_id).tag;
                if (raw_arg_ty.isError()) {
                    if (val_tag == .contextual_variant or val_tag == .closure_expr) {
                        cand_score = .group_or_tilde;
                        continue;
                    }
                    has_all_matched = false;
                    break;
                }
                const arg_ty = self.materializeUntypedType(raw_arg_ty);
                const p_node = self.pool.getNode(param_ty);

                if (param_ty == arg_ty) continue;
                if ((raw_arg_ty == .untyped_int_ty and param_ty.isIntegerPrimitive()) or
                    (raw_arg_ty == .untyped_float_ty and param_ty.isFloatPrimitive()))
                {
                    cand_score = .group_or_tilde;
                    continue;
                }
                if (p_node.tag == .bind_once_group_var or
                    p_node.tag == .bind_many_any_var or
                    p_node.tag == .type_param)
                {
                    const grp_ty = TypeId.fromInt(p_node.lhs);
                    const sat = checkGroupSatisfaction(
                        self.pool,
                        self.sym_table,
                        self.target_layout,
                        arg_ty,
                        grp_ty,
                    );
                    if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
                        has_all_matched = false;
                        break;
                    }
                    if (p_node.tag == .bind_once_group_var or p_node.tag == .type_param) {
                        if (subst.lookup(param_ty)) |prev_ty| {
                            if (prev_ty != arg_ty) {
                                has_all_matched = false;
                                break;
                            }
                        } else {
                            try subst.put(self.allocator, param_ty, arg_ty, self.getAstNodeSpan(args[src_idx]));
                        }
                    }
                    cand_score = .group_or_tilde;
                } else if (self.pool.getFlags(param_ty).has_type_vars) {
                    if (!(try self.unifyParamTypeWithArg(
                        param_ty,
                        arg_ty,
                        self.getAstNodeSpan(args[src_idx]),
                        &subst,
                        false,
                    ))) {
                        has_all_matched = false;
                        break;
                    }
                    cand_score = .group_or_tilde;
                } else {
                    has_all_matched = false;
                    break;
                }
            }

            if (!has_all_matched) continue;
            if (@backingInt(cand_score) > @backingInt(best_score)) {
                best_score = cand_score;
                best_candidate = cand_idx;
                is_ambiguous = false;
            } else if (cand_score == best_score) {
                is_ambiguous = true;
            }
        }

        if (is_ambiguous) {
            try self.emitDiagnosticSimple(
                .e0400_ambiguous_overload,
                self.getAstNodeSpan(call_id),
                "ambiguous call to `@overload` function group; multiple candidates match equally",
                "specify explicit type arguments or cast arguments to disambiguate",
            );
            return .err_ty;
        }
        if (best_candidate.isNone()) {
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(call_id),
                "no `@overload` candidate matches the supplied argument types",
                "no matching overload signature found",
            );
            return .err_ty;
        }

        self.sym_table.markSymbolUsed(best_candidate);
        self.recordNodeSymbol(call_id, best_candidate);
        const chosen_ty = self.sym_table.getSymbol(best_candidate).type_id;
        return self.checkCallArgumentsAgainstFn(
            call_id,
            chosen_ty,
            best_candidate,
            null,
            explicit_type_args,
            args,
        );
    }

    /// Two-Pass Spine-Local Argument, Named/Default (`SE-07`), Generic `[T]`, & `comptime` Verification:
    /// - Enforces `comptime fn` (`E0503` at runtime), `extern fn` (`E0503` at `comptime`), and `comptime` params (`E0503`),
    /// - Resolves positional, `label: val`, and omitted `param: T = default` arguments (`E0419`),
    /// - Binds explicit `[TypeArgs]` and infers Bind-Once / Bind-Many Type Group parameters,
    /// - Records concrete instantiation tuples in `self.call_instantiations`.
    fn checkCallArgumentsAgainstFn(
        self: *TypeChecker,
        call_id: NodeIndex,
        fn_ty: TypeId,
        callee_sym_idx: SymbolIndex,
        optional_self_recv: ?NodeIndex,
        explicit_type_args: []const NodeIndex,
        args: []const NodeIndex,
    ) !TypeId {
        const saved_walrus = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus;

        var comptime_param_mask: u64 = 0;
        var declared_type_params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer declared_type_params.deinit(self.allocator);
        var enclosing_owner_sym_idx: SymbolIndex = .none;

        if (!callee_sym_idx.isNone()) {
            const callee_sym = self.sym_table.getSymbol(callee_sym_idx).*;
            comptime_param_mask = callee_sym.is_comptime_param_mask;
            if (callee_sym.flags.is_comptime and self.pure_comptime_depth == 0) {
                try self.emitDiagnosticSimple(
                    .e0503_forbidden_comptime_operation,
                    self.getAstNodeSpan(call_id),
                    "`comptime fn` cannot be invoked at runtime; evaluate inside `comptime` or a `const` binding",
                    "compile-time-only function called in runtime context",
                );
            }
            if (callee_sym.flags.is_extern and self.pure_comptime_depth > 0) {
                try self.emitDiagnosticSimple(
                    .e0503_forbidden_comptime_operation,
                    self.getAstNodeSpan(call_id),
                    "cannot invoke `extern` FFI function during `comptime` evaluation",
                    "external FFI call is forbidden at compile time",
                );
            }
            // Include uninstantiated enclosing nominal `type_param_sym`s when calling `Box(42)` or `Box.new(42)`:
            if (self.pool.getFlags(fn_ty).has_type_vars and !callee_sym.scope_id.isNone()) {
                for (self.sym_table.getScopeMembers(callee_sym.scope_id)) |mem_idx| {
                    const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError()) {
                        try declared_type_params.append(self.allocator, mem_sym.type_id);
                    }
                }
                if (declared_type_params.items.len > 0) {
                    const parent_scope = self.sym_table.scope_arena.getScope(callee_sym.scope_id).parent;
                    if (!parent_scope.isNone()) {
                        for (self.sym_table.getScopeMembers(parent_scope)) |p_mem_idx| {
                            if (self.sym_table.getSymbol(p_mem_idx).target_scope == callee_sym.scope_id) {
                                enclosing_owner_sym_idx = p_mem_idx;
                                break;
                            }
                        }
                    }
                }
            }
            if (!callee_sym.target_scope.isNone()) {
                for (self.sym_table.getScopeMembers(callee_sym.target_scope)) |mem_idx| {
                    const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind == .type_param_sym and !mem_sym.type_id.isError()) {
                        try declared_type_params.append(self.allocator, mem_sym.type_id);
                    }
                }
            }
        }
        const declared_tp_count = declared_type_params.items.len;

        const sig = self.pool.getFnSignatureView(fn_ty) orelse {
            for (explicit_type_args) |type_node_id| _ = try self.resolveTypeAst(type_node_id);
            for (args) |arg_id| {
                _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
            }
            return .err_ty;
        };

        var subst = SubstitutionMap{};
        defer subst.deinit(self.allocator);

        // Bind explicit `[TypeArgs]` if supplied at the call site:
        const resolved_explicit_tys = try self.allocator.alloc(TypeId, explicit_type_args.len);
        defer if (resolved_explicit_tys.len > 0) self.allocator.free(resolved_explicit_tys);
        for (explicit_type_args, 0..) |type_node_id, i| {
            const resolved_ty = try self.resolveTypeAst(type_node_id);
            resolved_explicit_tys[i] = resolved_ty;
            if (i < declared_tp_count and !resolved_ty.isError()) {
                const tp_id = declared_type_params.items[i];
                const tp_node = self.pool.getNode(tp_id);
                const grp_ty = TypeId.fromInt(tp_node.lhs);
                var sat = checkGroupSatisfaction(
                    self.pool,
                    self.sym_table,
                    self.target_layout,
                    resolved_ty,
                    grp_ty,
                );
                if (sat == .rejected and self.pool.getTag(grp_ty) == .trait_ty) {
                    if (try self.hasTraitImplementation(resolved_ty, grp_ty, 0)) {
                        sat = .matched_exact;
                    }
                }
                if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
                    try self.emitGroupConstraintError(
                        self.getAstNodeSpan(type_node_id),
                        resolved_ty,
                        grp_ty,
                        sat == .rejected_distinct_without_tilde,
                    );
                }
                try subst.put(self.allocator, tp_id, resolved_ty, self.getAstNodeSpan(type_node_id));
            }
        }

        if (self.unsafe_depth == 0 and self.pure_comptime_depth == 0) {
            if (!callee_sym_idx.isNone()) {
                const resolved_callee_idx = self.unwrapAliasSymbolIdx(callee_sym_idx);
                const resolved_callee = self.sym_table.getSymbol(resolved_callee_idx).*;
                const ffi_contract = self.sym_table.getFfiContract(resolved_callee_idx);
                const is_trusted_ffi = if (ffi_contract) |fc| (fc.is_trusted and !fc.is_unsafe_extern) else false;
                const is_unsafe_fn = if (ffi_contract) |fc| fc.is_unsafe_extern else false;
                const is_foreign_extern_callee = resolved_callee.flags.is_extern and
                    resolved_callee.flags.is_prototype_only;
                if (is_unsafe_fn) {
                    try self.emitDiagnosticSimple(
                        .e0324_package_capability_violation,
                        self.getAstNodeSpan(call_id),
                        "calling `unsafe` function requires an `unsafe` block or enclosing `unsafe fn`",
                        "`unsafe` function called outside `unsafe` context",
                    );
                } else if (is_foreign_extern_callee and !is_trusted_ffi) {
                    try self.emitDiagnosticSimple(
                        .e0324_package_capability_violation,
                        self.getAstNodeSpan(call_id),
                        "calling untrusted foreign `extern` function requires an `unsafe` block or `@trusted` contract",
                        "untrusted `extern` call outside `unsafe` context",
                    );
                }
            } else if (sig.is_c_abi) {
                try self.emitDiagnosticSimple(
                    .e0324_package_capability_violation,
                    self.getAstNodeSpan(call_id),
                    "calling `extern \"C\" fn` pointer requires an `unsafe` block or enclosing `unsafe fn`",
                    "foreign function pointer called outside `unsafe` context",
                );
            }
        }

        const param_specs = if (!callee_sym_idx.isNone())
            self.sym_table.getFnParamSpecs(self.unwrapAliasSymbolIdx(callee_sym_idx))
        else
            &.{};

        var param_offset: usize = 0;
        if (optional_self_recv != null) {
            if (param_specs.len > 0) {
                if (std.mem.eql(u8, param_specs[0].name_text, "self")) {
                    param_offset = 1;
                }
            } else if (!callee_sym_idx.isNone()) {
                const callee_sym = self.sym_table.getSymbol(callee_sym_idx).*;
                var has_first_param = false;
                if (!callee_sym.target_scope.isNone()) {
                    for (self.sym_table.getScopeMembers(callee_sym.target_scope)) |mem_idx| {
                        const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                        if (mem_sym.kind == .param_sym) {
                            has_first_param = true;
                            if (std.mem.eql(u8, mem_sym.name_text, "self")) {
                                param_offset = 1;
                            }
                            break;
                        }
                    }
                }
                if (!has_first_param and sig.paramCount() == args.len + 1) {
                    param_offset = 1;
                }
            } else if (sig.paramCount() == args.len + 1) {
                param_offset = 1;
            }
        } else if (!callee_sym_idx.isNone() and self.sym_table.getSymbol(callee_sym_idx).extra_flags.is_builder_item) {
            // `SE-22` `@builder_item` implicit builder receiver injection (`E0436` if outside matching `@builder` block):
            if (sig.paramCount() >= 1) {
                param_offset = 1;
                const expected_builder_ty = self.unwrapRefType(self.pool.unwrapUnderlyingType(sig.getParamType(0)));
                const exp_base_ty = self.pool.unwrapNominalInstantiationBase(expected_builder_ty);
                var matched_builder_ty: ?TypeId = null;
                var b_idx: usize = @min(@as(usize, self.active_builder_depth), self.active_builder_stack.len);
                while (b_idx > 0) {
                    b_idx -= 1;
                    const cand_b_ty = self.active_builder_stack[b_idx];
                    if (cand_b_ty == expected_builder_ty or
                        self.pool.unwrapNominalInstantiationBase(cand_b_ty) == exp_base_ty)
                    {
                        matched_builder_ty = cand_b_ty;
                        break;
                    }
                }
                if (matched_builder_ty) |act_b_ty| {
                    try self.implicit_builder_item_calls.put(self.allocator, call_id.asInt(), 0);
                    if (self.pool.getFlags(expected_builder_ty).has_type_vars and !act_b_ty.isError()) {
                        _ = try self.unifyParamTypeWithArg(
                            expected_builder_ty,
                            act_b_ty,
                            self.getAstNodeSpan(call_id),
                            &subst,
                            false,
                        );
                    }
                } else {
                    var b_buf: [80]u8 = undefined;
                    const b_str = self.pool.formatType(expected_builder_ty, self.sym_table, &b_buf);
                    var msg_buf: [224]u8 = undefined;
                    const msg = std.fmt.bufPrint(
                        &msg_buf,
                        "`@builder_item` function `{s}` can only be called unqualified inside a `@builder` block for `{s}`",
                        .{ self.sym_table.getSymbol(callee_sym_idx).name_text, b_str },
                    ) catch "`@builder_item` function called outside matching `@builder` scope";
                    try self.emitDiagnosticSimple(
                        .e0436_builder_item_outside_scope,
                        self.getAstNodeSpan(call_id),
                        msg,
                        "no active `@builder` receiver in scope",
                    );
                }
            }
        }

        if (param_offset == 1 and sig.paramCount() >= 1) {
            if (optional_self_recv) |recv_id| {
                const recv_param_ty = self.pool.unwrapUnderlyingType(sig.getParamType(0));
                const is_mut_self = sig.getParamMode(0) == .inout_mode or
                    self.pool.getTag(recv_param_ty) == .mut_ref_ty;
                if (is_mut_self and recv_id.asInt() < self.node_types.len) {
                    const recv_ty = self.node_types[recv_id.asInt()];
                    if (!self.isScrutineeMutRefBindable(recv_id, recv_ty)) {
                        try self.emitDiagnosticSimple(
                            .e0305_exclusivity_violation,
                            self.getAstNodeSpan(recv_id),
                            "cannot invoke `&mut self` method on an immutable binding or `&T` borrow",
                            "receiver requires a mutable `var` binding or `&mut` borrow",
                        );
                    }
                }
            }
        }

        const total_params: usize = sig.paramCount() -| param_offset;
        const call_cst = self.ast_arena.getCstOrigin(call_id);
        const has_trailing_view_block = !call_cst.isNone() and
            call_cst.asInt() < self.cst_arena.countNodes() and
            self.cst_arena.getNode(call_cst).kind == .view_block_expr and
            args.len > 0 and
            self.ast_arena.getNode(args[args.len - 1]).tag == .block and
            total_params > 0 and
            blk_vb_sig: {
                const last_p_ty = self.pool.unwrapUnderlyingType(sig.getParamType(param_offset + total_params - 1));
                const last_tag = self.pool.getTag(last_p_ty);
                break :blk_vb_sig last_tag == .closure_ty or last_tag == .fn_ty;
            };

        var has_any_named_arg = false;
        for (args) |arg_id| {
            if (!arg_id.isNone() and arg_id.asInt() < self.ast_arena.countNodes() and
                self.ast_arena.getNode(arg_id).tag == .named_arg)
            {
                has_any_named_arg = true;
                break;
            }
        }
        var has_any_default_param = false;
        var has_any_kw_only_param = false;
        if (param_specs.len > param_offset) {
            for (param_specs[param_offset..@min(param_specs.len, param_offset + total_params)]) |spec| {
                if (spec.has_default) has_any_default_param = true;
                if (spec.is_keyword_only) has_any_kw_only_param = true;
            }
        }

        // Collect fallback parameter names from `.param_sym` scope members when `param_specs` is empty:
        var fallback_param_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer fallback_param_names.deinit(self.allocator);
        if (param_specs.len == 0 and has_any_named_arg and !callee_sym_idx.isNone()) {
            const callee_sym = self.sym_table.getSymbol(callee_sym_idx).*;
            if (!callee_sym.target_scope.isNone()) {
                var skipped_self: usize = 0;
                for (self.sym_table.getScopeMembers(callee_sym.target_scope)) |mem_idx| {
                    const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind == .param_sym) {
                        if (skipped_self < param_offset) {
                            skipped_self += 1;
                            continue;
                        }
                        try fallback_param_names.append(self.allocator, mem_sym.name_text);
                    }
                }
            }
        }

        var mapped_slots: std.ArrayListUnmanaged(CallArgSlot) = .empty;
        defer mapped_slots.deinit(self.allocator);
        var wrapper_nodes: std.ArrayListUnmanaged(NodeIndex) = .empty;
        defer wrapper_nodes.deinit(self.allocator);

        if (!has_any_named_arg and !has_any_default_param and !has_any_kw_only_param and !sig.is_variadic) {
            if (args.len != total_params) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(call_id),
                    "function call argument count does not match parameter signature",
                    "incorrect number of arguments passed to function",
                );
                for (args) |arg_id| {
                    _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                }
                return subst.apply(self.pool, sig.ret_ty);
            }
            try mapped_slots.ensureTotalCapacity(self.allocator, args.len);
            try wrapper_nodes.ensureTotalCapacity(self.allocator, args.len);
            for (args, 0..) |arg_id, i| {
                mapped_slots.appendAssumeCapacity(.{
                    .param_index = @intCast(i),
                    .arg_ast_node = arg_id,
                    .is_named = false,
                });
                wrapper_nodes.appendAssumeCapacity(arg_id);
            }
        } else if (sig.is_variadic and !has_any_named_arg and !has_any_default_param and !has_any_kw_only_param) {
            if (args.len < total_params) {
                try self.emitDiagnosticSimple(
                    .e0401_type_mismatch,
                    self.getAstNodeSpan(call_id),
                    "too few arguments supplied to C variadic (`...`) function call",
                    "missing fixed parameter(s) before `...`",
                );
                for (args) |arg_id| _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                return subst.apply(self.pool, sig.ret_ty);
            }
            try mapped_slots.ensureTotalCapacity(self.allocator, total_params);
            try wrapper_nodes.ensureTotalCapacity(self.allocator, total_params);
            for (args[0..total_params], 0..) |arg_id, i| {
                mapped_slots.appendAssumeCapacity(.{
                    .param_index = @intCast(i),
                    .arg_ast_node = arg_id,
                    .is_named = false,
                });
                wrapper_nodes.appendAssumeCapacity(arg_id);
            }
            for (args[total_params..]) |var_arg_id| {
                try self.checkFfiVariadicArg(self.unwrapCallArgExpr(var_arg_id));
            }
        } else {
            if (has_any_named_arg and callee_sym_idx.isNone()) {
                try self.emitDiagnosticSimple(
                    .e0419_invalid_call_arguments,
                    self.getAstNodeSpan(call_id),
                    "named arguments are not supported on indirect function pointer or closure calls",
                    "use positional arguments when calling a function value",
                );
                for (args) |arg_id| {
                    _ = try self.synthExpr(self.unwrapCallArgExpr(arg_id));
                }
                return subst.apply(self.pool, sig.ret_ty);
            }

            const is_slot_filled = try self.allocator.alloc(bool, total_params);
            defer if (is_slot_filled.len > 0) self.allocator.free(is_slot_filled);
            @memset(is_slot_filled, false);

            var has_seen_named = false;
            var has_reordered = false;
            var has_mapping_error = false;

            for (args, 0..) |raw_arg_id, src_idx| {
                const is_this_trailing_block = has_trailing_view_block and src_idx + 1 == args.len;
                const raw_node = self.ast_arena.getNode(raw_arg_id);
                if (raw_node.tag == .named_arg) {
                    has_seen_named = true;
                    const val_id = self.unwrapCallArgExpr(raw_arg_id);
                    const label_tok = raw_node.main_token;
                    const label_text = symbol_resolver.extractTokenSlice(self.source, self.token_buffer, label_tok);
                    const label_span = self.token_buffer.getTokenSpan(self.file_id, label_tok);

                    var matched_rel_idx: ?usize = null;
                    var p_rel: usize = 0;
                    while (p_rel < total_params) : (p_rel += 1) {
                        const p_name: []const u8 = if (param_offset + p_rel < param_specs.len)
                            param_specs[param_offset + p_rel].name_text
                        else if (p_rel < fallback_param_names.items.len)
                            fallback_param_names.items[p_rel]
                        else
                            "";
                        if (p_name.len > 0 and std.mem.eql(u8, p_name, label_text)) {
                            matched_rel_idx = p_rel;
                            break;
                        }
                    }

                    if (matched_rel_idx == null) {
                        var msg_buf: [160]u8 = undefined;
                        const msg = std.fmt.bufPrint(
                            &msg_buf,
                            "unknown parameter label `{s}` in function call",
                            .{label_text},
                        ) catch "unknown parameter label in function call";
                        try self.emitDiagnosticSimple(
                            .e0419_invalid_call_arguments,
                            label_span,
                            msg,
                            "no parameter with this name on callee",
                        );
                        _ = try self.synthExpr(val_id);
                        has_mapping_error = true;
                        continue;
                    }

                    const rel_idx = matched_rel_idx.?;
                    if (param_offset + rel_idx < param_specs.len and param_specs[param_offset + rel_idx].is_positional_only) {
                        var pos_msg_buf: [192]u8 = undefined;
                        const pos_msg = std.fmt.bufPrint(
                            &pos_msg_buf,
                            "positional-only parameter `{s}` (declared before `/`) cannot be passed by name",
                            .{label_text},
                        ) catch "positional-only parameter cannot be passed with a label";
                        try self.emitDiagnosticSimple(
                            .e0428_named_arg_for_positional_only,
                            label_span,
                            pos_msg,
                            "remove parameter label for positional-only parameter",
                        );
                    }
                    if (is_slot_filled[rel_idx]) {
                        var msg_buf: [160]u8 = undefined;
                        const msg = std.fmt.bufPrint(
                            &msg_buf,
                            "parameter `{s}` specified multiple times in call",
                            .{label_text},
                        ) catch "duplicate argument for parameter";
                        try self.emitDiagnosticSimple(
                            .e0419_invalid_call_arguments,
                            label_span,
                            msg,
                            "argument already supplied earlier in this call",
                        );
                        _ = try self.synthExpr(val_id);
                        has_mapping_error = true;
                        continue;
                    }

                    is_slot_filled[rel_idx] = true;
                    if (rel_idx != mapped_slots.items.len) has_reordered = true;
                    try mapped_slots.append(self.allocator, .{
                        .param_index = @intCast(rel_idx),
                        .arg_ast_node = val_id,
                        .is_named = true,
                    });
                    try wrapper_nodes.append(self.allocator, raw_arg_id);
                } else if (is_this_trailing_block) {
                    const trailing_rel_idx = total_params - 1;
                    if (is_slot_filled[trailing_rel_idx]) {
                        try self.emitDiagnosticSimple(
                            .e0419_invalid_call_arguments,
                            self.getAstNodeSpan(raw_arg_id),
                            "trailing `{ … }` block duplicates an explicit callback argument",
                            "callback parameter already supplied",
                        );
                        _ = try self.synthExpr(raw_arg_id);
                        has_mapping_error = true;
                        continue;
                    }
                    is_slot_filled[trailing_rel_idx] = true;
                    if (trailing_rel_idx != mapped_slots.items.len) has_reordered = true;
                    try mapped_slots.append(self.allocator, .{
                        .param_index = @intCast(trailing_rel_idx),
                        .arg_ast_node = raw_arg_id,
                        .is_named = false,
                    });
                    try wrapper_nodes.append(self.allocator, raw_arg_id);
                } else {
                    if (has_seen_named) {
                        try self.emitDiagnosticSimple(
                            .e0419_invalid_call_arguments,
                            self.getAstNodeSpan(raw_arg_id),
                            "positional argument cannot follow a named argument",
                            "supply a parameter label or move positional arguments before named arguments",
                        );
                        _ = try self.synthExpr(raw_arg_id);
                        has_mapping_error = true;
                        continue;
                    }
                    if (src_idx >= total_params) {
                        if (sig.is_variadic) {
                            try self.checkFfiVariadicArg(raw_arg_id);
                            continue;
                        }
                        try self.emitDiagnosticSimple(
                            if (has_any_named_arg) .e0419_invalid_call_arguments else .e0401_type_mismatch,
                            self.getAstNodeSpan(call_id),
                            "too many arguments supplied to function call",
                            "unexpected extra argument",
                        );
                        _ = try self.synthExpr(raw_arg_id);
                        has_mapping_error = true;
                        continue;
                    }
                    if (param_offset + src_idx < param_specs.len and param_specs[param_offset + src_idx].is_keyword_only) {
                        const kw_name = param_specs[param_offset + src_idx].name_text;
                        var kw_msg_buf: [200]u8 = undefined;
                        const kw_msg = std.fmt.bufPrint(
                            &kw_msg_buf,
                            "keyword-only parameter `{s}` (declared after `*`) must be passed by name as `{s}: …`",
                            .{ kw_name, kw_name },
                        ) catch "keyword-only parameter must be passed with a parameter label";
                        try self.emitDiagnosticSimple(
                            .e0429_positional_arg_for_keyword_only,
                            self.getAstNodeSpan(raw_arg_id),
                            kw_msg,
                            "add explicit `name: value` label here",
                        );
                    }
                    is_slot_filled[src_idx] = true;
                    try mapped_slots.append(self.allocator, .{
                        .param_index = @intCast(src_idx),
                        .arg_ast_node = raw_arg_id,
                        .is_named = false,
                    });
                    try wrapper_nodes.append(self.allocator, raw_arg_id);
                }
            }

            var has_omitted_default = false;
            var check_rel: usize = 0;
            while (check_rel < total_params) : (check_rel += 1) {
                if (is_slot_filled[check_rel]) continue;
                const has_def = param_offset + check_rel < param_specs.len and
                    param_specs[param_offset + check_rel].has_default;
                if (has_def) {
                    has_omitted_default = true;
                } else if (!has_mapping_error) {
                    const missing_name: []const u8 = if (param_offset + check_rel < param_specs.len)
                        param_specs[param_offset + check_rel].name_text
                    else if (check_rel < fallback_param_names.items.len)
                        fallback_param_names.items[check_rel]
                    else
                        "";
                    var msg_buf: [192]u8 = undefined;
                    const msg = if (missing_name.len > 0)
                        std.fmt.bufPrint(
                            &msg_buf,
                            "missing required argument for parameter `{s}`",
                            .{missing_name},
                        ) catch "missing required argument in call"
                    else
                        "function call argument count does not match parameter signature";
                    try self.emitDiagnosticSimple(
                        if (has_any_named_arg or has_any_default_param)
                            .e0419_invalid_call_arguments
                        else
                            .e0401_type_mismatch,
                        self.getAstNodeSpan(call_id),
                        msg,
                        "required parameter omitted at call site",
                    );
                    has_mapping_error = true;
                }
            }

            if (!has_mapping_error) {
                try self.recordCallArgMapping(
                    call_id,
                    callee_sym_idx,
                    mapped_slots.items,
                    @intCast(total_params),
                    has_reordered or has_omitted_default,
                );
            }
        }

        // Pass 1: Synthesize non-contextual arguments and populate `SubstitutionMap`:
        for (mapped_slots.items, 0..) |slot, slot_i| {
            const arg_id = slot.arg_ast_node;
            const wrapper_id = wrapper_nodes.items[slot_i];
            const param_idx: usize = @as(usize, slot.param_index) + param_offset;
            const param_ty = sig.getParamType(param_idx);
            const param_mode = sig.getParamMode(param_idx);
            const arg_node = self.ast_arena.getNode(arg_id);
            const is_deferred_trailing_block = has_trailing_view_block and arg_id == args[args.len - 1];
            if (arg_node.tag == .contextual_variant or arg_node.tag == .closure_expr or is_deferred_trailing_block) {
                continue;
            }

            if (param_mode == .set_mode) {
                const is_out_arg = arg_node.tag == .unary_expr and
                    !arg_node.main_token.isNone() and
                    self.token_buffer.getToken(arg_node.main_token).kind == .amp and
                    self.classifyAmpUnaryModifier(self.ast_arena.getCstOrigin(arg_id)) == .out_ref;
                if (!is_out_arg) {
                    try self.emitDiagnosticSimple(
                        .e0422_out_param_contract_violation,
                        self.getAstNodeSpan(arg_id),
                        "argument to `&out` parameter must be passed explicitly as `&out <var_place>`",
                        "expected `&out` mutable place argument here",
                    );
                    const syn_ty = try self.synthExpr(arg_id);
                    if (wrapper_id != arg_id) _ = self.recordNodeType(wrapper_id, syn_ty);
                    continue;
                }
            }

            const is_comptime_param = param_idx < 64 and
                (comptime_param_mask & (@as(u64, 1) << @intCast(param_idx))) != 0;
            const prev_pure = self.pure_comptime_depth;
            const prev_bound = self.comptime_boundary_scope_depth;
            if (is_comptime_param) {
                if (prev_pure == 0) {
                    self.comptime_boundary_scope_depth = if (self.current_scope.isNone())
                        0
                    else
                        self.sym_table.scope_arena.getScope(self.current_scope).depth;
                }
                self.pure_comptime_depth = prev_pure + 1;
            }
            defer if (is_comptime_param) {
                self.pure_comptime_depth = prev_pure;
                self.comptime_boundary_scope_depth = prev_bound;
            };

            var resolved_arg_ty: TypeId = .err_ty;
            if (self.pool.getFlags(param_ty).has_type_vars) {
                if (explicit_type_args.len > 0) {
                    const explicit_inst_param = try subst.apply(self.pool, param_ty);
                    if (!self.pool.getFlags(explicit_inst_param).has_type_vars) {
                        const checked_ty = try self.checkExpr(arg_id, explicit_inst_param);
                        if (wrapper_id != arg_id) _ = self.recordNodeType(wrapper_id, checked_ty);
                        resolved_arg_ty = checked_ty;
                    }
                }
                if (resolved_arg_ty.isError()) {
                    const raw_arg_ty = try self.synthExpr(arg_id);
                    if (wrapper_id != arg_id) _ = self.recordNodeType(wrapper_id, raw_arg_ty);
                    if (!raw_arg_ty.isError()) {
                        const concrete_arg_ty = self.materializeUntypedType(raw_arg_ty);
                        _ = try self.unifyParamTypeWithArg(
                            param_ty,
                            concrete_arg_ty,
                            self.getAstNodeSpan(arg_id),
                            &subst,
                            true,
                        );
                        resolved_arg_ty = concrete_arg_ty;
                    }
                }
            } else {
                const checked_ty = try self.checkExpr(arg_id, param_ty);
                if (wrapper_id != arg_id) _ = self.recordNodeType(wrapper_id, checked_ty);
                resolved_arg_ty = checked_ty;
            }

            if (param_mode == .sink_mode) {
                const check_own_ty = if (!resolved_arg_ty.isError())
                    resolved_arg_ty
                else
                    try subst.apply(self.pool, param_ty);
                try self.verifyCallSiteOwnArgument(arg_id, check_own_ty);
            }
        }

        // Pass 2: Check contextual variants, closures, and trailing `@builder` blocks against instantiated parameter types:
        for (mapped_slots.items, 0..) |slot, slot_i| {
            const arg_id = slot.arg_ast_node;
            const wrapper_id = wrapper_nodes.items[slot_i];
            const arg_node = self.ast_arena.getNode(arg_id);
            const is_deferred_trailing_block = has_trailing_view_block and arg_id == args[args.len - 1];
            if (arg_node.tag != .contextual_variant and arg_node.tag != .closure_expr and !is_deferred_trailing_block) {
                continue;
            }
            const param_idx: usize = @as(usize, slot.param_index) + param_offset;
            const is_comptime_param = param_idx < 64 and
                (comptime_param_mask & (@as(u64, 1) << @intCast(param_idx))) != 0;
            const prev_pure = self.pure_comptime_depth;
            const prev_bound = self.comptime_boundary_scope_depth;
            if (is_comptime_param) {
                if (prev_pure == 0) {
                    self.comptime_boundary_scope_depth = if (self.current_scope.isNone())
                        0
                    else
                        self.sym_table.scope_arena.getScope(self.current_scope).depth;
                }
                self.pure_comptime_depth = prev_pure + 1;
            }
            defer if (is_comptime_param) {
                self.pure_comptime_depth = prev_pure;
                self.comptime_boundary_scope_depth = prev_bound;
            };

            const inst_param_ty = try subst.apply(self.pool, sig.getParamType(param_idx));
            if (is_deferred_trailing_block) {
                const inst_sig = self.pool.getFnSignatureView(self.pool.unwrapUnderlyingType(inst_param_ty));
                const is_builder_param = (param_idx < param_specs.len and param_specs[param_idx].is_builder) or
                    (inst_sig != null and inst_sig.?.contracts.has_builder);
                if (inst_sig) |cb_sig| {
                    var has_pushed_builder = false;
                    if (is_builder_param and cb_sig.paramCount() >= 1) {
                        const builder_state_ty = self.unwrapRefType(
                            self.pool.unwrapUnderlyingType(cb_sig.getParamType(0)),
                        );
                        if (!builder_state_ty.isError() and self.active_builder_depth < self.active_builder_stack.len) {
                            self.active_builder_stack[self.active_builder_depth] = builder_state_ty;
                            self.active_builder_depth += 1;
                            has_pushed_builder = true;
                        }
                        try self.builder_block_calls.put(self.allocator, call_id.asInt(), builder_state_ty);
                    } else if (cb_sig.paramCount() == 0) {
                        try self.builder_block_calls.put(self.allocator, call_id.asInt(), .unit_ty);
                    }
                    defer if (has_pushed_builder) {
                        self.active_builder_depth -= 1;
                    };
                    if (self.pool.getFlags(cb_sig.ret_ty).has_type_vars) {
                        const blk_ty = self.materializeUntypedType(try self.synthExpr(arg_id));
                        if (!blk_ty.isError()) {
                            _ = try self.unifyParamTypeWithArg(
                                cb_sig.ret_ty,
                                blk_ty,
                                self.getAstNodeSpan(arg_id),
                                &subst,
                                true,
                            );
                        }
                    } else {
                        _ = try self.checkExpr(arg_id, cb_sig.ret_ty);
                    }
                    if (wrapper_id != arg_id) _ = self.recordNodeType(wrapper_id, inst_param_ty);
                    continue;
                }
            }

            const checked_ty = try self.checkExpr(arg_id, inst_param_ty);
            if (wrapper_id != arg_id) _ = self.recordNodeType(wrapper_id, checked_ty);
            if (sig.getParamMode(param_idx) == .sink_mode) {
                try self.verifyCallSiteOwnArgument(arg_id, if (!checked_ty.isError()) checked_ty else inst_param_ty);
            }
        }

        // Validate instantiated parameter types against omitted default initializers on generic callees:
        if (has_any_default_param and mapped_slots.items.len < total_params and
            (declared_tp_count > 0 or explicit_type_args.len > 0 or
                subst.inline_len > 0 or subst.overflow_entries.items.len > 0))
        {
            const filled_mask = try self.allocator.alloc(bool, total_params);
            defer if (filled_mask.len > 0) self.allocator.free(filled_mask);
            @memset(filled_mask, false);
            for (mapped_slots.items) |slot| {
                if (slot.param_index < total_params) filled_mask[slot.param_index] = true;
            }
            var def_rel: usize = 0;
            while (def_rel < total_params) : (def_rel += 1) {
                if (filled_mask[def_rel]) continue;
                const param_idx = param_offset + def_rel;
                if (param_idx >= param_specs.len) continue;
                const spec = param_specs[param_idx];
                if (!spec.has_default) continue;
                const inst_param_ty = try subst.apply(self.pool, sig.getParamType(param_idx));
                const raw_def_ty = spec.default_type_id;
                if (!inst_param_ty.isError() and !raw_def_ty.isError()) {
                    const inst_def_ty = try subst.apply(self.pool, raw_def_ty);
                    if (self.pool.getFlags(inst_param_ty).has_type_vars) {
                        _ = try self.unifyParamTypeWithArg(
                            inst_param_ty,
                            self.materializeUntypedType(inst_def_ty),
                            self.getAstNodeSpan(call_id),
                            &subst,
                            true,
                        );
                    } else {
                        _ = try self.checkTypeCompatibility(call_id, inst_def_ty, inst_param_ty);
                        if (spec.decl_file_id == self.file_id and !spec.default_ast_node.isNone() and
                            spec.default_ast_node.asInt() < self.ast_arena.countNodes())
                        {
                            const def_ast = self.ast_arena.getNode(spec.default_ast_node);
                            if (def_ast.tag == .contextual_variant) {
                                const def_args = self.getNodeExtraSlice(spec.default_ast_node, true);
                                if (def_args.len == 1 and self.pool.getTag(inst_param_ty) == .optional_ty) {
                                    const inner_arg = NodeIndex.fromInt(def_args[0]);
                                    const inner_tag = self.ast_arena.getNode(inner_arg).tag;
                                    const opt_inner_ty = TypeId.fromInt(self.pool.getNode(inst_param_ty).lhs);
                                    if (inner_tag == .int_lit) {
                                        _ = try self.checkTypeCompatibility(call_id, .untyped_int_ty, opt_inner_ty);
                                    } else if (inner_tag == .float_lit) {
                                        _ = try self.checkTypeCompatibility(call_id, .untyped_float_ty, opt_inner_ty);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // `SE-10A`: Fill any remaining unbound generic type parameters from trailing generic defaults:
        if (declared_tp_count > 0 and !callee_sym_idx.isNone()) {
            var tp_cursor: usize = 0;
            if (!enclosing_owner_sym_idx.isNone()) {
                const owner_specs = self.sym_table.getGenericParamSpecs(enclosing_owner_sym_idx);
                for (owner_specs) |g_spec| {
                    if (g_spec.is_const) continue;
                    if (tp_cursor < declared_tp_count) {
                        const tp_id = declared_type_params.items[tp_cursor];
                        if (subst.lookup(tp_id) == null and g_spec.has_default) {
                            const raw_def = try self.resolveGenericDefaultSpec(enclosing_owner_sym_idx, g_spec);
                            const app_def = try subst.apply(self.pool, raw_def);
                            if (!app_def.isError()) {
                                try subst.put(self.allocator, tp_id, app_def, self.getAstNodeSpan(call_id));
                            }
                        }
                        tp_cursor += 1;
                    }
                }
            }
            const fn_gen_specs = self.sym_table.getGenericParamSpecs(callee_sym_idx);
            for (fn_gen_specs) |g_spec| {
                if (g_spec.is_const) continue;
                if (tp_cursor < declared_tp_count) {
                    const tp_id = declared_type_params.items[tp_cursor];
                    if (subst.lookup(tp_id) == null and g_spec.has_default) {
                        const raw_def = try self.resolveGenericDefaultSpec(callee_sym_idx, g_spec);
                        const app_def = try subst.apply(self.pool, raw_def);
                        if (!app_def.isError()) {
                            try subst.put(self.allocator, tp_id, app_def, self.getAstNodeSpan(call_id));
                        }
                    }
                    tp_cursor += 1;
                }
            }
        }

        // Record concrete instantiation tuple in `self.call_instantiations`:
        var inst_tys: std.ArrayListUnmanaged(TypeId) = .empty;
        defer inst_tys.deinit(self.allocator);
        if (declared_tp_count > 0) {
            for (declared_type_params.items) |tp_id| {
                try inst_tys.append(self.allocator, try subst.apply(self.pool, tp_id));
            }
        } else if (explicit_type_args.len > 0) {
            try inst_tys.appendSlice(self.allocator, resolved_explicit_tys);
        }
        for (subst.inline_entries[0..subst.inline_len]) |entry| {
            const var_tag = self.pool.getTag(entry.var_ty);
            if (var_tag == .bind_once_group_var or var_tag == .bind_many_any_var) {
                try inst_tys.append(self.allocator, entry.concrete_ty);
            }
        }
        for (subst.overflow_entries.items) |entry| {
            const var_tag = self.pool.getTag(entry.var_ty);
            if (var_tag == .bind_once_group_var or var_tag == .bind_many_any_var) {
                try inst_tys.append(self.allocator, entry.concrete_ty);
            }
        }
        if (inst_tys.items.len > 0) {
            try self.recordCallInstantiation(call_id, inst_tys.items);
        }

        const inst_ret_ty = try subst.apply(self.pool, sig.ret_ty);
        if (sig.is_async) {
            const producer_id: u32 = if (!callee_sym_idx.isNone()) callee_sym_idx.asInt() else 0;
            return self.pool.internFuture(inst_ret_ty, producer_id);
        }
        return inst_ret_ty;
    }

    /// Enforces `ADR-22B` `E0420`: passing a named variable/place of `~Copy` type to an `own T` parameter requires `own`.
    fn verifyCallSiteOwnArgument(self: *TypeChecker, arg_id: NodeIndex, arg_ty: TypeId) !void {
        if (arg_ty.isError() or self.isCopyType(arg_ty)) return;
        const arg_node = self.ast_arena.getNode(arg_id);
        if (arg_node.tag == .unary_expr and !arg_node.main_token.isNone() and
            self.token_buffer.getToken(arg_node.main_token).kind == .kw_own)
        {
            return;
        }
        if (!self.isNamedPlaceRequiringCallSiteOwn(arg_id)) return;

        var ty_buf: [96]u8 = undefined;
        const ty_str = self.pool.formatType(arg_ty, self.sym_table, &ty_buf);
        var msg_buf: [224]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "passing non-`Copy` variable of type `{s}` to `own` parameter requires explicit `own` at the call site",
            .{ty_str},
        ) catch "passing non-`Copy` variable to `own` parameter requires explicit `own`";
        const arg_span = self.getAstNodeSpan(arg_id);
        const insert_span = Span.init(arg_span.file_id, arg_span.start_byte, arg_span.start_byte);
        try self.emitDiagnosticWithSingleFix(
            .e0420_missing_call_site_own,
            arg_span,
            msg,
            "add `own` to move ownership into callee",
            "insert `own ` before moved argument",
            insert_span,
            "own ",
        );
    }

    /// Returns `true` when `expr_id` denotes a named local/parameter variable or place projection (as opposed to an rvalue).
    fn isNamedPlaceRequiringCallSiteOwn(self: *const TypeChecker, expr_id: NodeIndex) bool {
        var cur = expr_id;
        var steps: u32 = 0;
        while (steps < 32 and !cur.isNone() and cur.asInt() < self.ast_arena.countNodes()) : (steps += 1) {
            const node = self.ast_arena.getNode(cur);
            switch (node.tag) {
                .ident_expr => {
                    if (cur.asInt() >= self.node_symbols.len) return false;
                    const sym_idx = self.node_symbols[cur.asInt()];
                    if (sym_idx.isNone()) return false;
                    const kind = self.sym_table.getSymbol(sym_idx).kind;
                    return kind == .local_let_sym or kind == .local_var_sym or kind == .param_sym;
                },
                .field_access, .index_expr, .deref_expr => {
                    if (node.lhs.tag != .node) return false;
                    cur = NodeIndex.fromInt(node.lhs.payload);
                },
                else => return false,
            }
        }
        return false;
    }

    /// Validates that a trailing C variadic (`...`) argument is C-ABI safe (`ADR-22F`).
    fn checkFfiVariadicArg(self: *TypeChecker, arg_id: NodeIndex) !void {
        const raw_ty = try self.synthExpr(arg_id);
        if (raw_ty.isError()) return;
        const mat_ty = self.materializeUntypedType(raw_ty);
        if (raw_ty == .untyped_int_ty or raw_ty == .untyped_float_ty) {
            _ = self.recordNodeType(arg_id, mat_ty);
        }
        const unwrapped = self.pool.unwrapUnderlyingType(mat_ty);
        if (unwrapped.isError() or self.pool.getFlags(unwrapped).has_type_vars) return;

        const tag = self.pool.getTag(unwrapped);
        const is_ffi_safe: bool = switch (tag) {
            .primitive => unwrapped.isSizedPrimitive() and unwrapped != .str_ty and unwrapped != .fmt_args_ty,
            .raw_ptr_ty, .fn_ty, .bit_field_ty => true,
            .enum_ty => self.pool.getEnumBackingIntType(unwrapped) != null or
                self.sym_table.getSymbol(SymbolIndex.fromInt(self.pool.getNode(unwrapped).rhs)).contract_flags.is_repr_c,
            .struct_ty, .union_ty => blk_comp: {
                const sym = self.sym_table.getSymbol(SymbolIndex.fromInt(self.pool.getNode(unwrapped).rhs)).*;
                break :blk_comp sym.contract_flags.is_repr_c and self.isCopyType(unwrapped);
            },
            else => false,
        };
        if (!is_ffi_safe) {
            var ty_buf: [96]u8 = undefined;
            const ty_str = self.pool.formatType(mat_ty, self.sym_table, &ty_buf);
            var msg_buf: [224]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &msg_buf,
                "cannot pass non-C-ABI type `{s}` through C variadic `...`; pass a C scalar, raw pointer, or `@repr(C)` `Copy` value",
                .{ty_str},
            ) catch "type is not FFI-safe for C variadic `...` call";
            try self.emitDiagnosticSimple(
                .e0401_type_mismatch,
                self.getAstNodeSpan(arg_id),
                msg,
                "not FFI-safe for C variadic `...`",
            );
        }
    }

    /// Recursively unifies `param_ty` (which may be or contain `.bind_once_group_var`, `.bind_many_any_var`, or `.type_param`)
    /// against `arg_ty`, updating `subst` and optionally emitting `E0401`/`E0402`/`E0404`.
    fn unifyParamTypeWithArg(
        self: *TypeChecker,
        param_ty: TypeId,
        arg_ty: TypeId,
        arg_span: Span,
        subst: *SubstitutionMap,
        is_emitting_diags: bool,
    ) anyerror!bool {
        if (param_ty.isError() or arg_ty.isError()) return true;
        if (param_ty == arg_ty) return true;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return true;
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const p_node = self.pool.getNode(param_ty);
        const a_node = self.pool.getNode(arg_ty);

        if (p_node.tag == .bind_once_group_var or
            p_node.tag == .bind_many_any_var or
            p_node.tag == .type_param)
        {
            var concrete_arg = self.materializeUntypedType(arg_ty);
            const group_ty = TypeId.fromInt(p_node.lhs);
            var sat = checkGroupSatisfaction(
                self.pool,
                self.sym_table,
                self.target_layout,
                concrete_arg,
                group_ty,
            );
            if (sat == .rejected and (a_node.tag == .ref_ty or a_node.tag == .mut_ref_ty) and !self.pool.isOutRef(arg_ty)) {
                const inner_a = self.pool.getNode(TypeId.fromInt(a_node.lhs));
                if (inner_a.tag == .array_ty or inner_a.tag == .soa_array_ty) {
                    const coerced_slice = try self.pool.internSlice(
                        TypeId.fromInt(inner_a.lhs),
                        inner_a.tag == .soa_array_ty,
                    );
                    const coerced_ref = try self.pool.internRef(coerced_slice, a_node.tag == .mut_ref_ty);
                    var slice_sat = checkGroupSatisfaction(
                        self.pool,
                        self.sym_table,
                        self.target_layout,
                        coerced_ref,
                        group_ty,
                    );
                    if (slice_sat == .rejected and a_node.tag == .mut_ref_ty) {
                        const shared_ref = try self.pool.internRef(coerced_slice, false);
                        slice_sat = checkGroupSatisfaction(
                            self.pool,
                            self.sym_table,
                            self.target_layout,
                            shared_ref,
                            group_ty,
                        );
                        if (slice_sat == .matched_exact or slice_sat == .matched_via_tilde) {
                            sat = slice_sat;
                            concrete_arg = shared_ref;
                        }
                    } else if (slice_sat == .matched_exact or slice_sat == .matched_via_tilde) {
                        sat = slice_sat;
                        concrete_arg = coerced_ref;
                    }
                }
            }
            if (sat == .rejected and self.pool.getTag(group_ty) == .trait_ty) {
                if (try self.hasTraitImplementation(concrete_arg, group_ty, 0)) {
                    sat = .matched_exact;
                }
            }
            if (sat == .rejected or sat == .rejected_distinct_without_tilde) {
                if (is_emitting_diags) {
                    try self.emitGroupConstraintError(
                        arg_span,
                        concrete_arg,
                        group_ty,
                        sat == .rejected_distinct_without_tilde,
                    );
                }
                return false;
            }

            if (p_node.tag == .bind_once_group_var or p_node.tag == .type_param) {
                if (subst.lookup(param_ty)) |bound_ty| {
                    if (bound_ty != concrete_arg) {
                        if (is_emitting_diags) {
                            try self.emitBindOnceConflict(
                                arg_span,
                                group_ty,
                                bound_ty,
                                concrete_arg,
                            );
                        }
                        return false;
                    }
                } else {
                    try subst.put(self.allocator, param_ty, concrete_arg, arg_span);
                }
            } else {
                // `bind_many_any_var`: each parameter ordinal binds independently:
                try subst.put(self.allocator, param_ty, concrete_arg, arg_span);
            }
            return true;
        }

        switch (p_node.tag) {
            .ref_ty => {
                if ((a_node.tag == .ref_ty or a_node.tag == .mut_ref_ty) and !self.pool.isOutRef(arg_ty)) {
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
                if (a_node.tag == .mut_ref_ty and self.pool.isOutRef(arg_ty)) {
                    if (is_emitting_diags) {
                        try self.emitDiagnosticSimple(
                            .e0422_out_param_contract_violation,
                            arg_span,
                            "cannot pass `&out` write-only reference to `&T` parameter",
                            "unexpected `&out` reference",
                        );
                    }
                    return false;
                }
            },
            .mut_ref_ty => {
                if (a_node.tag == .mut_ref_ty and self.pool.isOutRef(param_ty) == self.pool.isOutRef(arg_ty)) {
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
                if (self.pool.isOutRef(param_ty) != self.pool.isOutRef(arg_ty)) {
                    if (is_emitting_diags) {
                        try self.emitDiagnosticSimple(
                            .e0422_out_param_contract_violation,
                            arg_span,
                            "mismatched `&out` vs `&mut` reference mode at call site",
                            "expected matching `&out` / `&mut` mode",
                        );
                    }
                    return false;
                }
            },
            .raw_ptr_ty => {
                if (a_node.tag == .raw_ptr_ty and (a_node.rhs != 0 or p_node.rhs == 0)) {
                    if (TypeId.fromInt(p_node.lhs) == .opaque_ty) return true;
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
                if ((a_node.tag == .ref_ty or a_node.tag == .mut_ref_ty) and
                    !self.pool.isOutRef(arg_ty) and
                    (a_node.tag == .mut_ref_ty or p_node.rhs == 0))
                {
                    if (TypeId.fromInt(p_node.lhs) == .opaque_ty) return true;
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
            },
            .slice_ty => {
                if (a_node.tag == .slice_ty) {
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
                if ((a_node.tag == .ref_ty or a_node.tag == .mut_ref_ty) and !self.pool.isOutRef(arg_ty)) {
                    const inner_a = TypeId.fromInt(a_node.lhs);
                    const inner_a_node = self.pool.getNode(inner_a);
                    if (inner_a_node.tag == .slice_ty or inner_a_node.tag == .array_ty) {
                        return self.unifyParamTypeWithArg(
                            TypeId.fromInt(p_node.lhs),
                            TypeId.fromInt(inner_a_node.lhs),
                            arg_span,
                            subst,
                            is_emitting_diags,
                        );
                    }
                }
            },
            .soa_slice_ty => {
                if (a_node.tag == .soa_slice_ty) {
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
                if ((a_node.tag == .ref_ty or a_node.tag == .mut_ref_ty) and !self.pool.isOutRef(arg_ty)) {
                    const inner_a = TypeId.fromInt(a_node.lhs);
                    const inner_a_node = self.pool.getNode(inner_a);
                    if (inner_a_node.tag == .soa_slice_ty or inner_a_node.tag == .soa_array_ty) {
                        return self.unifyParamTypeWithArg(
                            TypeId.fromInt(p_node.lhs),
                            TypeId.fromInt(inner_a_node.lhs),
                            arg_span,
                            subst,
                            is_emitting_diags,
                        );
                    }
                }
            },
            .array_ty, .soa_array_ty => {
                if (a_node.tag == p_node.tag) {
                    if (a_node.rhs == p_node.rhs) {
                        return self.unifyParamTypeWithArg(
                            TypeId.fromInt(p_node.lhs),
                            TypeId.fromInt(a_node.lhs),
                            arg_span,
                            subst,
                            is_emitting_diags,
                        );
                    }
                    if ((p_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) != 0 and
                        (a_node.rhs & SYMBOLIC_ARRAY_LEN_FLAG) == 0)
                    {
                        const const_sym = SymbolId.fromInt(p_node.rhs & ~SYMBOLIC_ARRAY_LEN_FLAG);
                        const len_key = try self.pool.internSymbolicArray(.unit_ty, const_sym, false);
                        const concrete_len_ty = try self.pool.internArray(.unit_ty, a_node.rhs, false);
                        if (subst.lookup(len_key)) |bound_len_ty| {
                            if (bound_len_ty != concrete_len_ty) {
                                if (is_emitting_diags) {
                                    const inst_param = try subst.apply(self.pool, param_ty);
                                    try self.emitTypeMismatch(
                                        arg_span,
                                        inst_param,
                                        self.materializeUntypedType(arg_ty),
                                    );
                                }
                                return false;
                            }
                        } else {
                            try subst.put(self.allocator, len_key, concrete_len_ty, arg_span);
                        }
                        return self.unifyParamTypeWithArg(
                            TypeId.fromInt(p_node.lhs),
                            TypeId.fromInt(a_node.lhs),
                            arg_span,
                            subst,
                            is_emitting_diags,
                        );
                    }
                }
            },
            .optional_ty => {
                if (a_node.tag == .optional_ty) {
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
            },
            .future_ty => {
                if (a_node.tag == .future_ty) {
                    return self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                }
            },
            .result_ty => {
                if (a_node.tag == .result_ty) {
                    const is_ok_match = try self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.lhs),
                        TypeId.fromInt(a_node.lhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                    const is_err_match = try self.unifyParamTypeWithArg(
                        TypeId.fromInt(p_node.rhs),
                        TypeId.fromInt(a_node.rhs),
                        arg_span,
                        subst,
                        is_emitting_diags,
                    );
                    return is_ok_match and is_err_match;
                }
            },
            .tuple_ty => {
                if (a_node.tag == .tuple_ty and p_node.rhs == a_node.rhs) {
                    const p_elems = self.pool.getTupleElements(param_ty);
                    const a_elems = self.pool.getTupleElements(arg_ty);
                    var has_all_elems_matched = true;
                    for (p_elems, 0..) |raw_p, i| {
                        if (!(try self.unifyParamTypeWithArg(
                            TypeId.fromInt(raw_p),
                            TypeId.fromInt(a_elems[i]),
                            arg_span,
                            subst,
                            is_emitting_diags,
                        ))) {
                            has_all_elems_matched = false;
                        }
                    }
                    return has_all_elems_matched;
                }
            },
            .struct_ty, .enum_ty, .union_ty => {
                if (a_node.tag == p_node.tag and p_node.rhs == a_node.rhs) {
                    const p_args = self.pool.getGenericTypeArgs(param_ty);
                    const a_args = self.pool.getGenericTypeArgs(arg_ty);
                    if (p_args.len == a_args.len) {
                        var has_all_args_matched = true;
                        for (p_args, 0..) |raw_p_arg, i| {
                            if (!(try self.unifyParamTypeWithArg(
                                TypeId.fromInt(raw_p_arg),
                                TypeId.fromInt(a_args[i]),
                                arg_span,
                                subst,
                                is_emitting_diags,
                            ))) {
                                has_all_args_matched = false;
                            }
                        }
                        return has_all_args_matched;
                    }
                }
            },
            .fn_ty, .closure_ty => {
                if (a_node.tag == p_node.tag or
                    (p_node.tag == .fn_ty and a_node.tag == .closure_ty) or
                    (p_node.tag == .closure_ty and a_node.tag == .fn_ty))
                {
                    const p_sig = self.pool.getFnSignatureView(param_ty) orelse return false;
                    const a_sig = self.pool.getFnSignatureView(arg_ty) orelse return false;
                    const is_capture_compatible = if (p_node.tag == .fn_ty and a_node.tag == .closure_ty)
                        !a_sig.has_env_capture and a_sig.capture_tier == .copy_tier and !a_sig.is_async
                    else if (p_node.tag == .closure_ty and a_node.tag == .fn_ty)
                        !p_sig.is_async
                    else if (p_node.tag == .closure_ty and a_node.tag == .closure_ty)
                        !(a_sig.capture_tier != .copy_tier and p_sig.capture_tier == .copy_tier) and
                            p_sig.is_async == a_sig.is_async
                    else
                        p_sig.is_async == a_sig.is_async and p_sig.is_variadic == a_sig.is_variadic;

                    if (is_capture_compatible and
                        p_sig.paramCount() == a_sig.paramCount() and
                        std.mem.eql(u32, p_sig.param_modes, a_sig.param_modes))
                    {
                        var has_sig_matched = true;
                        var param_i: usize = 0;
                        while (param_i < p_sig.paramCount()) : (param_i += 1) {
                            if (!(try self.unifyParamTypeWithArg(
                                p_sig.getParamType(param_i),
                                a_sig.getParamType(param_i),
                                arg_span,
                                subst,
                                is_emitting_diags,
                            ))) {
                                has_sig_matched = false;
                            }
                        }
                        if (!(try self.unifyParamTypeWithArg(
                            p_sig.ret_ty,
                            a_sig.ret_ty,
                            arg_span,
                            subst,
                            is_emitting_diags,
                        ))) {
                            has_sig_matched = false;
                        }
                        if (!has_sig_matched) return false;
                        if (a_sig.contracts.isSatisfying(p_sig.contracts)) {
                            return true;
                        }
                        if (is_emitting_diags) {
                            try self.emitFnContractCoercionError(
                                arg_span,
                                arg_ty,
                                try subst.apply(self.pool, param_ty),
                                a_sig.contracts,
                                p_sig.contracts,
                            );
                        }
                        return false;
                    }
                }
            },
            else => {},
        }

        if (is_emitting_diags) {
            const inst_param = try subst.apply(self.pool, param_ty);
            try self.emitTypeMismatch(arg_span, inst_param, self.materializeUntypedType(arg_ty));
        }
        return false;
    }

    /// Synthesizes or checks an `if` / `else` expression (`if_expr`).
    fn synthOrCheckIfExpr(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_ty: TypeId,
    ) anyerror!TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const saved_scope = self.current_scope;
        const if_scope = try self.sym_table.scope_arena.allocScope(
            .condition_scope,
            self.current_scope,
            .NONE,
            self.file_id,
            .{},
        );
        self.current_scope = if_scope;
        defer self.current_scope = saved_scope;

        if (ast_node.lhs.tag == .node) {
            try self.checkConditionHeader(NodeIndex.fromInt(ast_node.lhs.payload));
        }

        if (ast_node.rhs.tag == .node) {
            // `if` without `else` always evaluates to `()` (`.unit_ty`):
            _ = try self.checkBlock(NodeIndex.fromInt(ast_node.rhs.payload), .unit_ty, false);
            try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, if_scope, self.interner, self.diagnostic_sink);
            return self.recordNodeType(expr_id, .unit_ty);
        }

        const branches = self.getNodeExtraSlice(expr_id, true);
        const then_id = if (branches.len >= 1) NodeIndex.fromInt(branches[0]) else .none;
        const else_id = if (branches.len >= 2) NodeIndex.fromInt(branches[1]) else .none;

        const then_ty = if (!expected_ty.isError())
            try self.checkBlock(then_id, expected_ty, false)
        else
            try self.checkBlock(then_id, .err_ty, false);

        try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, if_scope, self.interner, self.diagnostic_sink);

        // `else` branch runs in the outer scope (not `if_scope` where `ConditionScope` bindings live):
        self.current_scope = saved_scope;
        const branch_expected = if (!expected_ty.isError())
            expected_ty
        else if (then_ty != .never_ty)
            self.materializeUntypedType(then_ty)
        else
            .err_ty;

        const else_ty = if (!else_id.isNone()) blk: {
            if (self.ast_arena.getNode(else_id).tag == .if_expr) {
                break :blk try self.synthOrCheckIfExpr(else_id, branch_expected);
            }
            break :blk try self.checkBlock(else_id, branch_expected, false);
        } else .unit_ty;

        const final_ty = if (then_ty == .never_ty)
            else_ty
        else if (else_ty == .never_ty)
            then_ty
        else
            self.materializeUntypedType(then_ty);

        return self.recordNodeType(expr_id, final_ty);
    }

    // ------ Maranget Match Exhaustiveness & Unreachable Arms ------

    /// Synthesizes or checks `match scrutinee { arms… }`, verifying exhaustiveness (`E0415`) and reachability (`W0401`).
    fn synthOrCheckMatchExpr(
        self: *TypeChecker,
        expr_id: NodeIndex,
        expected_ty: TypeId,
        is_comptime_match: bool,
    ) anyerror!TypeId {
        const ast_node = self.ast_arena.getNode(expr_id);
        const saved_walrus_pos = self.is_dominating_walrus_pos;
        self.is_dominating_walrus_pos = false;
        defer self.is_dominating_walrus_pos = saved_walrus_pos;

        const scrutinee_id = if (ast_node.lhs.tag == .node) NodeIndex.fromInt(ast_node.lhs.payload) else .none;
        const scrutinee_ty = if (is_comptime_match) blk: {
            const prev_comptime_depth = self.pure_comptime_depth;
            const prev_boundary_depth = self.comptime_boundary_scope_depth;
            if (prev_comptime_depth == 0) {
                self.comptime_boundary_scope_depth = if (self.current_scope.isNone())
                    0
                else
                    self.sym_table.scope_arena.getScope(self.current_scope).depth;
            }
            self.pure_comptime_depth += 1;
            defer {
                self.pure_comptime_depth = prev_comptime_depth;
                self.comptime_boundary_scope_depth = prev_boundary_depth;
            }
            break :blk self.materializeUntypedType(try self.synthExpr(scrutinee_id));
        } else self.materializeUntypedType(try self.synthExpr(scrutinee_id));

        const arm_entries = self.getNodeExtraSlice(expr_id, true);
        const arm_count = arm_entries.len / 2;

        // Detect optional `label: match` (`SE-23`) and guarded arms (`pat if cond => body`) from CST:
        const arm_guards = try self.allocator.alloc(NodeIndex, arm_count);
        defer if (arm_guards.len > 0) self.allocator.free(arm_guards);
        @memset(arm_guards, .none);
        var match_label_tok: TokenIndex = .none;
        var match_cst = self.ast_arena.getCstOrigin(expr_id);
        var unwrap_match_steps: u32 = 0;
        while (unwrap_match_steps < 4 and !match_cst.isNone() and match_cst.asInt() < self.cst_arena.countNodes()) : (unwrap_match_steps += 1) {
            const outer_rec = self.cst_arena.getNode(match_cst);
            if (outer_rec.kind != .local_decl_stmt and outer_rec.kind != .expr_stmt) break;
            const outer_start: usize = match_cst.asInt();
            const outer_end: usize = @min(
                outer_start + @max(@as(usize, outer_rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var inner_match: CstNodeIndex = .none;
            var scan_cur = outer_start + 1;
            while (scan_cur < outer_end) {
                const sub_id = CstNodeIndex.fromInt(@intCast(scan_cur));
                const sub = self.cst_arena.getNode(sub_id);
                const step: usize = @max(@as(usize, sub.subtree_size), 1);
                if (sub.kind == .match_expr or sub.kind == .expr_stmt or sub.kind == .local_decl_stmt) {
                    inner_match = sub_id;
                    break;
                }
                scan_cur += step;
            }
            if (inner_match.isNone()) break;
            match_cst = inner_match;
        }
        if (!match_cst.isNone() and match_cst.asInt() < self.cst_arena.countNodes()) {
            const start_idx: usize = match_cst.asInt();
            const rec = self.cst_arena.getNode(match_cst);
            const end_idx: usize = @min(
                start_idx + @max(@as(usize, rec.subtree_size), 1),
                self.cst_arena.countNodes(),
            );
            var has_passed_match_kw = false;
            var arm_ord: usize = 0;
            var cur = start_idx + 1;
            while (cur < end_idx and arm_ord < arm_guards.len) {
                const sub = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(cur)));
                if (!has_passed_match_kw and sub.kind == .loop_label) {
                    const lbl_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    var lbl_cur = cur + 1;
                    while (lbl_cur < lbl_end) : (lbl_cur += 1) {
                        const lbl_leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(lbl_cur)));
                        if (lbl_leaf.subtree_size <= 1 and !lbl_leaf.token.isNone() and
                            lbl_leaf.token.asInt() < self.token_buffer.countTokens() and
                            symbol_resolver.isIdentifierToken(self.token_buffer.getToken(lbl_leaf.token).kind))
                        {
                            match_label_tok = lbl_leaf.token;
                            break;
                        }
                    }
                    cur = lbl_end;
                    continue;
                }
                if (!has_passed_match_kw and sub.subtree_size <= 1 and !sub.token.isNone() and
                    sub.token.asInt() < self.token_buffer.countTokens() and
                    self.token_buffer.getToken(sub.token).kind == .kw_match)
                {
                    has_passed_match_kw = true;
                }
                if (sub.kind == .match_expr and sub.subtree_size > 1) {
                    cur = @min(cur + @as(usize, sub.subtree_size), end_idx);
                    continue;
                }
                if (sub.kind == .match_arm) {
                    has_passed_match_kw = true;
                    const arm_end = @min(cur + @max(@as(usize, sub.subtree_size), 1), end_idx);
                    var if_pos: ?usize = null;
                    var arrow_pos: ?usize = null;
                    var a_cur = cur + 1;
                    while (a_cur < arm_end) : (a_cur += 1) {
                        const leaf = self.cst_arena.getNode(CstNodeIndex.fromInt(@intCast(a_cur)));
                        if (leaf.subtree_size <= 1 and !leaf.token.isNone() and
                            leaf.token.asInt() < self.token_buffer.countTokens())
                        {
                            const tok_kind = self.token_buffer.getToken(leaf.token).kind;
                            if (tok_kind == .kw_if and if_pos == null and arrow_pos == null) {
                                if_pos = a_cur;
                            } else if (tok_kind == .fat_arrow and arrow_pos == null) {
                                arrow_pos = a_cur;
                                break;
                            }
                        }
                    }
                    if (if_pos) |ip| {
                        const search_end = arrow_pos orelse arm_end;
                        arm_guards[arm_ord] = self.findFirstAstInCstRange(ip + 1, search_end);
                    }
                    arm_ord += 1;
                    cur = arm_end;
                    continue;
                }
                cur += 1;
            }
        }

        const match_label_sym = try self.internLoopLabelToken(match_label_tok);
        const pushed_match_frame = !match_label_sym.isNone() and self.loop_frame_depth < self.loop_frames.len;
        if (pushed_match_frame) {
            self.loop_frames[self.loop_frame_depth] = .{
                .label = match_label_sym,
                .break_ty = if (!expected_ty.isError()) expected_ty else .never_ty,
                .is_unconditional_loop = false,
                .is_comptime_for = false,
                .is_labeled_match = true,
                .match_scrutinee_ty = scrutinee_ty,
                .match_ast_node = expr_id,
                .defer_depth_at_entry = self.defer_depth,
            };
            self.loop_frame_depth += 1;
        }
        defer if (pushed_match_frame) {
            self.loop_frame_depth -= 1;
        };

        // Exhaustiveness state across `bool`, `T?`, `Result[T, E]`, nominal `enum`, and integer/refinement intervals:
        const unwrapped_scr = self.unwrapRefType(scrutinee_ty);
        const scr_node = self.pool.getNode(unwrapped_scr);
        var has_wildcard_cover = false;
        var has_seen_pattern_hole = false;
        var bool_covered_mask: u8 = 0; // bit 0 = false, bit 1 = true
        var variant_covered_mask: u64 = 0;
        const total_variants: usize = switch (scr_node.tag) {
            .optional_ty, .result_ty => 2,
            .enum_ty => blk: {
                const e_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(scr_node.rhs)).*;
                if (e_sym.target_scope.isNone()) break :blk 0;
                var variant_count: usize = 0;
                for (self.sym_table.getScopeMembers(e_sym.target_scope)) |member_idx| {
                    if (self.sym_table.getSymbol(member_idx).kind == .enum_variant_sym) {
                        variant_count += 1;
                    }
                }
                break :blk variant_count;
            },
            else => 0,
        };

        var uncovered_intervals: std.ArrayListUnmanaged(Interval128) = .empty;
        defer uncovered_intervals.deinit(self.allocator);
        var has_int_intervals = false;
        if (self.pool.getRefinementBounds(unwrapped_scr)) |ref_b| {
            try uncovered_intervals.append(self.allocator, .{ .min_val = ref_b.min_val, .max_val = ref_b.max_val });
            has_int_intervals = true;
        } else if (unwrapped_scr == .u128_ty) {
            try uncovered_intervals.append(
                self.allocator,
                .{ .min_val = std.math.minInt(i128), .max_val = std.math.maxInt(i128) },
            );
            has_int_intervals = true;
        } else if (getPrimitiveIntBounds(unwrapped_scr)) |prim_b| {
            try uncovered_intervals.append(self.allocator, .{ .min_val = prim_b.min_val, .max_val = prim_b.max_val });
            has_int_intervals = true;
        }

        var unified_body_ty: TypeId = expected_ty;
        var arm_idx: usize = 0;
        while (arm_idx < arm_count) : (arm_idx += 1) {
            const pat_id = NodeIndex.fromInt(arm_entries[arm_idx * 2]);
            const body_id = NodeIndex.fromInt(arm_entries[arm_idx * 2 + 1]);
            const guard_id = if (arm_idx < arm_guards.len) arm_guards[arm_idx] else .none;
            const is_unguarded = guard_id.isNone();

            // [1] Check arm usefulness & update coverage (`W0401`, `DR-04` Section 1.5 / `DR-07` Section 2.5):
            const is_already_fully_covered = has_wildcard_cover or
                (unwrapped_scr == .bool_ty and bool_covered_mask == 0b11) or
                (total_variants > 0 and total_variants <= 64 and
                    variant_covered_mask == (@as(u64, 1) << @intCast(total_variants)) - 1) or
                (has_int_intervals and uncovered_intervals.items.len == 0);

            const has_arm_added_coverage = try self.updateMatchArmCoverage(
                pat_id,
                unwrapped_scr,
                is_unguarded,
                &has_wildcard_cover,
                &has_seen_pattern_hole,
                &bool_covered_mask,
                &variant_covered_mask,
                &uncovered_intervals,
                has_int_intervals,
            );

            if (!unwrapped_scr.isError() and (is_already_fully_covered or (!has_arm_added_coverage and is_unguarded))) {
                try self.emitDiagnosticSimple(
                    .w0401_unreachable_pattern_arm,
                    self.getAstNodeSpan(pat_id),
                    "unreachable `match` arm; all values matched by this pattern are already covered",
                    "remove this redundant pattern arm",
                );
            }

            // [2] Type-check arm pattern, optional `if` guard, and body inside `.match_arm_scope`:
            const saved_scope = self.current_scope;
            const arm_scope = try self.sym_table.scope_arena.allocScope(
                .match_arm_scope,
                self.current_scope,
                .NONE,
                self.file_id,
                .{},
            );
            self.current_scope = arm_scope;
            defer self.current_scope = saved_scope;

            try self.bindPattern(
                pat_id,
                scrutinee_ty,
                false,
                self.isScrutineeMutRefBindable(scrutinee_id, scrutinee_ty),
            );
            if (!guard_id.isNone()) {
                _ = try self.checkExpr(guard_id, .bool_ty);
            }

            const body_ty = if (!unified_body_ty.isError())
                try self.checkExpr(body_id, unified_body_ty)
            else
                try self.synthExpr(body_id);

            if (unified_body_ty.isError() and !body_ty.isError() and body_ty != .never_ty) {
                unified_body_ty = self.materializeUntypedType(body_ty);
            }
            try symbol_resolver.checkUnusedBindingsInScope(self.sym_table, arm_scope, self.interner, self.diagnostic_sink);
        }

        // [3] Verify exhaustiveness (`E0415`, `DR-04` Section 1.5 / `DR-07` Section 2.5):
        if (!unwrapped_scr.isError() and !has_wildcard_cover and !has_seen_pattern_hole) {
            if (unwrapped_scr == .bool_ty and bool_covered_mask != 0b11) {
                const missing_lit = if ((bool_covered_mask & 1) == 0) "`false`" else "`true`";
                var msg_buf: [128]u8 = undefined;
                const msg = std.fmt.bufPrint(
                    &msg_buf,
                    "non-exhaustive `match` on `bool`; missing pattern {s}",
                    .{missing_lit},
                ) catch "non-exhaustive `match` on `bool`";
                try self.emitDiagnosticSimple(
                    .e0415_non_exhaustive_match,
                    self.getAstNodeSpan(expr_id),
                    msg,
                    "add missing boolean arm or `_` wildcard",
                );
            } else if (total_variants > 0 and total_variants <= 64) {
                const full_mask: u64 = (@as(u64, 1) << @intCast(total_variants)) - 1;
                if ((variant_covered_mask & full_mask) != full_mask) {
                    const missing_name = self.findFirstUncoveredVariantName(
                        unwrapped_scr,
                        variant_covered_mask,
                    );
                    var msg_buf: [160]u8 = undefined;
                    const msg = std.fmt.bufPrint(
                        &msg_buf,
                        "non-exhaustive `match`; variant `.{s}` is not covered",
                        .{missing_name},
                    ) catch "non-exhaustive `match`; not all variants are covered";
                    try self.emitDiagnosticSimple(
                        .e0415_non_exhaustive_match,
                        self.getAstNodeSpan(expr_id),
                        msg,
                        "handle all enum/Result/Option variants or add a `_` wildcard arm",
                    );
                }
            } else if (has_int_intervals and uncovered_intervals.items.len > 0) {
                const first_gap = uncovered_intervals.items[0];
                var msg_buf: [192]u8 = undefined;
                const msg = if (unwrapped_scr == .u128_ty) blk_u128_msg: {
                    const sign_bias: u128 = @as(u128, 1) << 127;
                    const gap_min_u: u128 = @as(u128, @bitCast(first_gap.min_val)) ^ sign_bias;
                    const gap_max_u: u128 = @as(u128, @bitCast(first_gap.max_val)) ^ sign_bias;
                    break :blk_u128_msg std.fmt.bufPrint(
                        &msg_buf,
                        "non-exhaustive `match`; integer range `{d}..={d}` is not covered",
                        .{ gap_min_u, gap_max_u },
                    ) catch "non-exhaustive `match` over integer range";
                } else std.fmt.bufPrint(
                    &msg_buf,
                    "non-exhaustive `match`; integer range `{d}..={d}` is not covered",
                    .{ first_gap.min_val, first_gap.max_val },
                ) catch "non-exhaustive `match` over integer range";
                try self.emitDiagnosticSimple(
                    .e0415_non_exhaustive_match,
                    self.getAstNodeSpan(expr_id),
                    msg,
                    "cover all remaining integer intervals or add a `_` wildcard arm",
                );
            }
        }

        const result_ty = if (unified_body_ty.isError()) .unit_ty else unified_body_ty;
        return self.recordNodeType(expr_id, result_ty);
    }

    /// Updates Maranget exhaustiveness coverage state for `pat_id`, returning `true` if new values were covered.
    fn updateMatchArmCoverage(
        self: *TypeChecker,
        pat_id: NodeIndex,
        scrutinee_ty: TypeId,
        is_unguarded: bool,
        has_wildcard_cover: *bool,
        has_seen_pattern_hole: *bool,
        bool_covered_mask: *u8,
        variant_covered_mask: *u64,
        uncovered_intervals: *std.ArrayListUnmanaged(Interval128),
        has_int_intervals: bool,
    ) anyerror!bool {
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return true;
        if (self.recursion_depth >= MAX_TYPE_DEPTH) return true;
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;

        const pat_node = self.ast_arena.getNode(pat_id);

        switch (pat_node.tag) {
            .pattern_hole => {
                // Recovery hole suppresses `E0415` without marking subsequent arms unreachable (`W0401`):
                has_seen_pattern_hole.* = true;
                return true;
            },
            .wildcard_pat => {
                const is_already_covered = has_wildcard_cover.*;
                if (is_unguarded) {
                    has_wildcard_cover.* = true;
                    uncovered_intervals.clearRetainingCapacity();
                }
                return !is_already_covered;
            },
            .bind_pat => {
                if (self.resolveBindPatConstOrVariantQuiet(pat_id, false)) |sym_idx| {
                    const sym = self.sym_table.getSymbol(sym_idx).*;
                    if (sym.kind == .enum_variant_sym and sym.member_ordinal < 64) {
                        const bit = @as(u64, 1) << @intCast(sym.member_ordinal);
                        const is_new = (variant_covered_mask.* & bit) == 0;
                        if (is_unguarded) variant_covered_mask.* |= bit;
                        return is_new;
                    }
                    if (sym.kind == .const_sym and has_int_intervals) {
                        const arm_range_opt = if (scrutinee_ty == .u128_ty)
                            self.extractBiasedU128PatternRangeBounds(pat_id)
                        else
                            self.extractPatternRangeBounds(pat_id);
                        if (arm_range_opt) |arm_range| {
                            var has_intersection = false;
                            if (arm_range.min_val <= arm_range.max_val) {
                                for (uncovered_intervals.items) |iv| {
                                    if (arm_range.max_val >= iv.min_val and arm_range.min_val <= iv.max_val) {
                                        has_intersection = true;
                                        break;
                                    }
                                }
                            }
                            if (is_unguarded and has_intersection) {
                                try subtractIntervalFromUncoveredList(
                                    self.allocator,
                                    uncovered_intervals,
                                    arm_range,
                                );
                            }
                            return has_intersection;
                        }
                    }
                    return true;
                }
                const is_already_covered = has_wildcard_cover.*;
                if (is_unguarded) {
                    has_wildcard_cover.* = true;
                    uncovered_intervals.clearRetainingCapacity();
                }
                return !is_already_covered;
            },
            .tuple_pat, .struct_pat => {
                if (pat_node.tag == .tuple_pat) {
                    const sub_pats = self.getNodeExtraSlice(pat_id, false);
                    if (sub_pats.len == 1 and !hasShallowCommaInTupleCst(
                        self.cst_arena,
                        self.token_buffer,
                        self.ast_arena.getCstOrigin(pat_id),
                    )) {
                        return self.updateMatchArmCoverage(
                            NodeIndex.fromInt(sub_pats[0]),
                            scrutinee_ty,
                            is_unguarded,
                            has_wildcard_cover,
                            has_seen_pattern_hole,
                            bool_covered_mask,
                            variant_covered_mask,
                            uncovered_intervals,
                            has_int_intervals,
                        );
                    }
                }
                if (!self.isPatternIrrefutable(pat_id, 0)) return true;
                const is_already_covered = has_wildcard_cover.*;
                if (is_unguarded) {
                    has_wildcard_cover.* = true;
                    uncovered_intervals.clearRetainingCapacity();
                }
                return !is_already_covered;
            },
            .or_pat => {
                const is_lhs_useful = if (pat_node.lhs.tag == .node)
                    try self.updateMatchArmCoverage(
                        NodeIndex.fromInt(pat_node.lhs.payload),
                        scrutinee_ty,
                        is_unguarded,
                        has_wildcard_cover,
                        has_seen_pattern_hole,
                        bool_covered_mask,
                        variant_covered_mask,
                        uncovered_intervals,
                        has_int_intervals,
                    )
                else
                    false;
                const is_rhs_useful = if (pat_node.rhs.tag == .node)
                    try self.updateMatchArmCoverage(
                        NodeIndex.fromInt(pat_node.rhs.payload),
                        scrutinee_ty,
                        is_unguarded,
                        has_wildcard_cover,
                        has_seen_pattern_hole,
                        bool_covered_mask,
                        variant_covered_mask,
                        uncovered_intervals,
                        has_int_intervals,
                    )
                else
                    false;
                return is_lhs_useful or is_rhs_useful;
            },
            .at_pat => {
                if (pat_node.rhs.tag == .node) {
                    return self.updateMatchArmCoverage(
                        NodeIndex.fromInt(pat_node.rhs.payload),
                        scrutinee_ty,
                        is_unguarded,
                        has_wildcard_cover,
                        has_seen_pattern_hole,
                        bool_covered_mask,
                        variant_covered_mask,
                        uncovered_intervals,
                        has_int_intervals,
                    );
                }
                return true;
            },
            .slice_pat => {
                if (!self.isPatternIrrefutable(pat_id, 0)) return true;
                const is_already_covered = has_wildcard_cover.*;
                if (is_unguarded) {
                    has_wildcard_cover.* = true;
                    uncovered_intervals.clearRetainingCapacity();
                }
                return !is_already_covered;
            },
            .lit_pat => {
                if (scrutinee_ty == .bool_ty and !pat_node.main_token.isNone()) {
                    const kind = self.token_buffer.getToken(pat_node.main_token).kind;
                    const bit: u8 = if (kind == .kw_false) 1 else if (kind == .kw_true) 2 else 0;
                    const is_new = (bool_covered_mask.* & bit) == 0;
                    if (is_unguarded) bool_covered_mask.* |= bit;
                    return is_new;
                }
                if (has_int_intervals) {
                    const arm_range_opt = if (scrutinee_ty == .u128_ty)
                        self.extractBiasedU128PatternRangeBounds(pat_id)
                    else
                        self.extractPatternRangeBounds(pat_id);
                    if (arm_range_opt) |arm_range| {
                        // Check if `arm_range` intersects any remaining uncovered interval:
                        var has_intersection = false;
                        if (arm_range.min_val <= arm_range.max_val) {
                            for (uncovered_intervals.items) |iv| {
                                if (arm_range.max_val >= iv.min_val and arm_range.min_val <= iv.max_val) {
                                    has_intersection = true;
                                    break;
                                }
                            }
                        }
                        if (is_unguarded and has_intersection) {
                            try subtractIntervalFromUncoveredList(
                                self.allocator,
                                uncovered_intervals,
                                arm_range,
                            );
                        }
                        return has_intersection;
                    }
                }
                return true;
            },
            .variant_pat => {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                for (sub_pats) |raw_sub| {
                    if (!self.isPatternIrrefutable(NodeIndex.fromInt(raw_sub), 0)) return true;
                }
                const var_name = self.extractVariantPatName(pat_id);
                const scr_node = self.pool.getNode(scrutinee_ty);
                var var_ordinal: ?u6 = null;
                switch (scr_node.tag) {
                    .optional_ty => {
                        if (std.mem.eql(u8, var_name, "None")) var_ordinal = 0;
                        if (std.mem.eql(u8, var_name, "Some")) var_ordinal = 1;
                    },
                    .result_ty => {
                        if (std.mem.eql(u8, var_name, "Ok")) var_ordinal = 0;
                        if (std.mem.eql(u8, var_name, "Err")) var_ordinal = 1;
                    },
                    .enum_ty => {
                        const e_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(scr_node.rhs)).*;
                        if (!e_sym.target_scope.isNone()) {
                            if (self.interner.lookup(var_name)) |v_sym_id| {
                                const v_idx = self.sym_table.lookupInScopeDirect(
                                    e_sym.target_scope,
                                    v_sym_id,
                                    NamespaceMask.VALUE_ONLY,
                                );
                                if (!v_idx.isNone()) {
                                    self.sym_table.markSymbolUsed(v_idx);
                                    const ord = self.sym_table.getSymbol(v_idx).member_ordinal;
                                    if (ord < 64) var_ordinal = @intCast(ord);
                                }
                            }
                        }
                    },
                    else => {},
                }
                if (var_ordinal) |ord| {
                    const bit = @as(u64, 1) << ord;
                    const is_new = (variant_covered_mask.* & bit) == 0;
                    if (is_unguarded) variant_covered_mask.* |= bit;
                    return is_new;
                }
                if (sub_pats.len == 0 and has_int_intervals) {
                    const arm_range_opt = if (scrutinee_ty == .u128_ty)
                        self.extractBiasedU128PatternRangeBounds(pat_id)
                    else
                        self.extractPatternRangeBounds(pat_id);
                    if (arm_range_opt) |arm_range| {
                        var has_intersection = false;
                        if (arm_range.min_val <= arm_range.max_val) {
                            for (uncovered_intervals.items) |iv| {
                                if (arm_range.max_val >= iv.min_val and arm_range.min_val <= iv.max_val) {
                                    has_intersection = true;
                                    break;
                                }
                            }
                        }
                        if (is_unguarded and has_intersection) {
                            try subtractIntervalFromUncoveredList(
                                self.allocator,
                                uncovered_intervals,
                                arm_range,
                            );
                        }
                        return has_intersection;
                    }
                }
                return true;
            },
            else => return true,
        }
    }

    /// Returns `true` if `pat_id` is irrefutable (matches all values of its type without refutable sub-patterns).
    fn isPatternIrrefutable(self: *const TypeChecker, pat_id: NodeIndex, depth: u32) bool {
        if (depth >= MAX_TYPE_DEPTH) return true;
        if (pat_id.isNone() or pat_id.asInt() >= self.ast_arena.countNodes()) return true;
        const pat_node = self.ast_arena.getNode(pat_id);
        return switch (pat_node.tag) {
            .wildcard_pat, .pattern_hole => true,
            .bind_pat => self.resolveBindPatConstOrVariantQuiet(pat_id, false) == null,
            .at_pat => pat_node.rhs.tag == .node and
                self.isPatternIrrefutable(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1),
            .slice_pat => blk: {
                const sub_pats = self.getNodeExtraSlice(pat_id, false);
                break :blk sub_pats.len == 1 and self.isSliceRestPatternNode(NodeIndex.fromInt(sub_pats[0]));
            },
            .tuple_pat => blk: {
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    if (!self.isPatternIrrefutable(NodeIndex.fromInt(raw_sub), depth + 1)) break :blk false;
                }
                break :blk true;
            },
            .struct_pat => blk: {
                for (self.getNodeExtraSlice(pat_id, false)) |raw_sub| {
                    if (!self.isPatternIrrefutable(NodeIndex.fromInt(raw_sub), depth + 1)) break :blk false;
                }
                break :blk true;
            },
            .or_pat => blk: {
                const is_lhs_irrefutable = pat_node.lhs.tag == .node and
                    self.isPatternIrrefutable(NodeIndex.fromInt(pat_node.lhs.payload), depth + 1);
                const is_rhs_irrefutable = pat_node.rhs.tag == .node and
                    self.isPatternIrrefutable(NodeIndex.fromInt(pat_node.rhs.payload), depth + 1);
                break :blk is_lhs_irrefutable or is_rhs_irrefutable;
            },
            else => false,
        };
    }

    /// Returns the name of the first uncovered variant in `scrutinee_ty` for `E0415`.
    fn findFirstUncoveredVariantName(
        self: *const TypeChecker,
        scrutinee_ty: TypeId,
        covered_mask: u64,
    ) []const u8 {
        const scr_node = self.pool.getNode(scrutinee_ty);
        switch (scr_node.tag) {
            .optional_ty => return if ((covered_mask & 1) == 0) "None" else "Some",
            .result_ty => return if ((covered_mask & 1) == 0) "Ok" else "Err",
            .enum_ty => {
                const e_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(scr_node.rhs)).*;
                if (!e_sym.target_scope.isNone()) {
                    for (self.sym_table.getScopeMembers(e_sym.target_scope)) |member_idx| {
                        const member_sym = self.sym_table.getSymbol(member_idx).*;
                        if (member_sym.kind != .enum_variant_sym) continue;
                        if (member_sym.member_ordinal < 64 and
                            (covered_mask & (@as(u64, 1) << @intCast(member_sym.member_ordinal))) == 0)
                        {
                            return member_sym.name_text;
                        }
                    }
                }
                return "_";
            },
            else => return "_",
        }
    }

    // ----------- Type Compatibility & Coercion Checking -----------

    /// Verifies whether `actual_ty` is assignable to `expected_ty` at `expr_id`, emitting diagnostics on failure.
    fn checkTypeCompatibility(
        self: *TypeChecker,
        expr_id: NodeIndex,
        actual_ty: TypeId,
        expected_ty: TypeId,
    ) !bool {
        if (actual_ty.isError() or expected_ty.isError()) return true;
        if (actual_ty == .never_ty) return true;
        if (actual_ty == expected_ty) return true;

        if (actual_ty == .str_ty and expected_ty == .fmt_args_ty) return true;

        const act_node = self.pool.getNode(actual_ty);
        const exp_node = self.pool.getNode(expected_ty);

        // Enforce `&out T` write-only reference isolation (`ADR-22B`, `E0422`):
        if (self.pool.isOutRef(actual_ty) != self.pool.isOutRef(expected_ty)) {
            try self.emitDiagnosticSimple(
                .e0422_out_param_contract_violation,
                self.getAstNodeSpan(expr_id),
                "cannot implicitly coerce between write-only `&out T` and `&T` / `&mut T`",
                "mismatched `&out` reference mode",
            );
            return false;
        }

        // [1] Constrained Type Group, `.tilde_approx`, or generic parameter satisfaction (`DR-04` Section 1.4):
        if (exp_node.tag == .bind_once_group_var or
            exp_node.tag == .bind_many_any_var or
            exp_node.tag == .type_param or
            exp_node.tag == .tilde_approx or
            exp_node.tag == .user_group or
            exp_node.tag == .builtin_group)
        {
            const grp_ty = if (exp_node.tag == .bind_once_group_var or
                exp_node.tag == .bind_many_any_var or
                exp_node.tag == .type_param)
                TypeId.fromInt(exp_node.lhs)
            else
                expected_ty;
            var sat = checkGroupSatisfaction(
                self.pool,
                self.sym_table,
                self.target_layout,
                actual_ty,
                grp_ty,
            );
            if (sat == .rejected and (act_node.tag == .ref_ty or act_node.tag == .mut_ref_ty)) {
                const inner_act = self.pool.getNode(TypeId.fromInt(act_node.lhs));
                if (inner_act.tag == .array_ty or inner_act.tag == .soa_array_ty) {
                    const coerced_slice = try self.pool.internSlice(
                        TypeId.fromInt(inner_act.lhs),
                        inner_act.tag == .soa_array_ty,
                    );
                    const coerced_ref = try self.pool.internRef(coerced_slice, false);
                    sat = checkGroupSatisfaction(
                        self.pool,
                        self.sym_table,
                        self.target_layout,
                        coerced_ref,
                        grp_ty,
                    );
                }
            }
            if (sat == .rejected and self.pool.getTag(grp_ty) == .trait_ty) {
                if (try self.hasTraitImplementation(self.materializeUntypedType(actual_ty), grp_ty, 0)) {
                    sat = .matched_exact;
                }
            }
            if (sat == .matched_exact or sat == .matched_via_tilde) {
                return true;
            }
            if (sat == .rejected_distinct_without_tilde) {
                try self.emitGroupConstraintError(
                    self.getAstNodeSpan(expr_id),
                    self.materializeUntypedType(actual_ty),
                    grp_ty,
                    true,
                );
                return false;
            }
        }

        // [2] `distinct` newtype isolation (`E0405`, `DR-04` Section 1.4):
        const is_actual_distinct = act_node.tag == .distinct_ty;
        const is_expected_distinct = exp_node.tag == .distinct_ty;
        if (is_actual_distinct or is_expected_distinct) {
            try self.emitDistinctMixingError(
                self.getAstNodeSpan(expr_id),
                expected_ty,
                self.materializeUntypedType(actual_ty),
            );
            return false;
        }

        // [3] Zero-cost `T is low..=high` range refinement (`DR-04` Section 1.5):
        // - Widening `Refined -> Base` or `Refined[A..=B] -> Refined[C..=D]` (where `A >= C` and `B <= D`) is implicit:
        if (act_node.tag == .refined_ty) {
            if (self.pool.unwrapRefinementBase(actual_ty) == expected_ty) {
                return true;
            }
            if (exp_node.tag == .refined_ty and
                self.pool.unwrapRefinementBase(actual_ty) == self.pool.unwrapRefinementBase(expected_ty))
            {
                if (self.pool.getRefinementBounds(actual_ty)) |act_b| {
                    if (self.pool.getRefinementBounds(expected_ty)) |exp_b| {
                        if (act_b.min_val >= exp_b.min_val and act_b.max_val <= exp_b.max_val) {
                            return true;
                        }
                    }
                }
            }
        }
        if (self.pool.getRefinementBounds(expected_ty)) |ref_bounds| {
            try self.emitRangeRefinementError(
                self.getAstNodeSpan(expr_id),
                expected_ty,
                ref_bounds.min_val,
                ref_bounds.min_val,
                ref_bounds.max_val,
            );
            return false;
        }

        // [4] Untyped literal materialization (`untyped_int_ty` / `untyped_float_ty`):
        if (actual_ty == .untyped_int_ty and
            (expected_ty.isIntegerPrimitive() or self.isIntegerBoundedVar(expected_ty)))
        {
            return true;
        }
        if (actual_ty == .untyped_float_ty and expected_ty.isFloatPrimitive()) {
            return true;
        }

        // [5] Reference, raw pointer (`ADR-22F`), symbolic-array, & array-to-slice coercions:
        if (act_node.tag == .mut_ref_ty and exp_node.tag == .ref_ty and act_node.lhs == exp_node.lhs) {
            return true;
        }
        if (act_node.tag == .raw_ptr_ty and exp_node.tag == .raw_ptr_ty) {
            const is_mut_ok = act_node.rhs != 0 or exp_node.rhs == 0;
            if (is_mut_ok and (act_node.lhs == exp_node.lhs or TypeId.fromInt(exp_node.lhs) == .opaque_ty)) {
                return true;
            }
        }
        if ((act_node.tag == .ref_ty or act_node.tag == .mut_ref_ty) and exp_node.tag == .raw_ptr_ty) {
            const is_mut_ok = act_node.tag == .mut_ref_ty or exp_node.rhs == 0;
            if (is_mut_ok and (act_node.lhs == exp_node.lhs or TypeId.fromInt(exp_node.lhs) == .opaque_ty)) {
                return true;
            }
        }
        if ((act_node.tag == .array_ty or act_node.tag == .soa_array_ty) and
            act_node.tag == exp_node.tag and act_node.lhs == exp_node.lhs and
            act_node.rhs == exp_node.rhs)
        {
            return true;
        }
        if (exp_node.tag == .slice_ty) {
            if (act_node.tag == .ref_ty or act_node.tag == .mut_ref_ty) {
                const inner_act = self.pool.getNode(TypeId.fromInt(act_node.lhs));
                if ((inner_act.tag == .array_ty or inner_act.tag == .slice_ty) and
                    inner_act.lhs == exp_node.lhs)
                {
                    return true;
                }
            }
        }
        if (exp_node.tag == .soa_slice_ty) {
            if (act_node.tag == .ref_ty or act_node.tag == .mut_ref_ty) {
                const inner_act = self.pool.getNode(TypeId.fromInt(act_node.lhs));
                if ((inner_act.tag == .soa_array_ty or inner_act.tag == .soa_slice_ty) and
                    inner_act.lhs == exp_node.lhs)
                {
                    return true;
                }
            }
        }
        if ((exp_node.tag == .ref_ty and (act_node.tag == .ref_ty or act_node.tag == .mut_ref_ty)) or
            (exp_node.tag == .mut_ref_ty and act_node.tag == .mut_ref_ty))
        {
            const inner_exp = self.pool.getNode(TypeId.fromInt(exp_node.lhs));
            const inner_act = self.pool.getNode(TypeId.fromInt(act_node.lhs));
            if (inner_exp.tag == .slice_ty and inner_act.tag == .array_ty and inner_act.lhs == inner_exp.lhs) {
                return true;
            }
            if (inner_exp.tag == .soa_slice_ty and inner_act.tag == .soa_array_ty and inner_act.lhs == inner_exp.lhs) {
                return true;
            }
        }

        // [6] Function pointer & closure contract + captureless coercion (`SE-19`, `E0320`–`E0322`):
        if ((act_node.tag == .fn_ty or act_node.tag == .closure_ty) and
            (exp_node.tag == .fn_ty or exp_node.tag == .closure_ty))
        {
            if (self.pool.getFnSignatureView(actual_ty)) |act_sig| {
                if (self.pool.getFnSignatureView(expected_ty)) |exp_sig| {
                    const is_capture_compatible = if (act_node.tag == .closure_ty and exp_node.tag == .fn_ty)
                        !act_sig.has_env_capture and act_sig.capture_tier == .copy_tier and !act_sig.is_async
                    else if (act_node.tag == .fn_ty and exp_node.tag == .closure_ty)
                        !exp_sig.is_async and !act_sig.is_variadic
                    else if (act_node.tag == .closure_ty and exp_node.tag == .closure_ty)
                        !(act_sig.capture_tier != .copy_tier and exp_sig.capture_tier == .copy_tier) and
                            act_sig.is_async == exp_sig.is_async
                    else
                        act_sig.is_async == exp_sig.is_async and act_sig.is_variadic == exp_sig.is_variadic;

                    if (is_capture_compatible and
                        act_sig.paramCount() == exp_sig.paramCount() and
                        std.mem.eql(u32, act_sig.param_types, exp_sig.param_types) and
                        std.mem.eql(u32, act_sig.param_modes, exp_sig.param_modes) and
                        act_sig.ret_ty == exp_sig.ret_ty)
                    {
                        if (act_sig.contracts.isSatisfying(exp_sig.contracts)) {
                            return true;
                        }
                        try self.emitFnContractCoercionError(
                            self.getAstNodeSpan(expr_id),
                            actual_ty,
                            expected_ty,
                            act_sig.contracts,
                            exp_sig.contracts,
                        );
                        return false;
                    }
                }
            }
        }

        // [7] Uninstantiated generic nominal struct/enum literal compatibility (`Box { val: x }` -> `Box[T]`):
        if ((act_node.tag == .struct_ty or act_node.tag == .enum_ty or act_node.tag == .union_ty) and
            act_node.tag == exp_node.tag and act_node.rhs == exp_node.rhs)
        {
            const act_args = self.pool.getGenericTypeArgs(actual_ty);
            const exp_args = self.pool.getGenericTypeArgs(expected_ty);
            if (act_args.len == 0 or exp_args.len == 0) {
                return true;
            }
        }

        // [8] `Future[T]` compatibility across distinct async producers (`rhs = producer_id`):
        if (act_node.tag == .future_ty and exp_node.tag == .future_ty) {
            return self.checkTypeCompatibility(
                expr_id,
                TypeId.fromInt(act_node.lhs),
                TypeId.fromInt(exp_node.lhs),
            );
        }
        if ((self.isTaskGroupLikeType(actual_ty) and self.isTaskGroupLikeType(expected_ty)) or
            (self.isTaskHandleLikeType(actual_ty) and self.isTaskHandleLikeType(expected_ty)))
        {
            const act_inner = self.extractTaskHandleValueType(actual_ty) orelse
                self.extractTaskGroupErrorType(actual_ty) orelse .never_ty;
            const exp_inner = self.extractTaskHandleValueType(expected_ty) orelse
                self.extractTaskGroupErrorType(expected_ty) orelse .never_ty;
            if (act_inner == exp_inner or exp_inner == .never_ty) return true;
        }

        try self.emitTypeMismatch(
            self.getAstNodeSpan(expr_id),
            expected_ty,
            self.materializeUntypedType(actual_ty),
        );
        return false;
    }

    /// Materializes `.untyped_int_ty` to `.i32_ty` and `.untyped_float_ty` to `.f64_ty`.
    pub inline fn materializeUntypedType(self: *const TypeChecker, ty: TypeId) TypeId {
        _ = self;
        if (ty == .untyped_int_ty) return .i32_ty;
        if (ty == .untyped_float_ty) return .f64_ty;
        return ty;
    }

    /// Unwraps one or more `.ref_ty` / `.mut_ref_ty` layers for auto-dereferencing member/method access.
    fn unwrapRefType(self: *const TypeChecker, ty: TypeId) TypeId {
        var cur = ty;
        var guard: u32 = 0;
        while (guard < 16) : (guard += 1) {
            const node = self.pool.getNode(cur);
            if (node.tag == .ref_ty or node.tag == .mut_ref_ty) {
                cur = TypeId.fromInt(node.lhs);
            } else {
                break;
            }
        }
        return cur;
    }

    /// Emits `E0320`, `E0321`, or `E0322` when coercing a function lacking `@no_alloc`, `@no_panic`, or `@no_block`.
    fn emitFnContractCoercionError(
        self: *TypeChecker,
        span: Span,
        actual_ty: TypeId,
        expected_ty: TypeId,
        actual_contracts: FnPtrContractMask,
        expected_contracts: FnPtrContractMask,
    ) !void {
        if (self.diagnostic_sink == null) return;
        var act_buf: [96]u8 = undefined;
        var exp_buf: [96]u8 = undefined;
        const act_str = self.pool.formatType(actual_ty, self.sym_table, &act_buf);
        const exp_str = self.pool.formatType(expected_ty, self.sym_table, &exp_buf);

        const code: DiagnosticCode = if (expected_contracts.has_no_alloc and !actual_contracts.has_no_alloc)
            .e0320_no_alloc_contract_violation
        else if (expected_contracts.has_no_panic and !actual_contracts.has_no_panic)
            .e0321_no_panic_contract_violation
        else
            .e0322_no_block_contract_violation;

        const attr_name: []const u8 = switch (code) {
            .e0320_no_alloc_contract_violation => "@no_alloc",
            .e0321_no_panic_contract_violation => "@no_panic",
            else => "@no_block",
        };

        var msg_buf: [240]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "cannot coerce `{s}` to `{s}`: target function type requires `{s}` contract",
            .{ act_str, exp_str, attr_name },
        ) catch "cannot coerce function value to stricter `@no_alloc` / `@no_panic` / `@no_block` function type";

        try self.emitDiagnosticSimple(
            code,
            span,
            msg,
            "function value lacks required effect contract",
        );
    }

    /// Returns `true` if `ty` is a type variable whose constraining Type Group admits integer literals.
    fn isIntegerBoundedVar(self: *const TypeChecker, ty: TypeId) bool {
        const node = self.pool.getNode(ty);
        if (node.tag == .bind_once_group_var or
            node.tag == .bind_many_any_var or
            node.tag == .type_param)
        {
            const grp_ty = TypeId.fromInt(node.lhs);
            return checkGroupSatisfaction(
                self.pool,
                self.sym_table,
                self.target_layout,
                .untyped_int_ty,
                grp_ty,
            ) != .rejected;
        }
        return false;
    }

    /// Returns `true` if `expr_id` produces a `@must_use` value (`Result[T, E]`, `@must_use` nominal type, or `@must_use` fn).
    fn isMustUseTypeOrCall(self: *const TypeChecker, expr_id: NodeIndex, expr_ty: TypeId) bool {
        if (self.pool.getFlags(expr_ty).is_must_use) return true;
        if (expr_id.isNone() or expr_id.asInt() >= self.ast_arena.countNodes()) return false;
        const ast_node = self.ast_arena.getNode(expr_id);
        if ((ast_node.tag == .call_expr or ast_node.tag == .generic_call) and ast_node.lhs.tag == .node) {
            const callee_id = NodeIndex.fromInt(ast_node.lhs.payload);
            if (callee_id.asInt() < self.node_types.len) {
                const callee_ty = self.node_types[callee_id.asInt()];
                if (self.pool.getFlags(callee_ty).is_must_use) return true;
            }
        } else if (ast_node.tag == .method_call and ast_node.lhs.tag == .node) {
            const recv_id = NodeIndex.fromInt(ast_node.lhs.payload);
            if (recv_id.asInt() < self.node_types.len) {
                const recv_ty = self.unwrapRefType(self.node_types[recv_id.asInt()]);
                const recv_node = self.pool.getNode(recv_ty);
                if (recv_node.tag == .struct_ty or recv_node.tag == .enum_ty or
                    recv_node.tag == .union_ty or recv_node.tag == .trait_ty)
                {
                    const owner_sym = self.sym_table.getSymbol(SymbolIndex.fromInt(recv_node.rhs)).*;
                    const raw_items = self.getNodeExtraSlice(expr_id, true);
                    if (!owner_sym.target_scope.isNone() and raw_items.len > 0) {
                        const member_tok = TokenIndex.fromInt(raw_items[0]);
                        const member_name = symbol_resolver.extractTokenSlice(
                            self.source,
                            self.token_buffer,
                            member_tok,
                        );
                        if (self.interner.lookup(member_name)) |m_sym_id| {
                            const m_idx = self.sym_table.lookupInScopeDirect(
                                owner_sym.target_scope,
                                m_sym_id,
                                NamespaceMask.VALUE_ONLY,
                            );
                            if (!m_idx.isNone() and self.sym_table.getSymbol(m_idx).flags.is_must_use) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    // ------------------- Diagnostic Formatters --------------------

    /// Matched nominal symbol pair from two distinct `PackageId` versions of the same canonical package (`E0012`).
    const CrossMajorNominalMatch = struct {
        /// Expected nominal `SymbolIndex`.
        exp_sym_idx: SymbolIndex,
        /// Actual nominal `SymbolIndex`.
        act_sym_idx: SymbolIndex,
        /// Owning `PackageId` of `exp_sym_idx`.
        exp_pkg: symbol_resolver.PackageId,
        /// Owning `PackageId` of `act_sym_idx`.
        act_pkg: symbol_resolver.PackageId,
        /// Shared canonical package name `SymbolId`.
        canon_name_sym: SymbolId,
    };

    /// Resolves the canonical package name `SymbolId` for `pkg_id` in $O(1)$ (`SymbolId.empty` when unregistered).
    fn lookupPackageCanonicalNameSym(
        self: *const TypeChecker,
        pkg_id: symbol_resolver.PackageId,
    ) SymbolId {
        if (self.sym_table.package_canonical_names.get(pkg_id)) |canon_sym| {
            return canon_sym;
        }
        if (self.sym_table.package_metas.get(pkg_id)) |meta| {
            return meta.canonical_name_sym;
        }
        return .empty;
    }

    /// Resolves the borrowed SemVer text for `pkg_id` (`"?"` when unregistered).
    fn lookupPackageVersionSlice(
        self: *const TypeChecker,
        pkg_id: symbol_resolver.PackageId,
    ) []const u8 {
        if (self.sym_table.package_metas.get(pkg_id)) |meta| {
            if (meta.version_text.len > 0) return meta.version_text;
        }
        if (self.sym_table.package_version_labels.get(pkg_id)) |ver_id| {
            const ver_str = self.interner.get(ver_id);
            if (ver_str.len > 0) return ver_str;
        }
        return "?";
    }

    /// Extracts the reverse intra-package `[sym, mod_k, …, mod_0]` `SymbolId` path up to `pkg_id`'s root scope.
    fn extractIntraPackageSymbolChain(
        self: *const TypeChecker,
        sym_idx: SymbolIndex,
        pkg_id: symbol_resolver.PackageId,
        out_chain: *[16]SymbolId,
    ) usize {
        if (sym_idx.isNone()) return 0;
        const sym = self.sym_table.getSymbol(sym_idx).*;
        out_chain[0] = sym.name;
        var count: usize = 1;

        const pkg_root = self.sym_table.lookupPackageRootScope(pkg_id) orelse
            (self.sym_table.file_module_scopes.get(sym.decl_span.file_id.asInt()) orelse .none);
        var cur_mod = if (!sym.scope_id.isNone())
            self.sym_table.scope_arena.getScope(sym.scope_id).enclosing_module
        else
            .none;

        var steps: usize = 0;
        while (!cur_mod.isNone() and cur_mod != pkg_root and
            cur_mod != self.sym_table.prelude_scope and
            count < out_chain.len and steps < 16) : (steps += 1)
        {
            const parent_mod = self.sym_table.scope_arena.findImmediateParentModule(cur_mod);
            if (parent_mod.isNone()) break;
            var mod_name: SymbolId = .empty;
            for (self.sym_table.getScopeMembers(parent_mod)) |mem_idx| {
                const mem_sym = self.sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind == .module_sym and !mem_sym.flags.is_imported and mem_sym.target_scope == cur_mod) {
                    mod_name = mem_sym.name;
                    break;
                }
            }
            if (mod_name == .empty) break;
            out_chain[count] = mod_name;
            count += 1;
            cur_mod = parent_mod;
        }
        return count;
    }

    /// Formats a reversed `chain[0..chain_len]` (`[leaf, …, root_submod]`) into `out_buf` as `root_submod.….leaf`.
    fn formatIntraPackageSymbolChain(
        self: *const TypeChecker,
        chain: []const SymbolId,
        out_buf: *[128]u8,
    ) []const u8 {
        var pos: usize = 0;
        var rev_idx: usize = chain.len;
        while (rev_idx > 0) {
            rev_idx -= 1;
            if (pos > 0 and pos < out_buf.len) {
                out_buf[pos] = '.';
                pos += 1;
            }
            const seg_str = self.interner.get(chain[rev_idx]);
            const copy_len = @min(seg_str.len, out_buf.len - pos);
            @memcpy(out_buf[pos .. pos + copy_len], seg_str[0..copy_len]);
            pos += copy_len;
        }
        return out_buf[0..pos];
    }

    /// Checks in $O(1)$ before scope-walking whether `(exp_sym_idx, act_sym_idx)` are coexisting-version twins.
    fn matchCrossMajorNominalSymbols(
        self: *const TypeChecker,
        exp_sym_idx: SymbolIndex,
        act_sym_idx: SymbolIndex,
    ) ?CrossMajorNominalMatch {
        if (exp_sym_idx.isNone() or act_sym_idx.isNone() or exp_sym_idx == act_sym_idx) return null;
        const exp_sym = self.sym_table.getSymbol(exp_sym_idx).*;
        const act_sym = self.sym_table.getSymbol(act_sym_idx).*;
        if (exp_sym.name != act_sym.name) return null;

        const exp_pkg = self.sym_table.getFilePackageId(exp_sym.decl_span.file_id);
        const act_pkg = self.sym_table.getFilePackageId(act_sym.decl_span.file_id);
        if (exp_pkg == act_pkg) return null;

        const exp_canon = self.lookupPackageCanonicalNameSym(exp_pkg);
        if (exp_canon == .empty) return null;
        const act_canon = self.lookupPackageCanonicalNameSym(act_pkg);
        if (exp_canon != act_canon) return null;

        var exp_chain: [16]SymbolId = undefined;
        var act_chain: [16]SymbolId = undefined;
        const exp_len = self.extractIntraPackageSymbolChain(exp_sym_idx, exp_pkg, &exp_chain);
        const act_len = self.extractIntraPackageSymbolChain(act_sym_idx, act_pkg, &act_chain);
        if (exp_len == 0 or exp_len != act_len) return null;
        for (exp_chain[0..exp_len], act_chain[0..act_len]) |exp_seg, act_seg| {
            if (exp_seg != act_seg) return null;
        }
        return .{
            .exp_sym_idx = exp_sym_idx,
            .act_sym_idx = act_sym_idx,
            .exp_pkg = exp_pkg,
            .act_pkg = act_pkg,
            .canon_name_sym = exp_canon,
        };
    }

    /// Recursively walks matching structural constructors up to depth `16` to find a cross-major nominal pair.
    fn findCrossMajorNominalPairBounded(
        self: *const TypeChecker,
        raw_exp_ty: TypeId,
        raw_act_ty: TypeId,
        depth: u32,
    ) ?CrossMajorNominalMatch {
        if (depth >= 16 or raw_exp_ty == raw_act_ty or raw_exp_ty.isError() or raw_act_ty.isError()) {
            return null;
        }
        var exp_ty = raw_exp_ty;
        var act_ty = raw_act_ty;
        while (self.pool.getTag(exp_ty) == .refined_ty or self.pool.getTag(exp_ty) == .tilde_approx) {
            exp_ty = TypeId.fromInt(self.pool.getNode(exp_ty).lhs);
        }
        while (self.pool.getTag(act_ty) == .refined_ty or self.pool.getTag(act_ty) == .tilde_approx) {
            act_ty = TypeId.fromInt(self.pool.getNode(act_ty).lhs);
        }
        if (exp_ty == act_ty or exp_ty.isError() or act_ty.isError()) return null;

        const exp_node = self.pool.getNode(exp_ty);
        const act_node = self.pool.getNode(act_ty);

        if (isCrossMajorNominalTag(exp_node.tag) and exp_node.tag == act_node.tag) {
            const exp_sym_idx = self.sym_table.type_to_symbol.get(exp_ty.toU32()) orelse
                SymbolIndex.fromInt(exp_node.rhs);
            const act_sym_idx = self.sym_table.type_to_symbol.get(act_ty.toU32()) orelse
                SymbolIndex.fromInt(act_node.rhs);
            if (self.matchCrossMajorNominalSymbols(exp_sym_idx, act_sym_idx)) |matched| {
                return matched;
            }
            const exp_args = self.pool.getGenericTypeArgs(exp_ty);
            const act_args = self.pool.getGenericTypeArgs(act_ty);
            if (exp_args.len > 0 and exp_args.len == act_args.len) {
                for (exp_args, act_args) |exp_arg_raw, act_arg_raw| {
                    if (self.findCrossMajorNominalPairBounded(
                        TypeId.fromInt(exp_arg_raw),
                        TypeId.fromInt(act_arg_raw),
                        depth + 1,
                    )) |arg_match| {
                        return arg_match;
                    }
                }
            }
            return null;
        }

        const is_both_ref = (exp_node.tag == .ref_ty or exp_node.tag == .mut_ref_ty) and
            (act_node.tag == .ref_ty or act_node.tag == .mut_ref_ty);
        const is_both_slice = (exp_node.tag == .slice_ty or exp_node.tag == .soa_slice_ty) and
            (act_node.tag == .slice_ty or act_node.tag == .soa_slice_ty);
        const is_both_array = (exp_node.tag == .array_ty or exp_node.tag == .soa_array_ty) and
            (act_node.tag == .array_ty or act_node.tag == .soa_array_ty);
        if (is_both_ref or is_both_slice or is_both_array) {
            return self.findCrossMajorNominalPairBounded(
                TypeId.fromInt(exp_node.lhs),
                TypeId.fromInt(act_node.lhs),
                depth + 1,
            );
        }

        if (exp_node.tag != act_node.tag) return null;
        return switch (exp_node.tag) {
            .primitive => if (exp_node.rhs == act_node.rhs and
                (exp_node.rhs == TypeId.task_group_base_ty.toU32() or
                    exp_node.rhs == TypeId.task_handle_base_ty.toU32()))
                self.findCrossMajorNominalPairBounded(
                    TypeId.fromInt(exp_node.lhs),
                    TypeId.fromInt(act_node.lhs),
                    depth + 1,
                )
            else
                null,
            .optional_ty, .raw_ptr_ty, .dyn_trait_ty, .future_ty => self.findCrossMajorNominalPairBounded(
                TypeId.fromInt(exp_node.lhs),
                TypeId.fromInt(act_node.lhs),
                depth + 1,
            ),
            .result_ty => self.findCrossMajorNominalPairBounded(
                TypeId.fromInt(exp_node.lhs),
                TypeId.fromInt(act_node.lhs),
                depth + 1,
            ) orelse self.findCrossMajorNominalPairBounded(
                TypeId.fromInt(exp_node.rhs),
                TypeId.fromInt(act_node.rhs),
                depth + 1,
            ),
            .tuple_ty => blk_tup: {
                if (exp_node.rhs != act_node.rhs or exp_node.rhs == 0) break :blk_tup null;
                const arity: usize = exp_node.rhs;
                const exp_elems = self.pool.extra.items[exp_node.lhs .. exp_node.lhs + arity];
                const act_elems = self.pool.extra.items[act_node.lhs .. act_node.lhs + arity];
                for (exp_elems, act_elems) |exp_el, act_el| {
                    if (self.findCrossMajorNominalPairBounded(
                        TypeId.fromInt(exp_el),
                        TypeId.fromInt(act_el),
                        depth + 1,
                    )) |el_match| {
                        break :blk_tup el_match;
                    }
                }
                break :blk_tup null;
            },
            .fn_ty, .closure_ty => blk_fn: {
                const exp_sig = self.pool.getFnSignatureView(exp_ty) orelse break :blk_fn null;
                const act_sig = self.pool.getFnSignatureView(act_ty) orelse break :blk_fn null;
                if (exp_sig.paramCount() != act_sig.paramCount()) break :blk_fn null;
                var param_idx: usize = 0;
                while (param_idx < exp_sig.paramCount()) : (param_idx += 1) {
                    if (self.findCrossMajorNominalPairBounded(
                        exp_sig.getParamType(param_idx),
                        act_sig.getParamType(param_idx),
                        depth + 1,
                    )) |p_match| {
                        break :blk_fn p_match;
                    }
                }
                break :blk_fn self.findCrossMajorNominalPairBounded(exp_sig.ret_ty, act_sig.ret_ty, depth + 1);
            },
            else => null,
        };
    }

    /// Emits `E0012` (`e0012_cross_major_cxi_type_mismatch`) for a matched cross-version nominal or trait pair.
    fn emitCrossMajorMismatchDiagnostic(
        self: *TypeChecker,
        span: Span,
        matched: CrossMajorNominalMatch,
        is_trait_bound: bool,
    ) !void {
        const sink = self.diagnostic_sink orelse return;
        const arena_alloc = sink.arena.asAllocator();

        const pkg_name = self.interner.get(matched.canon_name_sym);
        const exp_ver = self.lookupPackageVersionSlice(matched.exp_pkg);
        const act_ver = self.lookupPackageVersionSlice(matched.act_pkg);

        var exp_chain: [16]SymbolId = undefined;
        const chain_len = self.extractIntraPackageSymbolChain(matched.exp_sym_idx, matched.exp_pkg, &exp_chain);
        var path_buf: [128]u8 = undefined;
        const qual_path = self.formatIntraPackageSymbolChain(exp_chain[0..chain_len], &path_buf);

        const message = if (is_trait_bound)
            try std.fmt.allocPrint(
                arena_alloc,
                "unsatisfied trait bound across coexisting versions of `{s}`: implements `{s}` from `{s}@{s}`, but `{s}@{s}` is required",
                .{ pkg_name, qual_path, pkg_name, act_ver, pkg_name, exp_ver },
            )
        else
            try std.fmt.allocPrint(
                arena_alloc,
                "mismatched nominal types across coexisting versions of `{s}`: expected `{s}` from `{s}@{s}`, found `{s}` from `{s}@{s}`",
                .{ pkg_name, qual_path, pkg_name, exp_ver, qual_path, pkg_name, act_ver },
            );

        const primary_lbl = try std.fmt.allocPrint(
            arena_alloc,
            "uses `{s}` from `{s}@{s}` (expected `{s}@{s}`)",
            .{ qual_path, pkg_name, act_ver, pkg_name, exp_ver },
        );

        var labels_buf: [3]diagnostic.LabeledSpan = undefined;
        labels_buf[0] = .{
            .span = span,
            .label = primary_lbl,
            .style = .primary,
        };
        var label_count: usize = 1;

        const exp_decl = self.sym_table.getSymbol(matched.exp_sym_idx).decl_span;
        if (!exp_decl.file_id.isNone()) {
            labels_buf[label_count] = .{
                .span = exp_decl,
                .label = try std.fmt.allocPrint(arena_alloc, "`{s}` in `{s}@{s}` defined here", .{ qual_path, pkg_name, exp_ver }),
                .style = .secondary,
            };
            label_count += 1;
        }
        const act_decl = self.sym_table.getSymbol(matched.act_sym_idx).decl_span;
        if (!act_decl.file_id.isNone()) {
            labels_buf[label_count] = .{
                .span = act_decl,
                .label = try std.fmt.allocPrint(arena_alloc, "`{s}` in `{s}@{s}` defined here", .{ qual_path, pkg_name, act_ver }),
                .style = .secondary,
            };
            label_count += 1;
        }

        const help_note = try std.fmt.allocPrint(
            arena_alloc,
            "help: `{s}@{s}` and `{s}@{s}` have distinct `.cxi` nominal identities; " ++
                "unify dependency versions in `corex.toml` or write an explicit adapter",
            .{ pkg_name, exp_ver, pkg_name, act_ver },
        );
        const notes_slice = try arena_alloc.alloc([]const u8, 1);
        notes_slice[0] = help_note;

        _ = try sink.emit(.{
            .code = .e0012_cross_major_cxi_type_mismatch,
            .severity = .err,
            .primary_span = span,
            .message = message,
            .labels = try arena_alloc.dupe(diagnostic.LabeledSpan, labels_buf[0..label_count]),
            .notes = notes_slice,
        });
    }

    /// Emits `E0012` and returns `true` when `(expected_ty, actual_ty)` fails solely due to coexisting package versions.
    fn tryEmitCrossMajorNominalMismatch(
        self: *TypeChecker,
        span: Span,
        expected_ty: TypeId,
        actual_ty: TypeId,
    ) !bool {
        if (self.sym_table.package_canonical_names.count() == 0 and
            self.sym_table.package_metas.count() == 0)
        {
            return false;
        }
        if (self.findCrossMajorNominalPairBounded(expected_ty, actual_ty, 0)) |matched| {
            try self.emitCrossMajorMismatchDiagnostic(span, matched, false);
            return true;
        }
        return false;
    }

    /// Emits `E0012` and returns `true` when `candidate_ty` implements a trait from a different version of `group_ty`'s package.
    fn tryEmitCrossMajorTraitBoundMismatch(
        self: *TypeChecker,
        span: Span,
        candidate_ty: TypeId,
        group_ty: TypeId,
    ) !bool {
        if (self.sym_table.package_canonical_names.count() == 0 and
            self.sym_table.package_metas.count() == 0)
        {
            return false;
        }
        if (self.pool.getTag(group_ty) != .trait_ty) return false;
        const exp_trait_sym = self.sym_table.type_to_symbol.get(group_ty.toU32()) orelse
            SymbolIndex.fromInt(self.pool.getNode(group_ty).rhs);
        if (exp_trait_sym.isNone()) return false;

        var peeled_cand = candidate_ty;
        while (self.pool.getTag(peeled_cand) == .ref_ty or
            self.pool.getTag(peeled_cand) == .mut_ref_ty or
            self.pool.getTag(peeled_cand) == .refined_ty or
            self.pool.getTag(peeled_cand) == .tilde_approx)
        {
            peeled_cand = TypeId.fromInt(self.pool.getNode(peeled_cand).lhs);
        }

        var key_iter = self.sym_table.trait_impl_pairs.keyIterator();
        while (key_iter.next()) |pair_key_ptr| {
            const pair_key = pair_key_ptr.*;
            const impl_target_raw: u32 = @truncate(pair_key >> 32);
            if (impl_target_raw != candidate_ty.toU32() and impl_target_raw != peeled_cand.toU32()) {
                continue;
            }
            const impl_trait_sym = SymbolIndex.fromInt(@truncate(pair_key));
            if (self.matchCrossMajorNominalSymbols(exp_trait_sym, impl_trait_sym)) |matched| {
                try self.emitCrossMajorMismatchDiagnostic(span, matched, true);
                return true;
            }
        }
        return false;
    }

    /// Emits `E0401` (`type_mismatch`, or `E0012` across coexisting package versions) with formatted type names.
    fn emitTypeMismatch(
        self: *TypeChecker,
        span: Span,
        expected_ty: TypeId,
        actual_ty: TypeId,
    ) !void {
        if (self.diagnostic_sink == null) return;
        if (try self.tryEmitCrossMajorNominalMismatch(span, expected_ty, actual_ty)) return;
        var exp_buf: [96]u8 = undefined;
        var act_buf: [96]u8 = undefined;
        const exp_str = self.pool.formatType(expected_ty, self.sym_table, &exp_buf);
        const act_str = self.pool.formatType(actual_ty, self.sym_table, &act_buf);

        var msg_buf: [220]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "mismatched types: expected `{s}`, found `{s}`",
            .{ exp_str, act_str },
        ) catch "mismatched types";

        var lbl_buf: [160]u8 = undefined;
        const lbl = std.fmt.bufPrint(
            &lbl_buf,
            "expected `{s}`, found `{s}`",
            .{ exp_str, act_str },
        ) catch "type mismatch here";

        try self.emitDiagnosticSimple(.e0401_type_mismatch, span, msg, lbl);
    }

    /// Emits `E0402` (`unsatisfied_trait_bound`, or `E0012` across coexisting package versions) on failed group/trait checks.
    fn emitGroupConstraintError(
        self: *TypeChecker,
        span: Span,
        candidate_ty: TypeId,
        group_ty: TypeId,
        is_distinct_without_tilde: bool,
    ) !void {
        if (self.diagnostic_sink == null) return;
        if (!is_distinct_without_tilde) {
            if (try self.tryEmitCrossMajorTraitBoundMismatch(span, candidate_ty, group_ty)) return;
        }
        var cand_buf: [96]u8 = undefined;
        var grp_buf: [96]u8 = undefined;
        const cand_str = self.pool.formatType(candidate_ty, self.sym_table, &cand_buf);
        const grp_str = self.pool.formatType(group_ty, self.sym_table, &grp_buf);

        var msg_buf: [240]u8 = undefined;
        const msg = if (is_distinct_without_tilde)
            std.fmt.bufPrint(
                &msg_buf,
                "`distinct` type `{s}` does not satisfy Type Group `{s}` without `~` underlying-type approximation",
                .{ cand_str, grp_str },
            ) catch "`distinct` type does not satisfy Type Group without `~`"
        else
            std.fmt.bufPrint(
                &msg_buf,
                "type `{s}` does not satisfy Constrained Type Group `{s}`",
                .{ cand_str, grp_str },
            ) catch "type does not satisfy Constrained Type Group";

        try self.emitDiagnosticSimple(
            .e0402_unsatisfied_trait_bound,
            span,
            msg,
            "unsatisfied Type Group constraint",
        );
    }

    /// Emits `E0404` (`bind_once_type_group_conflict`) when a bare Type Group binds to two different types.
    fn emitBindOnceConflict(
        self: *TypeChecker,
        span: Span,
        group_ty: TypeId,
        first_ty: TypeId,
        second_ty: TypeId,
    ) !void {
        if (self.diagnostic_sink == null) return;
        var grp_buf: [64]u8 = undefined;
        var first_buf: [64]u8 = undefined;
        var second_buf: [64]u8 = undefined;
        const grp_str = self.pool.formatType(group_ty, self.sym_table, &grp_buf);
        const first_str = self.pool.formatType(first_ty, self.sym_table, &first_buf);
        const second_str = self.pool.formatType(second_ty, self.sym_table, &second_buf);

        var msg_buf: [240]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "Bind-Once Type Group `{s}` bound to conflicting types `{s}` and `{s}` (use `any {s}` for independent parameters)",
            .{ grp_str, first_str, second_str, grp_str },
        ) catch "Bind-Once Type Group bound to conflicting concrete types";

        try self.emitDiagnosticSimple(
            .e0404_bind_once_group_conflict,
            span,
            msg,
            "expected same concrete type as previous Bind-Once parameter",
        );
    }

    /// Emits `E0405` (`distinct_type_mismatch`) when mixing a `distinct` newtype with its base type.
    fn emitDistinctMixingError(
        self: *TypeChecker,
        span: Span,
        lhs_ty: TypeId,
        rhs_ty: TypeId,
    ) !void {
        if (self.diagnostic_sink == null) return;
        var lhs_buf: [64]u8 = undefined;
        var rhs_buf: [64]u8 = undefined;
        const lhs_str = self.pool.formatType(lhs_ty, self.sym_table, &lhs_buf);
        const rhs_str = self.pool.formatType(rhs_ty, self.sym_table, &rhs_buf);

        var msg_buf: [220]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "cannot mix `distinct` type `{s}` with `{s}` without an explicit `as` cast",
            .{ lhs_str, rhs_str },
        ) catch "cannot mix `distinct` type with underlying type without explicit `as` cast";

        try self.emitDiagnosticSimple(
            .e0405_distinct_type_mixing,
            span,
            msg,
            "`distinct` newtypes do not implicitly convert to or from their underlying type",
        );
    }

    /// Emits `E0406` (`range_refinement_violation`) when a value violates a `T is low..=high` refinement.
    fn emitRangeRefinementError(
        self: *TypeChecker,
        span: Span,
        refined_ty: TypeId,
        actual_val: i128,
        min_val: i128,
        max_val: i128,
    ) !void {
        if (self.diagnostic_sink == null) return;
        var ty_buf: [64]u8 = undefined;
        const ty_str = self.pool.formatType(refined_ty, self.sym_table, &ty_buf);

        var msg_buf: [220]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "value `{d}` violates refinement type `{s}` (expected `{d}..={d}`)",
            .{ actual_val, ty_str, min_val, max_val },
        ) catch "value violates `is` range refinement bounds";

        try self.emitDiagnosticSimple(
            .e0406_range_refinement_violation,
            span,
            msg,
            "value outside refined range `low..=high`",
        );
    }

    /// Emits `E0413` (`unhandled_must_use_result`) when a `Result[T, E]` or `@must_use` value is discarded.
    fn emitUnhandledMustUseError(self: *TypeChecker, span: Span, expr_ty: TypeId) !void {
        if (self.diagnostic_sink == null) return;
        var ty_buf: [96]u8 = undefined;
        const ty_str = self.pool.formatType(expr_ty, self.sym_table, &ty_buf);

        var msg_buf: [220]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &msg_buf,
            "unhandled `@must_use` or `Result` value of type `{s}`; propagate with `?` or handle with `catch`",
            .{ty_str},
        ) catch "unhandled `@must_use` or `Result` value";

        try self.emitDiagnosticSimple(
            .e0413_unhandled_must_use_or_result,
            span,
            msg,
            "unused `@must_use` / `Result` value must be handled",
        );
    }

    /// Emits a diagnostic code with message and primary label into `self.diagnostic_sink`.
    fn emitDiagnosticSimple(
        self: *TypeChecker,
        code: DiagnosticCode,
        span: Span,
        message: []const u8,
        label: []const u8,
    ) !void {
        const sink = self.diagnostic_sink orelse return;
        const sev: Severity = code.defaultSeverity();
        const labels = [1]LabeledSpan{.{
            .span = span,
            .label = label,
            .style = .primary,
        }};
        try sink.emit(.{
            .code = code,
            .severity = sev,
            .primary_span = span,
            .message = message,
            .labels = &labels,
        });
    }

    /// Emits a diagnostic with a single machine-applicable `SuggestedFix` replacement edit.
    fn emitDiagnosticWithSingleFix(
        self: *TypeChecker,
        code: DiagnosticCode,
        span: Span,
        message: []const u8,
        label: []const u8,
        fix_message: []const u8,
        edit_span: Span,
        replacement_text: []const u8,
    ) !void {
        const sink = self.diagnostic_sink orelse return;
        const sev: Severity = code.defaultSeverity();
        const repl_id = try self.interner.intern(replacement_text);
        const labels = [1]LabeledSpan{.{
            .span = span,
            .label = label,
            .style = .primary,
        }};
        const edits = [1]TextEdit{.{
            .file_id = edit_span.file_id,
            .start_byte = edit_span.start_byte,
            .end_byte = edit_span.end_byte,
            .replacement_id = repl_id,
        }};
        const fixes = [1]SuggestedFix{.{
            .message = fix_message,
            .applicability = .machine_applicable,
            .priority = .syntax_canonicalization,
            .edits = &edits,
        }};
        try sink.emit(.{
            .code = code,
            .severity = sev,
            .primary_span = span,
            .message = message,
            .labels = &labels,
            .suggestions = &fixes,
        });
    }
};

// ------------- Single-File Typecheck Entry Point --------------

/// Bundles the arenas and tables produced by standalone single-file type checking (`typecheckSource`).
pub const TypecheckResult = struct {
    /// Backing allocator.
    allocator: std.mem.Allocator,
    /// String interner.
    interner: StringInterner,
    /// Token buffer.
    token_buffer: TokenBuffer,
    /// Lossless CST arena.
    cst_arena: LosslessCstArena,
    /// Lowered AST arena.
    ast_arena: AstArena,
    /// Canonical `InternPool` (`TypeArena`).
    type_pool: InternPool,
    /// Resolved `SymbolTable` and `ScopeArena`.
    symbol_table: SymbolTable,
    /// Emitted lexical, syntax, name-resolution, and type diagnostics.
    diagnostics: DiagnosticSink,

    /// Releases all owned buffers, arenas, and pools.
    pub fn deinit(self: *TypecheckResult) void {
        self.diagnostics.deinit();
        self.symbol_table.deinit();
        self.type_pool.deinit();
        self.ast_arena.deinit();
        self.cst_arena.deinit();
        self.token_buffer.deinit();
        self.interner.deinit();
        self.* = undefined;
    }
};

/// Tokenizes, parses, resolves names/imports, and type-checks `source` for `file_id`.
pub fn typecheckSource(
    allocator: std.mem.Allocator,
    file_id: FileId,
    source: []const u8,
) !TypecheckResult {
    var interner = try StringInterner.init(allocator);
    errdefer interner.deinit();

    var token_buffer = TokenBuffer.init(allocator);
    errdefer token_buffer.deinit();

    var cst_arena = LosslessCstArena.init(allocator);
    errdefer cst_arena.deinit();

    var ast_arena = AstArena.init(allocator);
    errdefer ast_arena.deinit();

    var diagnostics = DiagnosticSink.init(allocator);
    errdefer diagnostics.deinit();

    _ = try parser.parseSource(
        source,
        file_id,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
        &interner,
    );

    var type_pool = try InternPool.init(allocator);
    errdefer type_pool.deinit();

    var symbol_table = try SymbolTable.init(allocator, &interner);
    errdefer symbol_table.deinit();

    _ = try symbol_resolver.collectFileModuleItems(
        &symbol_table,
        &interner,
        file_id,
        source,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    try symbol_resolver.resolveFileUseImports(
        &symbol_table,
        &interner,
        file_id,
        source,
        &token_buffer,
        &cst_arena,
        &diagnostics,
    );

    var checker = try TypeChecker.init(
        allocator,
        &interner,
        &type_pool,
        &symbol_table,
        file_id,
        source,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    defer checker.deinit();

    try checker.resolveModuleSignatures();
    try checker.checkFileBodies();

    return .{
        .allocator = allocator,
        .interner = interner,
        .token_buffer = token_buffer,
        .cst_arena = cst_arena,
        .ast_arena = ast_arena,
        .type_pool = type_pool,
        .symbol_table = symbol_table,
        .diagnostics = diagnostics,
    };
}

// ---------------------------------------- MAIN -----------------------------------------

test "test_type_node_14_byte_layout_and_intern_pool_static_slots" {
    const soa_bytes = @sizeOf(TypeTag) + @sizeOf(TypeFlags) + @sizeOf(u32) * 3;
    try std.testing.expectEqual(@as(usize, 14), soa_bytes);
    try std.testing.expectEqual(@as(usize, 1), @sizeOf(TypeFlags));

    var pool = try InternPool.init(std.testing.allocator);
    defer pool.deinit();

    try std.testing.expectEqual(@as(usize, 64), pool.countTypes());
    try std.testing.expectEqual(TypeTag.primitive, pool.getTag(.i32_ty));
    try std.testing.expectEqual(TypeTag.builtin_group, pool.getTag(.group_integer));
    try std.testing.expect(TypeGroupMask.containsPrimitive(TypeGroupMask.INTEGER, .i32_ty));
    try std.testing.expect(!TypeGroupMask.containsPrimitive(TypeGroupMask.INTEGER, .f64_ty));
    try std.testing.expect(TypeGroupMask.isSubsetOf(TypeGroupMask.SIGNED, TypeGroupMask.INTEGER));
    try std.testing.expect(TypeGroupMask.isSubsetOf(TypeGroupMask.INTEGER, TypeGroupMask.NUMBER));

    // Structural deduplication:
    const opt_i32_a = try pool.internOptional(.i32_ty);
    const opt_i32_b = try pool.internOptional(.i32_ty);
    try std.testing.expectEqual(opt_i32_a, opt_i32_b);

    const res_a = try pool.internResult(.u64_ty, .i32_ty);
    const res_b = try pool.internResult(.u64_ty, .i32_ty);
    try std.testing.expectEqual(res_a, res_b);
    try std.testing.expect(pool.getFlags(res_a).is_must_use);
}

test "test_bind_once_vs_bind_many_and_distinct_refinement_typing" {
    const source =
        \\type UserId = distinct u64;
        \\type Port = u16 is 1024..=65535;
        \\type IntLike = ~Integer;
        \\
        \\pub fn add_same(first_val: Integer, second_val: Integer) -> Integer {
        \\    return first_val + second_val;
        \\}
        \\
        \\pub fn accept_any(first_val: any Integer, second_val: any Integer) -> i32 {
        \\    let _ = first_val;
        \\    let _ = second_val;
        \\    return 0;
        \\}
        \\
        \\pub fn test_calls() -> i32 {
        \\    let arg_a: i32 = 10;
        \\    let arg_b: i32 = 20;
        \\    let sum_ok: i32 = add_same(arg_a, arg_b);
        \\    let small_val: i8 = 10;
        \\    let big_val: i64 = 20;
        \\    let mix_ok = accept_any(small_val, big_val);
        \\    let valid_port: Port = 8080;
        \\    let widened_u16: u16 = valid_port;
        \\    let _ = widened_u16;
        \\    return sum_ok + mix_ok;
        \\}
    ;
    var res = try typecheckSource(std.testing.allocator, FileId.fromInt(1), source);
    defer res.deinit();

    try std.testing.expectEqual(@as(usize, 0), res.diagnostics.countDiagnostics());
}

/// Returns `true` if `sink` contains at least one diagnostic with `target_code`.
fn hasDiagnosticCode(sink: *const DiagnosticSink, target_code: DiagnosticCode) bool {
    for (sink.diagnostics.items) |diag_item| {
        if (diag_item.code == target_code) return true;
    }
    return false;
}

test "test_phase5_all_reflection_intrinsics_and_compile_assert" {
    const valid_source =
        \\@attribute_schema
        \\pub struct ColumnAttr {
        \\    pub name: str,
        \\}
        \\
        \\@derive(Eq)
        \\pub struct Point {
        \\    @ColumnAttr(name: "coord_x")
        \\    pub x: i32,
        \\    pub y: i32,
        \\}
        \\
        \\pub fn inspect_point() -> usize {
        \\    @compile_assert(@size_of[Point]() == 8, "Point must be 8 bytes");
        \\    @compile_assert(@align_of[Point]() == 4, "Point must be 4-byte aligned");
        \\    @compile_assert(@has_field[Point]("x"), "Point must have field x");
        \\    @compile_assert(@implements[Point, Eq](), "Point must implement Eq");
        \\    comptime if false {
        \\        @compile_error("statically pruned dead branch");
        \\    }
        \\    let zero_pt: Point = @default_init[Point]();
        \\    let x_copy: i32 = @field(zero_pt, "x");
        \\    let ty_label: str = @type_name[Point]();
        \\    let embedded: &[u8] = @embed_bytes("assets/header.bin");
        \\    let info = @type_info[Point]();
        \\    let col_opt: ColumnAttr? = @field_attr_lookup[ColumnAttr](info.id, 0);
        \\    let _ = x_copy;
        \\    let _ = ty_label;
        \\    let _ = embedded;
        \\    let _ = col_opt;
        \\    return @size_of[Point]();
        \\}
    ;
    var ok_res = try typecheckSource(std.testing.allocator, FileId.fromInt(2), valid_source);
    defer ok_res.deinit();
    try std.testing.expectEqual(@as(usize, 0), ok_res.diagnostics.countDiagnostics());

    const fail_assert_source =
        \\pub fn bad_assert() -> i32 {
        \\    @compile_assert(2 + 2 == 5, "math invariant violated");
        \\    return 0;
        \\}
    ;
    var fail_res = try typecheckSource(std.testing.allocator, FileId.fromInt(3), fail_assert_source);
    defer fail_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&fail_res.diagnostics, .e0510_compile_assertion_failed));
}

test "test_phase5_comptime_fn_params_for_and_forbidden_ops_e0503" {
    const valid_source =
        \\pub comptime fn compute_magic(base_val: i32) -> i32 {
        \\    return base_val * 4;
        \\}
        \\
        \\pub fn with_comptime_param(comptime tag_name: str, runtime_val: i32) -> i32 {
        \\    let _ = tag_name;
        \\    let folded: i32 = comptime compute_magic(8);
        \\    comptime for step_idx in 0..3 {
        \\        let _ = step_idx;
        \\    }
        \\    return runtime_val + folded;
        \\}
        \\
        \\pub fn caller() -> i32 {
        \\    return with_comptime_param("alpha", 10);
        \\}
    ;
    var ok_res = try typecheckSource(std.testing.allocator, FileId.fromInt(4), valid_source);
    defer ok_res.deinit();
    try std.testing.expectEqual(@as(usize, 0), ok_res.diagnostics.countDiagnostics());

    // [1] Capturing runtime variable inside `comptime` emits `E0503`:
    const capture_err_src =
        \\pub fn bad_capture(runtime_arg: i32) -> i32 {
        \\    return comptime (runtime_arg + 1);
        \\}
    ;
    var cap_res = try typecheckSource(std.testing.allocator, FileId.fromInt(5), capture_err_src);
    defer cap_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&cap_res.diagnostics, .e0503_forbidden_comptime_operation));

    // [2] Calling `comptime fn` in a runtime expression emits `E0503`:
    const runtime_call_src =
        \\comptime fn only_ct() -> i32 { return 7; }
        \\pub fn bad_runtime_call() -> i32 { return only_ct(); }
    ;
    var rt_res = try typecheckSource(std.testing.allocator, FileId.fromInt(6), runtime_call_src);
    defer rt_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&rt_res.diagnostics, .e0503_forbidden_comptime_operation));

    // [3] Calling `extern fn` inside `comptime` emits `E0503`:
    const extern_ct_src =
        \\extern fn os_clock() -> u64;
        \\const BAD_TICK: u64 = os_clock();
    ;
    var ext_res = try typecheckSource(std.testing.allocator, FileId.fromInt(7), extern_ct_src);
    defer ext_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&ext_res.diagnostics, .e0503_forbidden_comptime_operation));

    // [4] Pointer-to-integer `as` cast inside `comptime` emits `E0503`:
    const ptr_cast_src =
        \\pub fn bad_ptr_cast() -> usize {
        \\    return comptime {
        \\        let local_num: i32 = 1;
        \\        let raw_ptr: *i32 = &local_num as *i32;
        \\        raw_ptr as usize
        \\    };
        \\}
    ;
    var ptr_res = try typecheckSource(std.testing.allocator, FileId.fromInt(8), ptr_cast_src);
    defer ptr_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&ptr_res.diagnostics, .e0503_forbidden_comptime_operation));
}

test "test_phase5_is_pattern_expr_scoping_and_negation" {
    const valid_source =
        \\pub enum Status {
        \\    Ready,
        \\    Pending(i32),
        \\}
        \\
        \\pub fn check_status(status: Status, opt_num: i32?) -> i32 {
        \\    if status is .Ready {
        \\        return 1;
        \\    }
        \\    if opt_num is .Some(bound_val) and bound_val > 0 {
        \\        return bound_val;
        \\    }
        \\    if status is not .Pending(_) {
        \\        return 0;
        \\    }
        \\    return 2;
        \\}
    ;
    var ok_res = try typecheckSource(std.testing.allocator, FileId.fromInt(9), valid_source);
    defer ok_res.deinit();
    try std.testing.expectEqual(@as(usize, 0), ok_res.diagnostics.countDiagnostics());

    // Negated `not (opt is .Some(leaked))` forbids pattern bindings (`E0214`) and does NOT expose `leaked` (`E0403`):
    const leak_source =
        \\pub fn negated_leak(opt_num: i32?) -> i32 {
        \\    if not (opt_num is .Some(leaked_val)) {
        \\        return leaked_val;
        \\    }
        \\    return 0;
        \\}
    ;
    var leak_res = try typecheckSource(std.testing.allocator, FileId.fromInt(10), leak_source);
    defer leak_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&leak_res.diagnostics, .e0214_invalid_condition_binding));
    try std.testing.expect(hasDiagnosticCode(&leak_res.diagnostics, .e0403_unresolved_symbol));
}

test "test_phase5_attribute_schema_and_two_phase_derive" {
    const valid_source =
        \\@attribute_schema(targets: [.Struct, .StructField])
        \\pub struct ArgAttr {
        \\    pub short: char = 'x',
        \\    pub help: str,
        \\}
        \\
        \\@derive(Eq, Hash, Debug, Clone)
        \\@ArgAttr(help: "pair record")
        \\pub struct Pair {
        \\    @arg(short: 'a', help: "first value")
        \\    pub first: i32,
        \\    pub second: i32,
        \\}
        \\
        \\pub fn same_pair[T: Eq](lhs: &T, rhs: &T) -> bool {
        \\    let _ = lhs;
        \\    let _ = rhs;
        \\    return true;
        \\}
        \\
        \\pub fn exercise_derived(item_a: Pair, item_b: Pair) -> u64 {
        \\    let cloned_a: Pair = item_a.clone();
        \\    let is_same: bool = cloned_a.eq(&item_b);
        \\    let is_generic_eq: bool = same_pair(&cloned_a, &item_b);
        \\    let dbg_text: str = cloned_a.debug();
        \\    let _ = is_same;
        \\    let _ = is_generic_eq;
        \\    let _ = dbg_text;
        \\    return cloned_a.hash();
        \\}
    ;
