    defer ok_res.deinit();
    try std.testing.expectEqual(@as(usize, 0), ok_res.diagnostics.countDiagnostics());

    // `@derive(Eq)` on a struct containing a non-`Eq` field must emit `E0402`:
    const bad_derive_src =
        \\pub struct OpaqueHandle {
