    defer borrowed_slice_res.deinit();
    try std.testing.expectEqual(@as(usize, 0), borrowed_slice_res.diagnostics.countDiagnostics());
}

test "test_redteam_3a_attr_escapes_enum_ordinals_string_interp_and_large_arity" {
