}

test "test_phase6_seam2_context_fields_and_safe_narrowing_d11" {
    const src =
        \\pub struct Context {}
        \\pub fn exercise_ctx_and_narrow(ctx: &Context, wide_val: i64) -> u8 {
        \\    let seed: u64 = ctx.rng_seed;
        \\    let sink_ptr: (*mut u8)? = ctx.trace_sink;
