    var pool = try InternPool.init(std.testing.allocator);
    defer pool.deinit();
    var sym_table = try SymbolTable.init(std.testing.allocator, &interner);
    defer sym_table.deinit();
    _ = try symbol_resolver.collectFileModuleItems(
        &sym_table,
        &interner,
        file_id,
        valid_src,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    var checker = try TypeChecker.init(
        std.testing.allocator,
        &interner,
        &pool,
        &sym_table,
        file_id,
        valid_src,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    defer checker.deinit();
    try checker.resolveModuleSignatures();
    try checker.checkFileBodies();
    try std.testing.expectEqual(@as(usize, 0), diagnostics.countDiagnostics());
    try std.testing.expectEqual(@as(u32, 2), checker.string_interps.count());

    var has_debug_eq_hole = false;
    var has_fmt_args_interp = false;
    var interp_it = checker.string_interps.valueIterator();
    while (interp_it.next()) |meta_ptr| {
        if (meta_ptr.is_fmt_args_mode) has_fmt_args_interp = true;
        if (meta_ptr.holes.len > 0 and meta_ptr.holes[0].has_debug_eq) {
            has_debug_eq_hole = true;
            try std.testing.expectEqual(lexer.FmtTypeCode.lower_hex, meta_ptr.holes[0].spec.extractTypeCode());
            try std.testing.expectEqual(@as(?u16, 6), meta_ptr.holes[0].spec.extractWidth());
        }
    }
    try std.testing.expect(has_debug_eq_hole and has_fmt_args_interp);

    // [1] `E0431` invalid `FmtSpec`, `E0432` missing struct field, `E0434` immut destructure, `E0305` aliased swap:
    const errs_src =
        \\pub struct Pair2 { pub a: i32, pub b: i32 }
        \\pub fn bad_cases(flag: bool) -> str {
        \\    let bad_s = Pair2 { a: 1 };
        \\    let immut_x: i32 = 1;
        \\    var mut_y: i32 = 2;
        \\    (immut_x, mut_y) = (3, 4);
        \\    (mut_y, mut_y) = (5, 6);
        \\    let _ = bad_s;
        \\    return "{flag:#x}";
        \\}
    ;
    var errs_res = try typecheckSource(std.testing.allocator, FileId.fromInt(53), errs_src);
    defer errs_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&errs_res.diagnostics, .e0431_invalid_format_specifier));
    try std.testing.expect(hasDiagnosticCode(&errs_res.diagnostics, .e0432_missing_struct_field_initializer));
    try std.testing.expect(hasDiagnosticCode(&errs_res.diagnostics, .e0434_invalid_parallel_assign_target));
    try std.testing.expect(hasDiagnosticCode(&errs_res.diagnostics, .e0305_exclusivity_violation));
}

test "test_phase76_se16_se18_se19_se20_se21_se22_se23_cfg_test_closures_subscript_builder_fsm" {
    const valid_src =
        \\@cfg(os == "windows" or os != "windows")
        \\pub fn active_platform_helper() -> i32 {
        \\    return 7;
        \\}
        \\
        \\@cfg(os == "windows" and os == "linux")
        \\pub fn pruned_helper() -> i32 {
        \\    @compile_error("must be pruned before Pass 1");
        \\    return 0;
        \\}
        \\
        \\pub struct Matrix2 {
        \\    pub cells: [f64; 4],
        \\}
        \\impl Matrix2 {
        \\    pub subscript(row: usize, col: usize) -> f64 {
        \\        let {
        \\            yield self.cells[row * 2 + col];
        \\        }
        \\        inout {
        \\            yield &mut self.cells[row * 2 + col];
        \\        }
        \\    }
        \\}
        \\
        \\pub struct TagChip {
        \\    pub code: i32,
        \\}
        \\impl TagChip {
        \\    @constructor
        \\    pub fn create(code: i32) -> TagChip {
        \\        return TagChip { code: code };
        \\    }
        \\}
        \\
        \\pub struct PanelScope {
        \\    pub count: u32,
        \\}
        \\
        \\@builder_item
        \\pub fn row_item(scope: &mut PanelScope, weight: u32) {
        \\    scope.count = scope.count + weight;
        \\}
        \\
        \\pub fn panel(title: str, body: @builder |&mut PanelScope|) -> u32 {
        \\    var scope = PanelScope { count: 0 };
        \\    body(&mut scope);
        \\    let _ = title;
        \\    return scope.count;
        \\}
        \\
        \\pub enum StepState {
        \\    Init,
        \\    Running(i32),
        \\    Done(i32),
        \\}
        \\
        \\pub fn apply_fn(cb: fn(i32) -> i32, val: i32) -> i32 {
        \\    return cb(val);
        \\}
        \\
        \\pub fn trace_here(loc: SourceLoc = @caller_location()) -> u32 {
        \\    let file_name: str = loc.file;
        \\    let fn_label: str = loc.fn_name;
        \\    let _ = (file_name, fn_label);
        \\    return loc.line + loc.col;
        \\}
        \\
        \\pub fn run_all() -> i32 {
        \\    var mat = Matrix2 { cells: [1.0, 2.0, 3.0, 4.0] };
        \\    mat[0, 1] = 9.5;
        \\    let cell_val: f64 = mat[0, 1];
        \\    let chip = TagChip(12);
        \\    let built_rows: u32 = panel("main") {
        \\        row_item(3);
        \\    };
        \\    let inc_res: i32 = apply_fn(|num: i32| -> i32 { return num + 1; }, chip.code);
        \\    let loc_sum: u32 = trace_here();
        \\    let fsm_out: i32 = fsm: match StepState.Init {
        \\        .Init => continue :fsm .Running(inc_res),
        \\        .Running(cur) => continue :fsm .Done(cur + active_platform_helper()),
        \\        .Done(final_v) => final_v,
        \\    };
        \\    let _ = (cell_val, built_rows, loc_sum);
        \\    return fsm_out;
        \\}
        \\
        \\test "matrix and fsm smoke" {
        \\    let out_v = run_all();
        \\    let _ = out_v;
        \\}
        \\
        \\bench "panel builder bench" (bencher: &mut Bencher) {
        \\    let _ = bencher;
        \\}
    ;
    var interner = try StringInterner.init(std.testing.allocator);
    defer interner.deinit();
    var token_buffer = TokenBuffer.init(std.testing.allocator);
    defer token_buffer.deinit();
    var cst_arena = LosslessCstArena.init(std.testing.allocator);
    defer cst_arena.deinit();
    var ast_arena = AstArena.init(std.testing.allocator);
    defer ast_arena.deinit();
    var diagnostics = DiagnosticSink.init(std.testing.allocator);
    defer diagnostics.deinit();
    const file_id = FileId.fromInt(54);
    _ = try parser.parseSource(valid_src, file_id, &token_buffer, &cst_arena, &ast_arena, &diagnostics, &interner);
    var pool = try InternPool.init(std.testing.allocator);
    defer pool.deinit();
    var sym_table = try SymbolTable.init(std.testing.allocator, &interner);
    defer sym_table.deinit();
    _ = try symbol_resolver.collectFileModuleItems(
        &sym_table,
        &interner,
        file_id,
        valid_src,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    var checker = try TypeChecker.init(
        std.testing.allocator,
        &interner,
        &pool,
        &sym_table,
        file_id,
        valid_src,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    defer checker.deinit();
    try checker.resolveModuleSignatures();
    try checker.checkFileBodies();
    try std.testing.expectEqual(@as(usize, 0), diagnostics.countDiagnostics());
    try std.testing.expectEqual(@as(u32, 1), checker.builder_block_calls.count());
    try std.testing.expectEqual(@as(u32, 1), checker.implicit_builder_item_calls.count());
    try std.testing.expectEqual(@as(u32, 2), checker.labeled_match_continues.count());

    // [1] `E0435` invalid `@cfg`, `E0436` `@builder_item` outside builder scope, `E0437` bad `:fsm` continue:
    const neg_src =
        \\@cfg(42)
        \\pub fn bad_cfg_fn() {}
        \\
        \\pub struct ScopeB { pub items: u32 }
        \\@builder_item
        \\pub fn item_fn(sc: &mut ScopeB, tag: u32) { sc.items = tag; }
        \\
        \\pub enum FsmS { A, B, C }
        \\pub fn bad_builder_and_fsm() -> i32 {
        \\    item_fn(10);
        \\    return fsm: match FsmS.A {
        \\        .A => continue :fsm,
        \\        .B => continue :fsm 999,
        \\        .C => 0,
        \\    };
        \\}
    ;
    var neg_res = try typecheckSource(std.testing.allocator, FileId.fromInt(55), neg_src);
    defer neg_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0435_invalid_cfg_predicate));
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0436_builder_item_outside_scope));
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0437_invalid_labeled_match_continue));
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0401_type_mismatch));
}

test "test_stage4_mvs_mutability_casts_default_init_cmpxchg6_and_dependent_generics" {
    // [1] Valid MVS borrows, 6-arg `@atomic_cmpxchg`, dependent generic defaults, `_f32`/`_f64` int literals,
    //     cooked `@attribute_schema` args, raw/multiline interpolation holes, and `TxnResult` distinct casts:
    const valid_src =
        \\@attribute_schema(targets: [.Function])
        \\pub struct BenchMeta {
        \\    pub label: str,
        \\    pub scale: f32,
        \\}
        \\@linear
        \\pub struct LinearLease {
        \\    pub id: u32,
        \\}
        \\pub type TxnResult = distinct (i32!i32);
        \\pub type NonNegative = i32 is 0..=100;
        \\pub struct DepPair[A, B = A] {
        \\    pub first: A,
        \\    pub second: B,
        \\}
        \\impl[A, B] DepPair[A, B] {
        \\    @constructor
        \\    pub fn make(first: A, second: B) -> DepPair[A, B] {
        \\        return DepPair { first: first, second: second };
        \\    }
        \\}
        \\pub struct CounterBox {
        \\    pub count: u32,
        \\}
        \\impl CounterBox {
        \\    pub fn bump(&mut self) {
        \\        self.count += 1;
        \\    }
        \\}
        \\@BenchMeta(label: r#"fast_path"#, scale: 2_f32)
        \\pub fn check_valid_paths(mut_slice: &mut [i32], exclusive: &mut CounterBox) -> TxnResult {
        \\    (&mut_slice).*[0] = 9;
        \\    exclusive.bump();
        \\    var local_box = CounterBox { count: 4 };
        \\    local_box.bump();
        \\    let tmp_mut_arr: &mut [i32; 2] = &mut [1, 2];
        \\    tmp_mut_arr[0] = 7;
        \\    let flt_a: f32 = 3_f32;
        \\    let flt_b: f64 = -5_f64;
        \\    let dep_val = DepPair[u32] { first: 10, second: 20 };
        \\    let dep_sec: u32 = dep_val.second;
        \\    let opt_lease: LinearLease? = @default_init[LinearLease?]();
        \\    if opt_lease is .Some(lease) {
        \\        let LinearLease { id } = lease;
        \\        let _ = id;
        \\    }
        \\    let zero_ref: NonNegative = @default_init[NonNegative]();
        \\    let raw_zero: *u64 = unsafe { @default_init[*u64]() };
        \\    var atom_slot: u32 = 1;
        \\    let cmpx_res: (u32, bool) = unsafe {
        \\        @atomic_cmpxchg((&raw atom_slot) as *mut u32, 1, 2, 0_u8, 0_u8, true)
        \\    };
        \\    let interp_ok: str = "hole={if true { /* {brace} */ r#""""#.len() } else { 0 }}";
        \\    let raw_ml_ok: str = r"""
        \\        {not_an_interp_hole}
        \\        """;
        \\    @cfg(debug)
        \\    let stepped: i32 = fsm: match 0 {
        \\        0 => continue :fsm 1,
        \\        other => other,
        \\    };
        \\    let _ = (flt_a, flt_b, zero_ref, raw_zero, cmpx_res, interp_ok, raw_ml_ok, stepped);
        \\    return (.Ok((dep_sec as i32) + (local_box.count as i32))) as TxnResult;
        \\}
        \\pub mod trailing_mod {
        \\    pub fn mod_helper() -> i32 {
        \\        return 1;
        \\    }
        \\}
    ;
    var ok_res = try typecheckSource(std.testing.allocator, FileId.fromInt(60), valid_src);
    defer ok_res.deinit();
    try std.testing.expect(!ok_res.diagnostics.hasErrors());

    // [2] MVS mutability & `var` reference parameter bans:
    const mvs_err_src =
        \\pub struct Counter { pub count: i32 }
        \\impl Counter {
        \\    pub fn bump(&mut self) { self.count += 1; }
        \\}
        \\pub fn bad_mvs(shared_ref: &Counter, ro_ptr: *Counter, ro_slice: &[i32], opt_ro: &(i32?), var rebound_ref: &i32) {
        \\    let immut_local: i32 = 1;
        \\    immut_local = 2;
        \\    immut_local += 1;
        \\    shared_ref.count = 99;
        \\    unsafe { ro_ptr.*.count = 77; }
        \\    (&ro_slice).*[0] = 5;
        \\    let _bad_mut_borrow = &mut immut_local;
        \\    shared_ref.bump();
        \\    let immut_counter = Counter { count: 0 };
        \\    immut_counter.bump();
        \\    if opt_ro is .Some(&mut inner_v) {
        \\        inner_v = 3;
        \\    }
        \\    for &mut elem in ro_slice {
        \\        elem = 4;
        \\    }
        \\    let _ = rebound_ref;
        \\}
    ;
    var mvs_res = try typecheckSource(std.testing.allocator, FileId.fromInt(61), mvs_err_src);
    defer mvs_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&mvs_res.diagnostics, .e0305_exclusivity_violation));
    try std.testing.expect(hasDiagnosticCode(&mvs_res.diagnostics, .e0421_non_copy_value_parameter));
    var e0305_count: usize = 0;
    for (mvs_res.diagnostics.asSlice()) |diag| {
        if (diag.code == .e0305_exclusivity_violation) e0305_count += 1;
    }
    try std.testing.expect(e0305_count >= 9);

    // [3] Exhaustive cast whitelist & `@default_init[T]()` soundness:
    const cast_and_init_err_src =
        \\pub type PosPort = u16 is 1..=1024;
        \\@secret
        \\pub type SecretPin = distinct u32;
        \\@linear
        \\pub struct LinearTok { pub fd: i32 }
        \\pub struct RefHolder { pub num: i32 }
        \\pub fn bad_casts_and_inits(raw_u16: u16, pin: SecretPin, shared_num: &i32, mut_ptr: *mut i32) {
        \\    let _bad_ref_cast = raw_u16 as PosPort;
        \\    let _forged_mut = mut_ptr as &mut i32;
        \\    let _forged_ro = (0 as usize) as &i32;
        \\    let _escalated_ptr = shared_num as *mut i32;
        \\    let _leaked_pin = pin as u32;
        \\    let _bad_comp = RefHolder { num: 1 } as (i32, i32);
        \\    let _null_ref = @default_init[&i32]();
        \\    let _null_fn = @default_init[fn() -> i32]();
        \\    let _zero_pos = @default_init[PosPort]();
        \\    let _zero_sec = @default_init[SecretPin]();
        \\    let _zero_lin = @default_init[LinearTok]();
        \\    let LinearTok { fd } = _zero_lin;
        \\    let _ = fd;
        \\}
    ;
    var cast_res = try typecheckSource(std.testing.allocator, FileId.fromInt(62), cast_and_init_err_src);
    defer cast_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&cast_res.diagnostics, .e0406_range_refinement_violation));
    try std.testing.expect(hasDiagnosticCode(&cast_res.diagnostics, .e0405_distinct_type_mixing));
    try std.testing.expect(hasDiagnosticCode(&cast_res.diagnostics, .e0401_type_mismatch));
}

test "test_stage4_generic_default_bounds_parallel_assign_subscript_yield_and_cfg_target" {
    // [1] Invalid generic default bounds, parallel destructuring aliasing & `@linear` discard,
    //     incomplete/double `subscript` `yield`, and cooked `@embed_bytes` escape:
    const err_src =
        \\pub struct BadTypeDefault[T: Integer = str] {
        \\    pub item: T,
        \\}
        \\@linear
        \\pub struct GuardTok {
        \\    pub id: i32,
        \\}
        \\pub struct PairBox {
        \\    pub left: i32,
        \\    pub right: i32,
        \\}
        \\pub struct LinearPair {
        \\    pub count: i32,
        \\    pub tok: GuardTok,
        \\}
        \\pub struct BrokenSub {
        \\    pub data: [i32; 2],
        \\}
        \\impl BrokenSub {
        \\    pub subscript(idx: usize) -> i32 {
        \\        let {
        \\            if idx == 0 {
        \\                yield self.data[0];
        \\            }
        \\        }
        \\        inout {
        \\            yield &mut self.data[0];
        \\            yield &mut self.data[1];
        \\        }
        \\    }
        \\}
        \\pub fn trigger_errors(mut_ref: &mut PairBox, dyn_idx: usize, lin_pair: LinearPair) {
        \\    (mut_ref.left, mut_ref.*.left) = (1, 2);
        \\    var arr: [i32; 2] = [0, 0];
        \\    (arr[dyn_idx], arr[0]) = (3, 4);
        \\    var out_left: i32 = 0;
        \\    PairBox { left: out_left } = PairBox { left: 5, right: 6 };
        \\    LinearPair { count: out_left, .. } = lin_pair;
        \\    let _escaped = @embed_bytes(r#"../outside.bin"#);
        \\    let _ = (arr, out_left);
        \\}
    ;
    var err_res = try typecheckSource(std.testing.allocator, FileId.fromInt(63), err_src);
    defer err_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&err_res.diagnostics, .e0402_unsatisfied_trait_bound));
    try std.testing.expect(hasDiagnosticCode(&err_res.diagnostics, .e0305_exclusivity_violation));
    try std.testing.expect(hasDiagnosticCode(&err_res.diagnostics, .e0432_missing_struct_field_initializer));
    try std.testing.expect(hasDiagnosticCode(&err_res.diagnostics, .e0304_resource_or_memory_leak));
    try std.testing.expect(hasDiagnosticCode(&err_res.diagnostics, .e0401_type_mismatch));
    try std.testing.expect(hasDiagnosticCode(&err_res.diagnostics, .e0503_forbidden_comptime_operation));

    // [2] `CfgEnv.fromTargetSpec` & `cfg.test_mode` decoupling:
    const wasm_env = CfgEnv.fromTargetSpec(codegen_abi.TargetSpec.WASM32_WASI, false);
    try std.testing.expectEqual(CfgArch.wasm32, wasm_env.arch);
    try std.testing.expectEqual(CfgOs.wasi, wasm_env.os);
    try std.testing.expectEqual(@as(u16, 32), wasm_env.ptr_width);
    try std.testing.expect(!wasm_env.is_test_mode);

    const cfg_src =
        \\@cfg(test_mode)
        \\pub fn only_in_test_mode() -> i32 {
        \\    @compile_error("test_mode must remain false when is_test_mode is false");
        \\    return 0;
        \\}
        \\pub fn normal_entry() -> i32 {
        \\    return 42;
        \\}
    ;
    var interner = try StringInterner.init(std.testing.allocator);
    defer interner.deinit();
    var token_buffer = TokenBuffer.init(std.testing.allocator);
    defer token_buffer.deinit();
    var cst_arena = LosslessCstArena.init(std.testing.allocator);
    defer cst_arena.deinit();
    var ast_arena = AstArena.init(std.testing.allocator);
    defer ast_arena.deinit();
    var diagnostics = DiagnosticSink.init(std.testing.allocator);
    defer diagnostics.deinit();
    const file_id = FileId.fromInt(64);
    _ = try parser.parseSource(cfg_src, file_id, &token_buffer, &cst_arena, &ast_arena, &diagnostics, &interner);
    var pool = try InternPool.init(std.testing.allocator);
    defer pool.deinit();
    var sym_table = try SymbolTable.init(std.testing.allocator, &interner);
    defer sym_table.deinit();
    _ = try symbol_resolver.collectFileModuleItems(
        &sym_table,
        &interner,
        file_id,
        cfg_src,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    var checker = try TypeChecker.init(
        std.testing.allocator,
        &interner,
        &pool,
        &sym_table,
        file_id,
        cfg_src,
        &token_buffer,
        &cst_arena,
        &ast_arena,
        &diagnostics,
    );
    defer checker.deinit();
    checker.is_including_tests = true;
    checker.cfg_env.is_test_mode = false;
    try checker.resolveModuleSignatures();
    try checker.checkFileBodies();
    try std.testing.expect(!diagnostics.hasErrors());

    // [3] Twin `@cfg` items in both orders, `@cfg(false) use`, generic `type` alias defaults, and `/` vs. `*` `@overload`:
    const twin_and_alias_src =
        \\@cfg(false)
        \\use nonexistent_os_mod.MissingType;
        \\
        \\@cfg(false)
        \\pub fn choose_first() -> i32 { return 10; }
        \\@cfg(true)
        \\pub fn choose_first() -> i32 { return 20; }
        \\
        \\@cfg(true)
        \\pub fn choose_second() -> i32 { return 30; }
        \\@cfg(false)
        \\pub fn choose_second() -> i32 { return 40; }
        \\
        \\pub type Pair[A, B = A] = (A, B);
        \\
        \\@overload
        \\pub fn dispatch_zone(val: i32, /) -> i32 { return val + 1; }
        \\@overload
        \\pub fn dispatch_zone(*, val: i32) -> i32 { return val + 10; }
        \\
        \\pub fn verify_all() -> i32 {
        \\    let same_pair: Pair[i32] = (4, 5);
        \\    let mixed_pair: Pair[i32, bool] = (6, true);
        \\    let extra: i32 = if mixed_pair.1 { mixed_pair.0 } else { 0 };
        \\    return choose_first() + choose_second() + same_pair.0 + same_pair.1 + extra +
        \\        dispatch_zone(2) + dispatch_zone(val: 3);
        \\}
    ;
    var twin_res = try typecheckSource(std.testing.allocator, FileId.fromInt(65), twin_and_alias_src);
    defer twin_res.deinit();
    try std.testing.expect(!twin_res.diagnostics.hasErrors());

    // [4] Active `@cfg(true)` duplicate emits `E0408`, and undeclared `cfg.feature.<name>` emits `E0435`:
    const dup_and_feat_src =
        \\@cfg(true)
        \\pub fn active_dup() -> i32 { return 1; }
        \\@cfg(true)
        \\pub fn active_dup() -> i32 { return 2; }
        \\@cfg(cfg.feature.undeclared_xyz)
        \\pub fn gated_fn() -> i32 { return 3; }
    ;
    var df_interner = try StringInterner.init(std.testing.allocator);
    defer df_interner.deinit();
    var df_tok = TokenBuffer.init(std.testing.allocator);
    defer df_tok.deinit();
    var df_cst = LosslessCstArena.init(std.testing.allocator);
    defer df_cst.deinit();
    var df_ast = AstArena.init(std.testing.allocator);
    defer df_ast.deinit();
    var df_diags = DiagnosticSink.init(std.testing.allocator);
    defer df_diags.deinit();
    const df_fid = FileId.fromInt(66);
    _ = try parser.parseSource(dup_and_feat_src, df_fid, &df_tok, &df_cst, &df_ast, &df_diags, &df_interner);
    var df_pool = try InternPool.init(std.testing.allocator);
    defer df_pool.deinit();
    var df_sym = try SymbolTable.init(std.testing.allocator, &df_interner);
    defer df_sym.deinit();
    _ = try symbol_resolver.collectFileModuleItems(
        &df_sym,
        &df_interner,
        df_fid,
        dup_and_feat_src,
        &df_tok,
        &df_cst,
        &df_ast,
        &df_diags,
    );
    var df_checker = try TypeChecker.init(
        std.testing.allocator,
        &df_interner,
        &df_pool,
        &df_sym,
        df_fid,
        dup_and_feat_src,
        &df_tok,
        &df_cst,
        &df_ast,
        &df_diags,
    );
    defer df_checker.deinit();
    const declared_feats = [_][]const u8{ "json", "tls" };
    df_checker.cfg_env.declared_features = &declared_feats;
    try df_checker.resolveModuleSignatures();
    try std.testing.expect(hasDiagnosticCode(&df_diags, .e0408_duplicate_definition));
    try std.testing.expect(hasDiagnosticCode(&df_diags, .e0435_invalid_cfg_predicate));

    // [5] `Parser.parseSourceWithOptions(.{ .is_including_tests = false })` skips test/bench bodies with zero AST nodes:
    const skip_tb_src =
        \\pub fn prod_fn() -> i32 { return 7; }
        \\test "heavy test body" {
        \\    let alpha = 1 + 2 + 3 + 4;
        \\    let beta = alpha * 5;
        \\    let _ = beta;
        \\}
    ;
    var tok_inc = TokenBuffer.init(std.testing.allocator);
    defer tok_inc.deinit();
    var cst_inc = LosslessCstArena.init(std.testing.allocator);
    defer cst_inc.deinit();
    var ast_inc = AstArena.init(std.testing.allocator);
    defer ast_inc.deinit();
    _ = try parser.parseSource(
        skip_tb_src,
        FileId.fromInt(67),
        &tok_inc,
        &cst_inc,
        &ast_inc,
        null,
        null,
    );
    var cst_exc = LosslessCstArena.init(std.testing.allocator);
    defer cst_exc.deinit();
    var ast_exc = AstArena.init(std.testing.allocator);
    defer ast_exc.deinit();
    var exc_parser = parser.Parser.initWithOptions(
        skip_tb_src,
        FileId.fromInt(67),
        &tok_inc,
        &cst_exc,
        &ast_exc,
        null,
        null,
        .{ .is_including_tests = false },
    );
    _ = try exc_parser.parse();
    try std.testing.expect(ast_exc.countNodes() < ast_inc.countNodes());
}

test "test_phase8_ffi_contracts_c_import_trusted_extern_non_niche_opt_ptr_and_variadics" {
    const allocator = std.testing.allocator;

    // [1] Valid `@c_import("foo.h")` synthetic module, `@trusted` safe calls/reads, `(extern "C" fn)?` niche,
    //     FFI contract attributes (`@slice_len`, `@byte_len`, `@free_with`, `@owned_by_caller`), & C variadics:
    const header_stub_src =
        \\pub type c_int = i32;
        \\@trusted
        \\pub extern "C" fn c_add(lhs: c_int, rhs: c_int) -> c_int;
    ;
    const valid_ffi_src =
        \\@derive(Copy, Clone)
        \\@repr(C)
        \\pub struct CStr {
        \\    ptr: *u8,
        \\}
        \\@repr(C)
        \\pub enum LogLevel: u8 {
        \\    Info = 1,
        \\    Warn = 2,
        \\}
        \\pub bit_field Flags8: u8 {
        \\    pub is_ready: bool | 1,
        \\    pub mode: u8 | 3,
        \\    pub pad: u8 | 4,
        \\}
        \\@repr(C)
        \\pub struct CallbackTable {
        \\    pub on_tick: (extern "C" fn(i32) -> i32)?,
        \\    pub maybe_id: u32?,
        \\}
        \\
        \\@trusted
        \\extern "C" {
        \\    @owned_by_caller
        \\    @free_with(c_release)
        \\    @may_be_null
        \\    pub fn c_alloc_buf(size: usize) -> *mut u8;
        \\    pub fn c_release(@consumes @may_be_null ptr: *mut u8);
        \\    pub fn c_read_items(@slice_len(count) items: *u32, count: usize) -> i32;
        \\    pub fn c_write_raw(@byte_len(byte_cap) data: *u8, byte_cap: usize) -> i32;
        \\    pub fn c_log_fmt(fmt: *u8, ...) -> i32;
        \\    pub static GLOBAL_VERSION: i32;
        \\}
        \\
        \\const c_hdr = @c_import("foo.h");
        \\
        \\pub fn invoke_safe_ffi(cstr: CStr, raw_fmt: *u8) -> i32 {
        \\    let sum_hdr: i32 = c_hdr.c_add(10, 20);
        \\    let ver: i32 = GLOBAL_VERSION;
        \\    let flag_bf = Flags8 { is_ready: true, mode: 3, pad: 0 };
        \\    let small_i8: i8 = -4;
        \\    let small_u16: u16 = 500;
        \\    let flt32: f32 = 1.5_f32;
        \\    let logged: i32 = c_log_fmt(raw_fmt, true, small_i8, small_u16, LogLevel.Warn, flag_bf, flt32, cstr);
        \\    return sum_hdr + ver + logged;
        \\}
    ;

    var interner = try StringInterner.init(allocator);
    defer interner.deinit();
    var pool = try InternPool.init(allocator);
    defer pool.deinit();
    var sym_table = try SymbolTable.init(allocator, &interner);
    defer sym_table.deinit();
    var diags = DiagnosticSink.init(allocator);
    defer diags.deinit();

    // Parse & typecheck synthetic `"foo.h"` module and register in `sym_table.c_import_modules`:
    var hdr_tok = TokenBuffer.init(allocator);
    defer hdr_tok.deinit();
    var hdr_cst = LosslessCstArena.init(allocator);
    defer hdr_cst.deinit();
    var hdr_ast = AstArena.init(allocator);
    defer hdr_ast.deinit();
    const hdr_fid = FileId.fromInt(70);
    _ = try parser.parseSource(header_stub_src, hdr_fid, &hdr_tok, &hdr_cst, &hdr_ast, &diags, &interner);
    const hdr_scope = try symbol_resolver.collectFileModuleItems(
        &sym_table,
        &interner,
        hdr_fid,
        header_stub_src,
        &hdr_tok,
        &hdr_cst,
        &hdr_ast,
        &diags,
    );
    var hdr_checker = try TypeChecker.init(
        allocator,
        &interner,
        &pool,
        &sym_table,
        hdr_fid,
        header_stub_src,
        &hdr_tok,
        &hdr_cst,
        &hdr_ast,
        &diags,
    );
    defer hdr_checker.deinit();
    try hdr_checker.resolveModuleSignatures();

    const hdr_mod_name = try interner.intern("__c_import_foo_h");
    const hdr_mod_sym = try sym_table.appendSymbol(.{
        .name = hdr_mod_name,
        .name_text = interner.get(hdr_mod_name),
        .kind = .module_sym,
        .namespace = .value_ns,
        .visibility = .public,
        .scope_id = sym_table.prelude_scope,
        .decl_span = .{ .file_id = hdr_fid, .start_byte = 0, .end_byte = 0 },
        .target_scope = hdr_scope,
    });
    try sym_table.registerCImportModule(&interner, "foo.h", hdr_mod_sym);

    var main_tok = TokenBuffer.init(allocator);
    defer main_tok.deinit();
    var main_cst = LosslessCstArena.init(allocator);
    defer main_cst.deinit();
    var main_ast = AstArena.init(allocator);
    defer main_ast.deinit();
    const main_fid = FileId.fromInt(71);
    _ = try parser.parseSource(valid_ffi_src, main_fid, &main_tok, &main_cst, &main_ast, &diags, &interner);
    const main_scope = try symbol_resolver.collectFileModuleItems(
        &sym_table,
        &interner,
        main_fid,
        valid_ffi_src,
        &main_tok,
        &main_cst,
        &main_ast,
        &diags,
    );
    var main_checker = try TypeChecker.init(
        allocator,
        &interner,
        &pool,
        &sym_table,
        main_fid,
        valid_ffi_src,
        &main_tok,
        &main_cst,
        &main_ast,
        &diags,
    );
    defer main_checker.deinit();
    try main_checker.resolveModuleSignatures();
    try main_checker.checkFileBodies();
    try std.testing.expectEqual(@as(usize, 0), diags.countDiagnostics());

    // Verify populated `ffi_contracts` ordinals & `@free_with` target symbol:
    const alloc_sym = sym_table.lookupInScopeDirect(main_scope, try interner.intern("c_alloc_buf"), NamespaceMask.VALUE_ONLY);
    const release_sym = sym_table.lookupInScopeDirect(main_scope, try interner.intern("c_release"), NamespaceMask.VALUE_ONLY);
    const read_sym = sym_table.lookupInScopeDirect(main_scope, try interner.intern("c_read_items"), NamespaceMask.VALUE_ONLY);
    const alloc_fc = sym_table.getFfiContract(alloc_sym).?;
    try std.testing.expect(alloc_fc.is_ret_owned_by_caller);
    try std.testing.expect(alloc_fc.is_ret_may_be_null);
    try std.testing.expectEqual(release_sym, alloc_fc.ret_free_with_sym);
    const read_fc = sym_table.getFfiContract(read_sym).?;
    try std.testing.expect(read_fc.param_contracts[0].has_slice_len);
    try std.testing.expectEqual(@as(u8, 1), read_fc.param_contracts[0].len_param_ordinal);

    // [2] Negative checks: `E0009` missing `@c_import`, `E0324` untrusted `extern` fn / `extern static [mut]` outside `unsafe`,
    //     and `E0401` rejecting `16B` non-niche `*u8?` in `extern "C"` signatures and `@repr(C)` structs:
    const neg_ffi_src =
        \\@repr(C)
        \\pub struct BadReprCStruct {
        \\    pub bad_opt_ptr: *u8?,
        \\}
        \\extern "C" {
        \\    pub fn bad_opt_extern(ptr: *mut i32?) -> *u8?;
        \\    pub fn untrusted_c_fn() -> i32;
        \\    pub static UNTRUSTED_CONST: i32;
        \\    pub static mut GLOBAL_MUT_COUNTER: i32;
        \\}
        \\pub fn bad_caller() -> i32 {
        \\    let missing_c = @c_import("nonexistent_header.h");
        \\    let _ = missing_c;
        \\    let val_a = untrusted_c_fn();
        \\    let val_b = UNTRUSTED_CONST;
        \\    GLOBAL_MUT_COUNTER = 5;
        \\    return val_a + val_b;
        \\}
    ;
    var neg_res = try typecheckSource(allocator, FileId.fromInt(72), neg_ffi_src);
    defer neg_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0009_c_header_translation_failed));
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0324_package_capability_violation));
    try std.testing.expect(hasDiagnosticCode(&neg_res.diagnostics, .e0401_type_mismatch));
}

test "test_phase8_nominal_nursery_escape_c_abi_compound_sync_task_group_and_cross_file_c_import" {
    const allocator = std.testing.allocator;

    // [1] `block_on(task_group(|grp| { let handle = grp.spawn(async { 1 }); handle.join().await }))` inside sync `fn` -> 0 errors:
    const sync_tg_src =
        \\use cx.async.{ block_on, task_group };
        \\pub fn run_sync_nursery() -> i32 {
        \\    return block_on(task_group(|grp| {
        \\        let handle = grp.spawn(async { 42 });
        \\        handle.join().await
        \\    }));
        \\}
    ;
    var sync_tg_res = try typecheckSource(allocator, FileId.fromInt(73), sync_tg_src);
    defer sync_tg_res.deinit();
    try std.testing.expect(!sync_tg_res.diagnostics.hasErrors());

    // [2] Nominal `struct` / `enum` wrapping `TaskHandle[i32]` returned out of `task_group` -> `E0309`:
    const escaped_handle_src =
        \\use cx.async.{ TaskHandle, task_group };
        \\pub struct EscapedHandle {
        \\    pub handle: TaskHandle[i32],
        \\}
        \\pub async fn bad_escape() -> EscapedHandle {
        \\    return task_group(|grp| {
        \\        let handle = grp.spawn(async { 7 });
        \\        EscapedHandle { handle: own handle }
        \\    }).await;
        \\}
    ;
    var escaped_res = try typecheckSource(allocator, FileId.fromInt(74), escaped_handle_src);
    defer escaped_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&escaped_res.diagnostics, .e0309_concurrent_exclusivity_or_escape));

    // [3] Compound `[*u8?; 4]`, `*mut (*u8?)`, and `(*u8?, i32)` in `extern "C"` / `@repr(C)` -> `E0401`:
    const compound_c_abi_src =
        \\@repr(C)
        \\pub struct BadArrayReprC {
        \\    pub slots: [*u8?; 4],
        \\}
        \\extern "C" {
        \\    pub fn bad_nested_ptr(ptr_a: *mut (*u8?));
        \\    pub fn bad_tuple_ptr(pair: (*u8?, i32));
        \\}
    ;
    var c_abi_res = try typecheckSource(allocator, FileId.fromInt(75), compound_c_abi_src);
    defer c_abi_res.deinit();
    var e0401_count: usize = 0;
    for (c_abi_res.diagnostics.diagnostics.items) |diag_item| {
        if (diag_item.code == .e0401_type_mismatch) e0401_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 3), e0401_count);

    // [4] Cross-file `@not_send`/`@not_sync` & `@c_import(IMPORTED_CONST)` via `CompilerDb`:
    var db = try query_db.CompilerDb.init(allocator);
    defer db.deinit();
    var vfs_headers: std.StringHashMapUnmanaged([]const u8) = .empty;
    defer vfs_headers.deinit(allocator);
    try vfs_headers.put(allocator, "mini_ext.h", "int ext_magic(void);\n");
    db.setEmbedSandbox(null, &vfs_headers);

    const defs_fid = FileId.fromInt(76);
    const caller_fid = FileId.fromInt(77);
    const defs_src =
        \\pub const EXT_HDR_PATH: str = "mini_ext.h";
        \\@not_send
        \\pub struct ForeignToken {
        \\    pub code: i32,
        \\}
        \\@not_sync
        \\pub struct ForeignUnsync {
        \\    pub val: i32,
        \\}
    ;
    const caller_src =
        \\use defs.{ EXT_HDR_PATH, ForeignToken, ForeignUnsync };
        \\use cx.async.task_group;
        \\const c_ext = @c_import(EXT_HDR_PATH);
        \\pub fn use_imported_c() -> i32 {
        \\    return unsafe { c_ext.ext_magic() };
        \\}
        \\pub async fn bad_cross_mod_send(tok: ForeignToken, unsync_val: ForeignUnsync) -> i32 {
        \\    return task_group(|grp| {
        \\        let h1 = grp.spawn(own || { tok.code });
        \\        let h2 = grp.spawn(async { unsync_val.val });
        \\        h1.join().await + h2.join().await
        \\    }).await;
        \\}
    ;
    try db.registerRootModule("defs", defs_fid);
    _ = try db.setInput(defs_fid, defs_src, .low);
    _ = try db.setInput(caller_fid, caller_src, .low);

    _ = try db.resolveSignatures(defs_fid);
    _ = try db.resolveSignatures(caller_fid);
    const caller_tree = try db.extractItemTree(caller_fid);
    var use_c_def: DefId = .NONE;
    var bad_send_def: DefId = .NONE;
    for (caller_tree.entries) |entry| {
        if (std.mem.eql(u8, entry.name_text, "use_imported_c")) use_c_def = entry.def_id;
        if (std.mem.eql(u8, entry.name_text, "bad_cross_mod_send")) bad_send_def = entry.def_id;
    }
    try std.testing.expect(!use_c_def.isNone());
    try std.testing.expect(!bad_send_def.isNone());

    const use_c_body = try db.typecheckBody(use_c_def);
    try std.testing.expectEqual(@as(u32, 0), use_c_body.error_count);

    const bad_send_body = try db.typecheckBody(bad_send_def);
    try std.testing.expect(bad_send_body.error_count >= 2);
}

test "test_binary_tuple_dag_64_layout_niche_offset_and_ownership_memoization" {
    const allocator = std.testing.allocator;
    var interner = try StringInterner.init(allocator);
    defer interner.deinit();
    var pool = try InternPool.init(allocator);
    defer pool.deinit();
    var sym_table = try SymbolTable.init(allocator, &interner);
    defer sym_table.deinit();

    // [1] Construct a 64-level shared binary tuple DAG `t_0 = i32`, `t_k = (t_{k-1}, t_{k-1})`:
    var dag_ty: TypeId = .i32_ty;
    var dag_30_ty: TypeId = .i32_ty;
    var i: usize = 1;
    while (i <= 64) : (i += 1) {
        dag_ty = try pool.internTuple(&.{ dag_ty, dag_ty });
        if (i == 30) dag_30_ty = dag_ty;
    }

    const layout_30 = computeTypeLayoutWithPool(&pool, &sym_table, dag_30_ty, TargetLayout.NATIVE_64);
    try std.testing.expect(layout_30.is_sized);
    try std.testing.expectEqual(@as(u64, 4) << 30, layout_30.byte_size);
    try std.testing.expectEqual(@as(u32, 4), layout_30.align_bytes);
    try std.testing.expectEqual(
        @as(?u64, @as(u64, 4) << 29),
        computeTupleElemOffset(&pool, &sym_table, dag_30_ty, 1, TargetLayout.NATIVE_64),
    );

    const layout_64 = computeTypeLayoutWithPool(&pool, &sym_table, dag_ty, TargetLayout.NATIVE_64);
    try std.testing.expect(layout_64.is_sized);
    try std.testing.expectEqual(@as(u32, 4), layout_64.align_bytes);
    try std.testing.expectEqual(@as(u8, 2), layout_64.align_log2);
    try std.testing.expectEqual(
        NicheKind.none,
        computeLeafNiche(&pool, &sym_table, dag_ty, TargetLayout.NATIVE_64).kind,
    );
    try std.testing.expectEqual(
        @as(?u64, 0),
        computeTupleElemOffset(&pool, &sym_table, dag_ty, 0, TargetLayout.NATIVE_64),
    );
    try std.testing.expect(computeTupleElemOffset(&pool, &sym_table, dag_ty, 1, TargetLayout.NATIVE_64) != null);
    try std.testing.expectEqual(OwnershipTier.copy_tier, classifyOwnershipTier(&pool, &sym_table, dag_ty));
    try std.testing.expect(!hasLinearObligation(&pool, &sym_table, dag_ty));
    try std.testing.expect(explainNonSendOrSyncTypeWithPool(&pool, &sym_table, dag_ty, true, 0) == null);

    // [2] Verify 64-level niche-carrying `bool` and `@linear` `Bencher` binary tuple DAGs in $O(D)$:
    var bool_dag_ty: TypeId = .bool_ty;
    var linear_dag_ty: TypeId = .bencher_ty;
    i = 1;
    while (i <= 64) : (i += 1) {
        bool_dag_ty = try pool.internTuple(&.{ bool_dag_ty, bool_dag_ty });
        linear_dag_ty = try pool.internTuple(&.{ linear_dag_ty, linear_dag_ty });
    }
    const bool_niche = computeLeafNiche(&pool, &sym_table, bool_dag_ty, TargetLayout.NATIVE_64);
    try std.testing.expectEqual(NicheKind.high_scalar_range, bool_niche.kind);
    try std.testing.expectEqual(@as(u32, 0), bool_niche.byte_offset);
    try std.testing.expectEqual(@as(u64, 2), bool_niche.invalid_first);
    try std.testing.expectEqual(@as(u64, 254), bool_niche.invalid_count);
    try std.testing.expectEqual(OwnershipTier.linear_tier, classifyOwnershipTier(&pool, &sym_table, linear_dag_ty));
    try std.testing.expect(hasLinearObligation(&pool, &sym_table, linear_dag_ty));
}

test "test_phase8_linear_future_producer_tier_and_nominal_spoofing_guards" {
    const allocator = std.testing.allocator;

    // [1] Unpolled `Future[T]` from `@linear`-consuming `async fn` inherits `.linear_tier`,
    //     user `Cell`/`Rc` without `@not_send`/`@not_sync` are `Send`/`Sync`, and user `AtomicSpoof`/`CStr`
    //     cannot spoof `core` raw-pointer `Send` or variadic `@repr(C)` exemptions:
    const spoof_and_linear_src =
        \\use cx.async.task_group;
        \\@linear
        \\pub struct LinearPermit {
        \\    pub code: i32,
        \\}
        \\pub fn consume_permit(permit: own LinearPermit) -> i32 {
        \\    let LinearPermit { code } = permit;
        \\    return code;
        \\}
        \\pub async fn async_take_permit(permit: own LinearPermit) -> i32 {
        \\    return consume_permit(own permit);
        \\}
        \\pub struct Cell {
        \\    pub val: i32,
        \\}
        \\pub struct Rc {
        \\    pub val: i32,
        \\}
        \\pub struct AtomicSpoof {
        \\    pub raw: *mut i32,
        \\}
        \\@derive(Copy, Clone)
        \\pub struct CStr {
        \\    pub ptr: *u8,
        \\}
        \\@trusted
        \\extern "C" {
        \\    pub fn c_var_sink(fmt: *u8, ...) -> i32;
        \\}
        \\pub async fn allow_user_cell_and_rc(cell_val: Cell, rc_val: Rc) -> i32 {
        \\    return task_group(|grp| {
        \\        let h1 = grp.spawn(async { cell_val.val });
        \\        let h2 = grp.spawn(own || { rc_val.val });
        \\        h1.join().await + h2.join().await
        \\    }).await;
        \\}
        \\pub async fn reject_atomic_spoof_and_variadic_cstr(spoof: AtomicSpoof, fake_cstr: CStr, fmt_ptr: *u8) -> i32 {
        \\    let _ = c_var_sink(fmt_ptr, fake_cstr);
        \\    return task_group(|grp| {
        \\        let handle = grp.spawn(own || {
        \\            let _ = spoof;
        \\            0
        \\        });
        \\        handle.join().await
        \\    }).await;
        \\}
    ;
    var check_res = try typecheckSource(allocator, FileId.fromInt(78), spoof_and_linear_src);
    defer check_res.deinit();
    try std.testing.expect(hasDiagnosticCode(&check_res.diagnostics, .e0309_concurrent_exclusivity_or_escape));
    try std.testing.expect(hasDiagnosticCode(&check_res.diagnostics, .e0401_type_mismatch));

    const mod_scope = check_res.symbol_table.file_module_scopes.get(78).?;
    const take_sym = check_res.symbol_table.lookupInScopeDirect(
        mod_scope,
        try check_res.interner.intern("async_take_permit"),
        NamespaceMask.VALUE_ONLY,
    );
    try std.testing.expect(!take_sym.isNone());
    const fut_with_linear = try check_res.type_pool.internFuture(.i32_ty, take_sym.asInt());
    try std.testing.expectEqual(
        OwnershipTier.linear_tier,
        classifyOwnershipTier(&check_res.type_pool, &check_res.symbol_table, fut_with_linear),
    );
    try std.testing.expect(hasLinearObligation(&check_res.type_pool, &check_res.symbol_table, fut_with_linear));
}
